CREATE OR REPLACE FUNCTION public.phase05_allergy_screen(p_person_medication_id uuid)
 RETURNS TABLE(allergy_id uuid, finding_status text, reason text, coding_system text, coding_code text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE p_person uuid; p_med uuid; mapped int; allergy_count int;
BEGIN
 SELECT pm.person_id,pm.medication_id INTO p_person,p_med FROM public.person_medications pm WHERE pm.id=p_person_medication_id AND pm.deleted_at IS NULL;
 IF NOT FOUND THEN RETURN QUERY SELECT NULL::uuid,'REVIEW_REQUIRED'::text,'Medication unavailable'::text,NULL::text,NULL::text; RETURN; END IF;
 SELECT count(*) INTO mapped FROM public.medication_ingredient_identifiers i WHERE i.medication_id=p_med AND i.verification_status='VERIFIED';
 SELECT count(*) INTO allergy_count FROM public.allergies a WHERE a.person_id=p_person AND a.deleted_at IS NULL AND a.clinical_status <> 'inactive' AND a.verified_status <> 'refuted';
 IF mapped=0 THEN RETURN QUERY SELECT NULL::uuid,'REVIEW_REQUIRED'::text,'No verified ingredient identifiers for medication'::text,NULL::text,NULL::text; RETURN; END IF;
 IF allergy_count=0 THEN RETURN QUERY SELECT NULL::uuid,'NOT_ASSESSED'::text,'No active allergy records found; this does not prove no allergies'::text,NULL::text,NULL::text; RETURN; END IF;
 RETURN QUERY SELECT a.id,'POTENTIAL_MATCH'::text,'Matching verified substance identifier; clinical review required'::text,mi.coding_system,mi.coding_code
 FROM public.allergies a
 JOIN public.allergy_substance_identifiers ai ON ai.allergy_id=a.id AND ai.verification_status='VERIFIED'
 JOIN public.medication_ingredient_identifiers mi ON mi.coding_system=ai.coding_system AND mi.coding_code=ai.coding_code AND mi.medication_id=p_med AND mi.verification_status='VERIFIED'
 WHERE a.person_id=p_person AND a.deleted_at IS NULL AND a.clinical_status <> 'inactive' AND a.verified_status <> 'refuted';
 IF NOT FOUND THEN RETURN QUERY SELECT NULL::uuid,'REVIEW_REQUIRED'::text,'No matching code found; cross-reactivity and incomplete codings remain unassessed'::text,NULL::text,NULL::text; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.phase05_assess_conditional_safety(p_rule_id uuid, p_measurement_id uuid)
 RETURNS TABLE(status text, reason text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE r record; m record; o record; val numeric; matched boolean;
BEGIN
 SELECT * INTO r FROM public.medication_conditional_rules WHERE id=p_rule_id AND deleted_at IS NULL AND active;
 IF NOT FOUND THEN RETURN QUERY SELECT 'HOLD_FOR_REVIEW'::text,'Rule unavailable'::text; RETURN; END IF;
 IF r.verification_status <> 'VERIFIED' OR r.order_version_id IS NULL THEN RETURN QUERY SELECT 'HOLD_FOR_REVIEW'::text,'Rule not verified'::text; RETURN; END IF;
 SELECT * INTO o FROM public.medication_order_versions WHERE id=r.order_version_id AND person_medication_id=r.person_medication_id AND verified_at IS NOT NULL AND verified_by IS NOT NULL AND lower(status) IN ('verified','active','approved') AND effective_from <= now() AND (effective_to IS NULL OR effective_to > now());
 IF NOT FOUND THEN RETURN QUERY SELECT 'HOLD_FOR_REVIEW'::text,'Verified order unavailable or expired'::text; RETURN; END IF;
 SELECT m0.* INTO m FROM public.health_measurements m0 JOIN public.person_medications pm ON pm.person_id=m0.person_id WHERE pm.id=r.person_medication_id AND m0.id=p_measurement_id AND m0.deleted_at IS NULL;
 IF NOT FOUND THEN RETURN QUERY SELECT 'HOLD_FOR_REVIEW'::text,'Measurement missing or different patient'::text; RETURN; END IF;
 IF m.measured_at > now() OR (r.observation_max_age_minutes IS NOT NULL AND m.measured_at < now() - make_interval(mins=>r.observation_max_age_minutes)) THEN RETURN QUERY SELECT 'HOLD_FOR_REVIEW'::text,'Measurement outside validated time window'::text; RETURN; END IF;
 IF r.threshold_unit IS NULL OR m.unit IS DISTINCT FROM r.threshold_unit THEN RETURN QUERY SELECT 'HOLD_FOR_REVIEW'::text,'Measurement unit unverified'::text; RETURN; END IF;
 IF r.parameter IN ('systolic','blood_pressure_systolic') AND m.measurement_type IN ('blood_pressure','blood_pressure_systolic','blood_pressure_reading') THEN val:=m.systolic;
 ELSIF r.parameter IN ('diastolic','blood_pressure_diastolic') AND m.measurement_type IN ('blood_pressure','blood_pressure_diastolic','blood_pressure_reading') THEN val:=m.diastolic;
 ELSIF r.parameter=m.measurement_type THEN val:=m.value_numeric;
 ELSE RETURN QUERY SELECT 'HOLD_FOR_REVIEW'::text,'Measurement parameter mismatch'::text; RETURN; END IF;
 IF val IS NULL OR r.operator IS NULL THEN RETURN QUERY SELECT 'HOLD_FOR_REVIEW'::text,'Incomplete measurement or rule'::text; RETURN; END IF;
 IF r.operator IN ('<','lt') AND r.threshold_low IS NOT NULL THEN matched := val < r.threshold_low;
 ELSIF r.operator IN ('<=','lte') AND r.threshold_low IS NOT NULL THEN matched := val <= r.threshold_low;
 ELSIF r.operator IN ('>','gt') AND r.threshold_high IS NOT NULL THEN matched := val > r.threshold_high;
 ELSIF r.operator IN ('>=','gte') AND r.threshold_high IS NOT NULL THEN matched := val >= r.threshold_high;
 ELSIF r.operator IN ('=','eq') AND r.threshold_low IS NOT NULL AND (r.threshold_high IS NULL OR r.threshold_low=r.threshold_high) THEN matched := val = r.threshold_low;
 ELSIF r.operator IN ('between','range') AND r.threshold_low IS NOT NULL AND r.threshold_high IS NOT NULL AND r.threshold_low<=r.threshold_high THEN matched := val BETWEEN r.threshold_low AND r.threshold_high;
 ELSE RETURN QUERY SELECT 'HOLD_FOR_REVIEW'::text,'Unsupported or ambiguous threshold/operator'::text; RETURN; END IF;
 RETURN QUERY SELECT 'PENDING_CLINICAL_REVIEW'::text, CASE WHEN matched THEN 'Condition matched; clinical review still required' ELSE 'Condition not matched; clinical review still required' END::text;
END $function$

CREATE OR REPLACE FUNCTION public.phase05_audit_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_actor uuid;
BEGIN
 IF TG_OP='DELETE' THEN v_id=OLD.id;
 ELSE v_id=NEW.id; END IF;
 v_actor=NULLIF(current_setting('request.jwt.claim.sub',true),'')::uuid;
 INSERT INTO public.medication_phase05_audit_events(entity_table,entity_id,operation,old_record,new_record,actor_id)
 VALUES(TG_TABLE_NAME,v_id,TG_OP,CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END,CASE WHEN TG_OP='DELETE' THEN NULL ELSE to_jsonb(NEW) END,v_actor);
 RETURN COALESCE(NEW,OLD);
END $function$

CREATE OR REPLACE FUNCTION public.phase05_conditional_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
 IF NEW.order_version_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.medication_order_versions v WHERE v.id=NEW.order_version_id AND v.person_medication_id=NEW.person_medication_id) THEN RAISE EXCEPTION 'order version/medication mismatch'; END IF;
 IF NEW.verification_status='VERIFIED' AND NOT EXISTS(SELECT 1 FROM public.medication_order_versions v WHERE v.id=NEW.order_version_id AND v.verified_at IS NOT NULL AND v.verified_by IS NOT NULL AND lower(v.status) IN ('verified','active','approved')) THEN RAISE EXCEPTION 'order version not clinically verified'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.phase05_guard_person_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE actual_person uuid;
BEGIN
 IF TG_TABLE_NAME='allergy_reaction_events' THEN
  SELECT person_id INTO actual_person FROM public.allergies WHERE id=NEW.allergy_id;
  IF actual_person IS DISTINCT FROM NEW.person_id THEN RAISE EXCEPTION 'allergy/person mismatch'; END IF;
 ELSIF TG_TABLE_NAME IN ('medication_dose_decisions','medication_prn_assessments','medication_safety_reviews') THEN
  IF NEW.person_medication_id IS NOT NULL THEN
   SELECT person_id INTO actual_person FROM public.person_medications WHERE id=NEW.person_medication_id;
   IF actual_person IS DISTINCT FROM NEW.person_id THEN RAISE EXCEPTION 'medication/person mismatch'; END IF;
  END IF;
 END IF;
 IF TG_TABLE_NAME='medication_dose_decisions' THEN
  IF NOT EXISTS (SELECT 1 FROM public.medication_conditional_rules r WHERE r.id=NEW.conditional_rule_id AND r.person_medication_id=NEW.person_medication_id) THEN RAISE EXCEPTION 'conditional rule/medication mismatch'; END IF;
  IF NEW.measurement_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.health_measurements m WHERE m.id=NEW.measurement_id AND m.person_id=NEW.person_id AND m.deleted_at IS NULL) THEN RAISE EXCEPTION 'measurement/person mismatch'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.phase05_review_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE relmed uuid; relperson uuid;
BEGIN
 IF TG_TABLE_NAME='medication_dose_decisions' THEN
  SELECT person_medication_id INTO relmed FROM public.medication_conditional_rules WHERE id=NEW.conditional_rule_id;
  IF relmed IS DISTINCT FROM NEW.person_medication_id THEN RAISE EXCEPTION 'dose decision rule mismatch'; END IF;
  IF NEW.order_version_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.medication_order_versions v WHERE v.id=NEW.order_version_id AND v.person_medication_id=NEW.person_medication_id) THEN RAISE EXCEPTION 'dose decision order mismatch'; END IF;
  IF NEW.status IN ('CONDITION_MATCHED','CONDITION_NOT_MATCHED') AND NOT EXISTS(SELECT 1 FROM public.medication_conditional_rules r JOIN public.medication_order_versions v ON v.id=r.order_version_id WHERE r.id=NEW.conditional_rule_id AND r.verification_status='VERIFIED' AND r.order_version_id=NEW.order_version_id AND v.verified_at IS NOT NULL AND v.verified_by IS NOT NULL) THEN RAISE EXCEPTION 'verified rule and order required'; END IF;
  IF NEW.actual_administration_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.medication_administration_events ae WHERE ae.id=NEW.actual_administration_id AND ae.person_id=NEW.person_id AND ae.person_medication_id=NEW.person_medication_id) THEN RAISE EXCEPTION 'administration mismatch'; END IF;
  IF NEW.scheduled_dose_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.medication_scheduled_doses sd WHERE sd.id=NEW.scheduled_dose_id AND sd.person_id=NEW.person_id AND sd.person_medication_id=NEW.person_medication_id) THEN RAISE EXCEPTION 'scheduled dose mismatch'; END IF;
 ELSIF TG_TABLE_NAME='medication_prn_assessments' THEN
  IF NEW.order_version_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.medication_order_versions v WHERE v.id=NEW.order_version_id AND v.person_medication_id=NEW.person_medication_id) THEN RAISE EXCEPTION 'PRN order mismatch'; END IF;
  IF NEW.administration_event_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.medication_administration_events ae WHERE ae.id=NEW.administration_event_id AND ae.person_id=NEW.person_id AND ae.person_medication_id=NEW.person_medication_id) THEN RAISE EXCEPTION 'PRN administration mismatch'; END IF;
 ELSIF TG_TABLE_NAME='medication_safety_reviews' THEN
  IF NEW.allergy_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.allergies a WHERE a.id=NEW.allergy_id AND a.person_id=NEW.person_id) THEN RAISE EXCEPTION 'safety allergy mismatch'; END IF;
  IF NEW.order_version_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.medication_order_versions ov JOIN public.person_medications pm ON pm.id=ov.person_medication_id WHERE ov.id=NEW.order_version_id AND pm.person_id=NEW.person_id AND (NEW.person_medication_id IS NULL OR pm.id=NEW.person_medication_id)) THEN RAISE EXCEPTION 'safety order mismatch'; END IF;
 ELSIF TG_TABLE_NAME='allergy_reaction_events' THEN
  IF NEW.exposure_medication_id IS NOT NULL AND NEW.verification_status='confirmed' AND NEW.verified_by IS NULL THEN RAISE EXCEPTION 'confirmed reaction needs reviewer'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.phase06_expense_link_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE medperson uuid; expenseperson uuid; expense_currency char(3); itemamount numeric; allocated numeric;
BEGIN
 SELECT pm.person_id INTO medperson FROM public.medication_dispenses d JOIN public.person_medications pm ON pm.id=d.person_medication_id WHERE d.id=NEW.dispense_id;
 SELECT he.person_id,he.currency,hei.amount INTO expenseperson,expense_currency,itemamount
 FROM public.healthcare_expense_items hei JOIN public.healthcare_expenses he ON he.id=hei.expense_id WHERE hei.id=NEW.expense_item_id AND hei.deleted_at IS NULL AND he.deleted_at IS NULL;
 IF medperson IS NULL OR expenseperson IS NULL OR medperson<>expenseperson THEN RAISE EXCEPTION 'dispense and expense must belong to same patient'; END IF;
 IF NEW.allocated_amount IS NOT NULL THEN
 SELECT coalesce(sum(allocated_amount),0) INTO allocated FROM public.medication_expense_links WHERE expense_item_id=NEW.expense_item_id AND id IS DISTINCT FROM NEW.id;
 IF itemamount IS NOT NULL AND allocated+NEW.allocated_amount > itemamount THEN RAISE EXCEPTION 'expense item allocation exceeds billed amount'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.phase06_immutable_snapshot_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF OLD.person_id IS DISTINCT FROM NEW.person_id OR OLD.generated_at IS DISTINCT FROM NEW.generated_at OR OLD.payload IS DISTINCT FROM NEW.payload OR OLD.source_record_ids IS DISTINCT FROM NEW.source_record_ids THEN
 RAISE EXCEPTION 'Emergency snapshot contents are immutable';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.phms_accept_line_person_invite_direct(p_line_user_id text, p_invitation_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_line public.line_identities%rowtype;
 v_inv public.person_claim_invitations%rowtype;
 v_hash text;
 v_person public.persons%rowtype;
 v_existing public.persons%rowtype;
 v_fp uuid;
begin
 select * into v_line
 from public.line_identities li
 where li.line_user_id=p_line_user_id and li.is_active=true and li.user_id is not null
 order by li.updated_at desc nulls last limit 1;
 if not found then raise exception 'line_identity_not_linked'; end if;

 v_hash:=encode(digest(btrim(coalesce(p_invitation_token,'')),'sha256'),'hex');
 select * into v_inv
 from public.person_claim_invitations pci
 where pci.invitation_token_hash=v_hash and pci.status='pending'
 for update;
 if not found then raise exception 'person_invite_invalid_or_used'; end if;
 if v_inv.expires_at<=now() then
   update public.person_claim_invitations set status='expired',expired_at=coalesce(expired_at,now()),updated_at=now() where id=v_inv.id;
   raise exception 'person_invite_expired';
 end if;

 if not exists(
   select 1 from public.family_memberships fm
   where fm.family_id=v_inv.family_id and fm.user_id=v_line.user_id and fm.status='active'
 ) then raise exception 'family_membership_required'; end if;

 select * into v_person from public.persons p where p.id=v_inv.person_id for update;
 if not found or coalesce(v_person.status,'active')<>'active' then raise exception 'person_not_available'; end if;
 if v_person.linked_user_id is not null and v_person.linked_user_id<>v_line.user_id then raise exception 'person_already_linked'; end if;

 select p.* into v_existing
 from public.persons p
 where p.linked_user_id=v_line.user_id and p.id<>v_inv.person_id
 order by p.created_at limit 1;

 if found then
   if exists(select 1 from public.family_persons fp where fp.person_id=v_existing.id and coalesce(fp.status,'active')='active')
      or exists(select 1 from public.person_medications pm where pm.person_id=v_existing.id and pm.deleted_at is null)
      or exists(select 1 from public.appointments a where a.person_id=v_existing.id and a.deleted_at is null)
      or exists(select 1 from public.health_measurements h where h.person_id=v_existing.id and h.deleted_at is null)
   then
     raise exception 'current_user_already_has_person_with_data';
   end if;
   update public.persons
   set linked_user_id=null,status='inactive',updated_at=now()
   where id=v_existing.id;
 end if;

 update public.persons
 set linked_user_id=v_line.user_id,updated_at=now()
 where id=v_inv.person_id;

 select fp.id into v_fp
 from public.family_persons fp
 where fp.family_id=v_inv.family_id and fp.person_id=v_inv.person_id and coalesce(fp.status,'active')='active'
 limit 1;

 update public.person_claim_invitations
 set status='accepted',
     accepted_by_user_id=v_line.user_id,
     accepted_by_line_identity_id=v_line.id,
     accepted_at=now(),
     updated_at=now()
 where id=v_inv.id;

 update public.person_claim_requests
 set status='approved',approved_by_user_id=v_inv.invited_by_user_id,approved_at=now(),updated_at=now()
 where person_id=v_inv.person_id
   and requested_user_id=v_line.user_id
   and status in ('pending','person_confirmed');

 if v_fp is not null then
   insert into public.person_self_access(
     family_person_id,family_id,can_view_profile,can_update_profile,
     can_view_medications,can_create_medications,can_update_medications,
     can_view_appointments,can_create_appointments,can_update_appointments,
     can_view_health,can_create_health,can_update_health,configured_by)
   values(
     v_fp,v_inv.family_id,true,true,true,true,true,true,true,true,true,true,true,v_inv.invited_by_user_id)
   on conflict(family_person_id) do nothing;
 end if;

 insert into public.audit_logs(
   family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,record_id,new_data,description,created_at)
 values(
   v_inv.family_id,v_line.user_id,v_line.user_id,v_fp,'person_invite_direct_linked','persons',v_inv.person_id,
   jsonb_build_object('invitation_id',v_inv.id,'line_identity_id',v_line.id),
   'Accepted owner-issued Person invitation and linked current LINE account directly to existing Person',now());

 return jsonb_build_object(
   'status','linked',
   'person_id',v_inv.person_id,
   'family_id',v_inv.family_id,
   'family_person_id',v_fp
 );
end $function$

CREATE OR REPLACE FUNCTION public.phms_accept_person_claim_invitation(p_invitation_token text, p_line_identity_id uuid)
 RETURNS TABLE(claim_request_id uuid, invitation_id uuid, person_id uuid, family_id uuid, status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_hash text;
  v_inv public.person_claim_invitations%rowtype;
  v_claim_id uuid;
  v_existing uuid;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  if coalesce(length(trim(p_invitation_token)),0)=0 then raise exception 'invitation_token_required'; end if;
  v_hash := encode(digest(p_invitation_token,'sha256'),'hex');

  select pci.* into v_inv
    from public.person_claim_invitations pci
   where pci.invitation_token_hash=v_hash
   for update;
  if not found then raise exception 'invalid_invitation'; end if;
  if v_inv.status <> 'pending' then raise exception 'invitation_not_pending'; end if;
  if v_inv.expires_at <= now() then
    update public.person_claim_invitations pci
       set status='expired',expired_at=coalesce(pci.expired_at,now()),updated_at=now()
     where pci.id=v_inv.id;
    raise exception 'invitation_expired';
  end if;

  if exists(select 1 from public.persons p where p.id=v_inv.person_id and p.linked_user_id is not null) then
    raise exception 'person_already_linked';
  end if;
  if exists(select 1 from public.persons p where p.linked_user_id=v_uid) then
    raise exception 'user_already_has_person';
  end if;
  if not exists(
    select 1 from public.line_identities li
     where li.id=p_line_identity_id and li.user_id=v_uid and li.is_active=true
  ) then raise exception 'active_line_identity_required'; end if;

  select pcr.id into v_existing
    from public.person_claim_requests pcr
   where pcr.requested_user_id=v_uid
     and pcr.person_id=v_inv.person_id
     and pcr.status in ('pending','person_confirmed','approved')
   order by pcr.created_at desc
   limit 1;

  if v_existing is not null then
    v_claim_id := v_existing;
  else
    insert into public.person_claim_requests(
      person_id,requested_user_id,family_id,initiated_by_user_id,status,requires_approval,
      requested_from_line_identity_id,expires_at,metadata
    ) values(
      v_inv.person_id,v_uid,v_inv.family_id,v_inv.invited_by_user_id,'pending',true,
      p_line_identity_id,least(v_inv.expires_at,now()+interval '72 hours'),
      jsonb_build_object('invitation_id',v_inv.id,'source','family_invitation')
    ) returning id into v_claim_id;
  end if;

  update public.person_claim_invitations pci
     set status='accepted',accepted_by_user_id=v_uid,accepted_by_line_identity_id=p_line_identity_id,
         accepted_at=now(),updated_at=now()
   where pci.id=v_inv.id;

  insert into public.audit_logs(
    family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,record_id,new_data,description
  )
  select v_inv.family_id,v_uid,v_uid,fp.id,'person_claim_invitation_accepted','person_claim_invitation',v_inv.id,
         jsonb_build_object('person_id',v_inv.person_id,'claim_request_id',v_claim_id,'line_identity_id',p_line_identity_id),
         'Accepted person claim invitation and started claim request'
    from public.family_persons fp
   where fp.family_id=v_inv.family_id and fp.person_id=v_inv.person_id
   limit 1;

  return query select v_claim_id,v_inv.id,v_inv.person_id,v_inv.family_id,'pending'::text;
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_apply_line_family_invite_intent(p_line_user_id text, p_invite_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_line record; v_intent public.family_invite_intents%rowtype; v_hash text;
 v_resources text[]:=array['medications','appointments','health_data']; v_resource text;
 v_view boolean:=false;v_create boolean:=false;v_update boolean:=false;v_delete boolean:=false;v_notify boolean:=false;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 v_hash:=encode(digest(btrim(coalesce(p_invite_token,'')),'sha256'),'hex');

 select * into v_intent
 from public.family_invite_intents
 where token_hash=v_hash and status='pending'
 for update;

 if not found then return jsonb_build_object('applied',false,'reason','no_invite_intent'); end if;

 if not exists(
   select 1 from public.family_invite_links l
   where l.token_hash=v_hash and l.family_id=v_intent.family_id
     and l.status='active' and l.expires_at>now()
 ) then
   update public.family_invite_intents set status='expired',updated_at=now() where id=v_intent.id;
   raise exception 'invite_intent_invalid_or_expired';
 end if;

 if not exists(
   select 1 from public.family_memberships fm
   where fm.family_id=v_intent.family_id and fm.user_id=v_line.user_id and fm.status='active'
 ) then raise exception 'invite_intent_membership_required'; end if;

 perform set_config('phms.suppress_access_notifications','on',true);

 if v_intent.intent_type='admin' then
   if not private.user_has_family_role(v_intent.created_by,v_intent.family_id,array['owner']) then
     raise exception 'admin_invite_owner_required';
   end if;

   insert into public.family_role_assignments(family_id,user_id,role,status,granted_by,granted_at)
   values(v_intent.family_id,v_line.user_id,'admin','active',v_intent.created_by,now())
   on conflict do nothing;

 elsif v_intent.intent_type='caregiver' then
   if v_intent.permission_preset='viewer' then
     insert into public.family_role_assignments(family_id,user_id,role,status,granted_by,granted_at)
     values(v_intent.family_id,v_line.user_id,'viewer','active',v_intent.created_by,now())
     on conflict do nothing;
     v_view:=true; v_create:=false; v_update:=false; v_delete:=false; v_notify:=false;
   else
     insert into public.family_role_assignments(family_id,user_id,role,status,granted_by,granted_at)
     values(v_intent.family_id,v_line.user_id,'caregiver','active',v_intent.created_by,now())
     on conflict do nothing;
     if v_intent.permission_preset='caregiver_standard' then
       v_view:=true;v_create:=true;v_update:=true;v_delete:=true;v_notify:=true;
     end if;
   end if;

   if v_intent.permission_preset='caregiver_standard' and v_intent.family_person_id is not null then
     insert into public.person_caregiver_assignments(
       family_id,family_person_id,caregiver_user_id,is_primary,
       can_edit_profile,can_manage_medications,can_manage_appointments,can_manage_health,
       can_receive_notifications,assigned_by,status,assigned_at,created_at,updated_at
     ) values(
       v_intent.family_id,v_intent.family_person_id,v_line.user_id,false,
       true,true,true,true,true,v_intent.created_by,'active',now(),now(),now()
     )
     on conflict(family_person_id,caregiver_user_id) do update
     set status='active',can_edit_profile=true,can_manage_medications=true,
         can_manage_appointments=true,can_manage_health=true,can_receive_notifications=true,
         assigned_by=v_intent.created_by,updated_at=now();
   end if;

   if v_intent.permission_preset<>'role_only' and v_intent.family_person_id is not null then
     foreach v_resource in array v_resources loop
       insert into public.person_permissions(
         family_id,family_person_id,user_id,resource,
         can_view,can_create,can_update,can_delete,can_receive_notifications,
         granted_by,status,created_at,updated_at
       )
       values(
         v_intent.family_id,v_intent.family_person_id,v_line.user_id,v_resource,
         v_view,v_create,v_update,v_delete,v_notify,
         v_intent.created_by,'active',now(),now()
       )
       on conflict(family_id,family_person_id,user_id,resource) do update
       set can_view=excluded.can_view,can_create=excluded.can_create,
           can_update=excluded.can_update,can_delete=excluded.can_delete,
           can_receive_notifications=excluded.can_receive_notifications,
           granted_by=excluded.granted_by,status='active',updated_at=now();
     end loop;
   end if;
 end if;

 perform set_config('phms.suppress_access_notifications','off',true);

 update public.family_invite_intents
 set status='applied',accepted_by_user_id=v_line.user_id,applied_at=now(),updated_at=now()
 where id=v_intent.id;

 insert into public.audit_logs(
   family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,new_data,description
 )
 values(
   v_intent.family_id,v_intent.created_by,v_line.user_id,v_intent.family_person_id,
   'family_invite_intent_applied','permissions',
   jsonb_build_object('intent_type',v_intent.intent_type,'permission_preset',v_intent.permission_preset),
   'Applied family invite intent after join'
 );

 return jsonb_build_object(
   'applied',true,'intent_type',v_intent.intent_type,
   'permission_preset',v_intent.permission_preset,
   'family_person_id',v_intent.family_person_id
 );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_assign_line_intake_current_person(p_line_user_id text, p_source_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line public.line_identities%rowtype;
  v_source public.data_intake_sources%rowtype;
  v_session public.data_intake_sessions%rowtype;
  v_ctx record;
  v_code text := lower(btrim(coalesce(p_source_code,'')));
  v_match_count integer;
  v_asset_ref_count integer;
begin
  if length(v_code)<8 then raise exception 'source_code_too_short'; end if;

  select * into v_line from public.line_identities
  where line_user_id=p_line_user_id and coalesce(is_active,false)=true
  limit 1;
  if not found or v_line.user_id is null then raise exception 'line_identity_not_linked'; end if;

  select count(*) into v_match_count
  from public.data_intake_sources s
  where s.submitted_by=v_line.user_id
    and lower(s.id::text) like v_code||'%';
  if v_match_count=0 then raise exception 'intake_source_not_found'; end if;
  if v_match_count>1 then raise exception 'intake_source_code_ambiguous'; end if;

  select * into v_source
  from public.data_intake_sources s
  where s.submitted_by=v_line.user_id
    and lower(s.id::text) like v_code||'%'
  limit 1;

  select * into v_session
  from public.data_intake_sessions
  where id=v_source.session_id
  for update;
  if v_session.status in ('confirmed','committed','cancelled','rejected') then
    raise exception 'intake_session_already_final';
  end if;

  select * into v_ctx
  from public.phms_resolve_line_command_context(
    p_line_user_id,'health','view',true,'any'
  )
  limit 1;
  if not found or coalesce(v_ctx.context_ready,false) is not true
     or coalesce(v_ctx.permission_granted,false) is not true
     or v_ctx.target_person_id is null then
    raise exception 'current_person_not_accessible';
  end if;

  update public.data_intake_sessions
  set person_id=v_ctx.target_person_id,
      family_id=v_ctx.active_family_id,
      family_person_id=v_ctx.active_family_person_id,
      context_snapshot=
        coalesce(context_snapshot,'{}'::jsonb)
        || jsonb_build_object(
             'person_label',v_ctx.target_person_name,
             'person_pending',false,
             'person_resolution','current_context_confirmed',
             'person_resolved_at',now()
           ),
      status=case
        when coalesce(v_source.source_metadata->>'extraction_status','')='completed' then 'review'
        else status
      end,
      updated_at=now()
  where id=v_session.id;

  -- A temporary asset may follow a corrected Person only when it belongs to this intake alone.
  if v_source.storage_asset_id is not null then
    select count(*) into v_asset_ref_count
    from public.data_intake_sources s
    where s.storage_asset_id=v_source.storage_asset_id;

    if v_asset_ref_count=1 then
      update public.phms_storage_assets
      set person_id=v_ctx.target_person_id,
          metadata=coalesce(metadata,'{}'::jsonb)
            || jsonb_build_object(
                 'person_reassigned_at',now(),
                 'person_reassigned_from_intake_source_id',v_source.id
               ),
          updated_at=now()
      where id=v_source.storage_asset_id
        and lifecycle_state='temporary';
    end if;
  end if;

  update public.data_intake_candidates
  set person_id=v_ctx.target_person_id,
      validation_data=
        jsonb_build_object(
          'blocking_errors','[]'::jsonb,
          'warnings',
            case when normalized_data='{}'::jsonb
              then jsonb_build_array('normalized_data_empty')
              else '[]'::jsonb end,
          'validated_at',now()
        ),
      review_status='needs_review',
      updated_at=now()
  where source_id=v_source.id
    and review_status not in ('accepted','committed','rejected');

  insert into public.data_intake_actions(
    session_id,actor_user_id,action,after_data
  )
  values(
    v_session.id,v_line.user_id,'reconcile',
    jsonb_build_object(
      'source_id',v_source.id,
      'person_id',v_ctx.target_person_id,
      'person_name',v_ctx.target_person_name,
      'resolution','current_context_confirmed'
    )
  );

  return public.phms_get_line_intake_review_source(p_line_user_id,v_source.id);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_audit_row_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_person uuid; v_record uuid; begin
 v_record:=coalesce((case when tg_op='DELETE' then old.id else new.id end),gen_random_uuid());
 begin v_person:=case when tg_op='DELETE' then old.person_id else new.person_id end; exception when undefined_column then v_person:=null; end;
 insert into public.audit_logs(actor_user_id,family_person_id,event_type,resource,record_id,old_data,new_data,description) values(auth.uid(),null,lower(tg_op),tg_table_name,v_record,case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) end,case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) end,concat('12J-0 ',tg_op,' on ',tg_table_name));
 return case when tg_op='DELETE' then old else new end;
end $function$

CREATE OR REPLACE FUNCTION public.phms_auto_progress_line_context(p_line_user_id text)
 RETURNS TABLE(line_identity_id uuid, user_id uuid, action text, family_count integer, person_count integer, active_family_id uuid, active_family_person_id uuid, family_name text, person_display_name text, context_ready boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare v_line public.line_identities%rowtype; v_family record; v_person record; v_family_count int:=0; v_person_count int:=0;
begin
 select * into v_line from public.line_identities li where li.line_user_id=p_line_user_id and li.is_active=true order by li.updated_at desc nulls last,li.created_at desc limit 1;
 if not found then raise exception 'line_identity_not_found'; end if; if v_line.user_id is null then raise exception 'line_identity_not_linked'; end if;
 perform private.ensure_line_identity_context(v_line.id,v_line.user_id);
 select count(*)::int into v_family_count from public.family_memberships fm join public.families f on f.id=fm.family_id where fm.user_id=v_line.user_id and fm.status='active' and coalesce(f.status,'active')='active';
 if v_family_count=0 then return query select v_line.id,v_line.user_id,'no_family',0,0,null::uuid,null::uuid,null::text,null::text,false; return; end if;
 if v_family_count>1 then return query select v_line.id,v_line.user_id,'family_selection_required',v_family_count,0,null::uuid,null::uuid,null::text,null::text,false; return; end if;
 select f.id family_id,f.family_name into v_family from public.family_memberships fm join public.families f on f.id=fm.family_id where fm.user_id=v_line.user_id and fm.status='active' and coalesce(f.status,'active')='active' limit 1;
 update private.line_identity_contexts c set active_scope='family',active_family_id=v_family.family_id,active_family_person_id=null,context_changed_at=now(),updated_at=now() where c.line_identity_id=v_line.id;
 select count(*)::int into v_person_count from public.family_persons fp join public.persons p on p.id=fp.person_id
 where fp.family_id=v_family.family_id and coalesce(fp.status,'active')='active' and coalesce(p.status,'active')='active'
 and private.user_can_see_family_person(v_line.user_id,fp.id);
 if v_person_count=0 then return query select v_line.id,v_line.user_id,'no_person',1,0,v_family.family_id,null::uuid,v_family.family_name,null::text,true; return; end if;
 if v_person_count>1 then return query select v_line.id,v_line.user_id,'family_auto_selected',1,v_person_count,v_family.family_id,null::uuid,v_family.family_name,null::text,false; return; end if;
 select fp.id family_person_id,private.family_person_label_for_viewer(v_line.user_id,fp.id) person_display_name into v_person
 from public.family_persons fp join public.persons p on p.id=fp.person_id
 where fp.family_id=v_family.family_id and coalesce(fp.status,'active')='active' and coalesce(p.status,'active')='active'
 and private.user_can_see_family_person(v_line.user_id,fp.id) limit 1;
 update private.line_identity_contexts c set active_family_person_id=v_person.family_person_id,context_changed_at=now(),updated_at=now() where c.line_identity_id=v_line.id;
 return query select v_line.id,v_line.user_id,'family_and_person_auto_selected',1,1,v_family.family_id,v_person.family_person_id,v_family.family_name,v_person.person_display_name,true;
end $function$

CREATE OR REPLACE FUNCTION public.phms_auto_progress_line_person_context(p_line_user_id text)
 RETURNS TABLE(line_identity_id uuid, user_id uuid, action text, person_count integer, active_family_id uuid, active_family_person_id uuid, family_name text, person_display_name text, context_ready boolean)
