 if not found then raise exception 'family_context_not_accessible'; end if;
 select count(*)::int into v_count from public.family_persons fp join public.persons p on p.id=fp.person_id
 where fp.family_id=v_ctx.active_family_id and coalesce(fp.status,'active')='active' and coalesce(p.status,'active')='active'
 and private.user_can_see_family_person(v_line.user_id,fp.id);
 if v_count=0 then update private.line_identity_contexts c set active_family_person_id=null,updated_at=now() where c.line_identity_id=v_line.id;
   return query select v_line.id,v_line.user_id,'no_person',0,v_ctx.active_family_id,null::uuid,v_family.family_name,null::text,true; return; end if;
 if v_count>1 then update private.line_identity_contexts c set active_family_person_id=null,updated_at=now() where c.line_identity_id=v_line.id;
   return query select v_line.id,v_line.user_id,'person_selection_required',v_count,v_ctx.active_family_id,null::uuid,v_family.family_name,null::text,false; return; end if;
 select fp.id family_person_id,private.family_person_label_for_viewer(v_line.user_id,fp.id) person_display_name into v_person
 from public.family_persons fp join public.persons p on p.id=fp.person_id
 where fp.family_id=v_ctx.active_family_id and coalesce(fp.status,'active')='active' and coalesce(p.status,'active')='active'
 and private.user_can_see_family_person(v_line.user_id,fp.id) limit 1;
 update private.line_identity_contexts c set active_family_person_id=v_person.family_person_id,context_changed_at=now(),updated_at=now() where c.line_identity_id=v_line.id;
