CREATE OR REPLACE FUNCTION public.phms_cancel_person_claim_from_line(p_line_user_id text, p_claim_request_id uuid)
 RETURNS TABLE(claim_request_id uuid, status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line public.line_identities%rowtype;
  v_claim public.person_claim_requests%rowtype;
begin
  if p_line_user_id is null or btrim(p_line_user_id) = '' then
    raise exception 'line_user_id_required';
  end if;

  select * into v_line
  from public.line_identities
  where line_user_id=p_line_user_id
  for update;

  if not found then raise exception 'line_identity_not_found'; end if;
  if coalesce(v_line.is_active,false) is not true then raise exception 'active_line_identity_required'; end if;
  if v_line.user_id is null then raise exception 'line_identity_not_linked'; end if;

  select * into v_claim
  from public.person_claim_requests
  where id=p_claim_request_id
  for update;

  if not found then raise exception 'claim_not_found'; end if;
  if v_claim.requested_user_id is distinct from v_line.user_id then raise exception 'claim_not_owned_by_line_user'; end if;

  if v_claim.status = 'cancelled' then
    return query select v_claim.id, 'cancelled'::text;
    return;
  end if;

  if v_claim.status not in ('pending','person_confirmed') then
    raise exception 'claim_cannot_be_cancelled';
  end if;

  update public.person_claim_requests
  set status='cancelled', cancelled_at=now(), updated_at=now()
  where id=v_claim.id;

  insert into public.audit_logs(
    family_id,actor_user_id,target_user_id,event_type,resource,record_id,new_data,description
  ) values (
    v_claim.family_id,v_line.user_id,v_line.user_id,
    'person_claim_cancelled','person_claim',v_claim.id,
    jsonb_build_object('claim_request_id',v_claim.id,'status','cancelled','source','line_webhook'),
    'Claimant cancelled the person claim from LINE.'
  );

  return query select v_claim.id, 'cancelled'::text;
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_commit_confirmed_document(p_line_user_id text, p_source_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line public.line_identities%rowtype;
  v_source public.data_intake_sources%rowtype;
  v_ds public.data_intake_sessions%rowtype;
  v_code text:=lower(btrim(coalesce(p_source_code,'')));
  v_count integer;
  v_gate jsonb;
begin
  if length(v_code)<8 then raise exception 'source_code_too_short'; end if;

  select * into v_line
  from public.line_identities
  where line_user_id=p_line_user_id
    and coalesce(is_active,false)=true
  limit 1;
  if not found or v_line.user_id is null then
    raise exception 'line_identity_not_linked';
  end if;

  select count(*) into v_count
  from public.data_intake_sources s
  where s.submitted_by=v_line.user_id
    and lower(s.id::text) like v_code||'%';
  if v_count=0 then raise exception 'intake_source_not_found'; end if;
  if v_count>1 then raise exception 'intake_source_code_ambiguous'; end if;

  select * into v_source
  from public.data_intake_sources s
  where s.submitted_by=v_line.user_id
    and lower(s.id::text) like v_code||'%'
  limit 1;

  select * into v_ds
  from public.data_intake_sessions
  where id=v_source.session_id;

  if not found then raise exception 'intake_session_not_found'; end if;

  v_gate:=private.phms_real_data_gate_decision(
    v_ds.family_id,v_ds.person_id,array['document']::text[],
    'commit',v_line.user_id,1
  );

  if coalesce((v_gate->>'allowed')::boolean,false) is not true then
    raise exception '%',coalesce(v_gate->>'reason','real_data_gate_locked');
  end if;

  return private.phms_commit_confirmed_document_core(
    p_line_user_id,p_source_code
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_commit_confirmed_intake(p_line_user_id text, p_source_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line public.line_identities%rowtype;
  v_source public.data_intake_sources%rowtype;
  v_ds public.data_intake_sessions%rowtype;
  v_batch public.data_intake_commit_batches%rowtype;
  v_code text:=lower(btrim(coalesce(p_source_code,'')));
  v_match_count integer;
  v_guard jsonb;
  v_candidate record;
  v_item jsonb;
  v_results jsonb:='[]'::jsonb;
  v_medications integer:=0;
  v_appointments integer:=0;
  v_measurements integer:=0;
  v_temp_assets integer:=0;
  v_error text;
  v_error_state text;
begin
  if length(v_code)<8 then raise exception 'source_code_too_short'; end if;

  select * into v_line
  from public.line_identities
  where line_user_id=p_line_user_id
    and coalesce(is_active,false)=true
  limit 1;

  if not found or v_line.user_id is null then
    raise exception 'line_identity_not_linked';
  end if;

  select count(*) into v_match_count
  from public.data_intake_sources s
  where s.submitted_by=v_line.user_id
    and lower(s.id::text) like v_code||'%';

  if v_match_count=0 then raise exception 'intake_source_not_found'; end if;
  if v_match_count>1 then raise exception 'intake_source_code_ambiguous'; end if;

  select * into v_source
  from public.data_intake_sources s
  where s.submitted_by=v_line.user_id
    and lower(s.id::text) like v_code||'%'
  limit 1;

  select * into v_ds
  from public.data_intake_sessions
  where id=v_source.session_id
  for update;

  if not found then raise exception 'intake_session_not_found'; end if;
  if v_ds.submitted_by is distinct from v_line.user_id then
    raise exception 'intake_session_not_owned';
  end if;

  select * into v_batch
  from public.data_intake_commit_batches
  where session_id=v_ds.id
  for update;

  if found and v_batch.status='committed' then
    return coalesce(v_batch.result,'{}'::jsonb)
      || jsonb_build_object(
           'ok',true,
           'idempotent_replay',true,
           'batch_id',v_batch.id,
           'session_id',v_ds.id
         );
  end if;

  v_guard:=public.phms_intake_session_can_commit(v_ds.id,v_line.user_id);

  if coalesce((v_guard->>'allowed')::boolean,false) is not true then
    insert into public.data_intake_commit_batches(
      session_id,requested_by,status,guard_result,result
    )
    values(
      v_ds.id,v_line.user_id,'blocked',v_guard,
      jsonb_build_object(
        'ok',false,
        'canonical_commit',false,
        'reason',v_guard->>'reason'
      )
    )
    on conflict (session_id) do update set
      requested_by=excluded.requested_by,
      status='blocked',
      guard_result=excluded.guard_result,
      result=excluded.result,
      committed_at=null
    returning * into v_batch;

    return jsonb_build_object(
      'ok',false,
      'committed',false,
      'idempotent_replay',false,
      'batch_id',v_batch.id,
      'session_id',v_ds.id,
      'guard',v_guard,
      'canonical_commit',false
    );
  end if;

  -- Refresh duplicate/conflict reconciliation immediately before commit.
  for v_candidate in
    select c.id
    from public.data_intake_candidates c
    where c.session_id=v_ds.id
      and c.review_status='accepted'
    order by c.ordinal,c.id
  loop
    perform private.phms_reconcile_intake_candidate_core(v_candidate.id);
  end loop;

  v_guard:=public.phms_intake_session_can_commit(v_ds.id,v_line.user_id);

  if coalesce((v_guard->>'allowed')::boolean,false) is not true then
    insert into public.data_intake_commit_batches(
      session_id,requested_by,status,guard_result,result
    )
    values(
      v_ds.id,v_line.user_id,'blocked',v_guard,
      jsonb_build_object(
        'ok',false,
        'canonical_commit',false,
        'reason',v_guard->>'reason'
      )
    )
    on conflict (session_id) do update set
      requested_by=excluded.requested_by,
      status='blocked',
      guard_result=excluded.guard_result,
      result=excluded.result,
      committed_at=null
    returning * into v_batch;

    return jsonb_build_object(
      'ok',false,
      'committed',false,
      'idempotent_replay',false,
      'batch_id',v_batch.id,
      'session_id',v_ds.id,
      'guard',v_guard,
      'canonical_commit',false
    );
  end if;

  insert into public.data_intake_commit_batches(
    session_id,requested_by,status,guard_result,result
  )
  values(
    v_ds.id,v_line.user_id,'committing',v_guard,'{}'::jsonb
  )
  on conflict (session_id) do update set
    requested_by=excluded.requested_by,
    status='committing',
    guard_result=excluded.guard_result,
    result='{}'::jsonb,
    committed_at=null
  returning * into v_batch;

  begin
    for v_candidate in
      select c.*
      from public.data_intake_candidates c
      where c.session_id=v_ds.id
        and c.review_status='accepted'
      order by
        case c.candidate_type
          when 'medication' then 1
          when 'appointment' then 2
          when 'health_measurement' then 3
          when 'measurement' then 3
          else 99
        end,
        c.ordinal,c.id
      for update
    loop
      case
        when v_candidate.candidate_type='medication' then
          v_item:=private.phms_commit_medication_candidate(v_candidate.id,v_line.user_id);
          v_medications:=v_medications+1;

        when v_candidate.candidate_type='appointment' then
          v_item:=private.phms_commit_appointment_candidate(v_candidate.id,v_line.user_id);
          v_appointments:=v_appointments+1;

        when v_candidate.candidate_type in ('health_measurement','measurement') then
          v_item:=private.phms_commit_health_measurement_candidate(v_candidate.id,v_line.user_id);
          v_measurements:=v_measurements+1;

        else
          raise exception 'unsupported_candidate_type:%',v_candidate.candidate_type;
      end case;

      v_results:=v_results||jsonb_build_array(
        v_item||jsonb_build_object('candidate_id',v_candidate.id)
      );

      update public.data_intake_candidates
      set review_status='committed',
          reconciliation_data=coalesce(reconciliation_data,'{}'::jsonb)
            || jsonb_build_object(
                 'canonical_commit',true,
                 'commit_batch_id',v_batch.id,
                 'canonical_result',v_item,
                 'committed_at',now()
               ),
          updated_at=now()
      where id=v_candidate.id;

      insert into public.data_intake_actions(
        session_id,candidate_id,actor_user_id,action,after_data,reason
      )
      values(
        v_ds.id,v_candidate.id,v_line.user_id,'commit',
        jsonb_build_object(
          'commit_batch_id',v_batch.id,
          'canonical_result',v_item,
          'canonical_commit',true
        ),
        '12J_canonical_commit'
      );
    end loop;

    update public.data_intake_sessions
    set status='committed',
        context_snapshot=coalesce(context_snapshot,'{}'::jsonb)
          || jsonb_build_object(
               'canonical_commit',true,
               'commit_batch_id',v_batch.id,
               'committed_at',now()
             ),
        updated_at=now()
    where id=v_ds.id;

    update public.data_intake_sources
    set source_metadata=coalesce(source_metadata,'{}'::jsonb)
      || jsonb_build_object(
           'canonical_commit',true,
           'commit_batch_id',v_batch.id,
           'commit_stage','12J',
           'committed_at',now()
         )
    where session_id=v_ds.id;

    update public.phms_storage_assets a
    set metadata=coalesce(a.metadata,'{}'::jsonb)
      || jsonb_build_object(
           'retain_for_provenance',true,
           'retention_reason','12J_canonical_source',
           'canonical_commit_batch_id',v_batch.id,
           'storage_promotion_status',
             case
               when a.bucket_id='phms-intake-temp' then 'pending'
               else 'not_required'
             end
         ),
        updated_at=now()
    where a.id in (
      select distinct s.storage_asset_id
      from public.data_intake_sources s
      where s.session_id=v_ds.id
        and s.storage_asset_id is not null
    );

    select count(*) into v_temp_assets
    from public.data_intake_sources s
    join public.phms_storage_assets a on a.id=s.storage_asset_id
    where s.session_id=v_ds.id
      and a.bucket_id='phms-intake-temp'
      and a.deleted_at is null;

  exception when others then
    get stacked diagnostics
      v_error=message_text,
      v_error_state=returned_sqlstate;

    update public.data_intake_commit_batches
    set status='failed',
        result=jsonb_build_object(
          'ok',false,
          'canonical_commit',false,
          'error',v_error,
          'sqlstate',v_error_state,
          'rolled_back',true
        ),
        committed_at=null
    where id=v_batch.id;

    return jsonb_build_object(
      'ok',false,
      'committed',false,
      'idempotent_replay',false,
      'batch_id',v_batch.id,
      'session_id',v_ds.id,
      'error',v_error,
      'sqlstate',v_error_state,
      'rolled_back',true,
      'canonical_commit',false
    );
  end;

  update public.data_intake_commit_batches
  set status='committed',
      result=jsonb_build_object(
        'ok',true,
        'committed',true,
        'canonical_commit',true,
        'session_id',v_ds.id,
        'batch_id',v_batch.id,
        'resource_counts',jsonb_build_object(
          'medications',v_medications,
          'appointments',v_appointments,
          'health_measurements',v_measurements
        ),
        'records',v_results,
        'storage_promotion_required',v_temp_assets>0,
        'temporary_source_asset_count',v_temp_assets
      ),
      committed_at=now()
  where id=v_batch.id
  returning * into v_batch;

  return v_batch.result
    || jsonb_build_object('idempotent_replay',false);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_complete_line_account_link(p_verification_token text)
 RETURNS TABLE(line_identity_id uuid, user_id uuid, status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_req public.account_link_requests%rowtype;
  v_identity public.line_identities%rowtype;
  v_hash text;
begin
  if v_uid is null then
    raise exception 'authentication_required';
  end if;

  if p_verification_token is null or btrim(p_verification_token) = '' then
    raise exception 'verification_token_required';
  end if;

  if not exists (select 1 from public.profiles where id = v_uid) then
    raise exception 'profile_not_found';
  end if;

  v_hash := encode(digest(p_verification_token, 'sha256'), 'hex');

  select * into v_req
  from public.account_link_requests
  where verification_token_hash = v_hash
  for update;

  if not found then
    raise exception 'invalid_verification_token';
  end if;

  if v_req.status <> 'pending' then
    raise exception 'link_request_not_pending';
  end if;

  if v_req.expires_at is not null and v_req.expires_at <= now() then
    update public.account_link_requests
    set status = 'expired', updated_at = now()
    where id = v_req.id;
    raise exception 'link_request_expired';
  end if;

  select * into v_identity
  from public.line_identities
  where id = v_req.line_identity_id
  for update;

  if not found then
    raise exception 'line_identity_not_found';
  end if;

  if coalesce(v_identity.is_active, false) is not true then
    raise exception 'line_identity_inactive';
  end if;

  if v_identity.user_id is not null and v_identity.user_id <> v_uid then
    raise exception 'line_identity_already_linked_to_another_user';
  end if;

  update public.line_identities
  set user_id = v_uid,
      updated_at = now()
  where id = v_identity.id;

  update public.account_link_requests
  set requested_user_id = v_uid,
      status = 'completed',
      confirmed_at = now(),
      completed_at = now(),
      updated_at = now()
  where id = v_req.id;

  insert into public.audit_logs(
    actor_user_id,
    target_user_id,
    event_type,
    resource,
    record_id,
    new_data,
    description
  ) values (
    v_uid,
    v_uid,
    'line_account_linked',
    'line_identity',
    v_identity.id,
    jsonb_build_object('line_identity_id', v_identity.id, 'is_active', true),
    'LINE identity linked to PHMS user account'
  );

  return query select v_identity.id, v_uid, 'completed'::text;
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_complete_line_onboarding_if_ready(p_line_user_id text)
 RETURNS TABLE(line_identity_id uuid, user_id uuid, onboarding_status text, setup_ready boolean, has_self_person boolean, active_family_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_self boolean;
  v_fc int;
  v_ready boolean;
  v_status text;
begin
  select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
  select exists(select 1 from public.persons p where p.linked_user_id=v_line.user_id and coalesce(p.status,'active')='active') into v_self;
  select count(*)::int into v_fc from public.family_memberships fm join public.families f on f.id=fm.family_id
   where fm.user_id=v_line.user_id and fm.status='active' and coalesce(f.status,'active')='active';
  v_ready := v_self or v_fc>0;

  if v_ready then
    update public.line_identities li
       set onboarding_status='ready',
           onboarding_started_at=coalesce(li.onboarding_started_at,now()),
           onboarding_completed_at=coalesce(li.onboarding_completed_at,now()),
           updated_at=now()
     where li.id=v_line.line_identity_id;
    v_status:='ready';
  else
    update public.line_identities li
       set onboarding_status=case when li.onboarding_status='new' then 'onboarding' else li.onboarding_status end,
           onboarding_started_at=coalesce(li.onboarding_started_at,now()),
           updated_at=now()
     where li.id=v_line.line_identity_id
     returning li.onboarding_status into v_status;
  end if;

  return query select v_line.line_identity_id,v_line.user_id,v_status,v_ready,v_self,v_fc;
end; $function$

CREATE OR REPLACE FUNCTION public.phms_confirm_person_claim(p_claim_request_id uuid, p_line_identity_id uuid)
 RETURNS TABLE(claim_request_id uuid, person_id uuid, status text, requires_approval boolean, linked boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_claim public.person_claim_requests%rowtype;
  v_line public.line_identities%rowtype;
  v_person public.persons%rowtype;
  v_family_person_id uuid;
  v_final_status text;
begin
  if v_user_id is null then raise exception 'authentication_required'; end if;

  select * into v_claim from public.person_claim_requests where id = p_claim_request_id for update;
  if not found then raise exception 'claim_not_found'; end if;
  if v_claim.requested_user_id <> v_user_id then raise exception 'claim_not_owned_by_current_user'; end if;

  if v_claim.status = 'completed' then
    return query select v_claim.id, v_claim.person_id, v_claim.status, v_claim.requires_approval, true;
    return;
  end if;
  if v_claim.status = 'person_confirmed' then
    return query select v_claim.id, v_claim.person_id, v_claim.status, v_claim.requires_approval, false;
    return;
  end if;
  if v_claim.status <> 'pending' then raise exception 'claim_not_pending'; end if;

  if v_claim.expires_at is not null and v_claim.expires_at <= now() then
    update public.person_claim_requests pcr set status='expired', updated_at=now() where pcr.id=v_claim.id;
    return query select v_claim.id, v_claim.person_id, 'expired'::text, v_claim.requires_approval, false;
    return;
  end if;

  select * into v_line from public.line_identities where id = p_line_identity_id for update;
  if not found then raise exception 'line_identity_not_found'; end if;
  if v_line.user_id is distinct from v_user_id then raise exception 'line_identity_not_owned_by_current_user'; end if;
  if coalesce(v_line.is_active,false) is not true then raise exception 'active_line_identity_required'; end if;
  if not exists (select 1 from public.line_identities li where li.user_id=v_user_id and li.is_active=true) then raise exception 'active_line_identity_required'; end if;

  select * into v_person from public.persons where id=v_claim.person_id for update;
  if not found then raise exception 'person_not_found'; end if;
  if v_person.linked_user_id is not null then
    if v_person.linked_user_id=v_user_id then
      update public.person_claim_requests pcr
      set status='completed', confirmed_by_line_identity_id=coalesce(pcr.confirmed_by_line_identity_id,p_line_identity_id), person_confirmed_at=coalesce(pcr.person_confirmed_at,now()), completed_at=coalesce(pcr.completed_at,now()), updated_at=now()
      where pcr.id=v_claim.id;
      return query select v_claim.id, v_claim.person_id, 'completed'::text, v_claim.requires_approval, true;
      return;
    end if;
    raise exception 'person_already_linked_to_another_user';
  end if;

  if exists (select 1 from public.persons p where p.linked_user_id=v_user_id and p.id<>v_claim.person_id) then raise exception 'current_user_already_has_person'; end if;

  select fp.id into v_family_person_id from public.family_persons fp where fp.family_id=v_claim.family_id and fp.person_id=v_claim.person_id limit 1;

  update public.person_claim_requests pcr
  set confirmed_by_line_identity_id=p_line_identity_id,
      person_confirmed_at=now(),
      status=case when v_claim.requires_approval then 'person_confirmed' else 'completed' end,
      completed_at=case when v_claim.requires_approval then pcr.completed_at else now() end,
      updated_at=now()
  where pcr.id=v_claim.id;

  if not v_claim.requires_approval then
    update public.persons p set linked_user_id=v_user_id, updated_at=now() where p.id=v_claim.person_id and p.linked_user_id is null;
    v_final_status:='completed';
  else
    v_final_status:='person_confirmed';
  end if;

  insert into public.audit_logs(family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,record_id,new_data,description)
  values(v_claim.family_id,v_user_id,v_user_id,v_family_person_id,'person_claim_confirmed','person_claim',v_claim.id,
    jsonb_build_object('person_id',v_claim.person_id,'claim_request_id',v_claim.id,'confirmed_by_line_identity_id',p_line_identity_id,'status',v_final_status,'requires_approval',v_claim.requires_approval),
    case when v_claim.requires_approval then 'Claimant confirmed the existing person through an active LINE identity; approval is still required.' else 'Claimant confirmed the existing person through an active LINE identity and the person was linked without a second approval.' end);

  return query select v_claim.id, v_claim.person_id, v_final_status, v_claim.requires_approval, (v_final_status='completed');
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_confirm_person_claim_from_line(p_line_user_id text, p_claim_request_id uuid)
 RETURNS TABLE(claim_request_id uuid, person_id uuid, status text, requires_approval boolean, linked boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line public.line_identities%rowtype;
  v_claim public.person_claim_requests%rowtype;
  v_person public.persons%rowtype;
  v_family_person_id uuid;
  v_final_status text;
begin
  if p_line_user_id is null or btrim(p_line_user_id) = '' then
    raise exception 'line_user_id_required';
  end if;

  select * into v_line
  from public.line_identities
  where line_user_id = p_line_user_id
  for update;

  if not found then raise exception 'line_identity_not_found'; end if;
  if coalesce(v_line.is_active,false) is not true then raise exception 'active_line_identity_required'; end if;
  if v_line.user_id is null then raise exception 'line_identity_not_linked'; end if;

  select * into v_claim
  from public.person_claim_requests
  where id = p_claim_request_id
  for update;

  if not found then raise exception 'claim_not_found'; end if;
  if v_claim.requested_user_id is distinct from v_line.user_id then raise exception 'claim_not_owned_by_line_user'; end if;

  if v_claim.status = 'completed' then
    return query select v_claim.id, v_claim.person_id, v_claim.status, v_claim.requires_approval, true;
    return;
  end if;

  if v_claim.status = 'person_confirmed' then
    return query select v_claim.id, v_claim.person_id, v_claim.status, v_claim.requires_approval, false;
    return;
  end if;

  if v_claim.status <> 'pending' then raise exception 'claim_not_pending'; end if;

  if v_claim.expires_at is not null and v_claim.expires_at <= now() then
    update public.person_claim_requests
    set status='expired', expired_at=coalesce(expired_at,now()), updated_at=now()
    where id=v_claim.id;
    return query select v_claim.id, v_claim.person_id, 'expired'::text, v_claim.requires_approval, false;
    return;
  end if;

  select * into v_person
  from public.persons
  where id=v_claim.person_id
  for update;

  if not found then raise exception 'person_not_found'; end if;

  if v_person.linked_user_id is not null then
    if v_person.linked_user_id = v_line.user_id then
      update public.person_claim_requests
      set status='completed',
          confirmed_by_line_identity_id=coalesce(confirmed_by_line_identity_id,v_line.id),
          person_confirmed_at=coalesce(person_confirmed_at,now()),
          completed_at=coalesce(completed_at,now()),
          updated_at=now()
      where id=v_claim.id;
      return query select v_claim.id, v_claim.person_id, 'completed'::text, v_claim.requires_approval, true;
      return;
    end if;
    raise exception 'person_already_linked_to_another_user';
  end if;

  if exists (
    select 1 from public.persons p
    where p.linked_user_id = v_line.user_id
      and p.id <> v_claim.person_id
  ) then
    raise exception 'current_user_already_has_person';
  end if;

  select fp.id into v_family_person_id
  from public.family_persons fp
  where fp.family_id=v_claim.family_id and fp.person_id=v_claim.person_id
  limit 1;

  update public.person_claim_requests
  set confirmed_by_line_identity_id=v_line.id,
      person_confirmed_at=now(),
      status=case when v_claim.requires_approval then 'person_confirmed' else 'completed' end,
      completed_at=case when v_claim.requires_approval then completed_at else now() end,
      updated_at=now()
  where id=v_claim.id;

  if not v_claim.requires_approval then
    update public.persons
    set linked_user_id=v_line.user_id, updated_at=now()
    where id=v_claim.person_id and linked_user_id is null;
    v_final_status := 'completed';
  else
    v_final_status := 'person_confirmed';
  end if;

  insert into public.audit_logs(
    family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,record_id,new_data,description
  ) values (
    v_claim.family_id,v_line.user_id,v_line.user_id,v_family_person_id,
    'person_claim_confirmed','person_claim',v_claim.id,
    jsonb_build_object(
      'person_id',v_claim.person_id,
      'claim_request_id',v_claim.id,
      'confirmed_by_line_identity_id',v_line.id,
      'status',v_final_status,
      'requires_approval',v_claim.requires_approval,
      'source','line_webhook'
    ),
    case when v_claim.requires_approval
      then 'Claimant confirmed the existing person through active LINE; approval is still required.'
      else 'Claimant confirmed the existing person through active LINE and the person was linked.'
    end
  );

  return query select v_claim.id, v_claim.person_id, v_final_status, v_claim.requires_approval, (v_final_status='completed');
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_create_additional_line_invite(p_line_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line public.line_identities%rowtype;
  v_token text;
  v_hash text;
begin
  select * into v_line
  from public.line_identities
  where line_user_id=p_line_user_id
    and is_active=true
    and user_id is not null
  order by updated_at desc nulls last
  limit 1;
  if not found then raise exception 'linked_line_required'; end if;

  update public.line_identity_link_invites
  set status='revoked',updated_at=now()
  where requested_user_id=v_line.user_id
    and status in ('pending','requested');

  v_token:=encode(gen_random_bytes(24),'hex');
  v_hash:=encode(digest(v_token,'sha256'),'hex');

  insert into public.line_identity_link_invites(
    requested_user_id,created_by_line_identity_id,token_hash,status,expires_at
  ) values (
    v_line.user_id,v_line.id,v_hash,'pending',now()+interval '1 day'
  );

  return jsonb_build_object('invite_token',v_token,'expires_at',now()+interval '1 day');
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_create_family_from_line(p_line_user_id text, p_family_name text)
 RETURNS TABLE(family_id uuid, family_name text, family_code text, self_family_person_id uuid, created_new boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record; v_name text:=nullif(btrim(p_family_name),''); v_family public.families%rowtype;
  v_code text; v_self public.persons%rowtype; v_fp_id uuid; i int:=0;
begin
  select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
  if v_name is null then raise exception 'family_name_required'; end if;
  if length(v_name)>120 then raise exception 'family_name_too_long'; end if;
  loop
    i:=i+1; v_code:='PHMS-'||upper(substr(encode(extensions.gen_random_bytes(6),'hex'),1,8));
    exit when not exists(select 1 from public.families f where upper(btrim(f.family_code))=upper(v_code));
    if i>10 then raise exception 'family_code_generation_failed'; end if;
  end loop;
  insert into public.families(family_name,family_code,created_by,status,created_at,updated_at)
  values(v_name,v_code,v_line.user_id,'active',now(),now()) returning * into v_family;
  insert into public.family_memberships(family_id,user_id,status,joined_at,created_at,updated_at)
  values(v_family.id,v_line.user_id,'active',now(),now(),now()) on conflict do nothing;
  insert into public.family_role_assignments(family_id,user_id,role,status,granted_by,granted_at,created_at,updated_at)
  values(v_family.id,v_line.user_id,'owner','active',v_line.user_id,now(),now(),now()) on conflict do nothing;
  select p.* into v_self from public.persons p where p.linked_user_id=v_line.user_id and coalesce(p.status,'active')='active' order by p.created_at,p.id limit 1;
  if v_self.id is not null then
    select fp.id into v_fp_id from public.family_persons fp where fp.family_id=v_family.id and fp.person_id=v_self.id limit 1;
    if v_fp_id is null then
      insert into public.family_persons(family_id,person_id,relationship_label,status,created_at,updated_at)
      values(v_family.id,v_self.id,'ฉัน','active',now(),now()) returning id into v_fp_id;
    else
      update public.family_persons fp set status='active',relationship_label=coalesce(nullif(btrim(fp.relationship_label),''),'ฉัน'),updated_at=now() where fp.id=v_fp_id;
    end if;
    insert into public.family_person_view_labels(viewer_user_id,family_id,family_person_id,relationship_label,display_label,created_at,updated_at)
    values(v_line.user_id,v_family.id,v_fp_id,'ฉัน',null,now(),now()) on conflict do nothing;
  end if;
  return query select v_family.id,v_family.family_name,v_family.family_code,v_fp_id,true;
end; $function$

CREATE OR REPLACE FUNCTION public.phms_create_family_person_without_account(p_family_id uuid, p_display_name text, p_first_name text DEFAULT NULL::text, p_last_name text DEFAULT NULL::text, p_date_of_birth text DEFAULT NULL::text, p_sex text DEFAULT NULL::text, p_relationship_label text DEFAULT NULL::text)
 RETURNS TABLE(person_id uuid, family_person_id uuid, account_linked boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth'
AS $function$
declare
 v_user_id uuid:=auth.uid();
 v_person_id uuid; v_family_person_id uuid;
 v_label text:=nullif(btrim(coalesce(p_display_name,'')),'');
 v_rel text:=nullif(btrim(coalesce(p_relationship_label,'')),'');
begin
 if v_user_id is null then raise exception 'authentication_required'; end if;
 if p_family_id is null then raise exception 'family_required'; end if;
 if v_label is null then raise exception 'display_name_required'; end if;
 if not exists(select 1 from public.families f where f.id=p_family_id) then raise exception 'family_not_found'; end if;
 if not private.user_has_family_role(v_user_id,p_family_id,array['owner','admin']) then
   raise exception 'permission_denied';
 end if;

 insert into public.persons(
   linked_user_id,display_name,nickname,first_name,last_name,date_of_birth,sex,status,created_at,updated_at
 ) values(
   null,null,null,
   nullif(btrim(coalesce(p_first_name,'')),''),
   nullif(btrim(coalesce(p_last_name,'')),''),
   nullif(btrim(coalesce(p_date_of_birth,'')),''),
   nullif(btrim(coalesce(p_sex,'')),''),
   'active',now(),now()
 ) returning id into v_person_id;

 insert into public.family_persons(family_id,person_id,relationship_label,status,setup_status,setup_created_by,setup_completed_at,created_at,updated_at)
 values(p_family_id,v_person_id,null,'active','draft',v_user_id,null,now(),now())
 returning id into v_family_person_id;

 insert into public.family_person_view_labels(
   viewer_user_id,family_id,family_person_id,display_label,relationship_label,updated_at
 ) values(v_user_id,p_family_id,v_family_person_id,v_label,v_rel,now())
 on conflict(viewer_user_id,family_person_id) do update
 set display_label=excluded.display_label,
     relationship_label=excluded.relationship_label,
     updated_at=now();

 return query select v_person_id,v_family_person_id,false;
end
$function$

CREATE OR REPLACE FUNCTION public.phms_create_line_active_person_invitation(p_line_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_line record;
 v_ctx private.line_identity_contexts%rowtype;
 v_fp public.family_persons%rowtype;
 v_person public.persons%rowtype;
 v_family public.families%rowtype;
 v_token text;
 v_hash text;
 v_invite_name text;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select c.* into v_ctx
 from private.line_identity_contexts c
 where c.line_identity_id=v_line.line_identity_id;

 if v_ctx.active_scope<>'family'
    or v_ctx.active_family_id is null
    or v_ctx.active_family_person_id is null then
   raise exception 'active_family_person_required';
 end if;

 perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
 if not private.can_manage_permissions(v_ctx.active_family_id) then
   raise exception 'person_invite_permission_denied';
 end if;

 select * into v_fp from public.family_persons fp
 where fp.id=v_ctx.active_family_person_id
   and fp.family_id=v_ctx.active_family_id
   and coalesce(fp.status,'active')='active';
 if not found then raise exception 'active_family_person_not_found'; end if;
 if v_fp.setup_status<>'ready' then raise exception 'person_setup_not_published'; end if;

 select * into v_person from public.persons p
 where p.id=v_fp.person_id
   and coalesce(p.status,'active')='active';
 if not found then raise exception 'active_person_not_found'; end if;
 if v_person.linked_user_id is not null then raise exception 'person_already_linked'; end if;

 -- ก่อนเชื่อม ต้องเลือกอย่างน้อยหนึ่งแบบ:
 -- 1) เจ้าตัวจัดการข้อมูลตัวเอง หรือ 2) มีคนอื่นช่วยจัดการข้อมูลนี้
 if not private.family_person_self_manage_enabled(v_fp.id)
    and not exists(
      select 1 from public.person_caregiver_assignments ca
      where ca.family_person_id=v_fp.id and ca.status='active'
    )
    and not exists(
      select 1 from private.family_person_pending_access pa
      where pa.target_family_person_id=v_fp.id and pa.is_caregiver=true
    ) then
   raise exception 'self_manage_or_helper_required_before_person_invite';
 end if;

 select * into v_family from public.families f where f.id=v_ctx.active_family_id;

 v_invite_name:=nullif(btrim(concat_ws(' ',v_person.first_name,v_person.last_name)),'');
 if v_invite_name is null
    or nullif(btrim(v_person.first_name),'') is null
    or nullif(btrim(v_person.last_name),'') is null then
   raise exception 'legal_name_required_for_person_invite';
 end if;

 update public.person_claim_invitations
 set status='revoked',revoked_at=now(),updated_at=now()
 where person_id=v_person.id and status='pending';

 v_token:=encode(gen_random_bytes(24),'hex');
 v_hash:=encode(digest(v_token,'sha256'),'hex');

 insert into public.person_claim_invitations(
   person_id,family_id,invited_by_user_id,invitation_token_hash,status,expires_at,metadata
 ) values(
   v_person.id,v_ctx.active_family_id,v_line.user_id,v_hash,'pending',
   now()+interval '30 days',
   jsonb_build_object(
     'invite_kind','person_identity',
     'family_person_id',v_fp.id,
     'invite_person_name',v_invite_name,
     'identity_name_source','legal_name_only'
   )
 );

 return jsonb_build_object(
   'invite_token',v_token,
   'family_id',v_ctx.active_family_id,
   'family_name',coalesce(v_family.family_name,'ครอบครัว'),
   'family_code',v_family.family_code,
   'person_name',v_invite_name,
   'expires_at',now()+interval '30 days'
 );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_create_line_family_invite(p_line_user_id text)
 RETURNS TABLE(family_id uuid, family_name text, family_code text, invite_token text, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_line record; v_ctx private.line_identity_contexts%rowtype;
 v_name text; v_code text; v_token text; v_hash text; v_exp timestamptz;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select c.* into v_ctx from private.line_identity_contexts c
 where c.line_identity_id=v_line.line_identity_id;
 if v_ctx.active_scope<>'family' or v_ctx.active_family_id is null then raise exception 'family_not_selected'; end if;
 if not exists(select 1 from public.family_memberships fm
               where fm.family_id=v_ctx.active_family_id and fm.user_id=v_line.user_id and fm.status='active')
 then raise exception 'not_family_member'; end if;

 perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
 if not private.user_has_family_role(v_line.user_id,v_ctx.active_family_id,array['owner','admin']) then
   raise exception 'family_invite_manager_required';
 end if;

 select f.family_name,f.family_code into v_name,v_code
 from public.families f
 where f.id=v_ctx.active_family_id and coalesce(f.status,'active')='active';
 if v_name is null then raise exception 'family_not_found'; end if;

 v_token:=encode(gen_random_bytes(24),'hex');
 v_hash:=encode(digest(v_token,'sha256'),'hex');
 v_exp:=now()+interval '30 days';

 insert into public.family_invite_links(family_id,token_hash,created_by,status,expires_at,created_at)
 values(v_ctx.active_family_id,v_hash,v_line.user_id,'active',v_exp,now());

 return query select v_ctx.active_family_id,v_name,v_code,v_token,v_exp;
end
$function$

CREATE OR REPLACE FUNCTION public.phms_create_line_family_person_invite(p_line_user_id text, p_person_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_person_ref record;
  v_fp public.family_persons%rowtype;
  v_person public.persons%rowtype;
  v_family public.families%rowtype;
  v_family_inv record;
  v_person_token text;
  v_person_hash text;
  v_invite_name text;
begin
  select * into v_person_ref
  from private.resolve_line_family_person_code(
    p_line_user_id,p_person_code
  )
  limit 1;

  perform set_config(
    'request.jwt.claim.sub',
    v_person_ref.actor_user_id::text,
    true
  );

  if not private.can_manage_permissions(v_person_ref.family_id) then
    raise exception 'person_invite_permission_denied';
  end if;

  select * into v_fp
  from public.family_persons fp
  where fp.id=v_person_ref.family_person_id
    and fp.family_id=v_person_ref.family_id
    and coalesce(fp.status,'active')='active';

  if not found then raise exception 'family_person_not_found'; end if;
  if v_fp.setup_status<>'ready' then
    raise exception 'person_setup_not_published';
  end if;

  select * into v_person
  from public.persons p
  where p.id=v_fp.person_id
    and coalesce(p.status,'active')='active'
  for update;

  if not found then raise exception 'person_not_found'; end if;
  if v_person.linked_user_id is not null then
    raise exception 'person_already_linked';
  end if;

  if not private.family_person_self_manage_enabled(v_fp.id)
     and not exists(
       select 1
       from public.person_caregiver_assignments ca
       where ca.family_person_id=v_fp.id
         and ca.status='active'
     )
     and not exists(
       select 1
       from private.family_person_pending_access pa
       where pa.target_family_person_id=v_fp.id
         and pa.is_caregiver=true
     ) then
    raise exception 'self_manage_or_helper_required_before_person_invite';
  end if;

  v_invite_name:=nullif(
    btrim(concat_ws(' ',v_person.first_name,v_person.last_name)),
    ''
  );

  if v_invite_name is null
     or nullif(btrim(v_person.first_name),'') is null
     or nullif(btrim(v_person.last_name),'') is null then
    raise exception 'legal_name_required_for_person_invite';
  end if;

  select * into v_family
  from public.families f
  where f.id=v_person_ref.family_id
    and coalesce(f.status,'active')='active';

  if not found then raise exception 'family_not_found'; end if;

  select * into v_family_inv
  from public.phms_create_line_family_invite(p_line_user_id);

  update public.person_claim_invitations
  set status='revoked',
      revoked_at=now(),
      updated_at=now()
  where person_id=v_person.id
    and status='pending';

  v_person_token:=encode(gen_random_bytes(24),'hex');
  v_person_hash:=encode(digest(v_person_token,'sha256'),'hex');

  insert into public.person_claim_invitations(
    person_id,
    family_id,
    invited_by_user_id,
    invitation_token_hash,
    status,
    expires_at,
    metadata
  )
  values(
    v_person.id,
    v_person_ref.family_id,
    v_person_ref.actor_user_id,
    v_person_hash,
    'pending',
    now()+interval '30 days',
    jsonb_build_object(
      'invite_kind','person_identity',
      'family_person_id',v_fp.id,
      'invite_person_name',v_invite_name,
      'identity_name_source','legal_name_only',
      'created_from','family_invite_person_picker'
    )
  );

  insert into public.audit_logs(
    family_id,
    actor_user_id,
    family_person_id,
    event_type,
    resource,
    record_id,
    new_data,
    description
  )
  values(
    v_person_ref.family_id,
    v_person_ref.actor_user_id,
    v_fp.id,
    'family_person_invite_created',
    'family_invite',
    v_person.id,
    jsonb_build_object(
      'person_id',v_person.id,
      'family_person_id',v_fp.id,
      'person_name',v_invite_name,
      'target_unlinked_person',true
    ),
    'สร้างคำเชิญเข้าครอบครัวสำหรับบุคคลที่ยังไม่เชื่อมบัญชี'
  );

  return jsonb_build_object(
    'ok',true,
    'family_id',v_person_ref.family_id,
    'family_name',coalesce(v_family.family_name,'ครอบครัว'),
    'family_code',v_family.family_code,
    'family_invite_token',v_family_inv.invite_token,
    'person_invite_token',v_person_token,
    'person_name',v_invite_name,
    'person_code',lower(btrim(p_person_code)),
    'expires_at',least(
      v_family_inv.expires_at,
      now()+interval '30 days'
    )
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_create_line_family_person_without_account(p_line_user_id text, p_display_name text, p_relationship_label text DEFAULT NULL::text, p_first_name text DEFAULT NULL::text, p_last_name text DEFAULT NULL::text, p_date_of_birth text DEFAULT NULL::text, p_sex text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_line public.line_identities%rowtype; v_ctx private.line_identity_contexts%rowtype;
 v_name text:=nullif(btrim(coalesce(p_display_name,'')),'');
 v_rel text:=nullif(btrim(coalesce(p_relationship_label,'')),'');
 v_first text:=nullif(btrim(coalesce(p_first_name,'')),'');
 v_last text:=nullif(btrim(coalesce(p_last_name,'')),'');
 v_person_id uuid; v_family_person_id uuid; v_created boolean:=false; v_selection_code text; v_dob date;
begin
 if v_name is null then raise exception 'display_name_required'; end if;
 if length(v_name)>120 then raise exception 'display_name_too_long'; end if;
 if v_rel is not null and length(v_rel)>80 then raise exception 'relationship_label_too_long'; end if;

 select * into v_line from public.line_identities li
 where li.line_user_id=p_line_user_id and li.is_active=true and li.onboarding_status='ready' and li.user_id is not null
 order by li.updated_at desc nulls last,li.created_at desc limit 1;
 if not found then raise exception 'line_identity_not_ready'; end if;

 perform private.ensure_line_identity_context(v_line.id,v_line.user_id);
 select c.* into v_ctx from private.line_identity_contexts c where c.line_identity_id=v_line.id for update;
 if v_ctx.active_scope<>'family' or v_ctx.active_family_id is null then raise exception 'family_context_required'; end if;

 perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
 if not private.user_has_family_role(v_line.user_id,v_ctx.active_family_id,array['owner','admin']) then
   raise exception 'permission_denied';
 end if;

 if nullif(btrim(coalesce(p_date_of_birth,'')),'') is not null then v_dob:=private.normalize_phms_date(p_date_of_birth); end if;

 select p.id,fp.id into v_person_id,v_family_person_id
 from public.family_persons fp
 join public.persons p on p.id=fp.person_id
 left join public.family_person_view_labels vl
   on vl.viewer_user_id=v_line.user_id and vl.family_person_id=fp.id
 where fp.family_id=v_ctx.active_family_id and coalesce(fp.status,'active')='active' and coalesce(p.status,'active')='active'
   and lower(btrim(coalesce(vl.display_label,p.nickname,nullif(btrim(concat_ws(' ',p.first_name,p.last_name)),''),'')))=lower(v_name)
   and lower(btrim(coalesce(vl.relationship_label,'')))=lower(coalesce(v_rel,''))
 order by fp.created_at limit 1;

 if v_person_id is null then
   insert into public.persons(
     linked_user_id,display_name,nickname,first_name,last_name,date_of_birth,sex,status,created_at,updated_at
   ) values(
     null,null,null,v_first,v_last,
     case when v_dob is null then null else to_char(v_dob,'YYYY-MM-DD') end,
     nullif(btrim(coalesce(p_sex,'')),''),'active',now(),now()
   ) returning id into v_person_id;

   insert into public.family_persons(family_id,person_id,relationship_label,status,setup_status,setup_created_by,setup_completed_at,created_at,updated_at)
   values(v_ctx.active_family_id,v_person_id,null,'active','draft',v_line.user_id,null,now(),now())
   returning id into v_family_person_id;

   insert into public.family_person_view_labels(
     viewer_user_id,family_id,family_person_id,display_label,relationship_label,updated_at
   ) values(v_line.user_id,v_ctx.active_family_id,v_family_person_id,v_name,v_rel,now())
   on conflict (viewer_user_id,family_person_id) do update
   set display_label=excluded.display_label,relationship_label=excluded.relationship_label,updated_at=now();

   v_created:=true;
   insert into public.audit_logs(
     family_id,actor_user_id,family_person_id,event_type,resource,record_id,new_data,description,created_at
   ) values(
     v_ctx.active_family_id,v_line.user_id,v_family_person_id,'family_person_created_without_account','persons',v_person_id,
     jsonb_build_object('person_id',v_person_id,'family_person_id',v_family_person_id,'linked_user_id',null,
       'viewer_private_display_label',v_name,'viewer_private_relationship',v_rel,
       'first_name',v_first,'last_name',v_last,'source','line'),
     'Created family person; viewer label and relationship are private per viewer',now()
   );
 end if;

 update private.line_identity_contexts c
 set active_scope='family',active_family_person_id=v_family_person_id,
     context_changed_at=case when c.active_family_person_id is distinct from v_family_person_id then now() else c.context_changed_at end,
     updated_at=now()
 where c.line_identity_id=v_line.id;

 v_selection_code:=substr(encode(digest(v_family_person_id::text||':'||v_line.id::text,'sha256'),'hex'),1,12);

 return jsonb_build_object(
   'ok',true,'created',v_created,'family_id',v_ctx.active_family_id,
   'family_person_id',v_family_person_id,'person_id',v_person_id,
   'display_name',private.family_person_label_for_viewer(v_line.user_id,v_family_person_id),
   'relationship_label',case when (select linked_user_id from public.persons where id=v_person_id)=v_line.user_id then 'ฉัน' else v_rel end,
   'selection_code',v_selection_code,'account_linked',false,'context_selected',true,'setup_status',case when v_created then 'draft' else (select fp.setup_status from public.family_persons fp where fp.id=v_family_person_id) end
 );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_create_line_test_draft(p_line_user_id text, p_target_resource text, p_payload jsonb)
 RETURNS TABLE(draft_id uuid, person_id uuid, target_resource text, status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare v_line record; v_ctx private.line_identity_contexts%rowtype; v_person uuid; v_id uuid;
begin
 select li.id as line_identity_id,li.user_id into v_line from public.line_identities li where li.line_user_id=p_line_user_id and li.is_active=true and li.user_id is not null order by li.updated_at desc nulls last limit 1;
 if not found then raise exception 'account_not_linked'; end if;
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select c.* into v_ctx from private.line_identity_contexts c where c.line_identity_id=v_line.line_identity_id;
 if v_ctx.active_scope='family' and v_ctx.active_family_person_id is not null then
  select fp.person_id into v_person from public.family_persons fp where fp.id=v_ctx.active_family_person_id and coalesce(fp.status,'active')='active' and private.user_can_see_family_person(v_line.user_id,fp.id);
 else
  select p.id into v_person from public.persons p where p.linked_user_id=v_line.user_id and p.status='active' order by p.created_at limit 1;
 end if;
 if v_person is null then raise exception 'person_not_resolved'; end if;
 insert into public.data_intake_drafts(family_id,family_person_id,submitted_by,source_type,target_resource,raw_text,extracted_data,status,person_id,document_type,review_required,approval_required,validation_data,conflict_data)
 values(v_ctx.active_family_id,v_ctx.active_family_person_id,v_line.user_id,'line_text_test',p_target_resource,p_payload::text,p_payload,'draft',v_person,'free_text',true,true,jsonb_build_object('mode','test_ux','canonical_commit',false),'{}'::jsonb)
 returning id into v_id;
 return query select v_id,v_person,p_target_resource,'draft'::text;
end $function$

CREATE OR REPLACE FUNCTION public.phms_create_own_person_after_linking(p_display_name text DEFAULT NULL::text, p_first_name text DEFAULT NULL::text, p_last_name text DEFAULT NULL::text, p_date_of_birth text DEFAULT NULL::text, p_sex text DEFAULT NULL::text, p_family_id uuid DEFAULT NULL::uuid, p_relationship_label text DEFAULT NULL::text)
 RETURNS TABLE(person_id uuid, family_person_id uuid, linked_user_id uuid, created_new boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_person_id uuid;
  v_family_person_id uuid;
  v_has_active_line boolean;
begin
  if v_user_id is null then
    raise exception 'authentication_required';
  end if;

  if not exists (select 1 from public.profiles p where p.id = v_user_id) then
    raise exception 'profile_not_found';
  end if;

  select exists(
    select 1
    from public.line_identities li
    where li.user_id = v_user_id
      and coalesce(li.is_active, false) = true
  ) into v_has_active_line;

  if not v_has_active_line then
    raise exception 'active_linked_line_identity_required';
  end if;

  select p.id into v_person_id
  from public.persons p
  where p.linked_user_id = v_user_id
  limit 1;

  if v_person_id is not null then
    raise exception 'current_user_already_has_person';
  end if;

  if exists (
    select 1
    from public.person_claim_requests pcr
    where pcr.requested_user_id = v_user_id
      and pcr.status in ('pending','person_confirmed','approved')
  ) then
    raise exception 'current_user_has_open_claim';
  end if;

  if p_family_id is not null then
    if not private.is_active_family_member(p_family_id) then
      raise exception 'active_family_membership_required';
    end if;
  end if;

  insert into public.persons(
    linked_user_id, display_name, first_name, last_name,
    date_of_birth, sex, status, created_at, updated_at
  ) values (
    v_user_id,
    nullif(btrim(p_display_name), ''),
    nullif(btrim(p_first_name), ''),
    nullif(btrim(p_last_name), ''),
    nullif(btrim(p_date_of_birth), ''),
    nullif(btrim(p_sex), ''),
    'active', now(), now()
  )
  returning id into v_person_id;

  if p_family_id is not null then
    insert into public.family_persons(
      family_id, person_id, relationship_label, status, created_at, updated_at
    ) values (
      p_family_id,
      v_person_id,
      coalesce(nullif(btrim(p_relationship_label), ''), 'ตัวฉัน'),
      'active', now(), now()
    )
    returning id into v_family_person_id;
  end if;

  insert into public.audit_logs(
    family_id,
    actor_user_id,
    target_user_id,
    family_person_id,
    event_type,
    resource,
    record_id,
    new_data,
    description
  ) values (
    p_family_id,
    v_user_id,
    v_user_id,
    v_family_person_id,
    'self_person_created_after_account_link',
    'person',
    v_person_id,
    jsonb_build_object(
      'person_id', v_person_id,
      'linked_user_id', v_user_id,
      'family_id', p_family_id,
      'family_person_id', v_family_person_id,
      'source', 'post_account_link'
    ),
    'Authenticated user created their own person after linking at least one active LINE identity.'
  );

  return query
  select v_person_id, v_family_person_id, v_user_id, true;
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_create_own_person_from_line(p_line_user_id text, p_display_name text)
 RETURNS TABLE(person_id uuid, display_name text, created_new boolean, setup_ready boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_person public.persons%rowtype;
  v_name text := nullif(btrim(p_display_name),'');
begin
  select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
  if v_name is null then raise exception 'display_name_required'; end if;
  if length(v_name)>120 then raise exception 'display_name_too_long'; end if;

  select p.* into v_person
  from public.persons p
  where p.linked_user_id=v_line.user_id
  order by case when coalesce(p.status,'active')='active' then 0 else 1 end,p.created_at,p.id
  limit 1;

  if v_person.id is null then
    insert into public.persons(linked_user_id,display_name,status,created_at,updated_at)
    values(v_line.user_id,v_name,'active',now(),now())
    returning * into v_person;
    return query select v_person.id,v_person.display_name,true,true;
  else
    if coalesce(v_person.status,'active')<>'active' then raise exception 'self_person_inactive'; end if;
    if nullif(btrim(v_person.display_name),'') is null then
      update public.persons p set display_name=v_name,updated_at=now() where p.id=v_person.id returning * into v_person;
    end if;
    return query select v_person.id,coalesce(nullif(btrim(v_person.display_name),''),v_name),false,true;
  end if;
end; $function$

CREATE OR REPLACE FUNCTION public.phms_create_person_claim_invitation(p_person_id uuid, p_family_id uuid, p_ttl_hours integer DEFAULT 72)
 RETURNS TABLE(invitation_id uuid, invitation_token text, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_token text;
  v_hash text;
  v_exp timestamptz;
  v_id uuid;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  if p_ttl_hours < 1 or p_ttl_hours > 168 then raise exception 'invalid_ttl_hours'; end if;

  if not exists (
    select 1
    from public.family_persons fp
    join public.persons p on p.id = fp.person_id
    where fp.family_id = p_family_id
      and fp.person_id = p_person_id
      and fp.status = 'active'
      and p.status = 'active'
  ) then
    raise exception 'person_not_in_family';
  end if;

  if exists (
    select 1 from public.persons p
    where p.id = p_person_id and p.linked_user_id is not null
  ) then
    raise exception 'person_already_linked';
  end if;

  if not (private.is_family_owner(p_family_id) or private.has_family_permission(p_family_id,'persons','update')) then
    raise exception 'insufficient_permission';
  end if;

  update public.person_claim_invitations pci
     set status='expired', expired_at=coalesce(pci.expired_at,now()), updated_at=now()
   where pci.person_id=p_person_id
     and pci.status='pending'
     and pci.expires_at <= now();

  update public.person_claim_invitations pci
     set status='revoked', revoked_at=now(), updated_at=now()
   where pci.person_id=p_person_id
     and pci.status='pending';

  v_token := encode(gen_random_bytes(32),'hex');
  v_hash := encode(digest(v_token,'sha256'),'hex');
  v_exp := now() + make_interval(hours => p_ttl_hours);

  insert into public.person_claim_invitations(
    person_id,family_id,invited_by_user_id,invitation_token_hash,expires_at
  ) values (
    p_person_id,p_family_id,v_uid,v_hash,v_exp
  ) returning id into v_id;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,new_data,description
  )
  select p_family_id,v_uid,fp.id,'person_claim_invitation_created','person_claim_invitation',v_id,
         jsonb_build_object('person_id',p_person_id,'expires_at',v_exp),
         'Created invitation for an existing person to claim their PHMS person record'
    from public.family_persons fp
   where fp.family_id=p_family_id and fp.person_id=p_person_id
   limit 1;

  return query select v_id,v_token,v_exp;
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_diagnostic_add_procedure(p_line_user_id text, p_appointment_id uuid, p_code text, p_name_th text, p_name_en text, p_category text, p_request_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE ctx record; ap record; item record; next_sequence integer;
BEGIN
 SELECT * INTO ctx FROM private.phms_line_crud_context(p_line_user_id,'appointment','update');
 IF ctx.actor_user_id IS NULL OR ctx.target_person_id IS NULL OR ctx.active_family_id IS NULL THEN
  RAISE EXCEPTION 'diagnostic_permission_denied'; END IF;
 IF length(btrim(coalesce(p_code,''))) NOT BETWEEN 2 AND 70
 OR length(btrim(coalesce(p_name_th,''))) NOT BETWEEN 2 AND 160
 OR length(btrim(coalesce(p_request_key,''))) NOT BETWEEN 12 AND 180
 THEN RAISE EXCEPTION 'invalid_procedure_input'; END IF;
 SELECT * INTO ap FROM public.appointments
 WHERE id=p_appointment_id AND family_id=ctx.active_family_id
 AND person_id=ctx.target_person_id AND appointment_type='investigation'
 AND deleted_at IS NULL FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'diagnostic_appointment_not_found'; END IF;
 SELECT * INTO item FROM public.appointment_procedure_items
 WHERE appointment_id=ap.id AND request_key=p_request_key;
 IF FOUND THEN
  IF item.procedure_code<>btrim(p_code) OR item.procedure_name_th<>btrim(p_name_th)
   THEN RAISE EXCEPTION 'idempotency_conflict'; END IF;
  RETURN jsonb_build_object('ok',true,'item_id',item.id,'duplicate',true);
 END IF;
 SELECT coalesce(max(sequence_no),0)+1 INTO next_sequence
 FROM public.appointment_procedure_items WHERE appointment_id=ap.id;
 INSERT INTO public.appointment_procedure_items
 (appointment_id,procedure_code,procedure_name_th,procedure_name_en,procedure_category,
 sequence_no,created_by,request_key,status)
 VALUES(ap.id,btrim(p_code),btrim(p_name_th),nullif(btrim(p_name_en),''),
 coalesce(nullif(btrim(p_category),''),'other'),next_sequence,ctx.actor_user_id,
 p_request_key,'PLANNED') RETURNING * INTO item;
 RETURN jsonb_build_object('ok',true,'item_id',item.id,'duplicate',false);
END $function$

CREATE OR REPLACE FUNCTION public.phms_enforce_client_ocr_quality()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_q numeric;
  v_blocking jsonb;
begin
  if coalesce(new.confidence_data->>'ocr_location','') <> 'client_device' then
    return new;
  end if;

  begin
    v_q := coalesce((new.confidence_data->>'quality_score')::numeric,0);
  exception when others then
    v_q := 0;
  end;

  v_blocking := coalesce(new.validation_data->'blocking_errors','[]'::jsonb);
  if jsonb_typeof(v_blocking) <> 'array' then
    v_blocking := '[]'::jsonb;
  end if;

  -- Remove our own previous quality flag, then recalculate.
  select coalesce(jsonb_agg(x),'[]'::jsonb)
  into v_blocking
  from jsonb_array_elements(v_blocking) x
  where x <> '"ocr_quality_low"'::jsonb;

  if v_q < 0.45 then
    v_blocking := v_blocking || jsonb_build_array('ocr_quality_low');
  end if;

  new.validation_data :=
    coalesce(new.validation_data,'{}'::jsonb)
    || jsonb_build_object(
         'blocking_errors',v_blocking,
         'ocr_quality_score',v_q,
         'ocr_quality_threshold',0.45
       );
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.phms_expire_stale_linking_records()
 RETURNS TABLE(account_links_expired integer, person_claims_expired integer, invitations_expired integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth'
AS $function$
declare
  v_role text := coalesce(auth.role(), '');
  v_a integer := 0;
  v_c integer := 0;
  v_i integer := 0;
begin
  if v_role <> 'service_role' then
    raise exception 'service_role_required';
  end if;

  update public.account_link_requests
     set status = 'expired', expired_at = now(), updated_at = now()
   where status in ('pending','confirmed')
     and expires_at is not null
     and expires_at <= now();
  get diagnostics v_a = row_count;

  update public.person_claim_requests
     set status = 'expired', expired_at = now(), updated_at = now()
   where status in ('pending','person_confirmed','approved')
     and expires_at is not null
     and expires_at <= now();
  get diagnostics v_c = row_count;

  update public.person_claim_invitations
     set status = 'expired', expired_at = now(), updated_at = now()
   where status = 'pending'
     and expires_at <= now();
  get diagnostics v_i = row_count;

  return query select v_a, v_c, v_i;
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_finalize_line_intake_review(p_line_user_id text, p_source_code text, p_decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line public.line_identities%rowtype;
  v_source public.data_intake_sources%rowtype;
  v_session public.data_intake_sessions%rowtype;
  v_code text := lower(btrim(coalesce(p_source_code,'')));
  v_decision text := lower(btrim(coalesce(p_decision,'')));
  v_match_count integer;
  v_candidates integer;
  v_validation_blocking integer;
  v_conflict_blocking integer;
  v_person_name text;
  v_cid uuid;
begin
  if v_decision not in ('confirm','cancel') then raise exception 'invalid_review_decision'; end if;
  if length(v_code)<8 then raise exception 'source_code_too_short'; end if;

  select * into v_line from public.line_identities
  where line_user_id=p_line_user_id and coalesce(is_active,false)=true
  limit 1;
  if not found or v_line.user_id is null then raise exception 'line_identity_not_linked'; end if;

  select count(*) into v_match_count
  from public.data_intake_sources s
  where s.submitted_by=v_line.user_id
    and lower(s.id::text) like v_code||'%';
  if v_match_count=0 then raise exception 'intake_source_not_found'; end if;
  if v_match_count>1 then raise exception 'intake_source_code_ambiguous'; end if;

  select * into v_source
  from public.data_intake_sources s
  where s.submitted_by=v_line.user_id
    and lower(s.id::text) like v_code||'%'
  limit 1;

  select * into v_session
  from public.data_intake_sessions
  where id=v_source.session_id
  for update;

  if v_decision='cancel' then
    if v_session.status='cancelled' then
      return jsonb_build_object(
        'ok',true,'idempotent_replay',true,'decision','cancel',
        'source_id',v_source.id,'source_code',substr(v_source.id::text,1,12),
        'session_status','cancelled','canonical_commit',false
      );
    end if;
    if v_session.status in ('confirmed','committed') then
      raise exception 'confirmed_intake_cannot_be_cancelled_here';
    end if;

    update public.data_intake_candidates
    set review_status='rejected',updated_at=now()
    where source_id=v_source.id
      and review_status not in ('committed');

    update public.data_intake_sessions
    set status='cancelled',updated_at=now()
    where id=v_session.id;

    update public.data_intake_sources
    set source_metadata=
      coalesce(source_metadata,'{}'::jsonb)
      || jsonb_build_object(
           'review_decision','cancelled',
           'reviewed_at',now(),
           'canonical_commit',false
         )
    where id=v_source.id;

    insert into public.data_intake_actions(
      session_id,actor_user_id,action,after_data
    )
    values(
      v_session.id,v_line.user_id,'cancel',
      jsonb_build_object('source_id',v_source.id,'canonical_commit',false)
    );

    return jsonb_build_object(
      'ok',true,'idempotent_replay',false,'decision','cancel',
      'source_id',v_source.id,'source_code',substr(v_source.id::text,1,12),
      'session_status','cancelled','canonical_commit',false
    );
  end if;

  if v_session.status='confirmed' then
    return jsonb_build_object(
      'ok',true,'idempotent_replay',true,'decision','confirm',
      'source_id',v_source.id,'source_code',substr(v_source.id::text,1,12),
      'session_status','confirmed','canonical_commit',false
    );
  end if;
  if v_session.status in ('cancelled','rejected','committed') then
    raise exception 'intake_session_not_confirmable';
  end if;
  if coalesce(v_source.source_metadata->>'extraction_status','') <> 'completed' then
    raise exception 'extraction_not_completed';
  end if;
  if v_session.person_id is null then
    raise exception 'person_required';
  end if;

  -- Reconcile against the latest state immediately before confirmation.
  for v_cid in
    select c.id
    from public.data_intake_candidates c
    where c.source_id=v_source.id
      and c.review_status not in ('rejected','committed')
  loop
    perform private.phms_reconcile_intake_candidate_core(v_cid);
  end loop;

  select
    count(*),
    count(*) filter (
      where jsonb_array_length(coalesce(c.validation_data->'blocking_errors','[]'::jsonb))>0
    ),
    count(*) filter (
      where jsonb_array_length(coalesce(c.conflict_data->'blocking_conflicts','[]'::jsonb))>0
    )
  into v_candidates,v_validation_blocking,v_conflict_blocking
  from public.data_intake_candidates c
  where c.source_id=v_source.id
    and c.review_status not in ('rejected');

  if v_candidates=0 then raise exception 'candidate_required'; end if;
  if v_validation_blocking>0 then raise exception 'candidate_validation_failed'; end if;
  if v_conflict_blocking>0 then raise exception 'candidate_conflict_blocked'; end if;

  update public.data_intake_candidates
  set review_status='accepted',updated_at=now()
  where source_id=v_source.id
    and review_status in ('pending','needs_review','edited');

  update public.data_intake_sessions
  set status='confirmed',updated_at=now()
  where id=v_session.id;

  update public.data_intake_sources
  set source_metadata=
    coalesce(source_metadata,'{}'::jsonb)
    || jsonb_build_object(
         'review_decision','confirmed',
         'reviewed_at',now(),
         'duplicate_conflict_check','passed',
         'canonical_commit',false,
         'commit_stage','12J_not_started'
       )
  where id=v_source.id;

  insert into public.data_intake_actions(
    session_id,actor_user_id,action,after_data
  )
  values(
    v_session.id,v_line.user_id,'confirm',
    jsonb_build_object(
      'source_id',v_source.id,
      'candidate_count',v_candidates,
      'person_id',v_session.person_id,
      'duplicate_conflict_check','passed',
      'canonical_commit',false,
      'next_stage','12J'
    )
  );

  select coalesce(nullif(btrim(p.display_name),''),
                  nullif(btrim(concat_ws(' ',p.first_name,p.last_name)),''),
                  'ไม่ระบุชื่อ')
  into v_person_name
  from public.persons p where p.id=v_session.person_id;

  return jsonb_build_object(
    'ok',true,'idempotent_replay',false,'decision','confirm',
    'source_id',v_source.id,'source_code',substr(v_source.id::text,1,12),
    'session_status','confirmed',
    'person_id',v_session.person_id,
    'person_name',v_person_name,
    'document_type',v_source.document_type,
    'candidate_count',v_candidates,
    'duplicate_conflict_check','passed',
    'canonical_commit',false,
    'next_stage','12J'
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_finalize_line_link_completion(p_line_user_id text)
 RETURNS TABLE(line_identity_id uuid, user_id uuid, person_id uuid, linking_complete boolean, linking_completed_at timestamp with time zone, conversation_state text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line public.line_identities%rowtype;
  v_person_id uuid;
  v_now timestamptz := now();
begin
  if p_line_user_id is null or btrim(p_line_user_id) = '' then
    raise exception 'line_user_id_required';
  end if;

  select * into v_line
  from public.line_identities
  where line_user_id = p_line_user_id
  for update;

  if not found then
    return query select null::uuid, null::uuid, null::uuid, false, null::timestamptz, 'line_identity_missing'::text;
    return;
  end if;

  if coalesce(v_line.is_active,false) is not true then
    return query select v_line.id, v_line.user_id, null::uuid, false, v_line.linking_completed_at, 'line_inactive'::text;
    return;
  end if;

  if v_line.user_id is null then
    return query select v_line.id, null::uuid, null::uuid, false, v_line.linking_completed_at, 'account_unlinked'::text;
    return;
  end if;

  select p.id into v_person_id
  from public.persons p
  where p.linked_user_id = v_line.user_id
    and coalesce(p.status,'active') = 'active'
  limit 1;

  if v_person_id is null then
    return query select v_line.id, v_line.user_id, null::uuid, false, v_line.linking_completed_at, 'account_linked_no_person'::text;
    return;
  end if;

  if v_line.linking_completed_at is null then
    update public.line_identities
    set linking_completed_at = v_now,
        updated_at = v_now
    where id = v_line.id;

    insert into public.audit_logs(
      actor_user_id,
      target_user_id,
      event_type,
      resource,
      record_id,
      new_data,
      description
    ) values (
      v_line.user_id,
      v_line.user_id,
      'line_linking_completed',
      'line_identity',
      v_line.id,
      jsonb_build_object(
        'line_identity_id', v_line.id,
        'person_id', v_person_id,
        'linking_completed_at', v_now
      ),
      'LINE identity, PHMS user account, and self person linkage completed.'
    );

    v_line.linking_completed_at := v_now;
  end if;

  return query select v_line.id, v_line.user_id, v_person_id, true, v_line.linking_completed_at, 'person_linked'::text;
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_finalize_line_text_draft(p_line_user_id text, p_draft_code text, p_decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
declare
  v_line public.line_identities%rowtype;
  v_draft public.data_intake_drafts%rowtype;
  v_code text := lower(btrim(coalesce(p_draft_code,'')));
  v_decision text := lower(btrim(coalesce(p_decision,'')));
  v_count integer;
begin
  if v_decision not in ('confirm','cancel') then
    raise exception 'invalid_draft_decision';
  end if;
  if length(v_code)<8 then
    raise exception 'draft_code_too_short';
  end if;

  select * into v_line
  from public.line_identities
  where line_user_id=p_line_user_id
    and coalesce(is_active,false)=true
  limit 1;

  if not found or v_line.user_id is null then
    raise exception 'line_identity_not_linked';
  end if;

  select count(*) into v_count
  from public.data_intake_drafts d
  where d.submitted_by=v_line.user_id
    and lower(d.id::text) like v_code||'%';

  if v_count=0 then raise exception 'draft_not_found'; end if;
  if v_count>1 then raise exception 'draft_code_ambiguous'; end if;

  select * into v_draft
  from public.data_intake_drafts d
  where d.submitted_by=v_line.user_id
    and lower(d.id::text) like v_code||'%'
  limit 1
  for update;

  if v_decision='cancel' then
    if v_draft.status='rejected' then
      return jsonb_build_object(
        'ok',true,'idempotent_replay',true,'decision','cancel',
        'draft_id',v_draft.id,'draft_code',substr(v_draft.id::text,1,12),
        'status','rejected','canonical_commit',false
      );
    end if;

    if v_draft.status in ('confirmed','committed') then
      raise exception 'confirmed_draft_cannot_be_cancelled_here';
    end if;

    update public.data_intake_drafts
    set status='rejected',
        rejected_by=v_line.user_id,
        rejected_at=now(),
        rejection_reason='line_user_cancelled',
        updated_at=now(),
        final_record_id=null,
        commit_result=coalesce(commit_result,'{}'::jsonb)
          || jsonb_build_object('canonical_commit',false,'decision','cancelled')
    where id=v_draft.id;

    return jsonb_build_object(
      'ok',true,'idempotent_replay',false,'decision','cancel',
      'draft_id',v_draft.id,'draft_code',substr(v_draft.id::text,1,12),
      'status','rejected','canonical_commit',false
    );
  end if;

  if v_draft.status='confirmed' then
    return jsonb_build_object(
      'ok',true,'idempotent_replay',true,'decision','confirm',
      'draft_id',v_draft.id,'draft_code',substr(v_draft.id::text,1,12),
      'status','confirmed','person_id',v_draft.person_id,
      'target_resource',v_draft.target_resource,
      'canonical_commit',false
    );
  end if;

  if v_draft.status not in ('draft','review','pending') then
    raise exception 'draft_not_confirmable';
  end if;

  if v_draft.person_id is null then
    raise exception 'person_required';
  end if;

  if jsonb_array_length(coalesce(v_draft.validation_data->'blocking_errors','[]'::jsonb))>0 then
    raise exception 'draft_validation_failed';
  end if;

  if jsonb_array_length(coalesce(v_draft.conflict_data->'blocking_conflicts','[]'::jsonb))>0 then
    raise exception 'draft_conflict_blocked';
  end if;

  update public.data_intake_drafts
  set status='confirmed',
      confirmed_by=v_line.user_id,
      confirmed_at=now(),
      updated_at=now(),
      final_record_id=null,
      committed_at=null,
      commit_result=coalesce(commit_result,'{}'::jsonb)
        || jsonb_build_object(
             'canonical_commit',false,
             'confirmed_draft_only',true,
             'next_stage','12J'
           )
  where id=v_draft.id;

  return jsonb_build_object(
    'ok',true,'idempotent_replay',false,'decision','confirm',
    'draft_id',v_draft.id,'draft_code',substr(v_draft.id::text,1,12),
    'status','confirmed','person_id',v_draft.person_id,
    'target_resource',v_draft.target_resource,
    'canonical_commit',false,
    'next_stage','12J'
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_finish_line_family_setup(p_line_user_id text, p_family_id uuid)
 RETURNS TABLE(family_id uuid, family_name text, selection_code text, person_count bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare v_line public.line_identities%rowtype; v_family public.families%rowtype; v_code text; v_count bigint;
begin
 select * into v_line from public.line_identities where line_user_id=p_line_user_id and is_active=true limit 1;
 if not found or v_line.user_id is null then raise exception 'linked_line_required'; end if;
 select f.* into v_family from public.families f join public.family_memberships fm on fm.family_id=f.id where f.id=p_family_id and fm.user_id=v_line.user_id and fm.status='active' and coalesce(f.status,'active')='active' limit 1;
 if not found then raise exception 'family_not_accessible'; end if;
 v_code:=substr(encode(digest(v_family.id::text||':'||v_line.id::text,'sha256'),'hex'),1,12);
 perform public.phms_select_line_context_family(p_line_user_id,v_code);
 perform public.phms_complete_line_onboarding_if_ready(p_line_user_id);
 select count(*) into v_count from public.family_persons fp join public.persons p on p.id=fp.person_id where fp.family_id=v_family.id and coalesce(fp.status,'active')='active' and coalesce(p.status,'active')='active';
 return query select v_family.id,v_family.family_name,v_code,v_count;
end;$function$

CREATE OR REPLACE FUNCTION public.phms_finish_line_link_without_person(p_line_user_id text, p_auth_user_id uuid, p_display_name text DEFAULT NULL::text, p_picture_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line_id uuid;
  v_account_id uuid;
  v_primary_user_id uuid;
begin
  if p_line_user_id is null or p_auth_user_id is null then
    raise exception 'missing_identity';
  end if;

  v_account_id := private.phms_ensure_account_for_user(p_auth_user_id, 'system_anchor');

  select a.primary_auth_user_id
  into v_primary_user_id
  from public.accounts a
  where a.id = v_account_id;

  insert into public.line_login_accounts(
    line_user_id,auth_user_id,account_id,display_name,picture_url
  )
  values(
    p_line_user_id,v_primary_user_id,v_account_id,p_display_name,p_picture_url
  )
  on conflict(line_user_id) do update
  set auth_user_id=excluded.auth_user_id,
      account_id=excluded.account_id,
      display_name=coalesce(excluded.display_name,public.line_login_accounts.display_name),
      picture_url=coalesce(excluded.picture_url,public.line_login_accounts.picture_url),
      updated_at=now();

  update public.line_identities
  set account_id=v_account_id,
      user_id=v_primary_user_id,
      display_name=coalesce(p_display_name,display_name),
      picture_url=coalesce(p_picture_url,picture_url),
      linking_completed_at=now(),
      onboarding_started_at=coalesce(onboarding_started_at,now()),
      onboarding_status='ready',
      onboarding_completed_at=coalesce(onboarding_completed_at,now()),
      is_active=true,
      updated_at=now()
  where line_user_id=p_line_user_id
  returning id into v_line_id;

  if v_line_id is null then
    raise exception 'line_identity_not_found';
  end if;

  insert into public.user_contexts(user_id,active_scope)
  values(v_primary_user_id,'personal')
  on conflict(user_id) do nothing;

  perform private.ensure_line_identity_context(v_line_id,v_primary_user_id);

  return jsonb_build_object(
    'ok',true,
    'account_id',v_account_id,
    'user_id',v_primary_user_id,
    'line_identity_id',v_line_id
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_finish_line_notification(p_notification_id uuid, p_lock_token uuid, p_success boolean, p_error text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v public.notifications%rowtype;
  v_retry_at timestamptz;
  v_final_status text;
begin
  select * into v
  from public.notifications
  where id=p_notification_id
    and lock_token=p_lock_token
    and status='sending'
  for update;

  if not found then raise exception 'notification_claim_not_found'; end if;

  if coalesce(p_success,false) then
    update public.notifications
    set status='sent',sent_at=now(),next_attempt_at=null,
        locked_at=null,lock_token=null,last_error=null,updated_at=now()
    where id=v.id;

    if v.event_type in ('appointment_reminder','appointment_post_visit') then
      update public.appointment_reminders
      set status='sent',sent_at=now(),updated_at=now()
      where id=private.phms_try_uuid(v.payload->>'appointment_reminder_id');
    end if;

    return jsonb_build_object(
      'ok',true,'status','sent','notification_id',v.id,'attempt_count',v.attempt_count
    );
  end if;

  if v.attempt_count>=v.max_attempts then
    v_final_status:='failed';
    v_retry_at:=null;
  else
    v_final_status:='pending';
    v_retry_at:=now()+case
      when v.attempt_count<=1 then interval '5 minutes'
      when v.attempt_count=2 then interval '15 minutes'
      else interval '30 minutes'
    end;
  end if;

  update public.notifications
  set status=v_final_status,next_attempt_at=v_retry_at,
      locked_at=null,lock_token=null,
      last_error=left(coalesce(p_error,'line_delivery_failed'),1000),
      updated_at=now()
  where id=v.id;

  if v.event_type in ('appointment_reminder','appointment_post_visit')
     and v_final_status='failed' then
    update public.appointment_reminders
    set status='failed',updated_at=now()
    where id=private.phms_try_uuid(v.payload->>'appointment_reminder_id');
  end if;

  return jsonb_build_object(
    'ok',true,'status',v_final_status,'notification_id',v.id,
    'attempt_count',v.attempt_count,'next_attempt_at',v_retry_at
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_format_birth_info(p_date_of_birth text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare v_date date; v_age int; v_day text;
begin
  if nullif(btrim(coalesce(p_date_of_birth,'')),'') is null then return jsonb_build_object('date',null,'age',null,'weekday_th',null); end if;
  v_date:=private.normalize_phms_date(p_date_of_birth);
  v_age:=extract(year from age(current_date,v_date))::int;
  v_day:=case extract(isodow from v_date)::int when 1 then 'วันจันทร์' when 2 then 'วันอังคาร' when 3 then 'วันพุธ' when 4 then 'วันพฤหัสบดี' when 5 then 'วันศุกร์' when 6 then 'วันเสาร์' when 7 then 'วันอาทิตย์' end;
  return jsonb_build_object('date',to_char(v_date,'YYYY-MM-DD'),'age',v_age,'weekday_th',v_day);
end $function$

CREATE OR REPLACE FUNCTION public.phms_get_line_active_data_target(p_line_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
 v_line record; v_ctx private.line_identity_contexts%rowtype; v_person_id uuid; v_family_person_id uuid; v_family_id uuid;
 v_person_name text; v_target_label text; v_family_name text; v_code text;
begin
 select li.id as line_identity_id,li.user_id into v_line
 from public.line_identities li
 where li.line_user_id=p_line_user_id and li.is_active=true and li.user_id is not null
 order by li.updated_at desc nulls last,li.created_at desc limit 1;
 if not found then return jsonb_build_object('ok',false,'code','line_not_linked','target_ready',false); end if;

 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select c.* into v_ctx from private.line_identity_contexts c where c.line_identity_id=v_line.line_identity_id;

 if coalesce(v_ctx.active_scope,'personal')='personal' then
  select p.id,coalesce(nullif(btrim(p.nickname),''),nullif(btrim(concat_ws(' ',p.first_name,p.last_name)),''),'ฉัน')
  into v_person_id,v_person_name
  from public.persons p
  where p.linked_user_id=v_line.user_id and p.status='active'
  order by p.created_at limit 1;
  if v_person_id is null then
    return jsonb_build_object('ok',true,'code','personal_person_missing','scope','personal','target_ready',false,'target_type','person');
  end if;
  return jsonb_build_object(
    'ok',true,'code','ready','scope','personal','target_ready',true,'target_type','person',
    'person_id',v_person_id,'family_id',null,'family_person_id',null,'family_name',null,
    'target_label','ฉัน','canonical_name',v_person_name,'selection_disclosure','กำลังดูข้อมูลของ: ฉัน'
  );
 end if;

 v_family_id:=v_ctx.active_family_id;
 v_family_person_id:=v_ctx.active_family_person_id;
 if v_family_id is null then
   return jsonb_build_object('ok',true,'code','family_selection_required','scope','family','target_ready',false,'target_type','family_person');
 end if;
 if not exists(select 1 from public.family_memberships fm
               where fm.family_id=v_family_id and fm.user_id=v_line.user_id and fm.status='active') then
  return jsonb_build_object('ok',true,'code','family_access_lost','scope','family','target_ready',false,'target_type','family_person');
 end if;

 select f.family_name into v_family_name from public.families f
 where f.id=v_family_id and f.status='active';
 if v_family_name is null then
   return jsonb_build_object('ok',true,'code','family_unavailable','scope','family','target_ready',false,'target_type','family_person');
 end if;
 if v_family_person_id is null then
   return jsonb_build_object('ok',true,'code','person_selection_required','scope','family','target_ready',false,'target_type','family_person','family_id',v_family_id,'family_name',v_family_name);
 end if;
 if not private.user_can_see_family_person(v_line.user_id,v_family_person_id) then
   return jsonb_build_object('ok',true,'code','person_access_denied','scope','family','target_ready',false,'target_type','family_person','family_id',v_family_id,'family_name',v_family_name);
 end if;

 select fp.person_id,
        private.family_person_label_for_viewer(v_line.user_id,fp.id),
        coalesce(nullif(btrim(p.nickname),''),nullif(btrim(concat_ws(' ',p.first_name,p.last_name)),''),'บุคคลในครอบครัว')
 into v_person_id,v_target_label,v_person_name
 from public.family_persons fp
 join public.persons p on p.id=fp.person_id and p.status='active'
 where fp.id=v_family_person_id and fp.family_id=v_family_id and fp.status='active';

 if v_person_id is null then
   return jsonb_build_object('ok',true,'code','person_unavailable','scope','family','target_ready',false,'target_type','family_person','family_id',v_family_id,'family_name',v_family_name);
 end if;

 v_code:=substr(encode(extensions.digest(v_family_person_id::text||':'||v_line.line_identity_id::text,'sha256'),'hex'),1,12);
 return jsonb_build_object(
   'ok',true,'code','ready','scope','family','target_ready',true,'target_type','family_person',
   'person_id',v_person_id,'family_id',v_family_id,'family_person_id',v_family_person_id,
   'family_name',v_family_name,'target_label',v_target_label,'canonical_name',v_person_name,
   'selection_code',v_code,'selection_disclosure',format('กำลังดูข้อมูลของ: %s',v_target_label)
 );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_get_line_active_family_person_label_state(p_line_user_id text)
 RETURNS TABLE(line_identity_id uuid, user_id uuid, family_id uuid, family_name text, family_person_id uuid, person_id uuid, canonical_person_name text, relationship_label text, display_label text, resolved_label text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line public.line_identities%rowtype;
  v_ctx private.line_identity_contexts%rowtype;
  v_fp public.family_persons%rowtype;
  v_person public.persons%rowtype;
  v_family public.families%rowtype;
  v_label public.family_person_view_labels%rowtype;
begin
  if p_line_user_id is null or btrim(p_line_user_id)='' then raise exception 'line_user_id_required'; end if;

  select li.* into v_line
  from public.line_identities li
  where li.line_user_id=p_line_user_id
  limit 1;
  if not found then raise exception 'line_identity_not_found'; end if;
  if coalesce(v_line.is_active,false) is not true then raise exception 'active_line_identity_required'; end if;
  if v_line.user_id is null then raise exception 'line_identity_not_linked'; end if;

  perform private.ensure_line_identity_context(v_line.id,v_line.user_id);
  select c.* into v_ctx from private.line_identity_contexts c where c.line_identity_id=v_line.id;
  if not found or v_ctx.active_scope<>'family' or v_ctx.active_family_id is null then
    raise exception 'family_context_required';
  end if;
  if v_ctx.active_family_person_id is null then raise exception 'family_person_context_required'; end if;

  if not exists(
    select 1 from public.family_memberships fm
    where fm.user_id=v_line.user_id and fm.family_id=v_ctx.active_family_id and fm.status='active'
  ) then raise exception 'family_context_not_accessible'; end if;

  select fp.* into v_fp
  from public.family_persons fp
  where fp.id=v_ctx.active_family_person_id
    and fp.family_id=v_ctx.active_family_id
    and coalesce(fp.status,'active')='active';
  if not found then raise exception 'family_person_not_accessible'; end if;

  select p.* into v_person from public.persons p
  where p.id=v_fp.person_id and coalesce(p.status,'active')='active';
  if not found then raise exception 'person_inactive_or_missing'; end if;

  select f.* into v_family from public.families f
  where f.id=v_ctx.active_family_id and coalesce(f.status,'active')='active';
  if not found then raise exception 'family_inactive_or_missing'; end if;

  select x.* into v_label
  from public.family_person_view_labels x
  where x.viewer_user_id=v_line.user_id and x.family_person_id=v_fp.id;

  return query select
    v_line.id,
    v_line.user_id,
    v_family.id,
    v_family.family_name,
    v_fp.id,
    v_person.id,
    coalesce(nullif(btrim(v_person.nickname),''),nullif(btrim(concat_ws(' ',v_person.first_name,v_person.last_name)),''),'ไม่ระบุชื่อ'),
    v_label.relationship_label,
    v_label.display_label,
    private.family_person_label_for_viewer(v_line.user_id,v_fp.id);
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_get_line_active_person_notification_preference(p_line_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_ctx private.line_identity_contexts%rowtype;
  v_fp public.family_persons%rowtype;
  v_result jsonb:='{}'::jsonb;
  v_res record;
  v_any boolean:=false;
  v_all boolean:=true;
begin
  select * into v_line
  from private.resolve_line_user_for_service(p_line_user_id);

  perform private.ensure_line_identity_context(
    v_line.line_identity_id,v_line.user_id
  );

  select * into v_ctx
  from private.line_identity_contexts
  where line_identity_id=v_line.line_identity_id;

  if v_ctx.active_scope<>'family'
     or v_ctx.active_family_person_id is null then
    raise exception 'family_person_context_required';
  end if;

  select * into v_fp
  from public.family_persons
  where id=v_ctx.active_family_person_id
    and family_id=v_ctx.active_family_id
    and coalesce(status,'active')='active';

  for v_res in
    select * from (values
      ('medications'::text,1),
      ('appointments'::text,2),
      ('health_data'::text,3)
    ) x(resource,ord)
  loop
    if private.user_can_access_family_person(
      v_line.user_id,v_fp.id,v_res.resource,'view'
    ) then
      v_any:=true;
      if not private.person_notification_enabled(
        v_line.user_id,v_fp.id,v_res.resource
      ) then
        v_all:=false;
      end if;
      v_result:=v_result || jsonb_build_object(
        v_res.resource,
        private.person_notification_enabled(
          v_line.user_id,v_fp.id,v_res.resource
        )
      );
    else
      v_result:=v_result || jsonb_build_object(
        v_res.resource,null
      );
    end if;
  end loop;

  return jsonb_build_object(
    'any_access',v_any,
    'all_enabled',case when v_any then v_all else false end,
    'resources',v_result
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_get_line_active_person_profile(p_line_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_line public.line_identities%rowtype; v_ctx private.line_identity_contexts%rowtype;
 v_fp public.family_persons%rowtype; v_p public.persons%rowtype;
 v_can_edit boolean:=false; v_birth jsonb:='{}'::jsonb; v_view_relationship text;
 v_med_view boolean:=false; v_med_create boolean:=false; v_med_update boolean:=false; v_med_delete boolean:=false;
 v_appt_view boolean:=false; v_appt_create boolean:=false; v_appt_update boolean:=false; v_appt_delete boolean:=false;
 v_health_view boolean:=false; v_health_create boolean:=false; v_health_update boolean:=false; v_health_delete boolean:=false;
 v_is_self boolean:=false;
begin
 select * into v_line from public.line_identities li
 where li.line_user_id=p_line_user_id and li.is_active=true and li.user_id is not null
 order by li.updated_at desc nulls last,li.created_at desc limit 1;
 if not found then raise exception 'line_identity_not_ready'; end if;

 perform private.ensure_line_identity_context(v_line.id,v_line.user_id);
 select c.* into v_ctx from private.line_identity_contexts c where c.line_identity_id=v_line.id;
 if v_ctx.active_scope<>'family' or v_ctx.active_family_id is null or v_ctx.active_family_person_id is null then
   raise exception 'family_person_context_required';
 end if;

 select fp.* into v_fp
 from public.family_persons fp
 where fp.id=v_ctx.active_family_person_id and fp.family_id=v_ctx.active_family_id
   and coalesce(fp.status,'active')='active';
 if not found then raise exception 'family_person_not_accessible'; end if;

 if not exists(select 1 from public.family_memberships fm
               where fm.family_id=v_fp.family_id and fm.user_id=v_line.user_id and fm.status='active')
 then raise exception 'family_person_not_accessible'; end if;

 select p.* into v_p from public.persons p
 where p.id=v_fp.person_id and coalesce(p.status,'active')='active';
 if not found then raise exception 'person_not_found'; end if;

 v_is_self:=v_p.linked_user_id=v_line.user_id;

 if not private.user_can_access_family_person(v_line.user_id,v_fp.id,'persons','view') then
   raise exception 'person_view_denied';
 end if;

 perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
 v_can_edit:=private.can_access_family_person(v_fp.id,'persons','update');

 if private.user_can_see_family_person(v_line.user_id,v_fp.id) then
   v_med_view:=private.can_access_family_person(v_fp.id,'medications','view');
   v_med_create:=private.can_access_family_person(v_fp.id,'medications','create');
   v_med_update:=private.can_access_family_person(v_fp.id,'medications','update');
   v_med_delete:=private.can_access_family_person(v_fp.id,'medications','delete');
   v_appt_view:=private.can_access_family_person(v_fp.id,'appointments','view');
   v_appt_create:=private.can_access_family_person(v_fp.id,'appointments','create');
   v_appt_update:=private.can_access_family_person(v_fp.id,'appointments','update');
   v_appt_delete:=private.can_access_family_person(v_fp.id,'appointments','delete');
   v_health_view:=private.can_access_family_person(v_fp.id,'health_data','view');
   v_health_create:=private.can_access_family_person(v_fp.id,'health_data','create');
   v_health_update:=private.can_access_family_person(v_fp.id,'health_data','update');
   v_health_delete:=private.can_access_family_person(v_fp.id,'health_data','delete');
 end if;

 begin v_birth:=public.phms_format_birth_info(v_p.date_of_birth);
 exception when others then v_birth:=jsonb_build_object('date',v_p.date_of_birth,'age',null,'weekday_th',null); end;

 if v_is_self then
   v_view_relationship:='ฉัน';
 else
   select nullif(btrim(x.relationship_label),'') into v_view_relationship
   from public.family_person_view_labels x
   where x.viewer_user_id=v_line.user_id and x.family_person_id=v_fp.id;
 end if;

 return jsonb_build_object(
  'person_id',v_p.id,'family_person_id',v_fp.id,
  'person_code',substr(encode(digest(v_fp.id::text||':'||v_line.id::text,'sha256'),'hex'),1,12),
  'setup_status',v_fp.setup_status,
  'can_manage_setup',private.can_manage_family_person_setup(v_line.user_id,v_fp.id),
  'display_name',private.family_person_label_for_viewer(v_line.user_id,v_fp.id),
  'nickname',v_p.nickname,
  'first_name',v_p.first_name,'last_name',v_p.last_name,
  'date_of_birth',v_p.date_of_birth,'birth_info',v_birth,'sex',v_p.sex,
  'relationship_label',v_view_relationship,
  'primary_caregiver_name',(
    select coalesce(nullif(btrim(cp.nickname),''),nullif(btrim(cp.display_name),''),nullif(btrim(concat_ws(' ',cp.first_name,cp.last_name)),''))
    from private.medical_primary_responsibilities mr
    join public.persons cp on cp.linked_user_id=mr.primary_user_id and coalesce(cp.status,'active')='active'
    join public.family_persons cfp on cfp.person_id=cp.id and cfp.family_id=v_fp.family_id and cfp.status='active'
    where mr.family_person_id=v_fp.id and mr.family_id=v_fp.family_id and mr.state='active'
      and exists(select 1 from public.family_memberships fm where fm.family_id=v_fp.family_id and fm.user_id=mr.primary_user_id and fm.status='active')
    order by mr.updated_at desc nulls last limit 1
  ),
  'account_linked',v_p.linked_user_id is not null,'is_self',v_is_self,'can_edit',v_can_edit,
  'access',jsonb_build_object(
    'medications',jsonb_build_object('view',v_med_view,'create',v_med_create,'update',v_med_update,'delete',v_med_delete),
    'appointments',jsonb_build_object('view',v_appt_view,'create',v_appt_create,'update',v_appt_update,'delete',v_appt_delete),
    'health_data',jsonb_build_object('view',v_health_view,'create',v_health_create,'update',v_health_update,'delete',v_health_delete)
  )
 );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_get_line_active_person_subject_access(p_line_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_line record; v_ctx private.line_identity_contexts%rowtype; v_fp public.family_persons%rowtype; v_p public.persons%rowtype;
 v_target uuid; v_roles jsonb:='[]'::jsonb; v_perms jsonb:='[]'::jsonb; v_member_code text; v_name text;
 v_actor_owner boolean:=false; v_actor_admin boolean:=false; v_actor_manage boolean:=false; v_self_cfg jsonb:='{}'::jsonb; v_is_self_caregiver boolean:=false;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select c.* into v_ctx from private.line_identity_contexts c where c.line_identity_id=v_line.line_identity_id;
 if not found or v_ctx.active_scope<>'family' or v_ctx.active_family_id is null or v_ctx.active_family_person_id is null
 then raise exception 'active_family_person_required'; end if;

 select * into v_fp from public.family_persons fp
 where fp.id=v_ctx.active_family_person_id and fp.family_id=v_ctx.active_family_id and coalesce(fp.status,'active')='active';
 if not found then raise exception 'active_family_person_not_found'; end if;

 if not private.user_can_see_family_person(v_line.user_id,v_fp.id) then raise exception 'person_view_denied'; end if;
 select * into v_p from public.persons p where p.id=v_fp.person_id and coalesce(p.status,'active')='active';
 if not found then raise exception 'active_person_not_found'; end if;

 v_target:=v_p.linked_user_id;
 v_actor_owner:=private.user_has_family_role(v_line.user_id,v_fp.family_id,array['owner']);
 v_actor_admin:=private.user_has_family_role(v_line.user_id,v_fp.family_id,array['admin']);
 perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
 v_actor_manage:=private.can_manage_permissions(v_fp.family_id);

 if v_target is null then
   return jsonb_build_object(
     'account_linked',false,'person_name',private.family_person_label_for_viewer(v_line.user_id,v_fp.id),
     'actor_is_owner',v_actor_owner,'actor_can_manage_roles',v_actor_owner or v_actor_admin,
     'actor_can_manage_permissions',v_actor_manage
   );
 end if;

 v_member_code:=substr(encode(digest(v_target::text||':'||v_line.line_identity_id::text||':'||v_fp.family_id::text,'sha256'),'hex'),1,12);
 v_name:=private.family_user_label_for_viewer(v_line.user_id,v_fp.family_id,v_target);

 select coalesce(jsonb_agg(r.role order by r.role),'[]'::jsonb) into v_roles
 from public.family_role_assignments r
 where r.family_id=v_fp.family_id and r.user_id=v_target and r.status='active';

 select jsonb_build_object(
   'profile',jsonb_build_object('view',s.can_view_profile,'update',s.can_update_profile),
   'medications',jsonb_build_object('view',s.can_view_medications,'create',s.can_create_medications,'update',s.can_update_medications,'delete',s.can_delete_medications),
   'appointments',jsonb_build_object('view',s.can_view_appointments,'create',s.can_create_appointments,'update',s.can_update_appointments,'delete',s.can_delete_appointments),
   'health_data',jsonb_build_object('view',s.can_view_health,'create',s.can_create_health,'update',s.can_update_health,'delete',s.can_delete_health)
 ) into v_self_cfg
 from public.person_self_access s where s.family_person_id=v_fp.id;

 v_is_self_caregiver:=exists(select 1 from public.person_caregiver_assignments ca
   where ca.family_person_id=v_fp.id and ca.caregiver_user_id=v_target and ca.status='active');

 select jsonb_agg(jsonb_build_object(
   'resource',r.resource,
   'view',private.user_can_access_family_person(v_target,v_fp.id,r.resource,'view'),
   'create',private.user_can_access_family_person(v_target,v_fp.id,r.resource,'create'),
   'update',private.user_can_access_family_person(v_target,v_fp.id,r.resource,'update'),
   'delete',private.user_can_access_family_person(v_target,v_fp.id,r.resource,'delete'),
   'receive_notifications',private.user_can_access_family_person(v_target,v_fp.id,r.resource,'receive_notifications')
 ) order by r.ord)
 into v_perms
 from (values ('medications'::text,1),('appointments'::text,2),('health_data'::text,3)) r(resource,ord);

 return jsonb_build_object(
   'account_linked',true,'member_code',v_member_code,'display_name',v_name,'roles',v_roles,
   'is_owner',private.user_has_family_role(v_target,v_fp.family_id,array['owner']),
   'is_self_caregiver',v_is_self_caregiver,'self_access',coalesce(v_self_cfg,'{}'::jsonb),
   'permissions',coalesce(v_perms,'[]'::jsonb),
   'actor_is_owner',v_actor_owner,'actor_can_manage_roles',v_actor_owner or v_actor_admin,
   'actor_can_manage_permissions',v_actor_manage
 );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_get_line_actor_label(p_line_user_id text, p_resource text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_ctx record;
  v_family_id uuid;
  v_label text;
begin
  select * into v_line
  from private.resolve_line_user_for_service(p_line_user_id);

  if nullif(btrim(coalesce(p_resource,'')),'') is not null then
    begin
      select * into v_ctx
      from private.phms_line_crud_context(p_line_user_id,p_resource,'view')
      limit 1;
      v_family_id:=v_ctx.active_family_id;
    exception when others then
      v_family_id:=null;
    end;
  end if;

  if v_family_id is null then
    begin
      perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
      select c.active_family_id into v_family_id
      from private.line_identity_contexts c
      where c.line_identity_id=v_line.line_identity_id;
    exception when others then
      v_family_id:=null;
    end;
  end if;

  if v_family_id is null then
    select fm.family_id into v_family_id
    from public.family_memberships fm
    where fm.user_id=v_line.user_id and fm.status='active'
    order by fm.joined_at,fm.created_at
    limit 1;
  end if;

  if v_family_id is not null then
    v_label:=private.family_user_label_for_viewer(
      v_line.user_id,v_family_id,v_line.user_id
    );
  end if;

  if nullif(btrim(coalesce(v_label,'')),'') is null then
    select coalesce(
      nullif(btrim(p.nickname),''),
      nullif(btrim(concat_ws(' ',p.first_name,p.last_name)),'')
    )
    into v_label
    from public.persons p
    where p.linked_user_id=v_line.user_id
      and coalesce(p.status,'active')='active'
    order by p.created_at
    limit 1;
  end if;

  if nullif(btrim(coalesce(v_label,'')),'') is null then
    select coalesce(
      nullif(btrim(pr.display_name),''),
      nullif(btrim(li.display_name),''),
      'ฉัน'
    )
    into v_label
    from public.line_identities li
    left join public.profiles pr on pr.id=v_line.user_id
    where li.id=v_line.line_identity_id;
  end if;

  return jsonb_build_object(
    'user_id',v_line.user_id,
    'family_id',v_family_id,
    'display_name',coalesce(nullif(btrim(v_label),''),'ฉัน')
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_get_line_family_member_detail(p_line_user_id text, p_member_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v record; v_name text; v_roles text[];
  v_family_permissions jsonb; v_person_permissions jsonb;
  v_target_manage boolean; v_target_owner boolean;
  v_actor_owner boolean; v_actor_manage boolean; v_line_count integer;
begin
  select * into v from private.resolve_line_family_member(p_line_user_id,p_member_code);
  perform set_config('request.jwt.claim.sub',v.actor_user_id::text,true);
  if not private.user_has_family_role(v.actor_user_id,v.family_id,array['owner','admin']) then
    return jsonb_build_object('member_code',lower(btrim(p_member_code)),'display_name',private.family_user_label_for_viewer(v.actor_user_id,v.family_id,v.target_user_id),'is_self',v.target_user_id=v.actor_user_id,'can_manage_permissions',false);
  end if;
  v_name:=private.family_user_label_for_viewer(v.actor_user_id,v.family_id,v.target_user_id);

  select coalesce(array_agg(distinct fra.role order by fra.role),array[]::text[])
  into v_roles
  from public.family_role_assignments fra
  where fra.family_id=v.family_id and fra.user_id=v.target_user_id and fra.status='active';

  select coalesce(jsonb_agg(jsonb_build_object(
    'resource',x.resource,'view',coalesce(x.can_view,false),'create',coalesce(x.can_create,false),
    'update',coalesce(x.can_update,false),'delete',coalesce(x.can_delete,false),
    'manage_permissions',coalesce(x.can_manage_permissions,false)
  ) order by x.resource),'[]'::jsonb)
  into v_family_permissions
  from public.family_permissions x
  where x.family_id=v.family_id and x.user_id=v.target_user_id;

  select coalesce(jsonb_agg(row_to_json(z) order by z.person_name,z.resource),'[]'::jsonb)
  into v_person_permissions
  from (
    select pp.family_person_id,
      private.family_person_label_for_viewer(v.actor_user_id,pp.family_person_id) person_name,
      pp.resource,
      coalesce(pp.can_view,false) as can_view,
      coalesce(pp.can_create,false) as can_create,
      coalesce(pp.can_update,false) as can_update,
      coalesce(pp.can_delete,false) as can_delete,
      coalesce(pp.can_receive_notifications,false) as receive_notifications
    from public.person_permissions pp
    where pp.family_id=v.family_id and pp.user_id=v.target_user_id and pp.status='active'
      and (coalesce(pp.can_view,false) or coalesce(pp.can_create,false) or
           coalesce(pp.can_update,false) or coalesce(pp.can_delete,false) or
           coalesce(pp.can_receive_notifications,false))
  ) z;

  select count(*)::int into v_line_count
  from public.line_identities li
  where li.user_id=v.target_user_id and coalesce(li.is_active,false)=true;

  v_target_owner:=private.user_has_family_role(v.target_user_id,v.family_id,array['owner']);
  v_target_manage:=v_target_owner
    or private.user_has_family_role(v.target_user_id,v.family_id,array['admin']);
  v_actor_owner:=private.is_family_owner(v.family_id);
  v_actor_manage:=private.can_manage_permissions(v.family_id);

  return jsonb_build_object(
    'member_code',lower(btrim(p_member_code)),
    'user_id',v.target_user_id,
    'display_name',v_name,
    'roles',to_jsonb(v_roles),
    'is_owner',v_target_owner,
    'can_manage_permissions',v_target_manage,
    'is_self',v.target_user_id=v.actor_user_id,
    'actor_is_owner',v_actor_owner,
    'actor_can_manage_permissions',v_actor_manage,
    'family_permissions',v_family_permissions,
    'person_permissions',v_person_permissions,
    'active_line_count',coalesce(v_line_count,0)
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_get_line_family_person_visibility(p_line_user_id text, p_person_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_person public.persons%rowtype;
  v_rows jsonb:='[]'::jsonb;
begin
  select * into v_ref
  from private.resolve_line_family_person_code(p_line_user_id,p_person_code)
  limit 1;

  if not private.can_manage_family_person_visibility(v_ref.actor_user_id,v_ref.family_person_id) then
    raise exception 'visibility_management_denied';
  end if;

  select p.* into v_person
  from public.family_persons fp
  join public.persons p on p.id=fp.person_id
  where fp.id=v_ref.family_person_id;

  select coalesce(jsonb_agg(jsonb_build_object(
    'member_code',substr(encode(digest(fm.user_id::text||':'||v_ref.line_identity_id::text||':'||v_ref.family_id::text,'sha256'),'hex'),1,12),
    'user_id',fm.user_id,
    'display_name',private.family_user_label_for_viewer(v_ref.actor_user_id,v_ref.family_id,fm.user_id),
    'is_self_person',v_person.linked_user_id=fm.user_id,
    'visible',case
      when v_person.linked_user_id=fm.user_id then true
      else not exists(
        select 1 from private.family_person_visibility_overrides vo
        where vo.family_person_id=v_ref.family_person_id
          and vo.viewer_user_id=fm.user_id
          and vo.is_visible=false
      )
    end
  ) order by
    (v_person.linked_user_id=fm.user_id) desc,
    lower(private.family_user_label_for_viewer(v_ref.actor_user_id,v_ref.family_id,fm.user_id))
  ),'[]'::jsonb)
  into v_rows
  from public.family_memberships fm
  where fm.family_id=v_ref.family_id
    and fm.status='active';

  return jsonb_build_object(
    'person_code',lower(btrim(p_person_code)),
    'family_person_id',v_ref.family_person_id,
    'person_name',private.family_person_label_for_viewer(v_ref.actor_user_id,v_ref.family_person_id),
    'setup_status',(select fp.setup_status from public.family_persons fp where fp.id=v_ref.family_person_id),
    'members',v_rows
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_get_line_person_dashboard(p_line_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_line record; v_ctx private.line_identity_contexts%rowtype; v_fp public.family_persons%rowtype; v_p public.persons%rowtype;
 v_birth jsonb:='{}'::jsonb; v_access jsonb; v_self_access jsonb; v_roles jsonb:='[]'::jsonb;
 v_meds jsonb:='[]'::jsonb; v_appts jsonb:='[]'::jsonb; v_health jsonb:='[]'::jsonb;
 v_med_count int:=0; v_appt_count int:=0; v_health_count int:=0;
 v_photo_object text; v_photo_mime text; v_photo_shared boolean:=false;
 v_can_manage boolean:=false; v_is_owner boolean:=false; v_is_member boolean:=false; v_person_code text; v_is_self boolean:=false;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select c.* into v_ctx from private.line_identity_contexts c where c.line_identity_id=v_line.line_identity_id;
 if v_ctx.active_scope<>'family' or v_ctx.active_family_id is null or v_ctx.active_family_person_id is null then raise exception 'family_person_context_required'; end if;
 if not private.user_can_access_family_person(v_line.user_id,v_ctx.active_family_person_id,'persons','view') then raise exception 'person_view_denied'; end if;
 select fp.* into v_fp from public.family_persons fp where fp.id=v_ctx.active_family_person_id and fp.family_id=v_ctx.active_family_id and coalesce(fp.status,'active')='active';
 select p.* into v_p from public.persons p where p.id=v_fp.person_id and coalesce(p.status,'active')='active';
 if not found then raise exception 'person_not_found'; end if;
 perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
 v_is_self:=coalesce(v_p.linked_user_id=v_line.user_id,false);
 begin v_birth:=public.phms_format_birth_info(v_p.date_of_birth); exception when others then v_birth:=jsonb_build_object('date',v_p.date_of_birth,'age',null,'weekday_th',null); end;
 v_can_manage:=private.can_manage_permissions(v_fp.family_id);
 v_is_owner:=private.is_family_owner(v_fp.family_id);
 v_is_member:=private.is_active_family_member(v_fp.family_id);
 v_person_code:=substr(encode(digest(v_fp.id::text||':'||v_line.line_identity_id::text,'sha256'),'hex'),1,12);

 v_access:=jsonb_build_object(
   'profile',jsonb_build_object('view',private.can_access_family_person(v_fp.id,'persons','view'),'update',private.can_access_family_person(v_fp.id,'persons','update')),
   'medications',jsonb_build_object('view',private.can_access_family_person(v_fp.id,'medications','view'),'create',private.can_access_family_person(v_fp.id,'medications','create'),'update',private.can_access_family_person(v_fp.id,'medications','update'),'delete',private.can_access_family_person(v_fp.id,'medications','delete')),
   'appointments',jsonb_build_object('view',private.can_access_family_person(v_fp.id,'appointments','view'),'create',private.can_access_family_person(v_fp.id,'appointments','create'),'update',private.can_access_family_person(v_fp.id,'appointments','update'),'delete',private.can_access_family_person(v_fp.id,'appointments','delete')),
   'health_data',jsonb_build_object('view',private.can_access_family_person(v_fp.id,'health_data','view'),'create',private.can_access_family_person(v_fp.id,'health_data','create'),'update',private.can_access_family_person(v_fp.id,'health_data','update'),'delete',private.can_access_family_person(v_fp.id,'health_data','delete')),
   'documents',jsonb_build_object('view',private.user_can_access_family_person(v_line.user_id,v_fp.id,'documents','view'),'create',private.user_can_access_family_person(v_line.user_id,v_fp.id,'documents','create'),'update',private.user_can_access_family_person(v_line.user_id,v_fp.id,'documents','update'),'delete',private.user_can_access_family_person(v_line.user_id,v_fp.id,'documents','delete')),
   'expenses',jsonb_build_object('view',private.user_can_access_family_person(v_line.user_id,v_fp.id,'expenses','view'),'create',private.user_can_access_family_person(v_line.user_id,v_fp.id,'expenses','create'),'update',private.user_can_access_family_person(v_line.user_id,v_fp.id,'expenses','update'),'delete',private.user_can_access_family_person(v_line.user_id,v_fp.id,'expenses','delete')),
   'family',jsonb_build_object(
      'is_member',v_is_member,
      'is_owner',v_is_owner,
      'can_add_members',v_is_owner or v_can_manage,
      'can_manage_roles_permissions',v_is_owner or v_can_manage,
      'can_manage_caregivers',private.phms_can_manage_medical_grants(v_line.user_id,v_fp.id)
   ),
   'manage_permissions',private.can_manage_family_person_permissions(v_line.user_id,v_fp.id)
 );

 select jsonb_build_object(
   'profile',jsonb_build_object('view',s.can_view_profile,'update',s.can_update_profile),
   'medications',jsonb_build_object('view',s.can_view_medications,'create',s.can_create_medications,'update',s.can_update_medications,'delete',s.can_delete_medications),
   'appointments',jsonb_build_object('view',s.can_view_appointments,'create',s.can_create_appointments,'update',s.can_update_appointments,'delete',s.can_delete_appointments),
   'health_data',jsonb_build_object('view',s.can_view_health,'create',s.can_create_health,'update',s.can_update_health,'delete',s.can_delete_health),
   'documents',jsonb_build_object('view',s.can_view_documents,'create',s.can_create_documents,'update',s.can_update_documents,'delete',s.can_delete_documents),
   'expenses',jsonb_build_object('view',s.can_view_expenses,'create',s.can_create_expenses,'update',s.can_update_expenses,'delete',s.can_delete_expenses)
 ) into v_self_access
 from public.person_self_access s where s.family_person_id=v_fp.id;

 select coalesce(jsonb_agg(r.role order by r.role),'[]'::jsonb) into v_roles
 from public.family_role_assignments r where r.family_id=v_fp.family_id and r.user_id=v_line.user_id and r.status='active';

 if coalesce((v_access#>>'{medications,view}')::boolean,false) then
   select count(*)::int into v_med_count from public.person_medications pm where pm.person_id=v_p.id and pm.deleted_at is null;
   select coalesce(jsonb_agg(x.j order by x.sort_at desc),'[]'::jsonb) into v_meds from (
     select greatest(coalesce(pm.updated_at,pm.created_at),coalesce(mr.updated_at,mr.created_at,pm.updated_at,pm.created_at)) sort_at,jsonb_strip_nulls(jsonb_build_object('code',substr(pm.id::text,1,12),'name',coalesce(mm.brand_name,mm.generic_name),'generic_name',mm.generic_name,'status',pm.status,'updated_at',greatest(coalesce(pm.updated_at,pm.created_at),coalesce(mr.updated_at,mr.created_at,pm.updated_at,pm.created_at)),'dose_text',mr.dose_text,'instructions',mr.instructions,'meal_relation',mr.meal_relation)) j
     from public.person_medications pm join public.medication_master mm on mm.id=pm.medication_id
     left join lateral (select r.* from public.medication_regimens r where r.person_medication_id=pm.id and r.deleted_at is null and r.is_current=true order by r.effective_from desc,r.created_at desc limit 1) mr on true
     where pm.person_id=v_p.id and pm.deleted_at is null order by greatest(coalesce(pm.updated_at,pm.created_at),coalesce(mr.updated_at,mr.created_at,pm.updated_at,pm.created_at)) desc nulls last limit 3
   ) x;
 end if;

 if coalesce((v_access#>>'{appointments,view}')::boolean,false) then
   select count(*)::int into v_appt_count from public.appointments a where a.person_id=v_p.id and a.deleted_at is null and coalesce(a.status,'scheduled') not in ('cancelled','completed');
   select coalesce(jsonb_agg(x.j order by x.sort_at asc),'[]'::jsonb) into v_appts from (
     select coalesce(a.appointment_at,a.created_at) sort_at,jsonb_strip_nulls(jsonb_build_object('code',substr(a.id::text,1,12),'title',a.title,'appointment_at',a.appointment_at,'updated_at',coalesce(a.updated_at,a.created_at),'hospital_name',a.hospital_name,'hospital_display_name',private.phms_hospital_display_short(a.hospital_name),'department',a.department,'doctor_name',a.doctor_name,'status',a.status)) j
     from public.appointments a where a.person_id=v_p.id and a.deleted_at is null and coalesce(a.status,'scheduled') not in ('cancelled','completed') and (a.appointment_at is null or a.appointment_at>=now()-interval '1 day')
     order by a.appointment_at asc nulls last,a.created_at desc limit 3
   ) x;
 end if;

 if coalesce((v_access#>>'{health_data,view}')::boolean,false) then
   select count(*)::int into v_health_count from public.health_measurements h where h.person_id=v_p.id and h.deleted_at is null;
   select coalesce(jsonb_agg(x.j order by x.sort_at desc),'[]'::jsonb) into v_health from (
     select h.measured_at sort_at,jsonb_strip_nulls(jsonb_build_object('code',substr(h.id::text,1,12),'measurement_type',h.measurement_type,'measured_at',h.measured_at,'created_at',h.created_at,'value_numeric',h.value_numeric,'value_text',h.value_text,'unit',h.unit,'systolic',h.systolic,'diastolic',h.diastolic,'context',h.context)) j
     from public.health_measurements h where h.person_id=v_p.id and h.deleted_at is null order by h.measured_at desc,h.created_at desc limit 3
   ) x;
 end if;

 select ph.object_name,ph.mime_type,ph.visibility='shared' into v_photo_object,v_photo_mime,v_photo_shared
 from public.person_photo_preferences pref join public.person_photos ph on ph.id=pref.photo_id
 where pref.viewer_user_id=v_line.user_id and pref.family_person_id=v_fp.id and ph.status='active' and (ph.uploaded_by=v_line.user_id or ph.visibility='shared') limit 1;
 if v_photo_object is null then
   select ph.object_name,ph.mime_type,true into v_photo_object,v_photo_mime,v_photo_shared
   from public.person_photos ph where ph.family_person_id=v_fp.id and ph.status='active' and ph.visibility='shared' and ph.is_person_shared_default=true limit 1;
 end if;

 return jsonb_build_object(
   'family_id',v_fp.family_id,'family_person_id',v_fp.id,'person_id',v_p.id,'person_code',v_person_code,
   'display_name',private.family_person_label_for_viewer(v_line.user_id,v_fp.id),
   'canonical_name',coalesce(nullif(btrim(v_p.nickname),''),nullif(btrim(concat_ws(' ',v_p.first_name,v_p.last_name)),''),'บุคคล'),
   'nickname',v_p.nickname,'first_name',v_p.first_name,'last_name',v_p.last_name,'relationship_label',case when v_is_self then 'ฉัน' else (select nullif(btrim(x.relationship_label),'') from public.family_person_view_labels x where x.viewer_user_id=v_line.user_id and x.family_person_id=v_fp.id) end,
   'date_of_birth',v_p.date_of_birth,'birth_info',v_birth,'sex',v_p.sex,'is_self',v_is_self,'account_linked',v_p.linked_user_id is not null,
   'viewer_roles',v_roles,'access',v_access,'self_access',coalesce(v_self_access,'{}'::jsonb),
   'photo',case when v_photo_object is null then null else jsonb_build_object('bucket_id','phms-person-photos','object_name',v_photo_object,'mime_type',v_photo_mime,'shared',v_photo_shared) end,
   'summaries',jsonb_build_object('medications',jsonb_build_object('count',v_med_count,'items',v_meds,'updated_at',(select max(coalesce(pm.updated_at,pm.created_at)) from public.person_medications pm where pm.person_id=v_p.id and pm.deleted_at is null)),'appointments',jsonb_build_object('count',v_appt_count,'items',v_appts,'updated_at',(select max(coalesce(a.updated_at,a.created_at)) from public.appointments a where a.person_id=v_p.id and a.deleted_at is null and coalesce(a.status,'scheduled') not in ('cancelled','completed'))),'health_data',jsonb_build_object('count',v_health_count,'items',v_health,'updated_at',(select max(h.created_at) from public.health_measurements h where h.person_id=v_p.id and h.deleted_at is null)))
 );
end $function$

CREATE OR REPLACE FUNCTION public.phms_get_line_person_permission_detail(p_line_user_id text, p_member_code text, p_person_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_member record;
  v_person record;
  v_name text;
  v_perms jsonb;
  v_actor_admin boolean:=false;
begin
  select * into v_member
  from private.resolve_line_family_member(
    p_line_user_id,p_member_code
  );
  select * into v_person
  from private.resolve_line_family_person_code(
    p_line_user_id,p_person_code
  );
  if v_member.family_id<>v_person.family_id then
    raise exception 'family_scope_mismatch';
  end if;

  perform set_config(
    'request.jwt.claim.sub',
    v_member.actor_user_id::text,true
  );

  select private.family_person_label_for_viewer(
    v_member.actor_user_id,fp.id
  )
  into v_name
  from public.family_persons fp
  where fp.id=v_person.family_person_id;

  select jsonb_agg(
    jsonb_build_object(
      'resource',r.resource,
      'view',private.user_can_access_family_person(
        v_member.target_user_id,
        v_person.family_person_id,r.resource,'view'
      ),
      'create',private.user_can_access_family_person(
        v_member.target_user_id,
        v_person.family_person_id,r.resource,'create'
      ),
      'update',private.user_can_access_family_person(
        v_member.target_user_id,
        v_person.family_person_id,r.resource,'update'
      ),
      'delete',private.user_can_access_family_person(
        v_member.target_user_id,
        v_person.family_person_id,r.resource,'delete'
      ),
      'receive_notifications',
        private.person_notification_enabled(
          v_member.target_user_id,
          v_person.family_person_id,r.resource
        )
    )
    order by r.ord
  )
  into v_perms
  from (values
    ('persons'::text,1),
    ('appointments'::text,2),
    ('health_data'::text,3),
    ('medications'::text,4),
    ('emergency'::text,5), ('documents'::text,6), ('expenses'::text,7)
  ) r(resource,ord);

  v_actor_admin:=private.user_has_family_role(
    v_member.actor_user_id,v_member.family_id,array['admin']
  );

  return jsonb_build_object(
    'member_code',lower(btrim(p_member_code)),
    'person_code',lower(btrim(p_person_code)),
    'family_person_id',v_person.family_person_id,
    'person_name',coalesce(v_name,'บุคคลในครอบครัว'),
    'actor_is_owner',private.is_family_owner(v_member.family_id),
    'actor_is_admin',v_actor_admin,
    'actor_can_manage_permissions',
      private.phms_can_manage_medical_grants(v_member.actor_user_id,v_person.family_person_id),
    'permissions',coalesce(v_perms,'[]'::jsonb)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_get_line_self_profile_access(p_line_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare v_line record; v_p public.persons%rowtype; v_can boolean;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 select * into v_p from public.persons p where p.linked_user_id=v_line.user_id and coalesce(p.status,'active')='active' order by p.created_at limit 1;
 if not found then return jsonb_build_object('person_id',null,'can_update_profile',true); end if;
 v_can:=private.user_self_profile_update_allowed(v_line.user_id);
 return jsonb_build_object('person_id',v_p.id,'can_update_profile',v_can);
end $function$

CREATE OR REPLACE FUNCTION public.phms_get_main_context_contract()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid:=auth.uid(); v_scope text; v_family uuid; v_fp uuid; v_person uuid; v_label text; v_family_name text;
begin
 if v_uid is null then return jsonb_build_object('ok',false,'reason','unauthenticated'); end if;
 select active_scope,active_family_id,active_family_person_id into v_scope,v_family,v_fp from public.user_contexts where user_id=v_uid;
 if v_scope='family' and v_fp is not null then
  select fp.person_id, coalesce(nullif(vl.display_label,''),nullif(vl.relationship_label,''),nullif(fp.relationship_label,''),p.display_name,p.first_name), f.family_name into v_person,v_label,v_family_name from public.family_persons fp join public.persons p on p.id=fp.person_id join public.families f on f.id=fp.family_id left join public.family_person_view_labels vl on vl.family_person_id=fp.id and vl.viewer_user_id=v_uid where fp.id=v_fp;
 else
  select p.id,coalesce(p.display_name,p.first_name) into v_person,v_label from public.persons p where p.linked_user_id=v_uid and p.status='active' order by p.created_at limit 1; v_scope:='personal'; v_family:=null; v_fp:=null;
 end if;
 return jsonb_build_object('ok',v_person is not null,'scope',v_scope,'family_id',v_family,'family_name',v_family_name,'family_person_id',v_fp,'person_id',v_person,'display_label',v_label,'auto_selected',false,'modules',jsonb_build_array('health','medication','appointments','emergency','documents','expenses'));
end $function$

CREATE OR REPLACE FUNCTION public.phms_intake_session_can_commit(p_session_id uuid, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ds public.data_intake_sessions%rowtype;
  v_count integer;
  v_not_accepted integer;
  v_validation integer;
  v_conflicts integer;
  v_unsupported integer;
  v_resources text[];
  v_gate jsonb;
begin
  select * into v_ds
  from public.data_intake_sessions
  where id=p_session_id;

  if not found then
    return jsonb_build_object('allowed',false,'reason','session_not_found');
  end if;

  if p_actor_user_id is null or v_ds.submitted_by is distinct from p_actor_user_id then
    return jsonb_build_object('allowed',false,'reason','actor_not_session_submitter');
  end if;

  if v_ds.status='committed' then
    return jsonb_build_object('allowed',true,'reason','already_committed','status',v_ds.status);
  end if;

  if v_ds.status<>'confirmed' then
    return jsonb_build_object('allowed',false,'reason','confirmation_required','status',v_ds.status);
  end if;

  if v_ds.person_id is null then
    return jsonb_build_object('allowed',false,'reason','person_required');
  end if;

  select
    count(*),
    count(*) filter (where c.review_status<>'accepted'),
    count(*) filter (
      where jsonb_array_length(coalesce(c.validation_data->'blocking_errors','[]'::jsonb))>0
    ),
    count(*) filter (
      where jsonb_array_length(coalesce(c.conflict_data->'blocking_conflicts','[]'::jsonb))>0
    ),
    count(*) filter (
      where c.candidate_type not in ('medication','appointment','health_measurement','measurement')
    ),
    array_agg(distinct case
      when c.candidate_type='medication' then 'medication'
      when c.candidate_type='appointment' then 'appointment'
      when c.candidate_type in ('health_measurement','measurement') then 'health'
      else c.candidate_type
    end) filter(where c.review_status<>'rejected')
  into v_count,v_not_accepted,v_validation,v_conflicts,v_unsupported,v_resources
  from public.data_intake_candidates c
  where c.session_id=v_ds.id
    and c.review_status<>'rejected';

  if v_count=0 then
    return jsonb_build_object('allowed',false,'reason','candidate_required');
  end if;
  if v_not_accepted>0 then
    return jsonb_build_object('allowed',false,'reason','candidate_not_accepted','count',v_not_accepted);
  end if;
  if v_validation>0 then
    return jsonb_build_object('allowed',false,'reason','validation_blocked','count',v_validation);
  end if;
  if v_conflicts>0 then
    return jsonb_build_object('allowed',false,'reason','conflict_blocked','count',v_conflicts);
  end if;
  if v_unsupported>0 then
    return jsonb_build_object('allowed',false,'reason','unsupported_candidate_type','count',v_unsupported);
  end if;

  v_gate:=private.phms_real_data_gate_decision(
    v_ds.family_id,v_ds.person_id,v_resources,'commit',
    p_actor_user_id,v_count
  );

  if coalesce((v_gate->>'allowed')::boolean,false) is not true then
    return v_gate||jsonb_build_object(
      'allowed',false,
      'status',v_ds.status,
      'session_id',v_ds.id
    );
  end if;

  return v_gate||jsonb_build_object(
    'allowed',true,'reason','ok',
    'session_id',v_ds.id,
    'person_id',v_ds.person_id,
    'candidate_count',v_count
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_join_family_from_line(p_line_user_id text, p_family_code text)
 RETURNS TABLE(family_id uuid, family_name text, family_code text, already_member boolean, role text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_line record; v_code text:=upper(nullif(btrim(p_family_code),''));
 v_family public.families%rowtype; v_already boolean:=false;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 if v_code is null then raise exception 'family_code_required'; end if;

 select f.* into v_family
 from public.families f
 where upper(btrim(f.family_code))=v_code and coalesce(f.status,'active')='active'
 limit 1;
 if not found then raise exception 'family_code_not_found'; end if;

 select exists(
   select 1 from public.family_memberships fm
   where fm.family_id=v_family.id and fm.user_id=v_line.user_id and fm.status='active'
 ) into v_already;

 if not v_already then
   update public.family_memberships fm
   set status='active',joined_at=coalesce(fm.joined_at,now()),updated_at=now()
   where fm.family_id=v_family.id and fm.user_id=v_line.user_id and fm.status<>'active';
   if not found then
     insert into public.family_memberships(family_id,user_id,status,joined_at,created_at,updated_at)
     values(v_family.id,v_line.user_id,'active',now(),now(),now());
   end if;

   -- membership baseline ภายในระบบ
   insert into public.family_role_assignments(
     family_id,user_id,role,status,granted_by,granted_at,created_at,updated_at
   )
   values(v_family.id,v_line.user_id,'viewer','active',null,now(),now(),now())
   on conflict do nothing;

   insert into public.family_role_assignments(
     family_id,user_id,role,status,granted_by,granted_at,created_at,updated_at
   )
   values(v_family.id,v_line.user_id,'patient','active',v_line.user_id,now(),now(),now())
   on conflict do nothing;

   if coalesce(current_setting('phms.skip_join_notify',true),'')<>'on' then
     perform private.notify_family_managers_member_event(
       v_family.id,v_line.user_id,'family_member_joined',
       '👋 มีสมาชิกเข้าร่วมครอบครัว','เข้าร่วมด้วยรหัสครอบครัว',null
     );
   end if;
 end if;

 return query
 select v_family.id,v_family.family_name,v_family.family_code,v_already,
   case
     when private.user_has_family_role(v_line.user_id,v_family.id,array['owner']) then 'owner'
     when private.user_has_family_role(v_line.user_id,v_family.id,array['admin']) then 'admin'
     else 'viewer'
   end::text;
end
$function$

CREATE OR REPLACE FUNCTION public.phms_join_family_from_line_invite(p_line_user_id text, p_invite_token text)
 RETURNS TABLE(family_id uuid, family_name text, family_code text, already_member boolean, role text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_family uuid;
 v_hash text;
 v_line record;
 v_join record;
 v_applied jsonb;
 v_was_applied boolean:=false;
begin
 v_hash:=encode(digest(trim(p_invite_token),'sha256'),'hex');

 select l.family_id into v_family
 from public.family_invite_links l
 where l.token_hash=v_hash and l.status='active' and l.expires_at>now()
 limit 1;
 if v_family is null then raise exception 'invite_invalid_or_expired'; end if;

 update public.family_invite_links set last_used_at=now() where token_hash=v_hash;

 perform set_config('phms.skip_join_notify','on',true);

 select * into v_join
 from public.phms_join_family_from_line(
   p_line_user_id,
   (select f.family_code from public.families f where f.id=v_family)
 );

 v_applied:=public.phms_apply_line_family_invite_intent(p_line_user_id,p_invite_token);
 v_was_applied:=coalesce((v_applied->>'applied')::boolean,false);
 perform set_config('phms.skip_join_notify','off',true);

 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);

 if coalesce(v_join.already_member,false)=false or v_was_applied then
   perform private.notify_family_managers_member_event(
     v_family,
     v_line.user_id,
     case
       when coalesce(v_join.already_member,false)=false and v_was_applied then 'family_member_joined_with_role'
       when coalesce(v_join.already_member,false)=false then 'family_member_joined'
       else 'family_invite_role_accepted'
     end,
     case
       when coalesce(v_join.already_member,false)=false and v_was_applied then '👋 สมาชิกใหม่เข้าร่วมและรับบทบาทแล้ว'
       when coalesce(v_join.already_member,false)=false then '👋 มีสมาชิกเข้าร่วมครอบครัว'
       else '✅ สมาชิกตอบรับบทบาท/สิทธิ์แล้ว'
     end,
     case
       when v_was_applied then 'บทบาทและสิทธิ์จากคำเชิญถูกนำไปใช้เรียบร้อย'
       else 'เข้าร่วมครอบครัวเรียบร้อย'
     end,
     null
   );
 end if;

 return query
 select v_join.family_id,v_join.family_name,v_join.family_code,
        v_join.already_member,
        case
          when private.user_has_family_role(v_line.user_id,v_family,array['owner']) then 'owner'
          when private.user_has_family_role(v_line.user_id,v_family,array['admin']) then 'admin'
          when private.user_has_family_role(v_line.user_id,v_family,array['caregiver']) then 'caregiver'
          when private.user_has_family_role(v_line.user_id,v_family,array['patient']) then 'patient'
          else 'viewer'
        end::text;
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_admin_bug_reports(p_line_user_id text, p_limit integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth'
AS $function$
declare v_line record;v_ctx private.line_identity_contexts%rowtype;v_items jsonb;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select * into v_ctx from private.line_identity_contexts where line_identity_id=v_line.line_identity_id;
 if v_ctx.active_family_id is null or not exists(select 1 from public.family_role_assignments r where r.family_id=v_ctx.active_family_id and r.user_id=v_line.user_id and r.status='active' and r.role in ('owner','admin')) then raise exception 'bug_report_admin_denied';end if;
 select coalesce(jsonb_agg(x.j),'[]'::jsonb) into v_items from
 (select jsonb_build_object('id',b.id,'status',b.status,'description',b.description,'has_image',b.image_storage_path is not null,'image_storage_path',b.image_storage_path,'created_at',b.created_at) j from public.phms_bug_reports b where b.family_id=v_ctx.active_family_id order by created_at desc limit least(greatest(coalesce(p_limit,30),1),100)) x;
 return jsonb_build_object('items',v_items);
end $function$

CREATE OR REPLACE FUNCTION public.phms_line_admin_set_bug_status(p_line_user_id text, p_report_id uuid, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth'
AS $function$
declare a record; c private.line_identity_contexts%rowtype; n integer;
begin
 if p_status not in ('new','triaged','investigating','resolved','closed') then raise exception 'invalid_status';end if;
 select * into a from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(a.line_identity_id,a.user_id);
 select * into c from private.line_identity_contexts where line_identity_id=a.line_identity_id;
 update public.phms_bug_reports b set status=p_status,updated_at=now()
 where b.id=p_report_id and b.family_id=c.active_family_id
 and exists(select 1 from public.family_role_assignments f where f.family_id=b.family_id and f.user_id=a.user_id and f.status='active' and f.role in ('owner','admin'));
 get diagnostics n=row_count;
 if n=0 then raise exception 'bug_report_update_denied';end if;
 return jsonb_build_object('ok',true,'status',p_status);
end $function$

CREATE OR REPLACE FUNCTION public.phms_line_apply_appointment_notification_template(p_line_user_id text, p_record_code text, p_template_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_appt public.appointments%rowtype;
  v_t public.family_notification_templates%rowtype;
  v_t_id uuid;
  v_count integer;
  v_can_manage_groups boolean:=false;
begin
  select * into v_ref
  from private.phms_find_crud_record(p_line_user_id,'appointment',p_record_code,'update')
  limit 1;

  if not coalesce((
    select (coalesce((a.v->>'is_primary_caregiver')::boolean,false)
         or coalesce((a.v->>'is_self_manager')::boolean,false)
         or coalesce((a.v->>'is_authorized_helper')::boolean,false))
    from (select public.phms_line_appointment_action_capabilities(p_line_user_id,p_record_code) v) a
  ),false) then
    raise exception 'appointment_notification_permission_denied';
  end if;

  select * into v_appt
  from public.appointments
  where id=v_ref.record_id and deleted_at is null;

  select count(*),min(t.id) into v_count,v_t_id
  from public.family_notification_templates t
  where t.family_id=v_appt.family_id
    and t.is_active=true
    and lower(t.id::text) like lower(btrim(p_template_code))||'%';

  if v_count=0 then raise exception 'notification_template_not_found'; end if;
  if v_count>1 then raise exception 'notification_template_code_ambiguous'; end if;

  select * into v_t
  from public.family_notification_templates
  where id=v_t_id;

  v_can_manage_groups:=private.user_has_family_role(
    v_ref.actor_user_id,v_appt.family_id,array['owner','admin']
  );

  if not v_can_manage_groups and exists(
    select 1
    from public.family_notification_template_targets x
    where x.template_id=v_t.id
      and x.target_type='line_group'
      and x.enabled=true
  ) then
    raise exception 'group_notification_permission_denied';
  end if;

  insert into public.appointment_notification_settings(
    appointment_id,days_before,local_time,timezone,recipient_mode,created_by,updated_by
  ) values(
    v_appt.id,v_t.days_before,v_t.local_time,'Asia/Bangkok',
    v_t.recipient_mode,v_ref.actor_user_id,v_ref.actor_user_id
  )
  on conflict(appointment_id)
  do update set
    days_before=excluded.days_before,
    local_time=excluded.local_time,
    timezone='Asia/Bangkok',
    recipient_mode=excluded.recipient_mode,
    updated_by=v_ref.actor_user_id,
    updated_at=now();

  delete from public.appointment_notification_user_targets
  where appointment_id=v_appt.id;

  insert into public.appointment_notification_user_targets(
    appointment_id,user_id,enabled,created_by
  )
  select v_appt.id,x.target_user_id,true,v_ref.actor_user_id
  from public.family_notification_template_targets x
  where x.template_id=v_t.id
    and x.target_type='user'
    and x.enabled=true
    and exists(
      select 1 from private.phms_notification_recipients(v_appt.person_id,'appointments') r
      where r.recipient_user_id=x.target_user_id
    )
  on conflict(appointment_id,user_id)
  do update set enabled=true,updated_at=now();

  if v_can_manage_groups then
    update public.appointment_line_group_targets
    set status='disabled',disabled_at=now(),updated_at=now()
    where appointment_id=v_appt.id and status='active';

    insert into public.appointment_line_group_targets(
      appointment_id,line_group_id,status,created_by,family_channel_id
    )
    select v_appt.id,fc.external_channel_id,'active',v_ref.actor_user_id,fc.id
    from public.family_notification_template_targets x
    join public.family_channels fc on fc.id=x.family_channel_id
    join public.family_channel_family_links l
      on l.family_channel_id=fc.id
     and l.family_id=v_appt.family_id
     and l.status='active'
    where x.template_id=v_t.id
      and x.target_type='line_group'
      and x.enabled=true
      and fc.channel_type='line_group'
      and fc.status='active'
    on conflict(appointment_id,line_group_id)
    do update set
      status='active',
      disabled_at=null,
      created_by=v_ref.actor_user_id,
      family_channel_id=excluded.family_channel_id,
      updated_at=now();
  end if;

  perform private.phms_sync_auto_appointment_reminders(now());

  return public.phms_line_appointment_notification_workspace(
    p_line_user_id,substr(v_appt.id::text,1,12)
  ) || jsonb_build_object(
    'applied_template',v_t.template_name,
    'group_targets_preserved',not v_can_manage_groups
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_ack(p_line_user_id text, p_ack_code text, p_response text DEFAULT 'acknowledged'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_user uuid;
  v_code text:=lower(btrim(coalesce(p_ack_code,'')));
  v_response text:=lower(btrim(coalesce(p_response,'acknowledged')));
  v_count int;
  v_ack public.appointment_acknowledgements%rowtype;
  v_ack_id uuid;
  v_family uuid;
  v_family_person uuid;
  v_person uuid;
  v_title text;
  v_at timestamptz;
  v_role text;
  v_responder_name text;
begin
  if v_response not in ('acknowledged','declined') then
    raise exception 'invalid_ack_response';
  end if;
  if length(v_code)<8 then raise exception 'ack_code_too_short'; end if;

  select li.user_id into v_user
  from public.line_identities li
  where li.line_user_id=p_line_user_id
    and li.is_active=true
    and li.onboarding_status='ready'
  order by li.updated_at desc nulls last,li.created_at desc
  limit 1;

  if v_user is null then raise exception 'line_identity_not_ready'; end if;

  select count(*),min(id)
  into v_count,v_ack_id
  from public.appointment_acknowledgements
  where user_id=v_user
    and status='pending'
    and lower(id::text) like v_code||'%';

  if v_count=0 then raise exception 'ack_not_found'; end if;
  if v_count>1 then raise exception 'ack_code_ambiguous'; end if;

  update public.appointment_acknowledgements
  set status=v_response,
      responded_at=now(),
      updated_at=now()
  where id=v_ack_id
  returning * into v_ack;

  if v_ack.ack_type='assignment' then
    update public.appointment_assignees
    set status=case when v_response='acknowledged' then 'accepted' else 'declined' end,
        acknowledged_at=now(),
        updated_at=now()
    where id=private.phms_try_uuid(v_ack.change_snapshot->>'assignee_id');
  end if;

  select a.family_id,a.family_person_id,a.person_id,a.title,a.appointment_at
  into v_family,v_family_person,v_person,v_title,v_at
  from public.appointments a where a.id=v_ack.appointment_id;

  v_role:=coalesce(v_ack.change_snapshot->>'role','responsible');
  v_responder_name:=private.family_user_label_for_viewer(
    coalesce(v_ack.requested_by,v_user),v_family,v_user
  );

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,new_data,description
  )
  values(
    v_family,v_user,v_family_person,
    'appointment_ack','appointment',v_ack.appointment_id,
    jsonb_build_object('ack_id',v_ack.id,'ack_type',v_ack.ack_type,'status',v_response),
    case when v_response='acknowledged' then 'รับทราบนัด/หน้าที่แล้ว' else 'แจ้งว่ายังรับผิดชอบไม่ได้' end
  );

  -- แจ้งกลับคนที่มอบหมาย/ขอให้รับทราบ
  if v_ack.requested_by is not null and v_ack.requested_by<>v_user then
    insert into public.notifications(
      family_id,recipient_user_id,person_id,family_person_id,
      event_type,title,message,related_record_id,channel,priority,status,
      scheduled_for,next_attempt_at,payload,dedupe_key,created_at,updated_at
    )
    values(
      v_family,v_ack.requested_by,v_person,v_family_person,
      'appointment_assignment_ack',
      case when v_response='acknowledged'
        then '✅ ผู้รับผิดชอบรับทราบแล้ว'
        else '⚠️ ผู้รับผิดชอบกดรับไม่ได้' end,
      concat(
        '👤 ',coalesce(v_responder_name,'สมาชิก'),
        E'\nนัดเพื่อ: ',coalesce(nullif(btrim(v_title),''),'นัดหมาย'),
        E'\nวันเวลา: ',to_char(v_at at time zone 'Asia/Bangkok','DD/MM/YYYY HH24:MI'),
        E'\nหน้าที่: ',
        case v_role
          when 'driver' then 'คนขับรถ / คนพาไป'
          when 'caregiver' then 'ผู้ดูแลวันนัด'
          when 'companion' then 'คนไปด้วย'
          when 'booker' then 'คนประสานงานนัด'
          when 'responsible' then 'ผู้รับผิดชอบหลัก'
          else 'ผู้รับผิดชอบ'
        end,
        E'\nสถานะ: ',case when v_response='acknowledged' then 'รับทราบแล้ว' else 'รับไม่ได้' end
      ),
      v_ack.appointment_id,'line','normal','pending',now(),now(),
      jsonb_build_object(
        'appointment_id',v_ack.appointment_id,
        'appointment_code',substr(v_ack.appointment_id::text,1,12),
        'ack_response',v_response,
        'responded_by',v_user
      ),
      'appointment_assignment_ack_response:'||v_ack.id::text,
      now(),now()
    )
    on conflict (dedupe_key) where dedupe_key is not null do nothing;
  end if;

  return jsonb_build_object(
    'ok',true,
    'appointment_id',v_ack.appointment_id,
    'appointment_code',substr(v_ack.appointment_id::text,1,12),
    'ack_code',substr(v_ack.id::text,1,12),
    'ack_type',v_ack.ack_type,
    'status',v_ack.status
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_action_capabilities(p_line_user_id text, p_record_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_a public.appointments%rowtype;
  v_is_self boolean:=false;
  v_is_primary boolean:=false;
  v_is_helper boolean:=false;
  v_can_manage_status boolean:=false;
  v_local_date date;
  v_today date:=(now() at time zone 'Asia/Bangkok')::date;
begin
  select * into v_ref
  from private.phms_line_appointment_access(p_line_user_id,p_record_code)
  limit 1;

  select * into v_a
  from public.appointments
  where id=v_ref.record_id and deleted_at is null;

  if not found then raise exception 'appointment_not_found'; end if;

  select coalesce(p.linked_user_id=v_ref.actor_user_id,false)
  into v_is_self
  from public.persons p
  where p.id=v_ref.target_person_id;

  if v_ref.active_family_person_id is not null then
    v_is_primary:=private.phms_is_medical_primary(
      v_ref.actor_user_id,v_ref.active_family_person_id
    );

    select exists(
      select 1
      from public.person_caregiver_assignments ca
      where ca.family_person_id=v_ref.active_family_person_id
        and ca.caregiver_user_id=v_ref.actor_user_id
        and ca.status='active'
        and coalesce(ca.can_manage_appointments,false)
    ) into v_is_helper;
  end if;

  v_can_manage_status:=coalesce(v_ref.can_update,false)
    and (v_is_self or v_is_primary or v_is_helper);

  v_local_date:=(v_a.appointment_at at time zone 'Asia/Bangkok')::date;

  return jsonb_build_object(
    'ok',true,
    'can_update',coalesce(v_ref.can_update,false),
    'is_self_manager',v_is_self and coalesce(v_ref.can_update,false),
    'is_primary_caregiver',v_is_primary,
    'is_authorized_helper',v_is_helper,
    'can_manage_status',v_can_manage_status,
    'appointment_date',v_local_date,
    'is_appointment_today',v_local_date=v_today,
    'status',coalesce(v_a.status,'scheduled'),
    'can_post_visit',
      coalesce(v_ref.can_update,false)
      and coalesce(v_a.status,'scheduled')='completed'
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_add_task(p_line_user_id text, p_record_code text, p_title text, p_task_type text DEFAULT 'other'::text, p_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_instruction text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_type text:=lower(btrim(coalesce(p_task_type,'other')));
  v_task public.appointment_tasks%rowtype;
begin
  if nullif(btrim(p_title),'') is null then raise exception 'task_title_required'; end if;
  if v_type not in ('lab','imaging','urine','measurement','document','fasting','medication_instruction','other') then
    v_type:='other';
  end if;

  select * into v_ref
  from private.phms_find_crud_record(p_line_user_id,'appointment',p_record_code,'update')
  limit 1;

  insert into public.appointment_tasks(
    appointment_id,task_type,title,instruction,due_at,created_by
  )
  values(
    v_ref.record_id,v_type,btrim(p_title),nullif(btrim(p_instruction),''),
    p_due_at,v_ref.actor_user_id
  )
  returning * into v_task;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    new_data,description
  ) values(
    v_ref.active_family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
    'appointment_task_added','appointment',v_ref.record_id,
    to_jsonb(v_task),'เพิ่มสิ่งที่ต้องทำก่อนนัด'
  );

  return jsonb_build_object(
    'ok',true,
    'appointment_code',substr(v_ref.record_id::text,1,12),
    'task_code',substr(v_task.id::text,1,12),
    'task',to_jsonb(v_task)
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_add_tasks(p_line_user_id text, p_record_code text, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_ref record;
  v_item text;
  v_task public.appointment_tasks%rowtype;
  v_added jsonb:='[]'::jsonb;
  v_count int:=0;
begin
  if jsonb_typeof(p_items)<>'array' then
    raise exception 'task_items_array_required';
  end if;

  select jsonb_array_length(p_items) into v_count;
  if v_count<1 or v_count>12 then
    raise exception 'task_items_count_invalid';
  end if;

  select * into v_ref
  from private.phms_find_crud_record(p_line_user_id,'appointment',p_record_code,'update')
  limit 1;

  for v_item in
    select btrim(value)
    from jsonb_array_elements_text(p_items)
  loop
    if nullif(v_item,'') is null then
      continue;
    end if;

    insert into public.appointment_tasks(
      appointment_id,task_type,title,instruction,due_at,created_by
    ) values(
      v_ref.record_id,
      private.phms_appointment_task_type_from_text(v_item),
      v_item,
      null,
      null,
      v_ref.actor_user_id
    )
    returning * into v_task;

    v_added:=v_added||jsonb_build_array(jsonb_build_object(
      'task_code',substr(v_task.id::text,1,12),
      'title',v_task.title,
      'task_type',v_task.task_type
    ));
  end loop;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    new_data,description
  ) values(
    v_ref.active_family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
    'appointment_tasks_added_bulk','appointment',v_ref.record_id,
    jsonb_build_object('items',v_added),
    'เพิ่ม checklist เตรียมก่อนนัด'
  );

  return jsonb_build_object(
    'ok',true,
    'appointment_code',substr(v_ref.record_id::text,1,12),
    'added_count',jsonb_array_length(v_added),
    'items',v_added
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_attach_task_asset(p_line_user_id text, p_task_code text, p_storage_asset_id uuid, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_code text:=lower(btrim(coalesce(p_task_code,'')));
  v_count int;
  v_task public.appointment_tasks%rowtype;
  v_ref record;
  v_link_result jsonb;
  v_link_id uuid;
  v_evidence_result jsonb;
  v_link_note text;
begin
  if length(v_code)<8 then raise exception 'task_code_too_short'; end if;
  if p_storage_asset_id is null then raise exception 'storage_asset_required'; end if;

  select count(*) into v_count
  from public.appointment_tasks t
  where lower(t.id::text) like v_code||'%';
  if v_count=0 then raise exception 'task_not_found'; end if;
  if v_count>1 then raise exception 'task_code_ambiguous'; end if;

  select * into v_task
  from public.appointment_tasks t
  where lower(t.id::text) like v_code||'%'
  limit 1;

  select * into v_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',substr(v_task.appointment_id::text,1,12),'update'
  ) limit 1;

  v_link_note:=coalesce(
    nullif(btrim(coalesce(p_note,'')),''),
    'หลักฐานรายการเตรียม: '||v_task.title
  );

  v_link_result:=public.phms_line_appointment_link_existing_asset(
    p_line_user_id,
    substr(v_task.appointment_id::text,1,12),
    p_storage_asset_id,
    'preparation',
    null,
    v_link_note
  );

  v_link_id:=nullif(v_link_result->>'link_id','')::uuid;
  if v_link_id is null then raise exception 'task_evidence_link_failed'; end if;

  v_evidence_result:=public.phms_line_appointment_attach_task_evidence(
    p_line_user_id,
    substr(v_task.id::text,1,12),
    v_link_id,
    p_note
  );

  return v_evidence_result||jsonb_build_object(
    'storage_asset_id',p_storage_asset_id,
    'reused',coalesce((v_link_result->>'reused')::boolean,false)
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_attach_task_evidence(p_line_user_id text, p_task_code text, p_link_id uuid, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_code text:=lower(btrim(coalesce(p_task_code,'')));
  v_count int;
  v_task public.appointment_tasks%rowtype;
  v_ref record;
  v_link public.appointment_document_links%rowtype;
  v_evidence private.appointment_task_evidence%rowtype;
begin
  if length(v_code)<8 then raise exception 'task_code_too_short'; end if;
  if p_link_id is null then raise exception 'appointment_document_link_required'; end if;

  select count(*) into v_count
  from public.appointment_tasks t
  where lower(t.id::text) like v_code||'%';
  if v_count=0 then raise exception 'task_not_found'; end if;
  if v_count>1 then raise exception 'task_code_ambiguous'; end if;

  select * into v_task
  from public.appointment_tasks t
  where lower(t.id::text) like v_code||'%'
  limit 1;

  select * into v_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',substr(v_task.appointment_id::text,1,12),'update'
  ) limit 1;

  select * into v_link
  from public.appointment_document_links l
  where l.id=p_link_id
    and l.appointment_id=v_task.appointment_id;
  if not found then raise exception 'task_evidence_link_not_in_appointment'; end if;

  insert into private.appointment_task_evidence(
    task_id,appointment_document_link_id,evidence_type,note,created_by
  ) values(
    v_task.id,v_link.id,'supporting',nullif(btrim(coalesce(p_note,'')),''),v_ref.actor_user_id
  )
  on conflict(task_id,appointment_document_link_id)
  do update set
    note=coalesce(excluded.note,private.appointment_task_evidence.note)
  returning * into v_evidence;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,new_data,description
  ) values(
    v_ref.active_family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
    'appointment_task_evidence_linked','appointment',v_ref.record_id,
    jsonb_build_object(
      'task_id',v_task.id,
      'task_code',substr(v_task.id::text,1,12),
      'document_link_id',v_link.id,
      'evidence_id',v_evidence.id
    ),
    'เพิ่มรูปหรือเอกสารประกอบรายการเตรียมก่อนนัด'
  );

  return jsonb_build_object(
    'ok',true,
    'appointment_code',substr(v_ref.record_id::text,1,12),
    'task_code',substr(v_task.id::text,1,12),
    'evidence_id',v_evidence.id,
    'link_id',v_link.id
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_autofill(p_line_user_id text, p_hospital_query text, p_department_query text DEFAULT NULL::text, p_doctor_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ctx record;
  v_person_id uuid;
  v_hnorm text:=private.phms_normalize_directory_alias(p_hospital_query);
  v_dnorm text;
  v_org public.healthcare_organizations%rowtype;
  v_unit public.healthcare_service_units%rowtype;
  v_unit_inferred boolean:=false;
  v_mem private.person_appointment_memory%rowtype;
  v_hn text;
  v_display_hospital text;
  v_display_department text;
  v_fields jsonb:='{}'::jsonb;
  v_fac jsonb;
  v_obs record;
  v_memory_units int:=0;
begin
  if v_hnorm is null then
    return jsonb_build_object('matched',false,'reason','hospital_required','fields','{}'::jsonb);
  end if;

  select * into v_ctx
  from private.phms_line_crud_context(p_line_user_id,'appointment','view')
  limit 1;

  v_person_id:=v_ctx.target_person_id;
  if v_person_id is null then
    return jsonb_build_object('matched',false,'reason','active_person_required','fields','{}'::jsonb);
  end if;

  select o.* into v_org
  from private.healthcare_directory_aliases a
  join public.healthcare_organizations o on o.id=a.organization_id
  where a.entity_type='organization'
    and a.is_active
    and a.normalized_alias=v_hnorm
    and o.deleted_at is null
  order by case a.confidence when 'high' then 0 when 'medium' then 1 else 2 end,
           a.updated_at desc
  limit 1;

  if not found then
    select o.* into v_org
    from public.healthcare_organizations o
    where o.deleted_at is null
      and (
        private.phms_normalize_directory_alias(o.external_code)=v_hnorm
        or private.phms_normalize_directory_alias(o.name)=v_hnorm
        or private.phms_normalize_directory_alias(
          o.name||case when nullif(btrim(coalesce(o.external_code,'')),'') is not null
            then ' ('||o.external_code||')' else '' end
        )=v_hnorm
      )
    order by o.updated_at desc
    limit 1;
  end if;

  if not found then
    begin
      v_fac:=public.phms_resolve_line_appointment_facility(
        p_line_user_id,p_hospital_query,p_department_query
      );
      if coalesce((v_fac->>'matched')::boolean,false) then
        select * into v_org
        from public.healthcare_organizations
        where id=private.phms_try_uuid(v_fac->>'organization_id');
      end if;
    exception when others then
      null;
    end;
  end if;

  if v_org.id is null then
    return jsonb_build_object(
      'matched',false,'reason','hospital_not_found',
      'raw_hospital',p_hospital_query,'fields','{}'::jsonb
    );
  end if;

  v_display_hospital:=v_org.name;
  if nullif(btrim(coalesce(v_org.branch_name,'')),'') is not null
     and position(lower(v_org.branch_name) in lower(v_display_hospital))=0 then
    v_display_hospital:=v_display_hospital||' '||btrim(v_org.branch_name);
  end if;
  if nullif(btrim(coalesce(v_org.external_code,'')),'') is not null then
    v_display_hospital:=v_display_hospital||' ('||btrim(v_org.external_code)||')';
  end if;

  v_fields:=v_fields||jsonb_build_object(
    'hospital_name',jsonb_build_object(
      'value',v_display_hospital,'confidence','high','source','organization_master',
      'auto_apply',true,'fill_draft',true,'requires_confirmation',false
    ),
    'organization_id',jsonb_build_object(
      'value',v_org.id,'confidence','high','source','organization_master',
      'auto_apply',true,'fill_draft',true,'requires_confirmation',false
    )
  );

  if nullif(btrim(coalesce(p_department_query,'')),'') is not null then
    v_dnorm:=private.phms_normalize_directory_alias(
      private.phms_normalize_appointment_department(p_department_query)
    );

    select u.* into v_unit
    from private.healthcare_directory_aliases a
    join public.healthcare_service_units u on u.id=a.service_unit_id
    where a.entity_type='service_unit'
      and a.organization_id=v_org.id
      and a.is_active
      and a.normalized_alias=v_dnorm
      and u.deleted_at is null
    order by case a.confidence when 'high' then 0 when 'medium' then 1 else 2 end,
             u.is_verified desc,a.updated_at desc
    limit 1;

    if not found then
      select u.* into v_unit
      from public.healthcare_service_units u
      where u.organization_id=v_org.id
        and u.deleted_at is null
        and (
          private.phms_normalize_directory_alias(u.name)=v_dnorm
          or private.phms_normalize_directory_alias(u.code)=private.phms_normalize_directory_alias(p_department_query)
          or private.phms_normalize_directory_alias(
            u.name||case when nullif(btrim(coalesce(u.code,'')),'') is not null then ' ('||u.code||')' else '' end
          )=v_dnorm
        )
      order by u.is_verified desc,u.updated_at desc
      limit 1;
    end if;
  else
    select count(*) into v_memory_units
    from private.person_appointment_memory m
    where m.person_id=v_person_id and m.organization_id=v_org.id;

    if v_memory_units=1 then
      select u.* into v_unit
      from private.person_appointment_memory m
      join public.healthcare_service_units u on u.id=m.service_unit_id
      where m.person_id=v_person_id
        and m.organization_id=v_org.id
        and u.deleted_at is null
      order by m.confirmed_at desc
      limit 1;
      v_unit_inferred:=v_unit.id is not null;
    end if;
  end if;

  if v_unit.id is not null then
    v_display_department:=v_unit.name||
      case when nullif(btrim(coalesce(v_unit.code,'')),'') is not null then ' ('||v_unit.code||')' else '' end;

    v_fields:=v_fields||jsonb_build_object(
      'department',jsonb_build_object(
        'value',v_display_department,
        'confidence',case when v_unit_inferred then 'medium' else 'high' end,
        'source',case when v_unit_inferred then 'person_memory' else 'service_unit_master' end,
        'auto_apply',not v_unit_inferred,
        'fill_draft',true,
        'requires_confirmation',v_unit_inferred
      ),
      'service_unit_id',jsonb_build_object(
        'value',v_unit.id,
        'confidence',case when v_unit_inferred then 'medium' else 'high' end,
        'source',case when v_unit_inferred then 'person_memory' else 'service_unit_master' end,
        'auto_apply',not v_unit_inferred,
        'fill_draft',true,
        'requires_confirmation',v_unit_inferred
      )
    );
  end if;

  v_hn:=private.phms_person_hospital_hn(v_person_id,v_org.id,v_display_hospital);
  if nullif(btrim(coalesce(v_hn,'')),'') is not null then
    v_fields:=v_fields||jsonb_build_object(
      'hospital_hn',jsonb_build_object(
        'value',v_hn,'confidence','high','source','person_hospital_identifier',
        'auto_apply',true,'fill_draft',true,'requires_confirmation',false
      )
    );
  end if;

  if v_unit.id is not null then
    if nullif(btrim(coalesce(v_unit.location_detail,'')),'') is not null
       or nullif(btrim(coalesce(v_unit.building_name,'')),'') is not null
       or nullif(btrim(coalesce(v_unit.floor_label,'')),'') is not null
       or nullif(btrim(coalesce(v_unit.contact_point,'')),'') is not null then
      v_fields:=v_fields||jsonb_build_object(
        'location_detail',jsonb_build_object(
          'value',coalesce(
            nullif(btrim(v_unit.location_detail),''),
            concat_ws(' • ',
              nullif(btrim(v_unit.building_name),''),
              nullif(btrim(v_unit.floor_label),''),
              nullif(btrim(v_unit.contact_point),'')
            )
          ),
          'confidence',case when v_unit.is_verified then 'high' else 'medium' end,
          'source','service_unit_master',
          'auto_apply',v_unit.is_verified,
          'fill_draft',true,
          'requires_confirmation',not v_unit.is_verified
        )
      );
    else
      select * into v_obs
      from private.service_unit_observations o
      where o.service_unit_id=v_unit.id and o.field_name='location_detail'
      order by o.confirmation_count desc,o.last_confirmed_at desc
      limit 1;
      if found then
        v_fields:=v_fields||jsonb_build_object(
          'location_detail',jsonb_build_object(
            'value',v_obs.field_value,'confidence','medium','source','confirmed_appointment_memory',
            'auto_apply',false,'fill_draft',true,'requires_confirmation',true,
            'confirmation_count',v_obs.confirmation_count
          )
        );
      end if;
    end if;

    if nullif(btrim(coalesce(v_unit.phone,'')),'') is not null then
      v_fields:=v_fields||jsonb_build_object(
        'contact_phone',jsonb_build_object(
          'value',v_unit.phone,
          'confidence',case when v_unit.is_verified then 'high' else 'medium' end,
          'source','service_unit_master',
          'auto_apply',v_unit.is_verified,'fill_draft',true,
          'requires_confirmation',not v_unit.is_verified
        )
      );
    else
      select * into v_obs
      from private.service_unit_observations o
      where o.service_unit_id=v_unit.id and o.field_name='contact_phone'
      order by o.confirmation_count desc,o.last_confirmed_at desc
      limit 1;
      if found then
        v_fields:=v_fields||jsonb_build_object(
          'contact_phone',jsonb_build_object(
            'value',v_obs.field_value,'confidence','medium','source','confirmed_appointment_memory',
            'auto_apply',false,'fill_draft',true,'requires_confirmation',true,
            'confirmation_count',v_obs.confirmation_count
          )
        );
      end if;
    end if;

    if nullif(btrim(coalesce(v_unit.email,'')),'') is not null
       and v_unit.email ~* '^[A-Z0-9._%+-]+@[A-Z0-9.-]+[.][A-Z]{2,}$' then
      v_fields:=v_fields||jsonb_build_object(
        'contact_email',jsonb_build_object(
          'value',lower(v_unit.email),
          'confidence',case when v_unit.is_verified then 'high' else 'medium' end,
          'source','service_unit_master',
          'auto_apply',v_unit.is_verified,'fill_draft',true,
          'requires_confirmation',not v_unit.is_verified
        )
      );
    else
      select * into v_obs
      from private.service_unit_observations o
      where o.service_unit_id=v_unit.id and o.field_name='contact_email'
      order by o.confirmation_count desc,o.last_confirmed_at desc
      limit 1;
      if found then
        v_fields:=v_fields||jsonb_build_object(
          'contact_email',jsonb_build_object(
            'value',lower(v_obs.field_value),'confidence','medium','source','confirmed_appointment_memory',
            'auto_apply',false,'fill_draft',true,'requires_confirmation',true,
            'confirmation_count',v_obs.confirmation_count
          )
        );
      end if;
    end if;

    select * into v_mem
    from private.person_appointment_memory m
    where m.person_id=v_person_id
      and m.organization_id=v_org.id
      and m.service_unit_id=v_unit.id
    order by m.confirmed_at desc
    limit 1;

    if found then
      if nullif(btrim(coalesce(v_mem.last_doctor_name,'')),'') is not null
         and nullif(btrim(coalesce(p_doctor_name,'')),'') is null then
        v_fields:=v_fields||jsonb_build_object(
          'doctor_name',jsonb_build_object(
            'value',v_mem.last_doctor_name,'confidence','medium','source','person_service_unit_memory',
            'auto_apply',false,'fill_draft',true,'requires_confirmation',true,
            'confirmation_count',v_mem.confirmation_count
          )
        );
      end if;
      if nullif(btrim(coalesce(v_mem.last_coverage_type,'')),'') is not null then
        v_fields:=v_fields||jsonb_build_object(
          'coverage_type',jsonb_build_object(
            'value',v_mem.last_coverage_type,'confidence','medium','source','person_service_unit_memory',
            'auto_apply',false,'fill_draft',true,'requires_confirmation',true,
            'confirmation_count',v_mem.confirmation_count
          )
        );
      end if;
      if coalesce(v_mem.last_arrival_lead_minutes,0)>0 then
        v_fields:=v_fields||jsonb_build_object(
          'arrival_lead_minutes',jsonb_build_object(
            'value',v_mem.last_arrival_lead_minutes,'confidence','medium','source','person_service_unit_memory',
            'auto_apply',false,'fill_draft',true,'requires_confirmation',true,
            'confirmation_count',v_mem.confirmation_count
          )
        );
      end if;
      if nullif(btrim(coalesce(v_mem.last_care_topic,'')),'') is not null then
        v_fields:=v_fields||jsonb_build_object(
          'care_topic',jsonb_build_object(
            'value',v_mem.last_care_topic,'confidence','low','source','person_service_unit_memory',
            'auto_apply',false,'fill_draft',false,'requires_confirmation',true,
            'confirmation_count',v_mem.confirmation_count
          )
        );
      end if;
    end if;
  end if;

  return jsonb_build_object(
    'matched',true,
    'person_id',v_person_id,
    'organization_id',v_org.id,
    'service_unit_id',case when v_unit.id is not null then v_unit.id else null end,
    'fields',v_fields,
    'policy',jsonb_build_object(
      'high','เติมอัตโนมัติจากฐานกลาง/ตัวระบุที่ตรงกัน',
      'medium','เติมใน Draft แต่ต้องตรวจยืนยัน',
      'low','เสนอเป็นคำแนะนำเท่านั้น ไม่เติมเอง'
    )
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_autofill_v2(p_line_user_id text, p_hospital_query text, p_department_query text DEFAULT NULL::text, p_doctor_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_base jsonb;
  v_fields jsonb;
  v_ctx record;
  v_org uuid;
  v_vn text;
  v_doc jsonb;
  v_score integer:=0;
begin
  v_base:=public.phms_line_appointment_autofill(
    p_line_user_id,p_hospital_query,p_department_query,p_doctor_name
  );
  if coalesce((v_base->>'matched')::boolean,false) is not true then
    return v_base;
  end if;

  v_fields:=coalesce(v_base->'fields','{}'::jsonb);
  v_org:=private.phms_try_uuid(v_base->>'organization_id');

  select * into v_ctx
  from private.phms_line_crud_context(p_line_user_id,'appointment','view')
  limit 1;

  v_vn:=private.phms_person_hospital_vn(
    v_ctx.target_person_id,
    v_org,
    coalesce(v_fields#>>'{hospital_name,value}',p_hospital_query)
  );

  if nullif(btrim(coalesce(v_vn,'')),'') is not null then
    v_fields:=v_fields||jsonb_build_object(
      'hospital_vn',jsonb_build_object(
        'value',v_vn,
        'confidence','high',
        'source','person_hospital_identifier',
        'auto_apply',true,
        'fill_draft',true,
        'requires_confirmation',false
      )
    );
  end if;

  if nullif(btrim(coalesce(p_doctor_name,'')),'') is not null then
    begin
      v_doc:=public.phms_resolve_line_appointment_clinician(
        p_line_user_id,
        p_doctor_name,
        coalesce(v_fields#>>'{hospital_name,value}',p_hospital_query),
        coalesce(v_fields#>>'{department,value}',p_department_query)
      );
      if coalesce((v_doc->>'matched')::boolean,false) then
        v_score:=coalesce((v_doc->>'score')::integer,0);
        v_fields:=v_fields||jsonb_build_object(
          'doctor_name',jsonb_build_object(
            'value',v_doc->>'doctor_name',
            'confidence',case when v_score>=85 then 'high' else 'medium' end,
            'source','person_appointment_history_name_completion',
            'auto_apply',v_score>=85,
            'fill_draft',true,
            'requires_confirmation',v_score<85,
            'score',v_score
          )
        );
      end if;
    exception when others then
      null;
    end;
  end if;

  return jsonb_set(v_base,'{fields}',v_fields,true);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_cancel(p_line_user_id text, p_record_code text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_old jsonb;
  v_new jsonb;
  v_reason text:=coalesce(nullif(btrim(p_reason),''),'ยกเลิกนัด');
  v_audit_id uuid;
  v_rec record;
begin
  select * into v_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',p_record_code,'delete'
  ) limit 1;

  select to_jsonb(a) into v_old from public.appointments a where a.id=v_ref.record_id;

  update public.appointments
  set status='cancelled',
      cancelled_at=now(),
      cancel_reason=v_reason,
      last_change_reason=v_reason,
      updated_at=now()
  where id=v_ref.record_id;

  update public.appointment_reminders
  set status='cancelled',updated_at=now()
  where appointment_id=v_ref.record_id
    and status in ('pending','failed');

  update public.notifications
  set status='cancelled',
      last_error='appointment_cancelled',
      updated_at=now()
  where related_record_id=v_ref.record_id
    and status in ('pending','failed')
    and event_type in ('appointment_reminder','appointment_post_visit');

  select to_jsonb(a) into v_new from public.appointments a where a.id=v_ref.record_id;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    old_data,new_data,description
  )
  values(
    v_ref.active_family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
    'appointment_cancelled','appointment',v_ref.record_id,
    v_old,v_new,v_reason
  )
  returning id into v_audit_id;

  for v_rec in
    select distinct r.recipient_user_id
    from (
      select aa.user_id recipient_user_id
      from public.appointment_assignees aa
      where aa.appointment_id=v_ref.record_id
        and aa.status in ('assigned','accepted')
      union
      select nr.recipient_user_id
      from private.phms_notification_recipients(v_ref.target_person_id,'appointments') nr
    ) r
    where r.recipient_user_id is not null
      and r.recipient_user_id is distinct from v_ref.actor_user_id
  loop
    insert into public.notifications(
      family_id,recipient_user_id,person_id,family_person_id,event_type,title,message,
      related_record_id,channel,priority,status,scheduled_for,next_attempt_at,payload,dedupe_key,updated_at
    )
    values(
      v_ref.active_family_id,v_rec.recipient_user_id,v_ref.target_person_id,v_ref.active_family_person_id,
      'appointment_cancelled','❌ นัดหมายถูกยกเลิก',
      concat('👤 ',v_ref.target_person_name,E'
นัด: ',coalesce(nullif(v_new->>'title',''),'นัดหมาย'),E'
เหตุผล: ',v_reason),
      v_ref.record_id,'line','high','pending',now(),now(),
      jsonb_build_object('appointment_id',v_ref.record_id,'appointment_code',substr(v_ref.record_id::text,1,12)),
      'appointment_cancel:'||v_audit_id::text||':'||v_rec.recipient_user_id::text,now()
    );
  end loop;

  return jsonb_build_object(
    'ok',true,'record_code',substr(v_ref.record_id::text,1,12),
    'status','cancelled','reason',v_reason,'item',v_new
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_caregiver_note(p_line_user_id text, p_record_code text, p_operation text DEFAULT 'read'::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_ref record;
 v_cap jsonb;
 v_mode text:=lower(coalesce(p_operation,'read'));
 v_note text;
begin
 if v_mode not in ('read','save','clear') then raise exception 'invalid_caregiver_note_action'; end if;
 select * into v_ref from private.phms_line_appointment_access(p_line_user_id,p_record_code) limit 1;
 if v_ref.record_id is null then raise exception 'appointment_not_accessible'; end if;
 v_cap:=public.phms_line_appointment_action_capabilities(p_line_user_id,p_record_code);
 if coalesce((v_ref.can_update),false) is not true
   or not (
    coalesce((v_cap->>'is_self_manager')::boolean,false)
    or coalesce((v_cap->>'is_primary_caregiver')::boolean,false)
    or coalesce((v_cap->>'is_authorized_helper')::boolean,false)
   )
 then
  raise exception 'caregiver_note_access_denied';
 end if;
 if v_mode='save' then
  v_note:=btrim(coalesce(p_note,''));
  if length(v_note)>2000 then raise exception 'caregiver_note_too_long'; end if;
  if v_note='' then raise exception 'caregiver_note_empty'; end if;
  insert into private.appointment_caregiver_notes(appointment_id,note_text,updated_by,updated_at)
  values(v_ref.record_id,v_note,v_ref.actor_user_id,now())
  on conflict(appointment_id) do update
    set note_text=excluded.note_text,updated_by=excluded.updated_by,updated_at=now();
 elsif v_mode='clear' then
  delete from private.appointment_caregiver_notes where appointment_id=v_ref.record_id;
 end if;
 select c.note_text into v_note from private.appointment_caregiver_notes c
 where c.appointment_id=v_ref.record_id;
 return jsonb_build_object('ok',true,'record_code',substr(v_ref.record_id::text,1,12),
  'note',v_note,'has_note',v_note is not null and v_note<>'','may_edit',true);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_complete(p_line_user_id text, p_record_code text, p_outcome_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_old jsonb;
  v_new jsonb;
begin
  select * into v_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',p_record_code,'update'
  ) limit 1;

  select to_jsonb(a) into v_old from public.appointments a where a.id=v_ref.record_id;

  update public.appointments
  set status='completed',
      completed_at=coalesce(completed_at,now()),
      visit_outcome_notes=coalesce(nullif(btrim(p_outcome_notes),''),visit_outcome_notes),
      updated_at=now()
  where id=v_ref.record_id;

  select to_jsonb(a) into v_new from public.appointments a where a.id=v_ref.record_id;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    old_data,new_data,description
  )
  values(
    v_ref.active_family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
    'appointment_completed','appointment',v_ref.record_id,
    v_old,v_new,'จบนัด/บันทึกว่าพบแพทย์แล้ว'
  );

  perform private.phms_sync_auto_appointment_reminders(now());

  return jsonb_build_object(
    'ok',true,'record_code',substr(v_ref.record_id::text,1,12),
    'status','completed','item',v_new
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_complete_task(p_line_user_id text, p_task_code text, p_status text DEFAULT 'completed'::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_code text:=lower(btrim(coalesce(p_task_code,'')));
  v_status text:=lower(btrim(coalesce(p_status,'completed')));
  v_count int;
  v_id uuid;
  v_appt_id uuid;
  v_ref record;
  v_task public.appointment_tasks%rowtype;
begin
  if v_status not in ('completed','skipped') then raise exception 'invalid_task_status'; end if;
  if length(v_code)<8 then raise exception 'task_code_too_short'; end if;

  select count(*) into v_count
  from public.appointment_tasks t
  where lower(t.id::text) like v_code||'%'
    and t.status='pending';

  if v_count=0 then raise exception 'task_not_found'; end if;
  if v_count>1 then raise exception 'task_code_ambiguous'; end if;

  select t.id,t.appointment_id
  into v_id,v_appt_id
  from public.appointment_tasks t
  where lower(t.id::text) like v_code||'%'
    and t.status='pending'
  order by t.id::text
  limit 1;

  select * into v_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',substr(v_appt_id::text,1,12),'update'
  )
  limit 1;

  if v_ref.record_id is distinct from v_appt_id then
    raise exception 'task_appointment_context_mismatch';
  end if;

  update public.appointment_tasks
  set status=v_status,
      completed_at=now(),
      completed_by=v_ref.actor_user_id,
      note=coalesce(nullif(btrim(p_note),''),note),
      updated_at=now()
  where id=v_id
  returning * into v_task;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    new_data,description
  )
  values(
    v_ref.active_family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
    'appointment_task_'||v_status,'appointment',v_ref.record_id,
    to_jsonb(v_task),
    case when v_status='completed'
      then 'ทำสิ่งที่ต้องเตรียมก่อนนัดแล้ว'
      else 'ข้ามสิ่งที่ต้องเตรียมก่อนนัด'
    end
  );

  return jsonb_build_object(
    'ok',true,
    'appointment_id',v_ref.record_id,
    'appointment_code',substr(v_ref.record_id::text,1,12),
    'task_code',substr(v_task.id::text,1,12),
    'status',v_task.status,
    'task',to_jsonb(v_task)
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_confirm_with_assignee_policy(p_line_user_id text, p_record_code text, p_ack_days_before integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_confirm jsonb;
  v_policy jsonb;
begin
  -- ยืนยันนัดก่อน เพื่อให้คำขอรับทราบของผู้รับผิดชอบเริ่มทำงานได้
  v_confirm:=public.phms_line_appointment_set_visit_status(
