CREATE OR REPLACE FUNCTION public.phms_line_appointment_finance_upsert_core(p_line_user_id text, p_record_code text, p_paid_amount numeric, p_coverage_used boolean DEFAULT false, p_coverage_type text DEFAULT NULL::text, p_covered_amount numeric DEFAULT NULL::numeric, p_payment_method text DEFAULT NULL::text, p_payer text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_items jsonb DEFAULT NULL::jsonb, p_payment_method_code text DEFAULT NULL::text, p_payer_user_id uuid DEFAULT NULL::uuid, p_payer_family_person_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_sensitive record;
  v_appt public.appointments%rowtype;
  v_expense_id uuid;
  v_paid numeric(14,2);
  v_covered numeric(14,2);
  v_coverage text;
  v_method text;
  v_method_code text;
  v_payer text;
  v_payer_user_id uuid;
  v_payer_family_person_id uuid;
  v_status text;
  v_item jsonb;
  v_category text;
  v_label text;
  v_amount numeric(14,2);
  v_note text;
  v_sort integer:=0;
  v_breakdown_total numeric(14,2):=0;
  v_input_breakdown_total numeric(14,2):=0;
  v_input_item_count integer:=0;
  v_doc_count integer:=0;
  v_old jsonb;
  v_new jsonb;
  v_cgd_category text;
  v_cgd_item_code text;
  v_cgd_item_name text;
  v_hospital_item_code text;
  v_cgd_reference_rate numeric(14,2);
  v_cgd_rate_effective_date date;
  v_cgd_source_ref text;
  v_cgd_match_status text;
  v_linked_user_id uuid;
begin
  if p_paid_amount is null then raise exception 'paid_amount_required'; end if;
  v_paid:=round(p_paid_amount::numeric,2);
  if v_paid < 0 then raise exception 'paid_amount_invalid'; end if;

  if p_covered_amount is not null then
    v_covered:=round(p_covered_amount::numeric,2);
    if v_covered < 0 then raise exception 'covered_amount_invalid'; end if;
  end if;

  select * into v_ref
  from private.phms_line_appointment_access(
    p_line_user_id,p_record_code
  )
  limit 1;

  select * into v_sensitive
  from private.phms_line_appointment_sensitive_access(
    p_line_user_id,p_record_code
  )
  limit 1;

  if coalesce(v_sensitive.can_view_sensitive,false) is not true
     or coalesce(v_sensitive.can_update_appointments,false) is not true then
    raise exception 'appointment_finance_update_not_accessible';
  end if;

  select * into v_appt
  from public.appointments
  where id=v_ref.record_id
  limit 1;

  v_coverage:=nullif(btrim(coalesce(p_coverage_type,'')),'');
  if coalesce(p_coverage_used,false) and v_coverage is null then
    v_coverage:=nullif(btrim(coalesce(v_appt.coverage_type,'')),'');
  end if;

  v_method_code:=nullif(lower(btrim(coalesce(p_payment_method_code,''))),'');
  if v_method_code is null and nullif(btrim(coalesce(p_payment_method,'')),'') is not null then
    v_method_code:=case
      when lower(p_payment_method) ~ '(qr|promptpay|สแกน)' then 'promptpay_qr'
      when lower(p_payment_method) ~ '(เงินสด|cash)' then 'cash'
      when lower(p_payment_method) ~ '(บัตรเครดิต|credit)' then 'credit_card'
      when lower(p_payment_method) ~ '(บัตรเดบิต|debit)' then 'debit_card'
      when lower(p_payment_method) ~ '(โอน|transfer|mobile banking)' then 'bank_transfer'
      when lower(p_payment_method) ~ '(wallet|วอลเล็ต|กระเป๋าเงิน)' then 'e_wallet'
      else 'other'
    end;
  end if;

  if v_method_code is not null
     and v_method_code not in (
       'promptpay_qr','cash','credit_card','debit_card',
       'bank_transfer','e_wallet','other'
     ) then
    raise exception 'payment_method_invalid';
  end if;

  v_method:=case v_method_code
    when 'promptpay_qr' then 'สแกนจ่าย / QR'
    when 'cash' then 'เงินสด'
    when 'credit_card' then 'บัตรเครดิต'
    when 'debit_card' then 'บัตรเดบิต'
    when 'bank_transfer' then 'โอนเงิน / Mobile Banking'
    when 'e_wallet' then 'E-Wallet'
    when 'other' then 'อื่น ๆ'
    else nullif(btrim(coalesce(p_payment_method,'')),'')
  end;

  v_payer_user_id:=p_payer_user_id;
  v_payer_family_person_id:=p_payer_family_person_id;

  if v_payer_family_person_id is not null then
    select p.linked_user_id
    into v_linked_user_id
    from public.family_persons fp
    join public.persons p on p.id=fp.person_id
    where fp.id=v_payer_family_person_id
      and fp.family_id=v_ref.active_family_id
      and coalesce(fp.status,'active')='active'
      and coalesce(p.status,'active')='active'
      and private.family_person_is_visible_to_user(v_ref.actor_user_id,fp.id)
    limit 1;

    if not found then raise exception 'payer_family_person_invalid'; end if;

    v_payer:=private.family_person_label_for_viewer(
      v_ref.actor_user_id,v_payer_family_person_id
    );
    if v_payer_user_id is null then v_payer_user_id:=v_linked_user_id; end if;
  elsif v_payer_user_id is not null then
    if not exists(
      select 1
      from public.family_memberships fm
      where fm.family_id=v_ref.active_family_id
        and fm.user_id=v_payer_user_id
        and fm.status='active'
    ) then
      raise exception 'payer_user_invalid';
    end if;

    v_payer:=private.family_user_label_for_viewer(
      v_ref.actor_user_id,v_ref.active_family_id,v_payer_user_id
    );
  else
    v_payer:=nullif(btrim(coalesce(p_payer,'')),'');
  end if;

  if v_paid > 0 and v_method_code is null then
    raise exception 'payment_method_required';
  end if;
  if v_paid > 0 and v_payer_user_id is null and v_payer_family_person_id is null then
    raise exception 'payer_member_required';
  end if;

  if v_paid=0 then
    v_method_code:=null;
    v_method:=null;
    v_payer:=null;
    v_payer_user_id:=null;
    v_payer_family_person_id:=null;
  end if;

  if p_items is not null then
    if jsonb_typeof(p_items)<>'array' then raise exception 'expense_items_must_be_array'; end if;
    v_input_item_count:=jsonb_array_length(p_items);

    if v_input_item_count>0 then
      for v_item in select value from jsonb_array_elements(p_items)
      loop
        begin
          v_amount:=round((v_item->>'amount')::numeric,2);
        exception when others then
          raise exception 'expense_item_amount_invalid';
        end;
        if v_amount < 0 then raise exception 'expense_item_amount_invalid'; end if;
        v_input_breakdown_total:=v_input_breakdown_total+v_amount;
      end loop;

      if abs(v_paid-v_input_breakdown_total)>=0.01 then
        raise exception 'breakdown_total_mismatch:paid=%:items=%:diff=%',
          v_paid,v_input_breakdown_total,round(v_paid-v_input_breakdown_total,2);
      end if;
    end if;
  end if;

  v_status:=case
    when v_paid=0 and coalesce(p_coverage_used,false) then 'covered_no_payment'
    when v_paid=0 then 'no_charge'
    when coalesce(p_coverage_used,false) then 'covered_with_copay'
    else 'self_pay'
  end;

  select to_jsonb(e),e.id into v_old,v_expense_id
  from public.healthcare_expenses e
  where e.appointment_id=v_ref.record_id
    and e.deleted_at is null
  order by e.created_at desc
  limit 1;

  if v_expense_id is null then
    insert into public.healthcare_expenses(
      person_id,encounter_id,organization_id,appointment_id,expense_date,currency,
      total_amount,paid_amount,payer,payer_user_id,payer_family_person_id,
      payment_method,payment_method_code,notes,created_by,
      coverage_used,coverage_type,covered_amount,payment_status,payment_recorded_at
    )
    values(
      v_ref.target_person_id,v_appt.encounter_id,v_appt.organization_id,v_ref.record_id,
      coalesce((v_appt.appointment_at at time zone 'Asia/Bangkok')::date,current_date),
      'THB',
      case when v_covered is null then v_paid else v_paid+v_covered end,
      v_paid,v_payer,v_payer_user_id,v_payer_family_person_id,
      v_method,v_method_code,nullif(btrim(coalesce(p_notes,'')),''),
      v_ref.actor_user_id,
      coalesce(p_coverage_used,false),v_coverage,v_covered,v_status,now()
    )
    returning id into v_expense_id;
  else
    update public.healthcare_expenses
    set encounter_id=v_appt.encounter_id,
        organization_id=v_appt.organization_id,
        expense_date=coalesce((v_appt.appointment_at at time zone 'Asia/Bangkok')::date,expense_date,current_date),
        currency='THB',
        total_amount=case when v_covered is null then v_paid else v_paid+v_covered end,
        paid_amount=v_paid,
        payer=v_payer,
        payer_user_id=v_payer_user_id,
        payer_family_person_id=v_payer_family_person_id,
        payment_method=v_method,
        payment_method_code=v_method_code,
        notes=nullif(btrim(coalesce(p_notes,'')),''),
        coverage_used=coalesce(p_coverage_used,false),
        coverage_type=v_coverage,
        covered_amount=v_covered,
        payment_status=v_status,
        payment_recorded_at=now(),
        updated_at=now()
    where id=v_expense_id;
  end if;

  if p_items is not null then
    update public.healthcare_expense_items
    set deleted_at=now(),updated_at=now()
    where expense_id=v_expense_id and deleted_at is null;

    for v_item in select value from jsonb_array_elements(p_items)
    loop
      v_label:=nullif(btrim(coalesce(v_item->>'label','')),'');
      if v_label is null then continue; end if;

      v_amount:=round((v_item->>'amount')::numeric,2);

      v_category:=lower(btrim(coalesce(v_item->>'category','other')));
      if v_category not in (
        'consultation','medication','lab','imaging','procedure',
        'medical_supply','room','registration','transport','other'
      ) then
        v_category:='other';
      end if;

      v_cgd_category:=nullif(lpad(regexp_replace(coalesce(v_item->>'cgd_category_code',''),'[^0-9]','','g'),2,'0'),'00');
      if v_cgd_category is null then
        v_cgd_category:=case v_category
          when 'room' then '01'
          when 'medication' then '03'
          when 'medical_supply' then '05'
          when 'lab' then '07'
          when 'imaging' then '08'
          when 'procedure' then '11'
          when 'registration' then '16'
          else null
        end;
      end if;
      if v_cgd_category is not null and not exists(
        select 1 from public.cgd_medical_service_categories c
        where c.code=v_cgd_category and c.is_active
      ) then
        raise exception 'cgd_category_invalid';
      end if;

      v_cgd_item_code:=nullif(btrim(coalesce(v_item->>'cgd_item_code','')),'');
      v_cgd_item_name:=nullif(btrim(coalesce(v_item->>'cgd_item_name','')),'');
      v_hospital_item_code:=nullif(btrim(coalesce(v_item->>'hospital_item_code','')),'');
      v_cgd_source_ref:=nullif(btrim(coalesce(v_item->>'cgd_source_ref','')),'');
      v_cgd_match_status:=lower(btrim(coalesce(v_item->>'cgd_match_status','')));
      if v_cgd_match_status not in ('unmapped','category_only','item_code_provided','verified') then
        v_cgd_match_status:=case
          when v_cgd_item_code is not null then 'item_code_provided'
          when v_cgd_category is not null then 'category_only'
          else 'unmapped'
        end;
      end if;

      v_cgd_reference_rate:=null;
      if nullif(btrim(coalesce(v_item->>'cgd_reference_rate','')),'') is not null then
        begin
          v_cgd_reference_rate:=round((v_item->>'cgd_reference_rate')::numeric,2);
        exception when others then raise exception 'cgd_reference_rate_invalid';
        end;
        if v_cgd_reference_rate < 0 then raise exception 'cgd_reference_rate_invalid'; end if;
      end if;

      v_cgd_rate_effective_date:=null;
      if nullif(btrim(coalesce(v_item->>'cgd_rate_effective_date','')),'') is not null then
        begin
          v_cgd_rate_effective_date:=(v_item->>'cgd_rate_effective_date')::date;
        exception when others then raise exception 'cgd_rate_effective_date_invalid';
        end;
      end if;

      v_note:=nullif(btrim(coalesce(v_item->>'note','')),'');
      v_sort:=v_sort+1;

      insert into public.healthcare_expense_items(
        expense_id,category,label,amount,note,sort_order,created_by,
        cgd_category_code,cgd_item_code,cgd_item_name,hospital_item_code,
        cgd_reference_rate,cgd_rate_effective_date,cgd_source_ref,cgd_match_status
      )
      values(
        v_expense_id,v_category,v_label,v_amount,v_note,v_sort,v_ref.actor_user_id,
        v_cgd_category,v_cgd_item_code,v_cgd_item_name,v_hospital_item_code,
        v_cgd_reference_rate,v_cgd_rate_effective_date,v_cgd_source_ref,v_cgd_match_status
      );
    end loop;
  end if;

  select coalesce(sum(i.amount),0)
  into v_breakdown_total
  from public.healthcare_expense_items i
  where i.expense_id=v_expense_id and i.deleted_at is null;

  select count(*)::int
  into v_doc_count
  from public.appointment_document_links l
  where l.appointment_id=v_ref.record_id
    and l.link_kind in ('receipt','payment_slip','payment_qr','payment_other');

  select to_jsonb(e) into v_new
  from public.healthcare_expenses e
  where e.id=v_expense_id;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    old_data,new_data,description
  )
  values(
    v_ref.active_family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
    'appointment_finance_updated','appointment',v_ref.record_id,
    v_old,
    jsonb_build_object(
      'expense',v_new,
      'breakdown_total',v_breakdown_total,
      'payment_document_count',v_doc_count
    ),
    'บันทึกค่าใช้จ่ายหลังนัด'
  );

  return jsonb_build_object(
    'ok',true,
    'record_code',substr(v_ref.record_id::text,1,12),
    'expense_id',v_expense_id,
    'currency','THB',
    'paid_amount',v_paid,
    'coverage_used',coalesce(p_coverage_used,false),
    'coverage_type',v_coverage,
    'covered_amount',v_covered,
    'payment_status',v_status,
    'payment_method',v_method,
    'payment_method_code',v_method_code,
    'payer',v_payer,
    'payer_user_id',v_payer_user_id,
    'payer_family_person_id',v_payer_family_person_id,
    'breakdown_total',v_breakdown_total,
    'breakdown_difference',round(v_paid-v_breakdown_total,2),
    'breakdown_complete',case
      when p_items is null or jsonb_array_length(p_items)=0 then null
      else abs(v_paid-v_breakdown_total)<0.01
    end,
    'payment_document_count',v_doc_count
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_get_task(p_line_user_id text, p_task_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_code text:=lower(btrim(coalesce(p_task_code,'')));
  v_count int;
  v_task public.appointment_tasks%rowtype;
  v_ref record;
begin
  if length(v_code)<8 then raise exception 'task_code_too_short'; end if;

  select count(*)
  into v_count
  from public.appointment_tasks t
  where lower(t.id::text) like v_code||'%';

  if v_count=0 then raise exception 'task_not_found'; end if;
  if v_count>1 then raise exception 'task_code_ambiguous'; end if;

  select *
  into v_task
  from public.appointment_tasks t
  where lower(t.id::text) like v_code||'%'
  limit 1;

  select * into v_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',substr(v_task.appointment_id::text,1,12),'update'
  )
  limit 1;

  return jsonb_build_object(
    'ok',true,
    'appointment_code',substr(v_task.appointment_id::text,1,12),
    'task_code',substr(v_task.id::text,1,12),
    'task',jsonb_strip_nulls(to_jsonb(v_task))
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_link_existing_asset(p_line_user_id text, p_record_code text, p_storage_asset_id uuid, p_link_kind text DEFAULT 'result'::text, p_usage_relation text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_asset public.phms_storage_assets%rowtype;
  v_doc uuid;
  v_kind text:=lower(btrim(coalesce(p_link_kind,'result')));
  v_relation text:=nullif(lower(btrim(coalesce(p_usage_relation,''))),'');
  v_origin_appointment_id uuid;
  v_existing_count int:=0;
  v_link public.appointment_document_links%rowtype;
begin
  if p_storage_asset_id is null then raise exception 'storage_asset_required'; end if;

  if v_kind not in (
    'source','preparation','result','certificate','referral','other',
    'receipt','payment_slip','payment_qr','payment_other'
  ) then
    v_kind:='result';
  end if;

  if v_relation is not null
     and v_relation not in ('origin','carry_forward','referral','cross_condition','supporting') then
    raise exception 'appointment_document_usage_relation_invalid';
  end if;

  select * into v_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',p_record_code,'update'
  )
  limit 1;
  if v_ref.active_family_person_id is null or not private.user_can_access_family_person(v_ref.actor_user_id,v_ref.active_family_person_id,'documents','update') then raise exception 'document_permission_denied';end if;
  if v_kind in ('receipt','payment_slip','payment_qr','payment_other') and not private.user_can_access_family_person(v_ref.actor_user_id,v_ref.active_family_person_id,'expenses','update') then raise exception 'expense_permission_denied';end if;


  select * into v_asset
  from public.phms_storage_assets
  where id=p_storage_asset_id
    and deleted_at is null;

  if not found then raise exception 'storage_asset_not_found'; end if;
  if v_asset.person_id is distinct from v_ref.target_person_id then
    raise exception 'appointment_asset_person_mismatch';
  end if;

  select md.id into v_doc
  from public.medical_documents md
  where md.storage_asset_id=v_asset.id
    and md.person_id=v_ref.target_person_id
    and md.deleted_at is null
  order by md.created_at desc
  limit 1;

  select
    count(*)::int,
    coalesce(
      (
        select coalesce(l.origin_appointment_id,l.appointment_id)
        from public.appointment_document_links l
        where l.storage_asset_id=v_asset.id
        order by
          case when l.usage_relation='origin' then 0 else 1 end,
          l.created_at,
          l.id
        limit 1
      ),
      v_ref.record_id
    )
  into v_existing_count,v_origin_appointment_id
  from public.appointment_document_links x
  where x.storage_asset_id=v_asset.id;

  if v_origin_appointment_id=v_ref.record_id then
    v_relation:='origin';
  elsif v_relation is null then
    v_relation:=case when v_existing_count>0 then 'supporting' else 'origin' end;
  end if;

  insert into public.appointment_document_links(
    appointment_id,medical_document_id,storage_asset_id,link_kind,note,created_by,
    usage_relation,origin_appointment_id
  )
  values(
    v_ref.record_id,v_doc,v_asset.id,v_kind,
    nullif(btrim(coalesce(p_note,'')),''),
    v_ref.actor_user_id,
    v_relation,
    v_origin_appointment_id
  )
  on conflict do nothing;

  select * into v_link
  from public.appointment_document_links
  where appointment_id=v_ref.record_id
    and storage_asset_id=v_asset.id
    and link_kind=v_kind
  order by created_at
  limit 1;

  if v_link.id is null then
    select * into v_link
    from public.appointment_document_links
    where appointment_id=v_ref.record_id
      and storage_asset_id=v_asset.id
    order by created_at
    limit 1;
  end if;

  update public.appointment_document_links
  set usage_relation=coalesce(v_relation,usage_relation),
      origin_appointment_id=coalesce(origin_appointment_id,v_origin_appointment_id),
      note=coalesce(nullif(btrim(coalesce(p_note,'')),''),note)
  where id=v_link.id;

  select * into v_link
  from public.appointment_document_links
  where id=v_link.id;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    new_data,description
  )
  values(
    v_ref.active_family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
    'appointment_document_linked','appointment',v_ref.record_id,
    jsonb_build_object(
      'appointment_document_link_id',v_link.id,
      'storage_asset_id',v_asset.id,
      'medical_document_id',v_doc,
      'link_kind',v_link.link_kind,
      'usage_relation',v_link.usage_relation,
      'origin_appointment_id',v_link.origin_appointment_id
    ),
    case
      when v_link.usage_relation='referral' then 'ใช้เอกสารเดิมสำหรับการส่งต่อ/ไปสถานพยาบาลอื่น'
      when v_link.usage_relation='carry_forward' then 'ใช้เอกสารเดิมต่อในนัดถัดไป'
      when v_link.usage_relation='cross_condition' then 'ใช้เอกสารเดิมประกอบอีกกลุ่มโรค/บริบท'
      when v_link.usage_relation='supporting' then 'ใช้เอกสารเดิมเป็นเอกสารประกอบนัด'
      else 'เชื่อมเอกสารต้นทางเข้ากับนัด'
    end
  );

  return jsonb_strip_nulls(jsonb_build_object(
    'ok',true,
    'appointment_code',substr(v_ref.record_id::text,1,12),
    'link_id',v_link.id,
    'storage_asset_id',v_asset.id,
    'medical_document_id',v_doc,
    'link_kind',v_link.link_kind,
    'usage_relation',v_link.usage_relation,
    'origin_appointment_code',case
      when v_link.origin_appointment_id is not null
      then substr(v_link.origin_appointment_id::text,1,12)
      else null
    end,
    'reused',v_link.origin_appointment_id is distinct from v_ref.record_id
  ));
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_link_existing_followup(p_line_user_id text, p_previous_record_code text, p_next_record_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_prev_ref record;
  v_next_ref record;
  v_prev public.appointments%rowtype;
  v_next public.appointments%rowtype;
  v_result jsonb;
begin
  select * into v_prev_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',p_previous_record_code,'update'
  ) limit 1;

  select * into v_next_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',p_next_record_code,'update'
  ) limit 1;

  if v_prev_ref.record_id=v_next_ref.record_id then
    raise exception 'followup_same_appointment';
  end if;

  select * into v_prev
  from public.appointments
  where id=v_prev_ref.record_id and deleted_at is null;

  select * into v_next
  from public.appointments
  where id=v_next_ref.record_id and deleted_at is null;

  if v_prev.person_id is distinct from v_next.person_id then
    raise exception 'followup_person_mismatch';
  end if;

  if v_prev.appointment_at is null or v_next.appointment_at is null
     or v_next.appointment_at<=v_prev.appointment_at then
    raise exception 'followup_must_be_later';
  end if;

  if v_next.status in ('cancelled','no_show') then
    raise exception 'followup_next_not_active';
  end if;

  select public.phms_line_appointment_link_pair_auto(
    p_line_user_id,p_previous_record_code,p_next_record_code
  ) into v_result;

  return jsonb_build_object(
    'ok',true,
    'previous_record_code',substr(v_prev.id::text,1,12),
    'next_record_code',substr(v_next.id::text,1,12),
    'next_appointment_at',v_next.appointment_at,
    'next_title',v_next.title,
    'next_hospital_name',v_next.hospital_name,
    'changed',coalesce((v_result->>'changed')::boolean,false),
    'already_connected',coalesce((v_result->>'already_connected')::boolean,false),
    'group_size',coalesce((v_result->>'group_size')::integer,2)
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_link_pair_auto(p_line_user_id text, p_record_code_a text, p_record_code_b text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_a_ref record;
  v_b_ref record;
  v_a public.appointments%rowtype;
  v_b public.appointments%rowtype;
  v_prev public.appointments%rowtype;
  v_next public.appointments%rowtype;
  v_edge_a uuid;
  v_edge_b uuid;
  v_old_next jsonb;
  v_new_next jsonb;
  v_already_connected boolean := false;
  v_primary_changed boolean := false;
  v_component_size integer := 0;
begin
  select * into v_a_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',p_record_code_a,'update'
  ) limit 1;

  select * into v_b_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',p_record_code_b,'update'
  ) limit 1;

  if v_a_ref.record_id=v_b_ref.record_id then
    raise exception 'appointment_link_same_appointment';
  end if;

  select * into v_a
  from public.appointments
  where id=v_a_ref.record_id and deleted_at is null;

  select * into v_b
  from public.appointments
  where id=v_b_ref.record_id and deleted_at is null;

  if not found or v_a.id is null or v_b.id is null then
    raise exception 'appointment_not_found';
  end if;

  if v_a.person_id is distinct from v_b.person_id then
    raise exception 'appointment_link_person_mismatch';
  end if;

  if v_a.status in ('cancelled','no_show')
     or v_b.status in ('cancelled','no_show') then
    raise exception 'appointment_link_inactive';
  end if;

  if v_a.appointment_at is null or v_b.appointment_at is null then
    raise exception 'appointment_link_time_required';
  end if;

  if v_a.appointment_at=v_b.appointment_at then
    raise exception 'appointment_link_same_time';
  elsif v_a.appointment_at<v_b.appointment_at then
    v_prev:=v_a;
    v_next:=v_b;
  else
    v_prev:=v_b;
    v_next:=v_a;
  end if;

  select exists(
    select 1
    from private.phms_appointment_component(v_a.id,200) c
    where c.appointment_id=v_b.id
  ) into v_already_connected;

  if v_already_connected then
    select count(*)::int into v_component_size
    from private.phms_appointment_component(v_a.id,200);

    return jsonb_build_object(
      'ok',true,
      'changed',false,
      'already_connected',true,
      'group_size',v_component_size,
      'previous_record_code',substr(v_prev.id::text,1,12),
      'previous_appointment_at',v_prev.appointment_at,
      'previous_title',v_prev.title,
      'previous_hospital_name',v_prev.hospital_name,
      'next_record_code',substr(v_next.id::text,1,12),
      'next_appointment_at',v_next.appointment_at,
      'next_title',v_next.title,
      'next_hospital_name',v_next.hospital_name
    );
  end if;

  if v_a.id < v_b.id then
    v_edge_a:=v_a.id; v_edge_b:=v_b.id;
  else
    v_edge_a:=v_b.id; v_edge_b:=v_a.id;
  end if;

  insert into private.appointment_links(
    appointment_id_a,appointment_id_b,link_kind,source,created_by
  )
  values(
    v_edge_a,v_edge_b,'continuity','line_manual',
    v_a_ref.actor_user_id
  )
  on conflict do nothing;

  v_old_next:=to_jsonb(v_next);

  if v_next.followup_of_appointment_id is null then
    update public.appointments
    set followup_of_appointment_id=v_prev.id,
        appointment_type=case
          when nullif(btrim(appointment_type),'') is null
            or appointment_type='scheduled'
          then 'follow_up'
          else appointment_type
        end,
        updated_at=now()
    where id=v_next.id;
    v_primary_changed:=true;
  end if;

  update public.appointments
  set followup_required=true,
      followup_recorded_at=coalesce(followup_recorded_at,now()),
      updated_at=now()
  where id=v_prev.id;

  select to_jsonb(a)
  into v_new_next
  from public.appointments a
  where a.id=v_next.id;

  select count(*)::int into v_component_size
  from private.phms_appointment_component(v_a.id,200);

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    old_data,new_data,description
  )
  values(
    v_next.family_id,
    v_a_ref.actor_user_id,
    v_next.family_person_id,
    'appointment_link_group_merge',
    'appointment',
    v_next.id,
    v_old_next,
    v_new_next,
    'เชื่อมนัดเข้ากลุ่มความต่อเนื่องเดียวกัน โดยคงลิงก์เดิมของนัดอื่นไว้'
  );

  return jsonb_build_object(
    'ok',true,
    'changed',true,
    'already_connected',false,
    'group_size',v_component_size,
    'primary_followup_changed',v_primary_changed,
    'previous_record_code',substr(v_prev.id::text,1,12),
    'previous_appointment_at',v_prev.appointment_at,
    'previous_title',v_prev.title,
    'previous_hospital_name',v_prev.hospital_name,
    'next_record_code',substr(v_next.id::text,1,12),
    'next_appointment_at',v_next.appointment_at,
    'next_title',v_next.title,
    'next_hospital_name',v_next.hospital_name,
    'replaced_previous_record_code',null
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_manage_task(p_line_user_id text, p_task_code text, p_status text DEFAULT NULL::text, p_title text DEFAULT NULL::text, p_instruction text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_code text:=lower(btrim(coalesce(p_task_code,'')));
  v_count int;
  v_id uuid;
  v_appt_id uuid;
  v_ref record;
  v_task public.appointment_tasks%rowtype;
  v_status text:=nullif(lower(btrim(coalesce(p_status,''))),'');
begin
  if length(v_code)<8 then raise exception 'task_code_too_short'; end if;
  if v_status is not null
     and v_status not in ('pending','completed','skipped','cancelled') then
    raise exception 'invalid_task_status';
  end if;

  select count(*) into v_count
  from public.appointment_tasks t
  where lower(t.id::text) like v_code||'%';

  if v_count=0 then raise exception 'task_not_found'; end if;
  if v_count>1 then raise exception 'task_code_ambiguous'; end if;

  select t.id,t.appointment_id
  into v_id,v_appt_id
  from public.appointment_tasks t
  where lower(t.id::text) like v_code||'%'
  order by t.id::text
  limit 1;

  select * into v_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',substr(v_appt_id::text,1,12),'update'
  ) limit 1;

  if v_ref.record_id is distinct from v_appt_id then
    raise exception 'task_appointment_context_mismatch';
  end if;

  update public.appointment_tasks
  set
    status=coalesce(v_status,status),
    title=case
      when p_title is null then title
      when nullif(btrim(p_title),'') is null then title
      else btrim(p_title)
    end,
    instruction=case
      when p_instruction is null then instruction
      when btrim(p_instruction)='-' then null
      else nullif(btrim(p_instruction),'')
    end,
    note=case
      when p_note is null then note
      when btrim(p_note)='-' then null
      else nullif(btrim(p_note),'')
    end,
    completed_at=case
      when coalesce(v_status,status) in ('completed','skipped')
        then coalesce(completed_at,now())
      when coalesce(v_status,status)='pending' then null
      else completed_at
    end,
    completed_by=case
      when coalesce(v_status,status) in ('completed','skipped')
        then coalesce(completed_by,v_ref.actor_user_id)
      when coalesce(v_status,status)='pending' then null
      else completed_by
    end,
    updated_at=now()
  where id=v_id
  returning * into v_task;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    new_data,description
  ) values(
    v_ref.active_family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
    case
      when v_task.status='completed' then 'appointment_task_completed'
      when v_task.status='skipped' then 'appointment_task_skipped'
      when v_task.status='pending' then 'appointment_task_reopened'
      else 'appointment_task_updated'
    end,
    'appointment',v_ref.record_id,to_jsonb(v_task),
    case
      when v_task.status='completed' then 'ทำรายการเตรียมก่อนนัดเสร็จแล้ว'
      when v_task.status='skipped' then 'ข้ามรายการเตรียมก่อนนัด'
      when v_task.status='pending' then 'เปลี่ยนกลับเป็นยังไม่เสร็จ'
      else 'แก้รายการเตรียมก่อนนัด'
    end
  );

  return jsonb_build_object(
    'ok',true,
    'appointment_code',substr(v_ref.record_id::text,1,12),
    'task_code',substr(v_task.id::text,1,12),
    'status',v_task.status,
    'task',to_jsonb(v_task)
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_manual_notify(p_line_user_id text, p_record_code text, p_change_kind text DEFAULT 'updated'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_appt public.appointments%rowtype;
  v_rec record;
  v_group record;
  v_kind text:=lower(btrim(coalesce(p_change_kind,'updated')));
  v_title text;
  v_user_count int:=0;
  v_group_count int:=0;
  v_event_key text;
  v_mode text;
  v_person_label text;
  v_sender_label text;
  v_group_person_label text;
  v_group_sender_label text;
  v_message text;
begin
  if v_kind not in ('created','updated') then v_kind:='updated'; end if;

  select * into v_ref
  from private.phms_find_crud_record(p_line_user_id,'appointment',p_record_code,'update')
  limit 1;

  select * into v_appt
  from public.appointments
  where id=v_ref.record_id and deleted_at is null;
  if not found then raise exception 'appointment_not_found'; end if;

  select coalesce(s.recipient_mode,'default') into v_mode
  from (select 1) x
  left join public.appointment_notification_settings s on s.appointment_id=v_appt.id;

  v_title:=case when v_kind='created' then '📅 มีนัดหมายใหม่' else '✏️ อัปเดตนัดหมาย' end;
  v_event_key:=coalesce(
    to_char(v_appt.updated_at at time zone 'UTC','YYYYMMDDHH24MISSMS'),
    to_char(now() at time zone 'UTC','YYYYMMDDHH24MISSMS')
  );

  for v_rec in
    select x.recipient_user_id
    from (
      select r.recipient_user_id
      from private.phms_notification_recipients(v_appt.person_id,'appointments') r
      where v_mode='default' and r.recipient_user_id<>v_ref.actor_user_id
      union
      select t.user_id
      from public.appointment_notification_user_targets t
      where v_mode='custom' and t.appointment_id=v_appt.id and t.enabled=true
        and exists(
          select 1 from private.phms_notification_recipients(v_appt.person_id,'appointments') r2
          where r2.recipient_user_id=t.user_id
        )
    ) x
  loop
    v_person_label:=private.phms_notification_person_label(
      v_rec.recipient_user_id,v_appt.person_id,v_appt.family_person_id
    );
    v_sender_label:=private.family_user_label_for_viewer(
      v_rec.recipient_user_id,v_appt.family_id,v_ref.actor_user_id
    );
    v_message:=concat(
      '👤 ',v_person_label,
      E'\nนัดเพื่อ: ',coalesce(nullif(btrim(v_appt.title),''),'นัดหมาย'),
      E'\nวันเวลา: ',to_char(v_appt.appointment_at at time zone 'Asia/Bangkok','DD/MM/YYYY HH24:MI'),
      E'\nส่งโดย: ',v_sender_label
    );

    insert into public.notifications(
      family_id,recipient_user_id,person_id,family_person_id,event_type,title,message,related_record_id,
      channel,priority,status,scheduled_for,next_attempt_at,payload,dedupe_key,created_at,updated_at
    ) values(
      v_appt.family_id,v_rec.recipient_user_id,v_appt.person_id,v_appt.family_person_id,
      case when v_kind='created' then 'appointment_created_manual' else 'appointment_updated_manual' end,
      v_title,v_message,v_appt.id,'line','normal','pending',now(),now(),
      jsonb_strip_nulls(jsonb_build_object(
        'appointment_id',v_appt.id,
        'appointment_code',substr(v_appt.id::text,1,12),
        'appointment_at',v_appt.appointment_at,
        'appointment_status',v_appt.status,
        'appointment_title',coalesce(nullif(btrim(v_appt.title),''),'นัดหมาย'),
        'hospital_name',nullif(btrim(v_appt.hospital_name),''),
        'department',nullif(btrim(v_appt.department),''),
        'doctor_name',nullif(btrim(v_appt.doctor_name),''),
        'location_detail',nullif(btrim(v_appt.location_detail),''),
        'person_name',v_person_label,
        'sent_by_name',v_sender_label,
        'manual_send',true,
        'change_kind',v_kind
      )),
      'appointment-manual:'||v_appt.id::text||':'||v_event_key||':user:'||v_rec.recipient_user_id::text,
      now(),now()
    )
    on conflict(dedupe_key) where dedupe_key is not null
    do update set title=excluded.title,message=excluded.message,payload=excluded.payload,status='pending',
      scheduled_for=now(),next_attempt_at=now(),last_error=null,updated_at=now();

    v_user_count:=v_user_count+1;
  end loop;

  v_group_person_label:=private.phms_group_person_label(v_appt.person_id,v_appt.family_person_id);
  v_group_sender_label:=private.family_user_central_nickname(v_appt.family_id,v_ref.actor_user_id);

  for v_group in
    select gt.id,gt.line_group_id
    from public.appointment_line_group_targets gt
    where gt.appointment_id=v_appt.id and gt.status='active'
  loop
    v_message:=concat(
      '👤 ',v_group_person_label,
      E'\nนัดเพื่อ: ',coalesce(nullif(btrim(v_appt.title),''),'นัดหมาย'),
      E'\nวันเวลา: ',to_char(v_appt.appointment_at at time zone 'Asia/Bangkok','DD/MM/YYYY HH24:MI'),
      E'\nส่งโดย: ',v_group_sender_label
    );

    insert into public.notifications(
      family_id,recipient_user_id,person_id,family_person_id,event_type,title,message,related_record_id,
      channel,priority,status,scheduled_for,next_attempt_at,payload,dedupe_key,created_at,updated_at
    ) values(
      v_appt.family_id,null,v_appt.person_id,v_appt.family_person_id,
      case when v_kind='created' then 'appointment_created_manual_group' else 'appointment_updated_manual_group' end,
      v_title,v_message,v_appt.id,'line','normal','pending',now(),now(),
      jsonb_strip_nulls(jsonb_build_object(
        'appointment_id',v_appt.id,
        'appointment_code',substr(v_appt.id::text,1,12),
        'appointment_at',v_appt.appointment_at,
        'appointment_status',v_appt.status,
        'appointment_title',coalesce(nullif(btrim(v_appt.title),''),'นัดหมาย'),
        'hospital_name',nullif(btrim(v_appt.hospital_name),''),
        'department',nullif(btrim(v_appt.department),''),
        'doctor_name',nullif(btrim(v_appt.doctor_name),''),
        'location_detail',nullif(btrim(v_appt.location_detail),''),
        'person_name',v_group_person_label,
        'sent_by_name',v_group_sender_label,
        'manual_send',true,
        'change_kind',v_kind,
        'line_destination_type','group',
        'line_destination_id',v_group.line_group_id,
        'group_target_id',v_group.id
      )),
      'appointment-manual:'||v_appt.id::text||':'||v_event_key||':group:'||v_group.id::text,
      now(),now()
    )
    on conflict(dedupe_key) where dedupe_key is not null
    do update set title=excluded.title,message=excluded.message,payload=excluded.payload,status='pending',
      scheduled_for=now(),next_attempt_at=now(),last_error=null,updated_at=now();

    v_group_count:=v_group_count+1;
  end loop;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,new_data,description
  ) values(
    v_ref.active_family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
    'appointment_manual_notification_sent','appointment',v_ref.record_id,
    jsonb_build_object(
      'change_kind',v_kind,'recipient_mode',v_mode,
      'user_notifications',v_user_count,'group_notifications',v_group_count
    ),
    'ผู้ใช้เลือกส่งแจ้งเตือนการเปลี่ยนแปลงนัด'
  );

  return jsonb_build_object(
    'ok',true,'record_code',substr(v_appt.id::text,1,12),'change_kind',v_kind,
    'recipient_mode',v_mode,'user_notifications',v_user_count,'group_notifications',v_group_count
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_metadata(p_line_user_id text, p_record_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_creator text;
  v_created_at timestamptz;
  v_groups int;
begin
  select * into v_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',p_record_code,'view'
  ) limit 1;

  select
    private.family_user_label_for_viewer(v_ref.actor_user_id,v_ref.active_family_id,a.created_by),
    a.created_at,
    (select count(*) from public.appointment_line_group_targets gt
      where gt.appointment_id=a.id and gt.status='active')
  into v_creator,v_created_at,v_groups
  from public.appointments a
  where a.id=v_ref.record_id;

  return jsonb_build_object(
    'ok',true,
    'record_code',substr(v_ref.record_id::text,1,12),
    'created_by_name',v_creator,
    'created_at',v_created_at,
    'active_group_target_count',coalesce(v_groups,0)
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_notify_now(p_line_user_id text, p_record_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_appt public.appointments%rowtype;
  v_person public.persons%rowtype;
  v_mode text;
  v_rec record;
  v_group record;
  v_user_count integer:=0;
  v_group_count integer:=0;
  v_request_id uuid:=gen_random_uuid();
  v_title text:='🔔 แจ้งเตือนนัดหมาย';
  v_message text;
  v_person_name text;
begin
  select * into v_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',p_record_code,'update'
  ) limit 1;

  select * into v_appt
  from public.appointments
  where id=v_ref.record_id and deleted_at is null;
  if not found then raise exception 'appointment_not_found'; end if;

  select * into v_person from public.persons where id=v_appt.person_id;

  select coalesce(s.recipient_mode,'default')
  into v_mode
  from (select 1) x
  left join public.appointment_notification_settings s
    on s.appointment_id=v_appt.id;

  v_person_name:=coalesce(
    nullif(btrim(v_person.display_name),''),
    nullif(btrim(concat_ws(' ',v_person.first_name,v_person.last_name)),''),
    v_ref.target_person_name,
    'บุคคลในครอบครัว'
  );

  v_message:=concat(
    '👤 ',v_person_name,
    E'\nนัดเพื่อ: ',coalesce(nullif(btrim(v_appt.title),''),'นัดหมาย'),
    E'\n📆 วันเวลา: ',to_char(v_appt.appointment_at at time zone 'Asia/Bangkok','DD/MM/YYYY HH24:MI'),' น.',
    case when nullif(btrim(v_appt.hospital_name),'') is not null
      then E'\n🏥 สถานพยาบาล: '||v_appt.hospital_name else '' end,
    case when nullif(btrim(v_appt.department),'') is not null
      then E'\n🏢 แผนก/คลินิก: '||v_appt.department else '' end,
    case when nullif(btrim(v_appt.location_detail),'') is not null
      then E'\n📍 จุดนัด: '||v_appt.location_detail else '' end
  );

  for v_rec in
    select distinct q.recipient_user_id
    from (
      select r.recipient_user_id
      from private.phms_notification_recipients(v_appt.person_id,'appointments') r
      where v_mode='default'
      union
      select t.user_id
      from public.appointment_notification_user_targets t
      where v_mode='custom'
        and t.appointment_id=v_appt.id
        and t.enabled=true
        and exists(
          select 1
          from private.phms_notification_recipients(v_appt.person_id,'appointments') r2
          where r2.recipient_user_id=t.user_id
        )
    ) q
  loop
    insert into public.notifications(
      family_id,recipient_user_id,person_id,family_person_id,
      event_type,title,message,related_record_id,
      channel,priority,status,scheduled_for,next_attempt_at,
      payload,dedupe_key,created_at,updated_at
    ) values(
      v_appt.family_id,v_rec.recipient_user_id,v_appt.person_id,v_appt.family_person_id,
      'appointment_notify_now',v_title,v_message,v_appt.id,
      'line','normal','pending',now(),now(),
      jsonb_build_object(
        'appointment_id',v_appt.id,
        'appointment_code',substr(v_appt.id::text,1,12),
        'appointment_at',v_appt.appointment_at,
        'appointment_status',v_appt.status,
        'manual_send',true,
        'recipient_mode',v_mode,
        'request_id',v_request_id
      ),
      'appointment-notify-now:'||v_request_id::text||':user:'||v_rec.recipient_user_id::text,
      now(),now()
    );
    v_user_count:=v_user_count+1;
  end loop;

  for v_group in
    select gt.id,gt.line_group_id
    from public.appointment_line_group_targets gt
    where gt.appointment_id=v_appt.id
      and gt.status='active'
  loop
    insert into public.notifications(
      family_id,recipient_user_id,person_id,family_person_id,
      event_type,title,message,related_record_id,
      channel,priority,status,scheduled_for,next_attempt_at,
      payload,dedupe_key,created_at,updated_at
    ) values(
      v_appt.family_id,null,v_appt.person_id,v_appt.family_person_id,
      'appointment_notify_now_group',v_title,v_message,v_appt.id,
      'line','normal','pending',now(),now(),
      jsonb_build_object(
        'appointment_id',v_appt.id,
        'appointment_code',substr(v_appt.id::text,1,12),
        'appointment_at',v_appt.appointment_at,
        'appointment_status',v_appt.status,
        'manual_send',true,
        'recipient_mode',v_mode,
        'request_id',v_request_id,
        'line_destination_type','group',
        'line_destination_id',v_group.line_group_id,
        'group_target_id',v_group.id
      ),
      'appointment-notify-now:'||v_request_id::text||':group:'||v_group.id::text,
      now(),now()
    );
    v_group_count:=v_group_count+1;
  end loop;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    new_data,description
  ) values(
    v_ref.active_family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
    'appointment_notification_send_now','appointment',v_ref.record_id,
    jsonb_build_object(
      'request_id',v_request_id,
      'recipient_mode',v_mode,
      'user_notifications',v_user_count,
      'group_notifications',v_group_count
    ),
    'ส่งแจ้งเตือนนัดทันทีตามชุดผู้รับที่ตั้งไว้'
  );

  return jsonb_build_object(
    'ok',true,
    'record_code',substr(v_appt.id::text,1,12),
    'recipient_mode',v_mode,
    'user_notifications',v_user_count,
    'group_notifications',v_group_count,
    'request_id',v_request_id
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_post_visit_sync_clinical(p_line_user_id text, p_record_code text, p_medication_operations jsonb DEFAULT '[]'::jsonb, p_test_results text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_appt public.appointments%rowtype;
  v_med jsonb;
  v_action text;
  v_generic text;
  v_brand text;
  v_name_norm text;
  v_strength numeric;
  v_strength_unit text;
  v_key text;
  v_master_id uuid;
  v_pm_id uuid;
  v_reg_id uuid;
  v_health_id uuid;
  v_existing_health_id uuid;
  v_old jsonb;
  v_new jsonb;
  v_has_regimen boolean;
  v_op_hash text;
  v_applied boolean;
  v_med_count integer:=0;
  v_med_skipped integer:=0;
  v_health_count integer:=0;
  v_results jsonb:='[]'::jsonb;
  v_context text;
begin
  select * into v_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',p_record_code,'update'
  )
  limit 1;

  select * into v_appt
  from public.appointments
  where id=v_ref.record_id
    and deleted_at is null
  limit 1;

  if not found then raise exception 'appointment_not_found'; end if;

  if p_medication_operations is null then
    p_medication_operations:='[]'::jsonb;
  end if;
  if jsonb_typeof(p_medication_operations)<>'array' then
    raise exception 'medication_operations_must_be_array';
  end if;

  for v_med in select value from jsonb_array_elements(p_medication_operations)
  loop
    v_action:=lower(btrim(coalesce(v_med->>'action','add')));
    if v_action not in ('add','change','stop') then
      v_med_skipped:=v_med_skipped+1;
      continue;
    end if;

    v_generic:=nullif(btrim(v_med->>'generic_name'),'');
    v_brand:=nullif(btrim(v_med->>'brand_name'),'');
    if v_generic is null and v_brand is null then
      v_med_skipped:=v_med_skipped+1;
      continue;
    end if;

    v_name_norm:=private.phms_normalize_dedupe_text(coalesce(v_brand,v_generic));

    select pm.id
    into v_pm_id
    from public.person_medications pm
    join public.medication_master mm on mm.id=pm.medication_id
    where pm.person_id=v_appt.person_id
      and pm.deleted_at is null
      and (
        private.phms_normalize_dedupe_text(coalesce(mm.brand_name,''))=v_name_norm
        or private.phms_normalize_dedupe_text(coalesce(mm.generic_name,''))=v_name_norm
        or (
          v_generic is not null
          and private.phms_normalize_dedupe_text(mm.generic_name)
              =private.phms_normalize_dedupe_text(v_generic)
        )
        or (
          v_brand is not null
          and private.phms_normalize_dedupe_text(coalesce(mm.brand_name,''))
              =private.phms_normalize_dedupe_text(v_brand)
        )
      )
    order by
      case when pm.status in ('regular','prn','paused') then 0 else 1 end,
      pm.updated_at desc nulls last,
      pm.created_at desc
    limit 1;

    if v_action='stop' then
      if v_pm_id is null then
        v_med_skipped:=v_med_skipped+1;
        v_results:=v_results||jsonb_build_array(jsonb_build_object(
          'resource','medication','action','stop','status','not_found',
          'name',coalesce(v_brand,v_generic)
        ));
        continue;
      end if;

      select jsonb_build_object(
        'person_medication',to_jsonb(pm),
        'regimen',case when r.id is null then null else to_jsonb(r) end
      )
      into v_old
      from public.person_medications pm
      left join lateral (
        select rr.* from public.medication_regimens rr
        where rr.person_medication_id=pm.id
          and rr.deleted_at is null
          and rr.is_current=true
        order by rr.effective_from desc,rr.created_at desc
        limit 1
      ) r on true
      where pm.id=v_pm_id;

      update public.person_medications
      set status='discontinued',
          end_date=coalesce((v_appt.appointment_at at time zone 'Asia/Bangkok')::date,current_date),
          notes=coalesce(nullif(btrim(v_med->>'notes'),''),notes),
          updated_at=now()
      where id=v_pm_id;

      update public.medication_regimens
      set is_current=false,
          effective_to=coalesce(v_appt.appointment_at,now()),
          updated_at=now()
      where person_medication_id=v_pm_id
        and deleted_at is null
        and is_current=true;

      select jsonb_build_object(
        'person_medication',to_jsonb(pm),
        'regimen',case when r.id is null then null else to_jsonb(r) end
      )
      into v_new
      from public.person_medications pm
      left join lateral (
        select rr.* from public.medication_regimens rr
        where rr.person_medication_id=pm.id
          and rr.deleted_at is null
          and rr.is_current=true
        order by rr.effective_from desc,rr.created_at desc
        limit 1
      ) r on true
      where pm.id=v_pm_id;

      insert into public.medication_change_history(
        person_medication_id,change_type,old_data,new_data,reason,
        ordered_by_clinician_id,organization_id,effective_at,changed_by
      )
      values(
        v_pm_id,'discontinued',v_old,v_new,
        'appointment_post_visit #'||substr(v_appt.id::text,1,12),
        v_appt.clinician_id,v_appt.organization_id,
        coalesce(v_appt.appointment_at,now()),v_ref.actor_user_id
      );

      v_med_count:=v_med_count+1;
      v_results:=v_results||jsonb_build_array(jsonb_build_object(
        'resource','medication','action','stop','status','updated',
        'record_code',substr(v_pm_id::text,1,12)
      ));
      continue;
    end if;

    if v_pm_id is null then
      v_strength:=private.phms_try_numeric(v_med->>'strength_value');
      v_strength_unit:=nullif(btrim(v_med->>'strength_unit'),'');
      v_key:=private.phms_normalize_dedupe_text(concat_ws('|',
        coalesce(v_generic,v_brand),
        coalesce(v_brand,''),
        coalesce(v_med->>'strength_value',''),
        coalesce(v_strength_unit,''),
        coalesce(v_med->>'dosage_form','')
      ));

      select mm.id into v_master_id
      from public.medication_master mm
      where mm.normalized_key=v_key
        and mm.deleted_at is null
      limit 1;

      if v_master_id is null then
        insert into public.medication_master(
          generic_name,brand_name,strength_value,strength_unit,
          concentration_text,dosage_form,default_route,standard_unit,
          active_ingredient_text,normalized_key,status
        )
        values(
          coalesce(v_generic,v_brand),v_brand,v_strength,v_strength_unit,
          nullif(btrim(v_med->>'concentration_text'),''),
          nullif(btrim(v_med->>'dosage_form'),''),
          nullif(btrim(v_med->>'route'),''),
          nullif(btrim(v_med->>'standard_unit'),''),
          nullif(btrim(v_med->>'active_ingredient_text'),''),
          v_key,'active'
        )
        on conflict (normalized_key) where normalized_key is not null and deleted_at is null
        do nothing
        returning id into v_master_id;

        if v_master_id is null then
          select mm.id into v_master_id
          from public.medication_master mm
          where mm.normalized_key=v_key
            and mm.deleted_at is null
          limit 1;
        end if;
      end if;

      insert into public.person_medications(
        person_id,medication_id,indication,status,
        prescriber_id,organization_id,service_unit_id,
        start_date,notes,created_by
      )
      values(
        v_appt.person_id,v_master_id,
        nullif(btrim(v_med->>'indication'),''),
        'regular',
        v_appt.clinician_id,v_appt.organization_id,v_appt.service_unit_id,
        coalesce((v_appt.appointment_at at time zone 'Asia/Bangkok')::date,current_date),
        coalesce(nullif(btrim(v_med->>'notes'),''),
          'จากสรุปหลังนัด #'||substr(v_appt.id::text,1,12)),
        v_ref.actor_user_id
      )
      returning id into v_pm_id;

      v_old:=null;
    else
      select jsonb_build_object(
        'person_medication',to_jsonb(pm),
        'regimen',case when r.id is null then null else to_jsonb(r) end
      )
      into v_old
      from public.person_medications pm
      left join lateral (
        select rr.* from public.medication_regimens rr
        where rr.person_medication_id=pm.id
          and rr.deleted_at is null
          and rr.is_current=true
        order by rr.effective_from desc,rr.created_at desc
        limit 1
      ) r on true
      where pm.id=v_pm_id;

      update public.person_medications
      set status='regular',
          prescriber_id=coalesce(v_appt.clinician_id,prescriber_id),
          organization_id=coalesce(v_appt.organization_id,organization_id),
          service_unit_id=coalesce(v_appt.service_unit_id,service_unit_id),
          indication=coalesce(nullif(btrim(v_med->>'indication'),''),indication),
          notes=coalesce(nullif(btrim(v_med->>'notes'),''),notes),
          start_date=coalesce(start_date,(v_appt.appointment_at at time zone 'Asia/Bangkok')::date),
          end_date=null,
          updated_at=now()
      where id=v_pm_id;
    end if;

    v_op_hash:=encode(digest(
      concat_ws('|',v_action,coalesce(v_brand,''),coalesce(v_generic,''),v_med::text),
      'sha256'
    ),'hex');

    select exists(
      select 1
      from public.record_provenance rp
      where rp.resource_type='person_medications'
        and rp.record_id=v_pm_id
        and rp.source_type='appointment_post_visit_medication'
        and rp.source_record_id=v_appt.id
        and rp.source_text='op:'||v_op_hash
    ) into v_applied;

    if v_applied then
      v_med_skipped:=v_med_skipped+1;
      v_results:=v_results||jsonb_build_array(jsonb_build_object(
        'resource','medication','action',v_action,'status','idempotent',
        'record_code',substr(v_pm_id::text,1,12)
      ));
      continue;
    end if;

    v_has_regimen :=
      nullif(btrim(v_med->>'dose_value'),'') is not null
      or nullif(btrim(v_med->>'dose_unit'),'') is not null
      or nullif(btrim(v_med->>'dose_text'),'') is not null
      or nullif(btrim(v_med->>'frequency_type'),'') is not null
      or nullif(btrim(v_med->>'frequency_value'),'') is not null
      or nullif(btrim(v_med->>'frequency_unit'),'') is not null
      or nullif(btrim(v_med->>'route'),'') is not null
      or nullif(btrim(v_med->>'meal_relation'),'') is not null
      or nullif(btrim(v_med->>'instructions'),'') is not null
      or jsonb_typeof(v_med->'time_of_day')='array'
      or jsonb_typeof(v_med->'exact_times')='array';

    if v_has_regimen then
      update public.medication_regimens
      set is_current=false,
          effective_to=coalesce(v_appt.appointment_at,now()),
          updated_at=now()
      where person_medication_id=v_pm_id
        and deleted_at is null
        and is_current=true;

      insert into public.medication_regimens(
        person_medication_id,dose_value,dose_unit,dose_text,
        frequency_type,frequency_value,frequency_unit,
        route,administration_site,meal_relation,
        time_of_day,exact_times,instructions,
        effective_from,effective_to,is_current,created_by
      )
      values(
        v_pm_id,
        private.phms_try_numeric(v_med->>'dose_value'),
        nullif(btrim(v_med->>'dose_unit'),''),
        nullif(btrim(v_med->>'dose_text'),''),
        nullif(btrim(v_med->>'frequency_type'),''),
        private.phms_try_numeric(v_med->>'frequency_value'),
        nullif(btrim(v_med->>'frequency_unit'),''),
        nullif(btrim(v_med->>'route'),''),
        nullif(btrim(v_med->>'administration_site'),''),
        nullif(btrim(v_med->>'meal_relation'),''),
        private.phms_jsonb_text_array(v_med->'time_of_day'),
        private.phms_jsonb_time_array(v_med->'exact_times'),
        nullif(btrim(v_med->>'instructions'),''),
        coalesce(v_appt.appointment_at,now()),
        null,
        true,
        v_ref.actor_user_id
      )
      returning id into v_reg_id;
    else
      v_reg_id:=null;
    end if;

    select jsonb_build_object(
      'person_medication',to_jsonb(pm),
      'regimen',case when r.id is null then null else to_jsonb(r) end
    )
    into v_new
    from public.person_medications pm
    left join lateral (
      select rr.* from public.medication_regimens rr
      where rr.person_medication_id=pm.id
        and rr.deleted_at is null
        and rr.is_current=true
      order by rr.effective_from desc,rr.created_at desc
      limit 1
    ) r on true
    where pm.id=v_pm_id;

    insert into public.medication_change_history(
      person_medication_id,change_type,old_data,new_data,reason,
      ordered_by_clinician_id,organization_id,effective_at,changed_by
    )
    values(
      v_pm_id,
      case when v_old is null then 'added' else 'updated' end,
      v_old,v_new,
      'appointment_post_visit #'||substr(v_appt.id::text,1,12),
      v_appt.clinician_id,v_appt.organization_id,
      coalesce(v_appt.appointment_at,now()),v_ref.actor_user_id
    );

    insert into public.record_provenance(
      person_id,resource_type,record_id,source_type,source_record_id,
      source_text,confidence,extraction_method,verified_by,verified_at
    )
    select
      v_appt.person_id,'person_medications',v_pm_id,
      'appointment_post_visit_medication',v_appt.id,
      'op:'||v_op_hash,1.0,'structured_post_visit',
      v_ref.actor_user_id,now()
    where not exists(
      select 1 from public.record_provenance rp
      where rp.resource_type='person_medications'
        and rp.record_id=v_pm_id
        and rp.source_type='appointment_post_visit_medication'
        and rp.source_record_id=v_appt.id
        and rp.source_text='op:'||v_op_hash
    );

    if v_reg_id is not null then
      insert into public.record_provenance(
        person_id,resource_type,record_id,source_type,source_record_id,
        source_text,confidence,extraction_method,verified_by,verified_at
      )
      values(
        v_appt.person_id,'medication_regimens',v_reg_id,
        'appointment_post_visit_medication',v_appt.id,
        'op:'||v_op_hash,1.0,'structured_post_visit',
        v_ref.actor_user_id,now()
      );
    end if;

    v_med_count:=v_med_count+1;
    v_results:=v_results||jsonb_build_array(jsonb_build_object(
      'resource','medication','action',v_action,
      'status',case when v_old is null then 'created' else 'updated' end,
      'record_code',substr(v_pm_id::text,1,12)
    ));
  end loop;

  if nullif(btrim(coalesce(p_test_results,'')),'') is not null then
    select rp.record_id
    into v_existing_health_id
    from public.record_provenance rp
    where rp.resource_type='health_measurements'
      and rp.source_type='appointment_post_visit_test_results'
      and rp.source_record_id=v_appt.id
    order by rp.created_at desc
    limit 1;

    v_context:=concat_ws(' • ',
      'ผลตรวจจากนัด',
      nullif(btrim(v_appt.title),''),
      nullif(btrim(v_appt.hospital_name),'')
    );

    if v_existing_health_id is not null
       and exists(
         select 1 from public.health_measurements h
         where h.id=v_existing_health_id and h.deleted_at is null
       ) then
      update public.health_measurements
      set measurement_type='ผลตรวจจากนัด',
          measured_at=coalesce(v_appt.appointment_at,measured_at),
          value_numeric=null,
          value_text=btrim(p_test_results),
          unit=null,
          systolic=null,
          diastolic=null,
          context=v_context,
          notes='ซิงก์จากสรุปหลังนัด #'||substr(v_appt.id::text,1,12),
          source_type='appointment_post_visit'
      where id=v_existing_health_id;
      v_health_id:=v_existing_health_id;
    else
      insert into public.health_measurements(
        person_id,measurement_type,measured_at,value_text,
        context,notes,source_type,created_by
      )
      values(
        v_appt.person_id,'ผลตรวจจากนัด',
        coalesce(v_appt.appointment_at,now()),
        btrim(p_test_results),v_context,
        'ซิงก์จากสรุปหลังนัด #'||substr(v_appt.id::text,1,12),
        'appointment_post_visit',v_ref.actor_user_id
      )
      returning id into v_health_id;

      insert into public.record_provenance(
        person_id,resource_type,record_id,source_type,source_record_id,
        source_text,confidence,extraction_method,verified_by,verified_at
      )
      values(
        v_appt.person_id,'health_measurements',v_health_id,
        'appointment_post_visit_test_results',v_appt.id,
        btrim(p_test_results),1.0,'structured_post_visit',
        v_ref.actor_user_id,now()
      );
    end if;

    update public.record_provenance
    set source_text=btrim(p_test_results),
        verified_by=v_ref.actor_user_id,
        verified_at=now()
    where resource_type='health_measurements'
      and record_id=v_health_id
      and source_type='appointment_post_visit_test_results'
      and source_record_id=v_appt.id;

    v_health_count:=1;
    v_results:=v_results||jsonb_build_array(jsonb_build_object(
      'resource','health','status',
      case when v_existing_health_id is null then 'created' else 'updated' end,
      'record_code',substr(v_health_id::text,1,12)
    ));
  end if;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    old_data,new_data,description
  )
  values(
    v_ref.active_family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
    'appointment_post_visit_clinical_sync','appointment',v_appt.id,
    null,
    jsonb_build_object(
      'medications_synced',v_med_count,
      'medications_skipped',v_med_skipped,
      'health_results_synced',v_health_count,
      'results',v_results
    ),
    'ซิงก์ยาและผลตรวจจากสรุปหลังนัดเข้ารายการหลัก'
  );

  return jsonb_build_object(
    'ok',true,
    'record_code',substr(v_appt.id::text,1,12),
    'medications_synced',v_med_count,
    'medications_skipped',v_med_skipped,
    'health_results_synced',v_health_count,
    'results',v_results
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_post_visit_v2(p_line_user_id text, p_record_code text, p_summary jsonb, p_followup_required boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_old jsonb;
  v_new jsonb;
  v_summary jsonb:=coalesce(p_summary,'{}'::jsonb);
  v_outcome text;
begin
  if jsonb_typeof(v_summary)<>'object' then
    raise exception 'post_visit_summary_object_required';
  end if;

  select * into v_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',p_record_code,'update'
  )
  limit 1;

  select to_jsonb(a) into v_old
  from public.appointments a
  where a.id=v_ref.record_id;

  v_outcome:=nullif(btrim(coalesce(v_summary->>'visit_outcome_notes','')),'');
  if v_outcome is null then
    v_outcome:=nullif(concat_ws(E'\n',
      case when nullif(btrim(v_summary->>'diagnosis_summary'),'') is not null
        then 'วินิจฉัย/ความเห็นแพทย์: '||btrim(v_summary->>'diagnosis_summary') end,
      case when nullif(btrim(v_summary->>'treatment_summary'),'') is not null
        then 'การรักษาครั้งนี้: '||btrim(v_summary->>'treatment_summary') end,
      case when nullif(btrim(v_summary->>'next_steps'),'') is not null
        then 'ต้องทำต่อ: '||btrim(v_summary->>'next_steps') end,
      case when nullif(btrim(v_summary->>'medication_plan_notes'),'') is not null
        then 'ยา/การเปลี่ยนยา: '||btrim(v_summary->>'medication_plan_notes') end,
      case when nullif(btrim(v_summary->>'test_results_summary'),'') is not null
        then 'ผลตรวจ: '||btrim(v_summary->>'test_results_summary') end
    ),'');
  end if;

  update public.appointments
  set visit_outcome_notes=coalesce(v_outcome,visit_outcome_notes),
      diagnosis_summary=case
        when v_summary?'diagnosis_summary'
        then nullif(btrim(v_summary->>'diagnosis_summary'),'')
        else diagnosis_summary end,
      treatment_summary=case
        when v_summary?'treatment_summary'
        then nullif(btrim(v_summary->>'treatment_summary'),'')
        else treatment_summary end,
      next_steps=case
        when v_summary?'next_steps'
        then nullif(btrim(v_summary->>'next_steps'),'')
        else next_steps end,
      medication_plan_notes=case
        when v_summary?'medication_plan_notes'
        then nullif(btrim(v_summary->>'medication_plan_notes'),'')
        else medication_plan_notes end,
      test_results_summary=case
        when v_summary?'test_results_summary'
        then nullif(btrim(v_summary->>'test_results_summary'),'')
        else test_results_summary end,
      followup_required=coalesce(p_followup_required,followup_required),
      followup_recorded_at=now(),
      updated_at=now()
  where id=v_ref.record_id;

  update public.appointment_reminders
  set status='cancelled',updated_at=now()
  where appointment_id=v_ref.record_id
    and rule_key='auto_post_visit'
    and status in ('pending','failed');

  update public.notifications
  set status='cancelled',
      last_error='post_visit_already_recorded',
      updated_at=now(),
      locked_at=null,
      lock_token=null
  where related_record_id=v_ref.record_id
    and event_type='appointment_post_visit'
    and status in ('pending','failed');

  select to_jsonb(a) into v_new
  from public.appointments a
  where a.id=v_ref.record_id;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    old_data,new_data,description
  )
  values(
    v_ref.active_family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
    'appointment_post_visit','appointment',v_ref.record_id,
    v_old,v_new,'บันทึกสรุปหลังนัดแบบมีโครงสร้าง'
  );

  return jsonb_build_object(
    'ok',true,
    'record_code',substr(v_ref.record_id::text,1,12),
    'followup_required',v_new->'followup_required',
    'post_visit_reminder_cancelled',true,
    'item',v_new
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_previous_options(p_line_user_id text, p_record_code text, p_limit integer DEFAULT 12)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_current public.appointments%rowtype;
  v_items jsonb:='[]'::jsonb;
  v_limit int:=greatest(1,least(coalesce(p_limit,12),20));
begin
  select * into v_ref
  from private.phms_line_appointment_access(p_line_user_id,p_record_code)
  limit 1;

  if coalesce(v_ref.can_update,false) is not true then
    raise exception 'appointment_relation_update_denied';
  end if;

  select * into v_current
  from public.appointments
  where id=v_ref.record_id and deleted_at is null;

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'record_code',substr(a.id::text,1,12),
    'appointment_at',a.appointment_at,
    'title',a.title,
    'hospital_name',a.hospital_name,
    'department',a.department,
    'doctor_name',a.doctor_name,
    'appointment_type',a.appointment_type,
    'status',a.status
  )) order by a.appointment_at desc),'[]'::jsonb)
  into v_items
  from (
    select *
    from public.appointments a
    where a.person_id=v_current.person_id
      and a.id<>v_current.id
      and a.deleted_at is null
      and (
        v_current.appointment_at is null
        or a.appointment_at is null
        or a.appointment_at < v_current.appointment_at
      )
    order by a.appointment_at desc nulls last,a.created_at desc
    limit v_limit
  ) a;

  return jsonb_build_object(
    'ok',true,
    'record_code',substr(v_current.id::text,1,12),
    'appointment_type',v_current.appointment_type,
    'items',v_items
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_previsit_symptom_link_document(p_line_user_id text, p_symptom_code text, p_appointment_document_link_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_s public.appointment_previsit_symptoms%rowtype;
  v_ref record;
  v_count int:=0;
  v_early_ref record;
  v_early_linked boolean:=false;
begin
  select count(*)::int into v_count
  from public.appointment_previsit_symptoms s
  where lower(s.id::text) like lower(btrim(p_symptom_code))||'%' and s.deleted_at is null;
  if v_count=0 then raise exception 'previsit_symptom_not_found'; end if;
  if v_count>1 then raise exception 'previsit_symptom_code_ambiguous'; end if;

  select * into v_s from public.appointment_previsit_symptoms s
  where lower(s.id::text) like lower(btrim(p_symptom_code))||'%' and s.deleted_at is null limit 1;

  select * into v_ref from private.phms_line_appointment_access(p_line_user_id,substr(v_s.appointment_id::text,1,12)) limit 1;
 if v_ref.active_family_person_id is null or not private.user_can_access_family_person(v_ref.actor_user_id,v_ref.active_family_person_id,'documents','update') then raise exception 'document_permission_denied';end if;

  if coalesce(v_ref.can_update,false) is not true then raise exception 'previsit_document_link_denied'; end if;
  if v_ref.active_family_person_id is null or
     not private.user_can_access_family_person(v_ref.actor_user_id,v_ref.active_family_person_id,'health_data','create')
  then raise exception 'previsit_health_create_denied'; end if;

  if not exists(
    select 1 from public.appointment_document_links l
    where l.id=p_appointment_document_link_id and l.appointment_id=v_s.appointment_id
  ) then raise exception 'previsit_document_wrong_appointment'; end if;

  insert into public.appointment_previsit_symptom_documents(symptom_id,appointment_document_link_id,created_by)
  values(v_s.id,p_appointment_document_link_id,v_ref.actor_user_id)
  on conflict do nothing;


  if v_s.early_visit_appointment_id is not null then
    select * into v_early_ref from private.phms_line_appointment_access(
      p_line_user_id,substr(v_s.early_visit_appointment_id::text,1,12)
    ) limit 1;
    if v_early_ref.record_id=v_s.early_visit_appointment_id and coalesce(v_early_ref.can_update,false) then
      insert into public.appointment_document_links(
        appointment_id,medical_document_id,storage_asset_id,link_kind,note,
        created_by,usage_relation,origin_appointment_id
      )
      select v_s.early_visit_appointment_id,l.medical_document_id,l.storage_asset_id,'other',
        concat_ws(' • ',nullif(btrim(l.note),''),'รูป/ไฟล์อาการก่อนนัด'),
        v_ref.actor_user_id,'supporting',v_s.appointment_id
      from public.appointment_document_links l
      where l.id=p_appointment_document_link_id
        and (l.storage_asset_id is not null or l.medical_document_id is not null)
        and not exists(
          select 1 from public.appointment_document_links z
          where z.appointment_id=v_s.early_visit_appointment_id and z.link_kind='other'
          and z.storage_asset_id is not distinct from l.storage_asset_id
          and z.medical_document_id is not distinct from l.medical_document_id
        );
      v_early_linked:=true;
    end if;
  end if;

  return jsonb_build_object('ok',true,'symptom_code',substr(v_s.id::text,1,12),'record_code',substr(v_s.appointment_id::text,1,12),'early_visit_linked',v_early_linked);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_previsit_symptom_link_early_visit(p_line_user_id text, p_symptom_code text, p_early_record_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_s public.appointment_previsit_symptoms%rowtype;
  v_early record;
  v_count int:=0;
  v_docs_linked int:=0;
begin
  select count(*)::int into v_count
  from public.appointment_previsit_symptoms s
  where lower(s.id::text) like lower(btrim(p_symptom_code))||'%' and s.deleted_at is null;
  if v_count<>1 then raise exception 'previsit_symptom_not_found_or_ambiguous'; end if;
  select * into v_s from public.appointment_previsit_symptoms s
  where lower(s.id::text) like lower(btrim(p_symptom_code))||'%' and s.deleted_at is null limit 1;

  select a.id,a.early_visit_of_appointment_id,a.person_id,ref.actor_user_id,ref.active_family_person_id
  into v_early
  from private.phms_line_appointment_access(p_line_user_id,p_early_record_code) ref
  join public.appointments a on a.id=ref.record_id
  where ref.can_update=true and a.deleted_at is null
  limit 1;

  if v_early.id is null or v_early.early_visit_of_appointment_id is distinct from v_s.appointment_id
     or v_early.person_id is distinct from v_s.person_id
  then raise exception 'previsit_early_visit_mismatch'; end if;

  if v_early.active_family_person_id is null or not private.user_can_access_family_person(
    v_early.actor_user_id,v_early.active_family_person_id,'health_data','view'
  ) then raise exception 'previsit_health_view_denied'; end if;

  -- Link existing symptom images/files to the new visit without copying stored objects.
  insert into public.appointment_document_links(
    appointment_id,medical_document_id,storage_asset_id,link_kind,note,
    created_by,usage_relation,origin_appointment_id
  )
  select v_early.id,l.medical_document_id,l.storage_asset_id,'other',
    concat_ws(' • ',nullif(btrim(l.note),''),'รูป/ไฟล์อาการก่อนนัด'),
    v_early.actor_user_id,'supporting',v_s.appointment_id
  from public.appointment_previsit_symptom_documents d
  join public.appointment_document_links l on l.id=d.appointment_document_link_id
  where d.symptom_id=v_s.id and l.appointment_id=v_s.appointment_id
    and (l.storage_asset_id is not null or l.medical_document_id is not null)
    and not exists (
      select 1 from public.appointment_document_links z
      where z.appointment_id=v_early.id
        and z.link_kind='other'
        and z.storage_asset_id is not distinct from l.storage_asset_id
        and z.medical_document_id is not distinct from l.medical_document_id
    );
  get diagnostics v_docs_linked=row_count;

  update public.appointment_previsit_symptoms
  set early_visit_appointment_id=v_early.id,decision='early_visit',updated_at=now()
  where id=v_s.id;

  return jsonb_build_object('ok',true,'symptom_code',substr(v_s.id::text,1,12),'early_record_code',substr(v_early.id::text,1,12),'documents_linked',v_docs_linked);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_previsit_symptom_save(p_line_user_id text, p_record_code text, p_symptom_text text, p_onset_text text DEFAULT NULL::text, p_severity integer DEFAULT NULL::integer, p_trend text DEFAULT NULL::text, p_associated_symptoms text DEFAULT NULL::text, p_actions_taken text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_a public.appointments%rowtype;
  v_id uuid;
  v_text text:=nullif(btrim(coalesce(p_symptom_text,'')),'');
  v_trend text:=nullif(lower(btrim(coalesce(p_trend,''))),'');
begin
  if v_text is null or length(v_text)>2000 then raise exception 'previsit_symptom_text_required'; end if;
  if p_severity is not null and (p_severity<0 or p_severity>10) then raise exception 'previsit_severity_invalid'; end if;
  if v_trend is not null and v_trend not in ('new','stable','better','worse','fluctuating') then
    raise exception 'previsit_trend_invalid';
  end if;

  select * into v_ref from private.phms_line_appointment_access(p_line_user_id,p_record_code) limit 1;
  if v_ref.record_id is null then raise exception 'appointment_not_accessible'; end if;
  if v_ref.active_family_person_id is null or
     not private.user_can_access_family_person(v_ref.actor_user_id,v_ref.active_family_person_id,'health_data','create')
  then raise exception 'previsit_health_create_denied'; end if;

  select * into v_a from public.appointments
  where id=v_ref.record_id and deleted_at is null;
  if not found then raise exception 'appointment_not_found'; end if;
  if v_a.status not in ('scheduled','confirmed') then raise exception 'previsit_appointment_not_active'; end if;

  insert into public.appointment_previsit_symptoms(
    appointment_id,person_id,family_person_id,reported_at,onset_text,symptom_text,severity,trend,
    associated_symptoms,actions_taken,note,created_by
  ) values (
    v_a.id,v_a.person_id,v_ref.active_family_person_id,now(),
    nullif(btrim(coalesce(p_onset_text,'')),''),
    v_text,p_severity,v_trend,
    nullif(btrim(coalesce(p_associated_symptoms,'')),''),
    nullif(btrim(coalesce(p_actions_taken,'')),''),
    nullif(btrim(coalesce(p_note,'')),''),
    v_ref.actor_user_id
  ) returning id into v_id;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,new_data,description
  ) values (
    v_ref.active_family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
    'appointment_previsit_symptom_added','appointment',v_a.id,
    jsonb_build_object('symptom_id',v_id,'severity',p_severity,'trend',v_trend),
    'บันทึกอาการก่อนถึงวันนัด'
  );

  return jsonb_build_object(
    'ok',true,'record_code',substr(v_a.id::text,1,12),
    'symptom_code',substr(v_id::text,1,12),'reported_at',now()
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_previsit_symptoms(p_line_user_id text, p_record_code text, p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_items jsonb:='[]'::jsonb;
  v_count int:=0;
  v_can_add boolean:=false;
begin
  select * into v_ref from private.phms_line_appointment_access(p_line_user_id,p_record_code) limit 1;
  if v_ref.record_id is null then raise exception 'appointment_not_accessible'; end if;
  if v_ref.active_family_person_id is null or
     not private.user_can_access_family_person(v_ref.actor_user_id,v_ref.active_family_person_id,'health_data','view')
  then raise exception 'previsit_health_view_denied'; end if;

  v_can_add:=private.user_can_access_family_person(
    v_ref.actor_user_id,v_ref.active_family_person_id,'health_data','create'
  );

  select count(*)::int into v_count
  from public.appointment_previsit_symptoms s
  where s.appointment_id=v_ref.record_id and s.deleted_at is null;

  select coalesce(jsonb_agg(x.item order by x.reported_at desc),'[]'::jsonb)
  into v_items
  from (
    select s.reported_at,
      jsonb_strip_nulls(jsonb_build_object(
        'symptom_code',substr(s.id::text,1,12),
        'reported_at',s.reported_at,
        'onset_text',s.onset_text,
        'symptom_text',s.symptom_text,
        'severity',s.severity,
        'trend',s.trend,
        'associated_symptoms',s.associated_symptoms,
        'actions_taken',s.actions_taken,
        'note',s.note,
        'decision',s.decision,
        'early_visit_code',case when s.early_visit_appointment_id is not null then substr(s.early_visit_appointment_id::text,1,12) end,
        'document_count',(
          select count(*) from public.appointment_previsit_symptom_documents d where d.symptom_id=s.id
        ),
        'documents',coalesce((
          select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
            'link_id',l.id,
            'title',coalesce(md.title,a.original_filename,'รูปอาการก่อนนัด'),
            'storage_asset_id',l.storage_asset_id
          )) order by d.created_at)
          from public.appointment_previsit_symptom_documents d
          join public.appointment_document_links l on l.id=d.appointment_document_link_id
          left join public.medical_documents md on md.id=l.medical_document_id
          left join public.phms_storage_assets a on a.id=l.storage_asset_id
          where d.symptom_id=s.id
        ),'[]'::jsonb)
      )) item
    from public.appointment_previsit_symptoms s
    where s.appointment_id=v_ref.record_id and s.deleted_at is null
    order by s.reported_at desc
    limit greatest(1,least(coalesce(p_limit,20),50))
  ) x;

  return jsonb_build_object(
    'ok',true,'record_code',substr(v_ref.record_id::text,1,12),
    'count',v_count,'can_add',v_can_add,'items',v_items
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_remove_assignee(p_line_user_id text, p_record_code text, p_assignee_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_code text:=lower(btrim(coalesce(p_assignee_code,'')));
  v_count int;
  v_id uuid;
  v_ass public.appointment_assignees%rowtype;
begin
  select * into v_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',p_record_code,'update'
  ) limit 1;

  select count(*),min(id) into v_count,v_id
  from public.appointment_assignees
  where appointment_id=v_ref.record_id
    and status<>'removed'
    and lower(id::text) like v_code||'%';

  if v_count=0 then raise exception 'appointment_assignee_not_found'; end if;
  if v_count>1 then raise exception 'appointment_assignee_code_ambiguous'; end if;

  select * into v_ass from public.appointment_assignees where id=v_id;

  update public.notifications n
  set status='cancelled',updated_at=now(),last_error='appointment_assignee_removed'
  where n.id in (
    select ak.notification_id
    from public.appointment_acknowledgements ak
    where ak.appointment_id=v_ref.record_id
      and ak.ack_type='assignment'
      and ak.status='pending'
      and private.phms_try_uuid(ak.change_snapshot->>'assignee_id')=v_id
      and ak.notification_id is not null
  )
  and n.status in ('pending','failed');

  update public.appointment_acknowledgements
  set status='expired',updated_at=now()
  where appointment_id=v_ref.record_id
    and ack_type='assignment'
    and status='pending'
    and private.phms_try_uuid(change_snapshot->>'assignee_id')=v_id;

  update public.appointment_assignees
  set status='removed',requires_ack=false,updated_at=now()
  where id=v_id;

  insert into public.audit_logs(
    family_id,actor_user_id,target_user_id,family_person_id,
    event_type,resource,record_id,old_data,new_data,description
  )
  values(
    v_ref.active_family_id,v_ref.actor_user_id,v_ass.user_id,v_ref.active_family_person_id,
    'appointment_assignment_removed','appointment',v_ref.record_id,
    to_jsonb(v_ass),jsonb_build_object('status','removed'),'ถอดหน้าที่วันนัด'
  );

  return jsonb_build_object(
    'ok',true,
    'record_code',substr(v_ref.record_id::text,1,12),
    'assignee_code',substr(v_id::text,1,12),
    'display_name',private.family_user_label_for_viewer(
      v_ref.actor_user_id,v_ref.active_family_id,v_ass.user_id
    ),
    'role',v_ass.assignment_role
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_reschedule_accept(p_line_user_id text, p_request_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_actor uuid;
  v_req private.appointment_reschedule_requests%rowtype;
  v_count int;
  v_requester_label text;
  v_can_update boolean:=false;
begin
  select li.user_id into v_actor
  from public.line_identities li
  where li.line_user_id=p_line_user_id and li.is_active=true
  order by li.updated_at desc nulls last limit 1;
  if v_actor is null then raise exception 'line_identity_not_ready'; end if;

  select count(*)::int into v_count
  from private.appointment_reschedule_requests r
  where lower(r.id::text) like lower(btrim(p_request_code))||'%';
  if v_count=0 then raise exception 'reschedule_request_not_found'; end if;
  if v_count>1 then raise exception 'reschedule_request_code_ambiguous'; end if;

  select * into v_req
  from private.appointment_reschedule_requests r
  where lower(r.id::text) like lower(btrim(p_request_code))||'%'
  limit 1;

  if v_req.family_person_id is not null then
    v_can_update:=private.user_can_access_family_person(
      v_actor,v_req.family_person_id,'appointments','update'
    );
  end if;

  if v_req.assigned_to_user_id<>v_actor and not v_can_update then
    raise exception 'reschedule_request_not_assignee';
  end if;
  if v_req.status='completed' then raise exception 'reschedule_request_already_completed'; end if;
  if v_req.status='cancelled' then raise exception 'reschedule_request_cancelled'; end if;

  update private.appointment_reschedule_requests
  set status='in_progress',
      accepted_at=coalesce(accepted_at,now()),
      updated_at=now()
  where id=v_req.id
  returning * into v_req;

  if v_req.requested_by_user_id<>v_actor then
    v_requester_label:=private.family_user_label_for_viewer(
      v_req.requested_by_user_id,v_req.family_id,v_actor
    );
    insert into public.notifications(
      family_id,recipient_user_id,person_id,family_person_id,
      event_type,title,message,related_record_id,
      channel,priority,status,scheduled_for,next_attempt_at,
      payload,dedupe_key,created_at,updated_at
    ) values(
      v_req.family_id,v_req.requested_by_user_id,v_req.person_id,v_req.family_person_id,
      'appointment_reschedule_accepted',
      '✅ เริ่มดำเนินการเลื่อนนัดแล้ว',
      coalesce(v_requester_label,'ผู้ดำเนินการ')||' เริ่มดำเนินการงานเลื่อนนัดแล้ว',
      v_req.appointment_id,'line','normal','pending',now(),now(),
      jsonb_build_object(
        'appointment_id',v_req.appointment_id,
        'appointment_code',substr(v_req.appointment_id::text,1,12),
        'reschedule_code',substr(v_req.id::text,1,12)
      ),
      'appointment-reschedule-accepted:'||v_req.id::text||':'||v_actor::text,
      now(),now()
    )
    on conflict (dedupe_key) where dedupe_key is not null do nothing;
  end if;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    new_data,description
  ) values(
    v_req.family_id,v_actor,v_req.family_person_id,
    'appointment_reschedule_accepted','appointment',v_req.appointment_id,
    to_jsonb(v_req),
    case when v_actor=v_req.assigned_to_user_id
      then 'ผู้รับผิดชอบรับงานเลื่อนนัด'
      else 'ผู้มีสิทธิ์จัดการเริ่มดำเนินการงานเลื่อนนัด'
    end
  );

  return jsonb_build_object(
    'ok',true,
    'record_code',substr(v_req.appointment_id::text,1,12),
    'request_code',substr(v_req.id::text,1,12),
    'status',v_req.status,
    'acting_as_assignee',v_actor=v_req.assigned_to_user_id
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_reschedule_cancel(p_line_user_id text, p_request_code text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_actor uuid;
  v_req private.appointment_reschedule_requests%rowtype;
  v_count int;
  v_can_update boolean:=false;
  v_other uuid;
begin
  select li.user_id into v_actor
  from public.line_identities li
  where li.line_user_id=p_line_user_id and li.is_active=true
  order by li.updated_at desc nulls last limit 1;
  if v_actor is null then raise exception 'line_identity_not_ready'; end if;

  select count(*)::int into v_count
  from private.appointment_reschedule_requests r
  where lower(r.id::text) like lower(btrim(p_request_code))||'%';
  if v_count=0 then raise exception 'reschedule_request_not_found'; end if;
  if v_count>1 then raise exception 'reschedule_request_code_ambiguous'; end if;

  select * into v_req
  from private.appointment_reschedule_requests r
  where lower(r.id::text) like lower(btrim(p_request_code))||'%'
  limit 1;

  if v_req.status='completed' then raise exception 'reschedule_request_already_completed'; end if;
  if v_req.status='cancelled' then
    return jsonb_build_object('ok',true,'already_cancelled',true);
  end if;

  if v_req.family_person_id is not null then
    v_can_update:=private.user_can_access_family_person(
      v_actor,v_req.family_person_id,'appointments','update'
    );
  end if;

  if v_actor<>v_req.assigned_to_user_id
     and v_actor<>v_req.requested_by_user_id
     and not v_can_update then
    raise exception 'reschedule_request_not_authorized';
  end if;

  update private.appointment_reschedule_requests
  set status='cancelled',
      cancelled_at=now(),
      cancelled_by_user_id=v_actor,
      completion_note=coalesce(nullif(btrim(p_reason),''),completion_note),
      updated_at=now()
  where id=v_req.id
  returning * into v_req;

  v_other:=case
    when v_actor=v_req.requested_by_user_id then v_req.assigned_to_user_id
    else v_req.requested_by_user_id
  end;

  if v_other is not null and v_other<>v_actor then
    insert into public.notifications(
      family_id,recipient_user_id,person_id,family_person_id,
      event_type,title,message,related_record_id,
      channel,priority,status,scheduled_for,next_attempt_at,
      payload,dedupe_key,created_at,updated_at
    ) values(
      v_req.family_id,v_other,v_req.person_id,v_req.family_person_id,
      'appointment_reschedule_cancelled',
      '↩️ ยกเลิกงานเลื่อนนัด',
      coalesce(nullif(btrim(p_reason),''),'งานเลื่อนนัดนี้ถูกยกเลิก'),
      v_req.appointment_id,'line','normal','pending',now(),now(),
      jsonb_build_object(
        'appointment_id',v_req.appointment_id,
        'appointment_code',substr(v_req.appointment_id::text,1,12),
        'reschedule_code',substr(v_req.id::text,1,12)
      ),
      'appointment-reschedule-cancelled:'||v_req.id::text||':'||v_other::text,
      now(),now()
    )
    on conflict (dedupe_key) where dedupe_key is not null do nothing;
  end if;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    new_data,description
  ) values(
    v_req.family_id,v_actor,v_req.family_person_id,
    'appointment_reschedule_cancelled','appointment',v_req.appointment_id,
    to_jsonb(v_req),coalesce(nullif(btrim(p_reason),''),'ยกเลิกงานเลื่อนนัด')
  );

  return jsonb_build_object(
    'ok',true,
    'record_code',substr(v_req.appointment_id::text,1,12),
    'request_code',substr(v_req.id::text,1,12),
    'status','cancelled'
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_reschedule_complete(p_line_user_id text, p_request_code text, p_new_appointment_at timestamp with time zone, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_actor uuid;
  v_req private.appointment_reschedule_requests%rowtype;
  v_appt public.appointments%rowtype;
  v_old jsonb;
  v_new jsonb;
  v_count int;
  v_can_update boolean:=false;
  v_rec record;
  v_actor_label text;
  v_notification_count int:=0;
begin
  if p_new_appointment_at is null then raise exception 'new_appointment_at_required'; end if;
  if p_new_appointment_at<=now() then raise exception 'new_appointment_at_must_be_future'; end if;

  select li.user_id into v_actor
  from public.line_identities li
  where li.line_user_id=p_line_user_id and li.is_active=true
  order by li.updated_at desc nulls last limit 1;
  if v_actor is null then raise exception 'line_identity_not_ready'; end if;

  select count(*)::int into v_count
  from private.appointment_reschedule_requests r
  where lower(r.id::text) like lower(btrim(p_request_code))||'%';
  if v_count=0 then raise exception 'reschedule_request_not_found'; end if;
  if v_count>1 then raise exception 'reschedule_request_code_ambiguous'; end if;

  select * into v_req
  from private.appointment_reschedule_requests r
  where lower(r.id::text) like lower(btrim(p_request_code))||'%'
  limit 1;

  if v_req.status='completed' then
    return jsonb_build_object(
      'ok',true,'already_completed',true,
      'record_code',substr(v_req.appointment_id::text,1,12),
      'request_code',substr(v_req.id::text,1,12),
      'new_appointment_at',v_req.new_appointment_at
    );
  end if;
  if v_req.status='cancelled' then raise exception 'reschedule_request_cancelled'; end if;

  if v_req.family_person_id is not null then
    v_can_update:=private.user_can_access_family_person(
      v_actor,v_req.family_person_id,'appointments','update'
    );
  end if;

  if v_actor<>v_req.assigned_to_user_id and not v_can_update then
    raise exception 'reschedule_request_not_authorized';
  end if;

  select * into v_appt
  from public.appointments
  where id=v_req.appointment_id and deleted_at is null
  for update;

  if not found then raise exception 'appointment_not_found'; end if;
  if v_appt.status not in ('scheduled','confirmed') then
    raise exception 'appointment_not_reschedulable';
  end if;

  if v_appt.appointment_at is distinct from v_req.original_appointment_at
     and v_appt.appointment_at is distinct from p_new_appointment_at then
    raise exception 'appointment_changed_since_reschedule_request';
  end if;

  v_old:=to_jsonb(v_appt);

  update public.appointments
  set appointment_at=p_new_appointment_at,
      status=case when status='confirmed' then 'scheduled' else status end,
      last_change_reason=coalesce(nullif(btrim(p_note),''),'เลื่อนนัด'),
      updated_at=now()
  where id=v_appt.id;

  select to_jsonb(a) into v_new
  from public.appointments a where a.id=v_appt.id;

  update private.appointment_reschedule_requests
  set status='completed',
      accepted_at=coalesce(accepted_at,now()),
      new_appointment_at=p_new_appointment_at,
      completed_at=now(),
      completed_by_user_id=v_actor,
      recorded_by_user_id=coalesce(recorded_by_user_id,requested_by_user_id),
      performed_by_user_id=coalesce(performed_by_user_id,assigned_to_user_id,v_actor),
      performed_by_family_person_id=coalesce(performed_by_family_person_id,assigned_to_family_person_id),
      performed_at=now(),
      completion_note=nullif(btrim(p_note),''),
      updated_at=now()
  where id=v_req.id
  returning * into v_req;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    old_data,new_data,description
  ) values(
    v_req.family_id,v_actor,v_req.family_person_id,
    'appointment_rescheduled','appointment',v_req.appointment_id,
    v_old,v_new,
    coalesce(nullif(btrim(p_note),''),'เลื่อนนัดและปิดงานมอบหมาย')
  );

  perform private.phms_sync_auto_appointment_reminders(now());

  for v_rec in
    select distinct x.recipient_user_id
    from (
      select v_req.requested_by_user_id as recipient_user_id
      union
      select nr.recipient_user_id
      from private.phms_notification_recipients(v_req.person_id,'appointments') nr
      union
      select aa.user_id
      from public.appointment_assignees aa
      where aa.appointment_id=v_req.appointment_id
        and aa.user_id is not null
        and aa.status in ('assigned','accepted')
    ) x
    where x.recipient_user_id is not null
      and x.recipient_user_id<>v_actor
  loop
    v_actor_label:=private.family_user_label_for_viewer(
      v_rec.recipient_user_id,v_req.family_id,v_actor
    );

    insert into public.notifications(
      family_id,recipient_user_id,person_id,family_person_id,
      event_type,title,message,related_record_id,
      channel,priority,status,scheduled_for,next_attempt_at,
      payload,dedupe_key,created_at,updated_at
    )
    values(
      v_req.family_id,v_rec.recipient_user_id,v_req.person_id,v_req.family_person_id,
      'appointment_reschedule_completed',
      '✅ เลื่อนนัดเรียบร้อยแล้ว',
      concat(
        coalesce(v_actor_label,'ผู้รับผิดชอบ'),' ดำเนินการเลื่อนนัดเสร็จแล้ว',
        E'\nจาก: ',to_char(v_req.original_appointment_at at time zone 'Asia/Bangkok','DD/MM/YYYY HH24:MI'),' น.',
        E'\nเป็น: ',to_char(p_new_appointment_at at time zone 'Asia/Bangkok','DD/MM/YYYY HH24:MI'),' น.',
        case when nullif(btrim(p_note),'') is not null
          then E'\nหมายเหตุ: '||btrim(p_note) else '' end
      ),
      v_req.appointment_id,'line','high','pending',now(),now(),
      jsonb_build_object(
        'appointment_id',v_req.appointment_id,
        'appointment_code',substr(v_req.appointment_id::text,1,12),
        'reschedule_request_id',v_req.id,
        'reschedule_code',substr(v_req.id::text,1,12),
        'old_appointment_at',v_req.original_appointment_at,
        'new_appointment_at',p_new_appointment_at
      ),
      'appointment-reschedule-completed:'||v_req.id::text||':'||v_rec.recipient_user_id::text,
      now(),now()
    )
    on conflict (dedupe_key) where dedupe_key is not null do nothing;

    v_notification_count:=v_notification_count+1;
  end loop;

  return jsonb_build_object(
    'ok',true,
    'record_code',substr(v_req.appointment_id::text,1,12),
    'request_code',substr(v_req.id::text,1,12),
    'status','completed',
    'old_appointment_at',v_req.original_appointment_at,
    'new_appointment_at',p_new_appointment_at,
    'notifications_queued',v_notification_count
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_reschedule_create(p_line_user_id text, p_record_code text, p_mode text DEFAULT 'self'::text, p_assignee_code text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_requested_appointment_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_appt public.appointments%rowtype;
  v_mode text:=lower(btrim(coalesce(p_mode,'self')));
  v_code text:=lower(btrim(coalesce(p_assignee_code,'')));
  v_assignee_user uuid;
  v_assignee_fp uuid;
  v_count int:=0;
  v_req private.appointment_reschedule_requests%rowtype;
  v_requester_label text;
  v_assignee_label text;
  v_line_ready boolean:=false;
begin
  if v_mode not in ('self','delegate') then raise exception 'invalid_reschedule_mode'; end if;

  select * into v_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',p_record_code,'update'
  ) limit 1;

  select * into v_appt
  from public.appointments
  where id=v_ref.record_id and deleted_at is null;

  if not found then raise exception 'appointment_not_found'; end if;
  if v_appt.status not in ('scheduled','confirmed') then
    raise exception 'appointment_not_reschedulable';
  end if;

  if exists(
    select 1 from private.appointment_reschedule_requests r
    where r.appointment_id=v_appt.id
      and r.status in ('pending','in_progress')
  ) then
    raise exception 'reschedule_request_already_active';
  end if;

  if v_mode='self' then
    v_assignee_user:=v_ref.actor_user_id;
    select fp.id into v_assignee_fp
    from public.family_persons fp
    join public.persons p on p.id=fp.person_id
    where fp.family_id=v_ref.active_family_id
      and p.linked_user_id=v_assignee_user
      and coalesce(fp.status,'active')='active'
    limit 1;
  else
    if length(v_code)<6 then raise exception 'reschedule_assignee_required'; end if;

    select count(*)::int into v_count
    from public.family_persons fp
    join public.persons p on p.id=fp.person_id
    where fp.family_id=v_ref.active_family_id
      and coalesce(fp.status,'active')='active'
      and coalesce(p.status,'active')='active'
      and lower(fp.id::text) like v_code||'%';

    if v_count>0 then
      select fp.id,p.linked_user_id
      into v_assignee_fp,v_assignee_user
      from public.family_persons fp
      join public.persons p on p.id=fp.person_id
      where fp.family_id=v_ref.active_family_id
        and coalesce(fp.status,'active')='active'
        and coalesce(p.status,'active')='active'
        and lower(fp.id::text) like v_code||'%'
      order by fp.id
      limit 1;
    else
      select count(*)::int into v_count
      from public.family_memberships fm
      where fm.family_id=v_ref.active_family_id
        and fm.status='active'
        and fm.user_id is not null
        and lower(fm.user_id::text) like v_code||'%';

      if v_count>0 then
        select fm.user_id into v_assignee_user
        from public.family_memberships fm
        where fm.family_id=v_ref.active_family_id
          and fm.status='active'
          and fm.user_id is not null
          and lower(fm.user_id::text) like v_code||'%'
        order by fm.user_id
        limit 1;
      end if;
      v_assignee_fp:=null;
    end if;

    if v_count=0 then raise exception 'reschedule_assignee_not_found'; end if;
    if v_count>1 then raise exception 'reschedule_assignee_ambiguous'; end if;
    if v_assignee_user is null then raise exception 'reschedule_assignee_account_required'; end if;

    select exists(
      select 1 from public.line_identities li
      where li.user_id=v_assignee_user
        and li.is_active=true
        and li.onboarding_status='ready'
    ) into v_line_ready;

    if not v_line_ready then raise exception 'reschedule_assignee_line_required'; end if;
  end if;

  insert into private.appointment_reschedule_requests(
    appointment_id,family_id,person_id,family_person_id,
    requested_by_user_id,assigned_to_user_id,assigned_to_family_person_id,
    status,reason,original_appointment_at,requested_appointment_at,
    accepted_at,entry_mode,recorded_by_user_id,performed_by_user_id,performed_by_family_person_id
  )
  values(
    v_appt.id,v_appt.family_id,v_appt.person_id,v_appt.family_person_id,
    v_ref.actor_user_id,v_assignee_user,v_assignee_fp,
    case when v_assignee_user=v_ref.actor_user_id then 'in_progress' else 'pending' end,
    nullif(btrim(p_reason),''),
    v_appt.appointment_at,p_requested_appointment_at,
    case when v_assignee_user=v_ref.actor_user_id then now() else null end,
    'task',v_ref.actor_user_id,v_assignee_user,v_assignee_fp
  )
  returning * into v_req;

  v_requester_label:=private.family_user_label_for_viewer(
    v_assignee_user,v_appt.family_id,v_ref.actor_user_id
  );
  v_assignee_label:=private.family_user_label_for_viewer(
    v_ref.actor_user_id,v_appt.family_id,v_assignee_user
  );

  if v_assignee_user<>v_ref.actor_user_id then
    insert into public.notifications(
      family_id,recipient_user_id,person_id,family_person_id,
      event_type,title,message,related_record_id,
      channel,priority,status,scheduled_for,next_attempt_at,
      payload,dedupe_key,created_at,updated_at
    )
    values(
      v_appt.family_id,v_assignee_user,v_appt.person_id,v_appt.family_person_id,
      'appointment_reschedule_assigned',
      '🔄 มีงานให้ช่วยเลื่อนนัด',
      concat(
        'มอบหมายโดย: ',coalesce(v_requester_label,'สมาชิกครอบครัว'),
        E'\nนัด: ',coalesce(nullif(btrim(v_appt.title),''),'นัดหมาย'),
        E'\nวันเวลาเดิม: ',to_char(v_appt.appointment_at at time zone 'Asia/Bangkok','DD/MM/YYYY HH24:MI'),' น.',
        case when nullif(btrim(v_appt.hospital_name),'') is not null
          then E'\nสถานพยาบาล: '||v_appt.hospital_name else '' end,
        case when nullif(btrim(p_reason),'') is not null
          then E'\nเหตุผล/รายละเอียด: '||btrim(p_reason) else '' end
      ),
      v_appt.id,'line','high','pending',now(),now(),
      jsonb_build_object(
        'appointment_id',v_appt.id,
        'appointment_code',substr(v_appt.id::text,1,12),
        'reschedule_request_id',v_req.id,
        'reschedule_code',substr(v_req.id::text,1,12),
        'scoped_only',true
      ),
      'appointment-reschedule-assigned:'||v_req.id::text||':'||v_assignee_user::text,
      now(),now()
    );
  end if;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    new_data,description
  )
  values(
    v_appt.family_id,v_ref.actor_user_id,v_appt.family_person_id,
    'appointment_reschedule_requested','appointment',v_appt.id,
    to_jsonb(v_req),
    case when v_assignee_user=v_ref.actor_user_id
      then 'เริ่มดำเนินการเลื่อนนัดด้วยตนเอง'
      else 'มอบหมายให้สมาชิกครอบครัวช่วยเลื่อนนัด'
    end
  );

  return jsonb_build_object(
    'ok',true,
    'record_code',substr(v_appt.id::text,1,12),
    'request_code',substr(v_req.id::text,1,12),
    'status',v_req.status,
    'assignee_name',v_assignee_label,
    'assigned_to_self',v_assignee_user=v_ref.actor_user_id,
    'notification_queued',v_assignee_user<>v_ref.actor_user_id
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_reschedule_get(p_line_user_id text, p_record_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_actor uuid;
  v_ref record;
  v_appt public.appointments%rowtype;
  v_req private.appointment_reschedule_requests%rowtype;
  v_can_manage boolean:=false;
  v_is_assignee boolean:=false;
  v_scoped_only boolean:=false;
  v_requester_name text;
  v_assignee_name text;
  v_recorder_name text;
  v_performer_name text;
  v_count int:=0;
begin
  select li.user_id into v_actor
  from public.line_identities li
  where li.line_user_id=p_line_user_id
    and li.is_active=true
  order by li.updated_at desc nulls last
  limit 1;

  if v_actor is null then raise exception 'line_identity_not_ready'; end if;

  begin
    select * into v_ref
    from private.phms_find_crud_record(
      p_line_user_id,'appointment',p_record_code,'view'
    ) limit 1;
    v_can_manage:=private.user_can_access_family_person(
      v_actor,v_ref.active_family_person_id,'appointments','update'
    );
    select * into v_appt
    from public.appointments
    where id=v_ref.record_id and deleted_at is null;
  exception when others then
    v_scoped_only:=true;

    select count(*)::int into v_count
    from private.appointment_reschedule_requests r
    join public.appointments a on a.id=r.appointment_id
    where lower(a.id::text) like lower(btrim(p_record_code))||'%'
      and r.assigned_to_user_id=v_actor
      and a.deleted_at is null;

    if v_count=0 then raise exception 'appointment_reschedule_not_accessible'; end if;

    select a.* into v_appt
    from private.appointment_reschedule_requests r
    join public.appointments a on a.id=r.appointment_id
    where lower(a.id::text) like lower(btrim(p_record_code))||'%'
      and r.assigned_to_user_id=v_actor
      and a.deleted_at is null
    order by r.updated_at desc
    limit 1;
  end;

  if v_scoped_only then
    select * into v_req
    from private.appointment_reschedule_requests r
    where r.appointment_id=v_appt.id
      and r.assigned_to_user_id=v_actor
    order by
      case when r.status in ('pending','in_progress') then 0 else 1 end,
      r.updated_at desc
    limit 1;
  else
    select * into v_req
    from private.appointment_reschedule_requests r
    where r.appointment_id=v_appt.id
    order by
      case when r.status in ('pending','in_progress') then 0 else 1 end,
      r.updated_at desc
    limit 1;
  end if;

  if v_req.id is not null then
    v_is_assignee:=v_req.assigned_to_user_id=v_actor;
    v_requester_name:=private.family_user_label_for_viewer(
      v_actor,v_req.family_id,v_req.requested_by_user_id
    );
    v_assignee_name:=private.family_user_label_for_viewer(
      v_actor,v_req.family_id,v_req.assigned_to_user_id
    );
    v_recorder_name:=private.family_user_label_for_viewer(
      v_actor,v_req.family_id,coalesce(v_req.recorded_by_user_id,v_req.requested_by_user_id)
    );
    v_performer_name:=private.family_user_label_for_viewer(
      v_actor,v_req.family_id,coalesce(v_req.performed_by_user_id,v_req.assigned_to_user_id)
    );
  end if;

  return jsonb_build_object(
    'ok',true,
    'record_code',substr(v_appt.id::text,1,12),
    'appointment',jsonb_strip_nulls(jsonb_build_object(
      'id',v_appt.id,
      'title',v_appt.title,
      'appointment_at',v_appt.appointment_at,
      'hospital_name',v_appt.hospital_name,
      'department',v_appt.department,
      'status',v_appt.status
    )),
    'can_manage',v_can_manage,
    'scoped_only',v_scoped_only,
    'is_assignee',v_is_assignee,
    'request',case when v_req.id is null then null else jsonb_strip_nulls(jsonb_build_object(
      'id',v_req.id,
      'code',substr(v_req.id::text,1,12),
      'status',v_req.status,
      'entry_mode',coalesce(v_req.entry_mode,'task'),
      'reason',v_req.reason,
      'original_appointment_at',v_req.original_appointment_at,
      'requested_appointment_at',v_req.requested_appointment_at,
      'new_appointment_at',v_req.new_appointment_at,
      'requested_at',v_req.requested_at,
      'accepted_at',v_req.accepted_at,
      'completed_at',v_req.completed_at,
      'completion_note',v_req.completion_note,
      'requested_by_user_id',v_req.requested_by_user_id,
      'assigned_to_user_id',v_req.assigned_to_user_id,
      'requester_name',v_requester_name,
      'assignee_name',v_assignee_name,
      'recorder_name',v_recorder_name,
      'performer_name',v_performer_name,
      'performed_at',v_req.performed_at,
      'is_assignee',v_is_assignee
    )) end
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_reschedule_log(p_line_user_id text, p_record_code text, p_performer_code text, p_new_appointment_at timestamp with time zone, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_appt public.appointments%rowtype;
  v_code text:=lower(btrim(coalesce(p_performer_code,'')));
  v_performer_user uuid;
  v_performer_fp uuid;
  v_count int:=0;
  v_req private.appointment_reschedule_requests%rowtype;
  v_old jsonb;
  v_new jsonb;
  v_performer_name text;
begin
  if p_new_appointment_at is null then
    raise exception 'new_appointment_at_required';
  end if;

  select * into v_ref
  from private.phms_line_appointment_access(
    p_line_user_id,p_record_code
  ) limit 1;

  if coalesce(v_ref.can_update,false) is not true then
    raise exception 'appointment_reschedule_log_update_denied';
  end if;

  select * into v_appt
  from public.appointments
  where id=v_ref.record_id and deleted_at is null
  for update;
  if not found then raise exception 'appointment_not_found'; end if;

  if length(v_code)<6 then
    raise exception 'reschedule_performer_required';
  end if;

  select count(*)::int into v_count
  from public.family_persons fp
  join public.persons p on p.id=fp.person_id
  where fp.family_id=v_ref.active_family_id
    and coalesce(fp.status,'active')='active'
    and lower(fp.id::text) like v_code||'%';

  if v_count=1 then
    select fp.id,p.linked_user_id
    into v_performer_fp,v_performer_user
    from public.family_persons fp
    join public.persons p on p.id=fp.person_id
    where fp.family_id=v_ref.active_family_id
      and coalesce(fp.status,'active')='active'
      and lower(fp.id::text) like v_code||'%'
    order by fp.id::text
    limit 1;
  end if;

  if v_count=0 then
    select count(*)::int into v_count
    from public.family_memberships fm
    where fm.family_id=v_ref.active_family_id
      and fm.status='active'
      and fm.user_id is not null
      and lower(fm.user_id::text) like v_code||'%';
    if v_count=1 then
      select fm.user_id into v_performer_user
      from public.family_memberships fm
      where fm.family_id=v_ref.active_family_id
        and fm.status='active'
        and fm.user_id is not null
        and lower(fm.user_id::text) like v_code||'%'
      order by fm.user_id::text
      limit 1;
    end if;
    v_performer_fp:=null;
  end if;

  if v_count=0 then raise exception 'reschedule_performer_not_found'; end if;
  if v_count>1 then raise exception 'reschedule_performer_ambiguous'; end if;
  if v_performer_user is null then
    raise exception 'reschedule_performer_account_required';
  end if;

  v_old:=to_jsonb(v_appt);

  update public.appointments
  set appointment_at=p_new_appointment_at,
      status=case when status='confirmed' then 'scheduled' else status end,
      last_change_reason=coalesce(nullif(btrim(p_note),''),'บันทึกประวัติการเลื่อนนัด'),
      updated_at=now()
  where id=v_appt.id;

  select to_jsonb(a) into v_new
  from public.appointments a where a.id=v_appt.id;

  insert into private.appointment_reschedule_requests(
    appointment_id,family_id,person_id,family_person_id,
    requested_by_user_id,assigned_to_user_id,assigned_to_family_person_id,
    status,reason,original_appointment_at,new_appointment_at,
    requested_at,accepted_at,completed_at,completed_by_user_id,completion_note,
    entry_mode,recorded_by_user_id,performed_by_user_id,
    performed_by_family_person_id,performed_at,updated_at
  )
  values(
    v_appt.id,v_appt.family_id,v_appt.person_id,v_appt.family_person_id,
    v_ref.actor_user_id,v_performer_user,v_performer_fp,
    'completed',nullif(btrim(p_note),''),
    v_appt.appointment_at,p_new_appointment_at,
    now(),now(),now(),v_ref.actor_user_id,nullif(btrim(p_note),''),
    'history',v_ref.actor_user_id,v_performer_user,v_performer_fp,now(),now()
  )
  returning * into v_req;

  v_performer_name:=private.family_user_label_for_viewer(
    v_ref.actor_user_id,v_ref.active_family_id,v_performer_user
  );

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,
    event_type,resource,record_id,old_data,new_data,description
  ) values(
    v_appt.family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
    'appointment_rescheduled','appointment',v_appt.id,
    v_old,
    v_new||jsonb_build_object(
      'reschedule_entry_mode','history',
      'reschedule_recorded_by_user_id',v_ref.actor_user_id,
      'reschedule_performed_by_user_id',v_performer_user,
      'reschedule_performer_name',v_performer_name
    ),
    'บันทึกประวัติการเลื่อนนัด • ผู้เลื่อนจริง: '||
      coalesce(v_performer_name,'สมาชิกครอบครัว')
  );

  perform private.phms_sync_auto_appointment_reminders(now());

  return jsonb_build_object(
    'ok',true,
    'record_code',substr(v_appt.id::text,1,12),
    'request_code',substr(v_req.id::text,1,12),
    'entry_mode','history',
    'performer_name',v_performer_name,
    'recorded_by_user_id',v_ref.actor_user_id,
    'old_appointment_at',v_appt.appointment_at,
    'new_appointment_at',p_new_appointment_at
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_set_assignee(p_line_user_id text, p_record_code text, p_user_code text, p_role text DEFAULT 'responsible'::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_role text:=lower(btrim(coalesce(p_role,'responsible')));
  v_code text:=lower(btrim(coalesce(p_user_code,'')));
  v_target_user uuid;
  v_target_family_person uuid;
  v_count int;
  v_assignee public.appointment_assignees%rowtype;
  v_ack jsonb;
  v_has_view boolean:=false;
  v_display_name text;
begin
  if v_role not in ('booker','caregiver','driver','companion','responsible','other','documents') then
    raise exception 'invalid_assignment_role';
  end if;
  if length(v_code)<6 then raise exception 'assignee_code_too_short'; end if;

  select * into v_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',p_record_code,'update'
  ) limit 1;

  select count(*),min(fp.id),min(p.linked_user_id)
  into v_count,v_target_family_person,v_target_user
  from public.family_persons fp
  join public.persons p on p.id=fp.person_id
  where fp.family_id=v_ref.active_family_id
    and coalesce(fp.status,'active')='active'
    and coalesce(p.status,'active')='active'
    and lower(fp.id::text) like v_code||'%';

  if v_count=0 then
    select count(*),min(fm.user_id)
    into v_count,v_target_user
    from public.family_memberships fm
    where fm.family_id=v_ref.active_family_id
      and fm.status='active'
      and fm.user_id is not null
      and lower(fm.user_id::text) like v_code||'%';
    v_target_family_person:=null;
  end if;

  if v_count=0 then raise exception 'assignee_not_family_member'; end if;
  if v_count>1 then raise exception 'assignee_code_ambiguous'; end if;

  if v_target_family_person is not null then
    v_display_name:=private.family_person_label_for_viewer(
      v_ref.actor_user_id,v_target_family_person
    );
  else
    v_display_name:=private.family_user_label_for_viewer(
      v_ref.actor_user_id,v_ref.active_family_id,v_target_user
    );
  end if;

  if v_target_user is not null then
    v_has_view:=private.user_can_access_family_person(
      v_target_user,v_ref.active_family_person_id,'appointments','view'
    );
  end if;

  if v_target_family_person is not null then
    insert into public.appointment_assignees(
      appointment_id,user_id,family_person_id,assignment_role,status,requires_ack,
      assigned_by,assigned_at,note,updated_at
    )
    values(
      v_ref.record_id,v_target_user,v_target_family_person,v_role,'assigned',
      (v_target_user is not null),
      v_ref.actor_user_id,now(),nullif(btrim(p_note),''),now()
    )
    on conflict(appointment_id,family_person_id,assignment_role)
      where family_person_id is not null
    do update set
      user_id=excluded.user_id,
      status='assigned',
      requires_ack=excluded.requires_ack,
      assigned_by=v_ref.actor_user_id,
      assigned_at=now(),
      acknowledged_at=null,
      note=excluded.note,
      updated_at=now()
    returning * into v_assignee;
  else
    insert into public.appointment_assignees(
      appointment_id,user_id,family_person_id,assignment_role,status,requires_ack,
      assigned_by,assigned_at,note,updated_at
    )
    values(
      v_ref.record_id,v_target_user,null,v_role,'assigned',true,
      v_ref.actor_user_id,now(),nullif(btrim(p_note),''),now()
    )
    on conflict(appointment_id,user_id,assignment_role)
    do update set
      status='assigned',
      requires_ack=true,
      assigned_by=v_ref.actor_user_id,
      assigned_at=now(),
      acknowledged_at=null,
      note=excluded.note,
      updated_at=now()
    returning * into v_assignee;
  end if;

  if v_assignee.user_id is null then
    update public.appointment_assignees
    set requires_ack=false,status='assigned',acknowledged_at=null,updated_at=now()
    where id=v_assignee.id;

    v_ack:=jsonb_build_object(
      'ok',true,
      'require_ack',false,
      'status','assigned',
      'line_unlinked',true
    );
  else
    v_ack:=private.phms_schedule_appointment_assignee_ack(
      v_assignee.id,v_ref.actor_user_id
    );
  end if;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    new_data,description
  )
  values(
    v_ref.active_family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
    'appointment_assignment','appointment',v_ref.record_id,
    to_jsonb(v_assignee)||jsonb_build_object(
      'ack_policy',v_ack,
      'assignee_had_appointment_view',v_has_view,
      'assignment_scoped_only',not v_has_view,
      'assignee_family_person_id',v_target_family_person
    ),
    coalesce(nullif(btrim(p_note),''),'มอบหมายหน้าที่วันนัด')
  );

  return jsonb_build_object(
    'ok',true,
    'record_code',substr(v_ref.record_id::text,1,12),
    'assignee_code',substr(v_assignee.id::text,1,12),
    'user_id',v_target_user,
    'family_person_id',v_target_family_person,
    'display_name',v_display_name,
    'role',v_role,
    'status',coalesce(v_ack->>'status',v_assignee.status),
    'require_ack',coalesce((v_ack->>'require_ack')::boolean,false),
    'ack_code',v_ack->>'ack_code',
    'scheduled_for',v_ack->>'scheduled_for',
    'has_appointment_view',v_has_view,
    'assignment_scoped_only',not v_has_view,
    'line_unlinked',(v_target_user is null)
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_set_assignee_ack_policy(p_line_user_id text, p_record_code text, p_days_before integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_days integer;
  v_ass record;
  v_count int:=0;
begin
  select * into v_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',p_record_code,'update'
  ) limit 1;

  v_days:=case
    when p_days_before is null or p_days_before<=0 then null
    else greatest(1,least(p_days_before,30))
  end;

  update public.appointments
  set assignee_ack_days_before=v_days,updated_at=now()
  where id=v_ref.record_id;

  if v_days is null then
    update public.notifications n
    set status='cancelled',updated_at=now(),last_error='assignment_ack_policy_disabled'
    where n.id in (
      select ak.notification_id
      from public.appointment_acknowledgements ak
      where ak.appointment_id=v_ref.record_id
        and ak.ack_type='assignment'
        and ak.status='pending'
        and ak.notification_id is not null
    )
    and n.status in ('pending','failed');

    update public.appointment_acknowledgements
    set status='expired',updated_at=now()
    where appointment_id=v_ref.record_id
      and ack_type='assignment'
      and status='pending';

    update public.appointment_assignees
    set requires_ack=false,
        status=case when status='assigned' then 'accepted' else status end,
        updated_at=now()
    where appointment_id=v_ref.record_id
      and status<>'removed';
  else
    for v_ass in
      select id
      from public.appointment_assignees
      where appointment_id=v_ref.record_id
        and status<>'removed'
    loop
      perform private.phms_schedule_appointment_assignee_ack(
        v_ass.id,v_ref.actor_user_id
      );
      v_count:=v_count+1;
    end loop;
  end if;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,new_data,description
  )
  values(
    v_ref.active_family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
    'appointment_assignment_ack_policy','appointment',v_ref.record_id,
    jsonb_build_object('days_before',v_days),
    case when v_days is null then 'ไม่ต้องให้ผู้รับผิดชอบยืนยันล่วงหน้า'
         else 'ให้ผู้รับผิดชอบยืนยันก่อนนัด '||v_days::text||' วัน' end
  );

  return jsonb_build_object(
    'ok',true,
    'record_code',substr(v_ref.record_id::text,1,12),
    'days_before',v_days,
    'assignees_processed',v_count
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_set_contact_email(p_line_user_id text, p_record_code text, p_contact_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_email text:=lower(btrim(coalesce(p_contact_email,'')));
  v_old text;
begin
  if v_email<>'' and v_email !~* '^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$' then
    raise exception 'invalid_contact_email';
  end if;

  select * into v_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',p_record_code,'update'
  ) limit 1;

  select contact_email into v_old
  from public.appointments where id=v_ref.record_id;

  update public.appointments
  set contact_email=nullif(v_email,''),updated_at=now()
  where id=v_ref.record_id;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    old_data,new_data,description
  ) values(
    v_ref.active_family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
    'appointment_contact_update','appointment',v_ref.record_id,
    jsonb_build_object('contact_email',v_old),
    jsonb_build_object('contact_email',nullif(v_email,'')),
    'แก้อีเมลติดต่อของนัด'
  );

  return jsonb_build_object(
    'ok',true,'record_code',substr(v_ref.record_id::text,1,12),
    'contact_email',nullif(v_email,'')
  );
end
$function$

