CREATE OR REPLACE FUNCTION public.phms_line_appointment_set_group_channel_target(p_line_user_id text, p_record_code text, p_channel_code text, p_enabled boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_appt public.appointments%rowtype;
  v_fc public.family_channels%rowtype;
  v_fc_id uuid;
  v_count integer;
  v_row public.appointment_line_group_targets%rowtype;
begin
  select * into v_ref
  from private.phms_find_crud_record(p_line_user_id,'appointment',p_record_code,'update')
  limit 1;

  if not coalesce((
    select (coalesce((a.v->>'is_primary_caregiver')::boolean,false)
         or coalesce((a.v->>'is_self_manager')::boolean,false)
         or coalesce((a.v->>'is_authorized_helper')::boolean,false))
    from (select public.phms_line_appointment_action_capabilities(p_line_user_id,p_record_code) v) a
  ),false) then
    raise exception 'appointment_notification_permission_denied';
  end if;

  select * into v_appt
  from public.appointments
  where id=v_ref.record_id and deleted_at is null;

  if not private.user_has_family_role(v_ref.actor_user_id,v_appt.family_id,array['owner','admin'])
    then raise exception 'group_notification_permission_denied'; end if;

  select count(*),min(fc.id::text)::uuid
  into v_count,v_fc_id
  from public.family_channels fc
  where fc.channel_type='line_group'
    and fc.status='active'
    and lower(fc.id::text) like lower(btrim(p_channel_code))||'%'
    and exists(
      select 1 from public.family_channel_family_links l
      where l.family_channel_id=fc.id
        and l.family_id=v_appt.family_id
        and l.status='active'
    );

  if v_count=0 then raise exception 'family_group_not_found'; end if;
  if v_count>1 then raise exception 'family_group_code_ambiguous'; end if;

  select * into v_fc from public.family_channels where id=v_fc_id;

  insert into public.appointment_line_group_targets(
    appointment_id,line_group_id,status,created_by,updated_at,disabled_at,family_channel_id
  ) values(
    v_appt.id,v_fc.external_channel_id,
    case when coalesce(p_enabled,true) then 'active' else 'disabled' end,
    v_ref.actor_user_id,now(),
    case when coalesce(p_enabled,true) then null else now() end,
    v_fc.id
  )
  on conflict(appointment_id,line_group_id)
  do update set
    status=excluded.status,
    created_by=v_ref.actor_user_id,
    updated_at=now(),
    disabled_at=excluded.disabled_at,
    family_channel_id=v_fc.id
  returning * into v_row;

  perform private.phms_sync_auto_appointment_reminders(now());

  return public.phms_line_appointment_notification_workspace(
    p_line_user_id,substr(v_appt.id::text,1,12)
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_set_group_target(p_line_user_id text, p_record_code text, p_line_group_id text, p_enabled boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_appt public.appointments%rowtype;
  v_fc public.family_channels%rowtype;
  v_row public.appointment_line_group_targets%rowtype;
begin
  if length(btrim(coalesce(p_line_group_id,'')))<8
    then raise exception 'invalid_line_group_id'; end if;

  select * into v_ref
  from private.phms_find_crud_record(p_line_user_id,'appointment',p_record_code,'update')
  limit 1;

  if not coalesce((
    select (coalesce((a.v->>'is_primary_caregiver')::boolean,false)
         or coalesce((a.v->>'is_self_manager')::boolean,false)
         or coalesce((a.v->>'is_authorized_helper')::boolean,false))
    from (select public.phms_line_appointment_action_capabilities(p_line_user_id,p_record_code) v) a
  ),false) then
    raise exception 'appointment_notification_permission_denied';
  end if;

  select * into v_appt
  from public.appointments
  where id=v_ref.record_id and deleted_at is null;

  if not private.user_has_family_role(v_ref.actor_user_id,v_appt.family_id,array['owner','admin'])
    then raise exception 'group_notification_permission_denied'; end if;

  select * into v_fc
  from public.family_channels fc
  where fc.channel_type='line_group'
    and fc.external_channel_id=btrim(p_line_group_id)
    and fc.status='active'
    and exists(
      select 1 from public.family_channel_family_links l
      where l.family_channel_id=fc.id
        and l.family_id=v_appt.family_id
        and l.status='active'
    )
  limit 1;

  if coalesce(p_enabled,true) and v_fc.id is null then
    raise exception 'line_group_not_linked_to_appointment_family';
  end if;

  insert into public.appointment_line_group_targets(
    appointment_id,line_group_id,status,created_by,updated_at,disabled_at,family_channel_id
  ) values(
    v_appt.id,btrim(p_line_group_id),
    case when coalesce(p_enabled,true) then 'active' else 'disabled' end,
    v_ref.actor_user_id,now(),
    case when coalesce(p_enabled,true) then null else now() end,
    v_fc.id
  )
  on conflict(appointment_id,line_group_id)
  do update set
    status=excluded.status,
    created_by=v_ref.actor_user_id,
    updated_at=now(),
    disabled_at=excluded.disabled_at,
    family_channel_id=coalesce(
      excluded.family_channel_id,
      public.appointment_line_group_targets.family_channel_id
    )
  returning * into v_row;

  perform private.phms_sync_auto_appointment_reminders(now());

  return jsonb_build_object(
    'ok',true,
    'appointment_code',substr(v_appt.id::text,1,12),
    'status',v_row.status,
    'channel_name',v_fc.channel_name
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_set_notification_schedule(p_line_user_id text, p_record_code text, p_days_before integer[] DEFAULT ARRAY[3], p_time_local text DEFAULT '09:00'::text, p_recipient_mode text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_days integer[];
  v_time time;
  v_mode text;
  v_sync jsonb;
begin
  select * into v_ref
  from private.phms_find_crud_record(p_line_user_id,'appointment',p_record_code,'update')
  limit 1;

  if not coalesce((
    select (coalesce((a.v->>'is_primary_caregiver')::boolean,false)
         or coalesce((a.v->>'is_self_manager')::boolean,false)
         or coalesce((a.v->>'is_authorized_helper')::boolean,false))
    from (select public.phms_line_appointment_action_capabilities(p_line_user_id,p_record_code) v) a
  ),false) then
    raise exception 'appointment_notification_permission_denied';
  end if;

  select coalesce(array_agg(distinct d order by d desc),array[3]) into v_days
  from unnest(coalesce(p_days_before,array[3])) d
  where d between 0 and 60;
  if coalesce(array_length(v_days,1),0)=0 then v_days:=array[3]; end if;

  if btrim(coalesce(p_time_local,'')) !~ '^([01]?[0-9]|2[0-3]):[0-5][0-9]$' then
    raise exception 'invalid_time';
  end if;
  v_time:=btrim(p_time_local)::time;

  select coalesce(
    nullif(lower(btrim(coalesce(p_recipient_mode,''))),''),
    (select s.recipient_mode from public.appointment_notification_settings s where s.appointment_id=v_ref.record_id),
    'default'
  ) into v_mode;
  if v_mode not in ('default','custom') then raise exception 'invalid_recipient_mode'; end if;

  insert into public.appointment_notification_settings(
    appointment_id,days_before,local_time,timezone,recipient_mode,created_by,updated_by,created_at,updated_at
  ) values(
    v_ref.record_id,v_days,v_time,'Asia/Bangkok',v_mode,v_ref.actor_user_id,v_ref.actor_user_id,now(),now()
  )
  on conflict(appointment_id) do update set
    days_before=excluded.days_before,
    local_time=excluded.local_time,
    timezone='Asia/Bangkok',
    recipient_mode=excluded.recipient_mode,
    updated_by=v_ref.actor_user_id,
    updated_at=now();

  v_sync:=private.phms_sync_auto_appointment_reminders(now());

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,new_data,description
  ) values(
    v_ref.active_family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
    'appointment_notification_schedule','appointment',v_ref.record_id,
    jsonb_build_object('days_before',v_days,'time',to_char(v_time,'HH24:MI'),'recipient_mode',v_mode),
    'ตั้งค่าการแจ้งเตือนนัดแบบวันปฏิทิน'
  );

  return public.phms_line_appointment_notification_workspace(p_line_user_id,substr(v_ref.record_id::text,1,12))
    || jsonb_build_object('sync',v_sync);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_set_notification_user_target(p_line_user_id text, p_record_code text, p_user_code text, p_enabled boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_appt public.appointments%rowtype;
