$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_set_reminders(p_line_user_id text, p_record_code text, p_offsets_minutes integer[] DEFAULT ARRAY[10080, 4320, 1440], p_post_visit_minutes integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_offsets integer[];
  v_post integer;
  v_post_time time;
  v_old jsonb;
  v_new jsonb;
  v_sync jsonb;
begin
  select * into v_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',p_record_code,'update'
  ) limit 1;

  if not coalesce((
    select (coalesce((a.v->>'is_primary_caregiver')::boolean,false)
         or coalesce((a.v->>'is_self_manager')::boolean,false)
         or coalesce((a.v->>'is_authorized_helper')::boolean,false))
    from (select public.phms_line_appointment_action_capabilities(p_line_user_id,p_record_code) v) a
  ),false) then
    raise exception 'appointment_notification_permission_denied';
  end if;

  select coalesce(array_agg(distinct x order by x desc),'{}'::integer[])
  into v_offsets
  from unnest(coalesce(p_offsets_minutes,'{}'::integer[])) x
  where x between 30 and 40320;

  if p_post_visit_minutes is null then
    v_post:=0;
    v_post_time:='20:00'::time;
  elsif p_post_visit_minutes<=0 then
    v_post:=0;
    v_post_time:=null;
  else
    v_post:=greatest(1,least(p_post_visit_minutes,10080));
    v_post_time:=null;
  end if;

  select to_jsonb(a) into v_old from public.appointments a where a.id=v_ref.record_id;

  update public.appointments
  set reminder_offsets_minutes=v_offsets,
      post_visit_followup_minutes=v_post,
      post_visit_followup_time_local=v_post_time,
      updated_at=now()
  where id=v_ref.record_id;

  select to_jsonb(a) into v_new from public.appointments a where a.id=v_ref.record_id;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    old_data,new_data,description
  )
  values(
    v_ref.active_family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
    'appointment_reminder_settings','appointment',v_ref.record_id,
    v_old,v_new,'ตั้งค่าการเตือนนัด'
  );

  v_sync:=private.phms_sync_auto_appointment_reminders(now());

  return jsonb_build_object(
    'ok',true,
    'record_code',substr(v_ref.record_id::text,1,12),
    'reminder_offsets_minutes',v_offsets,
    'post_visit_followup_minutes',v_post,
    'post_visit_followup_time_local',case when v_post_time is null then null else to_char(v_post_time,'HH24:MI') end,
    'sync',v_sync
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_set_visit_status(p_line_user_id text, p_record_code text, p_status text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_status text:=lower(btrim(coalesce(p_status,'')));
  v_old jsonb;
  v_new jsonb;
  v_notify jsonb:=jsonb_build_object('ok',true,'user_notifications',0,'group_notifications',0,'patient_ack_requests',0);
begin
  if v_status not in ('confirmed','arrived','no_show') then
    raise exception 'invalid_appointment_visit_status';
  end if;

  select * into v_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',p_record_code,'update'
  ) limit 1;

  select to_jsonb(a) into v_old
  from public.appointments a where a.id=v_ref.record_id;

  if v_status='confirmed' and coalesce(v_old->>'status','')='planned' and (v_old->>'appointment_at') is null then
    raise exception 'appointment_confirmation_requires_time';
  end if;

  update public.appointments
  set status=v_status,
      arrived_at=case when v_status='arrived' then coalesce(arrived_at,now()) else arrived_at end,
      no_show_at=case when v_status='no_show' then coalesce(no_show_at,now()) else no_show_at end,
      last_change_reason=coalesce(nullif(btrim(p_reason),''),last_change_reason),
      updated_at=now()
  where id=v_ref.record_id;

  if v_status='no_show' then
    update public.appointment_reminders
    set status='cancelled',updated_at=now()
    where appointment_id=v_ref.record_id
      and status in ('pending','failed')
      and rule_key like 'auto_pre_%';
  end if;

  select to_jsonb(a) into v_new
  from public.appointments a where a.id=v_ref.record_id;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    old_data,new_data,description
  ) values(
    v_ref.active_family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
    'appointment_status_'||v_status,'appointment',v_ref.record_id,
    v_old,v_new,
    coalesce(nullif(btrim(p_reason),''),
      case v_status when 'confirmed' then 'ยืนยันนัด'
                    when 'arrived' then 'ถึงสถานพยาบาลแล้ว'
                    else 'ไม่ได้ไปตามนัด' end)
  );

  if v_status='confirmed'
     and coalesce(v_old->>'status','') is distinct from 'confirmed' then
    v_notify:=private.phms_enqueue_appointment_confirmed_notifications(
      v_ref.record_id,v_ref.actor_user_id
    );
    perform private.phms_sync_auto_appointment_reminders(now());
  end if;

  return jsonb_build_object(
    'ok',true,
    'record_code',substr(v_ref.record_id::text,1,12),
    'status',v_status,
    'item',v_new,
    'notifications',v_notify
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_set_vn(p_line_user_id text, p_record_code text, p_vn text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_vn text:=nullif(btrim(coalesce(p_vn,'')),'');
  v_old jsonb;
  v_new jsonb;
begin
  select * into v_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',p_record_code,'update'
  )
  limit 1;

  select to_jsonb(a) into v_old
  from public.appointments a
  where a.id=v_ref.record_id;

  update public.appointments
  set hospital_vn=v_vn,
      last_change_reason='แก้ไข VN',
      updated_at=now()
  where id=v_ref.record_id;

  select to_jsonb(a) into v_new
  from public.appointments a
  where a.id=v_ref.record_id;

