$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_source_info(p_line_user_id text, p_record_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_ref record;
 v_row public.appointments%rowtype;
 v_previous public.appointments%rowtype;
 v_source uuid;
 v_source_kind text;
 v_original_decision text;
 v_can_manage_original boolean:=false;
 v_can_cancel_original boolean:=false;
 v_original_code text;
 v_early_visits jsonb:='[]'::jsonb;
begin
 select * into v_ref
 from private.phms_line_appointment_access(p_line_user_id,p_record_code)
 limit 1;
 if v_ref.record_id is null then raise exception 'appointment_not_accessible'; end if;
 select * into v_row from public.appointments where id=v_ref.record_id and deleted_at is null;
 if not found then raise exception 'appointment_not_found'; end if;
 v_source:=case when v_row.early_visit_of_appointment_id is not null
  then v_row.early_visit_of_appointment_id else case v_row.appointment_type
  when 'follow_up' then v_row.followup_of_appointment_id
  when 'referral' then v_row.referral_from_appointment_id
  when 'investigation' then v_row.investigation_of_appointment_id
  else null::uuid end end;
 v_source_kind:=case when v_row.early_visit_of_appointment_id is not null then 'early_visit'
  when v_row.appointment_type='referral' and v_row.referral_source_kind='external_referral'
  then 'external' when v_source is not null then 'prior' else 'unset' end;
 if v_source is not null and coalesce(v_ref.has_person_view,false) then
  select * into v_previous from public.appointments where id=v_source and person_id=v_row.person_id and deleted_at is null;
 end if;
 if v_row.early_visit_of_appointment_id is not null and v_previous.id is not null then
  v_original_code:=substr(v_previous.id::text,1,12);
  begin
   v_can_manage_original:=coalesce(
    (public.phms_line_appointment_action_capabilities(p_line_user_id,v_original_code)->>'can_manage_status')::boolean,
    false
   );
  exception when others then
   v_can_manage_original:=false;
  end;
  begin
   perform 1
   from private.phms_find_crud_record(
     p_line_user_id,'appointment',v_original_code,'delete'
   )
   limit 1;
   v_can_cancel_original:=found;
  exception when others then
   v_can_cancel_original:=false;
  end;
  select case a.event_type
    when 'appointment_early_visit_original_kept' then 'keep'
    when 'appointment_early_visit_original_cancelled' then 'cancel'
    else null
   end
  into v_original_decision
  from public.audit_logs a
  where a.resource='appointment'
    and a.record_id=v_row.id
    and a.event_type in (
      'appointment_early_visit_original_kept',
      'appointment_early_visit_original_cancelled'
    )
  order by a.created_at desc
  limit 1;
  if v_previous.status='cancelled' and v_original_decision is null then
    v_original_decision:='cancel';
  end if;
 end if;
 if coalesce(v_ref.has_person_view,false) then
  select coalesce(jsonb_agg(jsonb_build_object(
    'record_code',substr(a.id::text,1,12),
    'title',a.title,
    'planned_visit_date',a.planned_visit_date,
    'status',a.status
  ) order by a.planned_visit_date desc,a.created_at desc),'[]'::jsonb)
  into v_early_visits
  from public.appointments a
  where a.early_visit_of_appointment_id=v_row.id
    and a.person_id=v_row.person_id
    and a.family_id=v_row.family_id
    and a.deleted_at is null;
 end if;
 return jsonb_build_object(
  'ok',true,
  'record_code',substr(v_row.id::text,1,12),
  'appointment_type',v_row.appointment_type,
  'has_source',v_source is not null or v_source_kind='external',
  'source_kind',v_source_kind,
  'source_code',case when v_previous.id is not null then substr(v_previous.id::text,1,12) else null end,
  'source_title',case when v_previous.id is not null then v_previous.title else null end,
  'source_date',case when v_previous.id is not null then v_previous.appointment_at else null end,
  'original_appointment_kept',v_row.early_visit_of_appointment_id is not null,
  'original_status',case when v_row.early_visit_of_appointment_id is not null and v_previous.id is not null then v_previous.status end,
  'original_decision',v_original_decision,
  'can_manage_original',v_can_manage_original,
  'can_cancel_original',v_can_cancel_original,
  'reference_note',v_row.reference_note,
  'early_visits',v_early_visits
 );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_timeline(p_line_user_id text, p_record_code text, p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_appt public.appointments%rowtype;
  v_patient_user uuid;
  v_creator text;
  v_created_source text:='manual';
  v_confirmed jsonb;
  v_ack jsonb;
  v_events jsonb:='[]'::jsonb;
  v_previous jsonb;
  v_next jsonb:='[]'::jsonb;
  v_limit int:=greatest(1,least(coalesce(p_limit,20),30));
begin
  select * into v_ref
  from private.phms_find_crud_record(p_line_user_id,'appointment',p_record_code,'view')
  limit 1;

  select * into v_appt from public.appointments where id=v_ref.record_id;
  select p.linked_user_id into v_patient_user from public.persons p where p.id=v_appt.person_id;

  v_creator:=case when v_appt.created_by is null then 'ระบบ'
    else private.family_user_label_for_viewer(
      v_ref.actor_user_id,v_ref.active_family_id,v_appt.created_by
    ) end;

  if exists(
    select 1 from public.record_provenance rp
    where rp.resource_type='appointments' and rp.record_id=v_appt.id
  ) then
    v_created_source:='confirmed_input';
  end if;

  select jsonb_strip_nulls(jsonb_build_object(
    'at',al.created_at,
    'actor_name',case when al.actor_user_id is null then 'ระบบ'
      else private.family_user_label_for_viewer(
        v_ref.actor_user_id,v_ref.active_family_id,al.actor_user_id
      ) end,
    'description',al.description
  ))
  into v_confirmed
  from public.audit_logs al
  where al.record_id=v_appt.id
    and al.resource='appointment'
    and al.event_type='appointment_status_confirmed'
  order by al.created_at desc
  limit 1;

  select jsonb_strip_nulls(jsonb_build_object(
    'status',ak.status,
    'requested_at',ak.requested_at,
    'responded_at',ak.responded_at,
    'display_name',private.family_user_label_for_viewer(
      v_ref.actor_user_id,v_ref.active_family_id,ak.user_id
    ),
    'note',ak.note
  ))
  into v_ack
  from public.appointment_acknowledgements ak
  where ak.appointment_id=v_appt.id
    and v_patient_user is not null
    and ak.user_id=v_patient_user
  order by ak.requested_at desc
  limit 1;

  select coalesce(jsonb_agg(x.ev order by x.at desc),'[]'::jsonb)
  into v_events
  from (
    select al.created_at at,
      jsonb_strip_nulls(jsonb_build_object(
        'at',al.created_at,
        'event_type',al.event_type,
        'actor_name',case when al.actor_user_id is null then 'ระบบ'
          else private.family_user_label_for_viewer(
            v_ref.actor_user_id,v_ref.active_family_id,al.actor_user_id
          ) end,
        'description',al.description,
        'old_data',al.old_data,
        'new_data',al.new_data
      )) ev
    from public.audit_logs al
    where al.record_id=v_appt.id
      and al.resource='appointment'
      and al.event_type not in ('insert','update')
    order by al.created_at desc
    limit v_limit
  ) x;

  if v_appt.followup_of_appointment_id is not null
     or v_appt.rescheduled_from_appointment_id is not null then
    select jsonb_strip_nulls(jsonb_build_object(
      'title',p.title,'appointment_at',p.appointment_at,'status',p.status,
      'code',substr(p.id::text,1,12),
      'relation',case when v_appt.followup_of_appointment_id=p.id then 'follow_up' else 'rescheduled' end
    ))
    into v_previous
    from public.appointments p
    where p.id=coalesce(v_appt.followup_of_appointment_id,v_appt.rescheduled_from_appointment_id)
      and p.deleted_at is null;
  end if;

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'title',n.title,'appointment_at',n.appointment_at,'status',n.status,
    'code',substr(n.id::text,1,12),
    'relation',case when n.followup_of_appointment_id=v_appt.id then 'follow_up' else 'rescheduled' end
  )) order by n.appointment_at asc),'[]'::jsonb)
  into v_next
  from public.appointments n
  where n.deleted_at is null
    and (n.followup_of_appointment_id=v_appt.id or n.rescheduled_from_appointment_id=v_appt.id);

  return jsonb_build_object(
    'ok',true,
    'person_name',v_ref.target_person_name,
    'appointment',jsonb_strip_nulls(jsonb_build_object(
      'title',v_appt.title,'appointment_at',v_appt.appointment_at,
      'status',v_appt.status,'hospital_name',v_appt.hospital_name,
      'department',v_appt.department
    )),
    'created',jsonb_build_object(
      'at',v_appt.created_at,'actor_name',v_creator,'source',v_created_source
    ),
    'confirmed',coalesce(v_confirmed,'null'::jsonb),
    'patient_acknowledgement',coalesce(v_ack,jsonb_build_object('status','not_requested')),
    'events',v_events,
    'previous_appointment',coalesce(v_previous,'null'::jsonb),
    'next_appointments',v_next
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_unlink_document(p_line_user_id text, p_record_code text, p_link_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_link public.appointment_document_links%rowtype;
begin
  select * into v_ref
  from private.phms_find_crud_record(p_line_user_id,'appointment',p_record_code,'update')
  limit 1;
  if v_ref.active_family_person_id is null or not private.user_can_access_family_person(v_ref.actor_user_id,v_ref.active_family_person_id,'documents','update') then raise exception 'document_permission_denied';end if;


  select * into v_link
  from public.appointment_document_links adl
  where adl.id=p_link_id
    and adl.appointment_id=v_ref.record_id
  limit 1;

  if not found then raise exception 'appointment_document_link_not_found'; end if;
  if v_link.link_kind in ('receipt','payment_slip','payment_qr','payment_other') and not private.user_can_access_family_person(v_ref.actor_user_id,v_ref.active_family_person_id,'expenses','update') then raise exception 'expense_permission_denied';end if;

  perform private.phms_put_recycle_entry(
    v_ref.active_family_id,v_ref.active_family_person_id,v_ref.target_person_id,
    'appointment_document_link',v_link.id,'unlink',to_jsonb(v_link),
    'Removed document link from appointment',v_ref.actor_user_id
  );

  delete from public.appointment_document_links
  where id=v_link.id and appointment_id=v_ref.record_id;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    old_data,description,created_at
  ) values(
    v_ref.active_family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
    'appointment_document_unlinked','appointment',v_ref.record_id,
    jsonb_build_object(
      'appointment_document_link_id',v_link.id,
      'medical_document_id',v_link.medical_document_id,
      'storage_asset_id',v_link.storage_asset_id,
      'link_kind',v_link.link_kind
    ),
    'Removed document link from appointment without deleting the source asset',
    now()
  );

  return jsonb_build_object(
    'ok',true,
    'appointment_code',substr(v_ref.record_id::text,1,12),
    'link_id',v_link.id,
    'source_asset_preserved',true
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_unlink_pair(p_line_user_id text, p_record_code_a text, p_record_code_b text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_a_ref record;
  v_b_ref record;
  v_a public.appointments%rowtype;
  v_b public.appointments%rowtype;
  v_next public.appointments%rowtype;
  v_prev public.appointments%rowtype;
  v_edge_id uuid;
  v_replacement uuid;
  v_old jsonb;
  v_still_connected boolean:=false;
  v_group_size integer:=1;
begin
  select * into v_a_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',p_record_code_a,'update'
  ) limit 1;

  select * into v_b_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',p_record_code_b,'update'
  ) limit 1;

  select * into v_a
  from public.appointments
  where id=v_a_ref.record_id and deleted_at is null;

  select * into v_b
  from public.appointments
  where id=v_b_ref.record_id and deleted_at is null;

  if v_a.person_id is distinct from v_b.person_id then
    raise exception 'appointment_link_person_mismatch';
  end if;

  select l.id into v_edge_id
  from private.appointment_links l
  where l.deleted_at is null
    and (
      (l.appointment_id_a=v_a.id and l.appointment_id_b=v_b.id)
      or
      (l.appointment_id_a=v_b.id and l.appointment_id_b=v_a.id)
    )
  limit 1;

  if v_edge_id is null then
    if exists(
      select 1
      from private.phms_appointment_component(v_a.id,200) c
      where c.appointment_id=v_b.id
    ) then
      raise exception 'appointment_pair_linked_indirectly';
    end if;
    raise exception 'appointment_pair_not_directly_linked';
  end if;

  update private.appointment_links
  set deleted_at=now()
  where id=v_edge_id;

  if v_a.followup_of_appointment_id=v_b.id then
    v_next:=v_a; v_prev:=v_b;
  elsif v_b.followup_of_appointment_id=v_a.id then
    v_next:=v_b; v_prev:=v_a;
  elsif v_a.appointment_at<v_b.appointment_at then
    v_prev:=v_a; v_next:=v_b;
  else
    v_prev:=v_b; v_next:=v_a;
  end if;

  v_old:=to_jsonb(v_next);

  if v_next.followup_of_appointment_id=v_prev.id then
    select n.id into v_replacement
    from public.appointments n
    join private.appointment_links l
      on l.deleted_at is null
     and (
       (l.appointment_id_a=v_next.id and l.appointment_id_b=n.id)
       or
       (l.appointment_id_b=v_next.id and l.appointment_id_a=n.id)
     )
    where n.deleted_at is null
      and n.person_id=v_next.person_id
      and n.appointment_at is not null
      and v_next.appointment_at is not null
      and n.appointment_at<v_next.appointment_at
    order by n.appointment_at desc,n.created_at desc,n.id
    limit 1;

    update public.appointments
    set followup_of_appointment_id=v_replacement,
        updated_at=now()
    where id=v_next.id;
  end if;

  select exists(
    select 1
    from private.phms_appointment_component(v_a.id,200) c
    where c.appointment_id=v_b.id
  ) into v_still_connected;

  select count(*)::int into v_group_size
  from private.phms_appointment_component(v_a.id,200);

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    old_data,new_data,description
  )
  values(
    v_next.family_id,v_a_ref.actor_user_id,v_next.family_person_id,
    'appointment_link_edge_removed','appointment',v_next.id,
    v_old,(select to_jsonb(a) from public.appointments a where a.id=v_next.id),
    case when v_still_connected
      then 'ยกเลิกเส้นเชื่อมคู่นี้ แต่ยังเชื่อมกันผ่านนัดอื่นในกลุ่มเดียวกัน'
      else 'ยกเลิกการเชื่อมนัดคู่นี้'
    end
  );

  return jsonb_build_object(
    'ok',true,
    'previous_record_code',substr(v_prev.id::text,1,12),
    'next_record_code',substr(v_next.id::text,1,12),
    'still_connected',v_still_connected,
    'group_size_from_first',v_group_size
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_update_assignee_role(p_line_user_id text, p_record_code text, p_assignee_code text, p_role text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_code text:=lower(btrim(coalesce(p_assignee_code,'')));
  v_role text:=lower(btrim(coalesce(p_role,'')));
  v_count int;
  v_id uuid;
  v_ass public.appointment_assignees%rowtype;
  v_result jsonb;
begin
  if v_role not in ('booker','caregiver','driver','companion','responsible','other') then
    raise exception 'invalid_assignment_role';
  end if;

  select * into v_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',p_record_code,'update'
  ) limit 1;

  select count(*),min(id) into v_count,v_id
  from public.appointment_assignees
  where appointment_id=v_ref.record_id
    and status<>'removed'
    and lower(id::text) like v_code||'%';

  if v_count=0 then raise exception 'appointment_assignee_not_found'; end if;
  if v_count>1 then raise exception 'appointment_assignee_code_ambiguous'; end if;

  select * into v_ass from public.appointment_assignees where id=v_id;

  if v_ass.assignment_role=v_role then
    return jsonb_build_object(
      'ok',true,'unchanged',true,
      'record_code',substr(v_ref.record_id::text,1,12),
      'assignee_code',substr(v_id::text,1,12),
      'role',v_role
    );
  end if;

  perform public.phms_line_appointment_remove_assignee(
    p_line_user_id,p_record_code,p_assignee_code
  );

  v_result:=public.phms_line_appointment_set_assignee(
    p_line_user_id,p_record_code,substr(v_ass.user_id::text,1,12),v_role,v_ass.note
  );

  return v_result||jsonb_build_object('role_changed',true);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_update_document_link(p_line_user_id text, p_record_code text, p_link_id uuid, p_title text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_link public.appointment_document_links%rowtype;
  v_title text:=nullif(btrim(coalesce(p_title,'')),'');
  v_note text:=nullif(btrim(coalesce(p_note,'')),'');
begin
  select * into v_ref
  from private.phms_find_crud_record(p_line_user_id,'appointment',p_record_code,'update')
  limit 1;
  if v_ref.active_family_person_id is null or not private.user_can_access_family_person(v_ref.actor_user_id,v_ref.active_family_person_id,'documents','update') then raise exception 'document_permission_denied';end if;


  select * into v_link
  from public.appointment_document_links
  where id=p_link_id and appointment_id=v_ref.record_id
  limit 1;
  if not found then raise exception 'appointment_document_link_not_found'; end if;
  if v_link.link_kind in ('receipt','payment_slip','payment_qr','payment_other') and not private.user_can_access_family_person(v_ref.actor_user_id,v_ref.active_family_person_id,'expenses','update') then raise exception 'expense_permission_denied';end if;

  update public.appointment_document_links
  set note=v_note
  where id=v_link.id;

  if v_title is not null and v_link.storage_asset_id is not null then
    update public.phms_storage_assets
    set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
      'display_title',v_title,
      'labeled_by',v_ref.actor_user_id,
      'labeled_at',now()
    ),
    updated_at=now()
    where id=v_link.storage_asset_id;
  end if;

  if v_title is not null and v_link.medical_document_id is not null then
    update public.medical_documents
    set title=v_title,updated_at=now()
    where id=v_link.medical_document_id;
  end if;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    new_data,description,created_at
  ) values(
    v_ref.active_family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
    'appointment_document_updated','appointment',v_ref.record_id,
    jsonb_strip_nulls(jsonb_build_object(
      'link_id',v_link.id,'title',v_title,'note',v_note
    )),
    'แก้ชื่อหรือหมายเหตุเอกสารของนัด',now()
  );

  return jsonb_build_object('ok',true,'appointment_code',substr(v_ref.record_id::text,1,12),'link_id',v_link.id);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_update_v3(p_line_user_id text, p_record_code text, p_patch jsonb, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_patch jsonb:=coalesce(p_patch,'{}'::jsonb)-'hospital_vn';
  v_result jsonb;
  v_vn_result jsonb;
  v_ref record;
begin
  if p_patch is null or jsonb_typeof(p_patch)<>'object' then
    raise exception 'appointment_patch_required';
  end if;

  if p_patch ? 'hospital_vn' then
    v_vn_result:=public.phms_line_appointment_set_vn(
      p_line_user_id,p_record_code,p_patch->>'hospital_vn'
    );
  end if;

  if v_patch<>'{}'::jsonb then
    v_result:=public.phms_line_appointment_update_v2(
      p_line_user_id,p_record_code,v_patch,p_reason
    );
  else
    select * into v_ref
    from private.phms_find_crud_record(
      p_line_user_id,'appointment',p_record_code,'view'
    )
    limit 1;
    v_result:=jsonb_build_object(
      'ok',true,
      'record_id',v_ref.record_id,
      'record_code',substr(v_ref.record_id::text,1,12),
      'schedule_changed',false,
      'updated',coalesce((v_vn_result->>'updated')::boolean,false)
    );
  end if;

  if v_vn_result is not null then
    v_result:=v_result||jsonb_build_object(
      'hospital_vn',v_vn_result->'hospital_vn',
      'vn_updated',coalesce((v_vn_result->>'updated')::boolean,false)
    );
  end if;

  return v_result;
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_update_walkin_fields(p_line_user_id text, p_record_code text, p_patch jsonb, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_old jsonb;
  v_new jsonb;
  v_row public.appointments%rowtype;
  v_original public.appointments%rowtype;
  v_date date;
  v_original_date date;
  v_time text;
  v_at timestamptz;
  v_reason text:=coalesce(nullif(btrim(p_reason),''),'แก้รายละเอียด Walk-in');
begin
  if p_patch is null or jsonb_typeof(p_patch)<>'object' then
    raise exception 'walkin_patch_required';
  end if;
  if (p_patch - array['planned_visit_date','visit_time','walk_in_reason','walk_in_note']) <> '{}'::jsonb then
    raise exception 'walkin_patch_field_not_allowed';
  end if;

  select * into v_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',p_record_code,'update'
  ) limit 1;

  select * into v_row
  from public.appointments
  where id=v_ref.record_id and deleted_at is null
  for update;

  if not found then raise exception 'walkin_appointment_not_found'; end if;
  if coalesce(v_row.visit_mode,'')<>'walk_in' then raise exception 'appointment_not_walkin'; end if;

  select to_jsonb(v_row) into v_old;

  v_date:=coalesce(v_row.planned_visit_date,(v_row.appointment_at at time zone 'Asia/Bangkok')::date);

  if p_patch ? 'planned_visit_date' then
    begin
      v_date:=nullif(btrim(p_patch->>'planned_visit_date'),'')::date;
    exception when others then
      raise exception 'invalid_walkin_date';
    end;
    if v_date is null then raise exception 'walkin_date_required'; end if;
  end if;

  if v_row.early_visit_of_appointment_id is not null then
    select * into v_original
    from public.appointments
    where id=v_row.early_visit_of_appointment_id
      and deleted_at is null
      and person_id=v_row.person_id;
    if not found then raise exception 'early_visit_original_missing'; end if;
    v_original_date:=coalesce(
      (v_original.appointment_at at time zone 'Asia/Bangkok')::date,
      v_original.planned_visit_date
    );
    if v_original_date is not null and v_date>=v_original_date then
      raise exception 'early_visit_must_precede_original_date';
    end if;
  end if;

  if p_patch ? 'visit_time' then
    v_time:=lower(btrim(coalesce(p_patch->>'visit_time','')));
    if v_time in ('','unknown','ไม่ทราบ','ยังไม่ทราบ','-','—') then
      v_at:=null;
    else
      if v_time !~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9]$' then
        raise exception 'invalid_walkin_time';
      end if;
      if v_date is null then raise exception 'walkin_date_required_before_time'; end if;
      v_at:=((v_date::text||' '||v_time)::timestamp at time zone 'Asia/Bangkok');
    end if;
  elsif p_patch ? 'planned_visit_date' and coalesce(v_row.visit_time_known,false)=true and v_row.appointment_at is not null then
    v_time:=to_char(v_row.appointment_at at time zone 'Asia/Bangkok','HH24:MI');
    v_at:=((v_date::text||' '||v_time)::timestamp at time zone 'Asia/Bangkok');
  else
    v_at:=v_row.appointment_at;
  end if;

  if p_patch ? 'walk_in_reason' then
    v_time:=nullif(lower(btrim(coalesce(p_patch->>'walk_in_reason',''))),'');
    if v_time is not null and v_time not in ('queue_full','hospital_advised','no_booking','urgent','other') then
      raise exception 'invalid_walkin_reason';
    end if;
  end if;

  update public.appointments a
  set planned_visit_date=case when p_patch?'planned_visit_date' then v_date else a.planned_visit_date end,
      appointment_at=case
        when p_patch?'visit_time' then v_at
        when p_patch?'planned_visit_date' and coalesce(a.visit_time_known,false)=true then v_at
        else a.appointment_at end,
      visit_time_known=case
        when p_patch?'visit_time' then (v_at is not null)
        else a.visit_time_known end,
      walk_in_reason=case
        when p_patch?'walk_in_reason' then nullif(lower(btrim(p_patch->>'walk_in_reason')),'')
        else a.walk_in_reason end,
      walk_in_note=case
        when p_patch?'walk_in_note' then nullif(btrim(p_patch->>'walk_in_note'),'')
        else a.walk_in_note end,
      last_change_reason=v_reason,
      updated_at=now()
  where a.id=v_ref.record_id;

  select to_jsonb(a) into v_new from public.appointments a where a.id=v_ref.record_id;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    old_data,new_data,description
  ) values(
    v_ref.active_family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
    'appointment_walkin_update','appointment',v_ref.record_id,
    v_old,v_new,v_reason
  );

  perform private.phms_sync_auto_appointment_reminders(now());

  return jsonb_build_object(
    'ok',true,
    'record_id',v_ref.record_id,
    'record_code',substr(v_ref.record_id::text,1,12),
    'item',v_new
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_appointment_view_request_workspace(p_line_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_ctx private.line_identity_contexts%rowtype;
  v_fp public.family_persons%rowtype;
  v_person public.persons%rowtype;
  v_can_view boolean:=false;
  v_req public.permission_requests%rowtype;
  v_code text;
  v_reviewer_name text;
  v_can_remind boolean:=false;
  v_next_reminder timestamptz;
  v_reviewer_count integer:=0;
begin
  select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
  perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
  select * into v_ctx
  from private.line_identity_contexts
  where line_identity_id=v_line.line_identity_id;

  if v_ctx.active_scope<>'family'
     or v_ctx.active_family_id is null
     or v_ctx.active_family_person_id is null then
    raise exception 'family_person_context_required';
  end if;

  select * into v_fp
  from public.family_persons
  where id=v_ctx.active_family_person_id
    and family_id=v_ctx.active_family_id
    and coalesce(status,'active')='active';
  if not found then raise exception 'family_person_not_found'; end if;

  if not exists(
    select 1 from public.family_memberships fm
    where fm.family_id=v_fp.family_id
      and fm.user_id=v_line.user_id
      and fm.status='active'
  ) then
    raise exception 'family_context_not_accessible';
  end if;

  if not private.family_person_is_visible_to_user(v_line.user_id,v_fp.id) then
    raise exception 'family_person_not_visible';
  end if;

  select * into v_person
  from public.persons p
  where p.id=v_fp.person_id
    and coalesce(p.status,'active')='active';
  if not found then raise exception 'person_not_found'; end if;

  v_can_view:=private.user_can_access_family_person(
    v_line.user_id,v_fp.id,'appointments','view'
  );

  select pr.* into v_req
  from public.permission_requests pr
  where pr.family_id=v_fp.family_id
    and pr.family_person_id=v_fp.id
    and pr.requester_user_id=v_line.user_id
    and pr.request_type='permission'
    and pr.resource='appointments'
    and pr.requested_action='view'
  order by pr.created_at desc,pr.id desc
  limit 1;

  if found then
    v_code:=substr(
      encode(digest(v_req.id::text||':'||v_line.line_identity_id::text,'sha256'),'hex'),
      1,12
    );
    if v_req.reviewed_by is not null then
      v_reviewer_name:=private.family_user_label_for_viewer(
        v_line.user_id,v_fp.family_id,v_req.reviewed_by
      );
    end if;
    if v_req.status='pending' then
      v_next_reminder:=coalesce(v_req.last_reminded_at,v_req.created_at)+interval '3 days';
      v_can_remind:=now()>=v_next_reminder;
    end if;
  end if;

  select count(distinct fm.user_id)::int
  into v_reviewer_count
  from public.family_memberships fm
  where fm.family_id=v_fp.family_id
    and fm.status='active'
    and fm.user_id<>v_line.user_id
    and private.can_review_person_access_request(fm.user_id,v_fp.id);

  return jsonb_build_object(
    'ok',true,
    'person_name',private.family_person_label_for_viewer(v_line.user_id,v_fp.id),
    'can_view',v_can_view,
    'request_status',
      case
        when v_can_view then 'allowed'
        when v_req.id is null then 'none'
        when v_req.status='approved' then 'revoked'
        else coalesce(v_req.status,'none')
      end,
    'request_code',v_code,
    'requested_at',v_req.created_at,
    'reviewed_at',v_req.reviewed_at,
    'reviewed_by_name',v_reviewer_name,
    'review_note',v_req.review_note,
    'reminder_count',coalesce(v_req.reminder_count,0),
    'last_reminded_at',v_req.last_reminded_at,
    'can_remind',v_can_remind,
    'next_reminder_at',v_next_reminder,
    'reviewer_count',coalesce(v_reviewer_count,0)
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_assign_health_task(p_line_user_id text, p_person_code text, p_member_code text, p_resource text, p_task_type text, p_title text, p_instructions text DEFAULT NULL::text, p_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_record_type text DEFAULT NULL::text, p_record_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_member record;v_person record;v_resource text:=case lower(btrim(coalesce(p_resource,'')))
  when 'profile' then 'persons' when 'health' then 'health_data'
  when 'documents' then 'health_data' when 'medication' then 'medications'
  else lower(btrim(coalesce(p_resource,''))) end;
 v_id uuid;v_code text;
begin
 if v_resource not in ('persons','medications','appointments','health_data','emergency') then
   raise exception 'invalid_task_resource';
 end if;
 if nullif(btrim(coalesce(p_title,'')),'') is null then raise exception 'task_title_required'; end if;

 select * into v_member from private.resolve_line_family_member(p_line_user_id,p_member_code);
 select * into v_person from private.resolve_line_family_person_code(p_line_user_id,p_person_code);
 if v_member.family_id<>v_person.family_id then raise exception 'family_scope_mismatch'; end if;
 perform set_config('request.jwt.claim.sub',v_member.actor_user_id::text,true);

 if not (
   private.phms_can_manage_medical_grants(v_member.actor_user_id,v_person.family_person_id)
   or private.user_can_access_family_person(v_member.actor_user_id,v_person.family_person_id,v_resource,'update')
 ) then raise exception 'task_assignment_outside_health_scope'; end if;

 if not exists(select 1 from public.family_memberships fm
               where fm.family_id=v_member.family_id and fm.user_id=v_member.target_user_id and fm.status='active')
 then raise exception 'task_assignee_not_active_family_member'; end if;

 insert into public.health_care_tasks(
  family_id,family_person_id,assigned_by_user_id,assigned_to_user_id,
  resource,task_type,title,instructions,record_type,record_id,status,
  requires_ack,due_at,expires_at,created_at,updated_at
 ) values(
  v_member.family_id,v_person.family_person_id,v_member.actor_user_id,v_member.target_user_id,
  v_resource,coalesce(nullif(lower(btrim(p_task_type)),''),'other'),btrim(p_title),
  nullif(btrim(coalesce(p_instructions,'')),''),
  nullif(btrim(coalesce(p_record_type,'')),''),p_record_id,'pending',
  true,p_due_at,p_expires_at,now(),now()
 ) returning id into v_id;

 v_code:=substr(replace(v_id::text,'-',''),1,12);

 insert into public.notifications(
  family_id,recipient_user_id,event_type,title,message,channel,priority,status,
  family_person_id,payload,dedupe_key
 ) values(
  v_member.family_id,v_member.target_user_id,'health_task_assigned',
  '📋 มีงานที่มอบหมาย',
  btrim(p_title)||case when p_due_at is not null then ' • กรุณาตรวจวันกำหนดในอิ่มอุ่น' else '' end,
  'line','normal','pending',v_person.family_person_id,
  jsonb_build_object('task_code',v_code,'resource',v_resource),
  'health_task_assigned_'||v_id::text
 );

 insert into public.audit_logs(
  family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,new_data,description
 ) values(
  v_member.family_id,v_member.actor_user_id,v_member.target_user_id,v_person.family_person_id,
  'health_task_assigned',v_resource,
  jsonb_build_object('task_id',v_id,'task_type',p_task_type,'due_at',p_due_at,'expires_at',p_expires_at),
  'Assigned one-off health task'
 );

 return jsonb_build_object('ok',true,'task_code',v_code,'status','pending',
   'resource',v_resource,'title',btrim(p_title));
end;
$function$

