CREATE OR REPLACE FUNCTION public.phms_line_bug_report_image_capture(p_line_user_id text, p_message_id text, p_storage_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth'
AS $function$
declare v_line record; v_ctx private.line_identity_contexts%rowtype; v_session public.phms_bug_report_sessions%rowtype; v_report uuid;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select * into v_session from public.phms_bug_report_sessions where line_user_id=p_line_user_id and expires_at>now() for update;
 if not found then return jsonb_build_object('captured',false); end if;
 if p_message_id !~ '^[0-9]{1,40}$' or p_storage_path not like 'line-bug/'||p_line_user_id||'/%' then raise exception 'invalid_image_reference';end if;
 select * into v_ctx from private.line_identity_contexts where line_identity_id=v_line.line_identity_id;
 v_report:=v_session.report_id;
 if v_report is null then
  insert into public.phms_bug_reports(line_user_id,reporter_user_id,family_id,person_id,line_image_message_id,image_storage_path,source_screen)
   values(p_line_user_id,v_line.user_id,v_ctx.active_family_id,(select person_id from public.family_persons where id=v_ctx.active_family_person_id),p_message_id,p_storage_path,'line_image')
  returning id into v_report;
 else
  update public.phms_bug_reports set line_image_message_id=p_message_id,image_storage_path=p_storage_path,updated_at=now()
  where id=v_report and line_user_id=p_line_user_id;
 end if;
 delete from public.phms_bug_report_sessions where line_user_id=p_line_user_id;
 return jsonb_build_object('captured',true,'report_code',substr(v_report::text,1,8));
end $function$

CREATE OR REPLACE FUNCTION public.phms_line_bug_report_start(p_line_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth'
AS $function$
declare v_line record;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 insert into public.phms_bug_report_sessions(line_user_id,report_id,expires_at,created_at)
 values(p_line_user_id,null,now()+interval '15 minutes',now())
 on conflict(line_user_id) do update set report_id=null,expires_at=excluded.expires_at,created_at=now();
 return jsonb_build_object('ok',true,'expires_in_minutes',15);
end $function$

CREATE OR REPLACE FUNCTION public.phms_line_create_early_visit(p_line_user_id text, p_original_record_code text, p_visit_date date, p_reason text DEFAULT 'doctor_advised'::text, p_same_hospital boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
DECLARE
  v_access record;
  v_original public.appointments%rowtype;
  v_new public.appointments%rowtype;
  v_original_day date;
  v_today date:=(now() at time zone 'Asia/Bangkok')::date;
  v_reason text:=coalesce(p_reason,'doctor_advised');
  v_same boolean:=coalesce(p_same_hospital,true);
  v_link_a uuid;
  v_link_b uuid;
  v_fp uuid;
  v_existing uuid;
  v_tasks_copied integer:=0;
  v_documents_linked integer:=0;
BEGIN
  IF p_visit_date IS NULL OR v_reason NOT IN ('doctor_advised','symptoms') THEN
    RAISE EXCEPTION 'early_visit_invalid_options';
  END IF;
  SELECT * INTO v_access
    FROM private.phms_line_appointment_access(p_line_user_id,p_original_record_code)
    LIMIT 1;
  IF v_access.record_id IS NULL THEN
    RAISE EXCEPTION 'early_visit_original_not_accessible';
  END IF;
  v_fp:=v_access.active_family_person_id;
  IF v_fp IS NULL
    OR NOT private.user_can_access_family_person(
      v_access.actor_user_id,v_fp,'appointments','create'
    ) THEN
    RAISE EXCEPTION 'early_visit_create_permission_denied';
  END IF;
  SELECT * INTO v_original
  FROM public.appointments a
  WHERE a.id=v_access.record_id AND a.deleted_at IS NULL
  FOR UPDATE;
  IF v_original.id IS NULL THEN RAISE EXCEPTION 'early_visit_original_not_found'; END IF;
  IF v_original.status NOT IN ('scheduled','confirmed','arrived') THEN
    RAISE EXCEPTION 'early_visit_original_not_active';
  END IF;
  v_original_day:=coalesce(
    (v_original.appointment_at AT TIME ZONE 'Asia/Bangkok')::date,
    v_original.planned_visit_date
  );
  IF v_original_day IS NULL OR p_visit_date>=v_original_day THEN
    RAISE EXCEPTION 'early_visit_must_precede_original_date';
  END IF;
  IF p_visit_date<v_today-365 THEN
    RAISE EXCEPTION 'early_visit_date_too_old';
  END IF;

  -- Idempotent for repeated taps only; do not prohibit truly separate clinical visits.
  SELECT id INTO v_existing
  FROM public.appointments
  WHERE early_visit_of_appointment_id=v_original.id
    AND planned_visit_date=p_visit_date
    AND visit_mode='walk_in'
    AND walk_in_reason=CASE WHEN v_reason='symptoms' THEN 'urgent' ELSE 'hospital_advised' END
    AND coalesce(hospital_name,'')=CASE WHEN v_same THEN coalesce(v_original.hospital_name,'') ELSE '' END
    AND created_by=v_access.actor_user_id
    AND deleted_at IS NULL
    AND created_at>now()-interval '2 minutes'
  ORDER BY created_at DESC LIMIT 1;
  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object('ok',true,'created',false,'already_created',true,
      'record_code',substr(v_existing::text,1,12),
      'original_record_code',substr(v_original.id::text,1,12),
      'kept_original',true,
      'planned_visit_date',p_visit_date,
      'same_hospital',v_same);
  END IF;

  INSERT INTO public.appointments(
    family_id,person_id,family_person_id,
    title,appointment_type,visit_mode,walk_in_reason,walk_in_note,
    planned_visit_date,visit_time_known,appointment_at,status,
    hospital_name,organization_id,service_unit_id,clinician_id,hospital_hn,hospital_vn,care_topic,walk_in_doctor_status,
    department,doctor_name,location_detail,coverage_type,contact_phone,contact_email,
    preparation_notes,note,treatment_episode_id,
    followup_kind,followup_interval_months,reference_note,early_visit_of_appointment_id,created_by
  ) VALUES (
    v_original.family_id,v_original.person_id,v_fp,
    'พบหมอก่อนนัด: '||left(coalesce(nullif(v_original.title,''),'ตรวจอาการ'),100),
    coalesce(v_original.appointment_type,'follow_up'),'walk_in',
    CASE WHEN v_reason='symptoms' THEN 'urgent' ELSE 'hospital_advised' END,
    CASE WHEN v_reason='symptoms'
      THEN 'มีอาการผิดปกติ จึงไปพบแพทย์ก่อนวันนัดเดิม'
      ELSE 'แพทย์แจ้งว่าสามารถไปพบก่อนวันนัดเดิมได้'
    END,
    p_visit_date,false,NULL,'scheduled',
    CASE WHEN v_same THEN v_original.hospital_name ELSE NULL END,
    CASE WHEN v_same THEN v_original.organization_id ELSE NULL END,
    CASE WHEN v_same THEN v_original.service_unit_id ELSE NULL END,
    NULL, -- Doctor assignment cannot be presumed from the original booking
    CASE WHEN v_same THEN v_original.hospital_hn ELSE NULL END,
    CASE WHEN v_same THEN v_original.hospital_vn ELSE NULL END,
    v_original.care_topic,'pending',
    CASE WHEN v_same THEN v_original.department ELSE NULL END,
    NULL, -- must ask which physician actually handles the earlier visit
    CASE WHEN v_same THEN v_original.location_detail ELSE NULL END,
    CASE WHEN v_same THEN v_original.coverage_type ELSE NULL END,
    CASE WHEN v_same THEN v_original.contact_phone ELSE NULL END,
    CASE WHEN v_same THEN v_original.contact_email ELSE NULL END,
    CASE WHEN v_same THEN v_original.preparation_notes ELSE NULL END,
    CASE WHEN v_same THEN v_original.note ELSE NULL END,
    v_original.treatment_episode_id,
    CASE WHEN v_original.appointment_type='follow_up' THEN coalesce(v_original.followup_kind,'general') ELSE NULL END,
    CASE WHEN v_original.appointment_type='follow_up' THEN v_original.followup_interval_months ELSE NULL END,
    'ไปพบแพทย์ก่อนนัดเดิม โดยคงนัดเดิมไว้จนกว่าโรงพยาบาลจะยืนยัน',
    v_original.id,v_access.actor_user_id
  ) RETURNING * INTO v_new;

  v_link_a:=least(v_original.id,v_new.id);
  v_link_b:=greatest(v_original.id,v_new.id);
  INSERT INTO private.appointment_links(
    appointment_id_a,appointment_id_b,link_kind,source,created_by
  ) VALUES(v_link_a,v_link_b,'continuity','early_visit',v_access.actor_user_id)
  ON CONFLICT DO NOTHING;


  -- The new encounter is independent: never copy arrival, completion or post-visit data.
  -- For the same hospital, automatically duplicate reusable pre-visit information.
  IF v_same THEN
    INSERT INTO public.appointment_tasks(
      appointment_id,task_type,title,instruction,due_at,status,completed_at,completed_by,
      source_document_id,related_health_measurement_id,note,created_by,source_key,source_document_link_id
    )
    SELECT v_new.id,t.task_type,t.title,t.instruction,NULL,'pending',NULL,NULL,
      t.source_document_id,NULL,t.note,v_access.actor_user_id,
      'early_visit_copy:'||t.id::text,NULL
    FROM public.appointment_tasks t
    WHERE t.appointment_id=v_original.id AND t.status<>'cancelled'
      AND NOT EXISTS(
        SELECT 1 FROM public.appointment_tasks z
        WHERE z.appointment_id=v_new.id
          AND (z.source_key='early_visit_copy:'||t.id::text
               OR (btrim(z.title)=btrim(t.title) AND z.task_type IS NOT DISTINCT FROM t.task_type))
      );
    GET DIAGNOSTICS v_tasks_copied=ROW_COUNT;

    INSERT INTO public.appointment_document_links(
      appointment_id,medical_document_id,storage_asset_id,link_kind,note,
      created_by,usage_relation,origin_appointment_id
    )
    SELECT v_new.id,l.medical_document_id,l.storage_asset_id,'preparation',
      CASE WHEN l.link_kind='source'
        THEN concat_ws(' • ',NULLIF(btrim(l.note),''),'เอกสารจากนัดเดิม (ใช้อ้างอิง ไม่ใช่ใบนัดใหม่)')
        ELSE l.note END,
      v_access.actor_user_id,'carry_forward',coalesce(l.origin_appointment_id,v_original.id)
    FROM public.appointment_document_links l
    WHERE l.appointment_id=v_original.id AND l.link_kind IN ('preparation','source')
      AND (l.storage_asset_id IS NOT NULL OR l.medical_document_id IS NOT NULL)
      AND NOT EXISTS(
        SELECT 1 FROM public.appointment_document_links z
        WHERE z.appointment_id=v_new.id
          AND coalesce(z.storage_asset_id::text,z.medical_document_id::text)=coalesce(l.storage_asset_id::text,l.medical_document_id::text)
          AND z.link_kind='preparation'
      );
    GET DIAGNOSTICS v_documents_linked=ROW_COUNT;
  END IF;

  INSERT INTO public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    new_data,description
  ) VALUES(
    v_original.family_id,v_access.actor_user_id,v_fp,'appointment_early_visit_created',
    'appointment',v_new.id,
    jsonb_build_object('early_visit_of_appointment_id',v_original.id,
      'visit_date',p_visit_date,'same_hospital',v_same,'reason',v_reason),
    'บันทึกการไปพบแพทย์ก่อนวันนัด โดยคงนัดเดิมและข้อมูลหลังนัดแยกกัน'
  );
  RETURN jsonb_build_object(
    'ok',true,'created',true,'already_created',false,
    'record_code',substr(v_new.id::text,1,12),
    'original_record_code',substr(v_original.id::text,1,12),
    'original_appointment_at',v_original.appointment_at,
    'planned_visit_date',v_new.planned_visit_date,
    'same_hospital',v_same,'kept_original',true,
    'tasks_copied',v_tasks_copied,'documents_linked',v_documents_linked,
    'copied',jsonb_build_array('person','care_topic','clinical_episode')||
      CASE WHEN v_same THEN '["hospital","hospital_hn","hospital_vn"]'::jsonb ELSE '[]'::jsonb END
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.phms_line_create_early_visit_with_doctor(p_line_user_id text, p_original_record_code text, p_visit_date date, p_reason text DEFAULT 'doctor_advised'::text, p_same_hospital boolean DEFAULT true, p_doctor_mode text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
DECLARE
  v_access record;
  v_original public.appointments%rowtype;
  v_new public.appointments%rowtype;
  v_original_day date;
  v_today date:=(now() at time zone 'Asia/Bangkok')::date;
  v_reason text:=coalesce(p_reason,'doctor_advised');
  v_same boolean:=coalesce(p_same_hospital,true);
  v_link_a uuid;
  v_link_b uuid;
  v_fp uuid;
  v_existing uuid;
  v_tasks_copied integer:=0;
  v_documents_linked integer:=0;
BEGIN
  IF p_doctor_mode IS NULL OR p_doctor_mode NOT IN ('same','on_duty','other','unknown') THEN
    RAISE EXCEPTION 'early_visit_doctor_choice_required';
  END IF;
  IF p_visit_date IS NULL OR v_reason NOT IN ('doctor_advised','symptoms') THEN
    RAISE EXCEPTION 'early_visit_invalid_options';
  END IF;
  SELECT * INTO v_access
    FROM private.phms_line_appointment_access(p_line_user_id,p_original_record_code)
    LIMIT 1;
  IF v_access.record_id IS NULL THEN
    RAISE EXCEPTION 'early_visit_original_not_accessible';
  END IF;
  v_fp:=v_access.active_family_person_id;
  IF v_fp IS NULL
    OR NOT private.user_can_access_family_person(
      v_access.actor_user_id,v_fp,'appointments','create'
    ) THEN
    RAISE EXCEPTION 'early_visit_create_permission_denied';
  END IF;
  SELECT * INTO v_original
  FROM public.appointments a
  WHERE a.id=v_access.record_id AND a.deleted_at IS NULL
  FOR UPDATE;
  IF v_original.id IS NULL THEN RAISE EXCEPTION 'early_visit_original_not_found'; END IF;
  IF p_doctor_mode='same' AND
    (NOT v_same OR nullif(btrim(coalesce(v_original.doctor_name,'')),'') IS NULL) THEN
    RAISE EXCEPTION 'early_visit_original_doctor_not_confirmable';
  END IF;
  IF v_original.status NOT IN ('scheduled','confirmed','arrived') THEN
    RAISE EXCEPTION 'early_visit_original_not_active';
  END IF;
  v_original_day:=coalesce(
    (v_original.appointment_at AT TIME ZONE 'Asia/Bangkok')::date,
    v_original.planned_visit_date
  );
  IF v_original_day IS NULL OR p_visit_date>=v_original_day THEN
    RAISE EXCEPTION 'early_visit_must_precede_original_date';
  END IF;
  IF p_visit_date<v_today-365 THEN
    RAISE EXCEPTION 'early_visit_date_too_old';
  END IF;

  -- Idempotent for repeated taps only; do not prohibit truly separate clinical visits.
  SELECT id INTO v_existing
  FROM public.appointments
  WHERE early_visit_of_appointment_id=v_original.id
    AND planned_visit_date=p_visit_date
    AND visit_mode='walk_in'
    AND walk_in_reason=CASE WHEN v_reason='symptoms' THEN 'urgent' ELSE 'hospital_advised' END
    AND coalesce(hospital_name,'')=CASE WHEN v_same THEN coalesce(v_original.hospital_name,'') ELSE '' END
    AND created_by=v_access.actor_user_id
    AND deleted_at IS NULL
    AND created_at>now()-interval '2 minutes'
  ORDER BY created_at DESC LIMIT 1;
  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object('ok',true,'created',false,'already_created',true,
      'record_code',substr(v_existing::text,1,12),
      'original_record_code',substr(v_original.id::text,1,12),
      'kept_original',true,
      'planned_visit_date',p_visit_date,
      'same_hospital',v_same);
  END IF;

  INSERT INTO public.appointments(
    family_id,person_id,family_person_id,
    title,appointment_type,visit_mode,walk_in_reason,walk_in_note,
    planned_visit_date,visit_time_known,appointment_at,status,
    hospital_name,organization_id,service_unit_id,clinician_id,hospital_hn,hospital_vn,care_topic,walk_in_doctor_status,
    department,doctor_name,location_detail,coverage_type,contact_phone,contact_email,
    preparation_notes,note,treatment_episode_id,
    followup_kind,followup_interval_months,reference_note,early_visit_of_appointment_id,created_by
  ) VALUES (
    v_original.family_id,v_original.person_id,v_fp,
    'พบหมอก่อนนัด: '||left(coalesce(nullif(v_original.title,''),'ตรวจอาการ'),100),
    coalesce(v_original.appointment_type,'follow_up'),'walk_in',
    CASE WHEN v_reason='symptoms' THEN 'urgent' ELSE 'hospital_advised' END,
    CASE WHEN v_reason='symptoms'
      THEN 'มีอาการผิดปกติ จึงไปพบแพทย์ก่อนวันนัดเดิม'
      ELSE 'แพทย์แจ้งว่าสามารถไปพบก่อนวันนัดเดิมได้'
    END,
    p_visit_date,false,NULL,'scheduled',
    CASE WHEN v_same THEN v_original.hospital_name ELSE NULL END,
    CASE WHEN v_same THEN v_original.organization_id ELSE NULL END,
    CASE WHEN v_same THEN v_original.service_unit_id ELSE NULL END,
    CASE WHEN v_same AND p_doctor_mode='same' THEN v_original.clinician_id ELSE NULL END,
    CASE WHEN v_same THEN v_original.hospital_hn ELSE NULL END,
    CASE WHEN v_same THEN v_original.hospital_vn ELSE NULL END,
    v_original.care_topic,
    CASE p_doctor_mode WHEN 'same' THEN 'same_confirmed'
      WHEN 'on_duty' THEN 'on_duty_unknown'
      WHEN 'other' THEN 'different_unknown'
      ELSE 'pending' END,
    CASE WHEN v_same THEN v_original.department ELSE NULL END,
    CASE WHEN v_same AND p_doctor_mode='same' THEN v_original.doctor_name ELSE NULL END,
    CASE WHEN v_same THEN v_original.location_detail ELSE NULL END,
    NULL, -- Coverage must be explicitly confirmed for each clinical visit
    CASE WHEN v_same THEN v_original.contact_phone ELSE NULL END,
    CASE WHEN v_same THEN v_original.contact_email ELSE NULL END,
    NULL, -- New visit: preparation checklist is selected individually, not inherited
    NULL, -- New visit: appointment notes are independent
    v_original.treatment_episode_id,
    CASE WHEN v_original.appointment_type='follow_up' THEN coalesce(v_original.followup_kind,'general') ELSE NULL END,
    CASE WHEN v_original.appointment_type='follow_up' THEN v_original.followup_interval_months ELSE NULL END,
    'ไปพบแพทย์ก่อนนัดเดิม โดยคงนัดเดิมไว้จนกว่าโรงพยาบาลจะยืนยัน',
    v_original.id,v_access.actor_user_id
  ) RETURNING * INTO v_new;

  v_link_a:=least(v_original.id,v_new.id);
  v_link_b:=greatest(v_original.id,v_new.id);
  INSERT INTO private.appointment_links(
    appointment_id_a,appointment_id_b,link_kind,source,created_by
  ) VALUES(v_link_a,v_link_b,'continuity','early_visit',v_access.actor_user_id)
  ON CONFLICT DO NOTHING;


  -- The new encounter is independent: never copy arrival, completion or post-visit data.
  -- For the same hospital, link existing reference documents without copying their stored bytes.
  IF v_same THEN
    -- Do not automatically copy the previous appointment's preparation tasks.
    -- Users choose relevant tasks one by one via phms_line_early_visit_copy_selected_task.
    INSERT INTO public.appointment_document_links(
      appointment_id,medical_document_id,storage_asset_id,link_kind,note,
      created_by,usage_relation,origin_appointment_id
    )
    SELECT v_new.id,l.medical_document_id,l.storage_asset_id,'preparation',
      CASE WHEN l.link_kind='source'
        THEN concat_ws(' • ',NULLIF(btrim(l.note),''),'เอกสารจากนัดเดิม (ใช้อ้างอิง ไม่ใช่ใบนัดใหม่)')
        ELSE l.note END,
      v_access.actor_user_id,'carry_forward',coalesce(l.origin_appointment_id,v_original.id)
    FROM public.appointment_document_links l
    WHERE l.appointment_id=v_original.id AND l.link_kind IN ('preparation','source')
      AND (l.storage_asset_id IS NOT NULL OR l.medical_document_id IS NOT NULL)
      AND NOT EXISTS(
        SELECT 1 FROM public.appointment_document_links z
        WHERE z.appointment_id=v_new.id
          AND coalesce(z.storage_asset_id::text,z.medical_document_id::text)=coalesce(l.storage_asset_id::text,l.medical_document_id::text)
          AND z.link_kind='preparation'
      );
    GET DIAGNOSTICS v_documents_linked=ROW_COUNT;
  END IF;

  INSERT INTO public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    new_data,description
  ) VALUES(
    v_original.family_id,v_access.actor_user_id,v_fp,'appointment_early_visit_created',
    'appointment',v_new.id,
    jsonb_build_object('early_visit_of_appointment_id',v_original.id,
      'visit_date',p_visit_date,'same_hospital',v_same,'reason',v_reason,'doctor_mode',p_doctor_mode),
    'บันทึกการไปพบแพทย์ก่อนวันนัด โดยคงนัดเดิมและข้อมูลหลังนัดแยกกัน'
  );
  RETURN jsonb_build_object(
    'ok',true,'created',true,'already_created',false,
    'record_code',substr(v_new.id::text,1,12),
    'original_record_code',substr(v_original.id::text,1,12),
    'original_appointment_at',v_original.appointment_at,
    'planned_visit_date',v_new.planned_visit_date,
    'same_hospital',v_same,'kept_original',true,'doctor_mode',p_doctor_mode,
    'coverage_available',(v_same AND nullif(btrim(coalesce(v_original.coverage_type,'')),'') IS NOT NULL),
    'tasks_copied',v_tasks_copied,'documents_linked',v_documents_linked,
    'copied',jsonb_build_array('person','care_topic','clinical_episode')||
      CASE WHEN v_same THEN '["hospital","hospital_hn","hospital_vn"]'::jsonb ELSE '[]'::jsonb END
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.phms_line_create_walkin_plan(p_line_user_id text, p_visit_date date, p_appointment_type text, p_title text DEFAULT NULL::text, p_hospital_name text DEFAULT NULL::text, p_care_topic text DEFAULT NULL::text, p_walk_in_reason text DEFAULT NULL::text, p_followup_kind text DEFAULT NULL::text, p_followup_interval_months integer DEFAULT NULL::integer, p_department text DEFAULT NULL::text, p_doctor_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'private', 'pg_catalog'
AS $function$
declare
 v_ctx record; v_id uuid;
 v_type text:=lower(btrim(coalesce(p_appointment_type,'')));
 v_reason text:=nullif(btrim(coalesce(p_walk_in_reason,'')),'');
 v_kind text:=nullif(btrim(coalesce(p_followup_kind,'')),'');
 v_days date:=(now() at time zone 'Asia/Bangkok')::date;
begin
 select * into v_ctx from private.phms_line_crud_context(p_line_user_id,'appointment','create') limit 1;
 if v_ctx.target_person_id is null or v_ctx.active_family_person_id is null then raise exception 'person_required'; end if;
 if p_visit_date is null or p_visit_date<v_days then raise exception 'walk_in_plan_future_or_today_date_required'; end if;
 if v_type not in ('new_case','follow_up','referral','investigation','procedure','checkup','vaccination','other') then
  raise exception 'invalid_clinical_appointment_type';
 end if;
 if v_reason is not null and v_reason not in ('queue_full','hospital_advised','no_booking','urgent','other') then
  raise exception 'invalid_walk_in_reason';
 end if;
 if v_kind is not null and (v_type<>'follow_up' or v_kind not in ('general','chronic_routine','post_treatment','results_review')) then
  raise exception 'invalid_followup_kind';
 end if;
 if p_followup_interval_months is not null and (v_type<>'follow_up' or p_followup_interval_months not between 1 and 120) then
  raise exception 'invalid_followup_interval';
 end if;
 insert into public.appointments(
  family_id,family_person_id,person_id,title,hospital_name,department,doctor_name,
  appointment_type,care_topic,visit_mode,walk_in_reason,followup_kind,
  followup_interval_months,planned_visit_date,visit_time_known,appointment_at,
  status,created_by
 ) values (
  v_ctx.active_family_id,v_ctx.active_family_person_id,v_ctx.target_person_id,
  coalesce(nullif(btrim(p_title),''),'วางแผนไปโรงพยาบาล'),
  nullif(btrim(p_hospital_name),''),
  nullif(btrim(p_department),''),
  nullif(btrim(p_doctor_name),''),
  v_type,nullif(btrim(p_care_topic),''),
  'walk_in',v_reason,v_kind,p_followup_interval_months,p_visit_date,false,null,
  'scheduled',v_ctx.actor_user_id
 ) returning id into v_id;
 return jsonb_build_object(
  'ok',true,'record_id',v_id,'record_code',substr(v_id::text,1,12),
  'planned_visit_date',p_visit_date,'visit_time_known',false,'visit_mode','walk_in',
  'appointment_type',v_type
 );
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_line_crud_list_v2(p_line_user_id text, p_resource text, p_offset integer DEFAULT 0, p_page_size integer DEFAULT 8)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_key text:=private.phms_crud_resource_key(p_resource);
  v_ctx record;
  v_items jsonb:='[]'::jsonb;
  v_total integer:=0;
  v_offset integer:=greatest(coalesce(p_offset,0),0);
  v_size integer:=least(greatest(coalesce(p_page_size,8),1),50);
begin
  if v_key is null then raise exception 'invalid_crud_resource'; end if;
  select * into v_ctx from private.phms_line_crud_context(p_line_user_id,v_key,'view') limit 1;

  if v_key='medication' then
    select count(*)::int into v_total from public.person_medications pm
    where pm.person_id=v_ctx.target_person_id and pm.deleted_at is null;

    select coalesce(jsonb_agg(x.item order by x.sort_at desc),'[]'::jsonb) into v_items
    from (
      select coalesce(pm.updated_at,pm.created_at) sort_at,
        jsonb_strip_nulls(jsonb_build_object(
          'id',pm.id,'code',substr(pm.id::text,1,12),'resource','medication',
          'name',coalesce(mm.brand_name,mm.generic_name),'generic_name',mm.generic_name,'brand_name',mm.brand_name,
          'strength_value',mm.strength_value,'strength_unit',mm.strength_unit,'status',pm.status,
          'indication',pm.indication,'notes',pm.notes,'dose_text',mr.dose_text,
          'frequency_type',mr.frequency_type,'frequency_value',mr.frequency_value,'frequency_unit',mr.frequency_unit,
          'route',mr.route,'meal_relation',mr.meal_relation,'instructions',mr.instructions,
          'created_at',pm.created_at,'updated_at',pm.updated_at
        )) item
      from public.person_medications pm
      join public.medication_master mm on mm.id=pm.medication_id
      left join lateral (
        select r.* from public.medication_regimens r
        where r.person_medication_id=pm.id and r.deleted_at is null and r.is_current=true
        order by r.effective_from desc,r.created_at desc limit 1
      ) mr on true
      where pm.person_id=v_ctx.target_person_id and pm.deleted_at is null
      order by coalesce(pm.updated_at,pm.created_at) desc,pm.id
      offset v_offset limit v_size
    ) x;

  elsif v_key='appointment' then
    select count(*)::int into v_total from public.appointments a
    where a.person_id=v_ctx.target_person_id and a.deleted_at is null;

    select coalesce(jsonb_agg(x.item order by x.sort_at desc),'[]'::jsonb) into v_items
    from (
      select coalesce(a.appointment_at,a.created_at) sort_at,
        jsonb_strip_nulls(jsonb_build_object(
          'id',a.id,'code',substr(a.id::text,1,12),'resource','appointment',
          'title',a.title,'hospital_name',a.hospital_name,'department',a.department,'doctor_name',a.doctor_name,
          'appointment_at',a.appointment_at,'note',a.note,'status',a.status,'appointment_type',a.appointment_type,
          'created_at',a.created_at,'updated_at',a.updated_at
        )) item
      from public.appointments a
      where a.person_id=v_ctx.target_person_id and a.deleted_at is null
      order by coalesce(a.appointment_at,a.created_at) desc,a.id
      offset v_offset limit v_size
    ) x;

  elsif v_key='health' then
    select count(*)::int into v_total from public.health_measurements h
    where h.person_id=v_ctx.target_person_id and h.deleted_at is null;

    select coalesce(jsonb_agg(x.item order by x.sort_at desc),'[]'::jsonb) into v_items
    from (
      select h.measured_at sort_at,
        jsonb_strip_nulls(jsonb_build_object(
          'id',h.id,'code',substr(h.id::text,1,12),'resource','health',
          'measurement_type',h.measurement_type,'measured_at',h.measured_at,
          'value_numeric',h.value_numeric,'value_text',h.value_text,'unit',h.unit,
          'systolic',h.systolic,'diastolic',h.diastolic,'context',h.context,'notes',h.notes,
          'source_type',h.source_type,'created_at',h.created_at
        )) item
      from public.health_measurements h
      where h.person_id=v_ctx.target_person_id and h.deleted_at is null
      order by h.measured_at desc,h.created_at desc,h.id
      offset v_offset limit v_size
    ) x;

  else
    select count(*)::int into v_total from public.medical_documents d
    where d.person_id=v_ctx.target_person_id and d.deleted_at is null;

    select coalesce(jsonb_agg(x.item order by x.sort_at desc),'[]'::jsonb) into v_items
    from (
      select coalesce(d.document_date::timestamptz,d.created_at) sort_at,
        jsonb_strip_nulls(jsonb_build_object(
          'id',d.id,'code',substr(d.id::text,1,12),'resource','document',
          'document_type',d.document_type,'document_date',d.document_date,'title',d.title,
          'original_filename',d.original_filename,'mime_type',d.mime_type,
          'extraction_status',d.extraction_status,'storage_asset_id',d.storage_asset_id,
          'created_at',d.created_at,'updated_at',d.updated_at
        )) item
      from public.medical_documents d
      where d.person_id=v_ctx.target_person_id and d.deleted_at is null
      order by d.document_date desc nulls last,d.created_at desc,d.id
      offset v_offset limit v_size
    ) x;
  end if;

  return jsonb_build_object(
    'ok',true,'resource',v_key,'person_id',v_ctx.target_person_id,'person_name',v_ctx.target_person_name,
    'total_count',v_total,'offset',v_offset,'page_size',v_size,'items',v_items
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_crud_stop(p_line_user_id text, p_resource text, p_record_code text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ctx record;
  v_gate jsonb;
begin
  select * into v_ctx
  from private.phms_line_crud_context(
    p_line_user_id,p_resource,'delete'
  )
  limit 1;

  v_gate:=private.phms_real_data_gate_decision(
    v_ctx.active_family_id,
    v_ctx.target_person_id,
    array[private.phms_crud_resource_key(p_resource)],
    'stop',
    v_ctx.actor_user_id,
    0
  );

  if coalesce((v_gate->>'allowed')::boolean,false) is not true then
    raise exception '%',coalesce(v_gate->>'reason','real_data_gate_locked');
  end if;

  return private.phms_line_crud_stop_core(
    p_line_user_id,p_resource,p_record_code,p_reason
  );
end
$function$

