CREATE OR REPLACE FUNCTION public.phms_line_early_visit_copy_preparation(p_line_user_id text, p_early_record_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_early public.appointments%rowtype;
  v_original public.appointments%rowtype;
  v_task_count int:=0;
  v_doc_count int:=0;
begin
  select * into v_ref from private.phms_line_appointment_access(p_line_user_id,p_early_record_code) limit 1;
  if coalesce(v_ref.can_update,false) is not true then raise exception 'early_visit_copy_denied'; end if;
  select * into v_early from public.appointments where id=v_ref.record_id and deleted_at is null;
  if v_early.early_visit_of_appointment_id is null then raise exception 'not_early_visit'; end if;
  select * into v_original from public.appointments where id=v_early.early_visit_of_appointment_id and deleted_at is null;
  if v_original.id is null or v_original.person_id is distinct from v_early.person_id then raise exception 'early_visit_original_missing'; end if;

  insert into public.appointment_tasks(
    appointment_id,task_type,title,instruction,due_at,status,completed_at,completed_by,
    source_document_id,related_health_measurement_id,note,created_by,source_key,source_document_link_id
  )
  select
    v_early.id,t.task_type,t.title,t.instruction,null,'pending',null,null,
    t.source_document_id,t.related_health_measurement_id,t.note,v_ref.actor_user_id,
    'early_visit_copy:'||t.id::text,null
  from public.appointment_tasks t
  where t.appointment_id=v_original.id and t.status<>'cancelled'
    and not exists(
      select 1 from public.appointment_tasks z
      where z.appointment_id=v_early.id and (
        z.source_key='early_visit_copy:'||t.id::text
        or (btrim(z.title)=btrim(t.title) and z.task_type is not distinct from t.task_type)
      )
    );
  get diagnostics v_task_count=row_count;

  insert into public.appointment_document_links(
    appointment_id,medical_document_id,storage_asset_id,link_kind,note,created_by,usage_relation,origin_appointment_id
  )
  select
    v_early.id,l.medical_document_id,l.storage_asset_id,'preparation',
    case when l.link_kind='source'
      then concat_ws(' • ',nullif(btrim(l.note),''),'เอกสารจากนัดเดิม (ใช้อ้างอิง ไม่ใช่ใบนัดใหม่)')
      else l.note end,
    v_ref.actor_user_id,
    'carry_forward',coalesce(l.origin_appointment_id,v_original.id)
  from public.appointment_document_links l
  where l.appointment_id=v_original.id and l.link_kind in ('preparation','source')
    and not exists(
      select 1 from public.appointment_document_links z
      where z.appointment_id=v_early.id
        and coalesce(z.storage_asset_id::text,z.medical_document_id::text)=coalesce(l.storage_asset_id::text,l.medical_document_id::text)
        and z.link_kind='preparation'
    );
  get diagnostics v_doc_count=row_count;

  return jsonb_build_object(
    'ok',true,'early_record_code',substr(v_early.id::text,1,12),
    'original_record_code',substr(v_original.id::text,1,12),
    'tasks_copied',v_task_count,'documents_linked',v_doc_count
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_early_visit_copy_preparation_note(p_line_user_id text, p_early_record_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_early public.appointments%rowtype;
  v_original public.appointments%rowtype;
  v_copied boolean:=false;
begin
  select * into v_ref
  from private.phms_line_appointment_access(p_line_user_id,p_early_record_code)
  limit 1;

  if coalesce(v_ref.can_update,false) is not true then
    raise exception 'early_visit_copy_denied';
  end if;

  select * into v_early
  from public.appointments
  where id=v_ref.record_id and deleted_at is null;

  if v_early.early_visit_of_appointment_id is null then
    raise exception 'not_early_visit';
  end if;

  select * into v_original
  from public.appointments
  where id=v_early.early_visit_of_appointment_id
    and person_id=v_early.person_id
    and deleted_at is null;

  if v_original.id is null then
    raise exception 'early_visit_original_missing';
  end if;

  if nullif(btrim(coalesce(v_original.preparation_notes,'')),'') is not null then
    update public.appointments
    set preparation_notes=v_original.preparation_notes,
        updated_at=now()
    where id=v_early.id;
    v_copied:=true;
  end if;

  return jsonb_build_object(
    'ok',true,
    'early_record_code',substr(v_early.id::text,1,12),
    'original_record_code',substr(v_original.id::text,1,12),
    'preparation_note_copied',v_copied
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_early_visit_copy_selected_task(p_line_user_id text, p_early_record_code text, p_task_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_access record;
 v_old_access record;
 v_early public.appointments%rowtype;
 v_old public.appointments%rowtype;
 v_task public.appointment_tasks%rowtype;
 v_existing uuid;
 v_new uuid;
 v_code text:=lower(btrim(coalesce(p_task_code,'')));
begin
 if v_code !~ '^[0-9a-f]{12}$' then raise exception 'invalid_task_code'; end if;
 select * into v_access from private.phms_line_appointment_access(p_line_user_id,p_early_record_code) limit 1;
 if v_access.record_id is null or coalesce(v_access.can_update,false) is not true
 then raise exception 'early_visit_task_copy_denied'; end if;
 select * into v_early from public.appointments
 where id=v_access.record_id and deleted_at is null for update;
 if v_early.early_visit_of_appointment_id is null then raise exception 'not_early_visit'; end if;
 select * into v_old from public.appointments where id=v_early.early_visit_of_appointment_id and deleted_at is null;
 if v_old.id is null or v_old.person_id is distinct from v_early.person_id or v_old.family_id is distinct from v_early.family_id
 then raise exception 'early_visit_source_mismatch'; end if;
 select * into v_old_access from private.phms_line_appointment_access(p_line_user_id,substr(v_old.id::text,1,12)) limit 1;
 if v_old_access.record_id is distinct from v_old.id or coalesce(v_old_access.has_person_view,false) is not true
 then raise exception 'early_visit_source_view_denied'; end if;

 select * into v_task from public.appointment_tasks t
 where t.appointment_id=v_old.id and t.status<>'cancelled'
 and substr(t.id::text,1,12)=v_code;
 if v_task.id is null then raise exception 'task_not_found_or_not_allowed'; end if;

 select id into v_existing from public.appointment_tasks z
 where z.appointment_id=v_early.id
 and (z.source_key='early_visit_copy:'||v_task.id::text
  or (btrim(z.title)=btrim(v_task.title) and z.task_type is not distinct from v_task.task_type))
 order by z.created_at limit 1;
 if v_existing is not null then
  return jsonb_build_object('ok',true,'already_selected',true,'record_code',substr(v_early.id::text,1,12),
   'title',v_task.title,'task_code',substr(v_task.id::text,1,12));
 end if;

 insert into public.appointment_tasks(
  appointment_id,task_type,title,instruction,due_at,status,completed_at,completed_by,
  source_document_id,related_health_measurement_id,note,created_by,source_key,source_document_link_id
 ) values(
  v_early.id,v_task.task_type,v_task.title,v_task.instruction,null,'pending',null,null,
  v_task.source_document_id,null,v_task.note,v_access.actor_user_id,
  'early_visit_copy:'||v_task.id::text,null
 ) returning id into v_new;

 return jsonb_build_object('ok',true,'already_selected',false,'record_code',substr(v_early.id::text,1,12),
  'task_code',substr(v_task.id::text,1,12),'new_task_code',substr(v_new::text,1,12),'title',v_task.title);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_early_visit_original_decision(p_line_user_id text, p_early_record_code text, p_decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
DECLARE
  v_ref record;
  v_early public.appointments%rowtype;
  v_original public.appointments%rowtype;
  v_original_code text;
  v_action jsonb;
  v_cancel jsonb;
  v_decision text:=lower(btrim(coalesce(p_decision,'')));
BEGIN
  IF v_decision NOT IN ('keep','cancel') THEN
    RAISE EXCEPTION 'early_visit_original_decision_invalid';
  END IF;

  SELECT * INTO v_ref
  FROM private.phms_line_appointment_access(p_line_user_id,p_early_record_code)
  LIMIT 1;
  IF v_ref.record_id IS NULL THEN
    RAISE EXCEPTION 'early_visit_not_accessible';
  END IF;

  SELECT * INTO v_early
  FROM public.appointments
  WHERE id=v_ref.record_id AND deleted_at IS NULL;
  IF NOT FOUND OR v_early.early_visit_of_appointment_id IS NULL THEN
    RAISE EXCEPTION 'not_an_early_visit';
  END IF;
  IF v_early.status <> 'completed' THEN
    RAISE EXCEPTION 'early_visit_not_completed';
  END IF;

  SELECT * INTO v_original
  FROM public.appointments
  WHERE id=v_early.early_visit_of_appointment_id
    AND person_id=v_early.person_id
    AND deleted_at IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'original_appointment_not_found';
  END IF;

  v_original_code:=substr(v_original.id::text,1,12);
  v_action:=public.phms_line_appointment_action_capabilities(
    p_line_user_id,v_original_code
  );
  IF coalesce((v_action->>'can_manage_status')::boolean,false) IS NOT TRUE THEN
    RAISE EXCEPTION 'original_appointment_manage_permission_denied';
  END IF;

  IF v_decision='cancel' THEN
    BEGIN
      PERFORM 1
      FROM private.phms_find_crud_record(
        p_line_user_id,'appointment',v_original_code,'delete'
      )
      LIMIT 1;
      IF NOT FOUND THEN RAISE EXCEPTION 'original_appointment_cancel_permission_denied'; END IF;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'original_appointment_cancel_permission_denied';
    END;
    IF v_original.status IN ('scheduled','confirmed','arrived') THEN
      v_cancel:=public.phms_line_appointment_cancel(
        p_line_user_id,
        v_original_code,
        'ไปพบแพทย์ก่อนวันนัดแล้ว และแพทย์แจ้งว่าไม่ต้องมาตามนัดเดิม'
      );
    ELSIF v_original.status <> 'cancelled' THEN
      RAISE EXCEPTION 'original_appointment_not_active';
    END IF;
  END IF;

  INSERT INTO public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    new_data,description
  ) VALUES(
    v_early.family_id,
    v_ref.actor_user_id,
    v_early.family_person_id,
    CASE WHEN v_decision='keep'
      THEN 'appointment_early_visit_original_kept'
      ELSE 'appointment_early_visit_original_cancelled' END,
    'appointment',
    v_early.id,
    jsonb_build_object(
      'decision',v_decision,
      'original_appointment_id',v_original.id,
      'original_record_code',v_original_code
    ),
    CASE WHEN v_decision='keep'
      THEN 'หลังไปพบแพทย์ก่อนนัด ยืนยันว่าให้คงนัดเดิมไว้'
      ELSE 'หลังไปพบแพทย์ก่อนนัด ยืนยันว่าไม่ต้องไปนัดเดิมแล้ว' END
  );

  RETURN jsonb_build_object(
    'ok',true,
    'decision',v_decision,
    'early_record_code',substr(v_early.id::text,1,12),
    'original_record_code',v_original_code,
    'original_status',CASE WHEN v_decision='cancel' THEN 'cancelled' ELSE v_original.status END
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.phms_line_early_visit_preparation_choices(p_line_user_id text, p_early_record_code text, p_offset integer DEFAULT 0, p_limit integer DEFAULT 8)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_access record;
 v_old_access record;
 v_early public.appointments%rowtype;
 v_old public.appointments%rowtype;
 v_offset integer:=greatest(0,least(coalesce(p_offset,0),200));
 v_limit integer:=greatest(1,least(coalesce(p_limit,8),10));
 v_items jsonb:='[]'::jsonb;
 v_count integer:=0;
begin
 select * into v_access from private.phms_line_appointment_access(p_line_user_id,p_early_record_code) limit 1;
 if v_access.record_id is null or coalesce(v_access.can_update,false) is not true
 then raise exception 'early_visit_preparation_update_denied'; end if;
 select * into v_early from public.appointments where id=v_access.record_id and deleted_at is null;
 if v_early.early_visit_of_appointment_id is null then raise exception 'not_early_visit'; end if;
 select * into v_old from public.appointments where id=v_early.early_visit_of_appointment_id and deleted_at is null;
 if v_old.id is null or v_old.person_id is distinct from v_early.person_id or v_old.family_id is distinct from v_early.family_id
 then raise exception 'early_visit_source_mismatch'; end if;
 select * into v_old_access from private.phms_line_appointment_access(p_line_user_id,substr(v_old.id::text,1,12)) limit 1;
 if v_old_access.record_id is distinct from v_old.id or coalesce(v_old_access.has_person_view,false) is not true
 then raise exception 'early_visit_source_view_denied'; end if;

 select count(*)::integer into v_count
 from public.appointment_tasks t where t.appointment_id=v_old.id and t.status<>'cancelled';

 select coalesce(jsonb_agg(jsonb_build_object(
  'task_code',substr(q.id::text,1,12),'title',q.title,
  'instruction',q.instruction,'selected',q.already_selected
 ) order by q.created_at,q.id),'[]'::jsonb) into v_items
 from (
  select t.id,t.title,t.instruction,t.created_at,
   exists(select 1 from public.appointment_tasks z
    where z.appointment_id=v_early.id
    and z.source_key='early_visit_copy:'||t.id::text) as already_selected
  from public.appointment_tasks t
  where t.appointment_id=v_old.id and t.status<>'cancelled'
  order by t.created_at,t.id
  limit v_limit offset v_offset
 ) q;

 return jsonb_build_object('ok',true,'record_code',substr(v_early.id::text,1,12),
  'original_record_code',substr(v_old.id::text,1,12),
  'count',v_count,'offset',v_offset,'limit',v_limit,'items',v_items);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_early_visit_set_coverage(p_line_user_id text, p_early_record_code text, p_mode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_ref record;
 v_early public.appointments%rowtype;
 v_old public.appointments%rowtype;
 v_mode text:=lower(btrim(coalesce(p_mode,'')));
 v_coverage text;
begin
 if v_mode not in ('same','change') then raise exception 'invalid_coverage_choice'; end if;
 select * into v_ref from private.phms_line_appointment_access(p_line_user_id,p_early_record_code) limit 1;
 if v_ref.record_id is null or coalesce(v_ref.can_update,false) is not true
 then raise exception 'early_visit_coverage_update_denied'; end if;
 select * into v_early from public.appointments where id=v_ref.record_id and deleted_at is null for update;
 if v_early.early_visit_of_appointment_id is null then raise exception 'not_early_visit'; end if;
 select * into v_old from public.appointments where id=v_early.early_visit_of_appointment_id and deleted_at is null;
 if v_old.id is null or v_old.person_id is distinct from v_early.person_id or v_old.family_id is distinct from v_early.family_id
 then raise exception 'early_visit_original_mismatch'; end if;
 if v_mode='same' then
  if nullif(btrim(coalesce(v_early.hospital_name,'')),'') is null
   or btrim(coalesce(v_early.hospital_name,'')) is distinct from btrim(coalesce(v_old.hospital_name,''))
  then raise exception 'early_visit_hospital_changed'; end if;
  v_coverage:=nullif(btrim(coalesce(v_old.coverage_type,'')),'');
  if v_coverage is null then raise exception 'no_previous_coverage'; end if;
 else
  v_coverage:=null;
 end if;
 update public.appointments
 set coverage_type=v_coverage,updated_at=now()
 where id=v_early.id;
 insert into public.audit_logs(
  family_id,actor_user_id,family_person_id,event_type,resource,record_id,new_data,description
 ) values(
  v_early.family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
  'appointment_early_visit_coverage_confirmed','appointment',v_early.id,
  jsonb_build_object('mode',v_mode,'coverage_type',v_coverage),
  'ยืนยันหรือเปลี่ยนสิทธิรักษาของการไปก่อนนัด'
 );
 return jsonb_build_object('ok',true,'record_code',substr(v_early.id::text,1,12),
  'mode',v_mode,'coverage_type',v_coverage);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_early_visit_set_doctor(p_line_user_id text, p_record_code text, p_doctor_mode text, p_doctor_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
DECLARE
 v_ref record;
 v_row public.appointments%rowtype;
 v_original public.appointments%rowtype;
 v_old jsonb;
 v_new jsonb;
 v_name text;
 v_status text;
 v_clinician uuid;
BEGIN
 IF p_doctor_mode IS NULL OR p_doctor_mode NOT IN ('same','on_duty','other','unknown','named') THEN
  RAISE EXCEPTION 'walkin_doctor_choice_invalid';
 END IF;
 SELECT * INTO v_ref FROM private.phms_find_crud_record(
   p_line_user_id,'appointment',p_record_code,'update'
 ) LIMIT 1;
 SELECT * INTO v_row FROM public.appointments
  WHERE id=v_ref.record_id AND deleted_at IS NULL FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'walkin_appointment_not_found'; END IF;
 IF v_row.visit_mode IS DISTINCT FROM 'walk_in' THEN RAISE EXCEPTION 'appointment_not_walkin'; END IF;
 IF v_row.early_visit_of_appointment_id IS NOT NULL THEN
  SELECT * INTO v_original FROM public.appointments o
   WHERE o.id=v_row.early_visit_of_appointment_id
     AND o.person_id=v_row.person_id AND o.family_id=v_row.family_id
     AND o.deleted_at IS NULL;
 END IF;
 IF p_doctor_mode='same' THEN
  IF v_original.id IS NULL
    OR v_row.hospital_name IS DISTINCT FROM v_original.hospital_name
    OR NULLIF(BTRIM(COALESCE(v_original.doctor_name,'')),'') IS NULL THEN
    RAISE EXCEPTION 'walkin_original_doctor_unavailable';
  END IF;
  v_name:=v_original.doctor_name;
  v_clinician:=v_original.clinician_id;
  v_status:='same_confirmed';
 ELSIF p_doctor_mode='named' THEN
  v_name:=NULLIF(BTRIM(COALESCE(p_doctor_name,'')),'');
  IF v_name IS NULL OR char_length(v_name)<2 OR char_length(v_name)>200 THEN
    RAISE EXCEPTION 'walkin_doctor_name_required';
  END IF;
  v_clinician:=NULL;
  v_status:='other_confirmed';
 ELSE
  v_name:=NULL;
  v_clinician:=NULL;
  v_status:=CASE p_doctor_mode
   WHEN 'on_duty' THEN 'on_duty_unknown'
   WHEN 'other' THEN 'different_unknown'
   ELSE 'pending' END;
 END IF;
 v_old:=to_jsonb(v_row);
 UPDATE public.appointments SET
   doctor_name=v_name,clinician_id=v_clinician,walk_in_doctor_status=v_status,
   updated_at=now(),
   last_change_reason='ยืนยันข้อมูลแพทย์สำหรับ Walk-in'
 WHERE id=v_row.id RETURNING to_jsonb(appointments.*) INTO v_new;
 INSERT INTO public.audit_logs(
   family_id,actor_user_id,family_person_id,event_type,resource,record_id,
   old_data,new_data,description
 ) VALUES(
   v_ref.active_family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
   'appointment_walkin_doctor_updated','appointment',v_row.id,v_old,v_new,
   'ตรวจสอบแพทย์อีกครั้งสำหรับการไปก่อนนัด'
 );
 RETURN jsonb_build_object('ok',true,'record_code',substr(v_row.id::text,1,12),
   'doctor_name',v_name,'doctor_status',v_status);
END
$function$

CREATE OR REPLACE FUNCTION public.phms_line_five_category_access_settings(p_line_user_id text, p_member_code text, p_person_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth'
AS $function$
declare m record;p record; pol public.person_five_category_policies%rowtype; v_levels jsonb;
begin
 select * into m from private.resolve_line_family_member(p_line_user_id,p_member_code);
 select * into p from private.resolve_line_family_person_code(p_line_user_id,p_person_code);
 if m.family_id<>p.family_id then raise exception 'family_scope_mismatch';end if;
 if not private.phms_can_manage_medical_grants(m.actor_user_id,p.family_person_id) then raise exception 'permission_management_denied';end if;
 select * into pol from public.person_five_category_policies where family_person_id=p.family_person_id and user_id=m.target_user_id and family_id=m.family_id;
 if not found then return jsonb_build_object('configured',false,'base_level',null,'overrides','{}'::jsonb);end if;
 select jsonb_object_agg(x.resource,coalesce(pol.overrides->>x.resource,pol.base_level)) into v_levels
 from (values ('appointments'::text),('medications'),('health_data'),('documents'),('expenses')) x(resource);
 return jsonb_build_object('configured',true,'base_level',pol.base_level,'overrides',pol.overrides,'effective',v_levels);
end $function$

CREATE OR REPLACE FUNCTION public.phms_line_group_link_request_remind(p_line_user_id text, p_request_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_actor uuid;
  v_req public.line_group_link_requests%rowtype;
  v_fc public.family_channels%rowtype;
  v_family public.families%rowtype;
  v_code text:=lower(btrim(coalesce(p_request_code,'')));
  v_count integer;
  v_anchor timestamptz;
  v_reviewer record;
  v_reviewer_count integer:=0;
  v_requester_label text;
  v_stage text;
begin
  select li.user_id into v_actor
  from public.line_identities li
  where li.line_user_id=p_line_user_id
    and li.is_active=true
    and li.onboarding_status='ready'
  order by li.updated_at desc nulls last,li.created_at desc
  limit 1;
  if v_actor is null then raise exception 'line_identity_not_ready'; end if;

  select count(*) into v_count
  from public.line_group_link_requests r
  where r.requested_by=v_actor and lower(r.id::text) like v_code||'%';
  if v_count=0 then raise exception 'group_link_request_not_found'; end if;
  if v_count>1 then raise exception 'group_link_request_code_ambiguous'; end if;

  select * into v_req
  from public.line_group_link_requests r
  where r.requested_by=v_actor and lower(r.id::text) like v_code||'%'
  limit 1 for update;

  select * into v_fc from public.family_channels where id=v_req.family_channel_id;
  select * into v_family from public.families where id=v_req.family_id;

  if v_req.status='pending' then
    v_anchor:=coalesce(v_req.last_reminded_at,v_req.requested_at);
    v_stage:='pending_review';
  elsif v_req.status='approved' and v_fc.setup_completed_at is null then
    v_anchor:=coalesce(v_req.last_reminded_at,v_req.reviewed_at,v_req.requested_at);
    v_stage:='approved_setup_pending';
  else
    raise exception 'group_link_request_not_waiting';
  end if;

  if now() < v_anchor + interval '3 days' then
    raise exception 'group_link_request_remind_too_soon';
  end if;

  for v_reviewer in
    select distinct fm.user_id
    from public.family_memberships fm
    where fm.family_id=v_req.family_id
      and fm.status='active'
      and private.user_has_family_role(fm.user_id,v_req.family_id,array['owner','admin'])
      and exists(
        select 1 from public.line_identities li
        where li.user_id=fm.user_id and li.is_active=true and li.onboarding_status='ready'
      )
  loop
    v_requester_label:=private.family_user_label_for_viewer(
      v_reviewer.user_id,v_req.family_id,v_req.requested_by
    );

    insert into public.notifications(
      family_id,recipient_user_id,event_type,title,message,related_record_id,
      channel,priority,status,scheduled_for,next_attempt_at,payload,dedupe_key,
      created_at,updated_at
    ) values(
      v_req.family_id,v_reviewer.user_id,'line_group_link_request_reminder',
      case when v_stage='pending_review'
        then '🔔 มีคำขอเชื่อม LINE กลุ่มที่ยังรอตรวจสอบ'
        else '🔔 LINE กลุ่มที่อนุมัติแล้ว ยังตั้งค่าไม่เสร็จ'
      end,
      case when v_stage='pending_review'
        then concat(v_requester_label,' ส่งคำขอเชื่อม LINE กลุ่ม “',
          coalesce(nullif(btrim(v_fc.channel_name),''),'LINE กลุ่ม'),'” กับ ',
          coalesce(nullif(btrim(v_family.family_name),''),'ครอบครัว'),' และยังรอตรวจสอบ')
        else concat('LINE กลุ่ม “',coalesce(nullif(btrim(v_fc.channel_name),''),'LINE กลุ่ม'),
          '” ของ ',coalesce(nullif(btrim(v_family.family_name),''),'ครอบครัว'),
          ' อนุมัติแล้ว แต่ยังต้องเลือกข้อมูลและกดเปิดใช้งาน')
      end,
      v_req.id,'line','normal','pending',now(),now(),
      jsonb_build_object(
        'stage',v_stage,
        'request_code',substr(v_req.id::text,1,12),
        'group_name',coalesce(nullif(btrim(v_fc.channel_name),''),'LINE กลุ่ม'),
        'family_name',coalesce(nullif(btrim(v_family.family_name),''),'ครอบครัว'),
        'requested_by_name',v_requester_label,
        'requested_at',v_req.requested_at,
        'reviewed_at',v_req.reviewed_at
      ),
      'line-group-link-reminder:'||v_req.id::text||':'||v_reviewer.user_id::text||':'||
        to_char((now() at time zone 'Asia/Bangkok')::date,'YYYYMMDD'),
      now(),now()
    )
    on conflict(dedupe_key) where dedupe_key is not null do nothing;

    v_reviewer_count:=v_reviewer_count+1;
  end loop;

  update public.line_group_link_requests
  set last_reminded_at=now(),
      reminder_count=reminder_count+1,
      updated_at=now()
  where id=v_req.id;

  return jsonb_build_object(
    'ok',true,
    'request_code',substr(v_req.id::text,1,12),
    'stage',v_stage,
    'reviewer_count',v_reviewer_count,
    'reminded_at',now(),
    'next_reminder_at',now()+interval '3 days'
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_group_mark_question_window(p_line_group_id text, p_minutes integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_fc uuid;
  v_until timestamptz;
begin
  select id into v_fc from public.family_channels
  where channel_type='line_group'
    and external_channel_id=btrim(p_line_group_id)
    and status='active'
  limit 1;
  if v_fc is null then return jsonb_build_object('ok',false,'linked',false); end if;

  v_until:=now()+make_interval(mins=>greatest(1,least(coalesce(p_minutes,5),15)));
  insert into public.family_channel_conversation_state(family_channel_id,awaiting_question_until,updated_at)
  values(v_fc,v_until,now())
  on conflict(family_channel_id) do update set awaiting_question_until=excluded.awaiting_question_until,updated_at=now();

  return jsonb_build_object('ok',true,'linked',true,'until',v_until);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_group_membership_event(p_line_group_id text, p_event text, p_event_id text DEFAULT NULL::text, p_channel_name text DEFAULT NULL::text, p_picture_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
DECLARE
 v_group text:=btrim(coalesce(p_line_group_id,''));
 v_kind text:=lower(btrim(coalesce(p_event,'')));
 v_event_id text:=nullif(btrim(coalesce(p_event_id,'')),'');
 v_fc public.family_channels%rowtype;
 v_had_completed boolean:=false;
BEGIN
 IF length(v_group)<8 OR length(v_group)>128 THEN RAISE EXCEPTION 'invalid_line_group_id'; END IF;
 IF v_kind NOT IN ('join','leave') THEN RAISE EXCEPTION 'invalid_group_membership_event'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('phms-group-membership:'||v_group,0));
 SELECT * INTO v_fc FROM public.family_channels
 WHERE channel_type='line_group' AND external_channel_id=v_group FOR UPDATE;
 IF v_fc.id IS NULL AND v_kind='leave' THEN
   RETURN jsonb_build_object('ok',true,'not_found',true);
 END IF;
 IF v_fc.id IS NULL THEN
   INSERT INTO public.family_channels(
     family_id,channel_type,external_channel_id,channel_name,channel_picture_url,
     status,can_receive_notifications,can_query_bot,privacy_level,
     linked_at,last_seen_at,last_joined_at,last_join_event_id,membership_generation
   ) VALUES (
     null,'line_group',v_group,
     nullif(btrim(coalesce(p_channel_name,'')),''),
     nullif(btrim(coalesce(p_picture_url,'')),''),
     'pending_link',false,false,'summary',null,now(),now(),v_event_id,1
   ) RETURNING * INTO v_fc;
 ELSE
   IF v_event_id IS NOT NULL AND
     ((v_kind='join' AND v_fc.last_join_event_id=v_event_id)
      OR (v_kind='leave' AND v_fc.last_leave_event_id=v_event_id)) THEN
      RETURN jsonb_build_object('ok',true,'duplicate',true,'status',v_fc.status,
                                'generation',v_fc.membership_generation);
   END IF;
   v_had_completed:=v_fc.setup_completed_at IS NOT NULL OR v_fc.last_completed_at IS NOT NULL;
   IF v_kind='leave' THEN
     UPDATE public.family_channels SET
       status='left',can_query_bot=false,can_receive_notifications=false,
       last_completed_at=coalesce(last_completed_at,setup_completed_at),
       setup_started_at=null,setup_completed_at=null,setup_completed_by=null,
       ready_sent_at=null,last_left_at=now(),last_leave_event_id=v_event_id,
       updated_at=now()
     WHERE id=v_fc.id;
   ELSE
     UPDATE public.family_channels SET
       status='pending_link',can_query_bot=false,can_receive_notifications=false,
       channel_name=coalesce(nullif(btrim(coalesce(p_channel_name,'')),''),channel_name),
       channel_picture_url=coalesce(nullif(btrim(coalesce(p_picture_url,'')),''),channel_picture_url),
       last_completed_at=coalesce(last_completed_at,setup_completed_at),
       setup_started_at=null,setup_completed_at=null,setup_completed_by=null,
       ready_sent_at=null,last_joined_at=now(),last_seen_at=now(),
       last_join_event_id=v_event_id,membership_generation=membership_generation+1,
       updated_at=now()
     WHERE id=v_fc.id;
   END IF;
   IF NOT v_had_completed THEN
     UPDATE public.family_channel_family_links SET status='disabled',updated_at=now()
       WHERE family_channel_id=v_fc.id AND status='active';
     UPDATE public.family_channel_query_scopes SET enabled=false,updated_at=now()
       WHERE family_channel_id=v_fc.id AND enabled=true;
     UPDATE public.family_channels SET family_id=null,linked_by=null,linked_at=null,updated_at=now()
       WHERE id=v_fc.id;
   END IF;
 END IF;
 UPDATE public.line_group_link_requests
 SET status='cancelled',review_note='bot_'||v_kind||'_onboarding_reset',
     reviewed_at=now(),updated_at=now()
 WHERE family_channel_id=v_fc.id AND status='pending';
 UPDATE public.notifications n
 SET status='cancelled',last_error='bot_'||v_kind||'_onboarding_reset',
     updated_at=now(),locked_at=null,lock_token=null
 WHERE n.status IN ('pending','failed')
   AND ( (n.event_type IN ('line_group_setup_reminder','line_group_auto_setup_prompt')
          AND n.related_record_id=v_fc.id)
      OR (n.event_type='line_group_link_request' AND EXISTS(
          SELECT 1 FROM public.line_group_link_requests r
          WHERE r.id=n.related_record_id AND r.family_channel_id=v_fc.id AND r.status='cancelled'))
      OR (n.payload->>'line_destination_type'='group'
          AND n.payload->>'line_destination_id'=v_group) );
 DELETE FROM public.line_conversation_states
 WHERE state_key='line_group_private_setup' AND state_data->>'line_group_id'=v_group;
 UPDATE public.family_channel_conversation_state
 SET awaiting_question_until=null,updated_at=now()
 WHERE family_channel_id=v_fc.id;
 RETURN jsonb_build_object('ok',true,'event',v_kind,'status',
       CASE WHEN v_kind='join' THEN 'pending_link' ELSE 'left' END,
       'previously_ready',v_had_completed,
       'restart_required',NOT v_had_completed,
       'reconfirmation_required',v_had_completed,
       'generation',(SELECT membership_generation FROM public.family_channels WHERE id=v_fc.id));
END $function$

CREATE OR REPLACE FUNCTION public.phms_line_group_prepare_private_write(p_line_user_id text, p_line_group_id text, p_person_code text, p_resource text, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line public.line_identities%rowtype;
  v_fc public.family_channels%rowtype;
  v_fp public.family_persons%rowtype;
  v_person public.persons%rowtype;
  v_resource text:=lower(btrim(coalesce(p_resource,'')));
  v_action text:=lower(btrim(coalesce(p_action,'')));
  v_count integer;
  v_allowed boolean:=false;
  v_can_view boolean:=false;
  v_group_scope boolean:=false;
  v_person_name text;
  v_family_name text;
begin
  if v_resource not in ('appointments','medications','health_data') then
    raise exception 'unsupported_group_write_resource';
  end if;
  if v_action not in ('create','update','delete') then
    raise exception 'unsupported_group_write_action';
  end if;

  select * into v_line
  from public.line_identities li
  where li.line_user_id=p_line_user_id
    and li.is_active=true
  order by li.updated_at desc nulls last,li.created_at desc
  limit 1;
  if not found then raise exception 'line_identity_not_found'; end if;
  if v_line.user_id is null then raise exception 'line_identity_not_linked'; end if;

  select * into v_fc
  from public.family_channels fc
  where fc.channel_type='line_group'
    and fc.external_channel_id=btrim(p_line_group_id)
    and fc.status in ('active','pending_link')
  limit 1;
  if v_fc.id is null then raise exception 'group_not_linked'; end if;

  select count(*),min(fp.id::text)::uuid
  into v_count,v_fp.id
  from public.family_persons fp
  where lower(fp.id::text) like lower(btrim(p_person_code))||'%'
    and coalesce(fp.status,'active')='active'
    and (
      exists(
        select 1 from public.family_channel_family_links l
        where l.family_channel_id=v_fc.id and l.family_id=fp.family_id and l.status='active'
      )
      or not exists(
        select 1 from public.family_channel_family_links l0
        where l0.family_channel_id=v_fc.id and l0.status='active'
      )
    )
    and exists(
      select 1 from public.family_memberships fm
      where fm.family_id=fp.family_id
        and fm.user_id=v_line.user_id
        and fm.status='active'
    );
  if v_count=0 then raise exception 'group_person_not_accessible'; end if;
  if v_count>1 then raise exception 'group_person_code_ambiguous'; end if;

  select * into v_fp
  from public.family_persons fp
  where lower(fp.id::text) like lower(btrim(p_person_code))||'%'
    and coalesce(fp.status,'active')='active'
    and (
      exists(
        select 1 from public.family_channel_family_links l
        where l.family_channel_id=v_fc.id and l.family_id=fp.family_id and l.status='active'
      )
      or not exists(
        select 1 from public.family_channel_family_links l0
        where l0.family_channel_id=v_fc.id and l0.status='active'
      )
    )
    and exists(
      select 1 from public.family_memberships fm
      where fm.family_id=fp.family_id
        and fm.user_id=v_line.user_id
        and fm.status='active'
    )
  limit 1;

  select * into v_person
  from public.persons
  where id=v_fp.person_id
    and coalesce(status,'active')='active';
  if not found then raise exception 'person_not_found'; end if;

  v_allowed:=private.user_can_access_family_person(
    v_line.user_id,v_fp.id,v_resource,v_action
  );
  v_can_view:=private.user_can_access_family_person(
    v_line.user_id,v_fp.id,v_resource,'view'
  );
  v_group_scope:=exists(
    select 1 from public.family_channel_query_scopes qs
    where qs.family_channel_id=v_fc.id
      and qs.family_person_id=v_fp.id
      and qs.resource=v_resource
      and qs.enabled=true
      and v_fc.setup_completed_at is not null
      and coalesce(v_fc.can_query_bot,false)=true
  );

  if not v_allowed and not v_can_view and not v_group_scope
    and not private.user_can_see_family_person(v_line.user_id,v_fp.id) then
    raise exception 'group_person_not_accessible';
  end if;

  select coalesce(nullif(btrim(f.family_name),''),'ครอบครัว')
  into v_family_name
  from public.families f
  where f.id=v_fp.family_id;

  v_person_name:=case
    when private.user_can_see_family_person(v_line.user_id,v_fp.id)
      then private.family_person_label_for_viewer(v_line.user_id,v_fp.id)
    else private.family_person_central_label(v_fp.id)
  end;

  if v_allowed then
    perform private.ensure_line_identity_context(v_line.id,v_line.user_id);
    update private.line_identity_contexts c
    set active_scope='family',
        active_family_id=v_fp.family_id,
        active_family_person_id=v_fp.id,
        context_changed_at=now(),
        updated_at=now()
    where c.line_identity_id=v_line.id;

    insert into public.person_context_usage(
      user_id,family_person_id,use_count,first_used_at,last_used_at
    ) values(
      v_line.user_id,v_fp.id,1,now(),now()
    )
    on conflict on constraint person_context_usage_pkey
    do update set
      use_count=public.person_context_usage.use_count+1,
      last_used_at=now();
  end if;

  return jsonb_build_object(
    'ok',true,
    'allowed',v_allowed,
    'can_view',v_can_view,
    'group_scope_enabled',v_group_scope,
    'person_code',substr(v_fp.id::text,1,12),
    'person_name',coalesce(v_person_name,'บุคคลในครอบครัว'),
    'family_code',substr(v_fp.family_id::text,1,12),
    'family_name',v_family_name,
    'resource',v_resource,
    'action',v_action
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_group_query_safe_for_user(p_line_group_id text, p_line_user_id text, p_person_code text, p_resource text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_data jsonb;
  v_viewer_user_id uuid;
  v_fp_id uuid;
  v_count int;
  v_name text;
begin
  v_data:=public.phms_line_group_query_safe(
    p_line_group_id,p_person_code,p_resource
  );

  select li.user_id into v_viewer_user_id
  from public.line_identities li
  where li.line_user_id=btrim(coalesce(p_line_user_id,''))
    and li.is_active=true
  order by li.updated_at desc nulls last
  limit 1;

  if v_viewer_user_id is null then
    return v_data;
  end if;

  select count(*),min(fp.id::text)::uuid
  into v_count,v_fp_id
  from public.family_persons fp
  join public.family_channel_family_links l
    on l.family_id=fp.family_id and l.status='active'
  join public.family_channels fc
    on fc.id=l.family_channel_id
   and fc.channel_type='line_group'
   and fc.external_channel_id=btrim(p_line_group_id)
   and fc.status='active'
  where lower(fp.id::text) like lower(btrim(p_person_code))||'%'
    and coalesce(fp.status,'active')='active';

  if v_count=1 then
    v_name:=private.family_person_label_for_viewer(v_viewer_user_id,v_fp_id);
    if nullif(btrim(coalesce(v_name,'')),'') is not null then
      v_data:=jsonb_set(v_data,'{person_name}',to_jsonb(v_name),true);
    end if;
  end if;

  return v_data;
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_group_reconfirm(p_line_user_id text, p_line_group_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth'
AS $function$
DECLARE v_actor uuid; v_fc public.family_channels%rowtype; v_reminder timestamptz;
BEGIN
 SELECT user_id INTO v_actor FROM public.line_identities
 WHERE line_user_id=p_line_user_id AND is_active=true AND onboarding_status='ready'
 ORDER BY updated_at DESC NULLS LAST,created_at DESC LIMIT 1;
 IF v_actor IS NULL THEN RAISE EXCEPTION 'line_identity_not_ready'; END IF;
 SELECT * INTO v_fc FROM public.family_channels
 WHERE channel_type='line_group' AND external_channel_id=btrim(p_line_group_id)
 FOR UPDATE;
 IF v_fc.id IS NULL OR v_fc.status<>'pending_link' OR v_fc.last_completed_at IS NULL
 THEN RAISE EXCEPTION 'group_reconfirmation_not_available'; END IF;
 IF NOT EXISTS(
   SELECT 1 FROM public.family_channel_family_links l
   WHERE l.family_channel_id=v_fc.id AND l.status='active'
     AND private.user_has_family_role(v_actor,l.family_id,array['owner','admin'])
 ) THEN RAISE EXCEPTION 'group_settings_permission_denied'; END IF;
 UPDATE public.family_channels SET
   status='active',setup_started_at=now(),setup_completed_at=null,
   setup_completed_by=null,ready_sent_at=null,can_query_bot=false,
   can_receive_notifications=false,updated_at=now() WHERE id=v_fc.id;
 v_reminder:=private.phms_schedule_line_group_setup_reminder(v_fc.id,v_actor);
 RETURN jsonb_build_object('ok',true,'group_name',coalesce(v_fc.channel_name,'LINE กลุ่ม'),
 'line_group_id',v_fc.external_channel_id,'reminder_at',v_reminder);
END $function$

CREATE OR REPLACE FUNCTION public.phms_line_group_request_permission_workspace(p_line_user_id text, p_family_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_actor uuid;
  v_family public.families%rowtype;
  v_code text:=lower(btrim(coalesce(p_family_code,'')));
  v_count integer;
  v_members jsonb;
begin
  select li.user_id into v_actor
  from public.line_identities li
  where li.line_user_id=p_line_user_id
    and li.is_active=true
    and li.onboarding_status='ready'
  order by li.updated_at desc nulls last,li.created_at desc
  limit 1;
  if v_actor is null then raise exception 'line_identity_not_ready'; end if;

  select count(*) into v_count
  from public.families f
  where coalesce(f.status,'active')='active'
    and (lower(f.id::text) like v_code||'%' or lower(coalesce(f.family_code,''))=v_code)
    and exists(
      select 1 from public.family_memberships fm
      where fm.family_id=f.id and fm.user_id=v_actor and fm.status='active'
    )
    and private.user_has_family_role(v_actor,f.id,array['owner','admin']);

  if v_count=0 then raise exception 'family_not_found_or_permission_denied'; end if;
  if v_count>1 then raise exception 'family_code_ambiguous'; end if;

  select * into v_family
  from public.families f
  where coalesce(f.status,'active')='active'
    and (lower(f.id::text) like v_code||'%' or lower(coalesce(f.family_code,''))=v_code)
    and exists(
      select 1 from public.family_memberships fm
      where fm.family_id=f.id and fm.user_id=v_actor and fm.status='active'
    )
    and private.user_has_family_role(v_actor,f.id,array['owner','admin'])
  limit 1;

  select coalesce(jsonb_agg(jsonb_build_object(
    'user_code',substr(fm.user_id::text,1,12),
    'display_name',private.family_user_label_for_viewer(v_actor,v_family.id,fm.user_id),
    'is_manager',private.user_has_family_role(fm.user_id,v_family.id,array['owner','admin']),
    'can_request',case
      when private.user_has_family_role(fm.user_id,v_family.id,array['owner','admin']) then true
      else coalesce((
        select p.can_request_link
        from public.family_line_group_request_permissions p
        where p.family_id=v_family.id and p.user_id=fm.user_id
      ),false)
    end
  ) order by private.family_user_label_for_viewer(v_actor,v_family.id,fm.user_id)),'[]'::jsonb)
  into v_members
  from public.family_memberships fm
  where fm.family_id=v_family.id and fm.status='active';

  return jsonb_build_object(
    'family_code',substr(v_family.id::text,1,12),
    'family_name',coalesce(nullif(btrim(v_family.family_name),''),'ครอบครัว'),
    'members',v_members
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_group_request_write_access(p_line_user_id text, p_line_group_id text, p_person_code text, p_resource text, p_action text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line public.line_identities%rowtype;
  v_fc public.family_channels%rowtype;
  v_fp public.family_persons%rowtype;
  v_resource text:=lower(btrim(coalesce(p_resource,'')));
  v_action text:=lower(btrim(coalesce(p_action,'')));
  v_count integer;
  v_existing uuid;
  v_id uuid;
  v_person_name text;
  v_family_name text;
begin
  if v_resource not in ('appointments','medications','health_data') then
    raise exception 'unsupported_group_write_resource';
  end if;
  if v_action not in ('create','update','delete') then
    raise exception 'unsupported_group_write_action';
  end if;

  select * into v_line
  from public.line_identities li
  where li.line_user_id=p_line_user_id
    and li.is_active=true
  order by li.updated_at desc nulls last,li.created_at desc
  limit 1;
  if not found then raise exception 'line_identity_not_found'; end if;
  if v_line.user_id is null then raise exception 'line_identity_not_linked'; end if;

  select * into v_fc
  from public.family_channels fc
  where fc.channel_type='line_group'
    and fc.external_channel_id=btrim(p_line_group_id)
    and fc.status in ('active','pending_link')
  limit 1;
  if v_fc.id is null then raise exception 'group_not_linked'; end if;

  select count(*),min(fp.id::text)::uuid
  into v_count,v_fp.id
  from public.family_persons fp
  where lower(fp.id::text) like lower(btrim(p_person_code))||'%'
    and coalesce(fp.status,'active')='active'
    and (
      exists(
        select 1 from public.family_channel_family_links l
        where l.family_channel_id=v_fc.id and l.family_id=fp.family_id and l.status='active'
      )
      or not exists(
        select 1 from public.family_channel_family_links l0
        where l0.family_channel_id=v_fc.id and l0.status='active'
      )
    )
    and exists(
      select 1 from public.family_memberships fm
      where fm.family_id=fp.family_id
        and fm.user_id=v_line.user_id
        and fm.status='active'
    );
  if v_count=0 then raise exception 'group_person_not_accessible'; end if;
  if v_count>1 then raise exception 'group_person_code_ambiguous'; end if;

  select * into v_fp
  from public.family_persons fp
  where lower(fp.id::text) like lower(btrim(p_person_code))||'%'
    and coalesce(fp.status,'active')='active'
    and (
      exists(
        select 1 from public.family_channel_family_links l
        where l.family_channel_id=v_fc.id and l.family_id=fp.family_id and l.status='active'
      )
      or not exists(
        select 1 from public.family_channel_family_links l0
        where l0.family_channel_id=v_fc.id and l0.status='active'
      )
    )
    and exists(
      select 1 from public.family_memberships fm
      where fm.family_id=fp.family_id
        and fm.user_id=v_line.user_id
        and fm.status='active'
    )
  limit 1;

  if private.user_can_access_family_person(
    v_line.user_id,v_fp.id,v_resource,v_action
  ) then
    return jsonb_build_object(
      'status','already_allowed',
      'already_pending',false,
      'person_code',substr(v_fp.id::text,1,12),
      'resource',v_resource,
      'action',v_action
    );
  end if;

  if not (
    private.user_can_see_family_person(v_line.user_id,v_fp.id)
    or exists(
      select 1 from public.family_channel_query_scopes qs
      where qs.family_channel_id=v_fc.id
        and qs.family_person_id=v_fp.id
        and qs.resource=v_resource
        and qs.enabled=true
        and v_fc.setup_completed_at is not null
        and coalesce(v_fc.can_query_bot,false)=true
    )
  ) then
    raise exception 'group_person_not_accessible';
  end if;

  select pr.id into v_existing
  from public.permission_requests pr
  where pr.family_id=v_fp.family_id
    and pr.requester_user_id=v_line.user_id
    and pr.family_person_id=v_fp.id
    and pr.status='pending'
    and pr.request_type='permission'
    and pr.resource=v_resource
    and pr.requested_action=v_action
  order by pr.created_at desc
  limit 1;

  if v_existing is null then
    perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
    v_id:=public.phms_request_access(
      v_fp.family_id,
      'permission',
      null,
      v_fp.id,
      v_resource,
      v_action,
      coalesce(
        nullif(btrim(p_reason),''),
        'ขอสิทธิ์จากรายการที่เริ่มใน LINE กลุ่ม '||
        coalesce(nullif(btrim(v_fc.channel_name),''),'LINE กลุ่ม')
      )
    );
  else
    v_id:=v_existing;
  end if;

  select coalesce(nullif(btrim(f.family_name),''),'ครอบครัว')
  into v_family_name
  from public.families f
  where f.id=v_fp.family_id;

  v_person_name:=case
    when private.user_can_see_family_person(v_line.user_id,v_fp.id)
      then private.family_person_label_for_viewer(v_line.user_id,v_fp.id)
    else private.family_person_central_label(v_fp.id)
  end;

  return jsonb_build_object(
    'status','pending',
    'already_pending',v_existing is not null,
    'request_id',v_id,
    'request_code',substr(v_id::text,1,12),
    'person_code',substr(v_fp.id::text,1,12),
    'person_name',coalesce(v_person_name,'บุคคลในครอบครัว'),
    'family_name',v_family_name,
    'resource',v_resource,
    'action',v_action
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_group_set_family_scope(p_line_user_id text, p_line_group_id text, p_family_code text, p_resource text, p_enabled boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_actor uuid;
  v_fc public.family_channels%rowtype;
  v_family_id uuid;
  v_count integer;
  v_resource text:=lower(btrim(coalesce(p_resource,'')));
  v_family_code text:=lower(btrim(coalesce(p_family_code,'')));
begin
  if v_resource not in ('appointments','medications','health_data')
    then raise exception 'invalid_group_query_resource'; end if;

  select li.user_id into v_actor
  from public.line_identities li
  where li.line_user_id=p_line_user_id
    and li.is_active=true
    and li.onboarding_status='ready'
  order by li.updated_at desc nulls last,li.created_at desc
  limit 1;
  if v_actor is null then raise exception 'line_identity_not_ready'; end if;

  select * into v_fc
  from public.family_channels
  where channel_type='line_group'
    and external_channel_id=btrim(p_line_group_id)
    and status='active'
  limit 1;
  if v_fc.id is null then raise exception 'group_not_linked'; end if;

  select count(*),min(l.family_id::text)::uuid
  into v_count,v_family_id
  from public.family_channel_family_links l
  join public.families f on f.id=l.family_id
  where l.family_channel_id=v_fc.id
    and l.status='active'
    and (
      lower(f.id::text) like v_family_code||'%'
      or lower(coalesce(f.family_code,''))=v_family_code
    );
  if v_count=0 then raise exception 'group_family_not_found'; end if;
  if v_count>1 then raise exception 'group_family_code_ambiguous'; end if;

  if not private.user_has_family_role(v_actor,v_family_id,array['owner','admin'])
    then raise exception 'group_settings_permission_denied'; end if;

  insert into public.family_channel_query_scopes(
    family_channel_id,family_person_id,resource,enabled,
    created_by,updated_by,created_at,updated_at
  )
  select
    v_fc.id,fp.id,v_resource,coalesce(p_enabled,true),
    v_actor,v_actor,now(),now()
  from public.family_persons fp
  join public.persons p on p.id=fp.person_id
  where fp.family_id=v_family_id
    and coalesce(fp.status,'active')='active'
    and fp.setup_status='ready'
    and coalesce(p.status,'active')='active'
  on conflict(family_channel_id,family_person_id,resource)
  do update set
    enabled=excluded.enabled,
    updated_by=v_actor,
    updated_at=now();

  insert into public.audit_logs(
    family_id,actor_user_id,event_type,resource,record_id,new_data,description
  )
  values(
    v_family_id,v_actor,'line_group_query_scope_bulk','family_channel',v_fc.id,
    jsonb_build_object(
      'query_resource',v_resource,
      'enabled',coalesce(p_enabled,true),
      'scope','family'
    ),
    case when coalesce(p_enabled,true)
      then 'เปิดข้อมูลแบบอ่านอย่างเดียวทั้งบ้านสำหรับ LINE กลุ่ม'
      else 'ปิดข้อมูลทั้งบ้านสำหรับ LINE กลุ่ม'
    end
  );

  return public.phms_line_group_settings(p_line_user_id,p_line_group_id);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_group_set_request_permission(p_line_user_id text, p_family_code text, p_user_code text, p_enabled boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_actor uuid;
  v_family public.families%rowtype;
  v_target uuid;
  v_code text:=lower(btrim(coalesce(p_family_code,'')));
  v_user_code text:=lower(btrim(coalesce(p_user_code,'')));
  v_count integer;
begin
  select li.user_id into v_actor
  from public.line_identities li
  where li.line_user_id=p_line_user_id
    and li.is_active=true
    and li.onboarding_status='ready'
  order by li.updated_at desc nulls last,li.created_at desc
  limit 1;
  if v_actor is null then raise exception 'line_identity_not_ready'; end if;

  select count(*) into v_count
  from public.families f
  where coalesce(f.status,'active')='active'
    and (lower(f.id::text) like v_code||'%' or lower(coalesce(f.family_code,''))=v_code)
    and private.user_has_family_role(v_actor,f.id,array['owner','admin']);
  if v_count=0 then raise exception 'family_not_found_or_permission_denied'; end if;
  if v_count>1 then raise exception 'family_code_ambiguous'; end if;

  select * into v_family
  from public.families f
  where coalesce(f.status,'active')='active'
    and (lower(f.id::text) like v_code||'%' or lower(coalesce(f.family_code,''))=v_code)
    and private.user_has_family_role(v_actor,f.id,array['owner','admin'])
  limit 1;

  select count(*),min(fm.user_id::text)::uuid into v_count,v_target
  from public.family_memberships fm
  where fm.family_id=v_family.id
    and fm.status='active'
    and lower(fm.user_id::text) like v_user_code||'%';
  if v_count=0 then raise exception 'family_member_not_found'; end if;
  if v_count>1 then raise exception 'family_member_code_ambiguous'; end if;

  if private.user_has_family_role(v_target,v_family.id,array['owner','admin']) then
    raise exception 'manager_request_permission_is_always_enabled';
  end if;

  insert into public.family_line_group_request_permissions(
    family_id,user_id,can_request_link,updated_by,created_at,updated_at
  ) values(
    v_family.id,v_target,coalesce(p_enabled,false),v_actor,now(),now()
  )
  on conflict(family_id,user_id)
  do update set
    can_request_link=excluded.can_request_link,
    updated_by=v_actor,
    updated_at=now();

  insert into public.audit_logs(
    family_id,actor_user_id,event_type,resource,new_data,description
  ) values(
    v_family.id,v_actor,'line_group_request_permission_changed',
    'family_line_group_request_permission',
    jsonb_build_object(
      'target_user_id',v_target,
      'can_request_link',coalesce(p_enabled,false)
    ),
    'เปลี่ยนสิทธิ์สมาชิกในการส่งคำขอเชื่อม LINE กลุ่ม'
  );

  return public.phms_line_group_request_permission_workspace(
    p_line_user_id,substr(v_family.id::text,1,12)
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_group_status(p_line_user_id text, p_line_group_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_actor uuid;
  v_fc public.family_channels%rowtype;
  v_families jsonb;
  v_count integer:=0;
begin
  select li.user_id into v_actor
  from public.line_identities li
  where li.line_user_id=p_line_user_id and li.is_active=true and li.onboarding_status='ready'
  order by li.updated_at desc nulls last,li.created_at desc limit 1;
  if v_actor is null then raise exception 'line_identity_not_ready'; end if;

  select * into v_fc
  from public.family_channels fc
  where fc.channel_type='line_group' and fc.external_channel_id=p_line_group_id
  limit 1;

  if v_fc.id is null then return jsonb_build_object('linked',false); end if;

  select count(*)::int,
         coalesce(jsonb_agg(jsonb_build_object(
           'family_id',f.id,
           'family_code',substr(f.id::text,1,12),
           'family_name',coalesce(nullif(btrim(f.family_name),''),'ครอบครัว'),
           'can_manage',private.user_has_family_role(v_actor,f.id,array['owner','admin'])
         ) order by coalesce(f.family_name,'')),'[]'::jsonb)
  into v_count,v_families
  from public.family_channel_family_links l
  join public.families f on f.id=l.family_id
  join public.family_memberships fm
    on fm.family_id=f.id and fm.user_id=v_actor and fm.status='active'
  where l.family_channel_id=v_fc.id and l.status='active';

  if v_count=0 and exists(
    select 1 from public.family_channel_family_links l
    where l.family_channel_id=v_fc.id and l.status='active'
  ) then
    raise exception 'family_access_denied';
  end if;

  return jsonb_build_object(
    'linked',exists(
      select 1 from public.family_channel_family_links l
      where l.family_channel_id=v_fc.id and l.status='active'
    ) and v_fc.status='active' and v_fc.setup_completed_at is not null,
    'status',v_fc.status,
    'setup_completed',v_fc.status='active' and v_fc.setup_completed_at is not null,
    'family_id',v_fc.family_id,
    'family_name',case when v_count=1 then v_families->0->>'family_name' when v_count>1 then 'หลายครอบครัว' else null end,
    'linked_families',coalesce(v_families,'[]'::jsonb),
    'channel_name',v_fc.channel_name,
    'channel_code',substr(v_fc.id::text,1,12),
    'read_only',true
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_group_toggle_query_scope(p_line_user_id text, p_line_group_id text, p_person_code text, p_resource text, p_enabled boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_actor uuid;
  v_fc public.family_channels%rowtype;
  v_fp_id uuid;
  v_family_id uuid;
  v_count integer;
  v_resource text:=lower(btrim(coalesce(p_resource,'')));
begin
  if v_resource not in ('appointments','medications','health_data')
    then raise exception 'invalid_group_query_resource'; end if;

  select li.user_id into v_actor
  from public.line_identities li
  where li.line_user_id=p_line_user_id and li.is_active=true and li.onboarding_status='ready'
  order by li.updated_at desc nulls last,li.created_at desc limit 1;
  if v_actor is null then raise exception 'line_identity_not_ready'; end if;

  select * into v_fc
  from public.family_channels
  where channel_type='line_group'
    and external_channel_id=btrim(p_line_group_id)
    and status='active'
  limit 1;
  if v_fc.id is null then raise exception 'group_not_linked'; end if;

  select count(*),min(fp.id::text)::uuid,min(fp.family_id::text)::uuid
  into v_count,v_fp_id,v_family_id
  from public.family_persons fp
  join public.persons p on p.id=fp.person_id
  where coalesce(fp.status,'active')='active'
    and fp.setup_status='ready'
    and coalesce(p.status,'active')='active'
    and lower(fp.id::text) like lower(btrim(p_person_code))||'%'
    and exists(
      select 1 from public.family_channel_family_links l
      where l.family_channel_id=v_fc.id
        and l.family_id=fp.family_id
        and l.status='active'
    );
  if v_count=0 then raise exception 'group_person_not_found'; end if;
  if v_count>1 then raise exception 'group_person_code_ambiguous'; end if;

  if not private.user_has_family_role(v_actor,v_family_id,array['owner','admin'])
    then raise exception 'group_settings_permission_denied'; end if;

  insert into public.family_channel_query_scopes(
    family_channel_id,family_person_id,resource,enabled,created_by,updated_by,created_at,updated_at
  ) values(v_fc.id,v_fp_id,v_resource,coalesce(p_enabled,true),v_actor,v_actor,now(),now())
  on conflict(family_channel_id,family_person_id,resource)
  do update set enabled=excluded.enabled,updated_by=v_actor,updated_at=now();

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,new_data,description
  )
  values(
    v_family_id,v_actor,v_fp_id,'line_group_query_scope','family_channel',v_fc.id,
    jsonb_build_object(
      'query_resource',v_resource,
      'enabled',coalesce(p_enabled,true),
      'access_mode','read_only'
    ),
    'เปลี่ยนขอบเขตข้อมูลที่ LINE กลุ่มดู/ถามได้'
  );

  return public.phms_line_group_settings(p_line_user_id,p_line_group_id);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_has_accessible_other_person(p_line_user_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare v_line record;v_visible boolean:=false;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 if v_line.user_id is null then return false;end if;
 select exists(
 select 1 from public.family_memberships fm
 join public.family_persons fp on fp.family_id=fm.family_id
 join public.persons p on p.id=fp.person_id
 where fm.user_id=v_line.user_id and fm.status='active' and fp.status='active'
 and p.linked_user_id is distinct from v_line.user_id
 and private.user_can_access_family_person(v_line.user_id,fp.id,'persons','view')
 ) into v_visible;
 return coalesce(v_visible,false);
end $function$

CREATE OR REPLACE FUNCTION public.phms_line_health_task_accept(p_line_user_id text, p_task_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare v_line record;v_task public.health_care_tasks%rowtype;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 select * into v_task from public.health_care_tasks
 where assigned_to_user_id=v_line.user_id
   and replace(id::text,'-','') like lower(btrim(p_task_code))||'%'
   and status='pending'
 order by created_at desc limit 1 for update;
 if not found then raise exception 'health_task_not_found'; end if;
 if v_task.expires_at is not null and v_task.expires_at<=now() then
   update public.health_care_tasks set status='expired',updated_at=now() where id=v_task.id;
   raise exception 'health_task_expired';
 end if;
 update public.health_care_tasks
 set status='accepted',accepted_at=now(),updated_at=now()
 where id=v_task.id;
 return jsonb_build_object('ok',true,'task_code',substr(replace(v_task.id::text,'-',''),1,12),'status','accepted');
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_line_health_task_cancel(p_line_user_id text, p_task_code text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare v_line record;v_task public.health_care_tasks%rowtype;v_code text;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
 select * into v_task from public.health_care_tasks
 where replace(id::text,'-','') like lower(btrim(p_task_code))||'%'
   and status in ('pending','accepted','in_progress')
 order by created_at desc limit 1 for update;
 if not found then raise exception 'health_task_not_found'; end if;
 if not (
  v_task.assigned_by_user_id=v_line.user_id
  or private.phms_can_manage_medical_grants(v_line.user_id,v_task.family_person_id)
 ) then raise exception 'health_task_cancel_denied'; end if;
 update public.health_care_tasks
 set status='cancelled',completion_note=nullif(btrim(coalesce(p_note,'')),''),
     cancelled_at=now(),updated_at=now() where id=v_task.id;
 v_code:=substr(replace(v_task.id::text,'-',''),1,12);
 return jsonb_build_object('ok',true,'task_code',v_code,'status','cancelled');
end;
$function$

