CREATE OR REPLACE FUNCTION public.phms_line_healthcare_master_update_org(p_line_user_id text, p_org_code text, p_field text, p_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_id uuid;
  v_value text:=nullif(btrim(coalesce(p_value,'')),'');
  v_org public.healthcare_organizations%rowtype;
begin
  select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
  if v_line.user_id is null then raise exception 'line_identity_not_linked'; end if;
  if not private.phms_line_can_manage_healthcare_master(p_line_user_id) then
    raise exception 'healthcare_master_manage_required';
  end if;

  select o.id into v_id
  from public.healthcare_organizations o
  where o.deleted_at is null
    and replace(o.id::text,'-','') like replace(lower(btrim(p_org_code)),'-','')||'%'
  order by o.updated_at desc
  limit 1;

  if v_id is null then raise exception 'healthcare_org_not_found'; end if;
  if p_field not in ('name','branch_name','external_code','address_text','phone','email','website_url') then
    raise exception 'healthcare_master_field_not_allowed';
  end if;
  if p_field='email' and v_value is not null
     and v_value !~* '^[A-Z0-9._%+-]+@[A-Z0-9.-]+[.][A-Z]{2,}$' then
    raise exception 'invalid_email';
  end if;

  update public.healthcare_organizations
  set name=case when p_field='name' then coalesce(v_value,name) else name end,
      branch_name=case when p_field='branch_name' then v_value else branch_name end,
      external_code=case when p_field='external_code' then v_value else external_code end,
      address_text=case when p_field='address_text' then v_value else address_text end,
      phone=case when p_field='phone' then v_value else phone end,
      email=case when p_field='email' then lower(v_value) else email end,
      website_url=case when p_field='website_url' then v_value else website_url end,
      source='line_master_edit',
      is_verified=true,
      verified_at=now(),
      verified_by=v_line.user_id,
      updated_at=now()
  where id=v_id
  returning * into v_org;

  insert into private.healthcare_directory_aliases(
    entity_type,organization_id,alias,normalized_alias,source,confidence
  )
  select 'organization',v_org.id,x.alias,private.phms_normalize_directory_alias(x.alias),'line_master_edit','high'
  from (values(v_org.name),(v_org.external_code)) x(alias)
  where nullif(btrim(coalesce(x.alias,'')),'') is not null
  on conflict (entity_type,organization_id,normalized_alias)
  do update set alias=excluded.alias,source=excluded.source,confidence='high',is_active=true,updated_at=now();

  return jsonb_strip_nulls(jsonb_build_object(
    'ok',true,'record_code',substr(v_org.id::text,1,12),
    'name',v_org.name,'external_code',v_org.external_code,
    'field',p_field,'value',v_value
  ));
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_healthcare_master_update_unit(p_line_user_id text, p_unit_code text, p_field text, p_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_id uuid;
  v_value text:=nullif(btrim(coalesce(p_value,'')),'');
  v_minutes integer;
  v_unit public.healthcare_service_units%rowtype;
begin
  select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
  if v_line.user_id is null then raise exception 'line_identity_not_linked'; end if;
  if not private.phms_line_can_manage_healthcare_master(p_line_user_id) then
    raise exception 'healthcare_master_manage_required';
  end if;

  select u.id into v_id
  from public.healthcare_service_units u
  where u.deleted_at is null
    and replace(u.id::text,'-','') like replace(lower(btrim(p_unit_code)),'-','')||'%'
  order by u.updated_at desc
  limit 2;

  if v_id is null then raise exception 'service_unit_not_found'; end if;

  if p_field not in (
    'name','code','location_detail','building_name','floor_label','contact_point',
    'phone','email','contact_note',
    'reschedule_contact_phone','reschedule_contact_email',
    'reschedule_hours_text','reschedule_instructions','reschedule_min_notice_minutes'
  ) then
    raise exception 'healthcare_master_field_not_allowed';
  end if;

  if p_field in ('email','reschedule_contact_email')
     and v_value is not null
     and v_value !~* '^[A-Z0-9._%+-]+@[A-Z0-9.-]+[.][A-Z]{2,}$' then
    raise exception 'invalid_email';
  end if;

  if p_field='reschedule_min_notice_minutes' then
    if v_value is null then
      v_minutes:=null;
    elsif v_value ~ '^[0-9]+$' then
      v_minutes:=v_value::integer;
      if v_minutes>100800 then raise exception 'notice_minutes_out_of_range'; end if;
    else
      raise exception 'invalid_notice_minutes';
    end if;
  end if;

  update public.healthcare_service_units
  set name=case when p_field='name' then coalesce(v_value,name) else name end,
      code=case when p_field='code' then v_value else code end,
      location_detail=case when p_field='location_detail' then v_value else location_detail end,
      building_name=case when p_field='building_name' then v_value else building_name end,
      floor_label=case when p_field='floor_label' then v_value else floor_label end,
      contact_point=case when p_field='contact_point' then v_value else contact_point end,
      phone=case when p_field='phone' then v_value else phone end,
      email=case when p_field='email' then lower(v_value) else email end,
      contact_note=case when p_field='contact_note' then v_value else contact_note end,
      reschedule_contact_phone=case when p_field='reschedule_contact_phone' then v_value else reschedule_contact_phone end,
      reschedule_contact_email=case when p_field='reschedule_contact_email' then lower(v_value) else reschedule_contact_email end,
      reschedule_hours_text=case when p_field='reschedule_hours_text' then v_value else reschedule_hours_text end,
      reschedule_instructions=case when p_field='reschedule_instructions' then v_value else reschedule_instructions end,
      reschedule_min_notice_minutes=case when p_field='reschedule_min_notice_minutes' then v_minutes else reschedule_min_notice_minutes end,
      source='line_master_edit',
      is_verified=true,
      verified_at=now(),
      verified_by=v_line.user_id,
      updated_at=now()
  where id=v_id
  returning * into v_unit;

  if p_field in ('name','code') then
    insert into private.healthcare_directory_aliases(
      entity_type,organization_id,service_unit_id,alias,normalized_alias,source,confidence
    )
    select 'service_unit',v_unit.organization_id,v_unit.id,x.alias,
           private.phms_normalize_directory_alias(x.alias),'line_master_edit','high'
    from (values(v_unit.name),(v_unit.code)) x(alias)
    where nullif(btrim(coalesce(x.alias,'')),'') is not null
    on conflict (entity_type,organization_id,normalized_alias)
    do update set service_unit_id=excluded.service_unit_id,alias=excluded.alias,
                  source=excluded.source,confidence='high',is_active=true,updated_at=now();
  end if;

  return jsonb_strip_nulls(jsonb_build_object(
    'ok',true,
    'record_code',substr(v_unit.id::text,1,12),
    'name',v_unit.name,
    'code',v_unit.code,
    'field',p_field,
    'value',case when p_field='reschedule_min_notice_minutes'
                 then v_unit.reschedule_min_notice_minutes::text else v_value end
  ));
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_hospital_expenses_page(p_line_user_id text, p_hospital_name text, p_offset integer DEFAULT 0, p_page_size integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare v_line record;v_prep record;v_person_id uuid;v_total integer;v_items jsonb;
begin
select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
select * into v_prep from public.phms_prepare_line_main_command(p_line_user_id,'appointments');
if v_prep.flow_state<>'ready' then raise exception 'appointment_context_not_ready'; end if;
if v_prep.active_scope='family' and v_prep.active_family_person_id is not null then
select fp.person_id into v_person_id from public.family_persons fp where fp.id=v_prep.active_family_person_id and fp.status='active';
else
select p.id into v_person_id from public.persons p where p.linked_user_id=v_line.user_id and coalesce(p.status,'active')='active' order by p.created_at limit 1;
end if;
if v_person_id is null then raise exception 'person_not_found';end if;
select count(*) into v_total from public.healthcare_expenses e join public.appointments a on a.id=e.appointment_id and a.deleted_at is null
where e.person_id=v_person_id and e.deleted_at is null and e.paid_amount is not null
and coalesce(nullif(btrim(a.hospital_name),''),'ไม่ระบุสถานพยาบาล')=p_hospital_name
and private.phms_user_can_view_appointment_finance(v_line.user_id,e.appointment_id);
select coalesce(jsonb_agg(jsonb_build_object('record_code',record_code,'expense_date',expense_date,'paid_amount',paid_amount,'coverage_type',coverage_type,'department',department) order by expense_date desc,created_at desc),'[]'::jsonb)
into v_items from (select substr(a.id::text,1,12) record_code,e.expense_date,e.paid_amount,e.coverage_type,a.department,e.created_at
from public.healthcare_expenses e join public.appointments a on a.id=e.appointment_id and a.deleted_at is null
where e.person_id=v_person_id and e.deleted_at is null and e.paid_amount is not null
and coalesce(nullif(btrim(a.hospital_name),''),'ไม่ระบุสถานพยาบาล')=p_hospital_name
and private.phms_user_can_view_appointment_finance(v_line.user_id,e.appointment_id)
order by e.expense_date desc,e.created_at desc limit least(greatest(p_page_size,1),8) offset greatest(p_offset,0)) rows;
return jsonb_build_object('total_count',v_total,'items',v_items,'person_name',v_prep.target_person_name);
end $function$

CREATE OR REPLACE FUNCTION public.phms_line_household_admin_resign(p_line_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare a record;v_id uuid;v_owner uuid;v_family_id uuid;
begin
 select * into a from private.resolve_line_user_for_service(p_line_user_id);
 select x.active_family_id into v_family_id
 from private.line_identity_contexts x
 where x.line_identity_id=a.line_identity_id and x.active_scope='family'
 limit 1;
 if v_family_id is null or not exists(select 1 from public.family_memberships fm
 where fm.family_id=v_family_id and fm.user_id=a.user_id and fm.status='active') 
 then raise exception 'family_not_selected';end if;
 if not private.user_has_family_role(a.user_id,v_family_id,array['admin']) then raise exception 'not_family_admin';end if;
 if private.user_has_family_role(a.user_id,v_family_id,array['owner']) then raise exception 'owner_cannot_resign_as_admin';end if;
 insert into private.household_admin_resignation_requests(family_id,admin_user_id)
 values(v_family_id,a.user_id) returning id into v_id;
 select user_id into v_owner from public.family_role_assignments where family_id=v_family_id and role='owner' and status='active' limit 1;
 if v_owner is not null then
  insert into public.notifications(family_id,recipient_user_id,event_type,title,message,channel,priority,status,payload,dedupe_key)
  values(v_family_id,v_owner,'admin_resignation_requested','📥 แอดมินขอลาออกจากหน้าที่',
  'แอดมินบ้านขอกลับเป็นสมาชิกบ้าน กรุณาเปิดอิ่มอุ่น แล้วพิมพ์ “คำขอบ้าน” เพื่อพิจารณา',
  'line','normal','pending',jsonb_build_object('request_code',substr(v_id::text,1,12)),'admin_resign_'||v_id::text);
 end if;
 insert into public.audit_logs(family_id,actor_user_id,event_type,resource,new_data,description)
 values(v_family_id,a.user_id,'admin_resignation_requested','family_membership',jsonb_build_object('request_id',v_id),'Admin requested to return to regular household member');
 return jsonb_build_object('ok',true,'status','pending','request_code',substr(v_id::text,1,12));
end;$function$

CREATE OR REPLACE FUNCTION public.phms_line_household_admin_resign_review(p_line_user_id text, p_request_code text, p_approve boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare a record;v private.household_admin_resignation_requests%rowtype;
begin
 select * into a from private.resolve_line_user_for_service(p_line_user_id);
 select * into v from private.household_admin_resignation_requests
 where id::text like lower(btrim(p_request_code))||'%' and status='pending'
 order by created_at desc limit 1 for update;
 if not found then raise exception 'admin_resignation_request_not_found';end if;
 if not private.user_has_family_role(a.user_id,v.family_id,array['owner']) then raise exception 'owner_only';end if;
 if coalesce(p_approve,false) then
  update public.family_role_assignments set status='inactive',updated_at=now()
  where family_id=v.family_id and user_id=v.admin_user_id and role='admin' and status='active';
 end if;
 update private.household_admin_resignation_requests
 set status=case when p_approve then 'approved' else 'rejected' end,decided_at=now(),decided_by=a.user_id where id=v.id;
 insert into public.notifications(family_id,recipient_user_id,event_type,title,message,channel,priority,status,payload,dedupe_key)
 values(v.family_id,v.admin_user_id,'admin_resignation_reviewed',case when p_approve then '✅ กลับเป็นสมาชิกบ้านแล้ว' else 'คำขอลาออกจากแอดมินยังไม่อนุมัติ' end,
 case when p_approve then 'เจ้าบ้านอนุมัติแล้ว ตอนนี้คุณเป็นสมาชิกบ้านตามปกติ' else 'เจ้าบ้านยังไม่ได้อนุมัติคำขอ กรุณาพูดคุยกันก่อน' end,
 'line','normal','pending',jsonb_build_object('request_code',substr(v.id::text,1,12)),'admin_resign_review_'||v.id::text);
 return jsonb_build_object('ok',true,'status',case when p_approve then 'approved' else 'rejected' end);
end;$function$

CREATE OR REPLACE FUNCTION public.phms_line_household_owner_decide(p_line_user_id text, p_request_code text, p_accept boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare a record;v private.household_owner_transfer_requests%rowtype;v_owner uuid;v_accept boolean:=coalesce(p_accept,false);
begin
 select * into a from private.resolve_line_user_for_service(p_line_user_id);
 perform set_config('request.jwt.claim.sub',a.user_id::text,true);
 select * into v from private.household_owner_transfer_requests where status='pending' and proposed_owner_user_id=a.user_id
  and id::text like lower(btrim(p_request_code))||'%' order by created_at desc limit 1 for update;
 if not found then raise exception 'household_transfer_request_not_found';end if;
 if not exists(select 1 from public.family_memberships fm where fm.family_id=v.family_id and fm.user_id=a.user_id and fm.status='active') then raise exception 'target_not_active';end if;
 if not private.user_has_family_role(v.current_owner_user_id,v.family_id,array['owner']) then raise exception 'ownership_changed';end if;
 if v_accept then
   update public.family_role_assignments set status='inactive',updated_at=now()
   where family_id=v.family_id and status='active' and
    ((user_id=v.current_owner_user_id and role='owner') or (user_id=v.proposed_owner_user_id and role='admin'));
   insert into public.family_role_assignments(family_id,user_id,role,status,granted_by)
   values(v.family_id,v.proposed_owner_user_id,'owner','active',v.current_owner_user_id)
   on conflict do nothing;
   if v.previous_owner_role='admin' then
     insert into public.family_role_assignments(family_id,user_id,role,status,granted_by)
     values(v.family_id,v.current_owner_user_id,'admin','active',v.proposed_owner_user_id)
     on conflict do nothing;
   end if;
 end if;
 update private.household_owner_transfer_requests set status=case when v_accept then 'accepted' else 'rejected' end,
  decided_at=now(),decided_by=a.user_id where id=v.id;
 insert into public.notifications(family_id,recipient_user_id,event_type,title,message,channel,priority,status,payload,dedupe_key)
 values(v.family_id,v.current_owner_user_id,case when v_accept then 'owner_transfer_accepted' else 'owner_transfer_rejected' end,
 case when v_accept then '✅ เปลี่ยนเจ้าบ้านสำเร็จ' else 'ยังไม่ได้เปลี่ยนเจ้าบ้าน' end,
 case when v_accept then 'คนที่คุณเชิญตอบรับเป็นเจ้าบ้านแล้ว' else 'คนที่คุณเชิญยังไม่สะดวกรับหน้าที่เจ้าบ้าน' end,
 'line','normal','pending',jsonb_build_object('request_code',substr(v.id::text,1,12)),
 'owner_transfer_decision_'||v.id::text);
 insert into public.audit_logs(family_id,actor_user_id,target_user_id,event_type,resource,new_data,description)
 values(v.family_id,a.user_id,v.current_owner_user_id,
 case when v_accept then 'owner_transferred' else 'owner_transfer_declined' end,
 'family_ownership',jsonb_build_object('request_id',v.id,'accepted',v_accept,'former_owner_role',v.previous_owner_role),'Owner transfer recipient decision');
 return jsonb_build_object('ok',true,'status',case when v_accept then 'accepted' else 'rejected' end);
end;$function$

