CREATE OR REPLACE FUNCTION public.phms_line_label_storage_asset(p_line_user_id text, p_asset_id uuid, p_title text, p_file_role text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_ctx private.line_identity_contexts%rowtype;
  v_asset public.phms_storage_assets%rowtype;
  v_fp uuid;
  v_role text:=lower(nullif(btrim(coalesce(p_file_role,'')),''));
  v_title text:=nullif(btrim(coalesce(p_title,'')),'');
  v_perm text;
  v_allowed boolean:=false;
begin
  if v_title is null then raise exception 'asset_title_required'; end if;
  if v_role is not null and v_role not in ('appointment_source','appointment_attachment','medication','health','document') then
    raise exception 'invalid_asset_file_role';
  end if;

  select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
  perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
  select * into v_ctx from private.line_identity_contexts where line_identity_id=v_line.line_identity_id;

  select * into v_asset from public.phms_storage_assets
  where id=p_asset_id and deleted_at is null;
  if not found then raise exception 'storage_asset_not_found'; end if;

  v_perm:=case
    when v_role in ('appointment_source','appointment_attachment') then 'appointments'
    when v_role='medication' then 'medications'
    else 'health_data' end;

  if v_asset.created_by=v_line.user_id then
    v_allowed:=true;
  elsif v_ctx.active_scope='family' and v_ctx.active_family_id is not null then
    select fp.id into v_fp
    from public.family_persons fp
    where fp.family_id=v_ctx.active_family_id and fp.person_id=v_asset.person_id
      and coalesce(fp.status,'active')='active'
    limit 1;
    if v_fp is not null then
      perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
      v_allowed:=private.can_access_family_person(v_fp,v_perm,'update')
                 or private.can_access_family_person(v_fp,v_perm,'create');
    end if;
  else
    v_allowed:=exists(
      select 1 from public.persons p
      where p.id=v_asset.person_id and p.linked_user_id=v_line.user_id and coalesce(p.status,'active')='active'
    );
  end if;

  if not v_allowed then raise exception 'storage_asset_label_permission_denied'; end if;

  update public.phms_storage_assets
  set permission_resource=case
        when v_perm='health_data' then 'health'
        else v_perm
      end,
      metadata=coalesce(metadata,'{}'::jsonb)
        || jsonb_strip_nulls(jsonb_build_object(
          'display_title',v_title,
          'file_role',v_role,
          'appointment_file_role',case when v_role in ('appointment_source','appointment_attachment') then v_role else null end,
          'labeled_by',v_line.user_id,
          'labeled_at',now()
        )),
      updated_at=now()
  where id=p_asset_id;

  return jsonb_build_object('ok',true,'asset_id',p_asset_id,'title',v_title,'file_role',v_role);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_link_intake_source_to_appointment(p_line_user_id text, p_source_code text, p_record_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_source public.data_intake_sources%rowtype;
  v_ref record;
  v_count int;
  v_link_id uuid;
begin
  select * into v_line
  from private.resolve_line_user_for_service(p_line_user_id);

  select count(*) into v_count
  from public.data_intake_sources s
  where s.submitted_by=v_line.user_id
    and lower(s.id::text) like lower(btrim(p_source_code))||'%';

  if v_count=0 then
    return jsonb_build_object('ok',true,'linked',false,'reason','source_not_found');
  end if;
  if v_count>1 then raise exception 'intake_source_code_ambiguous'; end if;

  select * into v_source
  from public.data_intake_sources s
  where s.submitted_by=v_line.user_id
    and lower(s.id::text) like lower(btrim(p_source_code))||'%'
  limit 1;

  if v_source.storage_asset_id is null then
    return jsonb_build_object('ok',true,'linked',false,'reason','source_has_no_asset');
  end if;

  select * into v_ref
  from private.phms_find_crud_record(
    p_line_user_id,'appointment',p_record_code,'update'
  )
  limit 1;

  select adl.id into v_link_id
  from public.appointment_document_links adl
  where adl.appointment_id=v_ref.record_id
    and adl.storage_asset_id=v_source.storage_asset_id
  limit 1;

  if v_link_id is null then
    insert into public.appointment_document_links(
      appointment_id,storage_asset_id,link_kind,note,created_by,created_at
    )
    values(
      v_ref.record_id,v_source.storage_asset_id,'source',
      'ใบนัด/ไฟล์ต้นทางที่ใช้สร้างนัด',v_ref.actor_user_id,now()
    )
    returning id into v_link_id;
  end if;

  return jsonb_build_object(
    'ok',true,'linked',true,'link_id',v_link_id,
    'storage_asset_id',v_source.storage_asset_id,
    'appointment_code',substr(v_ref.record_id::text,1,12)
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_medical_finish_my_job(p_line_user_id text, p_job_code text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare v_line record;v_ass public.appointment_assignees%rowtype;v_appt public.appointments%rowtype;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 select aa.* into v_ass from public.appointment_assignees aa
 where aa.user_id=v_line.user_id
   and aa.status in ('assigned','accepted')
   and aa.assignment_role in ('driver','companion','booker','responsible','other','documents')
   and aa.id::text like lower(btrim(p_job_code))||'%'
 order by aa.created_at desc limit 1 for update;
 if not found then raise exception 'assigned_job_not_found';end if;
 select * into v_appt from public.appointments a where a.id=v_ass.appointment_id and a.deleted_at is null;
 if not found then raise exception 'appointment_not_found';end if;
 if not exists(select 1 from public.family_memberships fm where fm.family_id=v_appt.family_id and fm.user_id=v_line.user_id and fm.status='active')
 then raise exception 'not_family_member';end if;
 if v_appt.appointment_at+interval '1 day'<now() or v_appt.status not in ('scheduled','confirmed')
 then raise exception 'job_expired';end if;
 insert into private.medical_oneoff_job_completions(assignment_id,completed_by,completion_note)
 values(v_ass.id,v_line.user_id,left(nullif(btrim(p_note),''),400))
 on conflict(assignment_id) do nothing;
 insert into public.audit_logs(family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,record_id,new_data,description)
 values(v_appt.family_id,v_line.user_id,v_ass.assigned_by,v_appt.family_person_id,
 'medical_oneoff_job_completed','appointment',v_appt.id,
 jsonb_build_object('job_id',v_ass.id,'job_type',v_ass.assignment_role),
 'Assignee finished one-off appointment duty');
 if v_ass.assigned_by is not null and v_ass.assigned_by<>v_line.user_id then
  insert into public.notifications(family_id,recipient_user_id,person_id,family_person_id,event_type,title,message,related_record_id,
  channel,priority,status,payload,dedupe_key)
  values(v_appt.family_id,v_ass.assigned_by,v_appt.person_id,v_appt.family_person_id,
  'medical_oneoff_job_completed','✅ งานที่ฝากช่วยเสร็จแล้ว',
  private.family_user_label_for_viewer(v_ass.assigned_by,v_appt.family_id,v_line.user_id)||' ทำงานที่ได้รับมอบหมายเรียบร้อยแล้ว',
  v_appt.id,'line','normal','pending',jsonb_build_object('job_id',v_ass.id),
  'medical_oneoff_job_done_'||v_ass.id::text);
 end if;
 return jsonb_build_object('ok',true,'job_code',substr(v_ass.id::text,1,12),'status','completed');
end;$function$

CREATE OR REPLACE FUNCTION public.phms_line_medical_primary_accept(p_line_user_id text, p_request_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_line record;v_req private.medical_primary_transfer_requests%rowtype;
 v_old private.medical_primary_responsibilities%rowtype;v_linked_user uuid;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
 select * into v_req from private.medical_primary_transfer_requests
  where proposed_user_id=v_line.user_id and status='pending'
    and id::text like lower(btrim(p_request_code))||'%'
  order by created_at desc limit 1 for update;
 if not found then raise exception 'medical_primary_request_not_found';end if;
 if not exists(select 1 from public.family_memberships fm
               where fm.family_id=v_req.family_id and fm.user_id=v_line.user_id and fm.status='active')
 then raise exception 'not_active_member';end if;

 select * into v_old from private.medical_primary_responsibilities
  where family_person_id=v_req.family_person_id for update;
 select p.linked_user_id into v_linked_user
 from public.family_persons fp join public.persons p on p.id=fp.person_id
 where fp.id=v_req.family_person_id;

 if v_old.state='active' and v_old.primary_user_id is distinct from v_line.user_id
    and v_old.primary_user_id is distinct from v_linked_user then
   if v_req.keep_old_access then
     insert into public.person_caregiver_assignments(
      family_id,family_person_id,caregiver_user_id,is_primary,
      can_edit_profile,can_manage_medications,can_manage_appointments,can_manage_health,can_manage_emergency,
      can_receive_notifications,status,assigned_by,assigned_at,created_at,updated_at
     ) values(
      v_req.family_id,v_req.family_person_id,v_old.primary_user_id,false,
      true,true,true,true,false,true,'active',v_line.user_id,now(),now(),now()
     )
     on conflict(family_person_id,caregiver_user_id) do update set
      status='active',is_primary=false,can_edit_profile=true,can_manage_medications=true,
      can_manage_appointments=true,can_manage_health=true,can_manage_emergency=false,
      can_receive_notifications=true,updated_at=now();
   else
     update public.person_caregiver_assignments
       set status='inactive',is_primary=false,updated_at=now()
       where family_person_id=v_req.family_person_id and caregiver_user_id=v_old.primary_user_id;
     update public.person_permissions
       set can_view=false,can_create=false,can_update=false,can_delete=false,can_receive_notifications=false,
           can_approve=false,can_manage_stock=false,can_manage_medication=false,updated_at=now()
       where family_person_id=v_req.family_person_id and user_id=v_old.primary_user_id;
   end if;
 end if;

 -- Primary is a separate role, not an assistant.
 update public.person_caregiver_assignments
  set status='inactive',is_primary=false,updated_at=now()
  where family_person_id=v_req.family_person_id and caregiver_user_id=v_line.user_id;

 insert into private.medical_primary_responsibilities(
  family_person_id,family_id,primary_user_id,state,authority_basis,assigned_by,assigned_at
 ) values(
  v_req.family_person_id,v_req.family_id,v_line.user_id,'active',
  case when v_linked_user=v_line.user_id then 'linked_person_self' else 'accepted_delegation' end,
  v_req.requested_by,now()
 )
 on conflict(family_person_id) do update set
  primary_user_id=excluded.primary_user_id,state='active',authority_basis=excluded.authority_basis,
  assigned_by=excluded.assigned_by,assigned_at=now(),updated_at=now();

 update private.medical_primary_transfer_requests
  set status='accepted',decided_at=now(),decided_by=v_line.user_id where id=v_req.id;

 insert into public.audit_logs(
  family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,new_data,description
 ) values(
  v_req.family_id,v_line.user_id,v_line.user_id,v_req.family_person_id,
  'medical_primary_accepted','medical_access',
  jsonb_build_object('request_id',v_req.id,'previous_primary',v_old.primary_user_id,
                     'retain_old_access',v_req.keep_old_access),
  'Accepted primary health caregiver responsibility'
 );

 return jsonb_build_object('ok',true,'status','active','role','primary_caregiver',
   'family_person_id',v_req.family_person_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_line_medical_primary_decline(p_line_user_id text, p_request_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare v_line record;v_req private.medical_primary_transfer_requests%rowtype;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 select * into v_req from private.medical_primary_transfer_requests
 where proposed_user_id=v_line.user_id and status='pending' and id::text like lower(btrim(p_request_code))||'%'
 order by created_at desc limit 1 for update;
 if not found then raise exception 'primary_request_not_found'; end if;
 update private.medical_primary_transfer_requests set status='rejected',decided_at=now(),decided_by=v_line.user_id where id=v_req.id;
 insert into public.audit_logs(family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,new_data,description)
 values(v_req.family_id,v_line.user_id,v_line.user_id,v_req.family_person_id,'medical_primary_declined','medical_access',
 jsonb_build_object('request_id',v_req.id),'Declined primary health-data caregiver responsibility');
 if v_req.requested_by is distinct from v_line.user_id then
  insert into public.notifications(family_id,recipient_user_id,event_type,title,message,channel,priority,status,family_person_id,payload,dedupe_key)
  values(v_req.family_id,v_req.requested_by,'medical_primary_declined','คำขอคนดูแลหลักยังไม่สำเร็จ',
  'ผู้ที่คุณเชิญยังไม่สะดวกรับหน้าที่ดูแลหลัก กรุณาเลือกคนอื่นหรือพูดคุยกันก่อน',
  'line','normal','pending',v_req.family_person_id,
  jsonb_build_object('request_code',substr(v_req.id::text,1,12)),'medical_primary_declined_'||v_req.id::text);
 end if;
 return jsonb_build_object('ok',true,'status','rejected');
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_line_medical_primary_nominate(p_line_user_id text, p_person_code text, p_member_code text, p_reason text DEFAULT NULL::text, p_keep_previous_access boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare a record; p record; v_person public.persons%rowtype; v_current private.medical_primary_responsibilities%rowtype; v_request_id uuid;
begin
 select * into a from private.resolve_line_family_member(p_line_user_id,p_member_code);
 select * into p from private.resolve_line_family_person_code(p_line_user_id,p_person_code);
 if a.family_id<>p.family_id then raise exception 'family_scope_mismatch';end if;
 perform set_config('request.jwt.claim.sub',a.actor_user_id::text,true);
 select per.* into v_person from public.family_persons fp join public.persons per on per.id=fp.person_id where fp.id=p.family_person_id;
 select * into v_current from private.medical_primary_responsibilities where family_person_id=p.family_person_id for update;
 if not private.phms_can_manage_medical_grants(a.actor_user_id,p.family_person_id) then raise exception 'medical_primary_change_not_authorized';end if;
 if coalesce(v_current.state,'needs_assignment')<>'active' and v_person.linked_user_id is distinct from a.actor_user_id 
  and length(btrim(coalesce(p_reason,'')))<12 then
  raise exception 'care_authority_reason_required';
 end if;
 if a.target_user_id=a.actor_user_id and coalesce(v_current.state,'needs_assignment')<>'active' and v_person.linked_user_id is distinct from a.actor_user_id then
  raise exception 'cannot_nominate_self_for_unlinked_patient';
 end if;
 if v_current.state='active' and v_current.primary_user_id=a.target_user_id then raise exception 'already_primary';end if;
 insert into private.medical_primary_transfer_requests(
  family_id,family_person_id,proposed_user_id,requested_by,request_note,keep_old_access
 ) values(p.family_id,p.family_person_id,a.target_user_id,a.actor_user_id,nullif(btrim(p_reason),''),p_keep_previous_access)
 returning id into v_request_id;
 insert into public.audit_logs(family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,new_data,description)
 values(p.family_id,a.actor_user_id,a.target_user_id,p.family_person_id,'medical_primary_nominated','medical_access',
  jsonb_build_object('request_id',v_request_id,'keep_previous_access',p_keep_previous_access),
  'Proposed a new primary health-data caregiver, awaiting acceptance');
 return jsonb_build_object('ok',true,'status','pending','request_code',substr(v_request_id::text,1,12));
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_line_medical_record_request_add_asset(p_line_user_id text, p_request_code text, p_storage_asset_id uuid, p_item_code text DEFAULT NULL::text, p_document_type text DEFAULT 'medical_record'::text, p_title text DEFAULT NULL::text, p_document_date date DEFAULT NULL::date, p_service_period_start date DEFAULT NULL::date, p_service_period_end date DEFAULT NULL::date, p_received_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_req public.medical_record_requests%rowtype;
  v_asset public.phms_storage_assets%rowtype;
  v_doc public.medical_documents%rowtype;
  v_item public.medical_record_request_items%rowtype;
  v_item_code text:=lower(btrim(coalesce(p_item_code,'')));
  v_item_count int;
  v_received_at timestamptz:=coalesce(p_received_at,now());
  v_remaining int;
  v_received int;
begin
  select * into v_ref
  from private.phms_find_record_request_for_line(p_line_user_id,p_request_code,'update')
  limit 1;

  select * into v_req
  from public.medical_record_requests
  where id=v_ref.request_id and deleted_at is null;

  select * into v_asset
  from public.phms_storage_assets
  where id=p_storage_asset_id and deleted_at is null;

  if not found then raise exception 'storage_asset_not_found'; end if;
  if v_asset.person_id is not null and v_asset.person_id is distinct from v_ref.person_id then
    raise exception 'storage_asset_person_mismatch';
  end if;

  if v_item_code<>'' then
    select count(*) into v_item_count
    from public.medical_record_request_items i
    where i.request_id=v_req.id and lower(i.id::text) like v_item_code||'%';
    if v_item_count=0 then raise exception 'record_request_item_not_found'; end if;
    if v_item_count>1 then raise exception 'record_request_item_code_ambiguous'; end if;

    select * into v_item
    from public.medical_record_request_items i
    where i.request_id=v_req.id and lower(i.id::text) like v_item_code||'%'
    limit 1;
  end if;

  update public.phms_storage_assets
  set person_id=coalesce(person_id,v_ref.person_id),
      permission_resource='health',
      updated_at=now()
  where id=v_asset.id;

  insert into public.medical_documents(
    person_id,encounter_id,organization_id,document_type,document_date,title,
    storage_bucket,storage_path,source_channel,original_filename,mime_type,checksum_sha256,
    extraction_status,uploaded_by,metadata,storage_asset_id,
    treatment_episode_id,medical_record_request_id,
    service_period_start,service_period_end,received_at
  ) values(
    v_ref.person_id,null,v_req.organization_id,
    coalesce(nullif(btrim(coalesce(p_document_type,'')),''),coalesce(v_item.requested_document_type,'medical_record')),
    p_document_date,
    coalesce(nullif(btrim(coalesce(p_title,'')),''),v_item.title,v_asset.original_filename,'เวชระเบียน'),
    v_asset.bucket_id,v_asset.object_name,'line_medical_record_request',
    v_asset.original_filename,v_asset.mime_type,v_asset.checksum_sha256,
    'not_started',v_ref.actor_user_id,
    jsonb_build_object(
      'medical_record_request_id',v_req.id,
      'request_item_id',case when v_item.id is not null then v_item.id else null end
    ),
    v_asset.id,
    v_req.treatment_episode_id,v_req.id,
    coalesce(p_service_period_start,v_item.service_period_start),
    coalesce(p_service_period_end,v_item.service_period_end),
    v_received_at
  )
  returning * into v_doc;

  if v_item.id is not null then
    update public.medical_record_request_items
    set status='received',
        medical_document_id=v_doc.id,
        received_at=v_received_at,
        service_period_start=coalesce(p_service_period_start,service_period_start),
        service_period_end=coalesce(p_service_period_end,service_period_end),
        updated_at=now()
    where id=v_item.id;
  else
    insert into public.medical_record_request_items(
      request_id,requested_document_type,title,service_period_start,service_period_end,
      status,medical_document_id,received_at,created_by
    ) values(
      v_req.id,v_doc.document_type,coalesce(v_doc.title,'เวชระเบียน'),
      v_doc.service_period_start,v_doc.service_period_end,
      'received',v_doc.id,v_received_at,v_ref.actor_user_id
    )
    returning * into v_item;
  end if;

  select count(*) filter(where status='requested'),
         count(*) filter(where status='received')
  into v_remaining,v_received
  from public.medical_record_request_items
  where request_id=v_req.id
    and status not in ('cancelled','not_available');

  update public.medical_record_requests
  set status=case when v_remaining=0 and v_received>0 then 'received'
                  when v_received>0 then 'partial'
                  else status end,
      received_at=case when v_remaining=0 and v_received>0 then v_received_at else received_at end,
      updated_at=now()
  where id=v_req.id;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,new_data,description
  ) values(
    v_ref.family_id,v_ref.actor_user_id,v_ref.family_person_id,
    'medical_record_received','medical_document',v_doc.id,
    jsonb_build_object(
      'request_id',v_req.id,'request_item_id',v_item.id,'document',to_jsonb(v_doc)
    ),
    'รับเอกสารจากคำขอเวชระเบียน'
  );

  return jsonb_build_object(
    'ok',true,
    'request_code',substr(v_req.id::text,1,12),
    'episode_code',case when v_req.treatment_episode_id is not null then substr(v_req.treatment_episode_id::text,1,12) end,
    'item_code',substr(v_item.id::text,1,12),
    'document_code',substr(v_doc.id::text,1,12),
    'status',(select status from public.medical_record_requests where id=v_req.id)
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_medical_record_request_create(p_line_user_id text, p_episode_code text, p_hospital_query text, p_requested_at timestamp with time zone, p_items jsonb, p_request_channel text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ep record;
  v_req public.medical_record_requests%rowtype;
  v_org_id uuid;
  v_h text:=btrim(coalesce(p_hospital_query,''));
  v_item jsonb;
  v_count int:=0;
begin
  select * into v_ep
  from private.phms_find_treatment_episode_for_line(p_line_user_id,p_episode_code,'update')
  limit 1;

  if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then
    raise exception 'record_request_items_required';
  end if;

  if v_h<>'' then
    select o.id into v_org_id
    from public.healthcare_organizations o
    where o.deleted_at is null
      and (
        lower(btrim(coalesce(o.external_code,'')))=lower(v_h)
        or lower(btrim(o.name))=lower(v_h)
        or lower(btrim(o.name||case when nullif(btrim(coalesce(o.branch_name,'')),'') is not null then ' '||o.branch_name else '' end))=lower(v_h)
        or lower(o.name) like '%'||lower(v_h)||'%'
      )
    order by
      case when lower(btrim(coalesce(o.external_code,'')))=lower(v_h) then 0
           when lower(btrim(o.name))=lower(v_h) then 1 else 2 end,
      o.updated_at desc
    limit 1;
  end if;

  insert into public.medical_record_requests(
    family_id,family_person_id,person_id,treatment_episode_id,organization_id,
    requested_at,request_channel,status,notes,created_by
  ) values(
    v_ep.family_id,v_ep.family_person_id,v_ep.person_id,v_ep.episode_id,v_org_id,
    p_requested_at,nullif(btrim(coalesce(p_request_channel,'')),''),
    'requested',nullif(btrim(coalesce(p_notes,'')),''),v_ep.actor_user_id
  )
  returning * into v_req;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    if nullif(btrim(coalesce(v_item->>'title','')),'') is null then
      continue;
    end if;
    insert into public.medical_record_request_items(
      request_id,requested_document_type,title,
      service_period_start,service_period_end,status,note,created_by
    ) values(
      v_req.id,
      coalesce(nullif(btrim(v_item->>'document_type'),''),'medical_record'),
      btrim(v_item->>'title'),
      nullif(v_item->>'service_period_start','')::date,
      nullif(v_item->>'service_period_end','')::date,
      'requested',
      nullif(btrim(coalesce(v_item->>'note','')),''),
      v_ep.actor_user_id
    );
    v_count:=v_count+1;
  end loop;

  if v_count=0 then
    raise exception 'record_request_valid_items_required';
  end if;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,new_data,description
  ) values(
    v_ep.family_id,v_ep.actor_user_id,v_ep.family_person_id,
    'medical_record_request_created','medical_record_request',v_req.id,
    jsonb_build_object('request',to_jsonb(v_req),'item_count',v_count),
    'บันทึกคำขอเวชระเบียน'
  );

  return jsonb_build_object(
    'ok',true,
    'request_id',v_req.id,
    'request_code',substr(v_req.id::text,1,12),
    'episode_code',substr(v_ep.episode_id::text,1,12),
    'item_count',v_count
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_medical_set_member_access(p_line_user_id text, p_person_code text, p_member_code text, p_scopes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 a record;p record;v_key text;v_level text;
 v_allowed constant text[]:=array['persons','appointments','health_data','medications','emergency'];
 v_primary uuid;v_subject uuid;
begin
 if p_scopes is null or jsonb_typeof(p_scopes)<>'object' then raise exception 'scopes_object_required';end if;

 select * into a from private.resolve_line_family_member(p_line_user_id,p_member_code);
 select * into p from private.resolve_line_family_person_code(p_line_user_id,p_person_code);
 if a.family_id<>p.family_id then raise exception 'family_scope_mismatch';end if;
 perform set_config('request.jwt.claim.sub',a.actor_user_id::text,true);

 if not private.phms_can_manage_medical_grants(a.actor_user_id,p.family_person_id) then
  raise exception 'medical_grant_not_authorized';
 end if;

 select primary_user_id into v_primary
 from private.medical_primary_responsibilities
 where family_person_id=p.family_person_id and state='active';
 if a.target_user_id=v_primary then raise exception 'cannot_change_primary_grants';end if;

 select pp.linked_user_id into v_subject
 from public.family_persons fp join public.persons pp on pp.id=fp.person_id
 where fp.id=p.family_person_id;
 if a.target_user_id=v_subject then raise exception 'use_self_access_settings';end if;

 if exists(select 1 from jsonb_object_keys(p_scopes) s where s<>all(v_allowed)) then
  raise exception 'unknown_medical_resource';
 end if;
 if (select count(*) from jsonb_object_keys(p_scopes))=0 then raise exception 'at_least_one_scope_required';end if;

 for v_key in select jsonb_object_keys(p_scopes) loop
  if jsonb_typeof(p_scopes->v_key)<>'string' then raise exception 'invalid_scope_level';end if;
  v_level:=p_scopes->>v_key;
  if v_level not in ('none','view','manage') then raise exception 'invalid_scope_level';end if;

  insert into public.person_permissions(
   family_id,family_person_id,user_id,resource,
   can_view,can_create,can_update,can_delete,can_receive_notifications,status,granted_by,created_at,updated_at
  ) values(
   p.family_id,p.family_person_id,a.target_user_id,v_key,
   v_level<>'none',v_level='manage',v_level='manage',v_level='manage',false,
   'active',a.actor_user_id,now(),now()
  )
  on conflict(family_id,family_person_id,user_id,resource) do update
  set can_view=excluded.can_view,can_create=excluded.can_create,can_update=excluded.can_update,
      can_delete=excluded.can_delete,
      can_approve=false,can_manage_medication=false,can_manage_stock=false,
      granted_by=a.actor_user_id,status='active',updated_at=now();
 end loop;

 perform private.sync_care_assistant_from_person_permissions(
  p.family_person_id,a.target_user_id,a.actor_user_id
 );

 insert into public.audit_logs(
  family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,new_data,description
 ) values(
  p.family_id,a.actor_user_id,a.target_user_id,p.family_person_id,
  'medical_access_scopes_updated','medical_access',
  jsonb_build_object('scopes',p_scopes),'Updated five-category person-scoped health access'
 );

 return jsonb_build_object('ok',true,'person_code',p_person_code,'scopes',p_scopes);
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_line_owner_transfer_accept(p_line_user_id text, p_request_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare v_line record;v_req private.household_owner_transfer_requests%rowtype;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
 select * into v_req
 from private.household_owner_transfer_requests
 where proposed_owner_user_id=v_line.user_id and status='pending'
   and id::text like lower(btrim(p_request_code))||'%'
 order by created_at desc limit 1 for update;
 if not found then raise exception 'owner_transfer_request_not_found'; end if;
 if not private.user_has_family_role(v_req.current_owner_user_id,v_req.family_id,array['owner']) then
   raise exception 'current_owner_changed';
 end if;

 update public.family_role_assignments set status='inactive',updated_at=now()
 where family_id=v_req.family_id and user_id in (v_req.current_owner_user_id,v_req.proposed_owner_user_id)
   and status='active';

 insert into public.family_role_assignments(family_id,user_id,role,status,granted_by,granted_at,created_at,updated_at)
 values(v_req.family_id,v_req.proposed_owner_user_id,'owner','active',v_req.current_owner_user_id,now(),now(),now());

 insert into public.family_role_assignments(family_id,user_id,role,status,granted_by,granted_at,created_at,updated_at)
 values(v_req.family_id,v_req.current_owner_user_id,v_req.previous_owner_role,'active',v_line.user_id,now(),now(),now());

 update private.household_owner_transfer_requests
 set status='accepted',decided_at=now(),decided_by=v_line.user_id where id=v_req.id;

 insert into public.audit_logs(family_id,actor_user_id,target_user_id,event_type,resource,new_data,description)
 values(v_req.family_id,v_line.user_id,v_req.proposed_owner_user_id,'owner_transfer_accepted','family_ownership',
  jsonb_build_object('request_id',v_req.id,'previous_owner_new_role',v_req.previous_owner_role),
  'Recipient accepted household owner transfer');

 return jsonb_build_object('ok',true,'status','accepted','household_role','owner');
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_line_owner_transfer_decline(p_line_user_id text, p_request_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare v_line record;v_req private.household_owner_transfer_requests%rowtype;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 select * into v_req from private.household_owner_transfer_requests
 where proposed_owner_user_id=v_line.user_id and status='pending'
   and id::text like lower(btrim(p_request_code))||'%'
 order by created_at desc limit 1 for update;
 if not found then raise exception 'owner_transfer_request_not_found'; end if;
 update private.household_owner_transfer_requests
  set status='rejected',decided_at=now(),decided_by=v_line.user_id where id=v_req.id;
 return jsonb_build_object('ok',true,'status','rejected');
