$function$

CREATE OR REPLACE FUNCTION public.phms_line_person_card_colors(p_line_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare v_line record;v_ctx private.line_identity_contexts%rowtype;v_items jsonb;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select * into v_ctx from private.line_identity_contexts where line_identity_id=v_line.line_identity_id;
 if v_ctx.active_scope<>'family' or v_ctx.active_family_id is null then return jsonb_build_object('items','[]'::jsonb);end if;
 select coalesce(jsonb_agg(jsonb_build_object(
 'person_code',substr(encode(digest(fp.id::text||':'||v_line.line_identity_id::text,'sha256'),'hex'),1,12),
 'card_color',ui.card_color,
 'can_change',private.user_can_access_family_person(v_line.user_id,fp.id,'persons','update')
 ) order by fp.created_at),'[]'::jsonb) into v_items
 from public.family_persons fp left join public.person_ui_preferences ui on ui.person_id=fp.person_id
 where fp.family_id=v_ctx.active_family_id and fp.status='active'
 and private.user_can_access_family_person(v_line.user_id,fp.id,'persons','view');
 return jsonb_build_object('items',v_items);
end $function$

CREATE OR REPLACE FUNCTION public.phms_line_person_expense_recent_labels(p_line_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth'
AS $function$
declare v_line record; v_ctx private.line_identity_contexts%rowtype; v_person uuid; v_appointments boolean;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select * into v_ctx from private.line_identity_contexts where line_identity_id=v_line.line_identity_id;
 if v_ctx.active_scope<>'family' or v_ctx.active_family_person_id is null then raise exception 'family_person_context_required'; end if;
 if not private.user_can_access_family_person(v_line.user_id,v_ctx.active_family_person_id,'persons','view') or not private.user_can_access_family_person(v_line.user_id,v_ctx.active_family_person_id,'expenses','view') then raise exception 'expense_view_denied'; end if;
 select person_id into v_person from public.family_persons where id=v_ctx.active_family_person_id;
 v_appointments := private.user_can_access_family_person(v_line.user_id,v_ctx.active_family_person_id,'appointments','view');
 return (select coalesce(jsonb_agg(jsonb_build_object('appointment_id',case when v_appointments then x.appointment_id else null end,'date',x.expense_date,'amount',x.paid_amount,'appointment_title',case when v_appointments then x.appt_title else null end,'title',case when nullif(btrim(x.notes),'') is not null then left(btrim(x.notes),100) else null end) order by x.expense_date desc nulls last,x.created_at desc),'[]'::jsonb)
 from (select e.appointment_id,e.expense_date,e.paid_amount,e.created_at,e.notes,a.title as appt_title from public.healthcare_expenses e left join public.appointments a on a.id=e.appointment_id and a.person_id=v_person and a.deleted_at is null where e.person_id=v_person and e.deleted_at is null and e.paid_amount > 0 order by e.expense_date desc nulls last,e.created_at desc limit 5) x);
end $function$

CREATE OR REPLACE FUNCTION public.phms_line_person_expense_trend(p_line_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth'
AS $function$
declare v_line record; v_ctx private.line_identity_contexts%rowtype; v_person uuid; v_today date; v_begin date; v_rows jsonb; v_year numeric; v_month numeric; v_prev numeric; v_count int; v_missing int;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select * into v_ctx from private.line_identity_contexts where line_identity_id=v_line.line_identity_id;
 if v_ctx.active_scope <> 'family' or v_ctx.active_family_person_id is null then raise exception 'family_person_context_required'; end if;
 if not private.user_can_access_family_person(v_line.user_id,v_ctx.active_family_person_id,'persons','view') or not private.user_can_access_family_person(v_line.user_id,v_ctx.active_family_person_id,'expenses','view') then raise exception 'expense_view_denied'; end if;
 select person_id into v_person from public.family_persons where id=v_ctx.active_family_person_id;
 v_today := (now() at time zone 'Asia/Bangkok')::date;
 v_begin := date_trunc('month',v_today)::date;
 select count(*),count(*) filter(where paid_amount is null),
 coalesce(sum(paid_amount) filter(where expense_date>=date_trunc('year',v_today)::date and expense_date < (date_trunc('year',v_today)+interval '1 year')::date),0),
 coalesce(sum(paid_amount) filter(where expense_date>=v_begin and expense_date < (v_begin+interval '1 month')::date),0),
 coalesce(sum(paid_amount) filter(where expense_date>= (v_begin-interval '1 month')::date and expense_date<v_begin),0)
 into v_count,v_missing,v_year,v_month,v_prev from public.healthcare_expenses where person_id=v_person and deleted_at is null;
 select coalesce(jsonb_agg(jsonb_build_object('month',to_char(mon,'YYYY-MM'),'amount',total,'complete',mon<v_begin) order by mon),'[]'::jsonb)
 into v_rows from (
 select gs.mon::date mon,coalesce(sum(e.paid_amount),0) total
 from generate_series(v_begin-interval '5 months',v_begin,interval '1 month') gs(mon)
 left join public.healthcare_expenses e on e.person_id=v_person and e.deleted_at is null and e.expense_date>=gs.mon::date and e.expense_date<(gs.mon+interval '1 month')::date
 group by gs.mon
 ) t;
 return jsonb_build_object('view',true,'count',v_count,'verified',v_missing=0,'year_paid',case when v_missing=0 then v_year end,'month_paid',case when v_missing=0 then v_month end,'previous_month_paid',case when v_missing=0 then v_prev end,'delta',case when v_missing=0 then v_month-v_prev end,'months',v_rows);
end $function$

CREATE OR REPLACE FUNCTION public.phms_line_person_hospital_context(p_line_user_id text, p_hospital_query text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_ctx private.line_identity_contexts%rowtype;
  v_person_id uuid;
  v_display text;
  v_org uuid;
  v_hn text;
  v_vn text;
begin
  select * into v_line
  from private.resolve_line_user_for_service(p_line_user_id);

  perform private.ensure_line_identity_context(
    v_line.line_identity_id,v_line.user_id
  );

  select * into v_ctx
  from private.line_identity_contexts
  where line_identity_id=v_line.line_identity_id;

  if v_ctx.active_family_person_id is null then
    raise exception 'active_family_person_required';
  end if;

  if not private.user_can_access_family_person(
    v_line.user_id,v_ctx.active_family_person_id,'appointments','view'
  ) then
    raise exception 'appointment_view_required';
  end if;

  select fp.person_id into v_person_id
  from public.family_persons fp
  where fp.id=v_ctx.active_family_person_id;

  v_display:=private.phms_canonical_hospital_display(p_hospital_query);
  v_org:=private.phms_canonical_hospital_org_id(p_hospital_query);
  v_hn:=private.phms_person_hospital_hn(v_person_id,v_org,v_display);
  v_vn:=private.phms_person_hospital_vn(v_person_id,v_org,v_display);

  return jsonb_strip_nulls(jsonb_build_object(
    'matched',v_display is not null,
    'hospital_name',v_display,
    'organization_id',v_org,
    'hospital_hn',v_hn,
    'hospital_vn',v_vn,
    'has_hn',v_hn is not null,
    'has_vn',v_vn is not null,
    'hospital_code',private.phms_canonical_hospital_code(p_hospital_query)
  ));
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_person_previsit_health_history(p_line_user_id text, p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare v_line record;v_ctx private.line_identity_contexts%rowtype;v_person_id uuid;v_items jsonb;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select * into v_ctx from private.line_identity_contexts where line_identity_id=v_line.line_identity_id;
 if v_ctx.active_family_person_id is null or not private.user_can_access_family_person(v_line.user_id,v_ctx.active_family_person_id,'health_data','view') then raise exception 'health_access_denied'; end if;
 select fp.person_id into v_person_id from public.family_persons fp join public.persons p on p.id=fp.person_id where fp.id=v_ctx.active_family_person_id and fp.status='active' and p.status='active';
 if v_person_id is null then raise exception 'person_not_found'; end if;
 select coalesce(jsonb_agg(j order by reported_at desc),'[]'::jsonb) into v_items from (
 select s.reported_at,jsonb_build_object('symptom',s.symptom_text,'reported_at',s.reported_at,'severity',s.severity,'severity_dimension',s.severity_dimension,'functional_impact',s.functional_impact,'onset',s.onset_text,'appointment_date',a.appointment_at) j
 from public.appointment_previsit_symptoms s join public.appointments a on a.id=s.appointment_id
 where s.person_id=v_person_id and s.deleted_at is null order by s.reported_at desc limit least(greatest(coalesce(p_limit,10),1),30)
 ) z;
 return jsonb_build_object('ok',true,'items',v_items);
end $function$

CREATE OR REPLACE FUNCTION public.phms_line_person_theme_color(p_line_user_id text, p_color text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth'
AS $function$
declare v_line record; v_ctx private.line_identity_contexts%rowtype; v_p uuid; v_color text;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select * into v_ctx from private.line_identity_contexts where line_identity_id=v_line.line_identity_id;
 if v_ctx.active_family_person_id is null or v_ctx.active_scope<>'family' then raise exception 'family_person_context_required'; end if;
 if not private.user_can_access_family_person(v_line.user_id,v_ctx.active_family_person_id,'persons','view') then raise exception 'person_view_denied'; end if;
 select person_id into v_p from public.family_persons where id=v_ctx.active_family_person_id;
 if p_color is not null then
   if not private.user_can_access_family_person(v_line.user_id,v_ctx.active_family_person_id,'persons','update') then raise exception 'person_update_denied'; end if;
   v_color:=upper(trim(p_color));
   if v_color !~ '^#[0-9A-F]{6}$' then raise exception 'invalid_hex_color'; end if;
