   on conflict(person_id) do update set card_color=excluded.card_color,updated_by=excluded.updated_by,updated_at=now();
 end if;
 return jsonb_build_object('can_edit',private.user_can_access_family_person(v_line.user_id,v_ctx.active_family_person_id,'persons','update'),'color',(select card_color from public.person_ui_preferences where person_id=v_p));
end $function$

CREATE OR REPLACE FUNCTION public.phms_line_previsit_doctor_summary(p_line_user_id text, p_record_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE v_ref record; v_a public.appointments%rowtype; v_symptoms jsonb;v_health jsonb;v_med jsonb;v_m jsonb;v_allergy jsonb;v_can_health boolean;v_can_med boolean;
BEGIN
 SELECT * INTO v_ref FROM private.phms_line_appointment_access(p_line_user_id,p_record_code) LIMIT 1;
 IF v_ref.record_id IS NULL THEN RAISE EXCEPTION 'appointment_not_accessible'; END IF;
 SELECT * INTO v_a FROM public.appointments WHERE id=v_ref.record_id AND deleted_at IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'appointment_not_found'; END IF;
 v_can_health := v_ref.active_family_person_id IS NOT NULL AND private.user_can_access_family_person(v_ref.actor_user_id,v_ref.active_family_person_id,'health_data','view');
 v_can_med := v_ref.active_family_person_id IS NOT NULL AND private.user_can_access_family_person(v_ref.actor_user_id,v_ref.active_family_person_id,'medications','view');
 IF NOT v_can_health THEN RAISE EXCEPTION 'previsit_health_view_denied'; END IF;
 SELECT coalesce(jsonb_agg(z.item ORDER BY z.reported_at DESC),'[]'::jsonb) INTO v_symptoms FROM (
  SELECT reported_at,jsonb_strip_nulls(jsonb_build_object('reported_at',reported_at,'symptom',symptom_text,'onset',onset_text,'score',severity,'dimension',severity_dimension,'impact',functional_impact,'trend',trend,'questions',patient_questions,'method',severity_method)) item
  FROM public.appointment_previsit_symptoms WHERE appointment_id=v_a.id AND deleted_at IS NULL ORDER BY reported_at DESC LIMIT 10
 ) z;
 SELECT coalesce(jsonb_agg(z.item ORDER BY z.measured_at DESC),'[]'::jsonb) INTO v_m FROM (
  SELECT measured_at,jsonb_strip_nulls(jsonb_build_object('type',measurement_type,'measured_at',measured_at,'value',value_numeric,'text',value_text,'unit',unit,'systolic',systolic,'diastolic',diastolic)) item
  FROM public.health_measurements WHERE person_id=v_a.person_id AND deleted_at IS NULL ORDER BY measured_at DESC LIMIT 12
 ) z;
 SELECT coalesce(jsonb_agg(jsonb_build_object('condition',condition_name,'status',clinical_status)),'[]'::jsonb) INTO v_health FROM public.health_conditions WHERE person_id=v_a.person_id AND deleted_at IS NULL AND coalesce(clinical_status,'active') NOT IN ('resolved','inactive');
 SELECT coalesce(jsonb_agg(jsonb_build_object('allergen',allergen,'reaction',reaction)),'[]'::jsonb) INTO v_allergy FROM public.allergies WHERE person_id=v_a.person_id AND deleted_at IS NULL;
 IF v_can_med THEN
  SELECT coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('name',coalesce(mm.brand_name,mm.generic_name),'generic_name',mm.generic_name,'strength',concat_ws(' ',mm.strength_value::text,mm.strength_unit),'indication',pm.indication,'status',pm.status))),'[]'::jsonb)
  INTO v_med FROM public.person_medications pm JOIN public.medication_master mm ON mm.id=pm.medication_id
  WHERE pm.person_id=v_a.person_id AND pm.deleted_at IS NULL AND mm.deleted_at IS NULL AND pm.status IN ('active','current');
 ELSE v_med:='[]'::jsonb; END IF;
 RETURN jsonb_build_object('ok',true,'record_code',substr(v_a.id::text,1,12),'appointment',jsonb_build_object('title',v_a.title,'hospital',v_a.hospital_name,'department',v_a.department,'doctor',v_a.doctor_name,'date',v_a.appointment_at,'care_topic',v_a.care_topic),'symptoms',v_symptoms,'conditions',v_health,'allergies',v_allergy,'measurements',v_m,'medications',v_med,'medications_accessible',v_can_med,'disclaimer','ข้อมูลจากบันทึกในระบบ ตรวจสอบความถูกต้องกับผู้ป่วยและแพทย์ก่อนใช้รักษา');
END $function$

CREATE OR REPLACE FUNCTION public.phms_line_previsit_save_extended(p_line_user_id text, p_record_code text, p_symptom_text text, p_onset_text text DEFAULT NULL::text, p_severity integer DEFAULT NULL::integer, p_trend text DEFAULT NULL::text, p_associated_symptoms text DEFAULT NULL::text, p_actions_taken text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_severity_dimension text DEFAULT NULL::text, p_functional_impact integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare r jsonb;v_id uuid;v_appointment_id uuid;
begin
 if p_severity_dimension is not null and p_severity_dimension not in ('pain','breathlessness','fatigue','dizziness','vision','other') then raise exception 'invalid_symptom_dimension';end if;
 if p_functional_impact is not null and (p_functional_impact<0 or p_functional_impact>4) then raise exception 'invalid_functional_impact';end if;
 r:=public.phms_line_appointment_previsit_symptom_save(p_line_user_id,p_record_code,p_symptom_text,p_onset_text,p_severity,p_trend,p_associated_symptoms,p_actions_taken,p_note);
 select id,appointment_id into v_id,v_appointment_id from public.appointment_previsit_symptoms where substr(id::text,1,12)=r->>'symptom_code' limit 1;
 if v_id is null then raise exception 'symptom_not_found';end if;
 update public.appointment_previsit_symptoms set severity_dimension=p_severity_dimension,functional_impact=p_functional_impact,severity_method=case when p_severity is null then 'not_assessed' else 'nrs_0_10' end, severity_guide_version='aim-v1',original_report=p_symptom_text,confirmed_at=now() where id=v_id;
 insert into public.phms_symptom_event_links(symptom_id,appointment_id,link_kind) values(v_id,v_appointment_id,'origin') on conflict do nothing;
 return r;
end $function$

CREATE OR REPLACE FUNCTION public.phms_line_previsit_symptoms_extended(p_line_user_id text, p_record_code text, p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare base jsonb; src jsonb; mapped jsonb; item jsonb; result jsonb:='[]'::jsonb; rowinfo record;
begin
 base:=public.phms_line_appointment_previsit_symptoms(p_line_user_id,p_record_code,p_limit);
 for item in select value from jsonb_array_elements(coalesce(base->'items','[]'::jsonb)) loop
  select severity_dimension,functional_impact,severity_method into rowinfo
  from public.appointment_previsit_symptoms where substr(id::text,1,12)=item->>'symptom_code' limit 1;
  result:=result||jsonb_build_array(item||jsonb_build_object('severity_dimension',rowinfo.severity_dimension,'functional_impact',rowinfo.functional_impact,'severity_method',rowinfo.severity_method));
 end loop;
 return base||jsonb_build_object('items',result);
end $function$

CREATE OR REPLACE FUNCTION public.phms_line_record_capabilities(p_line_user_id text, p_resource text, p_record_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_dummy record;
  v_access record;
  v_sensitive record;
  v_update boolean:=false;
  v_delete boolean:=false;
  v_can_health boolean:=false;
  v_key text:=private.phms_crud_resource_key(p_resource);
begin
  if v_key='appointment' then
    select * into v_access
    from private.phms_line_appointment_access(
      p_line_user_id,p_record_code
    )
    limit 1;

    begin
      select * into v_sensitive
      from private.phms_line_appointment_sensitive_access(
        p_line_user_id,p_record_code
      )
      limit 1;
    exception when others then
      v_sensitive:=null;
    end;

    v_can_health:=coalesce(v_access.active_family_person_id is not null,false)
      and private.user_can_access_family_person(
        v_access.actor_user_id,v_access.active_family_person_id,'health_data','view'
      );
    v_update:=coalesce(v_access.can_update,false);

    if v_update then
      begin
        select * into v_dummy
        from private.phms_find_crud_record(
          p_line_user_id,p_resource,p_record_code,'delete'
        ) limit 1;
        v_delete:=found;
      exception when others then
        v_delete:=false;
      end;
    end if;

    return jsonb_build_object(
      'can_update',v_update,
      'can_create_early_visit',coalesce(v_access.active_family_person_id is not null,false)
        and private.user_can_access_family_person(
          v_access.actor_user_id,v_access.active_family_person_id,'appointments','create'
        ),
      'can_delete',v_delete,
      'has_person_view',coalesce(v_access.has_person_view,false),
      'is_assignee',coalesce(v_access.is_assignee,false),
      'can_view_full',coalesce(v_access.full_access,false),
      'can_view_documents',coalesce(v_access.full_access,false) or (
        exists(select 1 from public.appointments a where a.id=v_access.record_id and a.status='completed')
        and (v_can_health or coalesce(v_sensitive.can_view_sensitive,false))
      ),
      'can_view_post_visit',v_can_health,
      'can_view_history',true,
      'can_view_links',coalesce(v_access.full_access,false),
      'can_view_finance',coalesce(v_sensitive.can_view_sensitive,false),
      'can_update_finance',
        coalesce(v_sensitive.can_view_sensitive,false)
        and coalesce(v_sensitive.can_update_appointments,false),
      'can_view_sensitive',coalesce(v_sensitive.can_view_sensitive,false),
      'is_self',coalesce(v_sensitive.is_self,false),
      'is_primary_caregiver',coalesce(v_sensitive.is_primary,false),
      'is_care_assistant',coalesce(v_sensitive.is_care_assistant,false),
      'detail_access',case
        when coalesce(v_access.full_access,false) then 'full'
        else 'limited'
      end
    );
  end if;

  begin
    select * into v_dummy
    from private.phms_find_crud_record(
      p_line_user_id,p_resource,p_record_code,'update'
    ) limit 1;
    v_update:=found;
  exception when others then v_update:=false;
  end;

  begin
    select * into v_dummy
    from private.phms_find_crud_record(
      p_line_user_id,p_resource,p_record_code,'delete'
    ) limit 1;
    v_delete:=found;
  exception when others then v_delete:=false;
  end;

  return jsonb_build_object(
    'can_update',v_update,'can_delete',v_delete
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_remind_appointment_view_request(p_line_user_id text, p_request_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_req public.permission_requests%rowtype;
  v_code text:=lower(btrim(coalesce(p_request_code,'')));
  v_anchor timestamptz;
  v_reviewer record;
  v_reviewer_count integer:=0;
  v_requester_label text;
  v_person_label text;
begin
  select * into v_line from private.resolve_line_user_for_service(p_line_user_id);

  select pr.* into v_req
  from public.permission_requests pr
  where pr.requester_user_id=v_line.user_id
    and pr.request_type='permission'
    and pr.resource='appointments'
    and pr.requested_action='view'
    and pr.status='pending'
    and substr(
      encode(digest(pr.id::text||':'||v_line.line_identity_id::text,'sha256'),'hex'),
      1,12
    )=v_code
  limit 1
  for update;

  if not found then raise exception 'appointment_view_request_not_found'; end if;

  v_anchor:=coalesce(v_req.last_reminded_at,v_req.created_at);
  if now()<v_anchor+interval '3 days' then
    raise exception 'appointment_view_request_remind_too_soon';
  end if;

  for v_reviewer in
    select distinct fm.user_id
    from public.family_memberships fm
    where fm.family_id=v_req.family_id
      and fm.status='active'
      and fm.user_id<>v_line.user_id
      and private.can_review_person_access_request(fm.user_id,v_req.family_person_id)
      and exists(
        select 1 from public.line_identities li
        where li.user_id=fm.user_id
          and li.is_active=true
          and li.onboarding_status='ready'
      )
  loop
    v_requester_label:=private.family_user_label_for_viewer(
      v_reviewer.user_id,v_req.family_id,v_line.user_id
    );
    v_person_label:=private.family_person_label_for_viewer(
      v_reviewer.user_id,v_req.family_person_id
    );

    insert into public.notifications(
      family_id,recipient_user_id,event_type,title,message,related_record_id,
      channel,priority,status,family_person_id,scheduled_for,next_attempt_at,
      payload,dedupe_key,created_at,updated_at
    ) values(
      v_req.family_id,v_reviewer.user_id,'appointment_view_request_reminder',
      '🔔 คำขอดูนัดหมายยังรออนุมัติ',
      v_requester_label||' ยังรอสิทธิ์ดูนัดหมายของ '||coalesce(v_person_label,'บุคคล'),
      v_req.id,'line','normal','pending',v_req.family_person_id,now(),now(),
      jsonb_build_object(
        'request_id',v_req.id,
        'request_code',v_code,
        'resource','appointments',
        'requested_action','view'
      ),
      'appointment-view-request-reminder:'||v_req.id::text||':'||
        v_reviewer.user_id::text||':'||
        to_char((now() at time zone 'Asia/Bangkok')::date,'YYYYMMDD'),
      now(),now()
    )
    on conflict(dedupe_key) where dedupe_key is not null do nothing;

    v_reviewer_count:=v_reviewer_count+1;
  end loop;

  update public.permission_requests
  set last_reminded_at=now(),
      reminder_count=coalesce(reminder_count,0)+1,
      updated_at=now()
  where id=v_req.id;

  return jsonb_build_object(
    'ok',true,
    'status','pending',
    'request_code',v_code,
    'reviewer_count',v_reviewer_count,
    'reminded_at',now(),
    'next_reminder_at',now()+interval '3 days'
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_request_appointment_view(p_line_user_id text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_ctx private.line_identity_contexts%rowtype;
  v_fp public.family_persons%rowtype;
  v_existing public.permission_requests%rowtype;
  v_id uuid;
  v_code text;
begin
  select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
  perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
  select * into v_ctx from private.line_identity_contexts
  where line_identity_id=v_line.line_identity_id;

  if v_ctx.active_scope<>'family'
     or v_ctx.active_family_id is null
     or v_ctx.active_family_person_id is null then
    raise exception 'family_person_context_required';
  end if;

  select * into v_fp from public.family_persons
  where id=v_ctx.active_family_person_id
    and family_id=v_ctx.active_family_id
    and coalesce(status,'active')='active';
  if not found then raise exception 'family_person_not_found'; end if;

  if not exists(
    select 1 from public.family_memberships fm
    where fm.family_id=v_fp.family_id
      and fm.user_id=v_line.user_id
      and fm.status='active'
  ) then raise exception 'family_context_not_accessible'; end if;

  if not private.family_person_is_visible_to_user(v_line.user_id,v_fp.id) then
    raise exception 'family_person_not_visible';
  end if;

  if private.user_can_access_family_person(v_line.user_id,v_fp.id,'appointments','view') then
    return jsonb_build_object(
      'status','already_allowed',
      'already_allowed',true,
      'person_name',private.family_person_label_for_viewer(v_line.user_id,v_fp.id)
    );
  end if;

  select pr.* into v_existing
  from public.permission_requests pr
  where pr.family_id=v_fp.family_id
    and pr.family_person_id=v_fp.id
    and pr.requester_user_id=v_line.user_id
    and pr.request_type='permission'
    and pr.resource='appointments'
    and pr.requested_action='view'
    and pr.status='pending'
  order by pr.created_at desc
  limit 1;

  if found then
    v_code:=substr(
      encode(digest(v_existing.id::text||':'||v_line.line_identity_id::text,'sha256'),'hex'),
      1,12
    );
    return jsonb_build_object(
      'status','pending',
      'already_pending',true,
      'request_code',v_code,
      'person_name',private.family_person_label_for_viewer(v_line.user_id,v_fp.id),
      'requested_at',v_existing.created_at,
      'next_reminder_at',coalesce(v_existing.last_reminded_at,v_existing.created_at)+interval '3 days'
    );
  end if;

  insert into public.permission_requests(
    family_id,requester_user_id,family_person_id,
    request_type,resource,requested_action,reason,status,
    request_payload,created_at,updated_at,reminder_count
  ) values(
    v_fp.family_id,v_line.user_id,v_fp.id,
    'permission','appointments','view',
    coalesce(nullif(btrim(p_reason),''),'ขอสิทธิ์ดูนัดหมายของบุคคลนี้'),
    'pending',
    jsonb_build_object('source','appointment_denied_card','resource','appointments','action','view'),
    now(),now(),0
  )
  returning id into v_id;

  v_code:=substr(
    encode(digest(v_id::text||':'||v_line.line_identity_id::text,'sha256'),'hex'),
    1,12
  );

  insert into public.audit_logs(
    family_id,actor_user_id,target_user_id,family_person_id,
    event_type,resource,record_id,new_data,description,created_at
  ) values(
    v_fp.family_id,v_line.user_id,v_line.user_id,v_fp.id,
    'appointment_view_access_requested','appointments',v_id,
    jsonb_build_object('requested_action','view','source','appointment_denied_card'),
    'Requested appointment view access from LINE',now()
  );

  return jsonb_build_object(
    'status','pending',
    'already_pending',false,
    'request_code',v_code,
    'person_name',private.family_person_label_for_viewer(v_line.user_id,v_fp.id),
    'requested_at',now(),
    'next_reminder_at',now()+interval '3 days'
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_request_group_link(p_line_user_id text, p_line_group_id text, p_family_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_actor uuid;
  v_family public.families%rowtype;
  v_channel public.family_channels%rowtype;
  v_req public.line_group_link_requests%rowtype;
  v_code text:=lower(btrim(coalesce(p_family_code,'')));
  v_count integer;
  v_reviewer record;
  v_reviewer_count integer:=0;
  v_requester_label text;
begin
  select li.user_id into v_actor
  from public.line_identities li
  where li.line_user_id=p_line_user_id
    and li.is_active=true
    and li.onboarding_status='ready'
  order by li.updated_at desc nulls last,li.created_at desc
  limit 1;
  if v_actor is null then raise exception 'line_identity_not_ready'; end if;

  select * into v_channel
  from public.family_channels
  where channel_type='line_group'
    and external_channel_id=btrim(p_line_group_id)
    and status in ('pending_link','active')
  limit 1;
  if v_channel.id is null then raise exception 'line_group_not_seen'; end if;

  select count(*) into v_count
  from public.families f
  join public.family_memberships fm on fm.family_id=f.id
  where fm.user_id=v_actor
    and fm.status='active'
    and coalesce(f.status,'active')='active'
    and (lower(f.id::text) like v_code||'%' or lower(coalesce(f.family_code,''))=v_code);
  if v_count=0 then raise exception 'family_not_found_or_not_member'; end if;
  if v_count>1 then raise exception 'family_code_ambiguous'; end if;

  select f.* into v_family
  from public.families f
  join public.family_memberships fm on fm.family_id=f.id
  where fm.user_id=v_actor
    and fm.status='active'
    and coalesce(f.status,'active')='active'
    and (lower(f.id::text) like v_code||'%' or lower(coalesce(f.family_code,''))=v_code)
  limit 1;

  if exists(
    select 1 from public.family_channel_family_links l
    where l.family_channel_id=v_channel.id
      and l.family_id=v_family.id
      and l.status='active'
  ) then
    raise exception 'line_group_family_already_linked';
  end if;

  if private.user_has_family_role(v_actor,v_family.id,array['owner','admin']) then
    raise exception 'manager_should_link_directly';
  end if;

  if coalesce((
    select p.can_request_link
    from public.family_line_group_request_permissions p
    where p.family_id=v_family.id and p.user_id=v_actor
  ),false)=false then
    raise exception 'line_group_request_permission_denied';
  end if;

  insert into public.line_group_link_requests(
    family_channel_id,family_id,requested_by,status,requested_at,created_at,updated_at
  ) values(
    v_channel.id,v_family.id,v_actor,'pending',now(),now(),now()
  )
  on conflict(family_channel_id,family_id) where status='pending'
  do update set
    requested_by=excluded.requested_by,
    requested_at=now(),
    reviewed_by=null,
    reviewed_at=null,
    review_note=null,
    updated_at=now()
  returning * into v_req;

  for v_reviewer in
    select distinct fm.user_id
    from public.family_memberships fm
    where fm.family_id=v_family.id
      and fm.status='active'
      and private.user_has_family_role(fm.user_id,v_family.id,array['owner','admin'])
      and exists(
        select 1 from public.line_identities li
        where li.user_id=fm.user_id
          and li.is_active=true
          and li.onboarding_status='ready'
      )
  loop
    v_requester_label:=private.family_user_label_for_viewer(
      v_reviewer.user_id,v_family.id,v_actor
    );

    insert into public.notifications(
      family_id,recipient_user_id,event_type,title,message,related_record_id,
      channel,priority,status,scheduled_for,next_attempt_at,payload,dedupe_key,
      created_at,updated_at
    ) values(
      v_family.id,v_reviewer.user_id,'line_group_link_request',
      '🏠 มีคำขอเชื่อม LINE กลุ่ม',
      concat(
        v_requester_label,' ขอเชื่อม LINE กลุ่ม “',
        coalesce(nullif(btrim(v_channel.channel_name),''),'LINE กลุ่ม'),
        '” เข้ากับ ',coalesce(nullif(btrim(v_family.family_name),''),'ครอบครัว')
      ),
      v_req.id,'line','normal','pending',now(),now(),
      jsonb_build_object(
        'request_code',substr(v_req.id::text,1,12),
        'group_code',substr(v_channel.id::text,1,12),
        'group_name',coalesce(nullif(btrim(v_channel.channel_name),''),'LINE กลุ่ม'),
        'family_code',substr(v_family.id::text,1,12),
        'family_name',coalesce(nullif(btrim(v_family.family_name),''),'ครอบครัว'),
        'requested_by_name',v_requester_label
      ),
      'line-group-link-request:'||v_req.id::text||':'||v_reviewer.user_id::text,
      now(),now()
    )
    on conflict(dedupe_key) where dedupe_key is not null
    do update set
      title=excluded.title,
      message=excluded.message,
      payload=excluded.payload,
      status='pending',
      scheduled_for=now(),
      next_attempt_at=now(),
      last_error=null,
      updated_at=now();

    v_reviewer_count:=v_reviewer_count+1;
  end loop;

  insert into public.audit_logs(
    family_id,actor_user_id,event_type,resource,record_id,new_data,description
  ) values(
    v_family.id,v_actor,'line_group_link_requested','line_group_link_request',v_req.id,
    jsonb_build_object(
      'family_channel_id',v_channel.id,
      'group_name',v_channel.channel_name,
      'reviewer_count',v_reviewer_count
    ),
    'สมาชิกที่ได้รับอนุญาตส่งคำขอเชื่อม LINE กลุ่มเข้ากับครอบครัว'
  );

  return jsonb_build_object(
    'ok',true,
    'request_code',substr(v_req.id::text,1,12),
    'group_name',coalesce(nullif(btrim(v_channel.channel_name),''),'LINE กลุ่ม'),
    'family_name',coalesce(nullif(btrim(v_family.family_name),''),'ครอบครัว'),
    'reviewer_count',v_reviewer_count
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_restore_recycle_item(p_line_user_id text, p_trash_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_ctx private.line_identity_contexts%rowtype;
  v_rb private.phms_recycle_bin%rowtype;
  v_allowed boolean:=false;
  v_status text;
  v_reg jsonb;
begin
  select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
  perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
  select * into v_ctx from private.line_identity_contexts where line_identity_id=v_line.line_identity_id;
  if v_ctx.active_scope<>'family' or v_ctx.active_family_id is null then raise exception 'family_context_required'; end if;

  select rb.* into v_rb
  from private.phms_recycle_bin rb
  where rb.family_id=v_ctx.active_family_id
    and rb.restored_at is null
    and substr(encode(digest(rb.id::text||':'||v_line.line_identity_id::text,'sha256'),'hex'),1,12)=lower(btrim(p_trash_code))
  order by rb.trashed_at desc
  limit 1;
  if not found then raise exception 'recycle_item_not_found'; end if;

  perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);

  if v_rb.family_person_id is null then
    v_allowed:=private.is_family_owner(v_rb.family_id);
  elsif v_rb.resource='medication' then
    v_allowed:=private.can_access_family_person(v_rb.family_person_id,'medications','update');
  elsif v_rb.resource in ('appointment','appointment_document_link') then
    v_allowed:=private.can_access_family_person(v_rb.family_person_id,'appointments','update');
  elsif v_rb.resource in ('health','document') then
    v_allowed:=private.can_access_family_person(v_rb.family_person_id,'health_data','update');
  elsif v_rb.resource='storage_asset' and coalesce(v_rb.snapshot->>'permission_resource','health')='appointments' then
    v_allowed:=private.can_access_family_person(v_rb.family_person_id,'appointments','update');
  elsif v_rb.resource='storage_asset' and coalesce(v_rb.snapshot->>'permission_resource','health')='medications' then
    v_allowed:=private.can_access_family_person(v_rb.family_person_id,'medications','update');
  else
    v_allowed:=private.can_access_family_person(v_rb.family_person_id,'health_data','update');
  end if;
  if not v_allowed then raise exception 'recycle_restore_permission_denied'; end if;

  if v_rb.resource='medication' then
    update public.person_medications
    set status=coalesce(nullif(v_rb.snapshot->>'status',''),'regular'),
        start_date=nullif(v_rb.snapshot->>'start_date','')::date,
        end_date=nullif(v_rb.snapshot->>'end_date','')::date,
        deleted_at=nullif(v_rb.snapshot->>'deleted_at','')::timestamptz,
        updated_at=now()
    where id=v_rb.record_id;
    if not found then raise exception 'recycle_source_record_missing'; end if;

    for v_reg in select value from jsonb_array_elements(coalesce(v_rb.snapshot->'_regimens','[]'::jsonb))
    loop
      update public.medication_regimens
      set is_current=coalesce((v_reg->>'is_current')::boolean,false),
          effective_to=nullif(v_reg->>'effective_to','')::timestamptz,
          deleted_at=nullif(v_reg->>'deleted_at','')::timestamptz,
          updated_at=now()
      where id=(v_reg->>'id')::uuid and person_medication_id=v_rb.record_id;
    end loop;

  elsif v_rb.resource='appointment' then
    v_status:=coalesce(nullif(v_rb.snapshot->>'status',''),'scheduled');
    update public.appointments
    set status=v_status,
        deleted_at=nullif(v_rb.snapshot->>'deleted_at','')::timestamptz,
        cancelled_at=nullif(v_rb.snapshot->>'cancelled_at','')::timestamptz,
        cancel_reason=nullif(v_rb.snapshot->>'cancel_reason',''),
        last_change_reason='restored_from_recycle_bin',
        updated_at=now()
    where id=v_rb.record_id;
    if not found then raise exception 'recycle_source_record_missing'; end if;
    perform private.phms_sync_auto_appointment_reminders(now());

  elsif v_rb.resource='health' then
    update public.health_measurements
    set deleted_at=nullif(v_rb.snapshot->>'deleted_at','')::timestamptz
    where id=v_rb.record_id;
    if not found then raise exception 'recycle_source_record_missing'; end if;

  elsif v_rb.resource='document' then
    update public.medical_documents
    set deleted_at=nullif(v_rb.snapshot->>'deleted_at','')::timestamptz,updated_at=now()
    where id=v_rb.record_id;
    if not found then raise exception 'recycle_source_record_missing'; end if;

  elsif v_rb.resource='storage_asset' then
    update public.phms_storage_assets
    set deleted_at=nullif(v_rb.snapshot->>'deleted_at','')::timestamptz,
        lifecycle_state=coalesce(nullif(v_rb.snapshot->>'lifecycle_state',''),case when bucket_id='phms-intake-temp' then 'temporary' when bucket_id='phms-exports' then 'generated' else 'confirmed' end),
        updated_at=now()
    where id=v_rb.record_id;
    if not found then raise exception 'recycle_source_record_missing'; end if;

  elsif v_rb.resource='appointment_document_link' then
    insert into public.appointment_document_links(
      id,appointment_id,medical_document_id,storage_asset_id,link_kind,note,created_by,created_at
    ) values(
      v_rb.record_id,
      (v_rb.snapshot->>'appointment_id')::uuid,
      nullif(v_rb.snapshot->>'medical_document_id','')::uuid,
      nullif(v_rb.snapshot->>'storage_asset_id','')::uuid,
      coalesce(nullif(v_rb.snapshot->>'link_kind',''),'result'),
      nullif(v_rb.snapshot->>'note',''),
      nullif(v_rb.snapshot->>'created_by','')::uuid,
      coalesce(nullif(v_rb.snapshot->>'created_at','')::timestamptz,now())
    )
    on conflict(id) do nothing;
  else
    raise exception 'recycle_resource_not_supported';
  end if;

  update private.phms_recycle_bin
  set restored_by=v_line.user_id,restored_at=now(),updated_at=now()
  where id=v_rb.id;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    old_data,new_data,description,created_at
  ) values(
    v_rb.family_id,v_line.user_id,v_rb.family_person_id,'recycle_restored',v_rb.resource,v_rb.record_id,
    jsonb_build_object('trash_id',v_rb.id,'trashed_at',v_rb.trashed_at),
    jsonb_build_object('restored_at',now()),
    'Restored record from PHMS recycle bin',now()
  );

  return jsonb_build_object(
    'ok',true,'trash_code',lower(btrim(p_trash_code)),
    'resource',v_rb.resource,'record_code',substr(v_rb.record_id::text,1,12)
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_save_appointment_notification_template(p_line_user_id text, p_record_code text, p_template_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_appt public.appointments%rowtype;
  v_s record;
  v_template_id uuid;
  v_name text:=btrim(coalesce(p_template_name,''));
begin
  if length(v_name)<1 or length(v_name)>80 then raise exception 'invalid_template_name'; end if;
  select * into v_ref
  from private.phms_find_crud_record(p_line_user_id,'appointment',p_record_code,'update')
  limit 1;

  if not coalesce((
    select (coalesce((a.v->>'is_primary_caregiver')::boolean,false)
         or coalesce((a.v->>'is_self_manager')::boolean,false)
         or coalesce((a.v->>'is_authorized_helper')::boolean,false))
    from (select public.phms_line_appointment_action_capabilities(p_line_user_id,p_record_code) v) a
  ),false) then
    raise exception 'appointment_notification_permission_denied';
  end if;
  select * into v_appt
  from public.appointments
  where id=v_ref.record_id and deleted_at is null;

  select coalesce(s.days_before,array[3]) days_before,
         coalesce(s.local_time,'09:00'::time) local_time,
         coalesce(s.recipient_mode,'default') recipient_mode
  into v_s
  from (select 1) x
  left join public.appointment_notification_settings s on s.appointment_id=v_appt.id;

  select id into v_template_id
  from public.family_notification_templates
  where family_id=v_appt.family_id
    and is_active=true
    and lower(btrim(template_name))=lower(v_name)
  limit 1;

  if v_template_id is null then
    insert into public.family_notification_templates(
      family_id,template_name,days_before,local_time,timezone,recipient_mode,
      is_active,created_by,updated_by
    ) values(
      v_appt.family_id,v_name,v_s.days_before,v_s.local_time,'Asia/Bangkok',
      v_s.recipient_mode,true,v_ref.actor_user_id,v_ref.actor_user_id
    )
    returning id into v_template_id;
  else
    update public.family_notification_templates
    set days_before=v_s.days_before,
        local_time=v_s.local_time,
        recipient_mode=v_s.recipient_mode,
        updated_by=v_ref.actor_user_id,
        updated_at=now()
    where id=v_template_id;

    delete from public.family_notification_template_targets
    where template_id=v_template_id;
  end if;

  insert into public.family_notification_template_targets(
    template_id,target_type,target_user_id,enabled
  )
  select v_template_id,'user',t.user_id,true
  from public.appointment_notification_user_targets t
  where t.appointment_id=v_appt.id and t.enabled=true
  on conflict do nothing;

  insert into public.family_notification_template_targets(
    template_id,target_type,family_channel_id,enabled
  )
  select distinct v_template_id,'line_group',fc.id,true
  from public.appointment_line_group_targets gt
  join public.family_channels fc
    on fc.channel_type='line_group'
   and fc.external_channel_id=gt.line_group_id
   and fc.status='active'
  join public.family_channel_family_links l
    on l.family_channel_id=fc.id
   and l.family_id=v_appt.family_id
   and l.status='active'
  where gt.appointment_id=v_appt.id and gt.status='active'
  on conflict do nothing;

  return jsonb_build_object(
    'ok',true,
    'template_code',substr(v_template_id::text,1,12),
    'template_name',v_name
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_select_home_alert_owner_v1(p_line_user_id text, p_selection_code text, p_resource text, p_record_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_line record;
 v_fp record;
 v_resource text := lower(btrim(coalesce(p_resource,'')));
 v_code text := lower(btrim(coalesce(p_record_code,'')));
 v_found boolean := false;
begin
 if v_resource not in ('appointments','medications') then raise exception 'invalid_alert_resource'; end if;
 if p_selection_code !~* '^[a-f0-9]{12}$' or v_code !~* '^([a-f0-9]{8}-[a-f0-9]{3}|[a-f0-9]{12})$' then
   raise exception 'invalid_alert_record_code';
 end if;
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 if v_line.user_id is null then raise exception 'account_required'; end if;
 select fp.id as family_person_id,fp.family_id,fp.person_id
 into v_fp
 from public.family_persons fp
 join public.persons pe on pe.id=fp.person_id
 join public.family_memberships fm on fm.family_id=fp.family_id
   and fm.user_id=v_line.user_id and fm.status='active'
 join public.families f on f.id=fp.family_id
 where substr(encode(digest(fp.id::text||':'||v_line.line_identity_id::text,'sha256'),'hex'),1,12)=lower(p_selection_code)
   and fp.setup_status='ready'
   and coalesce(fp.status,'active')='active'
   and coalesce(pe.status,'active')='active'
   and coalesce(f.status,'active')='active'
   and private.family_person_is_visible_to_user(v_line.user_id,fp.id)
   and private.user_can_see_family_person(v_line.user_id,fp.id)
   and private.user_can_access_family_person(v_line.user_id,fp.id,v_resource,'view')
 limit 1;
 if not found then raise exception 'home_alert_access_denied'; end if;
 if v_resource='appointments' then
  select exists(
   select 1 from public.appointments a
   where a.person_id=v_fp.person_id and a.deleted_at is null
     and substr(a.id::text,1,12)=v_code
  ) into v_found;
 else
  select exists(
   select 1 from public.person_medications m
   where m.person_id=v_fp.person_id and m.deleted_at is null
     and substr(m.id::text,1,12)=v_code
  ) into v_found;
 end if;
 if not v_found then raise exception 'home_alert_record_not_found'; end if;
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 update private.line_identity_contexts
 set active_scope='family',
     active_family_id=v_fp.family_id,
     active_family_person_id=v_fp.family_person_id,
     context_changed_at=now(),updated_at=now()
 where line_identity_id=v_line.line_identity_id and user_id=v_line.user_id;
 if not found then raise exception 'home_alert_context_unavailable'; end if;
 return jsonb_build_object('ok',true,'resource',v_resource);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_set_five_category_access(p_line_user_id text, p_member_code text, p_person_code text, p_resource text, p_level text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth'
AS $function$
declare m record;p record; v text:=lower(trim(coalesce(p_resource,''))); l text:=lower(trim(coalesce(p_level,'')));n integer;
begin
 if v not in ('appointments','medications','health_data','documents','expenses') or l not in ('none','view','manage','inherit') then raise exception 'invalid_permission_level';end if;
 select * into m from private.resolve_line_family_member(p_line_user_id,p_member_code);
 select * into p from private.resolve_line_family_person_code(p_line_user_id,p_person_code);
 if m.family_id<>p.family_id then raise exception 'family_scope_mismatch';end if;
 if not private.phms_can_manage_medical_grants(m.actor_user_id,p.family_person_id) then raise exception 'permission_management_denied';end if;
 if private.phms_is_medical_primary(m.target_user_id,p.family_person_id) then raise exception 'cannot_change_primary_grants';end if;
 if exists(select 1 from public.family_persons fp join public.persons person on person.id=fp.person_id where fp.id=p.family_person_id and person.linked_user_id=m.target_user_id) then raise exception 'use_self_access_settings';end if;
 update public.person_five_category_policies pol
 set overrides=case when l='inherit' then pol.overrides-v else jsonb_set(pol.overrides,array[v],to_jsonb(l),true) end,
 updated_by=m.actor_user_id,updated_at=now()
 where pol.family_person_id=p.family_person_id and pol.user_id=m.target_user_id and pol.family_id=m.family_id;
 get diagnostics n=row_count;
 if n=0 then raise exception 'base_access_not_configured';end if;
 return jsonb_build_object('ok',true,'resource',v,'level',l);
end $function$

CREATE OR REPLACE FUNCTION public.phms_line_set_five_category_base_access(p_line_user_id text, p_member_code text, p_person_code text, p_level text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth'
AS $function$
declare m record;p record; lvl text:=lower(trim(coalesce(p_level,'')));
begin
 if lvl not in ('none','view','manage') then raise exception 'invalid_base_level';end if;
 select * into m from private.resolve_line_family_member(p_line_user_id,p_member_code);
 select * into p from private.resolve_line_family_person_code(p_line_user_id,p_person_code);
 if m.family_id<>p.family_id then raise exception 'family_scope_mismatch';end if;
 if not private.phms_can_manage_medical_grants(m.actor_user_id,p.family_person_id) then raise exception 'permission_management_denied';end if;
 if private.phms_is_medical_primary(m.target_user_id,p.family_person_id) then raise exception 'cannot_change_primary_grants';end if;
 if exists(select 1 from public.family_persons fp join public.persons person on person.id=fp.person_id where fp.id=p.family_person_id and person.linked_user_id=m.target_user_id) then raise exception 'use_self_access_settings';end if;
 insert into public.person_five_category_policies(family_id,family_person_id,user_id,base_level,overrides,updated_by)
 values(m.family_id,p.family_person_id,m.target_user_id,lvl,'{}'::jsonb,m.actor_user_id)
 on conflict(family_person_id,user_id) do update set base_level=excluded.base_level,overrides='{}'::jsonb,updated_by=excluded.updated_by,updated_at=now();
 return jsonb_build_object('ok',true,'base_level',lvl,'overrides','{}'::jsonb);
end $function$

CREATE OR REPLACE FUNCTION public.phms_line_set_notification_target(p_line_user_id text, p_batch_id uuid, p_target_type text, p_target_code text, p_enabled boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_line record;
 v_batch public.data_intake_commit_batches%rowtype;
 v_ds public.data_intake_sessions%rowtype;
 v_user uuid;
 v_group text;
 v_res text;
 v_person_name text;
 v_title text;
 v_message text;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 select * into v_batch
 from public.data_intake_commit_batches b
 where b.id=p_batch_id and b.requested_by=v_line.user_id;
 if not found then raise exception 'commit_batch_not_found'; end if;

 select * into v_ds
 from public.data_intake_sessions s
 where s.id=v_batch.session_id;
 if not found then raise exception 'intake_session_not_found'; end if;

 v_res:=case
   when coalesce((v_batch.result#>>'{resource_counts,appointments}')::int,0)>0 then 'appointment'
   when coalesce((v_batch.result#>>'{resource_counts,medications}')::int,0)>0 then 'medication'
   else 'health'
 end;

 select coalesce(
   private.person_label_for_viewer(v_line.user_id,p.id),
   nullif(btrim(p.nickname),''),
   nullif(btrim(concat_ws(' ',p.first_name,p.last_name)),''),
   'บุคคลในครอบครัว'
 )
 into v_person_name
 from public.persons p where p.id=v_ds.person_id;

 v_title:=case v_res
   when 'appointment' then '📅 มีนัดหมายใหม่'
   when 'medication' then '💊 มีข้อมูลยาใหม่'
   else '❤️ มีข้อมูลสุขภาพใหม่'
 end;
 v_message:=coalesce(v_person_name,'บุคคลในครอบครัว')||
   case v_res
     when 'appointment' then ' มีนัดหมายที่เพิ่งบันทึกในอิ่มอุ่น'
     when 'medication' then ' มีข้อมูลยาที่เพิ่งบันทึกในอิ่มอุ่น'
     else ' มีข้อมูลสุขภาพที่เพิ่งบันทึกในอิ่มอุ่น'
   end;

 if p_target_type='user' then
   select fm.user_id into v_user
   from public.family_memberships fm
   where fm.family_id=v_ds.family_id
     and fm.status='active'
     and substr(encode(digest(fm.user_id::text||':'||v_line.line_identity_id::text||':'||v_ds.family_id::text,'sha256'),'hex'),1,12)=lower(btrim(p_target_code))
   limit 1;
   if v_user is null then raise exception 'notification_target_user_not_found'; end if;

   insert into public.record_notification_targets(
     family_id,person_id,resource,intake_batch_id,target_type,target_user_id,enabled,created_by
   )
   values(v_ds.family_id,v_ds.person_id,v_res,p_batch_id,'user',v_user,p_enabled,v_line.user_id)
   on conflict(coalesce(record_id,intake_batch_id),target_user_id,resource) where target_type='user'
   do update set enabled=excluded.enabled,updated_at=now();

   if p_enabled and v_res<>'appointment' then
     insert into public.notifications(
      family_id,recipient_user_id,event_type,title,message,channel,priority,status,person_id,
      scheduled_for,next_attempt_at,payload,dedupe_key,created_at,updated_at
     )
     values(
      v_ds.family_id,v_user,'record_shared',v_title,v_message,'line','normal','pending',v_ds.person_id,
      now(),now(),jsonb_build_object('resource',v_res,'intake_batch_id',p_batch_id),
      'record-share:'||p_batch_id::text||':user:'||v_user::text,now(),now()
     )
     on conflict(dedupe_key) do update set
      status='pending',scheduled_for=now(),next_attempt_at=now(),updated_at=now();
   end if;

 elsif p_target_type='line_group' then
   if not private.user_has_family_role(v_line.user_id,v_ds.family_id,array['owner','admin']) then
     raise exception 'group_notification_permission_denied';
   end if;

   select fc.external_channel_id into v_group
   from public.family_channel_family_links l
   join public.family_channels fc on fc.id=l.family_channel_id
   where l.family_id=v_ds.family_id
     and l.status='active'
     and fc.channel_type='line_group'
     and fc.status='active'
     and substr(encode(digest(fc.external_channel_id||':'||v_line.line_identity_id::text,'sha256'),'hex'),1,12)=lower(btrim(p_target_code))
   limit 1;
   if v_group is null then raise exception 'notification_target_group_not_found'; end if;

   insert into public.record_notification_targets(
     family_id,person_id,resource,intake_batch_id,target_type,line_group_id,enabled,created_by
   )
   values(v_ds.family_id,v_ds.person_id,v_res,p_batch_id,'line_group',v_group,p_enabled,v_line.user_id)
   on conflict(coalesce(record_id,intake_batch_id),line_group_id,resource) where target_type='line_group'
   do update set enabled=excluded.enabled,updated_at=now();

   if p_enabled and v_res<>'appointment' then
     insert into public.notifications(
      family_id,recipient_user_id,event_type,title,message,channel,priority,status,person_id,
      scheduled_for,next_attempt_at,payload,dedupe_key,created_at,updated_at
     )
     values(
      v_ds.family_id,null,'record_shared_group',v_title,v_message,'line','normal','pending',v_ds.person_id,
      now(),now(),
      jsonb_build_object(
        'resource',v_res,
        'intake_batch_id',p_batch_id,
        'line_destination_type','group',
        'line_destination_id',v_group,
        'read_only',true
      ),
      'record-share:'||p_batch_id::text||':group:'||v_group,now(),now()
     )
     on conflict(dedupe_key) do update set
      status='pending',scheduled_for=now(),next_attempt_at=now(),updated_at=now();
   end if;

 else
   raise exception 'invalid_notification_target_type';
 end if;

 return jsonb_build_object(
   'status','ok',
   'enabled',p_enabled,
   'target_type',p_target_type,
   'resource',v_res
 );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_set_person_card_color(p_line_user_id text, p_person_code text, p_card_color text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare v_line record;v_ctx private.line_identity_contexts%rowtype;v_fp public.family_persons%rowtype;
begin
 if p_card_color is not null and upper(p_card_color) !~ '^#[0-9A-F]{6}$' then raise exception 'invalid_card_color';end if;
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select * into v_ctx from private.line_identity_contexts where line_identity_id=v_line.line_identity_id;
 if v_ctx.active_scope<>'family' or v_ctx.active_family_id is null then raise exception 'family_context_required';end if;
 select * into v_fp from public.family_persons fp
 where fp.family_id=v_ctx.active_family_id and fp.status='active'
 and substr(encode(digest(fp.id::text||':'||v_line.line_identity_id::text,'sha256'),'hex'),1,12)=p_person_code limit 1;
 if not found then raise exception 'person_not_found_or_inaccessible';end if;
 if not private.user_can_access_family_person(v_line.user_id,v_fp.id,'persons','update') then raise exception 'permission_denied';end if;
 insert into public.person_ui_preferences(person_id,card_color,updated_by,updated_at)
 values(v_fp.person_id,p_card_color,v_line.user_id,now())
 on conflict(person_id) do update set card_color=excluded.card_color,updated_by=excluded.updated_by,updated_at=now();
 return jsonb_build_object('ok',true,'person_code',p_person_code,'card_color',p_card_color);
end $function$

CREATE OR REPLACE FUNCTION public.phms_line_storage_asset_capabilities(p_line_user_id text, p_asset_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_ctx private.line_identity_contexts%rowtype;
  v_asset public.phms_storage_assets%rowtype;
  v_fp uuid;
  v_res text;
  v_can boolean:=false;
  v_can_reassign boolean:=false;
begin
  select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
  perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
  select * into v_ctx from private.line_identity_contexts where line_identity_id=v_line.line_identity_id;

  select * into v_asset
  from public.phms_storage_assets
  where id=p_asset_id and deleted_at is null and lifecycle_state<>'deleted';
  if not found then
    return jsonb_build_object(
      'can_view',false,'can_edit',false,'can_reassign_owner',false,'reason','asset_not_found'
    );
  end if;

  v_res:=case v_asset.permission_resource
    when 'appointments' then 'appointments'
    when 'medications' then 'medications'
    else 'health_data' end;

  v_can_reassign :=
    v_asset.lifecycle_state='temporary'
    and v_asset.created_by=v_line.user_id
    and not exists(
      select 1 from public.medical_documents d
      where d.storage_asset_id=v_asset.id and d.deleted_at is null
    )
    and not exists(
      select 1 from public.medication_media m
      where m.storage_asset_id=v_asset.id and m.deleted_at is null
    )
    and not exists(
      select 1 from public.appointment_document_links l
      where l.storage_asset_id=v_asset.id
    )
    and not exists(
      select 1
      from public.data_intake_sources s
      join public.data_intake_sessions ds on ds.id=s.session_id
      where s.storage_asset_id=v_asset.id
        and ds.status in ('confirmed','committed','cancelled','rejected')
    );

  if v_ctx.active_scope='family' and v_ctx.active_family_id is not null then
    select fp.id into v_fp
    from public.family_persons fp
    where fp.family_id=v_ctx.active_family_id
      and fp.person_id=v_asset.person_id
      and coalesce(fp.status,'active')='active'
    limit 1;

    if v_fp is null then
      return jsonb_build_object(
        'can_view',false,'can_edit',false,
        'can_reassign_owner',false,'resource',v_res,'reason','outside_family'
      );
    end if;

    perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
    v_can:=private.can_access_family_person(v_fp,v_res,'update');
    return jsonb_build_object(
      'can_view',private.can_access_family_person(v_fp,v_res,'view'),
      'can_edit',v_can,
      'can_reassign_owner',v_can_reassign,
      'resource',v_res
    );
  end if;

  if exists(
    select 1 from public.persons p
    where p.id=v_asset.person_id
      and p.linked_user_id=v_line.user_id
      and coalesce(p.status,'active')='active'
  ) then
    return jsonb_build_object(
      'can_view',true,'can_edit',true,
      'can_reassign_owner',v_can_reassign,
      'resource',v_res
    );
  end if;

  return jsonb_build_object(
    'can_view',false,'can_edit',false,
    'can_reassign_owner',false,'resource',v_res,'reason','context_not_editable'
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_submit_bug_report(p_line_user_id text, p_description text DEFAULT NULL::text, p_image_message_id text DEFAULT NULL::text, p_source_screen text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth'
AS $function$
declare v_line record; v_ctx private.line_identity_contexts%rowtype; v_id uuid;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 if nullif(btrim(coalesce(p_description,'')),'') is null and nullif(btrim(coalesce(p_image_message_id,'')),'') is null then raise exception 'empty_bug_report'; end if;
 select * into v_ctx from private.line_identity_contexts where line_identity_id=v_line.line_identity_id;
 insert into public.phms_bug_reports(line_user_id,reporter_user_id,family_id,person_id,description,line_image_message_id,source_screen)
 values(p_line_user_id,v_line.user_id,v_ctx.active_family_id,(select person_id from public.family_persons where id=v_ctx.active_family_person_id),nullif(left(btrim(p_description),4000),''),nullif(left(btrim(p_image_message_id),128),''),nullif(left(btrim(p_source_screen),150),''))
 returning id into v_id;
 update public.phms_bug_report_sessions set report_id=v_id where line_user_id=p_line_user_id and expires_at>now();
 return jsonb_build_object('ok',true,'report_code',left(v_id::text,8));
end $function$

CREATE OR REPLACE FUNCTION public.phms_line_trash_record(p_line_user_id text, p_resource text, p_record_code text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_reason text:=coalesce(nullif(btrim(p_reason),''),'moved to recycle bin by user');
begin
  select * into v_ref
  from private.phms_find_crud_record(p_line_user_id,p_resource,p_record_code,'delete')
  limit 1;

  perform set_config('request.jwt.claim.sub',v_ref.actor_user_id::text,true);

  if v_ref.resource_key='medication' then
    update public.person_medications
    set deleted_at=now(),updated_at=now()
    where id=v_ref.record_id and deleted_at is null;
  elsif v_ref.resource_key='appointment' then
    update public.appointments
    set deleted_at=now(),updated_at=now(),last_change_reason=v_reason
    where id=v_ref.record_id and deleted_at is null;
  elsif v_ref.resource_key='health' then
    update public.health_measurements
    set deleted_at=now()
    where id=v_ref.record_id and deleted_at is null;
  elsif v_ref.resource_key='document' then
    update public.medical_documents
    set deleted_at=now(),updated_at=now()
    where id=v_ref.record_id and deleted_at is null;
  else
    raise exception 'trash_resource_not_supported';
  end if;

  if not found then raise exception 'crud_record_not_found_or_already_trashed'; end if;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    new_data,description,created_at
  ) values(
    v_ref.active_family_id,v_ref.actor_user_id,v_ref.active_family_person_id,
    'recycle_trashed',v_ref.resource_key,v_ref.record_id,
    jsonb_build_object('reason',v_reason),
    'Moved record to recoverable recycle bin',now()
  );

  return jsonb_build_object(
    'ok',true,'resource',v_ref.resource_key,
    'record_code',substr(v_ref.record_id::text,1,12),
    'recoverable',true
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_trash_storage_asset(p_line_user_id text, p_asset_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_ctx private.line_identity_contexts%rowtype;
  v_asset public.phms_storage_assets%rowtype;
  v_fp uuid;
  v_res text;
begin
  select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
  perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
  select * into v_ctx from private.line_identity_contexts where line_identity_id=v_line.line_identity_id;
  if v_ctx.active_scope<>'family' or v_ctx.active_family_id is null then raise exception 'family_context_required'; end if;

  select * into v_asset from public.phms_storage_assets where id=p_asset_id and deleted_at is null;
  if not found then raise exception 'storage_asset_not_found'; end if;

  select fp.id into v_fp
  from public.family_persons fp
  where fp.family_id=v_ctx.active_family_id and fp.person_id=v_asset.person_id and coalesce(fp.status,'active')='active'
  limit 1;
  if v_fp is null then raise exception 'storage_asset_outside_family'; end if;

  perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
  v_res:=case v_asset.permission_resource when 'appointments' then 'appointments' when 'medications' then 'medications' else 'health_data' end;
  if not private.can_access_family_person(v_fp,v_res,'update') then raise exception 'storage_asset_edit_permission_required'; end if;

  update public.phms_storage_assets
  set deleted_at=now(),
      lifecycle_state='deleted',
      metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('delete_reason',coalesce(nullif(btrim(p_reason),''),'removed by user')),
      updated_at=now()
  where id=p_asset_id;

  return jsonb_build_object('ok',true,'asset_id',p_asset_id,'state','deleted','recoverable',true);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_treatment_episode_add_event(p_line_user_id text, p_episode_code text, p_event_type text, p_title text, p_started_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_ended_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_hospital_query text DEFAULT NULL::text, p_summary text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_enc public.encounters%rowtype;
  v_org_id uuid;
  v_type text:=lower(btrim(coalesce(p_event_type,'other')));
  v_h text:=btrim(coalesce(p_hospital_query,''));
begin
  select * into v_ref
  from private.phms_find_treatment_episode_for_line(p_line_user_id,p_episode_code,'update')
  limit 1;

  if nullif(btrim(coalesce(p_title,'')),'') is null then
    raise exception 'treatment_event_title_required';
  end if;
  if p_started_at is not null and p_ended_at is not null and p_ended_at<p_started_at then
    raise exception 'treatment_event_date_range_invalid';
  end if;

  if v_h<>'' then
    select o.id into v_org_id
    from public.healthcare_organizations o
    where o.deleted_at is null
      and (
        lower(btrim(coalesce(o.external_code,'')))=lower(v_h)
        or lower(btrim(o.name))=lower(v_h)
        or lower(btrim(o.name||case when nullif(btrim(coalesce(o.branch_name,'')),'') is not null then ' '||o.branch_name else '' end))=lower(v_h)
        or lower(o.name) like '%'||lower(v_h)||'%'
      )
    order by
      case when lower(btrim(coalesce(o.external_code,'')))=lower(v_h) then 0
           when lower(btrim(o.name))=lower(v_h) then 1 else 2 end,
      o.updated_at desc
    limit 1;
  end if;

  insert into public.encounters(
    person_id,organization_id,encounter_type,started_at,ended_at,reason,summary,status,created_by,treatment_episode_id
  ) values(
    v_ref.person_id,v_org_id,v_type,p_started_at,p_ended_at,btrim(p_title),
    nullif(btrim(coalesce(p_summary,'')),''),
    case when p_ended_at is null and v_type in ('inpatient','admission') then 'in_progress' else 'completed' end,
    v_ref.actor_user_id,v_ref.episode_id
  )
  returning * into v_enc;

  update public.treatment_episodes e
  set
    started_at=case
      when p_started_at is null then e.started_at
      when e.started_at is null then p_started_at
      else least(e.started_at,p_started_at)
    end,
    ended_at=case
      when p_ended_at is null then e.ended_at
      when e.ended_at is null then p_ended_at
      else greatest(e.ended_at,p_ended_at)
    end,
    primary_organization_id=coalesce(e.primary_organization_id,v_org_id),
    updated_at=now()
  where e.id=v_ref.episode_id;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,new_data,description
  ) values(
    v_ref.family_id,v_ref.actor_user_id,v_ref.family_person_id,
    'treatment_episode_event_added','encounter',v_enc.id,to_jsonb(v_enc),
    'เพิ่มเหตุการณ์ในเคสการรักษา'
  );

  return jsonb_build_object(
    'ok',true,
    'episode_code',substr(v_ref.episode_id::text,1,12),
    'encounter_code',substr(v_enc.id::text,1,12),
    'event_type',v_enc.encounter_type,
    'title',v_enc.reason
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_treatment_episode_create(p_line_user_id text, p_title text, p_care_topic text DEFAULT NULL::text, p_started_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_ended_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_summary text DEFAULT NULL::text, p_status text DEFAULT 'active'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ctx record;
  v_episode public.treatment_episodes%rowtype;
  v_status text:=lower(btrim(coalesce(p_status,'active')));
begin
  if nullif(btrim(coalesce(p_title,'')),'') is null then
    raise exception 'treatment_episode_title_required';
  end if;
  if v_status not in ('active','completed','archived') then
    raise exception 'invalid_treatment_episode_status';
  end if;
  if p_started_at is not null and p_ended_at is not null and p_ended_at<p_started_at then
    raise exception 'treatment_episode_date_range_invalid';
  end if;

  select * into v_ctx
  from private.phms_line_active_treatment_context(p_line_user_id,'update')
  limit 1;

  insert into public.treatment_episodes(
    family_id,family_person_id,person_id,title,care_topic,started_at,ended_at,status,summary,created_by
  ) values(
    v_ctx.family_id,v_ctx.family_person_id,v_ctx.person_id,btrim(p_title),
    nullif(btrim(coalesce(p_care_topic,'')),''),
    p_started_at,p_ended_at,v_status,
    nullif(btrim(coalesce(p_summary,'')),''),
    v_ctx.actor_user_id
  )
  returning * into v_episode;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,new_data,description
  ) values(
    v_ctx.family_id,v_ctx.actor_user_id,v_ctx.family_person_id,
    'treatment_episode_created','treatment_episode',v_episode.id,to_jsonb(v_episode),
    'สร้างเคสการรักษา'
  );

  return jsonb_build_object(
    'ok',true,
    'episode_id',v_episode.id,
    'episode_code',substr(v_episode.id::text,1,12),
    'title',v_episode.title,
    'person_name',v_ctx.person_name
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_treatment_episode_link_appointment(p_line_user_id text, p_episode_code text, p_record_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_appt_ref record;
  v_appt public.appointments%rowtype;
  v_old uuid;
begin
  select * into v_ref
  from private.phms_find_treatment_episode_for_line(p_line_user_id,p_episode_code,'update')
  limit 1;

  select * into v_appt_ref
  from private.phms_find_crud_record(p_line_user_id,'appointment',p_record_code,'update')
  limit 1;

  select * into v_appt
  from public.appointments
  where id=v_appt_ref.record_id and deleted_at is null;

  if not found then raise exception 'appointment_not_found'; end if;
  if v_appt.person_id is distinct from v_ref.person_id then
    raise exception 'treatment_episode_person_mismatch';
  end if;

  v_old:=v_appt.treatment_episode_id;

  update public.appointments
  set treatment_episode_id=v_ref.episode_id,updated_at=now()
  where id=v_appt.id;

  if v_appt.encounter_id is not null then
    update public.encounters
    set treatment_episode_id=v_ref.episode_id,updated_at=now()
    where id=v_appt.encounter_id and person_id=v_ref.person_id;
  end if;

  update public.treatment_episodes e
  set
    started_at=case
      when e.started_at is null then v_appt.appointment_at
      else least(e.started_at,v_appt.appointment_at)
    end,
    ended_at=case
      when v_appt.status='completed' then greatest(coalesce(e.ended_at,v_appt.completed_at,v_appt.appointment_at),coalesce(v_appt.completed_at,v_appt.appointment_at))
      else e.ended_at
    end,
    primary_organization_id=coalesce(e.primary_organization_id,v_appt.organization_id),
    updated_at=now()
  where e.id=v_ref.episode_id;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,old_data,new_data,description
  ) values(
    v_ref.family_id,v_ref.actor_user_id,v_ref.family_person_id,
    case when v_old is null then 'treatment_episode_appointment_linked' else 'treatment_episode_appointment_relinked' end,
    'appointment',v_appt.id,
    jsonb_build_object('treatment_episode_id',v_old),
    jsonb_build_object('treatment_episode_id',v_ref.episode_id),
    'เชื่อมนัดเข้ากับเคสการรักษา'
  );

  return jsonb_build_object(
    'ok',true,
    'episode_code',substr(v_ref.episode_id::text,1,12),
    'appointment_code',substr(v_appt.id::text,1,12),
    'changed',v_old is distinct from v_ref.episode_id
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_treatment_episode_link_encounter(p_line_user_id text, p_episode_code text, p_encounter_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_code text:=lower(btrim(coalesce(p_encounter_code,'')));
  v_count int;
  v_enc public.encounters%rowtype;
begin
  select * into v_ref
  from private.phms_find_treatment_episode_for_line(p_line_user_id,p_episode_code,'update')
  limit 1;

  if length(v_code)<8 then raise exception 'encounter_code_too_short'; end if;

  select count(*) into v_count
  from public.encounters e
  where e.person_id=v_ref.person_id and e.deleted_at is null
    and lower(e.id::text) like v_code||'%';
  if v_count=0 then raise exception 'encounter_not_found'; end if;
  if v_count>1 then raise exception 'encounter_code_ambiguous'; end if;

  select * into v_enc
  from public.encounters e
  where e.person_id=v_ref.person_id and e.deleted_at is null
    and lower(e.id::text) like v_code||'%'
  limit 1;

  update public.encounters
  set treatment_episode_id=v_ref.episode_id,updated_at=now()
  where id=v_enc.id;

  update public.appointments
  set treatment_episode_id=v_ref.episode_id,updated_at=now()
  where encounter_id=v_enc.id and deleted_at is null;

  update public.treatment_episodes e
  set
    started_at=case when e.started_at is null then v_enc.started_at else least(e.started_at,coalesce(v_enc.started_at,e.started_at)) end,
    ended_at=case when v_enc.ended_at is null then e.ended_at else greatest(coalesce(e.ended_at,v_enc.ended_at),v_enc.ended_at) end,
    primary_organization_id=coalesce(e.primary_organization_id,v_enc.organization_id),
    updated_at=now()
  where e.id=v_ref.episode_id;

  return jsonb_build_object(
    'ok',true,
    'episode_code',substr(v_ref.episode_id::text,1,12),
    'encounter_code',substr(v_enc.id::text,1,12)
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_try_canonical_commit(p_line_user_id text, p_source_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line public.line_identities%rowtype;
  v_source public.data_intake_sources%rowtype;
  v_ds public.data_intake_sessions%rowtype;
  v_code text:=lower(btrim(coalesce(p_source_code,'')));
  v_count integer;
  v_docs integer;
  v_total integer;
  v_resources text[];
  v_gate jsonb;
begin
  select * into v_line
  from public.line_identities
  where line_user_id=p_line_user_id
    and coalesce(is_active,false)=true
  limit 1;
  if not found or v_line.user_id is null then
    raise exception 'line_identity_not_linked';
  end if;

  select count(*) into v_count
  from public.data_intake_sources s
  where s.submitted_by=v_line.user_id
    and lower(s.id::text) like v_code||'%';
  if v_count=0 then raise exception 'intake_source_not_found'; end if;
  if v_count>1 then raise exception 'intake_source_code_ambiguous'; end if;

  select * into v_source
  from public.data_intake_sources s
  where s.submitted_by=v_line.user_id
    and lower(s.id::text) like v_code||'%'
  limit 1;

  select * into v_ds
  from public.data_intake_sessions
  where id=v_source.session_id;
  if not found then raise exception 'intake_session_not_found'; end if;

  select
    count(*),
    count(*) filter(where candidate_type='medical_document'),
    array_agg(distinct case
      when candidate_type='medication' then 'medication'
      when candidate_type='appointment' then 'appointment'
      when candidate_type in ('health_measurement','measurement') then 'health'
      when candidate_type='medical_document' then 'document'
      else candidate_type
    end) filter(where review_status<>'rejected')
  into v_total,v_docs,v_resources
  from public.data_intake_candidates
  where session_id=v_source.session_id
    and review_status<>'rejected';

  if v_total=0 then
    return jsonb_build_object(
      'ok',false,'committed',false,
      'canonical_commit',false,'reason','candidate_required'
    );
  end if;

  v_gate:=private.phms_real_data_gate_decision(
    v_ds.family_id,v_ds.person_id,v_resources,
    'commit',v_line.user_id,v_total
  );

  if coalesce((v_gate->>'allowed')::boolean,false) is not true then
    return jsonb_build_object(
      'ok',true,'committed',false,
      'canonical_commit',false,
      'reason',coalesce(v_gate->>'reason','real_data_gate_locked'),
      'gate',v_gate
    );
  end if;

  if v_docs=v_total then
    return public.phms_commit_confirmed_document(
      p_line_user_id,v_code
    ) || jsonb_build_object(
      'committed',true,'resource_group','document',
      'pilot_gate',v_gate
    );
  end if;

  if v_docs>0 then
    return jsonb_build_object(
      'ok',false,'committed',false,
      'canonical_commit',false,
      'reason','mixed_document_intake_not_supported'
    );
  end if;

  return public.phms_commit_confirmed_intake(
    p_line_user_id,v_code
  ) || jsonb_build_object(
    'resource_group','clinical',
    'pilot_gate',v_gate
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_unlink_group_family(p_line_user_id text, p_line_group_id text, p_family_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_actor uuid;
  v_fc public.family_channels%rowtype;
  v_family_id uuid;
  v_family public.families%rowtype;
  v_count integer;
  v_next_family uuid;
begin
  select li.user_id into v_actor
  from public.line_identities li
  where li.line_user_id=p_line_user_id
    and li.is_active=true and li.onboarding_status='ready'
  order by li.updated_at desc nulls last,li.created_at desc
  limit 1;
  if v_actor is null then raise exception 'line_identity_not_ready'; end if;

  select * into v_fc
  from public.family_channels
  where channel_type='line_group'
    and external_channel_id=btrim(p_line_group_id)
    and status in ('active','pending_link')
  limit 1
  for update;
  if v_fc.id is null then raise exception 'line_group_not_seen'; end if;

  select count(*),(array_agg(l.family_id order by l.family_id::text))[1]
  into v_count,v_family_id
  from public.family_channel_family_links l
  join public.families f on f.id=l.family_id
  where l.family_channel_id=v_fc.id
    and l.status='active'
    and (
      lower(f.id::text) like lower(btrim(p_family_code))||'%'
      or lower(coalesce(f.family_code,''))=lower(btrim(p_family_code))
    );
  if v_count=0 then raise exception 'group_family_not_found'; end if;
  if v_count>1 then raise exception 'group_family_code_ambiguous'; end if;

  if not private.user_has_family_role(v_actor,v_family_id,array['owner','admin'])
    then raise exception 'group_settings_permission_denied'; end if;

  select * into v_family from public.families where id=v_family_id;

  update public.family_channel_family_links
  set status='disabled',updated_at=now()
  where family_channel_id=v_fc.id and family_id=v_family_id;

  update public.family_channel_query_scopes s
  set enabled=false,updated_by=v_actor,updated_at=now()
  from public.family_persons fp
  where s.family_channel_id=v_fc.id
    and s.family_person_id=fp.id
    and fp.family_id=v_family_id
    and s.enabled=true;

  update public.appointment_line_group_targets gt
  set status='disabled',disabled_at=now(),updated_at=now()
  from public.appointments a
  where gt.appointment_id=a.id
    and gt.line_group_id=v_fc.external_channel_id
    and gt.status='active'
    and a.family_id=v_family_id;

  update public.family_notification_template_targets x
  set enabled=false,updated_at=now()
  from public.family_notification_templates t
  where x.template_id=t.id
    and t.family_id=v_family_id
    and x.target_type='line_group'
    and x.family_channel_id=v_fc.id
    and x.enabled=true;

  select (array_agg(l.family_id order by l.family_id::text))[1] into v_next_family
  from public.family_channel_family_links l
  where l.family_channel_id=v_fc.id and l.status='active';

  update public.family_channels
  set family_id=v_next_family,
      status=case when v_next_family is null then 'pending_link' else 'active' end,
      can_query_bot=case when v_next_family is null then false else can_query_bot end,
      can_receive_notifications=case when v_next_family is null then false else can_receive_notifications end,
      setup_completed_at=case when v_next_family is null then null else setup_completed_at end,
      setup_completed_by=case when v_next_family is null then null else setup_completed_by end,
      ready_sent_at=case when v_next_family is null then null else ready_sent_at end,
      updated_at=now()
  where id=v_fc.id;

  insert into public.audit_logs(
    family_id,actor_user_id,event_type,resource,record_id,new_data,description
  ) values(
    v_family_id,v_actor,'line_group_family_unlinked','family_channel',v_fc.id,
    jsonb_build_object(
      'line_group_id',v_fc.external_channel_id,
      'channel_name',v_fc.channel_name,
      'family_name',v_family.family_name
    ),
    'ยกเลิกการเชื่อม LINE กลุ่มกับครอบครัว'
  );

  perform private.phms_sync_auto_appointment_reminders(now());

  return jsonb_build_object(
    'ok',true,
    'group_name',coalesce(nullif(btrim(v_fc.channel_name),''),'LINE กลุ่ม'),
    'removed_family_name',coalesce(nullif(btrim(v_family.family_name),''),'ครอบครัว'),
    'has_remaining_families',v_next_family is not null
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_wound_series_can_create(p_line_user_id text, p_record_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_ref record;
 v_ctx record;
 v_src public.appointments%rowtype;
 v_existing boolean:=false;
begin
 begin
  select * into v_ref from private.phms_line_appointment_access(p_line_user_id,p_record_code) limit 1;
  if coalesce(v_ref.can_update,false) is not true then
   return jsonb_build_object('can_create',false);
  end if;
  select * into v_ctx from private.phms_line_crud_context(p_line_user_id,'appointment','create') limit 1;
  if v_ctx.target_person_id is distinct from v_ref.person_id then
   return jsonb_build_object('can_create',false);
  end if;
  select * into v_src from public.appointments where id=v_ref.record_id and deleted_at is null;
  if not found then return jsonb_build_object('can_create',false); end if;
  if v_src.status in ('cancelled','no_show','rescheduled')
    or v_src.appointment_at is null
    or nullif(btrim(coalesce(v_src.hospital_name,'')),'') is null then
   return jsonb_build_object('can_create',false);
  end if;
  if coalesce(v_src.title,'') !~* '(ล้างแผล|ทำแผล|ผ่าตัด|เย็บแผล|แผล)' then
   return jsonb_build_object('can_create',false);
  end if;
  select exists(select 1 from private.phms_wound_visit_series where source_appointment_id=v_src.id) into v_existing;
  return jsonb_build_object('can_create',not v_existing,'already_created',v_existing);
 exception when others then
  return jsonb_build_object('can_create',false);
 end;
end
$function$

CREATE OR REPLACE FUNCTION public.phms_line_wound_visit_series_create(p_line_user_id text, p_record_code text, p_interval_days integer, p_future_count integer, p_anchor_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_ref record;
 v_ctx record;
 v_base public.appointments%rowtype;
 v_old private.phms_wound_visit_series%rowtype;
 v_i integer;
 v_target timestamptz;
 v_next_id uuid;
 v_prev_id uuid;
 v_ids uuid[]:='{}'::uuid[];
 v_date_label text;
 v_recipient uuid;
begin
 if p_interval_days is null or p_interval_days not between 1 and 30 then
  raise exception 'wound_interval_invalid';
 end if;
 if p_future_count is null or p_future_count not between 1 and 10 then
  raise exception 'wound_count_invalid';
 end if;
 if p_anchor_at is null then raise exception 'wound_anchor_required'; end if;

 select * into v_ref
 from private.phms_line_appointment_access(p_line_user_id,p_record_code) limit 1;
 if coalesce(v_ref.can_update,false) is not true then
  raise exception 'wound_plan_update_denied';
 end if;

 select * into v_ctx
 from private.phms_line_crud_context(p_line_user_id,'appointment','create') limit 1;
 if v_ctx.target_person_id is distinct from v_ref.person_id then
  raise exception 'wound_plan_owner_context_mismatch';
 end if;

 select * into v_base
 from public.appointments
 where id=v_ref.record_id and deleted_at is null
 for update;
 if not found then raise exception 'wound_plan_source_not_found'; end if;

 if coalesce(v_base.title,'') !~* '(ล้างแผล|ทำแผล|ผ่าตัด|เย็บแผล|แผล)' then
  raise exception 'wound_plan_source_not_procedure';
 end if;
 if v_base.status in ('cancelled','no_show','rescheduled') then
  raise exception 'wound_plan_source_inactive';
 end if;
 if v_base.appointment_at is null or v_base.appointment_at is distinct from p_anchor_at then
  raise exception 'wound_plan_source_date_changed';
 end if;
 if nullif(btrim(coalesce(v_base.hospital_name,'')),'') is null then
  raise exception 'wound_plan_hospital_missing';
 end if;

 select * into v_old
 from private.phms_wound_visit_series
 where source_appointment_id=v_base.id;
 if found then
  return jsonb_build_object(
   'ok',true,'already_created',true,'source_record_code',left(v_base.id::text,12),
   'interval_days',v_old.interval_days,'future_count',v_old.future_count,
   'appointment_codes',(select coalesce(jsonb_agg(left(z.id::text,12)), '[]'::jsonb)
                        from unnest(v_old.appointment_ids) z(id))
  );
 end if;

 perform pg_catalog.set_config('phms.wound_series_insert','on',true);
 v_prev_id:=v_base.id;
 for v_i in 1..p_future_count loop
  v_target := v_base.appointment_at + (p_interval_days*v_i)*interval '1 day';
  if v_target <= now() then raise exception 'wound_plan_future_date_required'; end if;
  -- Fail closed if an existing wound-care visit could be duplicated at this exact time.
  if exists (
   select 1 from public.appointments a
   where a.person_id=v_base.person_id and a.deleted_at is null
     and a.appointment_at=v_target
     and a.title ~* '(ล้างแผล|ทำแผล)'
  ) then raise exception 'wound_plan_possible_duplicate'; end if;

  insert into public.appointments(
   person_id,family_id,family_person_id,appointment_at,title,appointment_type,status,
   hospital_name,organization_id,service_unit_id,department,doctor_name,clinician_id,
   hospital_hn,hospital_vn,care_topic,coverage_type,location_detail,arrival_lead_minutes,
   contact_phone,contact_email,preparation_notes,
   followup_of_appointment_id,treatment_episode_id,created_by,note,reference_note
  ) values (
   v_base.person_id,v_base.family_id,v_base.family_person_id,v_target,
   'ล้างแผล ครั้งที่ '||(v_i+1)::text,'procedure','scheduled',
   v_base.hospital_name,v_base.organization_id,v_base.service_unit_id,v_base.department,
   v_base.doctor_name,v_base.clinician_id,
   v_base.hospital_hn,v_base.hospital_vn,v_base.care_topic,v_base.coverage_type,
   v_base.location_detail,v_base.arrival_lead_minutes,
   v_base.contact_phone,v_base.contact_email,v_base.preparation_notes,
   v_prev_id,v_base.treatment_episode_id,v_ctx.user_id,
   'แผนล้างแผลต่อเนื่องที่ผู้ใช้บันทึกไว้ ยังไม่ใช่การยืนยันคิวจากโรงพยาบาล',
   'จากนัดต้นทาง '||left(v_base.id::text,12)||' • ทุก '||p_interval_days||' วัน'
  ) returning id into v_next_id;

  v_ids:=array_append(v_ids,v_next_id);
  v_prev_id:=v_next_id;
 end loop;

 perform pg_catalog.set_config('phms.wound_series_insert','off',true);
 insert into private.phms_wound_visit_series(
  source_appointment_id,interval_days,future_count,anchor_at,appointment_ids,created_by
 ) values (v_base.id,p_interval_days,p_future_count,v_base.appointment_at,v_ids,v_ctx.user_id);

 -- Aggregate rather than sending one linked-owner notification per generated visit.
 select linked_user_id into v_recipient from public.persons where id=v_base.person_id;
 if v_recipient is not null and v_recipient is distinct from v_ctx.user_id then
  insert into public.notifications(
   family_id,recipient_user_id,event_type,title,message,related_record_id,
   channel,priority,status,person_id,family_person_id,
   scheduled_for,next_attempt_at,payload,dedupe_key,created_at,updated_at
  ) values (
   v_base.family_id,v_recipient,'appointment_wound_series_created',
   '🩹 เพิ่มแผนนัดล้างแผลต่อเนื่อง',
   'มีแผนนัดล้างแผลเพิ่ม '||p_future_count::text||' ครั้ง (ทุก '||p_interval_days::text||' วัน) โปรดยืนยันวันเวลาและคิวกับโรงพยาบาล',
   v_base.id,'line','normal','pending',v_base.person_id,v_base.family_person_id,
   now(),now(),
   jsonb_build_object('appointments',to_jsonb(v_ids),'interval_days',p_interval_days,'future_count',p_future_count),
   'wound-series:'||v_base.id::text,now(),now()
  );
 end if;

 insert into public.audit_logs(
  family_id,actor_user_id,family_person_id,event_type,resource,record_id,new_data,description
 ) values (
  v_base.family_id,v_ctx.user_id,v_base.family_person_id,
  'appointment_wound_series_created','appointment',v_base.id,
  jsonb_build_object('interval_days',p_interval_days,'future_count',p_future_count,
                     'appointments',to_jsonb(v_ids)),
  'สร้างแผนนัดล้างแผลตามช่วงวันที่ผู้ใช้เลือกและกดยืนยัน'
 );

 return jsonb_build_object(
  'ok',true,'already_created',false,
  'source_record_code',left(v_base.id::text,12),
  'interval_days',p_interval_days,'future_count',p_future_count,
  'appointment_codes',(select coalesce(jsonb_agg(left(z.id::text,12)), '[]'::jsonb)
                       from unnest(v_ids) z(id))
 );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_link_line_to_current_user(p_verification_token text)
