CREATE OR REPLACE FUNCTION public.phms_list_active_family_persons_for_context()
 RETURNS TABLE(family_person_id uuid, person_id uuid, display_name text, relationship_label text, person_status text, family_person_status text, is_active_context boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'auth'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_family_id uuid;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  select uc.active_family_id into v_family_id
  from public.user_contexts uc
  where uc.user_id=v_uid and uc.active_scope='family' limit 1;
  if v_family_id is null then raise exception 'family_context_required'; end if;
  if not exists(
    select 1 from public.family_memberships fm join public.families f on f.id=fm.family_id
    where fm.user_id=v_uid and fm.family_id=v_family_id and fm.status='active' and f.status='active'
  ) then raise exception 'family_context_not_accessible'; end if;

  return query
  select fp.id,fp.person_id,
         private.family_person_label_for_viewer(v_uid,fp.id),
         coalesce(nullif(btrim(v.relationship_label),''),nullif(btrim(fp.relationship_label),'')),
         p.status,fp.status,(uc.active_family_person_id=fp.id)
  from public.family_persons fp
  join public.persons p on p.id=fp.person_id
  join public.user_contexts uc on uc.user_id=v_uid
  left join public.family_person_view_labels v on v.viewer_user_id=v_uid and v.family_person_id=fp.id
  where fp.family_id=v_family_id and fp.status='active' and p.status='active'
  order by lower(private.family_person_label_for_viewer(v_uid,fp.id)),fp.created_at,fp.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_list_line_context_families(p_line_user_id text)
 RETURNS TABLE(selection_code text, family_id uuid, family_name text, family_code text, family_person_count bigint, is_active_context boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare v_line public.line_identities%rowtype; v_ctx private.line_identity_contexts%rowtype;
begin
 select * into v_line from public.line_identities where line_user_id=p_line_user_id and is_active=true order by updated_at desc nulls last,created_at desc limit 1;
 if not found then raise exception 'line_identity_not_found'; end if;
 if v_line.user_id is null then raise exception 'line_identity_not_linked'; end if;
 perform private.ensure_line_identity_context(v_line.id,v_line.user_id);
 select * into v_ctx from private.line_identity_contexts where line_identity_id=v_line.id;
 return query
 select substr(encode(digest(f.id::text||':'||v_line.id::text,'sha256'),'hex'),1,12),f.id,f.family_name,f.family_code,
        count(fp.id) filter(where coalesce(fp.status,'active')='active' and private.user_can_see_family_person(v_line.user_id,fp.id)),
        coalesce(v_ctx.active_scope='family' and v_ctx.active_family_id=f.id,false)
 from public.family_memberships fm join public.families f on f.id=fm.family_id
 left join public.family_persons fp on fp.family_id=f.id
 where fm.user_id=v_line.user_id and fm.status='active' and coalesce(f.status,'active')='active'
 group by f.id,f.family_name,f.family_code,v_ctx.active_scope,v_ctx.active_family_id,v_line.id
 order by lower(coalesce(f.family_name,'')),f.created_at,f.id;
end $function$

CREATE OR REPLACE FUNCTION public.phms_list_line_family_removal_requests(p_line_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_ctx private.line_identity_contexts%rowtype;
  v_items jsonb;
begin
  select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
  perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
  select * into v_ctx from private.line_identity_contexts where line_identity_id=v_line.line_identity_id;
  if v_ctx.active_scope<>'family' or v_ctx.active_family_id is null then raise exception 'family_context_required'; end if;

  perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
  if not private.is_family_owner(v_ctx.active_family_id) then raise exception 'owner_required_to_review_removal'; end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'request_code',substr(encode(digest(pr.id::text||':'||v_line.line_identity_id::text,'sha256'),'hex'),1,12),
    'requester_name',private.family_user_label_for_viewer(v_line.user_id,pr.family_id,pr.requester_user_id),
    'target_kind',pr.requested_action,
    'target_name',case
      when pr.family_person_id is not null then private.family_person_label_for_viewer(v_line.user_id,pr.family_person_id)
      else private.family_user_label_for_viewer(v_line.user_id,pr.family_id,pr.target_user_id)
    end,
    'reason',pr.reason,
    'created_at',pr.created_at
  ) order by pr.created_at),'[]'::jsonb)
  into v_items
  from public.permission_requests pr
  where pr.family_id=v_ctx.active_family_id
    and pr.request_type='family_removal'
    and pr.status='pending';

  return jsonb_build_object('items',v_items,'count',jsonb_array_length(v_items));
end
$function$

CREATE OR REPLACE FUNCTION public.phms_list_line_family_removal_requests(p_line_user_id text, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_ctx private.line_identity_contexts%rowtype;
  v_is_owner boolean;
  v_is_admin boolean;
  v_items jsonb;
begin
  select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
  perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
  select * into v_ctx from private.line_identity_contexts where line_identity_id=v_line.line_identity_id;
  if v_ctx.active_scope<>'family' or v_ctx.active_family_id is null then raise exception 'family_context_required'; end if;
  perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);

  v_is_owner:=private.is_family_owner(v_ctx.active_family_id);
  v_is_admin:=private.user_has_family_role(v_line.user_id,v_ctx.active_family_id,array['admin']);
  if not (v_is_owner or v_is_admin) then raise exception 'family_removal_requests_not_accessible'; end if;

  select coalesce(jsonb_agg(x.item order by x.created_at desc),'[]'::jsonb)
  into v_items
  from (
    select r.created_at,
      jsonb_build_object(
        'request_code',substr(encode(digest(r.id::text||':'||v_line.line_identity_id::text,'sha256'),'hex'),1,12),
        'target_kind',r.target_kind,
        'target_name',case
          when r.target_kind='person' then private.family_person_label_for_viewer(v_line.user_id,r.family_person_id)
          else private.family_user_label_for_viewer(v_line.user_id,r.family_id,r.target_user_id)
        end,
        'requester_name',private.family_user_label_for_viewer(v_line.user_id,r.family_id,r.requested_by),
        'reason',r.reason,'status',r.status,'created_at',r.created_at,
        'can_review',v_is_owner and r.status='pending'
      ) item
    from private.family_removal_requests r
    where r.family_id=v_ctx.active_family_id
      and (v_is_owner or r.requested_by=v_line.user_id)
      and r.status in ('pending','approved','rejected')
    order by r.created_at desc
    limit greatest(1,least(coalesce(p_limit,100),200))
  ) x;

  return jsonb_build_object('ok',true,'is_owner',v_is_owner,'is_admin',v_is_admin,'items',v_items,'count',jsonb_array_length(v_items));
end
$function$

CREATE OR REPLACE FUNCTION public.phms_list_line_person_caregivers(p_line_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_line record;v_ctx private.line_identity_contexts%rowtype;v_fp public.family_persons%rowtype;
 v_person public.persons%rowtype;v_current jsonb:='[]'::jsonb;v_candidates jsonb:='[]'::jsonb;
 v_can_manage boolean:=false;v_primary uuid;v_primary_name text;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select c.* into v_ctx from private.line_identity_contexts c where c.line_identity_id=v_line.line_identity_id;
 if v_ctx.active_scope<>'family' or v_ctx.active_family_person_id is null then
   raise exception 'family_person_context_required';
 end if;
 select * into v_fp from public.family_persons
  where id=v_ctx.active_family_person_id and family_id=v_ctx.active_family_id and coalesce(status,'active')='active';
 if not found then raise exception 'family_person_not_found'; end if;
 select * into v_person from public.persons where id=v_fp.person_id;
 perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
 v_can_manage:=private.phms_can_manage_medical_grants(v_line.user_id,v_fp.id);

 select mp.primary_user_id into v_primary
 from private.medical_primary_responsibilities mp
 where mp.family_person_id=v_fp.id and mp.state='active';
 if v_primary is not null then
   v_primary_name:=private.family_user_label_for_viewer(v_line.user_id,v_fp.family_id,v_primary);
 end if;

 select coalesce(jsonb_agg(jsonb_build_object(
   'member_code',substr(encode(digest(ca.caregiver_user_id::text||':'||v_line.line_identity_id::text||':'||v_fp.family_id::text,'sha256'),'hex'),1,12),
   'display_name',private.family_user_label_for_viewer(v_line.user_id,v_fp.family_id,ca.caregiver_user_id),
   'access_kind','assistant','is_primary',false,
   'can_edit_profile',ca.can_edit_profile,'can_manage_medications',ca.can_manage_medications,
   'can_manage_appointments',ca.can_manage_appointments,'can_manage_health',ca.can_manage_health,
   'can_manage_emergency',ca.can_manage_emergency,'can_receive_notifications',ca.can_receive_notifications
 ) order by lower(private.family_user_label_for_viewer(v_line.user_id,v_fp.family_id,ca.caregiver_user_id))),'[]'::jsonb)
 into v_current
 from public.person_caregiver_assignments ca
 where ca.family_person_id=v_fp.id and ca.status='active'
   and ca.caregiver_user_id is distinct from v_person.linked_user_id
   and ca.caregiver_user_id is distinct from v_primary;

 select coalesce(jsonb_agg(jsonb_build_object(
   'member_code',substr(encode(digest(fm.user_id::text||':'||v_line.line_identity_id::text||':'||v_fp.family_id::text,'sha256'),'hex'),1,12),
   'display_name',private.family_user_label_for_viewer(v_line.user_id,v_fp.family_id,fm.user_id),
   'is_primary',fm.user_id=v_primary,
   'assigned_assistant',exists(select 1 from public.person_caregiver_assignments ca
      where ca.family_person_id=v_fp.id and ca.caregiver_user_id=fm.user_id and ca.status='active')
 ) order by lower(private.family_user_label_for_viewer(v_line.user_id,v_fp.family_id,fm.user_id)),fm.joined_at),'[]'::jsonb)
 into v_candidates
 from public.family_memberships fm
 where fm.family_id=v_fp.family_id and fm.status='active'
   and fm.user_id is distinct from v_person.linked_user_id;

 return jsonb_build_object(
   'can_manage',v_can_manage,'primary_status',case when v_primary is null then 'needs_assignment' else 'active' end,
   'primary_name',v_primary_name,
   'primary_member_code',case when v_primary is null then null else
     substr(encode(digest(v_primary::text||':'||v_line.line_identity_id::text||':'||v_fp.family_id::text,'sha256'),'hex'),1,12) end,
   'self_manage',private.family_person_self_manage_enabled(v_fp.id),
   'assistants',v_current,'current',v_current,'candidates',v_candidates
 );
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_list_line_person_change_requests(p_line_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare v_line record; v_ctx private.line_identity_contexts%rowtype; v_rows jsonb:='[]'::jsonb;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select c.* into v_ctx from private.line_identity_contexts c where c.line_identity_id=v_line.line_identity_id;
 if v_ctx.active_scope<>'family' or v_ctx.active_family_id is null then raise exception 'family_context_required'; end if;
 perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
 select coalesce(jsonb_agg(jsonb_build_object(
   'request_code',substr(encode(digest(r.id::text||':'||v_line.line_identity_id::text,'sha256'),'hex'),1,12),
   'request_id',r.id,'person_name',private.family_person_label_for_viewer(v_line.user_id,r.family_person_id),
   'field',r.field_name,'old_value',r.old_value,'requested_value',r.requested_value,'reason',r.reason,'created_at',r.created_at,
   'can_review',private.can_access_family_person(r.family_person_id,'persons','update'),
   'is_requester',r.requester_user_id=v_line.user_id
 ) order by r.created_at),'[]'::jsonb) into v_rows
 from public.person_change_requests r
 where r.family_id=v_ctx.active_family_id and r.status='pending'
 and (r.requester_user_id=v_line.user_id or private.can_access_family_person(r.family_person_id,'persons','update'));
 return jsonb_build_object('count',jsonb_array_length(v_rows),'requests',v_rows);
end $function$

CREATE OR REPLACE FUNCTION public.phms_list_line_person_photos(p_line_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare v_line record; v_ctx private.line_identity_contexts%rowtype; v_rows jsonb:='[]'::jsonb; v_p public.persons%rowtype; v_can_set_shared boolean:=false;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select c.* into v_ctx from private.line_identity_contexts c where c.line_identity_id=v_line.line_identity_id;
 if v_ctx.active_scope<>'family' or v_ctx.active_family_person_id is null then raise exception 'family_person_context_required'; end if;
 if not private.user_can_see_family_person(v_line.user_id,v_ctx.active_family_person_id) then raise exception 'person_view_denied'; end if;
 select p.* into v_p from public.family_persons fp join public.persons p on p.id=fp.person_id where fp.id=v_ctx.active_family_person_id;
 perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
 v_can_set_shared:=coalesce(v_p.linked_user_id=v_line.user_id,false) or private.can_access_family_person(v_ctx.active_family_person_id,'persons','update');
 select coalesce(jsonb_agg(jsonb_build_object(
   'photo_code',substr(encode(digest(ph.id::text||':'||v_line.line_identity_id::text,'sha256'),'hex'),1,12),
   'object_name',ph.object_name,'mime_type',ph.mime_type,'mine',ph.uploaded_by=v_line.user_id,
   'shared',ph.visibility='shared','person_shared_default',ph.is_person_shared_default,
   'selected_for_me',pref.photo_id=ph.id,'created_at',ph.created_at
 ) order by (pref.photo_id=ph.id) desc,ph.is_person_shared_default desc,ph.created_at desc),'[]'::jsonb)
 into v_rows
 from public.person_photos ph
 left join public.person_photo_preferences pref on pref.viewer_user_id=v_line.user_id and pref.family_person_id=ph.family_person_id
 where ph.family_person_id=v_ctx.active_family_person_id and ph.status='active'
 and (ph.uploaded_by=v_line.user_id or ph.visibility='shared');
 return jsonb_build_object('photos',v_rows,'count',jsonb_array_length(v_rows),'can_upload',true,'can_set_shared',v_can_set_shared);
end $function$

CREATE OR REPLACE FUNCTION public.phms_list_line_person_setup_drafts(p_line_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_ctx private.line_identity_contexts%rowtype;
  v_rows jsonb:='[]'::jsonb;
begin
  select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
  perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
  select c.* into v_ctx
  from private.line_identity_contexts c
  where c.line_identity_id=v_line.line_identity_id;

  if v_ctx.active_scope<>'family' or v_ctx.active_family_id is null then
    raise exception 'family_context_required';
  end if;

  if not private.user_has_family_role(v_line.user_id,v_ctx.active_family_id,array['owner','admin']) then
    raise exception 'permission_management_denied';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'person_code',substr(encode(digest(fp.id::text||':'||v_line.line_identity_id::text,'sha256'),'hex'),1,12),
    'family_person_id',fp.id,
    'display_name',private.family_person_label_for_viewer(v_line.user_id,fp.id),
    'shared_nickname',p.nickname,
    'created_at',fp.created_at,
    'created_by_me',fp.setup_created_by=v_line.user_id
  ) order by fp.created_at desc),'[]'::jsonb)
  into v_rows
  from public.family_persons fp
  join public.persons p on p.id=fp.person_id
  where fp.family_id=v_ctx.active_family_id
    and fp.setup_status='draft'
    and coalesce(fp.status,'active')='active'
    and coalesce(p.status,'active')='active'
    and (
      fp.setup_created_by=v_line.user_id
      or private.user_has_family_role(v_line.user_id,fp.family_id,array['owner'])
    );

  return jsonb_build_object('count',jsonb_array_length(v_rows),'drafts',v_rows);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_list_line_visibility_manage_people(p_line_user_id text)
 RETURNS jsonb
