CREATE OR REPLACE FUNCTION public.phms_med_action_claim(p_line_user_id text, p_token text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE v record; ctx record;
BEGIN
 IF p_idempotency_key IS NULL OR length(p_idempotency_key)<8 OR length(p_idempotency_key)>200 THEN RAISE EXCEPTION 'invalid_idempotency_key';END IF;
 SELECT * INTO v FROM public.phms_med_action_contexts WHERE token=p_token AND line_user_id=p_line_user_id FOR UPDATE;
 IF NOT FOUND OR v.expires_at<=now() THEN RAISE EXCEPTION 'expired_or_invalid_action';END IF;
 SELECT * INTO ctx FROM private.phms_line_crud_context(p_line_user_id,'medication',private.phms_med_action_permission(v.action_key));
 IF ctx.target_person_id IS NULL OR v.resolved_person_id IS DISTINCT FROM ctx.target_person_id THEN RAISE EXCEPTION 'person_context_changed';END IF;
 IF v.consumed_at IS NOT NULL THEN
  IF v.consumption_idempotency_key=p_idempotency_key THEN RETURN jsonb_build_object('ok',true,'replay',true,'state',v.outcome,'result',v.result,'action',v.action_key);END IF;
  RAISE EXCEPTION 'action_token_already_consumed';
 END IF;
 UPDATE public.phms_med_action_contexts SET consumed_at=now(),consumption_idempotency_key=p_idempotency_key,outcome='CLAIMED' WHERE id=v.id;
 INSERT INTO public.phms_med_action_audit(action_context_id,event_type,metadata) VALUES(v.id,'CLAIMED',jsonb_build_object('person_id',ctx.target_person_id));
 RETURN jsonb_build_object('ok',true,'replay',false,'action',v.action_key,'payload',v.payload,'person_id',ctx.target_person_id,'context_id',v.id);
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_action_execute(p_line_user_id text, p_token text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE a record; ctx record; v_result jsonb; v_args jsonb; v_permission text;
BEGIN
 IF p_idempotency_key IS NULL OR length(p_idempotency_key)<8 OR length(p_idempotency_key)>200 THEN RAISE EXCEPTION 'invalid_idempotency_key'; END IF;
 SELECT * INTO a FROM public.phms_med_action_contexts WHERE token=p_token AND line_user_id=p_line_user_id FOR UPDATE;
 IF NOT FOUND OR a.expires_at<=now() THEN RAISE EXCEPTION 'expired_or_invalid_action';END IF;
 v_permission:=private.phms_med_action_permission(a.action_key);
 IF v_permission IS NULL THEN RAISE EXCEPTION 'unsupported_med_action';END IF;
 SELECT * INTO ctx FROM private.phms_line_crud_context(p_line_user_id,'medication',v_permission);
 IF a.resolved_person_id IS DISTINCT FROM ctx.target_person_id THEN RAISE EXCEPTION 'person_context_changed';END IF;
 IF a.consumed_at IS NOT NULL THEN
  IF a.consumption_idempotency_key=p_idempotency_key AND a.outcome='SUCCEEDED' THEN
   RETURN jsonb_build_object('ok',true,'replay',true,'action',a.action_key,'result',a.result);
  END IF;
  RAISE EXCEPTION 'action_token_already_used';
 END IF;
 v_args:=coalesce(a.payload,'{}'::jsonb);
 IF a.action_key='med.administration.record' THEN
  v_result:=public.phms_med_v23_line_record(p_line_user_id,(v_args->>'scheduled_id')::uuid,v_args->>'outcome',v_args->>'evidence',(v_args->>'actual_at')::timestamptz,(v_args->>'actual_dose')::numeric,v_args->>'actual_unit',(v_args->>'performed_by')::uuid,p_idempotency_key,v_args->>'reason');
 ELSIF a.action_key='med.administration.correct' THEN
  v_result:=public.phms_med_v23_line_correct(p_line_user_id,(v_args->>'event_id')::uuid,v_args->>'correction_type',v_args->>'reason',coalesce(v_args->'values','{}'::jsonb),p_idempotency_key);
 ELSIF a.action_key='med.stock.receive' THEN
  v_result:=public.phms_med_v23_line_inventory_receive(p_line_user_id,(v_args->>'pool_id')::uuid,(v_args->>'location_id')::uuid,(v_args->>'medication_id')::uuid,(v_args->>'lot_id')::uuid,(v_args->>'container_id')::uuid,(v_args->>'quantity')::numeric,v_args->>'unit',p_idempotency_key,v_args->>'reason');
 ELSIF a.action_key='med.preparation.start' THEN
  v_result:=public.phms_med_v23_line_preparation_start(p_line_user_id,(v_args->>'start_date')::date,(v_args->>'end_date')::date);
 ELSIF a.action_key='med.preparation.verify' THEN
  v_result:=public.phms_med_v23_line_preparation_transition(p_line_user_id,(v_args->>'session_id')::uuid,v_args->>'new_status');
 ELSIF a.action_key='med.intake.commit' THEN
  v_result:=public.phms_med_intake_wizard_save(p_line_user_id,v_args->'draft',true);
 ELSE
  RAISE EXCEPTION 'med_action_not_implemented:%',a.action_key;
 END IF;
 UPDATE public.phms_med_action_contexts SET consumed_at=now(),consumption_idempotency_key=p_idempotency_key,
 outcome='SUCCEEDED',result=coalesce(v_result,'{}'::jsonb) WHERE id=a.id;
 INSERT INTO public.phms_med_action_audit(action_context_id,event_type,metadata)
 VALUES(a.id,'SUCCEEDED',jsonb_build_object('action',a.action_key,'person_id',ctx.target_person_id));
 RETURN jsonb_build_object('ok',true,'replay',false,'action',a.action_key,'result',v_result);
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_action_finalize(p_line_user_id text, p_token text, p_idempotency_key text, p_success boolean, p_result jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE v record; v_ctx record;
BEGIN
 SELECT * INTO v FROM public.phms_med_action_contexts WHERE token=p_token AND line_user_id=p_line_user_id FOR UPDATE;
 IF NOT FOUND OR v.consumption_idempotency_key IS DISTINCT FROM p_idempotency_key OR v.consumed_at IS NULL THEN RAISE EXCEPTION 'invalid_claim';END IF;
 SELECT * INTO v_ctx FROM private.phms_line_crud_context(p_line_user_id,'medication',private.phms_med_action_permission(v.action_key));
 IF v_ctx.target_person_id IS DISTINCT FROM v.resolved_person_id THEN RAISE EXCEPTION 'person_context_changed';END IF;
 IF v.outcome IN ('SUCCEEDED','FAILED') THEN RETURN jsonb_build_object('state',v.outcome,'result',v.result,'replay',true);END IF;
 IF p_result IS NULL OR length(p_result::text)>16000 THEN RAISE EXCEPTION 'invalid_result';END IF;
 UPDATE public.phms_med_action_contexts SET outcome=CASE WHEN p_success THEN 'SUCCEEDED' ELSE 'FAILED' END,result=p_result WHERE id=v.id;
 INSERT INTO public.phms_med_action_audit(action_context_id,event_type,metadata) VALUES(v.id,CASE WHEN p_success THEN 'SUCCEEDED' ELSE 'FAILED' END,jsonb_build_object('result_recorded',true));
 RETURN jsonb_build_object('state',CASE WHEN p_success THEN 'SUCCEEDED' ELSE 'FAILED' END,'result',p_result);
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_action_issue(p_line_user_id text, p_action text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS text
 LANGUAGE plpgsql
