 IF v_mode IS NULL THEN RAISE EXCEPTION 'unsupported_med_action';END IF;
 IF p_line_user_id IS NULL OR length(p_line_user_id)<3 OR p_payload IS NULL OR jsonb_typeof(p_payload)<>'object' OR length(p_payload::text)>2000 THEN RAISE EXCEPTION 'invalid_context';END IF;
 SELECT * INTO v_ctx FROM private.phms_line_crud_context(p_line_user_id,'medication',v_mode);
 IF v_ctx.target_person_id IS NULL THEN RAISE EXCEPTION 'person_required';END IF;
