CREATE OR REPLACE FUNCTION public.phms_med_intake_wizard_save(p_line_user_id text, p_payload jsonb, p_submit boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE ctx record; v_id uuid; v_status text;
BEGIN
 SELECT * INTO ctx FROM private.phms_line_crud_context(p_line_user_id,'medication','create');
 IF ctx.target_person_id IS NULL OR ctx.active_family_id IS NULL THEN RAISE EXCEPTION 'person or family required'; END IF;
 IF p_payload IS NULL OR jsonb_typeof(p_payload)<>'object' OR length(p_payload::text)>16000 THEN RAISE EXCEPTION 'invalid draft payload'; END IF;
 IF p_submit AND (nullif(btrim(p_payload->>'product'),'') IS NULL OR nullif(btrim(p_payload->>'quantity'),'') IS NULL OR nullif(btrim(p_payload->>'instructions_label'),'') IS NULL) THEN RAISE EXCEPTION 'product, quantity, label information required before review'; END IF;
 v_status:=CASE WHEN p_submit THEN 'PENDING_REVIEW' ELSE 'DRAFT' END;
 INSERT INTO public.medication_intake_wizard_drafts(person_id,family_id,created_by,draft,status,submitted_at)
 VALUES(ctx.target_person_id,ctx.active_family_id,ctx.actor_user_id,p_payload,v_status,CASE WHEN p_submit THEN now() ELSE NULL END)
 RETURNING id INTO v_id;
 RETURN jsonb_build_object('ok',true,'draft_id',v_id,'status',v_status,'person_name',ctx.target_person_name,'message','No clinical order or inventory changed');
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_generate_day(p_person_id uuid, p_day date, p_timezone text DEFAULT 'Asia/Bangkok'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE d record; num_created integer:=0; num_skipped integer:=0; planned timestamptz; rid uuid; local_stamp timestamp; inserted_count int;
BEGIN
 IF p_day IS NULL OR p_day<date '2000-01-01' OR p_day>(now() AT TIME ZONE 'Asia/Bangkok')::date+365 THEN RAISE EXCEPTION 'invalid_day';END IF;
 IF p_timezone<>'Asia/Bangkok' THEN RAISE EXCEPTION 'unsupported_timezone';END IF;
 FOR d IN
 SELECT v.*,pm.person_id,pm.medication_id,md.id AS rule_id,md.slot_key,md.local_time,md.dose_quantity,md.dose_unit,
 md.route,md.administration_site,md.sequence_no,md.effective_from AS rule_from,md.effective_to AS rule_to
 FROM public.medication_order_versions v
 JOIN public.person_medications pm ON pm.id=v.person_medication_id
 JOIN public.medication_regimens r ON r.id=v.regimen_id AND r.person_medication_id=pm.id
 JOIN public.medication_regimen_doses md ON md.order_version_id=v.id
 WHERE pm.person_id=p_person_id AND pm.deleted_at IS NULL AND pm.status='regular'
 AND (pm.start_date IS NULL OR pm.start_date<=p_day) AND (pm.end_date IS NULL OR pm.end_date>=p_day)
 AND v.status='verified' AND v.verified_at IS NOT NULL
 AND r.frequency_type='times_per_day' AND r.frequency_unit='day'
 AND md.local_time IS NOT NULL AND md.dose_quantity IS NOT NULL AND md.dose_quantity>0
 AND nullif(btrim(coalesce(md.dose_unit,'')),'') IS NOT NULL
 AND md.timezone=p_timezone
 AND NOT EXISTS (
  SELECT 1 FROM public.medication_conditional_rules c
  WHERE c.person_medication_id=pm.id AND (c.regimen_id IS NULL OR c.regimen_id=r.id)
    AND c.active=true AND c.deleted_at IS NULL
    AND (c.effective_from IS NULL OR c.effective_from<=((p_day::timestamp+time '23:59:59') AT TIME ZONE p_timezone))
    AND (c.effective_to IS NULL OR c.effective_to>=(p_day::timestamp AT TIME ZONE p_timezone))
 )
 AND NOT EXISTS (
  SELECT 1 FROM public.medication_timing_policies tp
  JOIN public.medication_schedule_overrides o ON o.timing_policy_id=tp.id
  WHERE tp.regimen_id=r.id AND tp.active=true AND tp.deleted_at IS NULL AND o.schedule_date=p_day
 )
 ORDER BY md.slot_key,md.sequence_no
 LOOP
   local_stamp:=p_day::timestamp+d.local_time;
   planned:=local_stamp AT TIME ZONE p_timezone;
   IF d.effective_from IS NOT NULL AND planned<d.effective_from THEN CONTINUE; END IF;
   IF d.effective_to IS NOT NULL AND planned>=d.effective_to THEN CONTINUE; END IF;
   IF d.rule_from IS NOT NULL AND planned<d.rule_from THEN CONTINUE; END IF;
   IF d.rule_to IS NOT NULL AND planned>=d.rule_to THEN CONTINUE; END IF;
   INSERT INTO public.medication_round_instances(person_id,round_date,slot_key,timezone)
   VALUES(p_person_id,p_day,d.slot_key,p_timezone)
   ON CONFLICT(person_id,round_date,slot_key) DO NOTHING;
   SELECT id INTO rid FROM public.medication_round_instances WHERE person_id=p_person_id AND round_date=p_day AND slot_key=d.slot_key;
   INSERT INTO public.medication_scheduled_doses(person_id,person_medication_id,regimen_id,order_version_id,round_id,slot_key,scheduled_at,planned_date,timezone,planned_dose,planned_unit,order_snapshot,occurrence_no)
   VALUES(p_person_id,d.person_medication_id,d.regimen_id,d.id,rid,d.slot_key,planned,p_day,p_timezone,d.dose_quantity,d.dose_unit,
   jsonb_build_object('version',d.order_snapshot,'rule_id',d.rule_id,'slot',d.slot_key,'route',d.route,'site',d.administration_site,'dose',d.dose_quantity,'unit',d.dose_unit),d.sequence_no)
   ON CONFLICT DO NOTHING;
   GET DIAGNOSTICS inserted_count=ROW_COUNT;
   IF inserted_count=1 THEN num_created:=num_created+1; ELSE num_skipped:=num_skipped+1;END IF;
 END LOOP;
 RETURN jsonb_build_object('created',num_created,'already_present',num_skipped);
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_guard_duplicate_administration()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE prior_event uuid; prior_void uuid;
BEGIN
 IF NEW.scheduled_dose_id IS NULL THEN RETURN NEW;END IF;
 PERFORM 1 FROM public.medication_scheduled_doses WHERE id=NEW.scheduled_dose_id FOR UPDATE;
 SELECT e.id INTO prior_event FROM public.medication_administration_events e
 WHERE e.scheduled_dose_id=NEW.scheduled_dose_id
 AND NOT EXISTS(SELECT 1 FROM public.medication_administration_corrections c WHERE c.administration_event_id=e.id AND c.correction_type='void')
 ORDER BY e.recorded_at DESC,e.id DESC LIMIT 1;
 IF prior_event IS NOT NULL THEN RAISE EXCEPTION 'scheduled_dose_already_has_active_administration';END IF;
 IF NEW.replaces_event_id IS NOT NULL AND NOT EXISTS (
   SELECT 1 FROM public.medication_administration_events e
   JOIN public.medication_administration_corrections c ON c.administration_event_id=e.id AND c.correction_type='void'
   WHERE e.id=NEW.replaces_event_id AND e.scheduled_dose_id=NEW.scheduled_dose_id
 ) THEN RAISE EXCEPTION 'replacement_must_reference_voided_event';END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_inventory_allocate(p_balance_id uuid, p_patient_id uuid, p_quantity numeric, p_actor uuid, p_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE b record;pool_row record;held numeric;old_alloc record;new_id uuid;lot_exp date;container_exp date;bud timestamptz;container_status text;
BEGIN
 IF p_quantity IS NULL OR p_quantity<=0 OR p_key IS NULL OR length(p_key)<12 OR length(p_key)>200 THEN RAISE EXCEPTION 'invalid allocation';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('allocation-key:'||p_key,0));
 SELECT * INTO old_alloc FROM public.medication_stock_allocations WHERE idempotency_key=p_key;
 IF FOUND THEN
  IF old_alloc.balance_id=p_balance_id AND old_alloc.patient_id=p_patient_id AND old_alloc.quantity=p_quantity THEN RETURN jsonb_build_object('ok',true,'duplicate',true,'allocation_id',old_alloc.id);END IF;
  RAISE EXCEPTION 'allocation idempotency conflict';
 END IF;
 SELECT * INTO b FROM public.medication_inventory_balances WHERE id=p_balance_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'balance missing';END IF;
 SELECT * INTO pool_row FROM public.medication_stock_pools WHERE id=b.pool_id FOR SHARE;
 IF pool_row.pool_type='quarantine' OR (pool_row.pool_type='patient_assigned' AND pool_row.assigned_person_id<>p_patient_id) THEN RAISE EXCEPTION 'pool cannot allocate';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.family_persons WHERE family_id=pool_row.family_id AND person_id=p_patient_id AND status='active') THEN RAISE EXCEPTION 'patient outside household';END IF;
 IF pool_row.pool_type='shared' AND NOT EXISTS(
  SELECT 1 FROM public.medication_shared_usage_authorizations a WHERE a.pool_id=b.pool_id AND a.medication_id=b.medication_id AND a.patient_id=p_patient_id
  AND a.status='verified' AND a.effective_from<=now() AND (a.expires_at IS NULL OR a.expires_at>now())
 ) THEN RAISE EXCEPTION 'shared stock authorization required';END IF;
 SELECT manufacturer_expiry_date INTO lot_exp FROM public.medication_lots WHERE id=b.lot_id;
 IF b.stock_container_id IS NOT NULL THEN
  SELECT manufacturer_expiry_date,beyond_use_at,lifecycle_status INTO container_exp,bud,container_status FROM public.medication_stock_containers WHERE id=b.stock_container_id;
 ELSIF b.container_id IS NOT NULL THEN
  SELECT manufacturer_expiry_date,beyond_use_at,lifecycle_status INTO container_exp,bud,container_status FROM public.medication_containers WHERE id=b.container_id;
 END IF;
 IF container_status IN('retired','empty','expired','quarantined') THEN RAISE EXCEPTION 'container not usable';END IF;
 IF lot_exp IS NULL AND container_exp IS NULL THEN RAISE EXCEPTION 'expiry information missing; reconcile stock'; END IF;
 IF (lot_exp IS NOT NULL AND lot_exp<(now() AT TIME ZONE 'Asia/Bangkok')::date)
 OR (container_exp IS NOT NULL AND container_exp<(now() AT TIME ZONE 'Asia/Bangkok')::date)
 OR (bud IS NOT NULL AND bud<now()) THEN RAISE EXCEPTION 'medicine expired';END IF;
 IF container_status='opened' AND bud IS NULL AND EXISTS(
  SELECT 1 FROM public.medication_master m WHERE m.id=b.medication_id AND lower(coalesce(m.dosage_form,'')) LIKE '%eye%'
 ) THEN RAISE EXCEPTION 'opened eye drop needs beyond-use validation';END IF;
 SELECT coalesce(sum(quantity),0) INTO held FROM public.medication_stock_allocations WHERE balance_id=p_balance_id AND status='reserved';
 IF b.quantity-held<p_quantity THEN RAISE EXCEPTION 'insufficient unreserved balance';END IF;
 INSERT INTO public.medication_stock_allocations(balance_id,patient_id,quantity,quantity_unit,idempotency_key)
 VALUES(p_balance_id,p_patient_id,p_quantity,b.quantity_unit,p_key) RETURNING id INTO new_id;
 RETURN jsonb_build_object('ok',true,'duplicate',false,'allocation_id',new_id);
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_inventory_clinical_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE pl record; lot_exp date; cutoff timestamptz;
BEGIN
 SELECT * INTO pl FROM public.medication_stock_pools WHERE id=NEW.pool_id;
 IF NEW.transaction_type IN('dispense','consume') THEN
  IF pl.pool_type='quarantine' THEN RAISE EXCEPTION 'quarantine cannot dispense';END IF;
  IF NEW.lot_id IS NOT NULL THEN
   SELECT manufacturer_expiry_date INTO lot_exp FROM public.medication_lots WHERE id=NEW.lot_id;
   IF lot_exp IS NOT NULL AND lot_exp < (now() AT TIME ZONE 'Asia/Bangkok')::date THEN RAISE EXCEPTION 'expired lot blocked';END IF;
  END IF;
  IF NEW.container_id IS NOT NULL THEN
   SELECT beyond_use_at INTO cutoff FROM public.medication_containers WHERE id=NEW.container_id;
   IF cutoff IS NOT NULL AND cutoff<now() THEN RAISE EXCEPTION 'container beyond-use date passed';END IF;
  END IF;
  IF pl.pool_type='shared' AND NOT EXISTS (
   SELECT 1 FROM public.medication_shared_usage_authorizations a
   WHERE a.pool_id=pl.id AND a.medication_id=NEW.medication_id AND a.patient_id=NEW.patient_id
   AND a.status='verified' AND a.effective_from<=now()
   AND (a.expires_at IS NULL OR a.expires_at>now())
  ) THEN RAISE EXCEPTION 'shared medicine patient authorization missing';END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_inventory_fulfill(p_allocation_id uuid, p_actor uuid, p_key text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE a record;b record;pool_row record;old_tx record;result jsonb;balance_ref uuid;pool_ref uuid;med_ref uuid;
BEGIN
 IF p_key IS NULL OR length(p_key)<12 THEN RAISE EXCEPTION 'invalid idempotency key';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('inv-idempotency:'||p_key,0));
 SELECT * INTO old_tx FROM public.medication_inventory_transactions WHERE idempotency_key=p_key;
 IF FOUND THEN
   IF old_tx.patient_id IS DISTINCT FROM (SELECT patient_id FROM public.medication_stock_allocations WHERE id=p_allocation_id) THEN RAISE EXCEPTION 'idempotency_patient_mismatch';END IF;
   RETURN jsonb_build_object('ok',true,'duplicate',true,'transaction_id',old_tx.id);
 END IF;
 SELECT balance_id INTO balance_ref FROM public.medication_stock_allocations WHERE id=p_allocation_id;
 IF balance_ref IS NULL THEN RAISE EXCEPTION 'allocation not found';END IF;
 SELECT pool_id,medication_id INTO pool_ref,med_ref FROM public.medication_inventory_balances WHERE id=balance_ref;
 IF pool_ref IS NULL THEN RAISE EXCEPTION 'inventory balance not found';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(pool_ref::text||':'||med_ref::text,0));
 SELECT * INTO a FROM public.medication_stock_allocations WHERE id=p_allocation_id FOR UPDATE;
 IF NOT FOUND OR a.status<>'reserved' OR a.balance_id<>balance_ref THEN RAISE EXCEPTION 'allocation not reserved';END IF;
 SELECT * INTO b FROM public.medication_inventory_balances WHERE id=a.balance_id FOR UPDATE;
 SELECT * INTO pool_row FROM public.medication_stock_pools WHERE id=b.pool_id;
 IF pool_row.pool_type='quarantine' OR b.quantity<a.quantity THEN RAISE EXCEPTION 'inventory not available';END IF;
 UPDATE public.medication_stock_allocations SET status='fulfilled',updated_at=now() WHERE id=a.id;
 IF b.stock_container_id IS NOT NULL THEN
  result:=public.phms_med_v23_inventory_post_stock(b.pool_id,b.medication_id,b.lot_id,NULL,b.location_id,NULL,a.patient_id,'dispense',
   a.quantity,a.quantity_unit,p_actor,p_key,p_reason,b.stock_container_id);
 ELSE
  result:=public.phms_med_v23_inventory_post(b.pool_id,b.medication_id,b.lot_id,b.container_id,b.location_id,NULL,a.patient_id,'dispense',
   a.quantity,a.quantity_unit,p_actor,p_key,p_reason);
 END IF;
 RETURN result||jsonb_build_object('allocation_id',a.id);
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_inventory_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_pool uuid;v_product uuid;v_owner uuid;v_lot_product uuid;v_container_owner uuid; v_container_lot uuid;
BEGIN
 IF TG_TABLE_NAME='medication_inventory_balances' THEN
  v_pool:=NEW.pool_id;v_product:=NEW.medication_id;
  IF NOT EXISTS(SELECT 1 FROM public.medication_stock_locations l WHERE l.id=NEW.location_id AND l.pool_id=NEW.pool_id) THEN RAISE EXCEPTION 'location not in pool';END IF;
 ELSIF TG_TABLE_NAME='medication_inventory_transactions' THEN
  v_pool:=NEW.pool_id;v_product:=NEW.medication_id;
  IF NEW.source_location_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.medication_stock_locations l WHERE l.id=NEW.source_location_id AND l.pool_id=NEW.pool_id) THEN RAISE EXCEPTION 'source not in pool';END IF;
  IF NEW.destination_location_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.medication_stock_locations l WHERE l.id=NEW.destination_location_id AND l.pool_id=NEW.pool_id) THEN RAISE EXCEPTION 'destination not in pool';END IF;
 ELSE
  RETURN NEW;
 END IF;
 IF NEW.lot_id IS NOT NULL THEN
  SELECT medication_id INTO v_lot_product FROM public.medication_lots WHERE id=NEW.lot_id;
  IF v_lot_product IS DISTINCT FROM v_product THEN RAISE EXCEPTION 'lot product mismatch';END IF;
 END IF;
 IF NEW.container_id IS NOT NULL THEN
  SELECT pm.medication_id,c.lot_id,c.person_id INTO v_container_owner,v_container_lot,v_owner
  FROM public.medication_containers c JOIN public.person_medications pm ON pm.id=c.person_medication_id WHERE c.id=NEW.container_id;
  IF v_container_owner IS DISTINCT FROM v_product THEN RAISE EXCEPTION 'container product mismatch';END IF;
  IF v_container_lot IS NOT NULL AND NEW.lot_id IS DISTINCT FROM v_container_lot THEN RAISE EXCEPTION 'container lot mismatch';END IF;
  IF NOT EXISTS(SELECT 1 FROM public.medication_stock_pools sp WHERE sp.id=v_pool AND (sp.pool_type<>'patient_assigned' OR sp.assigned_person_id=v_owner)) THEN
   RAISE EXCEPTION 'container is not assigned to compatible pool';END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_inventory_post(p_pool_id uuid, p_medication_id uuid, p_lot_id uuid, p_container_id uuid, p_source_location_id uuid, p_destination_location_id uuid, p_patient_id uuid, p_kind text, p_quantity numeric, p_unit text, p_actor uuid, p_key text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE old_tx record; src record; dst record; held numeric; source_balance_id uuid; target_balance_id uuid; tx_id uuid; pool record;
BEGIN
 IF p_key IS NULL OR length(p_key)<12 OR length(p_key)>200 OR p_quantity IS NULL OR p_quantity<=0 OR p_unit IS NULL OR btrim(p_unit)='' THEN RAISE EXCEPTION 'invalid transaction parameters';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('inv-idempotency:'||p_key,0));
 SELECT * INTO old_tx FROM public.medication_inventory_transactions WHERE idempotency_key=p_key;
 IF FOUND THEN
  IF old_tx.pool_id=p_pool_id AND old_tx.medication_id=p_medication_id AND old_tx.transaction_type=p_kind AND old_tx.quantity=p_quantity AND old_tx.quantity_unit=p_unit
  AND old_tx.source_location_id IS NOT DISTINCT FROM p_source_location_id AND old_tx.destination_location_id IS NOT DISTINCT FROM p_destination_location_id
  AND old_tx.patient_id IS NOT DISTINCT FROM p_patient_id AND old_tx.lot_id IS NOT DISTINCT FROM p_lot_id AND old_tx.container_id IS NOT DISTINCT FROM p_container_id AND old_tx.stock_container_id IS NULL
   THEN RETURN jsonb_build_object('ok',true,'duplicate',true,'transaction_id',old_tx.id);END IF;
  RAISE EXCEPTION 'idempotency key collision';
 END IF;
 SELECT * INTO pool FROM public.medication_stock_pools WHERE id=p_pool_id FOR SHARE;
 IF NOT FOUND OR pool.pool_type='quarantine' AND p_kind IN('dispense','consume') THEN RAISE EXCEPTION 'pool unavailable for dispensing';END IF;
 IF pool.pool_type='patient_assigned' AND p_patient_id IS NOT NULL AND pool.assigned_person_id<>p_patient_id THEN RAISE EXCEPTION 'patient mismatch';END IF;
 IF p_patient_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.family_persons WHERE family_id=pool.family_id AND person_id=p_patient_id AND status='active') THEN RAISE EXCEPTION 'patient not in family';END IF;
 IF p_kind NOT IN('receive','transfer','dispense','consume','dispose','adjust_in','adjust_out') THEN RAISE EXCEPTION 'invalid kind';END IF;
 IF p_kind IN('receive','adjust_in') AND (p_source_location_id IS NOT NULL OR p_destination_location_id IS NULL) THEN RAISE EXCEPTION 'invalid inbound locations';END IF;
 IF p_kind='transfer' AND (p_source_location_id IS NULL OR p_destination_location_id IS NULL OR p_source_location_id=p_destination_location_id) THEN RAISE EXCEPTION 'invalid transfer';END IF;
 IF p_kind IN('dispense','consume','dispose','adjust_out') AND (p_source_location_id IS NULL OR p_destination_location_id IS NOT NULL) THEN RAISE EXCEPTION 'invalid outbound locations';END IF;
 IF p_kind IN('dispense','consume') AND p_patient_id IS NULL THEN RAISE EXCEPTION 'patient required';END IF;
 IF p_source_location_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.medication_stock_locations WHERE id=p_source_location_id AND pool_id=p_pool_id AND active) THEN RAISE EXCEPTION 'invalid source location';END IF;
 IF p_destination_location_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.medication_stock_locations WHERE id=p_destination_location_id AND pool_id=p_pool_id AND active) THEN RAISE EXCEPTION 'invalid destination location';END IF;
 -- Serialize by product+pool to handle simultaneous caregivers and balance creation.
 PERFORM pg_advisory_xact_lock(hashtextextended(p_pool_id::text||':'||p_medication_id::text,0));
 IF p_source_location_id IS NOT NULL THEN
  SELECT * INTO src FROM public.medication_inventory_balances WHERE pool_id=p_pool_id AND location_id=p_source_location_id
  AND medication_id=p_medication_id AND lot_id IS NOT DISTINCT FROM p_lot_id AND container_id IS NOT DISTINCT FROM p_container_id AND stock_container_id IS NULL AND quantity_unit=p_unit FOR UPDATE;
  IF NOT FOUND OR src.quantity<p_quantity THEN RAISE EXCEPTION 'insufficient inventory';END IF;
  SELECT coalesce(sum(a.quantity),0) INTO held FROM public.medication_stock_allocations a WHERE a.balance_id=src.id AND a.status='reserved';
  IF src.quantity-held<p_quantity THEN RAISE EXCEPTION 'quantity reserved for patient';END IF;
  source_balance_id:=src.id;
 END IF;
 IF p_destination_location_id IS NOT NULL THEN
  INSERT INTO public.medication_inventory_balances(pool_id,location_id,medication_id,lot_id,container_id,quantity_unit,quantity)
  VALUES(p_pool_id,p_destination_location_id,p_medication_id,p_lot_id,p_container_id,p_unit,0)
  ON CONFLICT DO NOTHING;
  SELECT * INTO dst FROM public.medication_inventory_balances WHERE pool_id=p_pool_id AND location_id=p_destination_location_id
  AND medication_id=p_medication_id AND lot_id IS NOT DISTINCT FROM p_lot_id AND container_id IS NOT DISTINCT FROM p_container_id AND stock_container_id IS NULL AND quantity_unit=p_unit FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'destination balance unavailable';END IF;
  target_balance_id:=dst.id;
 END IF;
 IF source_balance_id IS NOT NULL THEN UPDATE public.medication_inventory_balances SET quantity=quantity-p_quantity,updated_at=now() WHERE id=source_balance_id;END IF;
 IF target_balance_id IS NOT NULL THEN UPDATE public.medication_inventory_balances SET quantity=quantity+p_quantity,updated_at=now() WHERE id=target_balance_id;END IF;
 INSERT INTO public.medication_inventory_transactions(pool_id,medication_id,lot_id,container_id,source_location_id,destination_location_id,patient_id,transaction_type,quantity,quantity_unit,actor_id,idempotency_key,reason)
 VALUES(p_pool_id,p_medication_id,p_lot_id,p_container_id,p_source_location_id,p_destination_location_id,p_patient_id,p_kind,p_quantity,p_unit,p_actor,p_key,p_reason)
 RETURNING id INTO tx_id;
 RETURN jsonb_build_object('ok',true,'duplicate',false,'transaction_id',tx_id);
END $function$

