CREATE OR REPLACE FUNCTION public.phms_med_v23_inventory_release(p_allocation_id uuid, p_actor uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE a record;
BEGIN
 IF nullif(btrim(coalesce(p_reason,'')),'') IS NULL THEN RAISE EXCEPTION 'release reason required';END IF;
 SELECT * INTO a FROM public.medication_stock_allocations WHERE id=p_allocation_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'allocation missing';END IF;
 IF a.status='released' THEN RETURN jsonb_build_object('ok',true,'already_released',true);END IF;
 IF a.status<>'reserved' THEN RAISE EXCEPTION 'allocation cannot release';END IF;
 UPDATE public.medication_stock_allocations SET status='released',updated_at=now() WHERE id=p_allocation_id;
 RETURN jsonb_build_object('ok',true,'released',true);
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_line_container_event(p_line_user_id text, p_container_id uuid, p_event text, p_event_at timestamp with time zone, p_reason text, p_key text, p_new_container_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE ctx record;c record;n record;previous record;event_id uuid;new_status text;
BEGIN
 SELECT * INTO ctx FROM private.phms_line_crud_context(p_line_user_id,'medication','update');
 IF p_key IS NULL OR length(p_key)<12 THEN RAISE EXCEPTION 'invalid_idempotency_key';END IF;
 SELECT * INTO previous FROM public.medication_container_lifecycle_events WHERE idempotency_key=p_key;
 IF FOUND THEN
  IF previous.container_id=p_container_id AND previous.event_type=p_event THEN RETURN jsonb_build_object('ok',true,'duplicate',true,'event_id',previous.id);END IF;
  RAISE EXCEPTION 'idempotency_conflict';
 END IF;
 SELECT * INTO c FROM public.medication_containers WHERE id=p_container_id AND person_id=ctx.target_person_id AND deleted_at IS NULL FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'container_not_found_or_denied';END IF;
 IF p_event NOT IN('opened','closed','emptied','discarded','quarantined','checked') THEN RAISE EXCEPTION 'invalid_event_type';END IF;
 IF p_event_at IS NULL OR p_event_at>now()+interval '5 minutes' THEN RAISE EXCEPTION 'invalid_event_time';END IF;
 IF p_event='opened' THEN
  IF c.lifecycle_status<>'unopened' OR c.opened_at IS NOT NULL THEN RAISE EXCEPTION 'container_already_opened_or_closed';END IF;
  new_status:='opened';
 ELSIF p_event IN('closed','discarded','quarantined') THEN
  IF c.lifecycle_status IN('retired','empty','expired') THEN RAISE EXCEPTION 'container_already_closed';END IF;
  IF nullif(trim(coalesce(p_reason,'')),'') IS NULL THEN RAISE EXCEPTION 'closing_reason_required';END IF;
  new_status:='retired';
 ELSIF p_event='emptied' THEN
  IF c.lifecycle_status IN('retired','empty','expired') THEN RAISE EXCEPTION 'container_already_closed';END IF;
  new_status:='empty';
 ELSE new_status:=c.lifecycle_status;
 END IF;
 IF p_new_container_id IS NOT NULL THEN
  SELECT * INTO n FROM public.medication_containers WHERE id=p_new_container_id AND person_id=ctx.target_person_id AND deleted_at IS NULL;
  IF NOT FOUND OR n.id=c.id OR n.person_medication_id<>c.person_medication_id THEN RAISE EXCEPTION 'replacement_container_mismatch';END IF;
 END IF;
 INSERT INTO public.medication_container_lifecycle_events(container_id,event_type,event_at,recorded_by,reason,replacement_container_id,idempotency_key)
 VALUES(c.id,p_event,p_event_at,ctx.actor_user_id,p_reason,p_new_container_id,p_key) RETURNING id INTO event_id;
 IF p_event<>'checked' THEN
  UPDATE public.medication_containers SET lifecycle_status=new_status,
   opened_at=CASE WHEN p_event='opened' THEN p_event_at ELSE opened_at END,
   opened_by=CASE WHEN p_event='opened' THEN ctx.actor_user_id ELSE opened_by END,
   emptied_at=CASE WHEN p_event='emptied' THEN p_event_at ELSE emptied_at END,
   retired_at=CASE WHEN p_event IN('closed','discarded','quarantined') THEN p_event_at ELSE retired_at END,
   retirement_reason=CASE WHEN p_event IN('closed','discarded','quarantined') THEN p_reason ELSE retirement_reason END,
   updated_at=now()
  WHERE id=c.id;
 END IF;
 RETURN jsonb_build_object('ok',true,'event_id',event_id,'status',new_status);
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_line_correct(p_line_user_id text, p_event_id uuid, p_correction_type text, p_reason text, p_values jsonb, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE ctx record; ev record; new_id uuid; prev record;
BEGIN
 SELECT * INTO ctx FROM private.phms_line_crud_context(p_line_user_id,'medication','update');
 SELECT * INTO ev FROM public.medication_administration_events WHERE id=p_event_id AND person_id=ctx.target_person_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'event_not_found_or_denied'; END IF;
 IF p_idempotency_key IS NULL OR length(p_idempotency_key)<8 OR length(p_idempotency_key)>200 THEN RAISE EXCEPTION 'invalid_idempotency_key';END IF;
 SELECT * INTO prev FROM public.medication_administration_corrections WHERE idempotency_key=p_idempotency_key;
 IF FOUND THEN
  IF prev.administration_event_id=p_event_id THEN RETURN jsonb_build_object('ok',true,'duplicate',true,'correction_id',prev.id);END IF;
  RAISE EXCEPTION 'idempotency_key_conflict';
 END IF;
 IF p_correction_type NOT IN ('void','clarify') OR nullif(trim(coalesce(p_reason,'')),'') IS NULL THEN
  RAISE EXCEPTION 'only_void_or_clarify_allowed_for_line';
 END IF;
 IF p_values IS NOT NULL AND p_values<>'{}'::jsonb THEN RAISE EXCEPTION 'structured_amendment_requires_separate_verification';END IF;
 IF p_correction_type='void' AND EXISTS(SELECT 1 FROM public.medication_administration_corrections WHERE administration_event_id=p_event_id AND correction_type='void') THEN
  RAISE EXCEPTION 'already_voided';
 END IF;
 INSERT INTO public.medication_administration_corrections(administration_event_id,corrected_by,reason,correction_type,corrected_values,idempotency_key)
 VALUES(p_event_id,ctx.actor_user_id,p_reason,p_correction_type,'{}'::jsonb,p_idempotency_key) RETURNING id INTO new_id;
 RETURN jsonb_build_object('ok',true,'duplicate',false,'correction_id',new_id);
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_line_dashboard(p_line_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE ctx record; med_count int; verified_count int; due_count int; administration_count int; safety_count int; allergy_count int; stock_count int; prep_count int; dispense_count int; expenses_count int;
BEGIN
 SELECT * INTO ctx FROM private.phms_line_crud_context(p_line_user_id,'medication','view');
 IF ctx.target_person_id IS NULL THEN RAISE EXCEPTION 'person_required'; END IF;
 SELECT count(*),count(*) FILTER (WHERE verification_label='VERIFIED') INTO med_count,verified_count FROM public.medication_current_list_v WHERE person_id=ctx.target_person_id;
 SELECT count(*) INTO due_count FROM public.medication_today_schedule_v WHERE person_id=ctx.target_person_id;
 SELECT count(*) INTO administration_count FROM public.medication_daily_administration_v WHERE person_id=ctx.target_person_id AND administration_date=(now() AT TIME ZONE 'Asia/Bangkok')::date;
 SELECT count(*) INTO safety_count FROM public.medication_safety_reviews WHERE person_id=ctx.target_person_id AND status IN ('PENDING_REVIEW','BLOCKED','UNDER_REVIEW');
 SELECT count(*) INTO allergy_count FROM public.allergies WHERE person_id=ctx.target_person_id AND deleted_at IS NULL;
 SELECT count(*) INTO prep_count FROM public.medication_preparation_sessions WHERE person_id=ctx.target_person_id AND status NOT IN ('CANCELLED');
 SELECT count(*) INTO dispense_count FROM public.medication_dispenses d JOIN public.person_medications pm ON pm.id=d.person_medication_id WHERE pm.person_id=ctx.target_person_id AND d.deleted_at IS NULL;
 SELECT count(*) INTO expenses_count FROM public.medication_expense_links link JOIN public.medication_dispenses d ON d.id=link.dispense_id JOIN public.person_medications pm ON pm.id=d.person_medication_id WHERE pm.person_id=ctx.target_person_id;
 RETURN jsonb_build_object('ok',true,'person_id',ctx.target_person_id,'person_name',ctx.target_person_name,
 'medication_records',med_count,'verified_orders',verified_count,'today_scheduled',due_count,'today_administrations',administration_count,
 'pending_safety',safety_count,'allergy_records',allergy_count,'preparation_sessions',prep_count,'dispense_records',dispense_count,'expense_links',expenses_count,
 'as_of',now(),'disclaimer','Historical entries are not necessarily verified current medical orders');
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_line_exception(p_line_user_id text, p_round_id uuid, p_exception_type text, p_explanation text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE ctx record; rd record; found_event record; event_id uuid;
BEGIN
 SELECT * INTO ctx FROM private.phms_line_crud_context(p_line_user_id,'medication','create');
 IF p_idempotency_key IS NULL OR length(p_idempotency_key)<8 OR length(p_idempotency_key)>200 THEN RAISE EXCEPTION 'invalid_idempotency_key';END IF;
 SELECT * INTO rd FROM public.medication_round_instances WHERE id=p_round_id AND person_id=ctx.target_person_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'round_not_found_or_denied';END IF;
 SELECT * INTO found_event FROM public.medication_round_exceptions WHERE idempotency_key=p_idempotency_key;
 IF FOUND THEN
  IF found_event.round_id=p_round_id THEN RETURN jsonb_build_object('ok',true,'duplicate',true,'exception_id',found_event.id);END IF;
  RAISE EXCEPTION 'idempotency_key_conflict';
 END IF;
 IF p_exception_type NOT IN ('late_wake','late_sleep','missed','hold','overlap','other') OR nullif(trim(coalesce(p_explanation,'')),'') IS NULL THEN RAISE EXCEPTION 'invalid_round_exception';END IF;
 INSERT INTO public.medication_round_exceptions(round_id,exception_type,occurred_at,recorded_by,explanation,idempotency_key)
 VALUES(p_round_id,p_exception_type,now(),ctx.actor_user_id,p_explanation,p_idempotency_key)
 RETURNING id INTO event_id;
 UPDATE public.medication_round_instances SET state='exception' WHERE id=p_round_id;
 RETURN jsonb_build_object('ok',true,'duplicate',false,'exception_id',event_id,'status','pending_review');
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_line_inventory_bootstrap(p_line_user_id text, p_pool_type text, p_name text, p_location_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE ctx record; new_pool uuid; new_location uuid;
BEGIN
 SELECT * INTO ctx FROM private.phms_line_crud_context(p_line_user_id,'medication','create');
 IF ctx.active_family_id IS NULL OR p_pool_type NOT IN('patient_assigned','quarantine','shared') THEN RAISE EXCEPTION 'unsupported pool scope';END IF;
 IF length(btrim(coalesce(p_name,''))) NOT BETWEEN 2 AND 100 OR length(btrim(coalesce(p_location_name,''))) NOT BETWEEN 2 AND 100 THEN RAISE EXCEPTION 'invalid name';END IF;
 IF p_pool_type IN('shared','quarantine') AND NOT EXISTS(
  SELECT 1 FROM public.family_role_assignments r WHERE r.family_id=ctx.active_family_id AND r.user_id=ctx.actor_user_id
  AND r.role IN('owner','admin') AND r.status='active'
 ) THEN RAISE EXCEPTION 'family_admin_required_for_household_pool';END IF;
 IF p_pool_type='patient_assigned' AND EXISTS(
  SELECT 1 FROM public.medication_stock_pools WHERE family_id=ctx.active_family_id
  AND assigned_person_id=ctx.target_person_id AND pool_type='patient_assigned'
 ) THEN RAISE EXCEPTION 'assigned_pool_already_exists';END IF;
 INSERT INTO public.medication_stock_pools(family_id,assigned_person_id,pool_type,name)
 VALUES(ctx.active_family_id,CASE WHEN p_pool_type='patient_assigned' THEN ctx.target_person_id ELSE NULL END,p_pool_type,p_name)
 RETURNING id INTO new_pool;
 INSERT INTO public.medication_stock_locations(pool_id,name)
 VALUES(new_pool,p_location_name) RETURNING id INTO new_location;
 RETURN jsonb_build_object('ok',true,'pool_id',new_pool,'location_id',new_location);
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_line_inventory_intake_commit(p_line_user_id text, p_pool_id uuid, p_location_id uuid, p_medication_id uuid, p_lot_number text, p_expiry date, p_bottle_label text, p_quantity numeric, p_unit text, p_source_description text, p_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE ctx record; pool_row record; lot_ref uuid; lot_row record; stocked jsonb; physical jsonb; source_label text;
BEGIN
 SELECT * INTO ctx FROM private.phms_line_crud_context(p_line_user_id,'medication','create');
 IF p_key IS NULL OR length(p_key)<12 OR length(p_key)>170 OR p_quantity IS NULL OR p_quantity<=0 THEN RAISE EXCEPTION 'invalid_intake_data';END IF;
 IF length(btrim(coalesce(p_source_description,''))) NOT BETWEEN 3 AND 500 OR length(btrim(coalesce(p_bottle_label,''))) NOT BETWEEN 3 AND 80 THEN RAISE EXCEPTION 'source_and_bottle_required';END IF;
 IF nullif(trim(coalesce(p_unit,'')),'') IS NULL OR length(p_unit)>30 THEN RAISE EXCEPTION 'unit_required';END IF;
 IF p_expiry IS NOT NULL AND p_expiry<date '1990-01-01' THEN RAISE EXCEPTION 'invalid_expiry';END IF;
 SELECT * INTO pool_row FROM public.medication_stock_pools WHERE id=p_pool_id AND family_id=ctx.active_family_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'pool_not_in_family';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.medication_stock_locations WHERE id=p_location_id AND pool_id=p_pool_id AND active) THEN RAISE EXCEPTION 'location_not_in_pool';END IF;
 IF pool_row.pool_type='patient_assigned' THEN
  IF pool_row.assigned_person_id<>ctx.target_person_id OR NOT EXISTS(
    SELECT 1 FROM public.person_medications WHERE person_id=ctx.target_person_id AND medication_id=p_medication_id AND deleted_at IS NULL
  ) THEN RAISE EXCEPTION 'person_medication_missing';END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM public.family_role_assignments WHERE family_id=ctx.active_family_id AND user_id=ctx.actor_user_id AND role IN('owner','admin') AND status='active') THEN RAISE EXCEPTION 'family_admin_required';END IF;
 END IF;
 IF nullif(btrim(coalesce(p_lot_number,'')),'') IS NOT NULL THEN
  PERFORM pg_advisory_xact_lock(hashtextextended('lot:'||p_medication_id::text||':'||lower(btrim(p_lot_number)),0));
  SELECT * INTO lot_row FROM public.medication_lots WHERE medication_id=p_medication_id AND lower(btrim(lot_number))=lower(btrim(p_lot_number)) AND deleted_at IS NULL LIMIT 1;
  IF FOUND THEN
   IF p_expiry IS NOT NULL AND lot_row.manufacturer_expiry_date IS NOT NULL AND lot_row.manufacturer_expiry_date<>p_expiry THEN RAISE EXCEPTION 'lot_expiry_conflict';END IF;
   lot_ref:=lot_row.id;
  ELSE
   INSERT INTO public.medication_lots(medication_id,lot_number,manufacturer_expiry_date) VALUES(p_medication_id,btrim(p_lot_number),p_expiry) RETURNING id INTO lot_ref;
  END IF;
 END IF;
 physical:=public.phms_med_v23_line_register_stock_container(
  p_line_user_id,p_pool_id,p_medication_id,lot_ref,p_bottle_label,p_expiry,NULL,p_key||':bottle');
 stocked:=public.phms_med_v23_line_inventory_stock_move(
  p_line_user_id,(physical->>'stock_container_id')::uuid,NULL,p_location_id,NULL,'receive',p_quantity,p_unit,p_key||':receive',p_source_description);
 RETURN jsonb_build_object('ok',true,'stock_container_id',physical->>'stock_container_id',
  'transaction_id',stocked->>'transaction_id','duplicate',stocked->'duplicate',
  'clinical_verification','not_inferred','expiry_status',CASE WHEN p_expiry IS NULL THEN 'unknown' ELSE 'reported' END);
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_line_inventory_receive(p_line_user_id text, p_pool_id uuid, p_location_id uuid, p_medication_id uuid, p_lot_id uuid, p_container_id uuid, p_quantity numeric, p_unit text, p_key text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE ctx record; pool record;
BEGIN
 SELECT * INTO ctx FROM private.phms_line_crud_context(p_line_user_id,'medication','create');
 SELECT * INTO pool FROM public.medication_stock_pools WHERE id=p_pool_id AND family_id=ctx.active_family_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'pool_out_of_scope';END IF;
 IF pool.pool_type='patient_assigned' AND pool.assigned_person_id<>ctx.target_person_id THEN RAISE EXCEPTION 'person_out_of_scope';END IF;
 IF pool.pool_type='shared' THEN
  RAISE EXCEPTION 'shared_stock_requires_dispensing_rights_review';
 END IF;
 RETURN public.phms_med_v23_inventory_post(p_pool_id,p_medication_id,p_lot_id,p_container_id,
  NULL,p_location_id,CASE WHEN pool.pool_type='patient_assigned' THEN ctx.target_person_id ELSE NULL END,
  'receive',p_quantity,p_unit,ctx.actor_user_id,p_key,p_reason);
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_line_inventory_stock_move(p_line_user_id text, p_stock_container_id uuid, p_source_location_id uuid, p_destination_location_id uuid, p_patient_id uuid, p_kind text, p_quantity numeric, p_unit text, p_key text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE ctx record;c record;p record; result jsonb;
BEGIN
 SELECT * INTO ctx FROM private.phms_line_crud_context(p_line_user_id,'medication',
 CASE WHEN p_kind='receive' THEN 'create' ELSE 'update' END);
 SELECT * INTO c FROM public.medication_stock_containers WHERE id=p_stock_container_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'unknown_physical_container'; END IF;
 SELECT * INTO p FROM public.medication_stock_pools WHERE id=c.pool_id AND family_id=ctx.active_family_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'pool_not_in_family';END IF;
 IF p.pool_type='patient_assigned' AND p.assigned_person_id<>ctx.target_person_id THEN RAISE EXCEPTION 'patient_scope_mismatch';END IF;
 IF p.pool_type<>'patient_assigned' AND NOT EXISTS(
 SELECT 1 FROM public.family_role_assignments r WHERE r.family_id=p.family_id AND r.user_id=ctx.actor_user_id AND r.role IN('owner','admin') AND r.status='active') THEN
 RAISE EXCEPTION 'shared_pool_requires_family_admin'; END IF;
 IF p_patient_id IS NOT NULL AND p_patient_id<>ctx.target_person_id THEN RAISE EXCEPTION 'selected_person_mismatch';END IF;
 IF p_kind IN('dispense','consume') AND (p_patient_id IS NULL OR NOT EXISTS(
 SELECT 1 FROM public.person_medications pm JOIN public.medication_order_versions v ON v.person_medication_id=pm.id
 WHERE pm.person_id=p_patient_id AND pm.medication_id=c.medication_id AND pm.deleted_at IS NULL AND v.status='verified'
 )) THEN RAISE EXCEPTION 'person_medication_order_not_verified';END IF;
 IF p_kind IN('receive','adjust_in','adjust_out') AND nullif(trim(coalesce(p_reason,'')),'') IS NULL THEN RAISE EXCEPTION 'source_or_reason_required';END IF;
 result:=public.phms_med_v23_inventory_post_stock(c.pool_id,c.medication_id,c.lot_id,NULL,
 p_source_location_id,p_destination_location_id,p_patient_id,p_kind,p_quantity,p_unit,ctx.actor_user_id,p_key,p_reason,c.id);
 IF p_kind='receive' AND (result->>'duplicate')::boolean IS FALSE THEN
  INSERT INTO public.medication_inventory_receipt_evidence(transaction_id,source_kind,source_description,received_at,recorded_by)
  VALUES((result->>'transaction_id')::uuid,'manual_report',p_reason,now(),ctx.actor_user_id);
 END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_line_preparation_add(p_line_user_id text, p_session_id uuid, p_scheduled_dose_id uuid, p_lot_id uuid DEFAULT NULL::uuid, p_stock_container_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE c record;s record;d record;pid uuid;itemid uuid;
BEGIN
 SELECT * INTO c FROM private.phms_line_crud_context(p_line_user_id,'medication','update');
 SELECT * INTO s FROM public.medication_preparation_sessions WHERE id=p_session_id AND person_id=c.target_person_id FOR UPDATE;
 IF NOT FOUND OR s.status<>'DRAFT' THEN RAISE EXCEPTION 'session_not_editable_or_denied';END IF;
 SELECT * INTO d FROM public.medication_scheduled_doses WHERE id=p_scheduled_dose_id AND person_id=s.person_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'dose_not_found_or_denied';END IF;
 SELECT medication_id INTO pid FROM public.person_medications WHERE id=d.person_medication_id;
 INSERT INTO public.medication_preparation_items(session_id,scheduled_dose_id,person_medication_id,order_version_id,medication_id,lot_id,stock_container_id,quantity,unit)
 VALUES(s.id,d.id,d.person_medication_id,d.order_version_id,pid,p_lot_id,p_stock_container_id,d.planned_dose,d.planned_unit)
 ON CONFLICT(session_id,scheduled_dose_id) DO NOTHING RETURNING id INTO itemid;
 RETURN jsonb_build_object('ok',true,'item_id',coalesce(itemid,(SELECT id FROM public.medication_preparation_items WHERE session_id=s.id AND scheduled_dose_id=d.id)),'duplicate',itemid IS NULL);
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_line_preparation_check(p_line_user_id text, p_session_id uuid, p_check_type text, p_passed boolean, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE c record;s record;cid uuid;
BEGIN
 SELECT * INTO c FROM private.phms_line_crud_context(p_line_user_id,'medication','update');
 SELECT * INTO s FROM public.medication_preparation_sessions WHERE id=p_session_id AND person_id=c.target_person_id FOR UPDATE;
 IF NOT FOUND OR s.status NOT IN ('REVIEWED','PREPARING','PREPARED') THEN RAISE EXCEPTION 'session_not_reviewable';END IF;
 IF p_check_type NOT IN ('order','quantity','identity','lot_expiry','packaging_stability','final_review')
 OR p_passed IS NULL THEN RAISE EXCEPTION 'invalid_check';END IF;
 IF nullif(trim(coalesce(p_note,'')),'') IS NULL THEN RAISE EXCEPTION 'review_evidence_required';END IF;
 INSERT INTO public.medication_preparation_checks(session_id,check_type,passed,checked_by,notes)
 VALUES(p_session_id,p_check_type,p_passed,c.actor_user_id,p_note) RETURNING id INTO cid;
 RETURN jsonb_build_object('ok',true,'check_id',cid);
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_line_preparation_eligible(p_line_user_id text, p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE c record;s record;j jsonb;dt date;
BEGIN
 SELECT * INTO c FROM private.phms_line_crud_context(p_line_user_id,'medication','view');
 SELECT * INTO s FROM public.medication_preparation_sessions WHERE id=p_session_id AND person_id=c.target_person_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'session_not_found_or_denied';END IF;
 IF s.status='DRAFT' THEN
  FOR dt IN SELECT generate_series(s.start_date,s.end_date,'1 day'::interval)::date LOOP
   PERFORM public.phms_med_v23_generate_day(c.target_person_id,dt,'Asia/Bangkok');
  END LOOP;
 END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',d.id,'name',coalesce(mm.brand_name,mm.generic_name),
  'date',d.planned_date,'slot',d.slot_key,'quantity',d.planned_dose,'unit',d.planned_unit,
  'in_session',i.id IS NOT NULL) ORDER BY d.planned_date,d.scheduled_at,d.id),'[]'::jsonb) INTO j
 FROM public.medication_scheduled_doses d
 JOIN public.medication_order_versions v ON v.id=d.order_version_id
 JOIN public.person_medications pm ON pm.id=d.person_medication_id
 JOIN public.medication_master mm ON mm.id=pm.medication_id
 LEFT JOIN public.medication_preparation_items i ON i.scheduled_dose_id=d.id AND i.session_id=s.id
 WHERE d.person_id=s.person_id AND d.planned_date BETWEEN s.start_date AND s.end_date
 AND d.state='planned' AND v.status='verified' AND v.verified_at IS NOT NULL;
 RETURN jsonb_build_object('ok',true,'session_id',s.id,'status',s.status,'person_name',c.target_person_name,'doses',j);
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_line_preparation_pack(p_line_user_id text, p_item_id uuid, p_allocation_id uuid, p_packaging_source_id uuid, p_evidence text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE ctx record; sid uuid; changed uuid;b record;
BEGIN
 SELECT * INTO ctx FROM private.phms_line_crud_context(p_line_user_id,'medication','update');
 SELECT i.session_id INTO sid FROM public.medication_preparation_items i
 JOIN public.medication_preparation_sessions s ON s.id=i.session_id
 WHERE i.id=p_item_id AND s.person_id=ctx.target_person_id;
 IF sid IS NULL THEN RAISE EXCEPTION 'preparation_item_not_found_or_denied';END IF;
 IF nullif(btrim(coalesce(p_evidence,'')),'') IS NULL THEN RAISE EXCEPTION 'packaging_evidence_required';END IF;
 SELECT b0.* INTO b FROM public.medication_stock_allocations a
 JOIN public.medication_inventory_balances b0 ON b0.id=a.balance_id
 WHERE a.id=p_allocation_id AND a.patient_id=ctx.target_person_id AND a.status='reserved';
 IF NOT FOUND THEN RAISE EXCEPTION 'allocation_not_available';END IF;
 UPDATE public.medication_preparation_items
 SET allocation_id=p_allocation_id,lot_id=b.lot_id,stock_container_id=b.stock_container_id,legacy_container_id=b.container_id,
 packaging_source_id=p_packaging_source_id,packaging_evidence=p_evidence,
 packaging_verified=true,packaging_verified_at=now(),packaging_verified_by=ctx.actor_user_id,state='PACKED'
 WHERE id=p_item_id RETURNING id INTO changed;
 RETURN jsonb_build_object('ok',true,'item_id',changed,'state','PACKED');
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_line_preparation_remove(p_line_user_id text, p_item_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE c record;i record;s record;
BEGIN
 SELECT * INTO c FROM private.phms_line_crud_context(p_line_user_id,'medication','update');
 IF nullif(btrim(coalesce(p_reason,'')),'') IS NULL THEN RAISE EXCEPTION 'reason_required';END IF;
 SELECT * INTO i FROM public.medication_preparation_items WHERE id=p_item_id FOR UPDATE;
 SELECT * INTO s FROM public.medication_preparation_sessions WHERE id=i.session_id AND person_id=c.target_person_id FOR UPDATE;
 IF NOT FOUND OR s.status<>'DRAFT' THEN RAISE EXCEPTION 'item_removal_requires_draft';END IF;
 UPDATE public.medication_preparation_items SET state='REMOVED',packaging_verified=false,packaging_verified_by=null,
 packaging_verified_at=null,packaging_evidence=null,packaging_source_id=null,allocation_id=null
 WHERE id=i.id;
 RETURN jsonb_build_object('ok',true,'item_id',i.id,'state','REMOVED');
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_line_preparation_resolve_impact(p_line_user_id text, p_impact_id uuid, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE c record;imp record;item record;sid uuid;
BEGIN
 SELECT * INTO c FROM private.phms_line_crud_context(p_line_user_id,'medication','update');
 IF nullif(btrim(coalesce(p_note,'')),'') IS NULL THEN RAISE EXCEPTION 'resolution_note_required';END IF;
 SELECT x.* INTO imp FROM public.medication_preparation_impacts x
 JOIN public.medication_preparation_sessions s ON s.id=x.session_id
 WHERE x.id=p_impact_id AND s.person_id=c.target_person_id FOR UPDATE OF x;
 IF NOT FOUND OR imp.status<>'PENDING_REVIEW' THEN RAISE EXCEPTION 'impact_not_pending_or_denied';END IF;
 SELECT * INTO item FROM public.medication_preparation_items WHERE id=imp.item_id;
 IF item.id IS NOT NULL AND item.state<>'REMOVED' THEN RAISE EXCEPTION 'affected_item_must_be_removed_or_reworked';END IF;
 UPDATE public.medication_preparation_impacts SET status='RESOLVED',resolved_by=c.actor_user_id,resolved_at=now(),resolution_notes=p_note WHERE id=imp.id;
 RETURN jsonb_build_object('ok',true,'impact_id',imp.id,'status','RESOLVED');
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_line_preparation_start(p_line_user_id text, p_start date, p_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE c record;sid uuid;dt date; count_doses int;
BEGIN
 SELECT * INTO c FROM private.phms_line_crud_context(p_line_user_id,'medication','create');
 IF p_start IS NULL OR p_end IS NULL OR p_end<p_start OR p_end-p_start>30 THEN RAISE EXCEPTION 'invalid_preparation_dates';END IF;
 IF p_start<(now() AT TIME ZONE 'Asia/Bangkok')::date THEN RAISE EXCEPTION 'cannot_prepare_historical_doses';END IF;
 FOR dt IN SELECT generate_series(p_start,p_end,'1 day'::interval)::date LOOP
  PERFORM public.phms_med_v23_generate_day(c.target_person_id,dt,'Asia/Bangkok');
 END LOOP;
 SELECT count(*) INTO count_doses FROM public.medication_scheduled_doses d
 JOIN public.medication_order_versions v ON v.id=d.order_version_id
 WHERE d.person_id=c.target_person_id AND d.planned_date BETWEEN p_start AND p_end AND d.state='planned' AND v.status='verified';
 IF count_doses=0 THEN RAISE EXCEPTION 'no_verified_scheduled_doses_to_prepare';END IF;
 INSERT INTO public.medication_preparation_sessions(person_id,start_date,end_date,prepared_by)
 VALUES(c.target_person_id,p_start,p_end,c.actor_user_id) RETURNING id INTO sid;
 RETURN jsonb_build_object('ok',true,'session_id',sid,'status','DRAFT','eligible_scheduled_doses',count_doses);
END $function$

