CREATE OR REPLACE FUNCTION public.phms_med_v23_line_read_page(p_line_user_id text, p_page text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE ctx record; items jsonb:='[]'::jsonb;
BEGIN
 SELECT * INTO ctx FROM private.phms_line_crud_context(p_line_user_id,'medication','view');
 IF ctx.target_person_id IS NULL THEN RAISE EXCEPTION 'person_required'; END IF;
 CASE p_page
 WHEN 'list' THEN
 SELECT coalesce(jsonb_agg(jsonb_build_object('name',coalesce(brand_name,generic_name),'generic',generic_name,'strength',concat_ws(' ',strength_value,strength_unit),'status',medication_status,'verification',verification_label,'dose_schedule',dose_schedule,'person_medication_id',person_medication_id) ORDER BY generic_name),'[]'::jsonb) INTO items FROM public.medication_current_list_v WHERE person_id=ctx.target_person_id;
 WHEN 'schedule' THEN
 SELECT coalesce(jsonb_agg(jsonb_build_object('name',coalesce(m.brand_name,m.generic_name),'slot',d.slot_key,'time',d.scheduled_at,'planned_dose',d.planned_dose,'unit',d.planned_unit,'state',d.state,'review',d.order_review_status) ORDER BY d.scheduled_at),'[]'::jsonb) INTO items FROM public.medication_today_schedule_v d JOIN public.person_medications pm ON pm.id=d.person_medication_id JOIN public.medication_master m ON m.id=pm.medication_id WHERE d.person_id=ctx.target_person_id;
 WHEN 'history' THEN
 SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.occurred_at DESC),'[]'::jsonb) INTO items FROM (SELECT occurred_at,outcome,evidence_type,actual_dose,actual_unit,symptom FROM public.medication_daily_administration_v WHERE person_id=ctx.target_person_id ORDER BY occurred_at DESC LIMIT 20) t;
 WHEN 'changes' THEN
 SELECT coalesce(jsonb_agg(jsonb_build_object('change_type',change_type,'effective_at',effective_at,'reason',reason) ORDER BY effective_at DESC),'[]'::jsonb) INTO items FROM public.medication_change_summary_v WHERE person_id=ctx.target_person_id;
 WHEN 'allergies' THEN
 SELECT coalesce(jsonb_agg(jsonb_build_object('allergen',allergen,'reaction',reaction,'severity',severity,'verification',verified_status)),'[]'::jsonb) INTO items FROM public.allergies WHERE person_id=ctx.target_person_id AND deleted_at IS NULL;
 WHEN 'safety' THEN
 SELECT coalesce(jsonb_agg(jsonb_build_object('type',review_type,'finding',finding,'severity',severity,'status',status) ORDER BY detected_at DESC),'[]'::jsonb) INTO items FROM public.medication_safety_reviews WHERE person_id=ctx.target_person_id AND status IN ('PENDING_REVIEW','BLOCKED','UNDER_REVIEW');
 WHEN 'prn' THEN
 SELECT coalesce(jsonb_agg(jsonb_build_object('symptom',symptom,'assessed_at',assessed_at,'before',severity_before,'after',severity_after,'response',response_notes) ORDER BY assessed_at DESC),'[]'::jsonb) INTO items FROM (SELECT * FROM public.medication_prn_assessments WHERE person_id=ctx.target_person_id ORDER BY assessed_at DESC LIMIT 20) p;
 WHEN 'dispense' THEN
 SELECT coalesce(jsonb_agg(jsonb_build_object('name',coalesce(m.brand_name,m.generic_name),'received_at',d.dispensed_at,'quantity',d.quantity,'unit',d.quantity_unit) ORDER BY d.dispensed_at DESC),'[]'::jsonb) INTO items FROM public.medication_dispenses d JOIN public.person_medications pm ON pm.id=d.person_medication_id JOIN public.medication_master m ON m.id=pm.medication_id WHERE pm.person_id=ctx.target_person_id AND d.deleted_at IS NULL;
 WHEN 'emergency' THEN
 SELECT coalesce(jsonb_agg(to_jsonb(e)),'[]'::jsonb) INTO items FROM public.medication_emergency_summary_v e WHERE e.person_id=ctx.target_person_id;
 WHEN 'expense' THEN
 SELECT coalesce(jsonb_agg(jsonb_build_object('expense_date',ex.expense_date,'item',ei.label,'amount',link.allocated_amount,'currency',ex.currency)),'[]'::jsonb) INTO items
 FROM public.medication_expense_links link JOIN public.medication_dispenses d ON d.id=link.dispense_id JOIN public.person_medications pm ON pm.id=d.person_medication_id JOIN public.healthcare_expense_items ei ON ei.id=link.expense_item_id JOIN public.healthcare_expenses ex ON ex.id=ei.expense_id WHERE pm.person_id=ctx.target_person_id;
 ELSE RAISE EXCEPTION 'unsupported_page';
 END CASE;
 RETURN jsonb_build_object('ok',true,'page',p_page,'person_name',ctx.target_person_name,'items',items,'count',jsonb_array_length(items));
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_line_record(p_line_user_id text, p_scheduled_id uuid, p_outcome text, p_evidence text, p_actual_at timestamp with time zone, p_actual_dose numeric, p_actual_unit text, p_performed_by uuid, p_idempotency_key text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE ctx record; d record; existing record; replay record; new_id uuid; actual_performer uuid; replaced_id uuid;
BEGIN
 SELECT * INTO ctx FROM private.phms_line_crud_context(p_line_user_id,'medication','create');
 IF p_idempotency_key IS NULL OR length(p_idempotency_key)<8 OR length(p_idempotency_key)>200 THEN RAISE EXCEPTION 'invalid idempotency key';END IF;
 SELECT * INTO replay FROM public.medication_administration_events WHERE idempotency_key=p_idempotency_key;
 IF FOUND THEN
  IF replay.person_id=ctx.target_person_id AND replay.scheduled_dose_id=p_scheduled_id THEN
   RETURN jsonb_build_object('ok',true,'duplicate',true,'event_id',replay.id);
  END IF;
  RAISE EXCEPTION 'idempotency_key_conflict';
 END IF;
 SELECT * INTO d FROM public.medication_scheduled_doses WHERE id=p_scheduled_id AND person_id=ctx.target_person_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'scheduled_dose_not_found_or_denied';END IF;
 IF d.state<>'planned' OR NOT EXISTS(SELECT 1 FROM public.medication_order_versions v WHERE v.id=d.order_version_id AND v.status='verified' AND v.verified_at IS NOT NULL) THEN
  RAISE EXCEPTION 'unverified_or_inactive_dose';
 END IF;
 SELECT * INTO existing FROM public.medication_administration_events e
 WHERE e.scheduled_dose_id=d.id AND NOT EXISTS(SELECT 1 FROM public.medication_administration_corrections c WHERE c.administration_event_id=e.id AND c.correction_type='void')
 ORDER BY e.recorded_at DESC,e.id DESC LIMIT 1;
 IF FOUND THEN RAISE EXCEPTION 'dose_already_recorded_use_correction';END IF;
 SELECT e.id INTO replaced_id FROM public.medication_administration_events e
 JOIN public.medication_administration_corrections c ON c.administration_event_id=e.id AND c.correction_type='void'
 WHERE e.scheduled_dose_id=d.id ORDER BY e.recorded_at DESC,e.id DESC LIMIT 1;
 IF p_outcome NOT IN ('given','not_given','refused','held','unknown') OR p_evidence NOT IN ('observed_taken','administered','patient_reported','caregiver_reported','not_observed','unknown') THEN RAISE EXCEPTION 'invalid_status';END IF;
 IF p_outcome='given' AND (p_actual_at IS NULL OR p_actual_dose IS NULL OR p_actual_dose<=0 OR nullif(trim(coalesce(p_actual_unit,'')),'') IS NULL) THEN RAISE EXCEPTION 'missing_actual_dose_or_time'; END IF;
 IF p_outcome='given' AND (p_actual_at>now()+interval '5 minutes' OR p_actual_at<now()-interval '365 days') THEN RAISE EXCEPTION 'actual_time_out_of_range';END IF;
 IF p_outcome<>'given' AND p_evidence IN ('observed_taken','administered') THEN RAISE EXCEPTION 'inconsistent_evidence';END IF;
 IF p_outcome IN ('not_given','refused','held') AND nullif(trim(coalesce(p_reason,'')),'') IS NULL THEN RAISE EXCEPTION 'reason_required';END IF;
 IF p_outcome='given' AND p_evidence IN ('not_observed','unknown') THEN RAISE EXCEPTION 'evidence_required';END IF;
 actual_performer:=CASE WHEN p_evidence='administered' THEN ctx.actor_user_id ELSE p_performed_by END;
 IF p_evidence='administered' AND p_performed_by IS NOT NULL AND p_performed_by<>ctx.actor_user_id THEN RAISE EXCEPTION 'use_caregiver_reported_for_another_performer';END IF;
 INSERT INTO public.medication_administration_events(person_id,scheduled_dose_id,person_medication_id,order_version_id,occurred_at,performed_by,recorded_by,evidence_type,outcome,actual_dose,actual_unit,reason,idempotency_key,source,replaces_event_id)
 VALUES(ctx.target_person_id,d.id,d.person_medication_id,d.order_version_id,p_actual_at,actual_performer,ctx.actor_user_id,p_evidence,p_outcome,
 CASE WHEN p_outcome='given' THEN p_actual_dose ELSE NULL END,CASE WHEN p_outcome='given' THEN p_actual_unit ELSE NULL END,p_reason,p_idempotency_key,'line',replaced_id)
 RETURNING id INTO new_id;
 RETURN jsonb_build_object('ok',true,'duplicate',false,'event_id',new_id,'replaces_event_id',replaced_id);
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_line_register_stock_container(p_line_user_id text, p_pool_id uuid, p_medication_id uuid, p_lot_id uuid, p_bottle_id text, p_manufacturer_expiry date, p_legacy_container_id uuid, p_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE ctx record;p record;old record; new_id uuid;lc record;lot_product uuid;
BEGIN
 SELECT * INTO ctx FROM private.phms_line_crud_context(p_line_user_id,'medication','create');
 IF p_key IS NULL OR length(p_key)<12 OR length(p_key)>200 THEN RAISE EXCEPTION 'invalid_key';END IF;
 SELECT * INTO old FROM public.medication_stock_containers WHERE idempotency_key=p_key;
 IF FOUND THEN
  IF old.pool_id=p_pool_id AND old.medication_id=p_medication_id AND old.bottle_id=p_bottle_id THEN RETURN jsonb_build_object('ok',true,'duplicate',true,'stock_container_id',old.id);END IF;
  RAISE EXCEPTION 'idempotency_conflict';
 END IF;
 SELECT * INTO p FROM public.medication_stock_pools WHERE id=p_pool_id AND family_id=ctx.active_family_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'pool_not_in_family';END IF;
 IF p.pool_type='patient_assigned' AND p.assigned_person_id<>ctx.target_person_id THEN RAISE EXCEPTION 'patient_scope_mismatch';END IF;
 IF p.pool_type<>'patient_assigned' AND NOT EXISTS(
 SELECT 1 FROM public.family_role_assignments r WHERE r.family_id=p.family_id AND r.user_id=ctx.actor_user_id AND r.role IN ('owner','admin') AND r.status='active') THEN
 RAISE EXCEPTION 'shared_pool_requires_family_admin';END IF;
 IF length(btrim(coalesce(p_bottle_id,''))) NOT BETWEEN 3 AND 80 THEN RAISE EXCEPTION 'invalid_bottle_id';END IF;
 IF p_lot_id IS NOT NULL THEN
  SELECT medication_id INTO lot_product FROM public.medication_lots WHERE id=p_lot_id;
  IF lot_product IS DISTINCT FROM p_medication_id THEN RAISE EXCEPTION 'lot_product_mismatch';END IF;
 END IF;
 IF p_legacy_container_id IS NOT NULL THEN
  SELECT c.*,pm.medication_id INTO lc FROM public.medication_containers c
  JOIN public.person_medications pm ON pm.id=c.person_medication_id WHERE c.id=p_legacy_container_id;
  IF NOT FOUND OR lc.person_id<>ctx.target_person_id OR lc.medication_id<>p_medication_id THEN RAISE EXCEPTION 'legacy_container_mismatch';END IF;
 END IF;
 INSERT INTO public.medication_stock_containers(pool_id,medication_id,lot_id,legacy_container_id,bottle_id,manufacturer_expiry_date,idempotency_key)
 VALUES(p_pool_id,p_medication_id,p_lot_id,p_legacy_container_id,p_bottle_id,p_manufacturer_expiry,p_key)
 RETURNING id INTO new_id;
 INSERT INTO public.medication_stock_container_events(stock_container_id,event_type,event_at,recorded_by,reason,idempotency_key)
 VALUES(new_id,'registered',now(),ctx.actor_user_id,'manual bottle registration',p_key||':registered');
 RETURN jsonb_build_object('ok',true,'stock_container_id',new_id,'duplicate',false);
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_line_rounds(p_line_user_id text, p_day date DEFAULT ((now() AT TIME ZONE 'Asia/Bangkok'::text))::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE ctx record; rs jsonb;
BEGIN
 SELECT * INTO ctx FROM private.phms_line_crud_context(p_line_user_id,'medication','view');
 SELECT coalesce(jsonb_agg(jsonb_build_object('round_id',r.id,'slot',r.slot_key,'state',r.state,'date',r.round_date,
  'exceptions',(SELECT count(*) FROM public.medication_round_exceptions e WHERE e.round_id=r.id)
 ) ORDER BY r.slot_key),'[]'::jsonb) INTO rs
 FROM public.medication_round_instances r WHERE r.person_id=ctx.target_person_id AND r.round_date=p_day;
 RETURN jsonb_build_object('ok',true,'person_name',ctx.target_person_name,'date',p_day,'rounds',rs);
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_line_stock_container_event(p_line_user_id text, p_stock_container_id uuid, p_event text, p_event_at timestamp with time zone, p_beyond_use_at timestamp with time zone, p_reason text, p_key text, p_replacement_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE ctx record;c record;pl record; prior record;replacement record; event_id uuid; units_remaining numeric;
BEGIN
 SELECT * INTO ctx FROM private.phms_line_crud_context(p_line_user_id,'medication','update');
 IF p_key IS NULL OR length(p_key)<12 OR length(p_key)>200 THEN RAISE EXCEPTION 'invalid_idempotency_key';END IF;
 SELECT * INTO prior FROM public.medication_stock_container_events WHERE idempotency_key=p_key;
 IF FOUND THEN
  IF prior.stock_container_id=p_stock_container_id AND prior.event_type=p_event THEN RETURN jsonb_build_object('ok',true,'duplicate',true,'event_id',prior.id);END IF;
  RAISE EXCEPTION 'idempotency_conflict';
 END IF;
 SELECT * INTO c FROM public.medication_stock_containers WHERE id=p_stock_container_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'stock_container_not_found';END IF;
 SELECT * INTO pl FROM public.medication_stock_pools WHERE id=c.pool_id AND family_id=ctx.active_family_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'container_out_of_family';END IF;
 IF pl.pool_type='patient_assigned' AND pl.assigned_person_id<>ctx.target_person_id THEN RAISE EXCEPTION 'patient_scope_mismatch';END IF;
 IF pl.pool_type<>'patient_assigned' AND NOT EXISTS(
 SELECT 1 FROM public.family_role_assignments r WHERE r.family_id=pl.family_id AND r.user_id=ctx.actor_user_id AND r.status='active' AND r.role IN('owner','admin')
 ) THEN RAISE EXCEPTION 'shared_container_requires_family_admin';END IF;
 IF p_event NOT IN('opened','checked','emptied','retired','quarantined') THEN RAISE EXCEPTION 'invalid_event';END IF;
 IF p_event_at IS NULL OR p_event_at>now()+interval '5 minutes' THEN RAISE EXCEPTION 'invalid_event_time';END IF;
 IF p_replacement_id IS NOT NULL THEN
  SELECT * INTO replacement FROM public.medication_stock_containers WHERE id=p_replacement_id;
  IF NOT FOUND OR replacement.id=c.id OR replacement.pool_id<>c.pool_id OR replacement.medication_id<>c.medication_id THEN
    RAISE EXCEPTION 'replacement_not_compatible';
  END IF;
 END IF;
 SELECT coalesce(sum(b.quantity),0) INTO units_remaining FROM public.medication_inventory_balances b WHERE b.stock_container_id=c.id;
 IF p_event='opened' THEN
  IF c.lifecycle_status<>'unopened' OR c.opened_at IS NOT NULL THEN RAISE EXCEPTION 'bottle_already_opened';END IF;
  IF p_beyond_use_at IS NOT NULL AND p_beyond_use_at<=p_event_at THEN RAISE EXCEPTION 'invalid_beyond_use_at';END IF;
  IF EXISTS (SELECT 1 FROM public.medication_master mm WHERE mm.id=c.medication_id AND lower(coalesce(mm.dosage_form,'')) LIKE '%eye%')
     AND p_beyond_use_at IS NULL THEN RAISE EXCEPTION 'eye_drops_need_confirmed_beyond_use_date';END IF;
 ELSIF p_event IN('emptied','retired') THEN
  IF c.lifecycle_status IN('empty','retired','expired') THEN RAISE EXCEPTION 'already_retired';END IF;
  IF units_remaining<>0 THEN RAISE EXCEPTION 'stock_still_present_post_disposal_or_dispense_first';END IF;
  IF nullif(btrim(coalesce(p_reason,'')),'') IS NULL THEN RAISE EXCEPTION 'closure_reason_required';END IF;
 ELSIF p_event='quarantined' THEN
  IF c.lifecycle_status IN('empty','retired','expired') THEN RAISE EXCEPTION 'closed_container';END IF;
  IF nullif(btrim(coalesce(p_reason,'')),'') IS NULL THEN RAISE EXCEPTION 'quarantine_reason_required';END IF;
 END IF;
 INSERT INTO public.medication_stock_container_events(stock_container_id,event_type,event_at,recorded_by,reason,replacement_container_id,idempotency_key)
 VALUES(c.id,p_event,p_event_at,ctx.actor_user_id,p_reason,p_replacement_id,p_key) RETURNING id INTO event_id;
 UPDATE public.medication_stock_containers SET
 lifecycle_status=CASE WHEN p_event='opened' THEN 'opened' WHEN p_event IN('emptied','retired','quarantined') THEN CASE WHEN p_event='emptied' THEN 'empty' ELSE p_event END ELSE lifecycle_status END,
 opened_at=CASE WHEN p_event='opened' THEN p_event_at ELSE opened_at END,
 opened_by=CASE WHEN p_event='opened' THEN ctx.actor_user_id ELSE opened_by END,
 beyond_use_at=CASE WHEN p_event='opened' THEN p_beyond_use_at ELSE beyond_use_at END
 WHERE id=c.id;
 RETURN jsonb_build_object('ok',true,'event_id',event_id,'new_status',(SELECT lifecycle_status FROM public.medication_stock_containers WHERE id=c.id));
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_preparation_allocation_exact()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE a record;b record;d record;sc record;lc record;l record;
BEGIN
 IF NEW.state='PACKED' THEN
   IF NEW.allocation_id IS NULL THEN RAISE EXCEPTION 'allocation_required';END IF;
   SELECT * INTO a FROM public.medication_stock_allocations WHERE id=NEW.allocation_id FOR UPDATE;
   SELECT * INTO b FROM public.medication_inventory_balances WHERE id=a.balance_id;
   SELECT * INTO d FROM public.medication_scheduled_doses WHERE id=NEW.scheduled_dose_id;
   IF a.id IS NULL OR a.status<>'reserved' OR a.quantity IS DISTINCT FROM NEW.quantity
     OR a.quantity_unit IS DISTINCT FROM NEW.unit OR b.medication_id IS DISTINCT FROM NEW.medication_id
     OR a.patient_id IS DISTINCT FROM d.person_id
     OR b.lot_id IS DISTINCT FROM NEW.lot_id
     OR b.stock_container_id IS DISTINCT FROM NEW.stock_container_id
     OR b.container_id IS DISTINCT FROM NEW.legacy_container_id
   THEN RAISE EXCEPTION 'packing_requires_exact_matching_allocation_and_provenance';END IF;
   IF b.lot_id IS NULL AND b.stock_container_id IS NULL AND b.container_id IS NULL THEN RAISE EXCEPTION 'physical_stock_traceability_required';END IF;
   IF b.lot_id IS NOT NULL THEN
     SELECT * INTO l FROM public.medication_lots WHERE id=b.lot_id;
     IF l.id IS NULL OR l.medication_id<>NEW.medication_id OR l.deleted_at IS NOT NULL
       OR l.manufacturer_expiry_date IS NULL OR l.manufacturer_expiry_date<d.planned_date
     THEN RAISE EXCEPTION 'lot_missing_expiry_or_expired';END IF;
   END IF;
   IF b.stock_container_id IS NOT NULL THEN
     SELECT * INTO sc FROM public.medication_stock_containers WHERE id=b.stock_container_id;
     IF sc.id IS NULL OR sc.medication_id<>NEW.medication_id OR sc.lifecycle_status NOT IN ('unopened','opened')
       OR (sc.manufacturer_expiry_date IS NULL AND sc.beyond_use_at IS NULL AND b.lot_id IS NULL)
       OR (sc.manufacturer_expiry_date IS NOT NULL AND sc.manufacturer_expiry_date<d.planned_date)
       OR (sc.opened_at IS NOT NULL AND sc.beyond_use_at IS NULL)
       OR (sc.beyond_use_at IS NOT NULL AND d.scheduled_at>sc.beyond_use_at)
     THEN RAISE EXCEPTION 'stock_container_not_usable_on_dose_date';END IF;
   END IF;
   IF b.container_id IS NOT NULL THEN
     SELECT * INTO lc FROM public.medication_containers WHERE id=b.container_id;
     IF lc.id IS NULL OR lc.deleted_at IS NOT NULL OR lc.lifecycle_status NOT IN ('unopened','opened')
       OR (lc.manufacturer_expiry_date IS NULL AND lc.beyond_use_at IS NULL AND b.lot_id IS NULL)
       OR (lc.manufacturer_expiry_date IS NOT NULL AND lc.manufacturer_expiry_date<d.planned_date)
       OR (lc.opened_at IS NOT NULL AND lc.beyond_use_at IS NULL)
       OR (lc.beyond_use_at IS NOT NULL AND d.scheduled_at>lc.beyond_use_at)
     THEN RAISE EXCEPTION 'legacy_container_not_usable_on_dose_date';END IF;
   END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_preparation_impact_update_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'preparation_impact_cannot_be_deleted';END IF;
 IF OLD.session_id IS DISTINCT FROM NEW.session_id OR OLD.item_id IS DISTINCT FROM NEW.item_id
 OR OLD.changed_order_version_id IS DISTINCT FROM NEW.changed_order_version_id
 OR OLD.reason IS DISTINCT FROM NEW.reason OR OLD.detected_at IS DISTINCT FROM NEW.detected_at
 THEN RAISE EXCEPTION 'preparation_impact_identity_is_immutable';END IF;
 IF OLD.status='RESOLVED' AND NEW.status<>'RESOLVED' THEN RAISE EXCEPTION 'resolved_impact_cannot_reopen';END IF;
 IF NEW.status='RESOLVED' AND (NEW.resolved_by IS NULL OR NEW.resolved_at IS NULL OR nullif(btrim(NEW.resolution_notes),'') IS NULL)
 THEN RAISE EXCEPTION 'resolution_audit_required';END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_preparation_inventory_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE a record;b record;s record;source record;
BEGIN
 IF NEW.state='PACKED' OR NEW.packaging_verified THEN
  SELECT * INTO s FROM public.medication_preparation_sessions WHERE id=NEW.session_id;
  IF s.status NOT IN ('DRAFT','REVIEWED','PREPARING') THEN RAISE EXCEPTION 'session_not_packable';END IF;
  IF NEW.allocation_id IS NULL THEN RAISE EXCEPTION 'allocation_required';END IF;
  SELECT * INTO a FROM public.medication_stock_allocations WHERE id=NEW.allocation_id FOR UPDATE;
  SELECT * INTO b FROM public.medication_inventory_balances WHERE id=a.balance_id;
  IF a.id IS NULL OR a.status<>'reserved' OR a.patient_id<>s.person_id OR a.quantity<NEW.quantity
   OR a.quantity_unit<>NEW.unit OR b.medication_id<>NEW.medication_id OR
   (NEW.lot_id IS NOT NULL AND b.lot_id IS DISTINCT FROM NEW.lot_id) OR
   (NEW.stock_container_id IS NOT NULL AND b.stock_container_id IS DISTINCT FROM NEW.stock_container_id)
   THEN RAISE EXCEPTION 'allocation_mismatch_or_not_reserved';END IF;
  IF NEW.packaging_source_id IS NULL THEN RAISE EXCEPTION 'verified_packaging_source_required';END IF;
  SELECT * INTO source FROM public.medication_instruction_sources WHERE id=NEW.packaging_source_id;
  IF source.id IS NULL OR source.person_medication_id<>NEW.person_medication_id OR source.verification_status<>'verified'
  OR source.source_kind NOT IN ('pharmacist','document','label')
  THEN RAISE EXCEPTION 'packaging_source_not_clinically_verified';END IF;
  IF NOT NEW.packaging_verified OR NEW.packaging_verified_by IS NULL OR NEW.packaging_verified_at IS NULL OR nullif(btrim(NEW.packaging_evidence),'') IS NULL THEN
    RAISE EXCEPTION 'packaging_evidence_missing';
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_preparation_item_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE s record;d record;v record;lots record;
BEGIN
 SELECT * INTO s FROM public.medication_preparation_sessions WHERE id=NEW.session_id;
 SELECT * INTO d FROM public.medication_scheduled_doses WHERE id=NEW.scheduled_dose_id;
 SELECT * INTO v FROM public.medication_order_versions WHERE id=NEW.order_version_id;
 IF s.id IS NULL OR s.status NOT IN ('DRAFT','REVIEWED','PREPARING') THEN RAISE EXCEPTION 'preparation_session_locked';END IF;
 IF d.id IS NULL OR d.person_id<>s.person_id OR d.person_medication_id<>NEW.person_medication_id OR d.order_version_id<>NEW.order_version_id OR d.planned_date<s.start_date OR d.planned_date>s.end_date OR d.state<>'planned'
 OR v.status<>'verified' OR v.verified_at IS NULL THEN RAISE EXCEPTION 'invalid_or_unverified_preparation_dose';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.person_medications pm WHERE pm.id=NEW.person_medication_id AND pm.medication_id=NEW.medication_id) THEN RAISE EXCEPTION 'product_mismatch';END IF;
 IF NEW.quantity<>d.planned_dose OR NEW.unit IS DISTINCT FROM d.planned_unit THEN RAISE EXCEPTION 'preparation_quantity_mismatch';END IF;
 IF NEW.lot_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.medication_lots l WHERE l.id=NEW.lot_id AND l.medication_id=NEW.medication_id AND l.deleted_at IS NULL AND (l.manufacturer_expiry_date IS NULL OR l.manufacturer_expiry_date>=d.planned_date)) THEN RAISE EXCEPTION 'lot_invalid_or_expired';END IF;
 IF NEW.stock_container_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.medication_stock_containers sc WHERE sc.id=NEW.stock_container_id AND sc.medication_id=NEW.medication_id AND (sc.manufacturer_expiry_date IS NULL OR sc.manufacturer_expiry_date>=d.planned_date) AND (sc.beyond_use_at IS NULL OR sc.beyond_use_at >= coalesce(d.scheduled_at, d.planned_date::timestamptz)) AND sc.lifecycle_status NOT IN ('discarded','retired','empty')) THEN RAISE EXCEPTION 'container_invalid_expired_or_retired';END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_preparation_release_inventory()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE item record;result jsonb;actor uuid;
BEGIN
 IF NEW.status='RELEASED' AND OLD.status IS DISTINCT FROM NEW.status THEN
  actor:=coalesce(NEW.reviewed_by,NEW.prepared_by);
  IF actor IS NULL THEN RAISE EXCEPTION 'release_actor_required';END IF;
  FOR item IN
   SELECT i.id,i.allocation_id,i.quantity,a.quantity AS allocated_quantity,a.status AS allocation_status
   FROM public.medication_preparation_items i
   LEFT JOIN public.medication_stock_allocations a ON a.id=i.allocation_id
   WHERE i.session_id=NEW.id AND i.state='PACKED'
   ORDER BY i.id
  LOOP
   IF item.allocation_id IS NULL OR item.allocation_status<>'reserved' OR item.quantity IS DISTINCT FROM item.allocated_quantity
   THEN RAISE EXCEPTION 'preparation_release_requires_exact_reserved_allocation';END IF;
   result:=public.phms_med_v23_inventory_fulfill(item.allocation_id,actor,
     'prep_release:'||NEW.id::text||':'||item.allocation_id::text,
     'Medication preparation released - physical dispense, not administration');
   IF coalesce((result->>'ok')::boolean,false) IS NOT TRUE THEN RAISE EXCEPTION 'inventory_fulfillment_failed';END IF;
  END LOOP;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_preparation_session_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE n integer; problems integer; expected_count integer; covered_count integer; review_count integer;
BEGIN
 IF TG_OP='UPDATE' THEN
 IF NEW.person_id<>OLD.person_id OR NEW.start_date<>OLD.start_date OR NEW.end_date<>OLD.end_date THEN RAISE EXCEPTION 'preparation_window_immutable';END IF;
 IF NEW.status<>OLD.status THEN
  IF NOT ((OLD.status='DRAFT' AND NEW.status IN ('REVIEWED','BLOCKED','CANCELLED'))
   OR (OLD.status='REVIEWED' AND NEW.status IN ('PREPARING','BLOCKED','CANCELLED'))
   OR (OLD.status='PREPARING' AND NEW.status IN ('PREPARED','BLOCKED','REWORK_REQUIRED','CANCELLED'))
   OR (OLD.status='PREPARED' AND NEW.status IN ('RELEASED','BLOCKED','REWORK_REQUIRED','CANCELLED'))
   OR (OLD.status='RELEASED' AND NEW.status='BLOCKED')
   OR (OLD.status='BLOCKED' AND NEW.status IN ('REWORK_REQUIRED','CANCELLED'))
   OR (OLD.status='REWORK_REQUIRED' AND NEW.status IN ('DRAFT','CANCELLED'))) THEN RAISE EXCEPTION 'invalid_preparation_transition';END IF;
 END IF;

IF NEW.status='REVIEWED' AND OLD.status IS DISTINCT FROM NEW.status THEN
 SELECT count(*) INTO expected_count FROM public.medication_scheduled_doses d
 JOIN public.medication_order_versions v ON v.id=d.order_version_id
 WHERE d.person_id=NEW.person_id AND d.planned_date BETWEEN NEW.start_date AND NEW.end_date AND d.state='planned' AND v.status='verified' AND v.verified_at IS NOT NULL;
 SELECT count(*) INTO covered_count FROM public.medication_preparation_items i
 WHERE i.session_id=NEW.id AND i.state IN ('PLANNED','PACKED');
 IF expected_count=0 OR covered_count<>expected_count
 OR EXISTS(SELECT 1 FROM public.medication_preparation_items i
  JOIN public.medication_scheduled_doses d ON d.id=i.scheduled_dose_id
  JOIN public.medication_order_versions v ON v.id=i.order_version_id
  WHERE i.session_id=NEW.id AND (d.state<>'planned' OR v.status<>'verified'
  OR i.quantity<>d.planned_dose OR i.unit IS DISTINCT FROM d.planned_unit))
 THEN RAISE EXCEPTION 'cannot_review_incomplete_or_outdated_preparation';END IF;
END IF;
IF NEW.status='PREPARING' AND OLD.status IS DISTINCT FROM NEW.status
 AND (NEW.reviewed_by IS NULL OR NEW.reviewed_at IS NULL) THEN
 RAISE EXCEPTION 'reviewer_required_before_preparing';
END IF;
IF NEW.status IN ('PREPARED','RELEASED') AND OLD.status IS DISTINCT FROM NEW.status THEN
  SELECT count(*) INTO n FROM public.medication_preparation_items WHERE session_id=NEW.id AND state='PACKED';
  SELECT count(*) INTO problems FROM public.medication_preparation_items i
    JOIN public.medication_scheduled_doses d ON d.id=i.scheduled_dose_id
    JOIN public.medication_order_versions v ON v.id=i.order_version_id
    WHERE i.session_id=NEW.id AND (i.state<>'PACKED' OR i.packaging_verified=false OR v.status<>'verified' OR d.state<>'planned'
       OR i.quantity<>d.planned_dose OR i.unit IS DISTINCT FROM d.planned_unit
       OR i.allocation_id IS NULL);
  SELECT count(*) INTO expected_count FROM public.medication_scheduled_doses d
   WHERE d.person_id=NEW.person_id AND d.planned_date BETWEEN NEW.start_date AND NEW.end_date
   AND d.state='planned' AND EXISTS(SELECT 1 FROM public.medication_order_versions v WHERE v.id=d.order_version_id AND v.status='verified');
  SELECT count(*) INTO covered_count FROM public.medication_preparation_items i
   WHERE i.session_id=NEW.id AND i.state='PACKED';
  IF n=0 OR problems>0 OR expected_count<>covered_count
   OR EXISTS(SELECT 1 FROM public.medication_preparation_impacts WHERE session_id=NEW.id AND status='PENDING_REVIEW')
  THEN RAISE EXCEPTION 'preparation_not_releasable';END IF;
  SELECT count(DISTINCT check_type) INTO review_count FROM (
    SELECT DISTINCT ON(check_type) check_type,passed FROM public.medication_preparation_checks
    WHERE session_id=NEW.id AND revision=NEW.revision ORDER BY check_type,checked_at DESC,id DESC
  ) c WHERE passed=true;
  IF review_count<>6 THEN RAISE EXCEPTION 'preparation_checks_incomplete';END IF;
 END IF;
 IF NEW.status='RELEASED' AND NEW.released_at IS NULL THEN NEW.released_at:=now();END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_protect_verified_rules()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE status_at_change text; version_id uuid;
BEGIN
 version_id:=CASE WHEN TG_OP='DELETE' THEN OLD.order_version_id ELSE NEW.order_version_id END;
 SELECT status INTO status_at_change FROM public.medication_order_versions WHERE id=version_id;
 IF status_at_change IN ('verified','superseded') THEN
  RAISE EXCEPTION 'Cannot change dose rules for a verified or superseded order; make a new order version';
 END IF;
 IF TG_OP='UPDATE' AND OLD.order_version_id<>NEW.order_version_id THEN
  RAISE EXCEPTION 'Dose rule cannot be transferred between order versions';
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_refill_create(p_line_user_id text, p_key text, p_at timestamp with time zone, p_hospital text, p_location text, p_items jsonb, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE ctx record; ap record; item jsonb; pm record; med uuid; cnt integer:=0; exp numeric; exunit text; v_uuid uuid;
BEGIN
 SELECT * INTO ctx FROM private.phms_line_crud_context(p_line_user_id,'appointment','create');
 IF ctx.actor_user_id IS NULL OR ctx.target_person_id IS NULL OR ctx.active_family_id IS NULL THEN RAISE EXCEPTION 'invalid_refill_context'; END IF;
 IF length(coalesce(p_key,'')) NOT BETWEEN 12 AND 120 OR p_at IS NULL OR
 length(btrim(coalesce(p_hospital,''))) NOT BETWEEN 2 AND 180 OR jsonb_typeof(p_items) IS DISTINCT FROM 'array'
 OR jsonb_array_length(p_items) NOT BETWEEN 1 AND 40 THEN RAISE EXCEPTION 'invalid_refill_input'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('refill:'||ctx.active_family_id::text||':'||p_key,0));
 SELECT * INTO ap FROM public.appointments WHERE family_id=ctx.active_family_id AND
 external_reference='phms-refill:'||p_key AND deleted_at IS NULL FOR UPDATE;
 IF FOUND THEN
   IF ap.appointment_type<>'medication_refill' OR ap.person_id<>ctx.target_person_id OR ap.appointment_at IS DISTINCT FROM p_at
   OR ap.hospital_name IS DISTINCT FROM btrim(p_hospital) THEN RAISE EXCEPTION 'idempotency_conflict'; END IF;
   RETURN jsonb_build_object('ok',true,'duplicate',true,'appointment_id',ap.id);
 END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_items) LOOP
   IF jsonb_typeof(item)<>'object' OR (item->>'person_medication_id') IS NULL THEN RAISE EXCEPTION 'person_medication_required'; END IF;
   BEGIN v_uuid:=(item->>'person_medication_id')::uuid;
   EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'invalid_person_medication'; END;
   SELECT pm0.id,pm0.medication_id INTO pm FROM public.person_medications pm0
   WHERE pm0.id=v_uuid AND pm0.person_id=ctx.target_person_id AND pm0.deleted_at IS NULL;
   IF NOT FOUND THEN RAISE EXCEPTION 'person_medication_not_found'; END IF;
   IF (item ? 'expected_quantity') AND nullif(item->>'expected_quantity','') IS NOT NULL THEN
    BEGIN exp:=(item->>'expected_quantity')::numeric; EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'invalid_expected_quantity'; END;
    IF exp<=0 OR exp>1000000 THEN RAISE EXCEPTION 'invalid_expected_quantity'; END IF;
    exunit:=nullif(btrim(item->>'expected_unit'),'');
    IF exunit IS NULL OR length(exunit)>35 THEN RAISE EXCEPTION 'expected_unit_required'; END IF;
   ELSE exp:=NULL;exunit:=NULL;END IF;
   cnt:=cnt+1;
 END LOOP;
 INSERT INTO public.appointments(family_id,person_id,family_person_id,appointment_type,title,hospital_name,
 location_detail,appointment_at,status,created_by,external_reference,preparation_notes)
 VALUES(ctx.active_family_id,ctx.target_person_id,ctx.active_family_person_id,'medication_refill',
 'นัดรับยาเดิม',btrim(p_hospital),nullif(btrim(p_location),''),p_at,'planned',ctx.actor_user_id,
 'phms-refill:'||p_key,nullif(btrim(p_notes),'')) RETURNING * INTO ap;
 FOR item IN SELECT value FROM jsonb_array_elements(p_items) LOOP
  v_uuid:=(item->>'person_medication_id')::uuid;
  IF nullif(item->>'expected_quantity','') IS NULL THEN exp:=NULL;exunit:=NULL;
  ELSE exp:=(item->>'expected_quantity')::numeric;exunit:=btrim(item->>'expected_unit');END IF;
  INSERT INTO public.medication_refill_items(appointment_id,person_medication_id,expected_quantity,expected_unit,notes)
  VALUES(ap.id,v_uuid,exp,exunit,nullif(item->>'notes',''));
 END LOOP;
 RETURN jsonb_build_object('ok',true,'duplicate',false,'appointment_id',ap.id,'item_count',cnt);
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_stock_container_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE x record;
BEGIN
 IF NEW.stock_container_id IS NULL THEN RETURN NEW;END IF;
 SELECT * INTO x FROM public.medication_stock_containers WHERE id=NEW.stock_container_id;
 IF NOT FOUND OR x.pool_id<>NEW.pool_id OR x.medication_id<>NEW.medication_id
 OR x.lot_id IS DISTINCT FROM NEW.lot_id THEN RAISE EXCEPTION 'physical container product/lot/pool mismatch';END IF;
 IF TG_TABLE_NAME='medication_inventory_transactions' THEN
   IF NEW.transaction_type IN('dispense','consume')
   AND (x.lifecycle_status IN('expired','retired','quarantined','empty')
   OR (x.beyond_use_at IS NOT NULL AND x.beyond_use_at<now())
   OR (x.manufacturer_expiry_date IS NOT NULL AND x.manufacturer_expiry_date<(now() AT TIME ZONE 'Asia/Bangkok')::date))
   THEN RAISE EXCEPTION 'physical container is not usable';END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.phms_med_v23_validate_links()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE actual_person uuid; actual_med uuid; actual_regimen uuid; actual_order_med uuid;
BEGIN
 SELECT person_id INTO actual_person FROM public.person_medications WHERE id=NEW.person_medication_id;
 IF actual_person IS DISTINCT FROM NEW.person_id THEN RAISE EXCEPTION 'Medication/person mismatch'; END IF;
 IF TG_TABLE_NAME='medication_scheduled_doses' THEN
   SELECT person_medication_id INTO actual_med FROM public.medication_regimens WHERE id=NEW.regimen_id;
   SELECT person_medication_id,regimen_id INTO actual_order_med,actual_regimen FROM public.medication_order_versions WHERE id=NEW.order_version_id;
   IF actual_med IS DISTINCT FROM NEW.person_medication_id OR actual_order_med IS DISTINCT FROM NEW.person_medication_id OR actual_regimen IS DISTINCT FROM NEW.regimen_id THEN RAISE EXCEPTION 'Regimen/order mismatch';END IF;
   IF NEW.round_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.medication_round_instances WHERE id=NEW.round_id AND person_id=NEW.person_id) THEN RAISE EXCEPTION 'Round/person mismatch';END IF;
 ELSE
   IF NEW.scheduled_dose_id IS NOT NULL AND NOT EXISTS
      (SELECT 1 FROM public.medication_scheduled_doses d WHERE d.id=NEW.scheduled_dose_id AND d.person_id=NEW.person_id AND d.person_medication_id=NEW.person_medication_id AND d.order_version_id=NEW.order_version_id)
      THEN RAISE EXCEPTION 'Administration/schedule mismatch'; END IF;
   IF NEW.order_version_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.medication_order_versions v WHERE v.id=NEW.order_version_id AND v.person_medication_id=NEW.person_medication_id)
      THEN RAISE EXCEPTION 'Administration/order mismatch';END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.phms_name_line_intake_source(p_line_user_id text, p_source_id uuid, p_display_name text, p_document_type text DEFAULT NULL::text, p_appointment_file_role text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_source public.data_intake_sources%rowtype;
  v_asset uuid;
  v_name text:=nullif(btrim(coalesce(p_display_name,'')),'');
  v_doc text:=nullif(btrim(coalesce(p_document_type,'')),'');
  v_role text:=nullif(btrim(coalesce(p_appointment_file_role,'')),'');
begin
  if v_name is null then raise exception 'display_name_required'; end if;
  if v_role is not null and v_role not in ('appointment_slip','appointment_attachment') then raise exception 'invalid_appointment_file_role'; end if;

  select * into v_line from private.resolve_line_user_for_service(p_line_user_id);

  select s.* into v_source
  from public.data_intake_sources s
  join public.data_intake_sessions ds on ds.id=s.session_id
  where s.id=p_source_id and ds.submitted_by=v_line.user_id
  limit 1;
  if not found then raise exception 'intake_source_not_accessible'; end if;

  update public.data_intake_sources
  set document_type=coalesce(v_doc,document_type),
      source_metadata=coalesce(source_metadata,'{}'::jsonb)
        ||jsonb_build_object('display_title',v_name,'named_by',v_line.user_id,'named_at',now())
        ||case when v_role is null then '{}'::jsonb else jsonb_build_object('appointment_file_role',v_role) end
  where id=p_source_id
  returning storage_asset_id into v_asset;

  if v_asset is not null then
    update public.phms_storage_assets
    set metadata=coalesce(metadata,'{}'::jsonb)
      ||jsonb_build_object('display_title',v_name,'named_by',v_line.user_id,'named_at',now())
      ||case when v_role is null then '{}'::jsonb else jsonb_build_object('appointment_file_role',v_role) end,
      permission_resource=case when v_role is not null then 'appointments' else permission_resource end,
      updated_at=now()
    where id=v_asset;
  end if;

  return jsonb_build_object(
    'ok',true,'source_id',p_source_id,'display_title',v_name,
    'document_type',v_doc,'appointment_file_role',v_role,'storage_asset_id',v_asset
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_notification_tick(p_now timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_sync jsonb;
  v_appt integer:=0;
  v_group integer:=0;
  v_med integer:=0;
  v_recovered integer:=0;
begin
  update public.notifications
  set status=case when attempt_count>=max_attempts then 'failed' else 'pending' end,
      next_attempt_at=case when attempt_count>=max_attempts then null else p_now end,
      locked_at=null,lock_token=null,
      last_error=coalesce(last_error,'stale_dispatch_lock_recovered'),
      updated_at=now()
  where status='sending'
    and locked_at<p_now-interval '15 minutes';
  get diagnostics v_recovered=row_count;

  v_sync:=private.phms_sync_auto_appointment_reminders(p_now);
  v_appt:=private.phms_generate_appointment_notifications(p_now);
  v_group:=private.phms_generate_appointment_group_notifications(p_now);
  v_med:=private.phms_generate_medication_notifications(p_now);

  return jsonb_build_object(
    'ok',true,
    'appointment_reminders',v_sync,
    'appointment_notifications_created',v_appt,
    'appointment_group_notifications_created',v_group,
    'medication_notifications_created',v_med,
    'stale_locks_recovered',v_recovered
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_prepare_line_family_management(p_line_user_id text)
 RETURNS TABLE(flow_state text, auto_selected boolean, family_id uuid, family_name text, is_owner boolean, can_manage_permissions boolean, member_count integer, person_count integer, pending_access_request_count integer, selection_options jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_main record; v_line record; v_owner boolean:=false; v_manage boolean:=false;
 v_members integer:=0; v_people integer:=0; v_pending integer:=0;
begin
 select * into v_main from public.phms_prepare_line_main_command(p_line_user_id,'family');
 if v_main.flow_state<>'ready' then
   return query select v_main.flow_state,v_main.auto_selected,v_main.active_family_id,v_main.family_name,
     false,false,0,0,0,coalesce(v_main.selection_options,'[]'::jsonb);
   return;
 end if;

 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
 v_owner:=private.is_family_owner(v_main.active_family_id);
 v_manage:=private.can_manage_permissions(v_main.active_family_id);

 select count(*)::int into v_members
 from public.family_memberships fm
 where fm.family_id=v_main.active_family_id and fm.status='active';

 select count(*)::int into v_people
 from public.family_persons fp join public.persons p on p.id=fp.person_id
 where fp.family_id=v_main.active_family_id
   and coalesce(fp.status,'active')='active' and coalesce(p.status,'active')='active'
   and private.family_person_is_visible_to_user(v_line.user_id,fp.id);

 select count(*)::int into v_pending
 from public.permission_requests pr
 where pr.family_id=v_main.active_family_id and pr.status='pending'
   and (
    (pr.request_type='role' and private.can_grant_role(pr.family_id,pr.requested_role))
    or (pr.request_type='person_bundle'
        and private.user_has_family_role(v_line.user_id,pr.family_id,array['owner','admin']))
    or (pr.request_type='permission' and pr.requested_action='manage_permissions'
        and private.user_has_family_role(v_line.user_id,pr.family_id,array['owner','admin']))
    or (pr.request_type='permission' and pr.requested_action<>'manage_permissions'
        and private.can_grant_permission(pr.family_id,pr.family_person_id,pr.resource,pr.requested_action))
   );

 return query select 'ready'::text,v_main.auto_selected,v_main.active_family_id,v_main.family_name,
   v_owner,v_manage,v_members,v_people,v_pending,'[]'::jsonb;
end
$function$

CREATE OR REPLACE FUNCTION public.phms_prepare_line_main_command(p_line_user_id text, p_command_key text)
 RETURNS TABLE(command_key text, flow_state text, auto_selected boolean, active_scope text, active_family_id uuid, active_family_person_id uuid, family_name text, target_person_name text, permission_granted boolean, resolution_code text, selection_options jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  r record;
  a record;
  v_opts jsonb := '[]'::jsonb;
  v_auto boolean := false;
  v_key text := lower(coalesce(nullif(btrim(p_command_key),''),''));
  v_person_required boolean := false;
begin
  select * into r
  from public.phms_resolve_line_main_command(p_line_user_id, v_key);

  v_person_required := coalesce(r.require_person,false);

  if r.resolution_code='ok' and coalesce(r.context_ready,false) and coalesce(r.permission_granted,false) then
    return query select v_key,'ready'::text,false,r.active_scope,r.active_family_id,r.active_family_person_id,r.family_name,r.target_person_name,true,'ok'::text,'[]'::jsonb;
    return;
  end if;

  if r.resolution_code='permission_denied' then
    return query select v_key,'permission_denied'::text,false,r.active_scope,r.active_family_id,r.active_family_person_id,r.family_name,r.target_person_name,false,r.resolution_code,'[]'::jsonb;
    return;
  end if;

  if r.resolution_code in ('family_scope_required','personal_person_required','personal_person_missing') then
    select * into a from public.phms_auto_progress_line_context(p_line_user_id);

    if a.action='family_and_person_auto_selected' then
      v_auto := true;
      select * into r from public.phms_resolve_line_main_command(p_line_user_id,v_key);
      if r.resolution_code='ok' and coalesce(r.context_ready,false) and coalesce(r.permission_granted,false) then
        return query select v_key,'ready'::text,true,r.active_scope,r.active_family_id,r.active_family_person_id,r.family_name,r.target_person_name,true,'ok'::text,'[]'::jsonb;
        return;
      elsif r.resolution_code='permission_denied' then
        return query select v_key,'permission_denied'::text,true,r.active_scope,r.active_family_id,r.active_family_person_id,r.family_name,r.target_person_name,false,r.resolution_code,'[]'::jsonb;
        return;
      end if;
    elsif a.action='family_auto_selected' then
      v_auto := true;
      if not v_person_required then
        select * into r from public.phms_resolve_line_main_command(p_line_user_id,v_key);
        if r.resolution_code='ok' and coalesce(r.context_ready,false) and coalesce(r.permission_granted,false) then
          return query select v_key,'ready'::text,true,r.active_scope,r.active_family_id,r.active_family_person_id,r.family_name,r.target_person_name,true,'ok'::text,'[]'::jsonb;
          return;
        elsif r.resolution_code='permission_denied' then
          return query select v_key,'permission_denied'::text,true,r.active_scope,r.active_family_id,r.active_family_person_id,r.family_name,r.target_person_name,false,r.resolution_code,'[]'::jsonb;
          return;
        end if;
      end if;
      select coalesce(jsonb_agg(jsonb_build_object(
        'selection_code',x.selection_code,
        'family_person_id',x.family_person_id,
        'display_name',x.display_name,
        'relationship_label',x.relationship_label,
        'is_active_context',x.is_active_context
      ) order by x.display_name,x.family_person_id),'[]'::jsonb)
      into v_opts
      from public.phms_list_line_context_persons(p_line_user_id) x;
      return query select v_key,'choose_person'::text,true,'family'::text,a.active_family_id,null::uuid,a.family_name,null::text,false,'family_person_required'::text,v_opts;
      return;
    elsif a.action='family_selection_required' then
      select coalesce(jsonb_agg(jsonb_build_object(
        'selection_code',x.selection_code,
        'family_id',x.family_id,
        'family_name',x.family_name,
        'family_code',x.family_code,
        'family_person_count',x.family_person_count,
        'is_active_context',x.is_active_context
      ) order by x.family_name,x.family_id),'[]'::jsonb)
      into v_opts
      from public.phms_list_line_context_families(p_line_user_id) x;
      return query select v_key,'choose_family'::text,false,r.active_scope,r.active_family_id,r.active_family_person_id,r.family_name,r.target_person_name,false,r.resolution_code,v_opts;
      return;
    elsif a.action='no_family' then
      return query select v_key,
        case when r.resolution_code='family_scope_required' then 'no_family' else 'no_target' end::text,
        false,r.active_scope,r.active_family_id,r.active_family_person_id,r.family_name,r.target_person_name,false,r.resolution_code,'[]'::jsonb;
      return;
    elsif a.action='no_person' then
      return query select v_key,'no_person'::text,true,'family'::text,a.active_family_id,null::uuid,a.family_name,null::text,false,'family_person_required'::text,'[]'::jsonb;
      return;
    end if;
  end if;

  if r.resolution_code='family_person_required' then
    select * into a from public.phms_auto_progress_line_person_context(p_line_user_id);
    if a.action='person_auto_selected' then
      select * into r from public.phms_resolve_line_main_command(p_line_user_id,v_key);
      if r.resolution_code='ok' and coalesce(r.context_ready,false) and coalesce(r.permission_granted,false) then
        return query select v_key,'ready'::text,true,r.active_scope,r.active_family_id,r.active_family_person_id,r.family_name,r.target_person_name,true,'ok'::text,'[]'::jsonb;
        return;
      elsif r.resolution_code='permission_denied' then
        return query select v_key,'permission_denied'::text,true,r.active_scope,r.active_family_id,r.active_family_person_id,r.family_name,r.target_person_name,false,r.resolution_code,'[]'::jsonb;
        return;
      end if;
    elsif a.action='person_selection_required' then
      select coalesce(jsonb_agg(jsonb_build_object(
        'selection_code',x.selection_code,
        'family_person_id',x.family_person_id,
        'display_name',x.display_name,
        'relationship_label',x.relationship_label,
        'is_active_context',x.is_active_context
      ) order by x.display_name,x.family_person_id),'[]'::jsonb)
      into v_opts
      from public.phms_list_line_context_persons(p_line_user_id) x;
      return query select v_key,'choose_person'::text,false,r.active_scope,r.active_family_id,r.active_family_person_id,r.family_name,r.target_person_name,false,r.resolution_code,v_opts;
      return;
    elsif a.action='no_person' then
      return query select v_key,'no_person'::text,false,r.active_scope,r.active_family_id,r.active_family_person_id,r.family_name,r.target_person_name,false,r.resolution_code,'[]'::jsonb;
      return;
    end if;
  end if;

  return query select v_key,'invalid_context'::text,v_auto,r.active_scope,r.active_family_id,r.active_family_person_id,r.family_name,r.target_person_name,coalesce(r.permission_granted,false),r.resolution_code,'[]'::jsonb;
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_prepare_line_manual_fallback(p_line_user_id text, p_source_code text, p_reason text DEFAULT 'ocr_unavailable'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
declare
  v_line public.line_identities%rowtype;
  v_source public.data_intake_sources%rowtype;
  v_session public.data_intake_sessions%rowtype;
  v_code text := lower(btrim(coalesce(p_source_code,'')));
  v_match_count integer;
begin
  if length(v_code)<8 then raise exception 'source_code_too_short'; end if;

  select * into v_line
  from public.line_identities
  where line_user_id=p_line_user_id and coalesce(is_active,false)=true
  limit 1;
  if not found or v_line.user_id is null then raise exception 'line_identity_not_linked'; end if;

  select count(*) into v_match_count
  from public.data_intake_sources s
  where s.submitted_by=v_line.user_id
    and lower(s.id::text) like v_code||'%';
  if v_match_count=0 then raise exception 'intake_source_not_found'; end if;
  if v_match_count>1 then raise exception 'intake_source_code_ambiguous'; end if;

  select * into v_source
  from public.data_intake_sources s
  where s.submitted_by=v_line.user_id
    and lower(s.id::text) like v_code||'%'
  limit 1;

  select * into v_session
  from public.data_intake_sessions
  where id=v_source.session_id
  for update;

  if v_session.status in ('confirmed','committed','cancelled','rejected') then
    raise exception 'intake_session_already_final';
  end if;

  update public.data_intake_sources
  set source_metadata=
    coalesce(source_metadata,'{}'::jsonb)
    || jsonb_build_object(
         'extraction_status','manual_pending',
         'manual_fallback',true,
         'manual_fallback_reason',left(coalesce(p_reason,'ocr_unavailable'),120),
         'auto_commit',false,
         'canonical_commit',false,
         'updated_at',now()
       )
  where id=v_source.id;

  update public.data_intake_sessions
  set status='collecting',updated_at=now()
  where id=v_session.id;

  insert into public.data_intake_actions(
    session_id,actor_user_id,action,after_data,reason
  )
  values(
    v_session.id,v_line.user_id,'fail',
    jsonb_build_object(
      'source_id',v_source.id,
      'stage','ocr',
      'fallback','human_manual',
      'canonical_commit',false
    ),
    left(coalesce(p_reason,'ocr_unavailable'),200)
  );

  return jsonb_build_object(
    'ok',true,
    'source_id',v_source.id,
    'source_code',substr(v_source.id::text,1,12),
    'session_id',v_session.id,
    'session_status','collecting',
    'manual_fallback',true,
    'canonical_commit',false
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_publish_line_family_person(p_line_user_id text, p_person_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_p public.persons%rowtype;
begin
  select * into v_ref
  from private.resolve_line_family_person_code(p_line_user_id,p_person_code)
  limit 1;

  if not private.can_manage_family_person_setup(v_ref.actor_user_id,v_ref.family_person_id) then
    raise exception 'draft_setup_denied';
  end if;

  select p.* into v_p
  from public.family_persons fp
  join public.persons p on p.id=fp.person_id
  where fp.id=v_ref.family_person_id
  for update;

  if nullif(btrim(v_p.nickname),'') is null then
    raise exception 'shared_nickname_required_before_publish';
  end if;

  update public.family_persons
  set setup_status='ready',
      setup_completed_at=now(),
      updated_at=now()
  where id=v_ref.family_person_id
    and setup_status='draft';

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,new_data,description,created_at
  )
  values(
    v_ref.family_id,v_ref.actor_user_id,v_ref.family_person_id,
    'family_person_setup_published','persons',v_p.id,
    jsonb_build_object('setup_status','ready','shared_nickname',v_p.nickname,'source','line'),
    'Published family person after setup review',now()
  );

  return jsonb_build_object(
    'status','ok',
    'person_code',lower(btrim(p_person_code)),
    'family_person_id',v_ref.family_person_id,
    'display_name',private.family_person_label_for_viewer(v_ref.actor_user_id,v_ref.family_person_id),
    'shared_nickname',v_p.nickname,
    'setup_status','ready'
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_rate_limit_check(p_scope text, p_subject text, p_limit integer, p_window_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'private', 'public', 'extensions'
AS $function$
declare
  v_scope text:=lower(btrim(coalesce(p_scope,'')));
  v_subject text:=coalesce(p_subject,'');
  v_limit integer:=p_limit;
  v_window integer:=p_window_seconds;
  v_epoch bigint;
  v_start timestamptz;
  v_count integer;
  v_retry integer;
begin
  if v_scope !~ '^[a-z0-9_:-]{2,64}$' then
    raise exception 'invalid_rate_limit_scope';
  end if;
  if length(v_subject)<1 or length(v_subject)>2048 then
    raise exception 'invalid_rate_limit_subject';
  end if;
  if v_limit<1 or v_limit>1000 then
    raise exception 'invalid_rate_limit_limit';
  end if;
  if v_window<1 or v_window>86400 then
    raise exception 'invalid_rate_limit_window';
  end if;

  v_epoch:=floor(extract(epoch from clock_timestamp())/v_window)::bigint*v_window;
  v_start:=to_timestamp(v_epoch);

  insert into private.phms_rate_limit_windows(
    scope,subject_hash,window_start,request_count,updated_at
  )
  values(
    v_scope,
    encode(extensions.digest(convert_to(v_scope||':'||v_subject,'UTF8'),'sha256'),'hex'),
    v_start,
    1,
    now()
  )
  on conflict(scope,subject_hash,window_start)
  do update set
    request_count=private.phms_rate_limit_windows.request_count+1,
    updated_at=now()
  returning request_count into v_count;

  v_retry:=greatest(
    1,
    ceil(extract(epoch from (v_start+make_interval(secs=>v_window)-clock_timestamp())))::integer
  );

  return jsonb_build_object(
    'allowed',v_count<=v_limit,
    'scope',v_scope,
    'limit',v_limit,
    'count',v_count,
    'remaining',greatest(0,v_limit-v_count),
    'retry_after_seconds',case when v_count>v_limit then v_retry else 0 end
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_reassign_line_intake_source_to_active_person(p_line_user_id text, p_source_code text, p_resource text DEFAULT 'appointments'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_ctx private.line_identity_contexts%rowtype;
  v_code text:=lower(btrim(coalesce(p_source_code,'')));
  v_resource text:=lower(btrim(coalesce(p_resource,'appointments')));
  v_source public.data_intake_sources%rowtype;
  v_session public.data_intake_sessions%rowtype;
  v_count int;
  v_source_count int;
  v_new_session uuid;
  v_candidate record;
  v_old_person uuid;
  v_target_person uuid;
begin
  if v_resource not in ('medications','appointments','health_data') then
    raise exception 'unsupported_permission_resource';
  end if;
  if length(v_code)<8 then raise exception 'source_code_too_short'; end if;

  select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
  perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
  select * into v_ctx
  from private.line_identity_contexts
  where line_identity_id=v_line.line_identity_id;

  if v_ctx.active_scope<>'family'
     or v_ctx.active_family_id is null
     or v_ctx.active_family_person_id is null then
    raise exception 'active_family_person_required';
  end if;

  select fp.person_id into v_target_person
  from public.family_persons fp
  where fp.id=v_ctx.active_family_person_id
    and coalesce(fp.status,'active')='active';
  if v_target_person is null then raise exception 'target_person_not_found'; end if;

  if not private.user_can_access_family_person(
    v_line.user_id,v_ctx.active_family_person_id,v_resource,'create'
  ) then
    raise exception 'target_create_permission_required';
  end if;

  select count(*),min(s.id)
  into v_count,v_source.id
  from public.data_intake_sources s
  where s.submitted_by=v_line.user_id
    and lower(s.id::text) like v_code||'%';

  if v_count=0 then raise exception 'intake_source_not_found'; end if;
  if v_count>1 then raise exception 'intake_source_code_ambiguous'; end if;

  select * into v_source
  from public.data_intake_sources
  where id=v_source.id
  for update;

  select * into v_session
  from public.data_intake_sessions
  where id=v_source.session_id
  for update;
  if not found then raise exception 'intake_session_not_found'; end if;

  if v_session.status in ('confirmed','committed','cancelled','rejected') then
    raise exception 'intake_session_already_final';
  end if;

  if v_source.storage_asset_id is not null and (
    exists(select 1 from public.medical_documents d where d.storage_asset_id=v_source.storage_asset_id and d.deleted_at is null)
    or exists(select 1 from public.medication_media m where m.storage_asset_id=v_source.storage_asset_id and m.deleted_at is null)
    or exists(select 1 from public.appointment_document_links l where l.storage_asset_id=v_source.storage_asset_id)
  ) then
    raise exception 'source_asset_already_committed';
  end if;

  v_old_person:=v_session.person_id;

  select count(*) into v_source_count
  from public.data_intake_sources
  where session_id=v_session.id;

  if v_source_count>1 then
    insert into public.data_intake_sessions(
      submitted_by,person_id,family_id,family_person_id,
      channel,status,input_count,context_snapshot,expires_at
    )
    values(
      v_line.user_id,v_target_person,v_ctx.active_family_id,v_ctx.active_family_person_id,
      v_session.channel,v_session.status,1,
      coalesce(v_session.context_snapshot,'{}'::jsonb)
        || jsonb_build_object(
          'person_label',private.family_person_label_for_viewer(v_line.user_id,v_ctx.active_family_person_id),
          'person_pending',false,'person_reassigned',true,'reassigned_at',now()
        ),
      v_session.expires_at
    )
    returning id into v_new_session;

    update public.data_intake_sources set session_id=v_new_session where id=v_source.id;
    update public.data_intake_candidates
    set session_id=v_new_session,person_id=v_target_person,updated_at=now()
    where source_id=v_source.id;
    update public.data_intake_actions a
    set session_id=v_new_session
    where a.candidate_id in (
      select c.id from public.data_intake_candidates c where c.source_id=v_source.id
    );
    update public.data_intake_sessions
    set input_count=(select count(*) from public.data_intake_sources where session_id=v_session.id),
        updated_at=now()
    where id=v_session.id;
  else
    v_new_session:=v_session.id;
    update public.data_intake_sessions
    set person_id=v_target_person,family_id=v_ctx.active_family_id,
        family_person_id=v_ctx.active_family_person_id,
        context_snapshot=coalesce(context_snapshot,'{}'::jsonb)
          || jsonb_build_object(
            'person_label',private.family_person_label_for_viewer(v_line.user_id,v_ctx.active_family_person_id),
            'person_pending',false,'person_reassigned',true,'reassigned_at',now()
          ),
        updated_at=now()
    where id=v_session.id;
    update public.data_intake_candidates
    set person_id=v_target_person,updated_at=now()
    where source_id=v_source.id;
  end if;

  if v_source.storage_asset_id is not null then
    update public.phms_storage_assets
    set person_id=v_target_person,updated_at=now()
    where id=v_source.storage_asset_id
      and deleted_at is null and lifecycle_state<>'deleted';
  end if;

  for v_candidate in
    select id from public.data_intake_candidates where source_id=v_source.id
  loop
    perform public.phms_intake_validate_candidate(v_candidate.id);
    perform public.phms_reconcile_intake_candidate(v_candidate.id);
    insert into public.data_intake_actions(
      session_id,candidate_id,actor_user_id,action,before_data,after_data,reason
    ) values(
      v_new_session,v_candidate.id,v_line.user_id,'edit',
      jsonb_build_object('person_id',v_old_person),
      jsonb_build_object('person_id',v_target_person,'family_person_id',v_ctx.active_family_person_id),
      'line_user_changed_draft_owner'
    );
  end loop;

  return jsonb_build_object(
    'ok',true,'source_id',v_source.id,'source_code',substr(v_source.id::text,1,12),
    'session_id',v_new_session,'person_id',v_target_person,
    'family_person_id',v_ctx.active_family_person_id,
    'person_name',private.family_person_label_for_viewer(v_line.user_id,v_ctx.active_family_person_id)
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_reassign_line_linked_appointment_asset_to_active_person(p_line_user_id text, p_asset_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_ctx private.line_identity_contexts%rowtype;
  v_asset public.phms_storage_assets%rowtype;
  v_target_person uuid;
  v_link record;
  v_unlinked_count int:=0;
begin
  select * into v_line
  from private.resolve_line_user_for_service(p_line_user_id);

  perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);

  select * into v_ctx
  from private.line_identity_contexts
  where line_identity_id=v_line.line_identity_id;

  if v_ctx.active_scope<>'family'
     or v_ctx.active_family_id is null
     or v_ctx.active_family_person_id is null then
    raise exception 'active_family_person_required';
  end if;

  select fp.person_id into v_target_person
  from public.family_persons fp
  where fp.id=v_ctx.active_family_person_id
    and fp.family_id=v_ctx.active_family_id
    and coalesce(fp.status,'active')='active';

  if v_target_person is null then
    raise exception 'target_person_not_found';
  end if;

  if not private.user_can_access_family_person(
    v_line.user_id,v_ctx.active_family_person_id,'appointments','create'
  ) then
    raise exception 'target_appointment_create_required';
  end if;

  select * into v_asset
  from public.phms_storage_assets a
  where a.id=p_asset_id
    and a.deleted_at is null
    and a.lifecycle_state='temporary'
    and a.permission_resource='appointments'
  for update;

  if not found then
    raise exception 'appointment_asset_not_reassignable';
  end if;

  if v_asset.created_by is distinct from v_line.user_id then
    raise exception 'appointment_asset_submitter_required';
  end if;

  for v_link in
    select l.*,a.family_person_id,a.family_id,a.person_id,a.title
    from public.appointment_document_links l
    join public.appointments a on a.id=l.appointment_id
    where l.storage_asset_id=v_asset.id
      and a.deleted_at is null
  loop
    if v_link.family_person_id is null
       or not private.user_can_access_family_person(
         v_line.user_id,v_link.family_person_id,'appointments','update'
       ) then
      raise exception 'source_appointment_update_required';
    end if;

    perform private.phms_put_recycle_entry(
      v_link.family_id,v_link.family_person_id,v_link.person_id,
      'appointment_document_link',v_link.id,'reassign_asset',to_jsonb(v_link),
      'Reassigned appointment asset to another person',v_line.user_id
    );

    delete from public.appointment_document_links
    where id=v_link.id;

    v_unlinked_count:=v_unlinked_count+1;
  end loop;

  update public.phms_storage_assets
  set person_id=v_target_person,
      metadata=(
        coalesce(metadata,'{}'::jsonb)
        - 'appointment_id'
        - 'appointment_link_kind'
      ) || jsonb_build_object(
        'reassigned_after_appointment_link',true,
        'reassigned_from_person_id',v_asset.person_id,
        'reassigned_to_person_id',v_target_person,
        'reassigned_by',v_line.user_id,
        'reassigned_at',now(),
        'manual_entry_required',false
      ),
      updated_at=now()
  where id=v_asset.id;

  insert into public.audit_logs(
    family_id,actor_user_id,family_person_id,event_type,resource,record_id,
    old_data,new_data,description
  )
  values(
    v_ctx.active_family_id,v_line.user_id,v_ctx.active_family_person_id,
    'appointment_asset_reassigned','appointment',v_asset.id,
    jsonb_build_object(
      'person_id',v_asset.person_id,
      'unlinked_appointment_count',v_unlinked_count
    ),
    jsonb_build_object(
      'person_id',v_target_person,
      'unlinked_appointment_count',v_unlinked_count
    ),
    'ย้ายรูป/เอกสารนัดไปยังบุคคลใหม่เพื่อผูกนัดใหม่'
  );

  return jsonb_build_object(
    'ok',true,
    'asset_id',v_asset.id,
    'person_id',v_target_person,
    'person_name',private.family_person_label_for_viewer(
      v_line.user_id,v_ctx.active_family_person_id
    ),
    'unlinked_appointment_count',v_unlinked_count
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_reassign_line_storage_asset_to_active_person(p_line_user_id text, p_asset_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_ctx private.line_identity_contexts%rowtype;
  v_asset public.phms_storage_assets%rowtype;
  v_resource text;
  v_source record;
  v_source_count int;
  v_result jsonb;
begin
  select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
  perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
  select * into v_ctx
  from private.line_identity_contexts
  where line_identity_id=v_line.line_identity_id;

  if v_ctx.active_scope<>'family'
     or v_ctx.active_family_id is null
     or v_ctx.active_family_person_id is null then
    raise exception 'active_family_person_required';
  end if;

  select * into v_asset
  from public.phms_storage_assets
  where id=p_asset_id and deleted_at is null and lifecycle_state<>'deleted'
  for update;
  if not found then raise exception 'asset_not_found'; end if;

  if v_asset.lifecycle_state<>'temporary' then
    raise exception 'asset_owner_change_only_before_commit';
  end if;

  if v_asset.created_by is distinct from v_line.user_id then
    raise exception 'asset_owner_change_submitter_only';
  end if;

  if exists(select 1 from public.medical_documents d where d.storage_asset_id=v_asset.id and d.deleted_at is null)
     or exists(select 1 from public.medication_media m where m.storage_asset_id=v_asset.id and m.deleted_at is null)
     or exists(select 1 from public.appointment_document_links l where l.storage_asset_id=v_asset.id) then
    raise exception 'asset_already_linked_to_canonical_record';
  end if;

  v_resource:=case
    when v_asset.permission_resource='medications' then 'medications'
    when v_asset.permission_resource='appointments' then 'appointments'
    else 'health_data'
  end;

  if not private.user_can_access_family_person(
    v_line.user_id,v_ctx.active_family_person_id,v_resource,'create'
  ) then
    raise exception 'target_create_permission_required';
  end if;

  select count(*) into v_source_count
  from public.data_intake_sources s
  where s.storage_asset_id=v_asset.id
    and s.submitted_by=v_line.user_id;

  if v_source_count>1 then
    raise exception 'asset_has_multiple_intake_sources';
  elsif v_source_count=1 then
    select s.id into v_source
    from public.data_intake_sources s
    where s.storage_asset_id=v_asset.id
      and s.submitted_by=v_line.user_id
    limit 1;

    v_result:=public.phms_reassign_line_intake_source_to_active_person(
      p_line_user_id,v_source.id::text,v_resource
    );
  else
    update public.phms_storage_assets
    set person_id=(select person_id from public.family_persons where id=v_ctx.active_family_person_id),
        updated_at=now()
    where id=v_asset.id;

    v_result:=jsonb_build_object(
      'ok',true,
      'asset_id',v_asset.id,
      'person_id',(select person_id from public.family_persons where id=v_ctx.active_family_person_id),
      'family_person_id',v_ctx.active_family_person_id,
      'person_name',private.family_person_label_for_viewer(v_line.user_id,v_ctx.active_family_person_id),
      'resource',v_resource
    );
  end if;

  return v_result||jsonb_build_object('asset_id',v_asset.id,'resource',v_resource);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_record_line_intake_extraction(p_source_id uuid, p_document_type text, p_raw_text text, p_candidates jsonb DEFAULT '[]'::jsonb, p_provider text DEFAULT 'tesseract_local'::text, p_person_name_evidence jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_source public.data_intake_sources%rowtype;
  v_session public.data_intake_sessions%rowtype;
  v_candidate jsonb;
  v_candidate_id uuid;
  v_count integer := 0;
  v_ordinal integer := 0;
  v_doc text := lower(coalesce(nullif(btrim(p_document_type),''),'unknown'));
  v_raw text := left(coalesce(p_raw_text,''),20000);
  v_class_conf numeric;
  v_blocking jsonb;
  v_warn jsonb;
  v_norm jsonb;
  v_type text;
  v_same_result boolean := false;
  v_reprocess_count integer := 0;
begin
  if p_source_id is null then raise exception 'source_id_required'; end if;
  if v_doc not in (
    'medication_label','medication_list','prescription','dispense_summary',
    'receipt','appointment','medical_document','free_text','unknown','other'
  ) then raise exception 'invalid_document_type'; end if;
  if jsonb_typeof(coalesce(p_candidates,'[]'::jsonb)) <> 'array' then
    raise exception 'candidates_must_be_array';
  end if;
  if jsonb_array_length(coalesce(p_candidates,'[]'::jsonb)) > 20 then
    raise exception 'too_many_candidates';
  end if;

  select * into v_source
  from public.data_intake_sources
  where id=p_source_id
  for update;
  if not found then raise exception 'intake_source_not_found'; end if;

  select * into v_session
  from public.data_intake_sessions
  where id=v_source.session_id
  for update;
  if not found or v_session.channel <> 'line' then
    raise exception 'line_intake_session_required';
  end if;
  if v_source.storage_asset_id is null and v_source.source_kind <> 'text' then
    raise exception 'storage_asset_required';
  end if;
  if v_session.status in ('confirmed','committed','cancelled','rejected') then
    raise exception 'intake_session_already_final';
  end if;

  if exists(
    select 1 from public.data_intake_candidates c
    where c.source_id=v_source.id and c.review_status in ('accepted','committed','edited')
  ) then
    raise exception 'intake_candidates_already_reviewed';
  end if;

  v_same_result :=
    coalesce(v_source.source_metadata->>'extraction_status','')='completed'
    and coalesce(v_source.raw_text,'') = v_raw
    and coalesce(v_source.document_type,'unknown') = v_doc
    and coalesce(v_source.source_metadata->>'extraction_provider','') = coalesce(nullif(p_provider,''),'tesseract_local');

  if v_same_result then
    select count(*) into v_count
    from public.data_intake_candidates c
    where c.source_id=v_source.id;
    return jsonb_build_object(
      'ok',true,'idempotent_replay',true,
      'session_id',v_session.id,'source_id',v_source.id,
      'document_type',v_source.document_type,
      'candidate_count',v_count,
      'raw_text_length',coalesce(length(v_source.raw_text),0),
      'status',v_session.status
    );
  end if;

  v_reprocess_count := coalesce((v_source.source_metadata->>'reprocess_count')::integer,0);

  delete from public.data_intake_candidates
  where source_id=v_source.id;

  v_class_conf := case
    when v_doc='unknown' then 0.20
    when v_doc='medical_document' then 0.55
    when v_doc='free_text' then 0.50
    else 0.80
  end;

  update public.data_intake_sources
  set document_type=v_doc,
      raw_text=v_raw,
      classification_confidence=v_class_conf,
      source_metadata=
        (coalesce(source_metadata,'{}'::jsonb) - 'extraction_error')
        || jsonb_build_object(
             'extraction_status','completed',
             'extraction_provider',coalesce(nullif(p_provider,''),'tesseract_local'),
             'ocr_location','client_device',
             'billing_required',false,
             'review_required',true,
             'auto_commit',false,
             'canonical_commit',false,
             'person_name_evidence',coalesce(p_person_name_evidence,'[]'::jsonb),
             'extracted_at',now(),
             'reprocess_count',v_reprocess_count + case when coalesce(v_source.source_metadata->>'extraction_status','')='completed' then 1 else 0 end
           )
  where id=v_source.id;

  if jsonb_array_length(coalesce(p_candidates,'[]'::jsonb))=0 and length(btrim(v_raw))>0 then
    p_candidates := jsonb_build_array(jsonb_build_object(
      'candidate_type',
        case
          when v_doc in ('medication_label','medication_list','prescription','dispense_summary') then 'medication'
          when v_doc='appointment' then 'appointment'
          when v_doc='receipt' then 'receipt'
          else 'medical_document'
        end,
      'raw_line',left(v_raw,1000),
      'normalized_data',jsonb_build_object(
        'document_type',v_doc,
        'text_preview',left(v_raw,1000)
      ),
      'confidence_data',jsonb_build_object(
        'classification_confidence',v_class_conf,
        'provider',coalesce(nullif(p_provider,''),'tesseract_local')
      )
    ));
  end if;

  for v_candidate in
    select value from jsonb_array_elements(coalesce(p_candidates,'[]'::jsonb))
  loop
    v_type := nullif(btrim(v_candidate->>'candidate_type'),'');
    if v_type is null then continue; end if;
    v_ordinal := v_ordinal + 1;
    v_norm := coalesce(v_candidate->'normalized_data','{}'::jsonb);
    v_blocking := case when v_session.person_id is null
      then jsonb_build_array('person_required') else '[]'::jsonb end;
    v_warn := case when v_norm='{}'::jsonb
      then jsonb_build_array('normalized_data_empty') else '[]'::jsonb end;

    insert into public.data_intake_candidates(
      session_id,source_id,person_id,candidate_type,ordinal,
      extracted_data,normalized_data,confidence_data,
      validation_data,conflict_data,reconciliation_data,review_status
    )
    values(
      v_session.id,
      v_source.id,
      v_session.person_id,
      v_type,
      v_ordinal,
      jsonb_strip_nulls(jsonb_build_object(
        'raw_line',left(coalesce(v_candidate->>'raw_line',''),2000),
        'source_text',left(coalesce(v_candidate->'normalized_data'->>'source_text',v_candidate->>'raw_line',''),2000)
      )),
      v_norm,
      coalesce(v_candidate->'confidence_data','{}'::jsonb)
        || jsonb_build_object('classification_confidence',v_class_conf),
      jsonb_build_object(
        'blocking_errors',v_blocking,
        'warnings',v_warn,
        'validated_at',now()
      ),
      '{}'::jsonb,
      '{}'::jsonb,
      'needs_review'
    )
    returning id into v_candidate_id;

    insert into public.data_intake_actions(
      session_id,candidate_id,actor_user_id,action,after_data
    )
    values(
      v_session.id,v_candidate_id,v_source.submitted_by,'extract',
      jsonb_build_object('source_id',v_source.id,'candidate_type',v_type,'ordinal',v_ordinal)
    );

    insert into public.data_intake_actions(
      session_id,candidate_id,actor_user_id,action,after_data
    )
    values(
      v_session.id,v_candidate_id,v_source.submitted_by,'validate',
      jsonb_build_object('blocking_errors',v_blocking,'warnings',v_warn)
    );

    v_count := v_count + 1;
  end loop;

  update public.data_intake_sessions
  set status='review',updated_at=now()
  where id=v_session.id;

  insert into public.data_intake_actions(
    session_id,actor_user_id,action,after_data
  )
  values(
    v_session.id,v_source.submitted_by,'classify',
    jsonb_build_object(
      'source_id',v_source.id,
      'document_type',v_doc,
      'classification_confidence',v_class_conf,
      'candidate_count',v_count,
      'raw_text_length',length(v_raw),
      'provider',coalesce(nullif(p_provider,''),'tesseract_local'),
      'reprocessed',coalesce(v_source.source_metadata->>'extraction_status','')='completed',
      'review_required',true,
      'auto_commit',false,
      'canonical_commit',false
    )
  );

  return jsonb_build_object(
    'ok',true,'idempotent_replay',false,
    'session_id',v_session.id,'source_id',v_source.id,
    'document_type',v_doc,
    'classification_confidence',v_class_conf,
    'candidate_count',v_count,
    'raw_text_length',length(v_raw),
    'status','review',
    'person_required',v_session.person_id is null,
    'review_required',true,
    'auto_commit',false,
    'canonical_commit',false
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_record_line_manual_extraction(p_line_user_id text, p_source_code text, p_document_type text, p_manual_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
declare
  v_line public.line_identities%rowtype;
  v_source public.data_intake_sources%rowtype;
  v_session public.data_intake_sessions%rowtype;
  v_code text := lower(btrim(coalesce(p_source_code,'')));
  v_doc text := lower(btrim(coalesce(p_document_type,'')));
  v_text text := left(btrim(coalesce(p_manual_text,'')),8000);
  v_match_count integer;
  v_candidate_type text;
  v_result jsonb;
begin
  if length(v_code)<8 then raise exception 'source_code_too_short'; end if;
  if length(v_text)<2 then raise exception 'manual_text_required'; end if;
  if v_doc not in ('appointment','medication_label','medical_document','free_text') then
    raise exception 'invalid_manual_document_type';
  end if;

  select * into v_line
  from public.line_identities
  where line_user_id=p_line_user_id and coalesce(is_active,false)=true
  limit 1;
  if not found or v_line.user_id is null then raise exception 'line_identity_not_linked'; end if;

  select count(*) into v_match_count
  from public.data_intake_sources s
  where s.submitted_by=v_line.user_id
    and lower(s.id::text) like v_code||'%';
  if v_match_count=0 then raise exception 'intake_source_not_found'; end if;
  if v_match_count>1 then raise exception 'intake_source_code_ambiguous'; end if;

  select * into v_source
  from public.data_intake_sources s
  where s.submitted_by=v_line.user_id
    and lower(s.id::text) like v_code||'%'
  limit 1;

  select * into v_session
  from public.data_intake_sessions
  where id=v_source.session_id;
  if not found then raise exception 'intake_session_not_found'; end if;
  if v_session.status in ('confirmed','committed','cancelled','rejected') then
    raise exception 'intake_session_already_final';
  end if;

  v_candidate_type := case
    when v_doc='appointment' then 'appointment'
    when v_doc='medication_label' then 'medication'
    else 'medical_document'
  end;

  v_result := public.phms_record_line_intake_extraction(
    v_source.id,
    v_doc,
    v_text,
    jsonb_build_array(jsonb_build_object(
      'candidate_type',v_candidate_type,
      'raw_line',left(v_text,1500),
      'normalized_data',jsonb_build_object(
        'source_text',v_text,
        'document_type',v_doc,
        'extraction_mode','human_manual'
      ),
      'confidence_data',jsonb_build_object(
        'human_entered',true,
        'ocr_location','human_manual',
        'provider','human_manual',
        'quality_score',1.0
      )
    )),
    'human_manual',
    '[]'::jsonb
  );

  update public.data_intake_sources
  set source_metadata=
    coalesce(source_metadata,'{}'::jsonb)
    || jsonb_build_object(
         'manual_fallback',true,
         'manual_completed_at',now(),
         'extraction_provider','human_manual',
         'ocr_location','human_manual',
         'auto_commit',false,
         'canonical_commit',false
       )
  where id=v_source.id;

  return public.phms_get_line_intake_review_source(
    p_line_user_id,
    v_source.id
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_record_line_manual_structured_extraction(p_line_user_id text, p_source_code text, p_document_type text, p_manual_text text, p_normalized_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
declare
  v_line public.line_identities%rowtype;
  v_source public.data_intake_sources%rowtype;
  v_session public.data_intake_sessions%rowtype;
  v_code text := lower(btrim(coalesce(p_source_code,'')));
  v_doc text := lower(btrim(coalesce(p_document_type,'')));
  v_text text := left(btrim(coalesce(p_manual_text,'')),8000);
  v_match_count integer;
  v_candidate_type text;
  v_norm jsonb := coalesce(p_normalized_data,'{}'::jsonb);
begin
  if length(v_code)<8 then raise exception 'source_code_too_short'; end if;
  if length(v_text)<2 then raise exception 'manual_text_required'; end if;
  if jsonb_typeof(v_norm)<>'object' then raise exception 'normalized_data_object_required'; end if;
  if v_doc not in ('appointment','medication_label','medical_document','free_text') then
    raise exception 'invalid_manual_document_type';
  end if;

  select * into v_line
  from public.line_identities
  where line_user_id=p_line_user_id and coalesce(is_active,false)=true
  limit 1;
  if not found or v_line.user_id is null then raise exception 'line_identity_not_linked'; end if;

  select count(*) into v_match_count
  from public.data_intake_sources s
  where s.submitted_by=v_line.user_id
    and lower(s.id::text) like v_code||'%';
  if v_match_count=0 then raise exception 'intake_source_not_found'; end if;
  if v_match_count>1 then raise exception 'intake_source_code_ambiguous'; end if;

  select * into v_source
  from public.data_intake_sources s
  where s.submitted_by=v_line.user_id
    and lower(s.id::text) like v_code||'%'
  limit 1;

  select * into v_session
  from public.data_intake_sessions
  where id=v_source.session_id;
  if not found then raise exception 'intake_session_not_found'; end if;
  if v_session.status in ('confirmed','committed','cancelled','rejected') then
    raise exception 'intake_session_already_final';
  end if;

  v_candidate_type := case
    when v_doc='appointment' then 'appointment'
    when v_doc='medication_label' then 'medication'
    else 'medical_document'
  end;

  if v_doc='appointment'
     and private.phms_try_timestamptz(v_norm->>'appointment_at') is null then
    raise exception 'appointment_at_required';
  end if;

  v_norm := v_norm || jsonb_build_object(
    'source_text',v_text,
    'document_type',v_doc,
    'extraction_mode','human_manual'
  );

  perform public.phms_record_line_intake_extraction(
    v_source.id,
    v_doc,
    v_text,
    jsonb_build_array(jsonb_build_object(
      'candidate_type',v_candidate_type,
      'raw_line',left(v_text,1500),
      'normalized_data',v_norm,
      'confidence_data',jsonb_build_object(
        'human_entered',true,
        'ocr_location','human_manual',
        'provider','human_manual',
        'quality_score',1.0
      )
    )),
    'human_manual',
    '[]'::jsonb
  );

  update public.data_intake_sources
  set source_metadata=
    coalesce(source_metadata,'{}'::jsonb)
    || jsonb_build_object(
         'manual_fallback',true,
         'manual_completed_at',now(),
         'extraction_provider','human_manual',
         'ocr_location','human_manual',
         'auto_commit',false,
         'canonical_commit',false
       )
  where id=v_source.id;

  return public.phms_get_line_intake_review_source(
    p_line_user_id,
    v_source.id
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_register_line_person_photo(p_line_user_id text, p_object_name text, p_mime_type text, p_byte_size bigint, p_checksum_sha256 text, p_share_with_family boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_line record; v_ctx private.line_identity_contexts%rowtype; v_fp public.family_persons%rowtype; v_p public.persons%rowtype;
 v_id uuid; v_can_share boolean:=false; v_code text;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select c.* into v_ctx from private.line_identity_contexts c where c.line_identity_id=v_line.line_identity_id;
 if v_ctx.active_scope<>'family' or v_ctx.active_family_person_id is null then raise exception 'family_person_context_required'; end if;
 if not private.user_can_see_family_person(v_line.user_id,v_ctx.active_family_person_id) then raise exception 'person_view_denied'; end if;
 select fp.* into v_fp from public.family_persons fp where fp.id=v_ctx.active_family_person_id and fp.family_id=v_ctx.active_family_id;
 select p.* into v_p from public.persons p where p.id=v_fp.person_id;
 perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
 v_can_share:=coalesce(v_p.linked_user_id=v_line.user_id,false) or private.can_access_family_person(v_fp.id,'persons','update');
 if p_share_with_family and not v_can_share then raise exception 'person_photo_share_denied'; end if;
 insert into public.person_photos(family_id,family_person_id,person_id,uploaded_by,uploaded_line_identity_id,object_name,mime_type,byte_size,checksum_sha256,visibility,is_person_shared_default)
 values(v_fp.family_id,v_fp.id,v_p.id,v_line.user_id,v_line.line_identity_id,p_object_name,p_mime_type,p_byte_size,p_checksum_sha256,
        case when p_share_with_family then 'shared' else 'private' end,p_share_with_family)
 returning id into v_id;
 if p_share_with_family then
   update public.person_photos set is_person_shared_default=false,updated_at=now()
   where family_person_id=v_fp.id and id<>v_id and is_person_shared_default=true;
 end if;
 insert into public.person_photo_preferences(viewer_user_id,family_person_id,photo_id,updated_at)
 values(v_line.user_id,v_fp.id,v_id,now())
 on conflict(viewer_user_id,family_person_id) do update set photo_id=excluded.photo_id,updated_at=now();
 v_code:=substr(encode(digest(v_id::text||':'||v_line.line_identity_id::text,'sha256'),'hex'),1,12);
 return jsonb_build_object('status','ok','photo_id',v_id,'photo_code',v_code,'object_name',p_object_name,'shared',p_share_with_family,'selected_for_me',true);
end $function$

CREATE OR REPLACE FUNCTION public.phms_remove_line_family_member(p_line_user_id text, p_member_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_is_owner boolean:=false;
  v_target_is_owner boolean:=false;
begin
  select * into v_ref
  from private.resolve_line_family_member(p_line_user_id,p_member_code)
  limit 1;

  perform set_config('request.jwt.claim.sub',v_ref.actor_user_id::text,true);
  v_is_owner:=private.is_family_owner(v_ref.family_id);
  if not v_is_owner then raise exception 'owner_required_to_remove_member'; end if;

  select exists(
    select 1 from public.family_role_assignments r
    where r.family_id=v_ref.family_id
      and r.user_id=v_ref.target_user_id
      and r.role='owner'
      and r.status='active'
  ) into v_target_is_owner;

  if v_target_is_owner then raise exception 'cannot_remove_family_owner'; end if;
  if v_ref.target_user_id=v_ref.actor_user_id then raise exception 'cannot_remove_self_member'; end if;

  update public.family_memberships
  set status='inactive',updated_at=now()
  where family_id=v_ref.family_id
    and user_id=v_ref.target_user_id
    and status='active';

  update public.family_role_assignments
  set status='inactive',updated_at=now()
  where family_id=v_ref.family_id
    and user_id=v_ref.target_user_id
    and status='active';

  update public.person_caregiver_assignments
  set status='inactive',updated_at=now()
  where family_id=v_ref.family_id
    and caregiver_user_id=v_ref.target_user_id
    and status='active';

  update public.family_persons fp
  set status='inactive',updated_at=now()
  from public.persons p
  where fp.person_id=p.id
    and fp.family_id=v_ref.family_id
    and p.linked_user_id=v_ref.target_user_id
    and coalesce(fp.status,'active')='active';

  update public.person_permissions
  set status='inactive',updated_at=now()
  where family_id=v_ref.family_id
    and user_id=v_ref.target_user_id
    and coalesce(status,'active')='active';

  delete from public.family_permissions
  where family_id=v_ref.family_id
    and user_id=v_ref.target_user_id;

  insert into public.audit_logs(
    family_id,actor_user_id,target_user_id,event_type,resource,old_data,description,created_at
  ) values(
    v_ref.family_id,v_ref.actor_user_id,v_ref.target_user_id,
    'family_member_removed','family_membership',
    jsonb_build_object('member_code',lower(btrim(p_member_code))),
    'Owner soft-removed member from family and revoked active access',
    now()
  );

  return jsonb_build_object('ok',true,'member_code',lower(btrim(p_member_code)),'status','inactive');
end
$function$

CREATE OR REPLACE FUNCTION public.phms_remove_line_family_person(p_line_user_id text, p_person_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_person_id uuid;
  v_linked_user_id uuid;
  v_target_is_owner boolean:=false;
begin
  select * into v_ref
  from private.resolve_line_family_person_code(p_line_user_id,p_person_code)
  limit 1;

  perform set_config('request.jwt.claim.sub',v_ref.actor_user_id::text,true);
  if not private.is_family_owner(v_ref.family_id) then
    raise exception 'owner_required_to_remove_person';
  end if;

  select fp.person_id,p.linked_user_id
  into v_person_id,v_linked_user_id
  from public.family_persons fp
  join public.persons p on p.id=fp.person_id
  where fp.id=v_ref.family_person_id
    and fp.family_id=v_ref.family_id
    and coalesce(fp.status,'active')='active'
  limit 1;

  if v_person_id is null then raise exception 'family_person_not_found'; end if;
  if v_linked_user_id=v_ref.actor_user_id then raise exception 'cannot_remove_self_person'; end if;

  if v_linked_user_id is not null then
    select exists(
      select 1 from public.family_role_assignments r
      where r.family_id=v_ref.family_id and r.user_id=v_linked_user_id
        and r.role='owner' and r.status='active'
    ) into v_target_is_owner;
    if v_target_is_owner then raise exception 'cannot_remove_family_owner'; end if;

    update public.family_memberships
    set status='inactive',updated_at=now()
    where family_id=v_ref.family_id and user_id=v_linked_user_id and status='active';

    update public.family_role_assignments
    set status='inactive',updated_at=now()
    where family_id=v_ref.family_id and user_id=v_linked_user_id and status='active';

    update public.person_caregiver_assignments
    set status='inactive',updated_at=now()
    where family_id=v_ref.family_id and caregiver_user_id=v_linked_user_id and status='active';

    update public.person_permissions
    set status='inactive',updated_at=now()
    where family_id=v_ref.family_id and user_id=v_linked_user_id and coalesce(status,'active')='active';

    delete from public.family_permissions
    where family_id=v_ref.family_id and user_id=v_linked_user_id;
  end if;

  update public.family_persons
  set status='inactive',updated_at=now()
  where id=v_ref.family_person_id and family_id=v_ref.family_id;

  update public.person_caregiver_assignments
  set status='inactive',updated_at=now()
  where family_id=v_ref.family_id and family_person_id=v_ref.family_person_id and status='active';

  update public.person_permissions
  set status='inactive',updated_at=now()
  where family_id=v_ref.family_id and family_person_id=v_ref.family_person_id and coalesce(status,'active')='active';

  update private.line_identity_contexts
  set active_family_person_id=null,updated_at=now()
  where active_family_person_id=v_ref.family_person_id;

  insert into public.audit_logs(
    family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,record_id,
    old_data,description,created_at
  ) values(
    v_ref.family_id,v_ref.actor_user_id,v_linked_user_id,v_ref.family_person_id,
    'family_person_removed','family_person',v_person_id,
    jsonb_build_object('person_code',lower(btrim(p_person_code)),'linked_user_id',v_linked_user_id),
    'Owner soft-removed family person; linked account access revoked; medical history retained',now()
  );

  return jsonb_build_object(
    'ok',true,'person_code',lower(btrim(p_person_code)),
    'status','inactive','linked_account_revoked',v_linked_user_id is not null,
    'medical_history_preserved',true
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_request_access(p_family_id uuid, p_request_type text, p_requested_role text DEFAULT NULL::text, p_family_person_id uuid DEFAULT NULL::uuid, p_resource text DEFAULT NULL::text, p_requested_action text DEFAULT NULL::text, p_reason text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user_id uuid; v_request_id uuid;
begin
 v_user_id:=auth.uid();
 if v_user_id is null then raise exception 'Authentication required'; end if;

 if p_request_type not in ('role','permission','person_bundle') then raise exception 'Invalid request_type'; end if;

 if p_request_type='role' then
   if p_requested_role is null or p_requested_role not in ('admin','caregiver','viewer','patient') then
     raise exception 'Invalid requested role';
   end if;
 elsif p_request_type='permission' then
   if p_resource is null then raise exception 'resource is required'; end if;
   if p_requested_action not in ('view','create','update','delete','receive_notifications','manage_permissions') then
     raise exception 'Invalid requested action';
   end if;
 elsif p_request_type='person_bundle' then
   if p_family_person_id is null then raise exception 'family_person_id is required'; end if;
   if p_requested_action not in ('view','manage') then raise exception 'Invalid bundle level'; end if;
 end if;

 insert into public.permission_requests(
   family_id,requester_user_id,family_person_id,request_type,requested_role,
   resource,requested_action,reason,status,created_at,updated_at
 )
 values(
   p_family_id,v_user_id,p_family_person_id,p_request_type,p_requested_role,
   p_resource,p_requested_action,p_reason,'pending',now(),now()
 )
 returning id into v_request_id;

 insert into public.audit_logs(
   family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,
   record_id,new_data,description,created_at
 )
 values(
   p_family_id,v_user_id,v_user_id,p_family_person_id,'access_requested',p_resource,
   v_request_id,
   jsonb_build_object('request_type',p_request_type,'requested_role',p_requested_role,'requested_action',p_requested_action),
   'User submitted an access request',now()
 );
 return v_request_id;
end
$function$

CREATE OR REPLACE FUNCTION public.phms_request_additional_line_link(p_line_user_id text, p_invite_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  li public.line_identities%rowtype;
  iv public.line_identity_link_invites%rowtype;
  h text;
  c text;
begin
  select * into li from public.line_identities
  where line_user_id=p_line_user_id and is_active=true
  order by updated_at desc nulls last limit 1;
  if not found then raise exception 'line_identity_not_found'; end if;

  h:=encode(digest(btrim(coalesce(p_invite_token,'')),'sha256'),'hex');
  select * into iv from public.line_identity_link_invites
  where token_hash=h and status in ('pending','requested') and expires_at>now()
  for update;
  if not found then raise exception 'invite_invalid_or_expired'; end if;

  if li.user_id is not null then
    if li.user_id=iv.requested_user_id then
      return jsonb_build_object('already_linked',true);
    end if;
    raise exception 'line_linked_elsewhere';
  end if;

  update public.line_identity_link_invites
  set candidate_line_identity_id=li.id,status='requested',requested_at=now(),updated_at=now()
  where id=iv.id;

  c:=substr(encode(digest(iv.id::text||':'||iv.requested_user_id::text,'sha256'),'hex'),1,12);
  return jsonb_build_object(
    'already_linked',false,
    'request_code',c,
    'candidate_display_name',coalesce(nullif(btrim(li.display_name),''),'LINE อีกบัญชี')
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_request_existing_person_claim(p_person_id uuid, p_line_identity_id uuid, p_family_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(claim_request_id uuid, person_id uuid, family_id uuid, status text, requires_approval boolean, already_pending boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_person public.persons%rowtype;
  v_line public.line_identities%rowtype;
  v_family_id uuid;
  v_family_person_id uuid;
  v_existing public.person_claim_requests%rowtype;
  v_count integer;
  v_claim_id uuid;
begin
  if v_user_id is null then
    raise exception 'authentication_required';
  end if;

  select * into v_person
  from public.persons
  where id = p_person_id
  for update;

  if not found then
    raise exception 'person_not_found';
  end if;

  if coalesce(v_person.status, 'active') <> 'active' then
    raise exception 'person_not_active';
  end if;

  if v_person.linked_user_id is not null then
    if v_person.linked_user_id = v_user_id then
      raise exception 'person_already_linked_to_current_user';
    end if;
    raise exception 'person_already_linked_to_another_user';
  end if;

  if exists (
    select 1 from public.persons p
    where p.linked_user_id = v_user_id
      and p.id <> p_person_id
  ) then
    raise exception 'current_user_already_has_person';
  end if;

  select * into v_line
  from public.line_identities
  where id = p_line_identity_id
  for update;

  if not found then
    raise exception 'line_identity_not_found';
  end if;

  if v_line.user_id is distinct from v_user_id then
    raise exception 'line_identity_not_owned_by_current_user';
  end if;

  if coalesce(v_line.is_active, false) is not true then
    raise exception 'active_line_identity_required';
  end if;

  if p_family_id is not null then
    select fp.family_id, fp.id
      into v_family_id, v_family_person_id
    from public.family_persons fp
    where fp.person_id = p_person_id
      and fp.family_id = p_family_id
      and coalesce(fp.status, 'active') = 'active'
    limit 1;

    if v_family_person_id is null then
      raise exception 'person_not_in_family';
    end if;

    if not private.is_active_family_member(v_family_id)
       and not private.can_access_family_person(v_family_person_id, 'persons', 'view') then
      raise exception 'family_person_access_denied';
    end if;
  else
    select count(*) into v_count
    from public.family_persons fp
    where fp.person_id = p_person_id
      and coalesce(fp.status, 'active') = 'active'
      and (
        private.is_active_family_member(fp.family_id)
        or private.can_access_family_person(fp.id, 'persons', 'view')
      );

    if v_count = 0 then
      raise exception 'no_accessible_family_context';
    elsif v_count > 1 then
      raise exception 'family_context_required';
    end if;

    select fp.family_id, fp.id
      into v_family_id, v_family_person_id
    from public.family_persons fp
    where fp.person_id = p_person_id
      and coalesce(fp.status, 'active') = 'active'
      and (
        private.is_active_family_member(fp.family_id)
        or private.can_access_family_person(fp.id, 'persons', 'view')
      )
    limit 1;
  end if;

  select * into v_existing
  from public.person_claim_requests pcr
  where pcr.requested_user_id = v_user_id
    and pcr.person_id = p_person_id
    and pcr.status in ('pending','person_confirmed','approved')
  order by pcr.created_at desc
  limit 1;

  if found then
    return query select v_existing.id, v_existing.person_id, v_existing.family_id,
                        v_existing.status, v_existing.requires_approval, true;
    return;
  end if;

  if exists (
    select 1 from public.person_claim_requests pcr
    where pcr.person_id = p_person_id
      and pcr.status in ('pending','person_confirmed','approved')
      and pcr.requested_user_id <> v_user_id
  ) then
    raise exception 'person_has_open_claim';
  end if;

  if exists (
    select 1 from public.person_claim_requests pcr
    where pcr.requested_user_id = v_user_id
      and pcr.status in ('pending','person_confirmed','approved')
      and pcr.person_id <> p_person_id
  ) then
    raise exception 'current_user_has_open_claim';
  end if;

  insert into public.person_claim_requests(
    person_id,
    requested_user_id,
    family_id,
    initiated_by_user_id,
    requested_from_line_identity_id,
    status,
    requires_approval,
    metadata
  ) values (
    p_person_id,
    v_user_id,
    v_family_id,
    v_user_id,
    p_line_identity_id,
    'pending',
    true,
    jsonb_build_object('claim_type','self_existing_person','source','line')
  ) returning id into v_claim_id;

  insert into public.audit_logs(
    family_id,
    actor_user_id,
    target_user_id,
    family_person_id,
    event_type,
    resource,
    record_id,
    new_data,
    description
  ) values (
    v_family_id,
    v_user_id,
    v_user_id,
    v_family_person_id,
    'person_claim_requested',
    'person_claim',
    v_claim_id,
    jsonb_build_object(
      'person_id', p_person_id,
      'claim_request_id', v_claim_id,
      'line_identity_id', p_line_identity_id,
      'status', 'pending'
    ),
    'User requested to claim an existing person; no person ownership link was changed.'
  );

  return query
  select v_claim_id, p_person_id, v_family_id, 'pending'::text, true, false;
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_request_existing_person_claim_from_line(p_line_user_id text, p_person_id uuid, p_family_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(claim_request_id uuid, person_id uuid, family_id uuid, status text, requires_approval boolean, already_pending boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line public.line_identities%rowtype;
  v_user_id uuid;
  v_person public.persons%rowtype;
  v_family_id uuid;
  v_family_person_id uuid;
  v_existing public.person_claim_requests%rowtype;
  v_count integer;
  v_claim_id uuid;
begin
  if p_line_user_id is null or btrim(p_line_user_id) = '' then
    raise exception 'line_user_id_required';
  end if;

  select * into v_line
  from public.line_identities
  where line_user_id=p_line_user_id
  for update;

  if not found then raise exception 'line_identity_not_found'; end if;
  if coalesce(v_line.is_active,false) is not true then raise exception 'active_line_identity_required'; end if;
  if v_line.user_id is null then raise exception 'line_identity_not_linked'; end if;
  v_user_id := v_line.user_id;

  select * into v_person
  from public.persons
  where id=p_person_id
  for update;

  if not found then raise exception 'person_not_found'; end if;
  if coalesce(v_person.status,'active') <> 'active' then raise exception 'person_not_active'; end if;
  if v_person.linked_user_id is not null then
    if v_person.linked_user_id=v_user_id then raise exception 'person_already_linked_to_current_user'; end if;
    raise exception 'person_already_linked_to_another_user';
  end if;

  if exists (select 1 from public.persons p where p.linked_user_id=v_user_id and p.id<>p_person_id) then
    raise exception 'current_user_already_has_person';
  end if;

  if p_family_id is not null then
    select fp.family_id,fp.id into v_family_id,v_family_person_id
    from public.family_persons fp
    where fp.person_id=p_person_id
      and fp.family_id=p_family_id
      and coalesce(fp.status,'active')='active'
    limit 1;
    if v_family_person_id is null then raise exception 'person_not_in_family'; end if;

    if not exists (
      select 1 from public.family_memberships fm
      where fm.user_id=v_user_id and fm.family_id=v_family_id and fm.status='active'
    ) and not exists (
      select 1 from public.person_permissions pp
      where pp.user_id=v_user_id and pp.family_person_id=v_family_person_id and pp.status='active' and pp.can_view=true
    ) then
      raise exception 'family_person_access_denied';
    end if;
  else
    select count(*) into v_count
    from public.family_persons fp
    where fp.person_id=p_person_id
      and coalesce(fp.status,'active')='active'
      and (
        exists(select 1 from public.family_memberships fm where fm.user_id=v_user_id and fm.family_id=fp.family_id and fm.status='active')
        or exists(select 1 from public.person_permissions pp where pp.user_id=v_user_id and pp.family_person_id=fp.id and pp.status='active' and pp.can_view=true)
      );
    if v_count=0 then raise exception 'no_accessible_family_context';
    elsif v_count>1 then raise exception 'family_context_required'; end if;

    select fp.family_id,fp.id into v_family_id,v_family_person_id
    from public.family_persons fp
    where fp.person_id=p_person_id
      and coalesce(fp.status,'active')='active'
      and (
        exists(select 1 from public.family_memberships fm where fm.user_id=v_user_id and fm.family_id=fp.family_id and fm.status='active')
        or exists(select 1 from public.person_permissions pp where pp.user_id=v_user_id and pp.family_person_id=fp.id and pp.status='active' and pp.can_view=true)
      )
    limit 1;
  end if;

  select * into v_existing
  from public.person_claim_requests pcr
  where pcr.requested_user_id=v_user_id
    and pcr.person_id=p_person_id
    and pcr.status in ('pending','person_confirmed','approved')
  order by pcr.created_at desc
  limit 1;

  if found then
    return query select v_existing.id,v_existing.person_id,v_existing.family_id,v_existing.status,v_existing.requires_approval,true;
    return;
  end if;

  if exists(select 1 from public.person_claim_requests pcr where pcr.person_id=p_person_id and pcr.status in ('pending','person_confirmed','approved') and pcr.requested_user_id<>v_user_id) then
    raise exception 'person_has_open_claim';
  end if;
  if exists(select 1 from public.person_claim_requests pcr where pcr.requested_user_id=v_user_id and pcr.status in ('pending','person_confirmed','approved') and pcr.person_id<>p_person_id) then
    raise exception 'current_user_has_open_claim';
  end if;

  insert into public.person_claim_requests(
    person_id,requested_user_id,family_id,initiated_by_user_id,requested_from_line_identity_id,status,requires_approval,metadata
  ) values (
    p_person_id,v_user_id,v_family_id,v_user_id,v_line.id,'pending',true,
    jsonb_build_object('claim_type','self_existing_person','source','line_webhook')
  ) returning id into v_claim_id;

  insert into public.audit_logs(
    family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,record_id,new_data,description
  ) values (
    v_family_id,v_user_id,v_user_id,v_family_person_id,'person_claim_requested','person_claim',v_claim_id,
    jsonb_build_object('person_id',p_person_id,'claim_request_id',v_claim_id,'line_identity_id',v_line.id,'status','pending','source','line_webhook'),
    'User requested to claim an existing person from an active linked LINE identity; ownership was not changed.'
  );

  return query select v_claim_id,p_person_id,v_family_id,'pending'::text,true,false;
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_request_line_access(p_line_user_id text, p_request_type text, p_requested_role text DEFAULT NULL::text, p_person_code text DEFAULT NULL::text, p_resource text DEFAULT NULL::text, p_requested_action text DEFAULT NULL::text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_line record; v_ctx private.line_identity_contexts%rowtype; v_fp uuid; v_existing uuid; v_id uuid;
 v_type text:=lower(coalesce(nullif(btrim(p_request_type),''),'')); v_role text:=lower(nullif(btrim(p_requested_role),''));
 v_resource text:=lower(nullif(btrim(p_resource),'')); v_action text:=lower(nullif(btrim(p_requested_action),''));
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select c.* into v_ctx from private.line_identity_contexts c where c.line_identity_id=v_line.line_identity_id;
 if v_ctx.active_scope<>'family' or v_ctx.active_family_id is null then raise exception 'family_context_required'; end if;
 if not exists(select 1 from public.family_memberships fm where fm.family_id=v_ctx.active_family_id and fm.user_id=v_line.user_id and fm.status='active') then raise exception 'family_context_not_accessible'; end if;
 if p_person_code is not null and btrim(p_person_code)<>'' then select r.family_person_id into v_fp from private.resolve_line_family_person_code(p_line_user_id,p_person_code) r; end if;
 perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
 select pr.id into v_existing from public.permission_requests pr
 where pr.family_id=v_ctx.active_family_id and pr.requester_user_id=v_line.user_id and pr.status='pending'
 and pr.request_type=v_type and coalesce(pr.requested_role,'')=coalesce(v_role,'')
 and pr.family_person_id is not distinct from v_fp and coalesce(pr.resource,'')=coalesce(v_resource,'')
 and coalesce(pr.requested_action,'')=coalesce(v_action,'') order by pr.created_at desc limit 1;
 if v_existing is not null then return jsonb_build_object('status','pending','request_id',v_existing,'already_pending',true); end if;
 v_id:=public.phms_request_access(v_ctx.active_family_id,v_type,v_role,v_fp,v_resource,v_action,p_reason);
 return jsonb_build_object('status','pending','request_id',v_id,'already_pending',false);
end $function$

CREATE OR REPLACE FUNCTION public.phms_request_line_admin_self_person_access_bundle(p_line_user_id text, p_person_code text, p_is_caregiver boolean, p_medications_level text, p_appointments_level text, p_health_level text, p_receive_notifications boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_ctx private.line_identity_contexts%rowtype;
  v_person record;
  v_med text:=lower(btrim(coalesce(p_medications_level,'none')));
  v_appt text:=lower(btrim(coalesce(p_appointments_level,'none')));
  v_health text:=lower(btrim(coalesce(p_health_level,'none')));
  v_payload jsonb;
  v_req uuid;
  v_person_name text;
begin
  if v_med not in ('none','view','manage')
     or v_appt not in ('none','view','manage')
     or v_health not in ('none','view','manage') then
    raise exception 'invalid_access_level';
  end if;

  select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
  perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
  select * into v_ctx
  from private.line_identity_contexts
  where line_identity_id=v_line.line_identity_id;

  if v_ctx.active_scope<>'family' or v_ctx.active_family_id is null then
    raise exception 'family_context_required';
  end if;

  if not private.user_has_family_role(v_line.user_id,v_ctx.active_family_id,array['admin'])
     or private.user_has_family_role(v_line.user_id,v_ctx.active_family_id,array['owner']) then
    raise exception 'admin_self_access_request_required';
  end if;

  select * into v_person
  from private.resolve_line_family_person_code(p_line_user_id,p_person_code)
  limit 1;

  if v_person.family_id<>v_ctx.active_family_id then
    raise exception 'family_scope_mismatch';
  end if;

  if exists(
    select 1
    from public.family_persons fp
    join public.persons p on p.id=fp.person_id
    where fp.id=v_person.family_person_id
      and p.linked_user_id=v_line.user_id
      and coalesce(fp.status,'active')='active'
      and coalesce(p.status,'active')='active'
  ) then
    raise exception 'self_person_uses_self_access';
  end if;

  v_payload:=jsonb_build_object(
    'caregiver',coalesce(p_is_caregiver,false),
    'medications',v_med,
    'appointments',v_appt,
    'health',v_health,
    'receive_notifications',coalesce(p_receive_notifications,false)
  );

  select pr.id into v_req
  from public.permission_requests pr
  where pr.family_id=v_ctx.active_family_id
    and pr.requester_user_id=v_line.user_id
    and pr.family_person_id=v_person.family_person_id
    and pr.request_type='admin_self_bundle'
    and pr.status='pending'
  order by pr.created_at desc
  limit 1;

  if v_req is not null then
    update public.permission_requests
    set request_payload=v_payload,
        requested_action=case
          when coalesce(p_is_caregiver,false)
            or v_med='manage' or v_appt='manage' or v_health='manage' then 'manage'
          when v_med='view' or v_appt='view' or v_health='view' then 'view'
          else 'none'
        end,
        reason='Admin ขอสิทธิ์ให้ตัวเอง — ยา: '||
          case v_med when 'manage' then 'จัดการ' when 'view' then 'ดู' else 'ไม่มี' end||
          ' • นัดหมาย: '||case v_appt when 'manage' then 'จัดการ' when 'view' then 'ดู' else 'ไม่มี' end||
          ' • สุขภาพ: '||case v_health when 'manage' then 'จัดการ' when 'view' then 'ดู' else 'ไม่มี' end||
          ' • ช่วยจัดการ: '||case when coalesce(p_is_caregiver,false) then 'ใช่' else 'ไม่' end||
          ' • แจ้งเตือน: '||case when coalesce(p_receive_notifications,false) then 'รับ' else 'ไม่รับ' end,
        updated_at=now()
    where id=v_req;

    return jsonb_build_object(
      'ok',true,'already_pending',true,'request_id',v_req,
      'person_code',lower(btrim(p_person_code)),'payload',v_payload
    );
  end if;

  v_person_name:=private.family_person_label_for_viewer(v_line.user_id,v_person.family_person_id);

  insert into public.permission_requests(
    family_id,requester_user_id,family_person_id,target_user_id,
    request_type,resource,requested_action,reason,status,routing_level,
    request_payload,created_at,updated_at
  ) values(
    v_ctx.active_family_id,v_line.user_id,v_person.family_person_id,v_line.user_id,
    'admin_self_bundle','persons',
    case
      when coalesce(p_is_caregiver,false)
        or v_med='manage' or v_appt='manage' or v_health='manage' then 'manage'
      when v_med='view' or v_appt='view' or v_health='view' then 'view'
      else 'none'
    end,
    'Admin ขอสิทธิ์ให้ตัวเองกับ '||coalesce(v_person_name,'บุคคล')||' — ยา: '||
      case v_med when 'manage' then 'จัดการ' when 'view' then 'ดู' else 'ไม่มี' end||
      ' • นัดหมาย: '||case v_appt when 'manage' then 'จัดการ' when 'view' then 'ดู' else 'ไม่มี' end||
      ' • สุขภาพ: '||case v_health when 'manage' then 'จัดการ' when 'view' then 'ดู' else 'ไม่มี' end||
      ' • ช่วยจัดการ: '||case when coalesce(p_is_caregiver,false) then 'ใช่' else 'ไม่' end||
      ' • แจ้งเตือน: '||case when coalesce(p_receive_notifications,false) then 'รับ' else 'ไม่รับ' end,
    'pending','owner',v_payload,now(),now()
  )
  returning id into v_req;

  insert into public.audit_logs(
    family_id,actor_user_id,target_user_id,family_person_id,
    event_type,resource,record_id,new_data,description,created_at
  ) values(
    v_ctx.active_family_id,v_line.user_id,v_line.user_id,v_person.family_person_id,
    'admin_self_access_requested','persons',v_req,v_payload,
    'Admin requested self access; owner approval required',now()
  );

  return jsonb_build_object(
    'ok',true,'already_pending',false,'request_id',v_req,
    'person_code',lower(btrim(p_person_code)),'person_name',v_person_name,'payload',v_payload
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_request_line_family_removal(p_line_user_id text, p_target_kind text, p_target_code text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_ctx private.line_identity_contexts%rowtype;
  v_kind text:=lower(btrim(coalesce(p_target_kind,'')));
  v_member record;
  v_person record;
  v_target_user uuid;
  v_target_fp uuid;
  v_req uuid;
  v_existing uuid;
  v_owner record;
  v_target_name text;
begin
  if v_kind not in ('member','person') then raise exception 'invalid_removal_target_kind'; end if;

  select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
  perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
  select * into v_ctx from private.line_identity_contexts where line_identity_id=v_line.line_identity_id;
  if v_ctx.active_scope<>'family' or v_ctx.active_family_id is null then raise exception 'family_context_required'; end if;

  perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);

  if private.is_family_owner(v_ctx.active_family_id) then raise exception 'owner_should_remove_directly'; end if;
  if not private.user_has_family_role(v_line.user_id,v_ctx.active_family_id,array['admin']) then
    raise exception 'admin_required_to_request_removal';
  end if;

  if v_kind='member' then
    select * into v_member from private.resolve_line_family_member(p_line_user_id,p_target_code) limit 1;
    v_target_user:=v_member.target_user_id;
    if v_target_user=v_line.user_id then raise exception 'cannot_request_remove_self'; end if;
    if private.user_has_family_role(v_target_user,v_ctx.active_family_id,array['owner']) then raise exception 'cannot_remove_family_owner'; end if;
    v_target_name:=private.family_user_label_for_viewer(v_line.user_id,v_ctx.active_family_id,v_target_user);
  else
    select * into v_person from private.resolve_line_family_person_code(p_line_user_id,p_target_code) limit 1;
    v_target_fp:=v_person.family_person_id;
    select p.linked_user_id into v_target_user
    from public.family_persons fp join public.persons p on p.id=fp.person_id
    where fp.id=v_target_fp;
    if v_target_user=v_line.user_id then raise exception 'cannot_request_remove_self'; end if;
    if v_target_user is not null and private.user_has_family_role(v_target_user,v_ctx.active_family_id,array['owner']) then
      raise exception 'cannot_remove_family_owner';
    end if;
    v_target_name:=private.family_person_label_for_viewer(v_line.user_id,v_target_fp);
  end if;

  select id into v_existing
  from public.permission_requests
  where family_id=v_ctx.active_family_id
    and requester_user_id=v_line.user_id
    and request_type='family_removal'
    and status='pending'
    and requested_action=v_kind
    and target_user_id is not distinct from v_target_user
    and family_person_id is not distinct from v_target_fp
  order by created_at desc
  limit 1;

  if v_existing is not null then
    return jsonb_build_object('ok',true,'already_pending',true,'request_id',v_existing,'target_name',v_target_name);
  end if;

  insert into public.permission_requests(
    family_id,requester_user_id,family_person_id,target_user_id,
    request_type,resource,requested_action,reason,status,routing_level,created_at,updated_at
  ) values(
    v_ctx.active_family_id,v_line.user_id,v_target_fp,v_target_user,
    'family_removal','family',v_kind,
    coalesce(nullif(btrim(p_reason),''),'ขอนำ '||coalesce(v_target_name,'สมาชิก')||' ออกจากครอบครัว'),
    'pending','owner',now(),now()
  ) returning id into v_req;

  for v_owner in
    select distinct r.user_id
    from public.family_role_assignments r
    where r.family_id=v_ctx.active_family_id and r.role='owner' and r.status='active'
  loop
    insert into public.notifications(
      family_id,recipient_user_id,event_type,title,message,related_record_id,channel,priority,status,
      family_person_id,scheduled_for,next_attempt_at,payload,dedupe_key,created_at,updated_at
    ) values(
      v_ctx.active_family_id,v_owner.user_id,'family_removal_request',
      '📥 คำขอนำออกจากครอบครัว',
      private.family_user_label_for_viewer(v_owner.user_id,v_ctx.active_family_id,v_line.user_id)||
      ' ขอให้นำ '||coalesce(v_target_name,'สมาชิก')||' ออกจากครอบครัว',
      v_req,'line','normal','pending',v_target_fp,now(),now(),
      jsonb_build_object('request_id',v_req,'target_kind',v_kind),
      'family-removal-request:'||v_req::text||':'||v_owner.user_id::text,now(),now()
    )
    on conflict (dedupe_key) where dedupe_key is not null do nothing;
  end loop;

  insert into public.audit_logs(
    family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,record_id,new_data,description,created_at
  ) values(
    v_ctx.active_family_id,v_line.user_id,v_target_user,v_target_fp,
    'family_removal_requested','family',v_req,
    jsonb_build_object('target_kind',v_kind,'target_name',v_target_name),
    'Admin requested owner approval for family removal',now()
  );

  return jsonb_build_object('ok',true,'already_pending',false,'request_id',v_req,'target_name',v_target_name);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_request_line_person_access_for_member(p_line_user_id text, p_person_code text, p_member_code text, p_level text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_ctx private.line_identity_contexts%rowtype;
  v_person record;
  v_member record;
  v_level text:=lower(btrim(coalesce(p_level,'')));
  v_existing uuid;
  v_id uuid;
  v_linked uuid;
  v_already boolean:=false;
begin
  if v_level not in ('view','manage') then
    raise exception 'invalid_bundle_level';
  end if;

  select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
  perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
  select * into v_ctx
  from private.line_identity_contexts
  where line_identity_id=v_line.line_identity_id;

  if v_ctx.active_scope<>'family' or v_ctx.active_family_id is null then
    raise exception 'family_context_required';
  end if;

  select * into v_person
  from private.resolve_line_family_person_code(p_line_user_id,p_person_code)
  limit 1;
  select * into v_member
  from private.resolve_line_family_member(p_line_user_id,p_member_code)
  limit 1;

  if v_person.family_id<>v_ctx.active_family_id
     or v_member.family_id<>v_ctx.active_family_id then
    raise exception 'family_scope_mismatch';
  end if;

  perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);

  if not private.user_can_see_family_person(v_line.user_id,v_person.family_person_id) then
    raise exception 'person_view_required_for_delegated_request';
  end if;

  if v_member.target_user_id=v_line.user_id then
    raise exception 'use_self_access_request';
  end if;

  select p.linked_user_id into v_linked
  from public.family_persons fp
  join public.persons p on p.id=fp.person_id
  where fp.id=v_person.family_person_id;

  if v_member.target_user_id=v_linked then
    raise exception 'target_is_person_self';
  end if;

  if v_level='manage' then
    v_already:=
      private.user_can_access_family_person(v_member.target_user_id,v_person.family_person_id,'medications','create')
      and private.user_can_access_family_person(v_member.target_user_id,v_person.family_person_id,'appointments','create')
      and private.user_can_access_family_person(v_member.target_user_id,v_person.family_person_id,'health_data','create');
  else
    v_already:=
      private.user_can_access_family_person(v_member.target_user_id,v_person.family_person_id,'medications','view')
      and private.user_can_access_family_person(v_member.target_user_id,v_person.family_person_id,'appointments','view')
      and private.user_can_access_family_person(v_member.target_user_id,v_person.family_person_id,'health_data','view');
  end if;

  if v_already then
    return jsonb_build_object(
      'status','already_allowed',
      'already_allowed',true,
      'target_name',private.family_user_label_for_viewer(
        v_line.user_id,v_ctx.active_family_id,v_member.target_user_id
      )
    );
  end if;

  select pr.id into v_existing
  from public.permission_requests pr
  where pr.family_id=v_ctx.active_family_id
    and pr.requester_user_id=v_line.user_id
    and pr.target_user_id=v_member.target_user_id
    and pr.family_person_id=v_person.family_person_id
    and pr.request_type='delegated_person_bundle'
    and pr.requested_action=v_level
    and pr.status='pending'
  order by pr.created_at desc
  limit 1;

  if v_existing is not null then
    return jsonb_build_object(
      'status','pending','request_id',v_existing,'already_pending',true,
      'target_name',private.family_user_label_for_viewer(
        v_line.user_id,v_ctx.active_family_id,v_member.target_user_id
      )
    );
  end if;

  insert into public.permission_requests(
    family_id,requester_user_id,target_user_id,family_person_id,
    request_type,resource,requested_action,reason,status,
    request_payload,created_at,updated_at
  )
  values(
    v_ctx.active_family_id,v_line.user_id,v_member.target_user_id,
    v_person.family_person_id,'delegated_person_bundle','all_person_data',
    v_level,
    coalesce(
      nullif(btrim(p_reason),''),
      case v_level
        when 'manage' then 'ขอเพิ่มสมาชิกคนนี้เป็นผู้ช่วยจัดการข้อมูล'
        else 'ขอให้สมาชิกคนนี้ดูยา นัดหมาย และสุขภาพได้อย่างเดียว'
      end
    ),
    'pending',
    jsonb_build_object(
      'level',v_level,
      'target_user_id',v_member.target_user_id
    ),
    now(),now()
  )
  returning id into v_id;

  insert into public.audit_logs(
    family_id,actor_user_id,target_user_id,family_person_id,
    event_type,resource,record_id,new_data,description,created_at
  )
  values(
    v_ctx.active_family_id,v_line.user_id,v_member.target_user_id,
    v_person.family_person_id,'delegated_person_access_requested',
    'persons',v_id,
    jsonb_build_object('level',v_level),
    'Requested Owner/Admin to add access for another family member',now()
  );

  return jsonb_build_object(
    'status','pending','request_id',v_id,'already_pending',false,
    'target_name',private.family_user_label_for_viewer(
      v_line.user_id,v_ctx.active_family_id,v_member.target_user_id
    )
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_request_line_person_bundle(p_line_user_id text, p_person_code text, p_level text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_line record; v_ctx private.line_identity_contexts%rowtype; v_person record;
 v_level text:=lower(btrim(coalesce(p_level,''))); v_existing uuid; v_id uuid;
begin
 if v_level not in ('view','manage') then raise exception 'invalid_bundle_level'; end if;
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select c.* into v_ctx from private.line_identity_contexts c where c.line_identity_id=v_line.line_identity_id;
 if v_ctx.active_scope<>'family' or v_ctx.active_family_id is null then raise exception 'family_context_required'; end if;

 select * into v_person from private.resolve_line_family_person_code(p_line_user_id,p_person_code);
 if v_person.family_id<>v_ctx.active_family_id then raise exception 'family_scope_mismatch'; end if;

 perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);

 select pr.id into v_existing
 from public.permission_requests pr
 where pr.family_id=v_ctx.active_family_id
   and pr.requester_user_id=v_line.user_id
   and pr.family_person_id=v_person.family_person_id
   and pr.request_type='person_bundle'
   and pr.requested_action=v_level
   and pr.status='pending'
 order by pr.created_at desc limit 1;

 if v_existing is not null then
   return jsonb_build_object('status','pending','request_id',v_existing,'already_pending',true);
 end if;

 v_id:=public.phms_request_access(
   v_ctx.active_family_id,'person_bundle',null,v_person.family_person_id,
   'all_person_data',v_level,p_reason
 );
 return jsonb_build_object('status','pending','request_id',v_id,'already_pending',false);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_request_line_person_change(p_line_user_id text, p_field text, p_value text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_line record; v_ctx private.line_identity_contexts%rowtype; v_fp public.family_persons%rowtype; v_p public.persons%rowtype;
 v_field text:=lower(btrim(coalesce(p_field,''))); v_value text:=nullif(btrim(coalesce(p_value,'')),'');
 v_old text; v_id uuid; v_norm text; v_name text;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select c.* into v_ctx from private.line_identity_contexts c where c.line_identity_id=v_line.line_identity_id;
 if v_ctx.active_scope<>'family' or v_ctx.active_family_person_id is null then raise exception 'family_person_context_required'; end if;

 select fp.* into v_fp from public.family_persons fp
 where fp.id=v_ctx.active_family_person_id and fp.family_id=v_ctx.active_family_id and coalesce(fp.status,'active')='active';
 select p.* into v_p from public.persons p where p.id=v_fp.person_id and coalesce(p.status,'active')='active';
 if v_p.linked_user_id is distinct from v_line.user_id then raise exception 'only_person_self_can_request_profile_change'; end if;
 if v_field not in ('nickname','first_name','last_name','date_of_birth','sex') then raise exception 'unsupported_person_field'; end if;

 perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
 if private.can_access_family_person(v_fp.id,'persons','update') then raise exception 'direct_update_allowed'; end if;
 if not private.can_access_family_person(v_fp.id,'persons','view') then raise exception 'person_view_denied'; end if;

 if v_field='date_of_birth' and v_value is not null then
   v_norm:=to_char(private.normalize_phms_date(v_value),'YYYY-MM-DD');
 elsif v_field='sex' then
   v_norm:=case lower(coalesce(v_value,''))
     when 'หญิง' then 'female' when 'female' then 'female'
     when 'ชาย' then 'male' when 'male' then 'male'
     when 'อื่นๆ' then 'other' when 'อื่น' then 'other' when 'other' then 'other'
     when 'ไม่ระบุ' then null else v_value end;
 else v_norm:=v_value;
 end if;

 v_old:=case v_field
   when 'nickname' then v_p.nickname
   when 'first_name' then v_p.first_name
   when 'last_name' then v_p.last_name
   when 'date_of_birth' then v_p.date_of_birth
   when 'sex' then v_p.sex
 end;

 select pr.id into v_id
 from public.person_change_requests pr
 where pr.family_person_id=v_fp.id and pr.requester_user_id=v_line.user_id
   and pr.field_name=v_field and pr.status='pending'
 order by pr.created_at desc limit 1;

 if v_id is not null then
   update public.person_change_requests
   set requested_value=v_norm,reason=p_reason,old_value=v_old,updated_at=now()
   where id=v_id;
 else
   insert into public.person_change_requests(
     family_id,family_person_id,person_id,requester_user_id,field_name,
     old_value,requested_value,reason
   )
   values(v_fp.family_id,v_fp.id,v_p.id,v_line.user_id,v_field,v_old,v_norm,p_reason)
   returning id into v_id;
 end if;

 v_name:=private.family_person_label_for_viewer(v_line.user_id,v_fp.id);
 perform private.queue_person_change_review_notifications(v_fp.family_id,v_fp.id,v_id,v_name,v_line.user_id);

 return jsonb_build_object(
   'status','pending','request_id',v_id,
   'request_code',substr(encode(digest(v_id::text||':'||v_line.line_identity_id::text,'sha256'),'hex'),1,12),
   'field',v_field,'requested_value',v_norm
 );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_request_line_self_caregivers(p_line_user_id text, p_member_codes text[], p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_ctx private.line_identity_contexts%rowtype;
  v_self_fp uuid;
  v_code text;
  v_member record;
  v_req uuid;
  v_created int:=0;
  v_existing int:=0;
  v_target_name text;
  v_self_name text;
  v_rec record;
begin
  if coalesce(array_length(p_member_codes,1),0)=0 then raise exception 'caregiver_targets_required'; end if;
  select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
  perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
  select * into v_ctx from private.line_identity_contexts where line_identity_id=v_line.line_identity_id;
  if v_ctx.active_scope<>'family' or v_ctx.active_family_id is null then raise exception 'family_context_required'; end if;

  select fp.id into v_self_fp
  from public.family_persons fp
  join public.persons p on p.id=fp.person_id
  where fp.family_id=v_ctx.active_family_id
    and p.linked_user_id=v_line.user_id
    and coalesce(fp.status,'active')='active'
    and coalesce(p.status,'active')='active'
  limit 1;
  if v_self_fp is null then raise exception 'self_family_person_not_found'; end if;

  perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
  v_self_name:=private.family_person_label_for_viewer(v_line.user_id,v_self_fp);

  foreach v_code in array p_member_codes loop
    select * into v_member from private.resolve_line_family_member(p_line_user_id,v_code) limit 1;
    if v_member.target_user_id=v_line.user_id then continue; end if;

    if exists(
      select 1 from public.person_caregiver_assignments ca
      where ca.family_person_id=v_self_fp
        and ca.caregiver_user_id=v_member.target_user_id
        and ca.status='active'
    ) then
      v_existing:=v_existing+1;
      continue;
    end if;

    if exists(
      select 1 from public.permission_requests pr
      where pr.family_id=v_ctx.active_family_id
        and pr.requester_user_id=v_line.user_id
        and pr.family_person_id=v_self_fp
        and pr.target_user_id=v_member.target_user_id
        and pr.request_type='self_caregiver'
        and pr.status='pending'
    ) then
      v_existing:=v_existing+1;
      continue;
    end if;

    v_target_name:=private.family_user_label_for_viewer(v_line.user_id,v_ctx.active_family_id,v_member.target_user_id);
    insert into public.permission_requests(
      family_id,requester_user_id,family_person_id,target_user_id,
      request_type,resource,requested_action,reason,status,routing_level,created_at,updated_at
    ) values(
      v_ctx.active_family_id,v_line.user_id,v_self_fp,v_member.target_user_id,
      'self_caregiver','persons','add_caregiver',
      coalesce(nullif(btrim(p_reason),''),
        'ขอให้ '||coalesce(v_target_name,'สมาชิก')||' มาช่วยจัดการข้อมูลของ '||coalesce(v_self_name,'ฉัน')),
      'pending','caregiver',now(),now()
    ) returning id into v_req;
    v_created:=v_created+1;

    insert into public.audit_logs(
      family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,record_id,new_data,description,created_at
    ) values(
      v_ctx.active_family_id,v_line.user_id,v_member.target_user_id,v_self_fp,
      'self_caregiver_requested','persons',v_req,
      jsonb_build_object('target_user_id',v_member.target_user_id),
      'Self user requested an additional caregiver',now()
    );

    for v_rec in
      select distinct x.user_id
      from (
        select ca.caregiver_user_id user_id
        from public.person_caregiver_assignments ca
        where ca.family_person_id=v_self_fp
          and ca.status='active'
          and ca.caregiver_user_id<>v_line.user_id

        union all

        select fra.user_id
        from public.family_role_assignments fra
        where fra.family_id=v_ctx.active_family_id
          and fra.status='active'
          and fra.role in ('owner','admin')
          and fra.user_id<>v_line.user_id
          and not exists(
            select 1
            from public.person_caregiver_assignments ca2
            where ca2.family_person_id=v_self_fp
              and ca2.status='active'
              and ca2.caregiver_user_id<>v_line.user_id
          )
      ) x
      where x.user_id is not null
    loop
      insert into public.notifications(
        family_id,recipient_user_id,event_type,title,message,related_record_id,channel,priority,status,
        family_person_id,scheduled_for,next_attempt_at,payload,dedupe_key,created_at,updated_at
      ) values(
        v_ctx.active_family_id,v_rec.user_id,'self_caregiver_request',
        '📥 คำขอเพิ่มคนช่วยจัดการ',
        coalesce(v_self_name,'สมาชิก')||' ขอเพิ่ม '||coalesce(v_target_name,'สมาชิก')||' เป็นคนช่วยจัดการข้อมูล',
        v_req,'line','normal','pending',v_self_fp,now(),now(),
        jsonb_build_object('request_id',v_req,'target_user_id',v_member.target_user_id),
        'self-caregiver-request:'||v_req::text||':'||v_rec.user_id::text,now(),now()
      )
      on conflict (dedupe_key) where dedupe_key is not null do nothing;
    end loop;
  end loop;

  return jsonb_build_object('ok',true,'created',v_created,'already_exists_or_pending',v_existing);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_request_line_self_change(p_line_user_id text, p_field text, p_value text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_line record; v_p public.persons%rowtype; v_fp public.family_persons%rowtype;
 v_field text:=lower(btrim(coalesce(p_field,''))); v_value text:=nullif(btrim(coalesce(p_value,'')),'');
 v_norm text; v_old text; v_id uuid; v_name text;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 if private.user_self_profile_update_allowed(v_line.user_id) then raise exception 'direct_update_allowed'; end if;

 select * into v_p from public.persons p
 where p.linked_user_id=v_line.user_id and coalesce(p.status,'active')='active'
 order by p.created_at limit 1;
 if not found then raise exception 'self_person_unavailable'; end if;

 select fp.* into v_fp
 from public.family_persons fp
 join public.family_memberships fm
   on fm.family_id=fp.family_id and fm.user_id=v_line.user_id and fm.status='active'
 left join public.person_self_access sa on sa.family_person_id=fp.id
 where fp.person_id=v_p.id
   and coalesce(fp.status,'active')='active'
   and coalesce(sa.can_update_profile,true)=false
 order by fp.created_at limit 1;
 if not found then raise exception 'approval_family_not_found'; end if;

 if v_field not in ('nickname','first_name','last_name','date_of_birth','sex') then raise exception 'unsupported_person_field'; end if;

 if v_field='date_of_birth' and v_value is not null then
   v_norm:=to_char(private.normalize_phms_date(v_value),'YYYY-MM-DD');
 elsif v_field='sex' then
   v_norm:=case lower(coalesce(v_value,''))
     when 'หญิง' then 'female' when 'female' then 'female'
     when 'ชาย' then 'male' when 'male' then 'male'
     when 'อื่นๆ' then 'other' when 'อื่น' then 'other' when 'other' then 'other'
     when 'ไม่ระบุ' then null else v_value end;
 else v_norm:=v_value;
 end if;

 v_old:=case v_field
   when 'nickname' then v_p.nickname
   when 'first_name' then v_p.first_name
   when 'last_name' then v_p.last_name
   when 'date_of_birth' then v_p.date_of_birth
   when 'sex' then v_p.sex
 end;

 select r.id into v_id from public.person_change_requests r
 where r.family_person_id=v_fp.id and r.requester_user_id=v_line.user_id
   and r.field_name=v_field and r.status='pending'
 order by r.created_at desc limit 1;

 if v_id is null then
   insert into public.person_change_requests(
     family_id,family_person_id,person_id,requester_user_id,field_name,
     old_value,requested_value,reason
   )
   values(v_fp.family_id,v_fp.id,v_p.id,v_line.user_id,v_field,v_old,v_norm,p_reason)
   returning id into v_id;
 else
   update public.person_change_requests
   set old_value=v_old,requested_value=v_norm,reason=p_reason,updated_at=now()
   where id=v_id;
 end if;

 v_name:=private.family_person_label_for_viewer(v_line.user_id,v_fp.id);
 perform private.queue_person_change_review_notifications(v_fp.family_id,v_fp.id,v_id,v_name,v_line.user_id);

 return jsonb_build_object('status','pending','request_id',v_id,'field',v_field);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_request_line_self_manage(p_line_user_id text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_ctx private.line_identity_contexts%rowtype;
  v_self_fp uuid;
  v_existing uuid;
  v_req uuid;
begin
  select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
  perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
  select * into v_ctx
  from private.line_identity_contexts
  where line_identity_id=v_line.line_identity_id;

  if v_ctx.active_scope<>'family' or v_ctx.active_family_id is null then
    raise exception 'family_context_required';
  end if;

  select fp.id into v_self_fp
  from public.family_persons fp
  join public.persons p on p.id=fp.person_id
  where fp.family_id=v_ctx.active_family_id
    and p.linked_user_id=v_line.user_id
    and coalesce(fp.status,'active')='active'
    and coalesce(p.status,'active')='active'
  limit 1;

  if v_self_fp is null then raise exception 'self_family_person_not_found'; end if;
  if private.family_person_self_manage_enabled(v_self_fp) then
    return jsonb_build_object('status','already_allowed','already_pending',false);
  end if;

  perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);

  select pr.id into v_existing
  from public.permission_requests pr
  where pr.family_id=v_ctx.active_family_id
    and pr.requester_user_id=v_line.user_id
    and pr.family_person_id=v_self_fp
    and pr.request_type='self_manage'
    and pr.status='pending'
  order by pr.created_at desc
  limit 1;

  if v_existing is not null then
    return jsonb_build_object('status','pending','request_id',v_existing,'already_pending',true);
  end if;

  insert into public.permission_requests(
    family_id,requester_user_id,family_person_id,request_type,
    resource,requested_action,reason,status,routing_level,created_at,updated_at
  ) values(
    v_ctx.active_family_id,v_line.user_id,v_self_fp,'self_manage',
    'persons','manage',
    coalesce(nullif(btrim(p_reason),''),'ขอสิทธิ์จัดการข้อมูลของตัวเอง'),
    'pending','caregiver',now(),now()
  )
  returning id into v_req;

  insert into public.audit_logs(
    family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,
    record_id,new_data,description,created_at
  ) values(
    v_ctx.active_family_id,v_line.user_id,v_line.user_id,v_self_fp,
    'self_manage_requested','persons',v_req,
    jsonb_build_object('requested_action','manage'),
    'Self user requested permission to manage own data',now()
  );

  return jsonb_build_object('status','pending','request_id',v_req,'already_pending',false);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_request_line_self_viewer(p_line_user_id text, p_member_code text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_line record;v_ctx private.line_identity_contexts%rowtype;v_self_fp uuid;
 v_member record;v_req uuid;v_target_name text;v_self_name text;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select * into v_ctx from private.line_identity_contexts where line_identity_id=v_line.line_identity_id;
 if v_ctx.active_scope<>'family' or v_ctx.active_family_id is null then raise exception 'family_context_required'; end if;

 select fp.id into v_self_fp
 from public.family_persons fp
 join public.persons p on p.id=fp.person_id
 where fp.family_id=v_ctx.active_family_id and p.linked_user_id=v_line.user_id
   and coalesce(fp.status,'active')='active' and coalesce(p.status,'active')='active'
 limit 1;
 if v_self_fp is null then raise exception 'self_family_person_not_found'; end if;

 perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
 if private.phms_can_manage_medical_grants(v_line.user_id,v_self_fp) then
   raise exception 'medical_manager_can_grant_viewer_directly';
 end if;

 select * into v_member from private.resolve_line_family_member(p_line_user_id,p_member_code) limit 1;
 if v_member.family_id<>v_ctx.active_family_id then raise exception 'family_scope_mismatch'; end if;
 if v_member.target_user_id=v_line.user_id then raise exception 'cannot_grant_self_viewer_to_self'; end if;

 if private.phms_is_medical_primary(v_member.target_user_id,v_self_fp)
    or exists(
      select 1 from public.person_caregiver_assignments ca
      where ca.family_id=v_ctx.active_family_id and ca.family_person_id=v_self_fp
        and ca.caregiver_user_id=v_member.target_user_id and ca.status='active'
    ) then
   return jsonb_build_object('ok',true,'already_allowed',true,'reason','target_already_manages_health_data');
 end if;

 if (
  select count(distinct pp.resource)=5
  from public.person_permissions pp
  where pp.family_id=v_ctx.active_family_id and pp.family_person_id=v_self_fp
    and pp.user_id=v_member.target_user_id
    and pp.resource in ('persons','medications','appointments','health_data','emergency')
    and pp.status='active' and coalesce(pp.can_view,false)
 ) then
   return jsonb_build_object('ok',true,'already_allowed',true,'reason','already_viewer');
 end if;

 select pr.id into v_req
 from public.permission_requests pr
 where pr.family_id=v_ctx.active_family_id and pr.requester_user_id=v_line.user_id
   and pr.family_person_id=v_self_fp and pr.target_user_id=v_member.target_user_id
   and pr.request_type='self_viewer' and pr.status='pending'
 order by pr.created_at desc limit 1;

 if v_req is not null then
   return jsonb_build_object('ok',true,'already_pending',true,'request_id',v_req);
 end if;

 v_target_name:=private.family_user_label_for_viewer(v_line.user_id,v_ctx.active_family_id,v_member.target_user_id);
 v_self_name:=private.family_person_label_for_viewer(v_line.user_id,v_self_fp);

 insert into public.permission_requests(
  family_id,requester_user_id,family_person_id,target_user_id,
  request_type,resource,requested_action,reason,status,routing_level,request_payload,
  created_at,updated_at
 ) values(
  v_ctx.active_family_id,v_line.user_id,v_self_fp,v_member.target_user_id,
  'self_viewer','medical_access','view',
  coalesce(nullif(btrim(p_reason),''),'ขออนุญาตให้ '||coalesce(v_target_name,'สมาชิก')||' ดูข้อมูลของ '||coalesce(v_self_name,'ฉัน')),
  'pending','medical_primary',
  jsonb_build_object('access_kind','viewer','resources',
    jsonb_build_array('persons','medications','appointments','health_data','emergency')),
  now(),now()
 ) returning id into v_req;

 insert into public.audit_logs(
  family_id,actor_user_id,target_user_id,family_person_id,
  event_type,resource,record_id,new_data,description,created_at
 ) values(
  v_ctx.active_family_id,v_line.user_id,v_member.target_user_id,v_self_fp,
  'self_viewer_requested','medical_access',v_req,
  jsonb_build_object('target_user_id',v_member.target_user_id,'all_five_categories',true),
  'Requested primary health caregiver approval for view-only access',now()
 );

 return jsonb_build_object(
  'ok',true,'already_pending',false,'request_id',v_req,
  'target_name',v_target_name,'person_name',v_self_name
 );
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_request_person_claim_by_candidate_from_line(p_line_user_id text, p_candidate_code text)
 RETURNS TABLE(claim_request_id uuid, person_id uuid, family_id uuid, status text, requires_approval boolean, already_pending boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line public.line_identities%rowtype;
  v_match record;
  v_match_count integer;
begin
  if p_line_user_id is null or btrim(p_line_user_id)='' then
    raise exception 'line_user_id_required';
  end if;
  if p_candidate_code is null or btrim(p_candidate_code)='' then
    raise exception 'candidate_code_required';
  end if;

  select * into v_line
  from public.line_identities
  where line_user_id=p_line_user_id
  for update;

  if not found then raise exception 'line_identity_not_found'; end if;
  if coalesce(v_line.is_active,false) is not true then raise exception 'active_line_identity_required'; end if;
  if v_line.user_id is null then raise exception 'line_identity_not_linked'; end if;

  select count(*) into v_match_count
  from public.family_persons fp
  join public.persons p on p.id=fp.person_id
  join public.families f on f.id=fp.family_id
  where coalesce(fp.status,'active')='active'
    and coalesce(p.status,'active')='active'
    and coalesce(f.status,'active')='active'
    and p.linked_user_id is null
    and substr(encode(digest(fp.person_id::text || ':' || fp.family_id::text || ':' || v_line.id::text,'sha256'),'hex'),1,12)=lower(btrim(p_candidate_code))
    and (
      exists(select 1 from public.family_memberships fm where fm.user_id=v_line.user_id and fm.family_id=fp.family_id and fm.status='active')
      or exists(select 1 from public.person_permissions pp where pp.user_id=v_line.user_id and pp.family_person_id=fp.id and pp.status='active' and pp.can_view=true)
    );

  if v_match_count=0 then raise exception 'candidate_not_found_or_not_accessible'; end if;
  if v_match_count>1 then raise exception 'candidate_code_collision'; end if;

  select fp.person_id, fp.family_id into v_match
  from public.family_persons fp
  join public.persons p on p.id=fp.person_id
  join public.families f on f.id=fp.family_id
  where coalesce(fp.status,'active')='active'
    and coalesce(p.status,'active')='active'
    and coalesce(f.status,'active')='active'
    and p.linked_user_id is null
    and substr(encode(digest(fp.person_id::text || ':' || fp.family_id::text || ':' || v_line.id::text,'sha256'),'hex'),1,12)=lower(btrim(p_candidate_code))
    and (
      exists(select 1 from public.family_memberships fm where fm.user_id=v_line.user_id and fm.family_id=fp.family_id and fm.status='active')
      or exists(select 1 from public.person_permissions pp where pp.user_id=v_line.user_id and pp.family_person_id=fp.id and pp.status='active' and pp.can_view=true)
    )
  limit 1;

  return query
  select * from public.phms_request_existing_person_claim_from_line(
    p_line_user_id,
    v_match.person_id,
    v_match.family_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_resolve_active_person_id()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid:=auth.uid(); v_scope text; v_fp uuid; v_person uuid;
begin
 select active_scope,active_family_person_id into v_scope,v_fp from public.user_contexts where user_id=v_uid;
 if v_scope='family' and v_fp is not null then select person_id into v_person from public.family_persons where id=v_fp and status='active'; return v_person; end if;
 select id into v_person from public.persons where linked_user_id=v_uid and status='active' order by created_at limit 1;
 return v_person;
end $function$

CREATE OR REPLACE FUNCTION public.phms_resolve_line_appointment_context(p_line_user_id text, p_hospital_name text, p_department text DEFAULT NULL::text, p_doctor_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_ctx private.line_identity_contexts%rowtype;
  v_person_id uuid;
  v_q text:=nullif(btrim(coalesce(p_hospital_name,'')),'');
  v_qnorm text;
  v_dnorm text:=lower(regexp_replace(coalesce(p_department,''),'[^0-9a-zก-๙]+','','g'));
  v_docnorm text:=lower(regexp_replace(coalesce(p_doctor_name,''),'(นายแพทย์|แพทย์หญิง|นพ[.]?|พญ[.]?|หมอ|แพทย์|[^0-9a-zก-๙]+)','','g'));
  v_hit public.appointments%rowtype;
  v_hit_found boolean:=false;
  v_hn text;
begin
  if v_q is null then return jsonb_build_object('matched',false,'reason','hospital_required'); end if;

  select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
  perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
  select * into v_ctx from private.line_identity_contexts where line_identity_id=v_line.line_identity_id;

  if v_ctx.active_family_person_id is null then
    return jsonb_build_object('matched',false,'reason','active_person_required');
  end if;

  if not private.user_can_access_family_person(
    v_line.user_id,v_ctx.active_family_person_id,'appointments','view'
  ) then
    raise exception 'appointment_view_required';
  end if;

  select fp.person_id into v_person_id
  from public.family_persons fp
  where fp.id=v_ctx.active_family_person_id;

  v_qnorm:=lower(regexp_replace(
    regexp_replace(v_q,'^(โรงพยาบาล|รพ[.]?)[[:space:]]*','','i'),
    '[^0-9a-zก-๙]+','','g'
  ));

  select a.* into v_hit
  from public.appointments a
  where a.person_id=v_person_id
    and a.deleted_at is null
    and nullif(btrim(a.hospital_name),'') is not null
    and (
      lower(regexp_replace(
        regexp_replace(a.hospital_name,'^(โรงพยาบาล|รพ[.]?)[[:space:]]*','','i'),
        '[^0-9a-zก-๙]+','','g'
      ))=v_qnorm
      or lower(regexp_replace(
        regexp_replace(a.hospital_name,'^(โรงพยาบาล|รพ[.]?)[[:space:]]*','','i'),
        '[^0-9a-zก-๙]+','','g'
      )) like v_qnorm||'%'
      or v_qnorm like lower(regexp_replace(
        regexp_replace(a.hospital_name,'^(โรงพยาบาล|รพ[.]?)[[:space:]]*','','i'),
        '[^0-9a-zก-๙]+','','g'
      ))||'%'
    )
  order by
    case when v_dnorm<>'' and lower(regexp_replace(coalesce(a.department,''),'[^0-9a-zก-๙]+','','g'))=v_dnorm then 0 else 1 end,
    case when v_docnorm<>'' and lower(regexp_replace(coalesce(a.doctor_name,''),'(นายแพทย์|แพทย์หญิง|นพ[.]?|พญ[.]?|หมอ|แพทย์|[^0-9a-zก-๙]+)','','g'))=v_docnorm then 0 else 1 end,
    a.appointment_at desc nulls last,a.updated_at desc
  limit 1;

  v_hit_found:=found;

  select pi.identifier_value into v_hn
  from public.person_identifiers pi
  where pi.person_id=v_person_id
    and pi.identifier_type='hospital_hn'
    and (
      (v_hit_found and v_hit.organization_id is not null and pi.issuer_organization_id=v_hit.organization_id)
      or (
        pi.issuer_organization_id is null
        and lower(regexp_replace(coalesce(pi.issuer,''),'[^0-9a-zก-๙]+','','g')) in (
          v_qnorm,
          case when v_hit_found then lower(regexp_replace(coalesce(v_hit.hospital_name,''),'[^0-9a-zก-๙]+','','g')) else '' end
        )
      )
    )
  order by pi.updated_at desc nulls last,pi.created_at desc
  limit 1;

  if not v_hit_found and v_hn is null then
    return jsonb_build_object('matched',false,'reason','history_not_found');
  end if;

  return jsonb_strip_nulls(jsonb_build_object(
    'matched',true,
    'source',case when v_hit_found then 'appointment_history' else 'hospital_identifier' end,
    'hospital_name',case when v_hit_found then v_hit.hospital_name else v_q end,
    'organization_id',case when v_hit_found then v_hit.organization_id else null end,
    'service_unit_id',case when v_hit_found then v_hit.service_unit_id else null end,
    'clinician_id',case when v_hit_found then v_hit.clinician_id else null end,
    'department',case when v_hit_found then v_hit.department else null end,
    'doctor_name',case when v_hit_found then v_hit.doctor_name else null end,
    'contact_phone',case when v_hit_found then v_hit.contact_phone else null end,
    'contact_email',case when v_hit_found then v_hit.contact_email else null end,
    'coverage_type',case when v_hit_found then v_hit.coverage_type else null end,
    'location_detail',case when v_hit_found then v_hit.location_detail else null end,
    'arrival_lead_minutes',case when v_hit_found then v_hit.arrival_lead_minutes else null end,
    'care_topic',case when v_hit_found then v_hit.care_topic else null end,
    'hospital_hn',coalesce(v_hn,case when v_hit_found then v_hit.hospital_hn else null end)
  ));
end
$function$

CREATE OR REPLACE FUNCTION public.phms_resolve_line_appointment_facility(p_line_user_id text, p_hospital_query text, p_department_query text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_ctx private.line_identity_contexts%rowtype;
  v_query text:=nullif(btrim(coalesce(p_hospital_query,'')),'');
  v_dept text:=nullif(btrim(coalesce(p_department_query,'')),'');
  v_qnorm text;
  v_dnorm text;
  v_org record;
  v_unit public.healthcare_service_units%rowtype;
  v_hist record;
  v_display text;
  v_top_count int:=0;
begin
  if v_query is null then
    return jsonb_build_object('matched',false,'reason','hospital_query_empty');
  end if;

  select * into v_line
  from private.resolve_line_user_for_service(p_line_user_id);

  perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);

  select * into v_ctx
  from private.line_identity_contexts
  where line_identity_id=v_line.line_identity_id;

  if v_ctx.active_scope<>'family'
     or v_ctx.active_family_id is null
     or v_ctx.active_family_person_id is null then
    raise exception 'active_family_person_required';
  end if;

  perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);

  if not private.user_can_access_family_person(
    v_line.user_id,v_ctx.active_family_person_id,'appointments','view'
  ) then
    raise exception 'appointment_view_required';
  end if;

  v_qnorm:=lower(v_query);
  v_qnorm:=regexp_replace(v_qnorm,'^(โรงพยาบาล|รพ[.]?)[[:space:]]*','','i');
  v_qnorm:=regexp_replace(v_qnorm,'[^0-9a-zก-๙]+','','g');

  if v_dept is not null then
    v_dnorm:=lower(regexp_replace(v_dept,'[^0-9a-zก-๙]+','','g'));
  end if;

  with ranked as (
    select
      o.*,
      regexp_replace(
        regexp_replace(
          lower(coalesce(o.name,'')||coalesce(o.branch_name,'')),
          '^(โรงพยาบาล|รพ[.]?)[[:space:]]*','','i'
        ),
        '[^0-9a-zก-๙]+','','g'
      ) name_norm,
      regexp_replace(lower(coalesce(o.external_code,'')),'[^0-9a-zก-๙]+','','g') code_norm,
      case
        when nullif(regexp_replace(lower(coalesce(o.external_code,'')),'[^0-9a-zก-๙]+','','g'),'')=v_qnorm then 110
        when regexp_replace(
          regexp_replace(lower(coalesce(o.name,'')||coalesce(o.branch_name,'')),'^(โรงพยาบาล|รพ[.]?)[[:space:]]*','','i'),
          '[^0-9a-zก-๙]+','','g'
        )=v_qnorm then 100
        when regexp_replace(
          regexp_replace(lower(coalesce(o.name,'')||coalesce(o.branch_name,'')),'^(โรงพยาบาล|รพ[.]?)[[:space:]]*','','i'),
          '[^0-9a-zก-๙]+','','g'
        ) like v_qnorm||'%' then 90
        when v_qnorm like regexp_replace(
          regexp_replace(lower(coalesce(o.name,'')||coalesce(o.branch_name,'')),'^(โรงพยาบาล|รพ[.]?)[[:space:]]*','','i'),
          '[^0-9a-zก-๙]+','','g'
        )||'%' then 86
        else 0
      end score
    from public.healthcare_organizations o
    where o.deleted_at is null
  ),
  best as (
    select *
    from ranked
    where score>=86
    order by score desc,updated_at desc,id
    limit 1
  )
  select * into v_org from best;

  if found then
    with ranked as (
      select
        o.id,
        case
          when nullif(regexp_replace(lower(coalesce(o.external_code,'')),'[^0-9a-zก-๙]+','','g'),'')=v_qnorm then 110
          when regexp_replace(
            regexp_replace(lower(coalesce(o.name,'')||coalesce(o.branch_name,'')),'^(โรงพยาบาล|รพ[.]?)[[:space:]]*','','i'),
            '[^0-9a-zก-๙]+','','g'
          )=v_qnorm then 100
          when regexp_replace(
            regexp_replace(lower(coalesce(o.name,'')||coalesce(o.branch_name,'')),'^(โรงพยาบาล|รพ[.]?)[[:space:]]*','','i'),
            '[^0-9a-zก-๙]+','','g'
          ) like v_qnorm||'%' then 90
          when v_qnorm like regexp_replace(
            regexp_replace(lower(coalesce(o.name,'')||coalesce(o.branch_name,'')),'^(โรงพยาบาล|รพ[.]?)[[:space:]]*','','i'),
            '[^0-9a-zก-๙]+','','g'
          )||'%' then 86
          else 0
        end score
      from public.healthcare_organizations o
      where o.deleted_at is null
    )
    select count(*) into v_top_count
    from ranked
    where score=(select max(score) from ranked);

    if v_top_count>1 and v_org.score<100 then
      return jsonb_build_object(
        'matched',false,'ambiguous',true,'source','directory','raw_name',v_query
      );
    end if;

    v_display:=regexp_replace(coalesce(v_org.name,v_query),'^โรงพยาบาล[[:space:]]*','รพ.','i');

    if nullif(btrim(coalesce(v_org.branch_name,'')),'') is not null
       and position(lower(v_org.branch_name) in lower(v_display))=0 then
      v_display:=v_display||' '||btrim(v_org.branch_name);
    end if;

    if nullif(btrim(coalesce(v_org.external_code,'')),'') is not null then
      v_display:=v_display||' ('||btrim(v_org.external_code)||')';
    end if;

    if v_dept is not null then
      select su.* into v_unit
      from public.healthcare_service_units su
      where su.organization_id=v_org.id
        and su.deleted_at is null
      order by
        case
          when nullif(lower(regexp_replace(coalesce(su.code,''),'[^0-9a-zก-๙]+','','g')),'')=v_dnorm then 0
          when lower(regexp_replace(su.name,'[^0-9a-zก-๙]+','','g'))=v_dnorm then 1
          when lower(regexp_replace(su.name,'[^0-9a-zก-๙]+','','g')) like v_dnorm||'%' then 2
          else 9
        end,
        su.updated_at desc
      limit 1;

      if found and not (
        nullif(lower(regexp_replace(coalesce(v_unit.code,''),'[^0-9a-zก-๙]+','','g')),'')=v_dnorm
        or lower(regexp_replace(v_unit.name,'[^0-9a-zก-๙]+','','g'))=v_dnorm
        or lower(regexp_replace(v_unit.name,'[^0-9a-zก-๙]+','','g')) like v_dnorm||'%'
      ) then
        v_unit:=null;
      end if;
    end if;

    return jsonb_strip_nulls(jsonb_build_object(
      'matched',true,
      'source','directory',
      'confidence',case when v_org.score>=100 then 'exact' else 'prefix' end,
      'organization_id',v_org.id,
      'organization_name',v_org.name,
      'branch_name',v_org.branch_name,
      'external_code',v_org.external_code,
      'organization_phone',v_org.phone,
      'organization_email',v_org.email,
      'organization_website_url',v_org.website_url,
      'organization_address',v_org.address_text,
      'contact_phone',coalesce(
        case when v_unit.id is not null then nullif(btrim(v_unit.phone),'') end,
        nullif(btrim(v_org.phone),'')
      ),
      'contact_email',coalesce(
        case when v_unit.id is not null then nullif(btrim(v_unit.email),'') end,
        nullif(btrim(v_org.email),'')
      ),
      'location_detail',coalesce(
        case when v_unit.id is not null then nullif(btrim(v_unit.location_detail),'') end,
        nullif(btrim(v_org.address_text),'')
      ),
      'display_name',v_display,
      'service_unit_id',case when v_unit.id is not null then v_unit.id else null end,
      'service_unit_name',case
        when v_unit.id is null then null
        when nullif(btrim(coalesce(v_unit.code,'')),'') is null then v_unit.name
        else v_unit.name||' ('||v_unit.code||')'
      end,
      'service_unit_code',case when v_unit.id is not null then v_unit.code else null end
    ));
  end if;

  with hist as (
    select
      a.id,
      a.hospital_name,
      a.department,
      regexp_replace(
        regexp_replace(
          lower(regexp_replace(a.hospital_name,'[[:space:]]*[(][^)]*[)][[:space:]]*$','','i')),
          '^(โรงพยาบาล|รพ[.]?)[[:space:]]*','','i'
        ),
        '[^0-9a-zก-๙]+','','g'
      ) base_norm,
      lower(regexp_replace(
        coalesce(substring(a.hospital_name from '[(]([^)]*)[)][[:space:]]*$'),''),
        '[^0-9a-zก-๙]+','','g'
      )) code_norm,
      regexp_replace(
        regexp_replace(lower(a.hospital_name),'^(โรงพยาบาล|รพ[.]?)[[:space:]]*','','i'),
        '[^0-9a-zก-๙]+','','g'
      ) full_norm,
      case
        when nullif(lower(regexp_replace(
          coalesce(substring(a.hospital_name from '[(]([^)]*)[)][[:space:]]*$'),''),
          '[^0-9a-zก-๙]+','','g'
        )),'')=v_qnorm then 110
        when regexp_replace(
          regexp_replace(
            lower(regexp_replace(a.hospital_name,'[[:space:]]*[(][^)]*[)][[:space:]]*$','','i')),
            '^(โรงพยาบาล|รพ[.]?)[[:space:]]*','','i'
          ),
          '[^0-9a-zก-๙]+','','g'
        )=v_qnorm then 100
        when regexp_replace(
          regexp_replace(lower(a.hospital_name),'^(โรงพยาบาล|รพ[.]?)[[:space:]]*','','i'),
          '[^0-9a-zก-๙]+','','g'
        )=v_qnorm then 98
        when regexp_replace(
          regexp_replace(
            lower(regexp_replace(a.hospital_name,'[[:space:]]*[(][^)]*[)][[:space:]]*$','','i')),
            '^(โรงพยาบาล|รพ[.]?)[[:space:]]*','','i'
          ),
          '[^0-9a-zก-๙]+','','g'
        ) like v_qnorm||'%' then 90
        when v_qnorm like regexp_replace(
          regexp_replace(
            lower(regexp_replace(a.hospital_name,'[[:space:]]*[(][^)]*[)][[:space:]]*$','','i')),
            '^(โรงพยาบาล|รพ[.]?)[[:space:]]*','','i'
          ),
          '[^0-9a-zก-๙]+','','g'
        )||'%' then 86
        else 0
      end score
    from public.appointments a
    where a.family_person_id=v_ctx.active_family_person_id
      and a.deleted_at is null
      and nullif(btrim(a.hospital_name),'') is not null
  )
  select * into v_hist
  from hist
  where score>=86
  order by score desc,id desc
  limit 1;

  if found then
    return jsonb_strip_nulls(jsonb_build_object(
      'matched',true,
      'source','history',
      'confidence',case when v_hist.score>=98 then 'exact' else 'prefix' end,
      'display_name',v_hist.hospital_name,
      'service_unit_name',case
        when v_dept is not null
          and nullif(btrim(coalesce(v_hist.department,'')),'') is not null
          and (
            lower(regexp_replace(
              regexp_replace(v_hist.department,'[[:space:]]*[(][^)]*[)][[:space:]]*$','','i'),
              '[^0-9a-zก-๙]+','','g'
            ))=v_dnorm
            or nullif(lower(regexp_replace(
              coalesce(substring(v_hist.department from '[(]([^)]*)[)][[:space:]]*$'),''),
              '[^0-9a-zก-๙]+','','g'
            )),'')=v_dnorm
            or lower(regexp_replace(
              regexp_replace(v_hist.department,'[[:space:]]*[(][^)]*[)][[:space:]]*$','','i'),
              '[^0-9a-zก-๙]+','','g'
            )) like v_dnorm||'%'
          )
        then v_hist.department
        else null
      end,
      'raw_name',v_query
    ));
  end if;

  return jsonb_build_object(
    'matched',false,'source','none','raw_name',v_query
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_resolve_line_linking_state(p_line_user_id text)
 RETURNS TABLE(line_identity_id uuid, line_user_id text, line_is_active boolean, phms_user_id uuid, account_link_status text, self_person_id uuid, claim_request_id uuid, claim_status text, claim_requires_approval boolean, claim_expires_at timestamp with time zone, conversation_state text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line public.line_identities%rowtype;
  v_link public.account_link_requests%rowtype;
  v_person_id uuid;
  v_claim public.person_claim_requests%rowtype;
begin
  if p_line_user_id is null or btrim(p_line_user_id)='' then
    raise exception 'line_user_id_required';
  end if;

  select * into v_line from public.line_identities li where li.line_user_id=p_line_user_id limit 1;
  if not found then
    return query select null::uuid,p_line_user_id,false,null::uuid,null::text,null::uuid,null::uuid,null::text,null::boolean,null::timestamptz,'line_identity_missing'::text;
    return;
  end if;

  if coalesce(v_line.is_active,false) is not true then
    return query select v_line.id,v_line.line_user_id,false,v_line.user_id,null::text,null::uuid,null::uuid,null::text,null::boolean,null::timestamptz,'line_inactive'::text;
    return;
  end if;

  if v_line.user_id is null then
    select * into v_link
    from public.account_link_requests alr
    where alr.line_identity_id=v_line.id and alr.status in ('pending','confirmed')
    order by alr.created_at desc limit 1;

    if found then
      if v_link.expires_at is not null and v_link.expires_at<=now() then
        return query select v_line.id,v_line.line_user_id,true,null::uuid,'expired'::text,null::uuid,null::uuid,null::text,null::boolean,null::timestamptz,'account_link_expired'::text;
        return;
      else
        return query select v_line.id,v_line.line_user_id,true,null::uuid,v_link.status,null::uuid,null::uuid,null::text,null::boolean,null::timestamptz,'account_link_pending'::text;
        return;
      end if;
    end if;

    return query select v_line.id,v_line.line_user_id,true,null::uuid,null::text,null::uuid,null::uuid,null::text,null::boolean,null::timestamptz,'account_unlinked'::text;
    return;
  end if;

  select p.id into v_person_id from public.persons p where p.linked_user_id=v_line.user_id and coalesce(p.status,'active')='active' limit 1;
  if v_person_id is not null then
    return query select v_line.id,v_line.line_user_id,true,v_line.user_id,'completed'::text,v_person_id,null::uuid,null::text,null::boolean,null::timestamptz,'person_linked'::text;
    return;
  end if;

  select * into v_claim
  from public.person_claim_requests pcr
  where pcr.requested_user_id=v_line.user_id and pcr.status in ('pending','person_confirmed','approved')
  order by pcr.created_at desc limit 1;

  if found then
    if v_claim.expires_at is not null and v_claim.expires_at<=now() then
      return query select v_line.id,v_line.line_user_id,true,v_line.user_id,'completed'::text,null::uuid,v_claim.id,'expired'::text,v_claim.requires_approval,v_claim.expires_at,'claim_expired'::text;
      return;
    elsif v_claim.status='pending' then
      return query select v_line.id,v_line.line_user_id,true,v_line.user_id,'completed'::text,null::uuid,v_claim.id,v_claim.status,v_claim.requires_approval,v_claim.expires_at,'claim_pending_confirmation'::text;
      return;
    elsif v_claim.status='person_confirmed' then
      return query select v_line.id,v_line.line_user_id,true,v_line.user_id,'completed'::text,null::uuid,v_claim.id,v_claim.status,v_claim.requires_approval,v_claim.expires_at,case when v_claim.requires_approval then 'claim_waiting_approval' else 'claim_confirmed' end::text;
      return;
    elsif v_claim.status='approved' then
      return query select v_line.id,v_line.line_user_id,true,v_line.user_id,'completed'::text,null::uuid,v_claim.id,v_claim.status,v_claim.requires_approval,v_claim.expires_at,'claim_approved_pending_completion'::text;
      return;
    end if;
  end if;

  select * into v_claim
  from public.person_claim_requests pcr
  where pcr.requested_user_id=v_line.user_id and pcr.status in ('rejected','cancelled','expired')
  order by coalesce(pcr.updated_at,pcr.created_at) desc limit 1;

  if found then
    return query select v_line.id,v_line.line_user_id,true,v_line.user_id,'completed'::text,null::uuid,v_claim.id,v_claim.status,v_claim.requires_approval,v_claim.expires_at,
      case v_claim.status when 'rejected' then 'claim_rejected' when 'cancelled' then 'claim_cancelled' else 'claim_expired' end::text;
    return;
  end if;

  return query select v_line.id,v_line.line_user_id,true,v_line.user_id,'completed'::text,null::uuid,null::uuid,null::text,null::boolean,null::timestamptz,'account_linked_no_person'::text;
  return;
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_resolve_line_main_command(p_line_user_id text, p_command_key text)
 RETURNS TABLE(command_key text, resource text, permission_action text, require_person boolean, required_scope text, line_identity_id uuid, user_id uuid, active_scope text, active_family_id uuid, active_family_person_id uuid, target_person_id uuid, target_person_name text, family_name text, context_valid boolean, context_ready boolean, permission_checked boolean, permission_granted boolean, resolution_code text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_key text := lower(coalesce(nullif(btrim(p_command_key),''),''));
  v_resource text;
  v_action text := 'view';
  v_require_person boolean := false;
  v_required_scope text := 'any';
begin
  case v_key
    when 'medications' then
      v_resource := 'medications';
      v_require_person := true;
    when 'appointments' then
      v_resource := 'appointments';
      v_require_person := false;
    when 'health' then
      v_resource := 'health_data';
      v_require_person := true;
    when 'emergency' then
      v_resource := 'health_data';
      v_require_person := true;
    when 'family' then
      v_resource := null;
      v_require_person := false;
      v_required_scope := 'family';
    else
      raise exception 'unsupported_main_command';
  end case;

  return query
  select
    v_key,
    v_resource,
    v_action,
    v_require_person,
    v_required_scope,
    r.line_identity_id,
    r.user_id,
    r.active_scope,
    r.active_family_id,
    r.active_family_person_id,
    r.target_person_id,
    r.target_person_name,
    r.family_name,
    r.context_valid,
    r.context_ready,
    r.permission_checked,
    r.permission_granted,
    r.resolution_code
  from public.phms_resolve_line_command_context(
    p_line_user_id,
    v_resource,
    v_action,
    v_require_person,
    v_required_scope
  ) r;
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_resolve_my_command_context(p_resource text DEFAULT NULL::text, p_action text DEFAULT 'view'::text, p_require_person boolean DEFAULT false, p_required_scope text DEFAULT 'any'::text)
 RETURNS TABLE(user_id uuid, active_scope text, active_family_id uuid, active_family_person_id uuid, target_person_id uuid, target_person_name text, family_name text, context_valid boolean, context_ready boolean, permission_checked boolean, permission_granted boolean, resolution_code text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  return query select * from private.resolve_user_command_context(v_uid,p_resource,p_action,p_require_person,p_required_scope);
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_restore_line_appointment_owner_context(p_line_user_id text, p_record_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_code text:=lower(btrim(coalesce(p_record_code,'')));
  v_count integer:=0;
  v_a public.appointments%rowtype;
  v_fp public.family_persons%rowtype;
begin
  if length(v_code)<8 then
    raise exception 'record_code_too_short';
  end if;

  select * into v_line
  from private.resolve_line_user_for_service(p_line_user_id);

  perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);

  select count(*)
    into v_count
  from public.appointments a
  join public.family_persons fp on fp.id=a.family_person_id
  where lower(a.id::text) like v_code||'%'
    and a.deleted_at is null
    and coalesce(fp.status,'active')='active'
    and private.user_can_access_family_person(
      v_line.user_id,fp.id,'appointments','view'
    );

  if v_count=0 then raise exception 'appointment_not_found_or_not_accessible'; end if;
  if v_count>1 then raise exception 'appointment_code_ambiguous'; end if;

  select a.*
    into v_a
  from public.appointments a
  join public.family_persons fp on fp.id=a.family_person_id
  where lower(a.id::text) like v_code||'%'
    and a.deleted_at is null
    and coalesce(fp.status,'active')='active'
    and private.user_can_access_family_person(
      v_line.user_id,fp.id,'appointments','view'
    )
  order by a.id::text
  limit 1;

  select *
    into v_fp
  from public.family_persons
  where id=v_a.family_person_id
    and person_id=v_a.person_id
  limit 1;

  if not found then raise exception 'appointment_family_person_missing'; end if;

  update private.line_identity_contexts c
  set active_scope='family',
      active_family_id=v_fp.family_id,
      active_family_person_id=v_fp.id,
      context_changed_at=case
        when c.active_family_id is distinct from v_fp.family_id
          or c.active_family_person_id is distinct from v_fp.id
        then now()
        else c.context_changed_at
      end,
      updated_at=now()
  where c.line_identity_id=v_line.line_identity_id;

  insert into public.person_context_usage(
    user_id,family_person_id,use_count,first_used_at,last_used_at
  )
  values(v_line.user_id,v_fp.id,1,now(),now())
  on conflict on constraint person_context_usage_pkey do update
  set use_count=public.person_context_usage.use_count+1,
      last_used_at=now();

  return jsonb_build_object(
    'ok',true,
    'record_id',v_a.id,
    'record_code',substr(v_a.id::text,1,12),
    'family_id',v_fp.family_id,
    'family_person_id',v_fp.id,
    'person_id',v_a.person_id,
    'person_name',private.family_person_label_for_viewer(v_line.user_id,v_fp.id)
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_review_access_request(p_request_id uuid, p_decision text, p_review_note text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_reviewer uuid:=auth.uid(); v_family_id uuid; v_requester uuid; v_family_person_id uuid; v_target_user uuid;
 v_request_type text; v_requested_role text; v_resource text; v_requested_action text; v_current_status text;
 v_allowed boolean:=false; v_res text; v_person_name text; v_reviewer_name text; v_rec uuid; v_requester_name text; v_payload jsonb;
begin
 if v_reviewer is null then raise exception 'Authentication required'; end if;
 if p_decision not in ('approved','rejected') then raise exception 'Decision must be approved or rejected'; end if;

 select family_id,requester_user_id,family_person_id,target_user_id,request_type,requested_role,resource,requested_action,status,request_payload
 into v_family_id,v_requester,v_family_person_id,v_target_user,v_request_type,v_requested_role,v_resource,v_requested_action,v_current_status,v_payload
 from public.permission_requests where id=p_request_id for update;

 if not found then raise exception 'Permission request not found'; end if;
 if v_current_status<>'pending' then raise exception 'Request has already been reviewed'; end if;
 if v_reviewer=v_requester then raise exception 'request_self_review_not_allowed'; end if;

 if v_request_type='admin_self_bundle' then
   v_allowed:=private.phms_can_manage_medical_grants(v_reviewer,v_family_person_id);
 elsif v_request_type='role' then
   v_allowed:=private.can_grant_role(v_family_id,v_requested_role);
 elsif v_request_type='permission' then
   if v_requested_action='manage_permissions' then
     v_allowed:=private.user_has_family_role(v_reviewer,v_family_id,array['owner','admin']);
   elsif v_family_person_id is not null then
     v_allowed:=private.can_review_person_access_request(v_reviewer,v_family_person_id);
   else
     v_allowed:=private.can_grant_permission(v_family_id,null,v_resource,v_requested_action);
   end if;
 elsif v_request_type='person_bundle' then
   v_allowed:=private.can_review_person_access_request(v_reviewer,v_family_person_id);
 elsif v_request_type='delegated_person_bundle' then
   if v_reviewer=v_target_user
      and not private.user_has_family_role(v_reviewer,v_family_id,array['owner']) then
     raise exception 'request_target_self_review_not_allowed';
   end if;
   v_allowed:=private.phms_can_manage_medical_grants(v_reviewer,v_family_person_id);
 elsif v_request_type='self_caregiver' then
   v_allowed:=private.can_review_person_access_request(v_reviewer,v_family_person_id);
 elsif v_request_type='self_manage' then
   v_allowed:=private.can_review_person_access_request(v_reviewer,v_family_person_id);
 end if;
 if not v_allowed then raise exception 'Reviewer does not have authority for this request'; end if;

 if p_decision='rejected' then
   update public.permission_requests
   set status='rejected',reviewed_by=v_reviewer,reviewed_at=now(),review_note=p_review_note,updated_at=now()
   where id=p_request_id;

   insert into public.audit_logs(
     family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,record_id,new_data,description,created_at
   ) values(
     v_family_id,v_reviewer,v_requester,v_family_person_id,'access_request_rejected',v_resource,p_request_id,
     jsonb_build_object('request_type',v_request_type,'requested_role',v_requested_role,'requested_action',v_requested_action),
     coalesce(p_review_note,'Access request rejected'),now()
   );
   return 'rejected';
 end if;

 if v_request_type='admin_self_bundle' then
   if v_family_person_id is null then raise exception 'admin_self_bundle_person_required'; end if;
   if v_payload is null then raise exception 'admin_self_bundle_payload_required'; end if;

   perform set_config('phms.suppress_access_notifications','on',true);

   if coalesce((v_payload->>'caregiver')::boolean,false) then
     insert into public.person_caregiver_assignments(
       family_id,family_person_id,caregiver_user_id,is_primary,
       can_edit_profile,can_manage_medications,can_manage_appointments,can_manage_health,
       can_receive_notifications,assigned_by,status,assigned_at,created_at,updated_at
     ) values(
       v_family_id,v_family_person_id,v_requester,false,true,
       (v_payload->>'medications')='manage',
       (v_payload->>'appointments')='manage',
       (v_payload->>'health')='manage',
       coalesce((v_payload->>'receive_notifications')::boolean,false),
       v_reviewer,'active',now(),now(),now()
     )
     on conflict(family_person_id,caregiver_user_id) do update set
       status='active',
       can_edit_profile=true,
       can_manage_medications=(v_payload->>'medications')='manage',
       can_manage_appointments=(v_payload->>'appointments')='manage',
       can_manage_health=(v_payload->>'health')='manage',
       can_receive_notifications=coalesce((v_payload->>'receive_notifications')::boolean,false),
       assigned_by=v_reviewer,assigned_at=now(),updated_at=now();
   else
     update public.person_caregiver_assignments
     set status='inactive',updated_at=now()
     where family_person_id=v_family_person_id
       and caregiver_user_id=v_requester
       and status='active';
   end if;

   foreach v_res in array array['medications','appointments','health_data']::text[] loop
     insert into public.person_permissions(
       family_id,family_person_id,user_id,resource,
       can_view,can_create,can_update,can_delete,can_receive_notifications,
       granted_by,status,created_at,updated_at
     ) values(
       v_family_id,v_family_person_id,v_requester,v_res,
       case v_res
         when 'medications' then (v_payload->>'medications') in ('view','manage')
         when 'appointments' then (v_payload->>'appointments') in ('view','manage')
         else (v_payload->>'health') in ('view','manage') end,
       case v_res
         when 'medications' then (v_payload->>'medications')='manage'
         when 'appointments' then (v_payload->>'appointments')='manage'
         else (v_payload->>'health')='manage' end,
       case v_res
         when 'medications' then (v_payload->>'medications')='manage'
         when 'appointments' then (v_payload->>'appointments')='manage'
         else (v_payload->>'health')='manage' end,
       case v_res
         when 'medications' then (v_payload->>'medications')='manage'
         when 'appointments' then (v_payload->>'appointments')='manage'
         else (v_payload->>'health')='manage' end,
       coalesce((v_payload->>'receive_notifications')::boolean,false),
       v_reviewer,'active',now(),now()
     )
     on conflict(family_id,family_person_id,user_id,resource) do update set
       can_view=excluded.can_view,can_create=excluded.can_create,
       can_update=excluded.can_update,can_delete=excluded.can_delete,
       can_receive_notifications=excluded.can_receive_notifications,
       granted_by=v_reviewer,status='active',updated_at=now();
   end loop;

   perform set_config('phms.suppress_access_notifications','off',true);

 elsif v_request_type='self_manage' then
   insert into public.person_self_access(
     family_person_id,family_id,
     can_view_profile,can_update_profile,
     can_view_medications,can_create_medications,can_update_medications,can_delete_medications,
     can_view_appointments,can_create_appointments,can_update_appointments,can_delete_appointments,
     can_view_health,can_create_health,can_update_health,can_delete_health,
     configured_by,created_at,updated_at
   )
   values(
     v_family_person_id,v_family_id,
     true,true,
     true,true,true,false,
     true,true,true,false,
     true,true,true,false,
     v_reviewer,now(),now()
   )
   on conflict(family_person_id) do update set
     can_view_profile=true,can_update_profile=true,
     can_view_medications=true,can_create_medications=true,can_update_medications=true,
     can_view_appointments=true,can_create_appointments=true,can_update_appointments=true,
     can_view_health=true,can_create_health=true,can_update_health=true,
     configured_by=v_reviewer,updated_at=now();

 elsif v_request_type='role' then
   insert into public.family_role_assignments(
     family_id,user_id,role,status,granted_by,granted_at,created_at,updated_at
   ) values(v_family_id,v_requester,v_requested_role,'active',v_reviewer,now(),now(),now())
   on conflict do nothing;

 elsif v_request_type='delegated_person_bundle' then
   if v_target_user is null or v_family_person_id is null then
     raise exception 'delegated_person_bundle_invalid';
   end if;

   perform set_config('phms.suppress_access_notifications','on',true);

   if v_requested_action='manage' then
     insert into public.person_caregiver_assignments(
       family_id,family_person_id,caregiver_user_id,is_primary,
       can_edit_profile,can_manage_medications,can_manage_appointments,can_manage_health,
       can_receive_notifications,assigned_by,status,assigned_at,created_at,updated_at
     ) values(
       v_family_id,v_family_person_id,v_target_user,false,
       true,true,true,true,true,v_reviewer,'active',now(),now(),now()
     )
     on conflict(family_person_id,caregiver_user_id) do update
     set status='active',can_edit_profile=true,
         can_manage_medications=true,can_manage_appointments=true,can_manage_health=true,
         can_receive_notifications=true,assigned_by=v_reviewer,
         assigned_at=now(),updated_at=now();

     if not private.user_has_family_role(v_target_user,v_family_id,array['owner']) then
       insert into public.family_role_assignments(
         family_id,user_id,role,status,granted_by,granted_at,created_at,updated_at
       ) values(
         v_family_id,v_target_user,'caregiver','active',v_reviewer,now(),now(),now()
       )
       on conflict do nothing;
     end if;
   end if;

   foreach v_res in array array['medications','appointments','health_data']::text[] loop
     insert into public.person_permissions(
       family_id,family_person_id,user_id,resource,
       can_view,can_create,can_update,can_delete,can_receive_notifications,
       granted_by,status,created_at,updated_at
     ) values(
       v_family_id,v_family_person_id,v_target_user,v_res,
       true,
       v_requested_action='manage',
       v_requested_action='manage',
       v_requested_action='manage',
       v_requested_action='manage',
       v_reviewer,'active',now(),now()
     )
     on conflict(family_id,family_person_id,user_id,resource) do update
     set can_view=true,
         can_create=public.person_permissions.can_create or excluded.can_create,
         can_update=public.person_permissions.can_update or excluded.can_update,
         can_delete=public.person_permissions.can_delete or excluded.can_delete,
         can_receive_notifications=public.person_permissions.can_receive_notifications
           or excluded.can_receive_notifications,
         granted_by=v_reviewer,status='active',updated_at=now();
   end loop;

   perform set_config('phms.suppress_access_notifications','off',true);

 elsif v_request_type='person_bundle' then
   perform set_config('phms.suppress_access_notifications','on',true);

   if v_requested_action='manage' then
     insert into public.family_role_assignments(
       family_id,user_id,role,status,granted_by,granted_at,created_at,updated_at
     ) values(v_family_id,v_requester,'caregiver','active',v_reviewer,now(),now(),now())
     on conflict do nothing;

     insert into public.person_caregiver_assignments(
       family_id,family_person_id,caregiver_user_id,is_primary,
       can_edit_profile,can_manage_medications,can_manage_appointments,can_manage_health,
       can_receive_notifications,assigned_by,status,assigned_at,created_at,updated_at
     ) values(
       v_family_id,v_family_person_id,v_requester,false,true,true,true,true,true,
       v_reviewer,'active',now(),now(),now()
     )
     on conflict(family_person_id,caregiver_user_id) do update
     set status='active',can_edit_profile=true,can_manage_medications=true,
         can_manage_appointments=true,can_manage_health=true,can_receive_notifications=true,
         assigned_by=v_reviewer,updated_at=now();

     perform private.ensure_self_caregiver_for_family_user(v_family_id,v_requester,v_reviewer);
   end if;

   foreach v_res in array array['medications','appointments','health_data']::text[] loop
     insert into public.person_permissions(
       family_id,family_person_id,user_id,resource,can_view,can_create,can_update,can_delete,
       can_receive_notifications,granted_by,status,created_at,updated_at
     ) values(
       v_family_id,v_family_person_id,v_requester,v_res,
       true,v_requested_action='manage',v_requested_action='manage',v_requested_action='manage',
       v_requested_action='manage',v_reviewer,'active',now(),now()
     )
     on conflict(family_id,family_person_id,user_id,resource) do update
     set can_view=true,
         can_create=excluded.can_create,can_update=excluded.can_update,can_delete=excluded.can_delete,
         can_receive_notifications=excluded.can_receive_notifications,
         granted_by=v_reviewer,status='active',updated_at=now();
   end loop;

   perform set_config('phms.suppress_access_notifications','off',true);

 elsif v_request_type='self_caregiver' then
   if v_target_user is null or v_family_person_id is null then raise exception 'self_caregiver_request_invalid'; end if;

   insert into public.person_caregiver_assignments(
     family_id,family_person_id,caregiver_user_id,is_primary,
     can_edit_profile,can_manage_medications,can_manage_appointments,can_manage_health,
     can_receive_notifications,assigned_by,status,assigned_at,created_at,updated_at
   ) values(
     v_family_id,v_family_person_id,v_target_user,false,
     true,true,true,true,true,v_reviewer,'active',now(),now(),now()
   )
   on conflict(family_person_id,caregiver_user_id) do update
   set status='active',can_edit_profile=true,can_manage_medications=true,
       can_manage_appointments=true,can_manage_health=true,can_receive_notifications=true,
       assigned_by=v_reviewer,assigned_at=now(),updated_at=now();

   if not private.user_has_family_role(v_target_user,v_family_id,array['owner']) then
     insert into public.family_role_assignments(
       family_id,user_id,role,status,granted_by,granted_at,created_at,updated_at
     ) values(v_family_id,v_target_user,'caregiver','active',v_reviewer,now(),now(),now())
     on conflict do nothing;
   end if;

   foreach v_res in array array['medications','appointments','health_data']::text[] loop
     insert into public.person_permissions(
       family_id,family_person_id,user_id,resource,can_view,can_create,can_update,can_delete,
       can_receive_notifications,granted_by,status,created_at,updated_at
     ) values(
       v_family_id,v_family_person_id,v_target_user,v_res,true,true,true,true,true,
       v_reviewer,'active',now(),now()
     )
     on conflict(family_id,family_person_id,user_id,resource) do update
     set can_view=true,can_create=true,can_update=true,can_delete=true,
         can_receive_notifications=true,granted_by=v_reviewer,status='active',updated_at=now();
   end loop;

 elsif v_request_type='permission' and v_family_person_id is null then
   insert into public.family_permissions(
     family_id,user_id,resource,can_view,can_create,can_update,can_delete,can_manage_permissions,
     granted_by,created_at,updated_at
   ) values(
     v_family_id,v_requester,v_resource,
     v_requested_action='view',v_requested_action='create',v_requested_action='update',
     v_requested_action='delete',v_requested_action='manage_permissions',v_reviewer,now(),now()
   )
   on conflict(family_id,user_id,resource) do update
   set can_view=public.family_permissions.can_view or excluded.can_view,
       can_create=public.family_permissions.can_create or excluded.can_create,
       can_update=public.family_permissions.can_update or excluded.can_update,
       can_delete=public.family_permissions.can_delete or excluded.can_delete,
       can_manage_permissions=public.family_permissions.can_manage_permissions or excluded.can_manage_permissions,
       granted_by=v_reviewer,updated_at=now();

 else
   insert into public.person_permissions(
     family_id,family_person_id,user_id,resource,can_view,can_create,can_update,can_delete,
     can_receive_notifications,granted_by,status,created_at,updated_at
   ) values(
     v_family_id,v_family_person_id,v_requester,v_resource,
     v_requested_action='view',v_requested_action='create',v_requested_action='update',
     v_requested_action='delete',v_requested_action='receive_notifications',
     v_reviewer,'active',now(),now()
   )
   on conflict(family_id,family_person_id,user_id,resource) do update
   set can_view=public.person_permissions.can_view or excluded.can_view,
       can_create=public.person_permissions.can_create or excluded.can_create,
       can_update=public.person_permissions.can_update or excluded.can_update,
       can_delete=public.person_permissions.can_delete or excluded.can_delete,
       can_receive_notifications=public.person_permissions.can_receive_notifications or excluded.can_receive_notifications,
       granted_by=v_reviewer,status='active',updated_at=now();
 end if;

 update public.permission_requests
 set status='approved',reviewed_by=v_reviewer,reviewed_at=now(),review_note=p_review_note,updated_at=now()
 where id=p_request_id;

 insert into public.audit_logs(
   family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,record_id,new_data,description,created_at
 ) values(
   v_family_id,v_reviewer,v_requester,v_family_person_id,'access_request_approved',v_resource,p_request_id,
   jsonb_build_object('request_type',v_request_type,'requested_role',v_requested_role,'requested_action',v_requested_action),
   coalesce(p_review_note,'Access request approved'),now()
 );

 if v_request_type='admin_self_bundle' then
   for v_rec in
     select distinct uid
