       select p.linked_user_id uid
       from public.family_persons fp
       join public.persons p on p.id=fp.person_id
       where fp.id=v_family_person_id

       union all

       select ca.caregiver_user_id
       from public.person_caregiver_assignments ca
       where ca.family_person_id=v_family_person_id
         and ca.status='active'
     ) x
     where uid is not null
       and uid<>v_reviewer
   loop
     v_person_name:=private.family_person_label_for_viewer(v_rec,v_family_person_id);
     v_requester_name:=private.family_user_label_for_viewer(v_rec,v_family_id,v_requester);

     insert into public.notifications(
