       '🔐 มีการอนุมัติสิทธิ์เข้าถึงข้อมูล',
       v_requester_name||' ได้รับการอนุมัติสิทธิ์กับ '||coalesce(v_person_name,'บุคคล')||
       E'\n'||coalesce(
         'ยา: '||case v_payload->>'medications' when 'manage' then 'จัดการ' when 'view' then 'ดู' else 'ไม่มี' end||
         ' • นัดหมาย: '||case v_payload->>'appointments' when 'manage' then 'จัดการ' when 'view' then 'ดู' else 'ไม่มี' end||
         ' • สุขภาพ: '||case v_payload->>'health' when 'manage' then 'จัดการ' when 'view' then 'ดู' else 'ไม่มี' end,
         ''
       ),
