   end loop;

 elsif v_request_type='delegated_person_bundle' then
   for v_rec in
     select distinct uid
     from (
       select v_requester uid
       union all select v_target_user
       union all
       select p.linked_user_id
       from public.family_persons fp
       join public.persons p on p.id=fp.person_id
       where fp.id=v_family_person_id
     ) x
     where uid is not null and uid<>v_reviewer
   loop
     v_person_name:=private.family_person_label_for_viewer(v_rec,v_family_person_id);
