     on conflict(dedupe_key) where dedupe_key is not null do nothing;
   end loop;

 elsif v_request_type='person_bundle' then
   v_person_name:=private.family_person_label_for_viewer(v_requester,v_family_person_id);
   v_reviewer_name:=private.family_user_label_for_viewer(v_requester,v_family_id,v_reviewer);
   insert into public.notifications(
     family_id,recipient_user_id,event_type,title,message,related_record_id,channel,priority,status,
