       then 'คุณได้รับสิทธิ์ผู้ดูแลและจัดการข้อมูลของ '||v_person_name
       else 'คุณได้รับสิทธิ์ดูข้อมูลยา นัดหมาย และสุขภาพของ '||v_person_name end||
       E'\nผู้อนุมัติ: '||v_reviewer_name,
     p_request_id,'line','normal','pending',v_family_person_id,now(),now(),
     jsonb_build_object('request_id',p_request_id,'decision','approved','level',v_requested_action),
     'access-request-result:'||p_request_id::text||':approved',now(),now()
   )
   on conflict (dedupe_key) where dedupe_key is not null do nothing;

 elsif v_request_type in ('self_caregiver','self_manage') then
   for v_rec in
     select distinct uid
     from (
       select v_requester uid
       union all select v_target_user
       union all
       select p.linked_user_id
       from public.family_persons fp
       join public.persons p on p.id=fp.person_id
       where fp.id=v_family_person_id
       union all
