       from public.family_role_assignments fra
       where fra.family_id=v_family_id
         and fra.status='active'
         and fra.role in ('owner','admin')
     ) x
     where uid is not null
       and uid<>v_reviewer
   loop
     v_person_name:=private.family_person_label_for_viewer(v_rec,v_family_person_id);
     v_reviewer_name:=private.family_user_label_for_viewer(v_rec,v_family_id,v_reviewer);
     v_requester_name:=private.family_user_label_for_viewer(v_rec,v_family_id,v_requester);

     insert into public.notifications(
