       case
         when v_request_type='self_manage'
           then v_requester_name||' ได้รับสิทธิ์จัดการข้อมูลของตัวเอง ('||coalesce(v_person_name,'ข้อมูลของฉัน')||')'
         else v_requester_name||' ได้รับอนุมัติคำขอเพิ่มคนช่วยจัดการข้อมูลของ '||coalesce(v_person_name,'ผู้ป่วย')
       end||E'\nผู้อนุมัติ: '||v_reviewer_name,
       p_request_id,'line','normal','pending',v_family_person_id,now(),now(),
       jsonb_build_object('request_id',p_request_id,'decision','approved','request_type',v_request_type),
       'patient-access-request-result:'||p_request_id::text||':'||v_rec::text,now(),now()
     )
     on conflict (dedupe_key) where dedupe_key is not null do nothing;
   end loop;
