CREATE OR REPLACE FUNCTION public.phms_review_additional_line_link(p_line_user_id text, p_request_code text, p_decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  a public.line_identities%rowtype;
  iv public.line_identity_link_invites%rowtype;
  c public.line_identities%rowtype;
  d text:=lower(btrim(coalesce(p_decision,'')));
begin
  select * into a from public.line_identities
  where line_user_id=p_line_user_id and is_active=true and user_id is not null
  order by updated_at desc nulls last limit 1;
  if not found then raise exception 'linked_line_required'; end if;

  select * into iv from public.line_identity_link_invites i
  where i.requested_user_id=a.user_id
    and i.status='requested'
    and i.expires_at>now()
    and substr(encode(digest(i.id::text||':'||i.requested_user_id::text,'sha256'),'hex'),1,12)=lower(btrim(p_request_code))
  for update;
  if not found then raise exception 'request_not_found'; end if;

  select * into c from public.line_identities where id=iv.candidate_line_identity_id for update;
  if not found then raise exception 'candidate_not_found'; end if;

  if d='reject' then
    update public.line_identity_link_invites set status='revoked',updated_at=now() where id=iv.id;
    return jsonb_build_object('approved',false,'candidate_line_user_id',c.line_user_id,'candidate_display_name',coalesce(nullif(btrim(c.display_name),''),'LINE อีกบัญชี'));
  end if;

  if d<>'approve' then raise exception 'invalid_decision'; end if;
  if c.user_id is not null and c.user_id<>a.user_id then raise exception 'candidate_linked_elsewhere'; end if;

  update public.line_identities
  set user_id=a.user_id,onboarding_status='ready',linking_completed_at=now(),updated_at=now()
  where id=c.id;

  update public.line_identity_link_invites
  set status='completed',completed_at=now(),updated_at=now()
  where id=iv.id;

  return jsonb_build_object('approved',true,'candidate_line_user_id',c.line_user_id,'candidate_display_name',coalesce(nullif(btrim(c.display_name),''),'LINE อีกบัญชี'));
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_review_line_access_request(p_line_user_id text, p_request_code text, p_decision text, p_review_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare v_line record; v_ctx private.line_identity_contexts%rowtype; v_request uuid; v_decision text:=lower(coalesce(nullif(btrim(p_decision),''),'')); v_result text;
begin
 if v_decision in ('approve','approved','อนุมัติ') then v_decision:='approved'; elsif v_decision in ('reject','rejected','ปฏิเสธ') then v_decision:='rejected'; else raise exception 'invalid_review_decision'; end if;
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select c.* into v_ctx from private.line_identity_contexts c where c.line_identity_id=v_line.line_identity_id;
 if v_ctx.active_scope<>'family' or v_ctx.active_family_id is null then raise exception 'family_context_required'; end if;
 select pr.id into v_request from public.permission_requests pr
 where pr.family_id=v_ctx.active_family_id and pr.status='pending'
 and substr(encode(digest(pr.id::text||':'||v_line.line_identity_id::text,'sha256'),'hex'),1,12)=lower(btrim(p_request_code)) limit 1;
 if v_request is null then raise exception 'permission_request_not_found'; end if;
 perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
 v_result:=public.phms_review_access_request(v_request,v_decision,p_review_note);
 return jsonb_build_object('status',v_result,'request_code',lower(btrim(p_request_code)));
end $function$

CREATE OR REPLACE FUNCTION public.phms_review_line_family_removal_request(p_line_user_id text, p_request_code text, p_decision text, p_review_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_ctx private.line_identity_contexts%rowtype;
  v_req public.permission_requests%rowtype;
  v_decision text:=lower(btrim(coalesce(p_decision,'')));
begin
  if v_decision not in ('approve','reject') then raise exception 'invalid_review_decision'; end if;

  select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
  perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
  select * into v_ctx from private.line_identity_contexts where line_identity_id=v_line.line_identity_id;
  if v_ctx.active_scope<>'family' or v_ctx.active_family_id is null then raise exception 'family_context_required'; end if;

  perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
  if not private.is_family_owner(v_ctx.active_family_id) then raise exception 'owner_required_to_review_removal'; end if;

  select * into v_req
  from public.permission_requests pr
  where pr.family_id=v_ctx.active_family_id
    and pr.request_type='family_removal'
    and pr.status='pending'
    and substr(encode(digest(pr.id::text||':'||v_line.line_identity_id::text,'sha256'),'hex'),1,12)=lower(btrim(p_request_code))
  for update;
  if not found then raise exception 'family_removal_request_not_found'; end if;

  if v_decision='reject' then
    update public.permission_requests
    set status='rejected',reviewed_by=v_line.user_id,reviewed_at=now(),review_note=p_review_note,updated_at=now()
    where id=v_req.id;

    insert into public.audit_logs(
      family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,record_id,new_data,description,created_at
    ) values(
      v_ctx.active_family_id,v_line.user_id,v_req.target_user_id,v_req.family_person_id,
      'family_removal_rejected','family',v_req.id,
      jsonb_build_object('target_kind',v_req.requested_action),
      'Owner rejected family removal request',now()
    );

    return jsonb_build_object('ok',true,'status','rejected');
  end if;

  if v_req.requested_action='member' then
    if v_req.target_user_id is null then raise exception 'removal_target_missing'; end if;
    if private.user_has_family_role(v_req.target_user_id,v_ctx.active_family_id,array['owner']) then raise exception 'cannot_remove_family_owner'; end if;

    update public.family_memberships set status='inactive',updated_at=now()
      where family_id=v_ctx.active_family_id and user_id=v_req.target_user_id and status='active';
    update public.family_role_assignments set status='inactive',updated_at=now()
      where family_id=v_ctx.active_family_id and user_id=v_req.target_user_id and status='active';
    update public.person_caregiver_assignments set status='inactive',updated_at=now()
      where family_id=v_ctx.active_family_id and caregiver_user_id=v_req.target_user_id and status='active';
    update public.person_permissions set status='inactive',updated_at=now()
      where family_id=v_ctx.active_family_id and user_id=v_req.target_user_id and coalesce(status,'active')='active';
    delete from public.family_permissions
      where family_id=v_ctx.active_family_id and user_id=v_req.target_user_id;

  elsif v_req.requested_action='person' then
    if v_req.family_person_id is null then raise exception 'removal_target_missing'; end if;

    update public.family_persons set status='inactive',updated_at=now()
      where id=v_req.family_person_id and family_id=v_ctx.active_family_id;

    update public.person_caregiver_assignments set status='inactive',updated_at=now()
      where family_id=v_ctx.active_family_id and family_person_id=v_req.family_person_id and status='active';

    update public.person_permissions set status='inactive',updated_at=now()
      where family_id=v_ctx.active_family_id and family_person_id=v_req.family_person_id and coalesce(status,'active')='active';

    update private.line_identity_contexts
    set active_family_person_id=null,updated_at=now()
    where active_family_person_id=v_req.family_person_id;
  else
    raise exception 'invalid_removal_target_kind';
  end if;

  update public.permission_requests
  set status='approved',reviewed_by=v_line.user_id,reviewed_at=now(),review_note=p_review_note,updated_at=now()
  where id=v_req.id;

  insert into public.audit_logs(
    family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,record_id,new_data,description,created_at
  ) values(
    v_ctx.active_family_id,v_line.user_id,v_req.target_user_id,v_req.family_person_id,
    'family_removal_approved','family',v_req.id,
    jsonb_build_object('target_kind',v_req.requested_action),
    'Owner approved admin family removal request',now()
  );

  return jsonb_build_object('ok',true,'status','approved','target_kind',v_req.requested_action);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_review_line_person_change(p_line_user_id text, p_request_code text, p_decision text, p_review_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_line record; v_ctx private.line_identity_contexts%rowtype; v_r public.person_change_requests%rowtype;
 v_dec text:=lower(btrim(coalesce(p_decision,''))); v_now timestamptz:=now();
 v_reviewer_name text; v_field_label text;
begin
 if v_dec in ('approve','approved','อนุมัติ') then v_dec:='approved';
 elsif v_dec in ('reject','rejected','ปฏิเสธ') then v_dec:='rejected';
 else raise exception 'invalid_review_decision'; end if;

 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select c.* into v_ctx from private.line_identity_contexts c where c.line_identity_id=v_line.line_identity_id;

 select r.* into v_r
 from public.person_change_requests r
 where r.family_id=v_ctx.active_family_id and r.status='pending'
   and substr(encode(digest(r.id::text||':'||v_line.line_identity_id::text,'sha256'),'hex'),1,12)=lower(btrim(p_request_code))
 limit 1;
 if not found then raise exception 'person_change_request_not_found'; end if;

 perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
 if not private.can_access_family_person(v_r.family_person_id,'persons','update') then
   raise exception 'person_change_review_denied';
 end if;

 if v_dec='approved' then
   if v_r.field_name='nickname' then
     update public.persons set nickname=v_r.requested_value,display_name=null,updated_at=v_now where id=v_r.person_id;
   elsif v_r.field_name='first_name' then
     update public.persons set first_name=v_r.requested_value,display_name=null,updated_at=v_now where id=v_r.person_id;
   elsif v_r.field_name='last_name' then
     update public.persons set last_name=v_r.requested_value,display_name=null,updated_at=v_now where id=v_r.person_id;
   elsif v_r.field_name='date_of_birth' then
     update public.persons set date_of_birth=v_r.requested_value,updated_at=v_now where id=v_r.person_id;
   elsif v_r.field_name='sex' then
     update public.persons set sex=v_r.requested_value,updated_at=v_now where id=v_r.person_id;
   else
     raise exception 'unsupported_person_field';
   end if;
 end if;

 update public.person_change_requests
 set status=v_dec,reviewed_by=v_line.user_id,reviewed_at=v_now,review_note=p_review_note,updated_at=v_now
 where id=v_r.id;

 v_reviewer_name:=private.family_user_label_for_viewer(v_r.requester_user_id,v_r.family_id,v_line.user_id);
 v_field_label:=case v_r.field_name
   when 'nickname' then 'ชื่อเล่นจริง'
   when 'first_name' then 'ชื่อจริง'
   when 'last_name' then 'นามสกุล'
   when 'date_of_birth' then 'วันเกิด'
   when 'sex' then 'เพศ'
   else v_r.field_name end;

 insert into public.notifications(
   family_id,recipient_user_id,event_type,title,message,related_record_id,
   channel,priority,status,person_id,family_person_id,scheduled_for,next_attempt_at,
   payload,dedupe_key,created_at,updated_at
 )
 values(
   v_r.family_id,v_r.requester_user_id,'person_change_reviewed',
   case when v_dec='approved' then '✅ คำขอแก้ข้อมูลได้รับอนุมัติ' else '❌ คำขอแก้ข้อมูลไม่ได้รับอนุมัติ' end,
   v_field_label||': '||coalesce(v_r.requested_value,'ล้างข้อมูล')||
   E'\nผู้พิจารณา: '||v_reviewer_name||
   case when nullif(btrim(coalesce(p_review_note,'')),'') is not null then E'\nหมายเหตุ: '||p_review_note else '' end,
   v_r.id,'line','normal','pending',v_r.person_id,v_r.family_person_id,v_now,v_now,
   jsonb_build_object('field',v_r.field_name,'decision',v_dec),
   'person-change-result:'||v_r.id::text,v_now,v_now
 )
 on conflict(dedupe_key) do nothing;

 return jsonb_build_object('status',v_dec,'field',v_r.field_name,'requested_value',v_r.requested_value);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_review_line_self_viewer_request(p_line_user_id text, p_request_code text, p_decision text, p_review_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_line record;v_ctx private.line_identity_contexts%rowtype;v_req public.permission_requests%rowtype;
 v_decision text:=lower(btrim(coalesce(p_decision,'')));v_res text;v_rec uuid;
 v_person_name text;v_target_name text;v_reviewer_name text;
begin
 if v_decision not in ('approve','approved','reject','rejected') then
   raise exception 'invalid_review_decision';
 end if;
 v_decision:=case when v_decision in ('approve','approved') then 'approved' else 'rejected' end;

 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select * into v_ctx from private.line_identity_contexts where line_identity_id=v_line.line_identity_id;
 if v_ctx.active_scope<>'family' or v_ctx.active_family_id is null then raise exception 'family_context_required'; end if;

 select * into v_req
 from public.permission_requests pr
 where pr.family_id=v_ctx.active_family_id and pr.request_type='self_viewer' and pr.status='pending'
   and substr(encode(digest(pr.id::text||':'||v_line.line_identity_id::text,'sha256'),'hex'),1,12)=lower(btrim(p_request_code))
 for update;
 if not found then raise exception 'self_viewer_request_not_found'; end if;
 if v_req.requester_user_id=v_line.user_id then raise exception 'request_self_review_not_allowed'; end if;
 if not private.can_review_self_viewer_request(v_line.user_id,v_req.family_person_id) then
   raise exception 'self_viewer_reviewer_not_authorized';
 end if;

 if v_decision='rejected' then
  update public.permission_requests
  set status='rejected',reviewed_by=v_line.user_id,reviewed_at=now(),
      review_note=p_review_note,updated_at=now()
  where id=v_req.id;

  insert into public.audit_logs(
   family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,
   record_id,new_data,description,created_at
  ) values(
   v_req.family_id,v_line.user_id,v_req.target_user_id,v_req.family_person_id,
   'self_viewer_rejected','medical_access',v_req.id,
   jsonb_build_object('decision','rejected'),coalesce(p_review_note,'View-only request rejected'),now()
  );
  return jsonb_build_object('ok',true,'status','rejected');
 end if;

 foreach v_res in array array['persons','medications','appointments','health_data','emergency']::text[] loop
  insert into public.person_permissions(
   family_id,family_person_id,user_id,resource,
   can_view,can_create,can_update,can_delete,can_receive_notifications,
   granted_by,status,created_at,updated_at
  ) values(
   v_req.family_id,v_req.family_person_id,v_req.target_user_id,v_res,
   true,false,false,false,false,v_line.user_id,'active',now(),now()
  )
  on conflict(family_id,family_person_id,user_id,resource) do update
  set can_view=true,can_create=false,can_update=false,can_delete=false,
      can_receive_notifications=false,granted_by=v_line.user_id,status='active',updated_at=now();
 end loop;

 update public.permission_requests
 set status='approved',reviewed_by=v_line.user_id,reviewed_at=now(),
     review_note=p_review_note,updated_at=now()
 where id=v_req.id;

 insert into public.audit_logs(
  family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,
  record_id,new_data,description,created_at
 ) values(
  v_req.family_id,v_line.user_id,v_req.target_user_id,v_req.family_person_id,
  'self_viewer_approved','medical_access',v_req.id,
  jsonb_build_object('decision','approved','mode','viewer','all_five_categories',true),
  'Primary health caregiver approved view-only access',now()
 );

 for v_rec in
  select distinct uid from (
   select v_req.target_user_id uid
   union all select v_req.requester_user_id
  ) x where uid is not null
 loop
  v_person_name:=private.family_person_label_for_viewer(v_rec,v_req.family_person_id);
  v_target_name:=private.family_user_label_for_viewer(v_rec,v_req.family_id,v_req.target_user_id);
  v_reviewer_name:=private.family_user_label_for_viewer(v_rec,v_req.family_id,v_line.user_id);

  insert into public.notifications(
   family_id,recipient_user_id,event_type,title,message,related_record_id,
   channel,priority,status,family_person_id,scheduled_for,next_attempt_at,
   payload,dedupe_key,created_at,updated_at
  ) values(
   v_req.family_id,v_rec,'self_viewer_approved',
   '✅ อนุญาตให้ดูข้อมูลแล้ว',
   case
    when v_rec=v_req.target_user_id
      then v_person_name||' อนุญาตให้คุณดูข้อมูลที่กำหนดไว้ โดยแก้ไขไม่ได้'
    else 'อนุมัติแล้ว: '||v_target_name||' ดูข้อมูลของคุณได้'
   end||E'\nผู้อนุมัติ: '||v_reviewer_name,
   v_req.id,'line','normal','pending',v_req.family_person_id,now(),now(),
   jsonb_build_object('request_id',v_req.id,'decision','approved','mode','viewer','all_five_categories',true),
   'self-viewer-approved:'||v_req.id::text||':'||v_rec::text,now(),now()
  )
  on conflict (dedupe_key) where dedupe_key is not null do nothing;
 end loop;

 return jsonb_build_object('ok',true,'status','approved','all_five_categories',true);
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_review_person_claim(p_claim_request_id uuid, p_decision text, p_reason text DEFAULT NULL::text)
 RETURNS TABLE(claim_request_id uuid, person_id uuid, requested_user_id uuid, status text, linked boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_reviewer uuid := auth.uid();
  v_claim public.person_claim_requests%rowtype;
  v_person public.persons%rowtype;
  v_family_person_id uuid;
  v_line public.line_identities%rowtype;
  v_decision text := lower(trim(coalesce(p_decision,'')));
begin
  if v_reviewer is null then
    raise exception 'authentication_required';
  end if;

  if v_decision not in ('approve','reject') then
    raise exception 'invalid_decision';
  end if;

  select * into v_claim
  from public.person_claim_requests
  where id = p_claim_request_id
  for update;

  if not found then
    raise exception 'claim_not_found';
  end if;

  if v_claim.family_id is null then
    raise exception 'family_context_required_for_review';
  end if;

  if not (private.is_family_owner(v_claim.family_id) or private.can_manage_permissions(v_claim.family_id)) then
    raise exception 'claim_review_permission_denied';
  end if;

  if v_claim.status = 'completed' then
    return query select v_claim.id, v_claim.person_id, v_claim.requested_user_id, 'completed'::text, true;
    return;
  end if;

  if v_claim.status in ('rejected','expired','cancelled') then
    raise exception 'claim_not_reviewable';
  end if;

  if v_claim.expires_at is not null and v_claim.expires_at <= now() then
    update public.person_claim_requests
       set status = 'expired', updated_at = now()
     where id = v_claim.id;
    return query select v_claim.id, v_claim.person_id, v_claim.requested_user_id, 'expired'::text, false;
    return;
  end if;

  select fp.id into v_family_person_id
  from public.family_persons fp
  where fp.family_id = v_claim.family_id
    and fp.person_id = v_claim.person_id
  limit 1;

  if v_decision = 'reject' then
    update public.person_claim_requests
       set status = 'rejected',
           rejected_by_user_id = v_reviewer,
           rejected_at = now(),
           updated_at = now(),
           metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('review_reason', p_reason)
     where id = v_claim.id;

    insert into public.audit_logs(
      family_id, actor_user_id, target_user_id, family_person_id,
      event_type, resource, record_id, new_data, description
    ) values (
      v_claim.family_id, v_reviewer, v_claim.requested_user_id, v_family_person_id,
      'person_claim_rejected', 'person_claim', v_claim.id,
      jsonb_build_object('person_id', v_claim.person_id, 'status', 'rejected', 'reason', p_reason),
      'Person claim was rejected by an authorized family reviewer.'
    );

    return query select v_claim.id, v_claim.person_id, v_claim.requested_user_id, 'rejected'::text, false;
    return;
  end if;

  if v_claim.status <> 'person_confirmed' then
    raise exception 'claimant_confirmation_required';
  end if;

  if v_claim.confirmed_by_line_identity_id is null or v_claim.person_confirmed_at is null then
    raise exception 'claimant_confirmation_required';
  end if;

  select * into v_line
  from public.line_identities
  where id = v_claim.confirmed_by_line_identity_id
  for update;

  if not found
     or v_line.user_id is distinct from v_claim.requested_user_id
     or coalesce(v_line.is_active, false) is not true then
    raise exception 'active_confirming_line_identity_required';
  end if;

  if not exists (
    select 1 from public.line_identities li
    where li.user_id = v_claim.requested_user_id and li.is_active = true
  ) then
    raise exception 'claimant_has_no_active_line_identity';
  end if;

  select * into v_person
  from public.persons
  where id = v_claim.person_id
  for update;

  if not found then
    raise exception 'person_not_found';
  end if;

  if v_person.linked_user_id is not null then
    if v_person.linked_user_id = v_claim.requested_user_id then
      update public.person_claim_requests
         set status = 'completed',
             approved_by_user_id = coalesce(approved_by_user_id, v_reviewer),
             approved_at = coalesce(approved_at, now()),
             completed_at = coalesce(completed_at, now()),
             updated_at = now()
       where id = v_claim.id;
      return query select v_claim.id, v_claim.person_id, v_claim.requested_user_id, 'completed'::text, true;
      return;
    end if;
    raise exception 'person_already_linked_to_another_user';
  end if;

  if exists (
    select 1 from public.persons p
    where p.linked_user_id = v_claim.requested_user_id
      and p.id <> v_claim.person_id
  ) then
    raise exception 'claimant_already_has_person';
  end if;

  update public.person_claim_requests
     set status = 'approved',
         approved_by_user_id = v_reviewer,
         approved_at = now(),
         updated_at = now(),
         metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('review_reason', p_reason)
   where id = v_claim.id;

  update public.persons
     set linked_user_id = v_claim.requested_user_id,
         updated_at = now()
   where id = v_claim.person_id
     and linked_user_id is null;

  if not found then
    raise exception 'person_link_conflict';
  end if;

  update public.person_claim_requests
     set status = 'completed',
         completed_at = now(),
         updated_at = now()
   where id = v_claim.id;

  insert into public.audit_logs(
    family_id, actor_user_id, target_user_id, family_person_id,
    event_type, resource, record_id, new_data, description
  ) values (
    v_claim.family_id, v_reviewer, v_claim.requested_user_id, v_family_person_id,
    'person_claim_approved_and_linked', 'person_claim', v_claim.id,
    jsonb_build_object(
      'person_id', v_claim.person_id,
      'requested_user_id', v_claim.requested_user_id,
      'confirmed_by_line_identity_id', v_claim.confirmed_by_line_identity_id,
      'approved_by_user_id', v_reviewer,
      'status', 'completed'
    ),
    'Authorized family reviewer approved the confirmed claim and linked the existing person to the claimant account.'
  );

  return query select v_claim.id, v_claim.person_id, v_claim.requested_user_id, 'completed'::text, true;
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_review_person_claim_from_line(p_line_user_id text, p_review_code text, p_decision text, p_reason text DEFAULT NULL::text)
 RETURNS TABLE(claim_request_id uuid, requested_user_id uuid, person_id uuid, status text, linked boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line public.line_identities%rowtype;
  v_claim public.person_claim_requests%rowtype;
  v_person public.persons%rowtype;
  v_confirming_line public.line_identities%rowtype;
  v_family_person_id uuid;
  v_decision text := lower(btrim(coalesce(p_decision,'')));
begin
  if p_line_user_id is null or btrim(p_line_user_id) = '' then raise exception 'line_user_id_required'; end if;
  if p_review_code is null or btrim(p_review_code) = '' then raise exception 'review_code_required'; end if;
  if v_decision not in ('approve','reject') then raise exception 'invalid_decision'; end if;

  select * into v_line
  from public.line_identities
  where line_user_id = p_line_user_id
  for update;

  if not found then raise exception 'line_identity_not_found'; end if;
  if coalesce(v_line.is_active,false) is not true then raise exception 'active_line_identity_required'; end if;
  if v_line.user_id is null then raise exception 'line_identity_not_linked'; end if;

  select pcr.* into v_claim
  from public.person_claim_requests pcr
  where pcr.family_id is not null
    and substr(encode(digest(pcr.id::text || ':' || v_line.id::text || ':' || pcr.family_id::text, 'sha256'),'hex'),1,12) = lower(btrim(p_review_code))
  order by pcr.created_at desc
  limit 1
  for update;

  if not found then raise exception 'review_request_not_found'; end if;

  if not private.user_has_family_role(v_line.user_id,v_claim.family_id,array['owner','admin']) then
    raise exception 'claim_review_permission_denied';
  end if;

  if v_claim.status in ('completed','rejected','expired','cancelled') then
    raise exception 'claim_not_reviewable';
  end if;

  if v_claim.expires_at is not null and v_claim.expires_at <= now() then
    update public.person_claim_requests
    set status='expired', expired_at=coalesce(expired_at,now()), updated_at=now()
    where id=v_claim.id;
    return query select v_claim.id, v_claim.requested_user_id, v_claim.person_id, 'expired'::text, false;
    return;
  end if;

  if v_claim.status <> 'person_confirmed' or v_claim.person_confirmed_at is null or v_claim.confirmed_by_line_identity_id is null then
    raise exception 'claimant_confirmation_required';
  end if;

  select * into v_confirming_line
  from public.line_identities
  where id=v_claim.confirmed_by_line_identity_id
  for update;

  if not found
     or v_confirming_line.user_id is distinct from v_claim.requested_user_id
     or coalesce(v_confirming_line.is_active,false) is not true then
    raise exception 'active_confirming_line_identity_required';
  end if;

  if not exists (
    select 1 from public.line_identities li
    where li.user_id=v_claim.requested_user_id and li.is_active=true
  ) then
    raise exception 'claimant_has_no_active_line_identity';
  end if;

  select fp.id into v_family_person_id
  from public.family_persons fp
  where fp.family_id=v_claim.family_id and fp.person_id=v_claim.person_id
  limit 1;

  if v_decision='reject' then
    update public.person_claim_requests
    set status='rejected',
        rejected_by_user_id=v_line.user_id,
        rejected_at=now(),
        updated_at=now(),
        metadata=coalesce(metadata,'{}'::jsonb) || jsonb_build_object('review_reason',p_reason,'review_source','line_webhook')
    where id=v_claim.id;

    insert into public.audit_logs(
      family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,record_id,new_data,description
    ) values (
      v_claim.family_id,v_line.user_id,v_claim.requested_user_id,v_family_person_id,
      'person_claim_rejected','person_claim',v_claim.id,
      jsonb_build_object('person_id',v_claim.person_id,'status','rejected','reason',p_reason,'source','line_webhook'),
      'Person claim was rejected by an authorized family reviewer from LINE.'
    );

    return query select v_claim.id,v_claim.requested_user_id,v_claim.person_id,'rejected'::text,false;
    return;
  end if;

  select * into v_person
  from public.persons
  where id=v_claim.person_id
  for update;

  if not found then raise exception 'person_not_found'; end if;

  if v_person.linked_user_id is not null then
    if v_person.linked_user_id=v_claim.requested_user_id then
      update public.person_claim_requests
      set status='completed',
          approved_by_user_id=coalesce(approved_by_user_id,v_line.user_id),
          approved_at=coalesce(approved_at,now()),
          completed_at=coalesce(completed_at,now()),
          updated_at=now()
      where id=v_claim.id;
      return query select v_claim.id,v_claim.requested_user_id,v_claim.person_id,'completed'::text,true;
      return;
    end if;
    raise exception 'person_already_linked_to_another_user';
  end if;

  if exists (
    select 1 from public.persons p
    where p.linked_user_id=v_claim.requested_user_id and p.id<>v_claim.person_id
  ) then
    raise exception 'claimant_already_has_person';
  end if;

  update public.person_claim_requests
  set status='approved',
      approved_by_user_id=v_line.user_id,
      approved_at=now(),
      updated_at=now(),
      metadata=coalesce(metadata,'{}'::jsonb) || jsonb_build_object('review_reason',p_reason,'review_source','line_webhook')
  where id=v_claim.id;

  update public.persons
  set linked_user_id=v_claim.requested_user_id, updated_at=now()
  where id=v_claim.person_id and linked_user_id is null;

  if not found then raise exception 'person_link_conflict'; end if;

  update public.person_claim_requests
  set status='completed', completed_at=now(), updated_at=now()
  where id=v_claim.id;

  insert into public.audit_logs(
    family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,record_id,new_data,description
  ) values (
    v_claim.family_id,v_line.user_id,v_claim.requested_user_id,v_family_person_id,
    'person_claim_approved_and_linked','person_claim',v_claim.id,
    jsonb_build_object(
      'person_id',v_claim.person_id,
      'requested_user_id',v_claim.requested_user_id,
      'confirmed_by_line_identity_id',v_claim.confirmed_by_line_identity_id,
      'approved_by_user_id',v_line.user_id,
      'status','completed',
      'source','line_webhook'
    ),
    'Authorized family reviewer approved the confirmed claim from LINE and linked the person to the claimant.'
  );

  return query select v_claim.id,v_claim.requested_user_id,v_claim.person_id,'completed'::text,true;
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_revoke_role(p_family_id uuid, p_target_user_id uuid, p_role text, p_reason text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid;
  v_owner_count integer;
begin

  v_actor := auth.uid();

  if v_actor is null then
    raise exception 'Authentication required';
  end if;

  -- Owner role cannot be revoked through generic revoke
  if p_role = 'owner' then
    raise exception 'Owner role must be changed through owner transfer';
  end if;

  if not private.can_manage_permissions(p_family_id) then
    raise exception 'Insufficient permission';
  end if;

  -- Admin role can only be revoked by Owner
  if p_role = 'admin'
     and not private.is_family_owner(p_family_id)
  then
    raise exception 'Only owner can revoke admin role';
  end if;

  update public.family_role_assignments
  set
    status = 'inactive',
    updated_at = now()
  where family_id = p_family_id
    and user_id = p_target_user_id
    and role = p_role
    and status = 'active';

  if not found then
    raise exception 'Active role assignment not found';
  end if;

  insert into public.audit_logs (
    family_id,
    actor_user_id,
    target_user_id,
    event_type,
    resource,
    old_data,
    description,
    created_at
  )
  values (
    p_family_id,
    v_actor,
    p_target_user_id,
    'role_revoked',
    'roles',
    jsonb_build_object('role', p_role),
    coalesce(p_reason, 'Role revoked'),
    now()
  );

  perform private.notify_family_owners(
    p_family_id,
    'role_revoked',
    'มีการถอนบทบาท',
    'มีการถอน Role ของสมาชิกในครอบครัว',
    null,
    null
  );

  return 'role_revoked';

end;
$function$

CREATE OR REPLACE FUNCTION public.phms_secondary_line_invite_approve(p_line_user_id text, p_invite_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions'
AS $function$
declare v record; inv record; receiver record; acc uuid;
begin
 select * into v from private.resolve_line_user_for_service(p_line_user_id);
 select * into inv from public.phms_line_secondary_invites where id=p_invite_id for update;
 if inv.id is null or inv.primary_user_id<>v.user_id or inv.status<>'claimed' or inv.expires_at<now() then raise exception 'not_authorized_or_expired'; end if;
 select * into receiver from public.line_identities where id=inv.recipient_line_identity_id for update;
 if receiver.id is null or receiver.is_active is not true then raise exception 'recipient_unavailable'; end if;
 if receiver.user_id is not null or receiver.account_id is not null then
   raise exception 'recipient_already_has_phms_account_use_delegated_access';
 end if;
 select account_id into acc from public.line_identities where id=v.line_identity_id;
 if acc is null then raise exception 'primary_account_missing'; end if;
 update public.line_identities set user_id=v.user_id,account_id=acc,linking_completed_at=now(),onboarding_status='completed',updated_at=now()
 where id=receiver.id and user_id is null and account_id is null;
 if not found then raise exception 'recipient_link_conflict'; end if;
 perform private.ensure_line_identity_context(receiver.id,v.user_id);
 update public.phms_line_secondary_invites set status='approved',approved_at=now() where id=inv.id;
 return jsonb_build_object('status','approved','person_id',inv.person_id);
end $function$

CREATE OR REPLACE FUNCTION public.phms_secondary_line_invite_claim(p_line_user_id text, p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions'
AS $function$
declare li record; inv record;
begin
 select * into li from public.line_identities where line_user_id=p_line_user_id and is_active=true for update;
 if li.id is null then raise exception 'line_identity_not_found'; end if;
 select * into inv from public.phms_line_secondary_invites where token_hash=encode(digest(p_token,'sha256'),'hex') for update;
 if inv.id is null or inv.status<>'pending' or inv.expires_at<=now() then raise exception 'invalid_or_expired_invitation'; end if;
 if li.user_id=inv.primary_user_id then raise exception 'already_primary_line'; end if;
 update public.phms_line_secondary_invites set recipient_line_identity_id=li.id,status='claimed',claimed_at=now() where id=inv.id;
 return jsonb_build_object('status','claimed','requires_primary_confirmation',true);
end $function$

CREATE OR REPLACE FUNCTION public.phms_secondary_line_invite_pending(p_line_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions'
AS $function$
declare v record;
begin
 select * into v from private.resolve_line_user_for_service(p_line_user_id);
 return coalesce((select jsonb_agg(jsonb_build_object('code',i.id,'person',coalesce(p.display_name,p.first_name),'created_at',i.created_at))
 from public.phms_line_secondary_invites i join public.persons p on p.id=i.person_id where i.primary_user_id=v.user_id and i.status='claimed' and i.expires_at>now()),'[]'::jsonb);
end $function$

CREATE OR REPLACE FUNCTION public.phms_secondary_line_invite_start(p_line_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions'
AS $function$
declare v record; ctx record; per record; tok text;
begin
 select * into v from private.resolve_line_user_for_service(p_line_user_id);
 select * into ctx from private.line_identity_contexts where line_identity_id=v.line_identity_id;
 if ctx.active_family_id is null or ctx.active_family_person_id is null then raise exception 'select_person_first'; end if;
 perform set_config('request.jwt.claim.sub',v.user_id::text,true);
 if not private.can_manage_permissions(ctx.active_family_id) then raise exception 'permission_denied'; end if;
 select p.id,p.linked_user_id into per from public.persons p join public.family_persons fp on fp.person_id=p.id where fp.id=ctx.active_family_person_id and fp.family_id=ctx.active_family_id and fp.status='active';
 if per.id is null or per.linked_user_id is null then raise exception 'person_must_have_primary_line'; end if;
 tok:=encode(gen_random_bytes(24),'hex');
 update public.phms_line_secondary_invites set status='revoked' where person_id=per.id and status='pending';
 insert into public.phms_line_secondary_invites(family_id,person_id,primary_user_id,invited_by_user_id,token_hash)
 values(ctx.active_family_id,per.id,per.linked_user_id,v.user_id,encode(digest(tok,'sha256'),'hex'));
 return jsonb_build_object('token',tok,'expires_in_hours',24,'state','pending');
end $function$

CREATE OR REPLACE FUNCTION public.phms_select_family_person_context(p_family_person_id uuid)
 RETURNS TABLE(user_id uuid, active_scope text, active_family_id uuid, active_family_person_id uuid, person_id uuid, person_display_name text, relationship_label text, person_status text, family_person_status text, context_ready boolean, context_changed_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_family_id uuid;
  v_person_id uuid;
  v_display_name text;
  v_relationship_label text;
  v_person_status text;
  v_fp_status text;
begin
  if v_uid is null then
    raise exception 'authentication_required';
  end if;
  if p_family_person_id is null then
    raise exception 'family_person_id_required';
  end if;

  select uc.active_family_id
    into v_family_id
    from public.user_contexts uc
   where uc.user_id = v_uid
     and uc.active_scope = 'family'
   limit 1;

  if v_family_id is null then
    raise exception 'family_context_required';
  end if;

  if not exists (
    select 1
      from public.family_memberships fm
      join public.families f on f.id = fm.family_id
     where fm.user_id = v_uid
       and fm.family_id = v_family_id
       and fm.status = 'active'
       and f.status = 'active'
  ) then
    raise exception 'family_context_not_accessible';
  end if;

  select fp.person_id,
         p.display_name,
         fp.relationship_label,
         p.status,
         fp.status
    into v_person_id,
         v_display_name,
         v_relationship_label,
         v_person_status,
         v_fp_status
    from public.family_persons fp
    join public.persons p on p.id = fp.person_id
   where fp.id = p_family_person_id
     and fp.family_id = v_family_id
   limit 1;

  if not found then
    raise exception 'family_person_not_in_active_family';
  end if;
  if coalesce(v_fp_status,'') <> 'active' then
    raise exception 'family_person_inactive';
  end if;
  if coalesce(v_person_status,'') <> 'active' then
    raise exception 'person_inactive';
  end if;

  update public.user_contexts uc
     set active_family_person_id = p_family_person_id,
         context_changed_at = case
           when uc.active_family_person_id is distinct from p_family_person_id then now()
           else uc.context_changed_at
         end,
         updated_at = now()
   where uc.user_id = v_uid
     and uc.active_scope = 'family'
     and uc.active_family_id = v_family_id;

  return query
  select uc.user_id,
         uc.active_scope,
         uc.active_family_id,
         uc.active_family_person_id,
         v_person_id,
         v_display_name,
         v_relationship_label,
         v_person_status,
         v_fp_status,
         true,
         uc.context_changed_at
    from public.user_contexts uc
   where uc.user_id = v_uid;
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_select_line_context_family(p_line_user_id text, p_selection_code text)
 RETURNS TABLE(user_id uuid, active_scope text, active_family_id uuid, active_family_person_id uuid, family_name text, context_ready boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare v_line public.line_identities%rowtype; v_family public.families%rowtype;
begin
 select * into v_line from public.line_identities where line_user_id=p_line_user_id and is_active=true order by updated_at desc nulls last,created_at desc limit 1;
 if not found then raise exception 'line_identity_not_found'; end if;
 if v_line.user_id is null then raise exception 'line_identity_not_linked'; end if;
 select f.* into v_family
 from public.family_memberships fm join public.families f on f.id=fm.family_id
 where fm.user_id=v_line.user_id and fm.status='active' and coalesce(f.status,'active')='active'
   and substr(encode(digest(f.id::text||':'||v_line.id::text,'sha256'),'hex'),1,12)=lower(btrim(p_selection_code))
 limit 1;
 if not found then raise exception 'family_selection_not_found_or_not_accessible'; end if;
 perform private.ensure_line_identity_context(v_line.id,v_line.user_id);
 update private.line_identity_contexts c
 set active_scope='family',active_family_id=v_family.id,active_family_person_id=null,
     context_changed_at=case when c.active_scope is distinct from 'family' or c.active_family_id is distinct from v_family.id or c.active_family_person_id is not null then now() else c.context_changed_at end,
     updated_at=now()
 where c.line_identity_id=v_line.id;
 return query select v_line.user_id,'family'::text,v_family.id,null::uuid,v_family.family_name,true;
end $function$

CREATE OR REPLACE FUNCTION public.phms_select_line_context_person(p_line_user_id text, p_selection_code text)
 RETURNS TABLE(user_id uuid, active_scope text, active_family_id uuid, active_family_person_id uuid, person_id uuid, person_display_name text, relationship_label text, context_ready boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_ref record;
 v_ctx private.line_identity_contexts%rowtype;
 v_person public.persons%rowtype;
 v_relationship text;
begin
 select * into v_ref
 from private.resolve_line_family_person_code(p_line_user_id,p_selection_code)
 limit 1;

 perform private.ensure_line_identity_context(v_ref.line_identity_id,v_ref.actor_user_id);
 select * into v_ctx
 from private.line_identity_contexts
 where line_identity_id=v_ref.line_identity_id
 for update;

 if not private.user_can_see_family_person(v_ref.actor_user_id,v_ref.family_person_id) then
   raise exception 'person_selection_not_accessible';
 end if;

 select p.* into v_person
 from public.family_persons fp
 join public.persons p on p.id=fp.person_id
 where fp.id=v_ref.family_person_id
   and fp.family_id=v_ref.family_id
   and coalesce(fp.status,'active')='active'
   and coalesce(p.status,'active')='active'
 limit 1;
 if not found then raise exception 'person_inactive_or_missing'; end if;

 update private.line_identity_contexts c
 set active_family_person_id=v_ref.family_person_id,
     context_changed_at=case when c.active_family_person_id is distinct from v_ref.family_person_id then now() else c.context_changed_at end,
     updated_at=now()
 where c.line_identity_id=v_ref.line_identity_id;

 insert into public.person_context_usage(user_id,family_person_id,use_count,first_used_at,last_used_at)
 values(v_ref.actor_user_id,v_ref.family_person_id,1,now(),now())
 on conflict on constraint person_context_usage_pkey do update
 set use_count=public.person_context_usage.use_count+1,last_used_at=now();

 if v_person.linked_user_id=v_ref.actor_user_id then
   v_relationship:='ฉัน';
 else
   select nullif(btrim(v.relationship_label),'') into v_relationship
   from public.family_person_view_labels v
   where v.viewer_user_id=v_ref.actor_user_id and v.family_person_id=v_ref.family_person_id;
 end if;

 return query
 select v_ref.actor_user_id,'family'::text,v_ref.family_id,v_ref.family_person_id,v_person.id,
        private.family_person_label_for_viewer(v_ref.actor_user_id,v_ref.family_person_id),
        v_relationship,true;
end
$function$

CREATE OR REPLACE FUNCTION public.phms_set_line_active_family_person_label(p_line_user_id text, p_field text, p_value text DEFAULT NULL::text)
 RETURNS TABLE(family_id uuid, family_person_id uuid, canonical_person_name text, relationship_label text, display_label text, resolved_label text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line public.line_identities%rowtype;
  v_ctx private.line_identity_contexts%rowtype;
  v_fp public.family_persons%rowtype;
  v_person public.persons%rowtype;
  v_existing public.family_person_view_labels%rowtype;
  v_field text := lower(coalesce(nullif(btrim(p_field),''),''));
  v_value text := nullif(btrim(p_value),'');
  v_relationship text;
  v_display text;
begin
  if v_field not in ('relationship','display') then raise exception 'unsupported_label_field'; end if;
  if p_line_user_id is null or btrim(p_line_user_id)='' then raise exception 'line_user_id_required'; end if;
  if v_value is not null and char_length(v_value)>80 then raise exception 'label_too_long'; end if;

  select li.* into v_line
  from public.line_identities li
  where li.line_user_id=p_line_user_id
  limit 1;
  if not found then raise exception 'line_identity_not_found'; end if;
  if coalesce(v_line.is_active,false) is not true then raise exception 'active_line_identity_required'; end if;
  if v_line.user_id is null then raise exception 'line_identity_not_linked'; end if;

  perform private.ensure_line_identity_context(v_line.id,v_line.user_id);
  select c.* into v_ctx from private.line_identity_contexts c where c.line_identity_id=v_line.id for update;
  if not found or v_ctx.active_scope<>'family' or v_ctx.active_family_id is null then raise exception 'family_context_required'; end if;
  if v_ctx.active_family_person_id is null then raise exception 'family_person_context_required'; end if;

  if not exists(
    select 1 from public.family_memberships fm
    where fm.user_id=v_line.user_id and fm.family_id=v_ctx.active_family_id and fm.status='active'
  ) then raise exception 'family_context_not_accessible'; end if;

  select fp.* into v_fp from public.family_persons fp
  where fp.id=v_ctx.active_family_person_id
    and fp.family_id=v_ctx.active_family_id
    and coalesce(fp.status,'active')='active';
  if not found then raise exception 'family_person_not_accessible'; end if;

  select p.* into v_person from public.persons p
  where p.id=v_fp.person_id and coalesce(p.status,'active')='active';
  if not found then raise exception 'person_inactive_or_missing'; end if;

  select x.* into v_existing
  from public.family_person_view_labels x
  where x.viewer_user_id=v_line.user_id and x.family_person_id=v_fp.id;

  v_relationship := v_existing.relationship_label;
  v_display := v_existing.display_label;
  if v_field='relationship' then v_relationship:=v_value; else v_display:=v_value; end if;

  if v_relationship is null and v_display is null then
    delete from public.family_person_view_labels x
    where x.viewer_user_id=v_line.user_id and x.family_person_id=v_fp.id;
  else
    insert into public.family_person_view_labels(
      viewer_user_id,family_id,family_person_id,relationship_label,display_label,updated_at
    ) values(
      v_line.user_id,v_ctx.active_family_id,v_fp.id,v_relationship,v_display,now()
    )
    on conflict on constraint family_person_view_labels_one_per_viewer do update
      set family_id=excluded.family_id,
          relationship_label=excluded.relationship_label,
          display_label=excluded.display_label,
          updated_at=now();
  end if;

  return query select
    v_ctx.active_family_id,
    v_fp.id,
    coalesce(nullif(btrim(v_person.nickname),''),nullif(btrim(concat_ws(' ',v_person.first_name,v_person.last_name)),''),'ไม่ระบุชื่อ'),
    v_relationship,
    v_display,
    private.family_person_label_for_viewer(v_line.user_id,v_fp.id);
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_set_line_active_family_person_relationship(p_line_user_id text, p_relationship_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_line public.line_identities%rowtype;
 v_ctx private.line_identity_contexts%rowtype;
 v_fp public.family_persons%rowtype;
 v_rel text:=nullif(btrim(coalesce(p_relationship_label,'')),'');
begin
 if v_rel is not null and length(v_rel)>80 then raise exception 'relationship_label_too_long'; end if;

 select * into v_line from public.line_identities
 where line_user_id=p_line_user_id and is_active=true and onboarding_status='ready' and user_id is not null
 order by updated_at desc nulls last,created_at desc limit 1;
 if not found then raise exception 'line_identity_not_ready'; end if;

 perform private.ensure_line_identity_context(v_line.id,v_line.user_id);
 select c.* into v_ctx from private.line_identity_contexts c
 where c.line_identity_id=v_line.id for update;
 if not found or v_ctx.active_scope<>'family'
    or v_ctx.active_family_id is null or v_ctx.active_family_person_id is null
 then raise exception 'family_person_context_required'; end if;

 if not exists(
   select 1 from public.family_memberships fm
   where fm.family_id=v_ctx.active_family_id and fm.user_id=v_line.user_id and fm.status='active'
 ) then raise exception 'family_context_not_accessible'; end if;

 select * into v_fp from public.family_persons
 where id=v_ctx.active_family_person_id and family_id=v_ctx.active_family_id
   and coalesce(status,'active')='active';
 if not found then raise exception 'family_person_not_accessible'; end if;

 insert into public.family_person_view_labels(
   viewer_user_id,family_id,family_person_id,relationship_label,updated_at
 )
 values(v_line.user_id,v_ctx.active_family_id,v_fp.id,v_rel,now())
 on conflict(viewer_user_id,family_person_id) do update
 set family_id=excluded.family_id,
     relationship_label=excluded.relationship_label,
     updated_at=now();

 if v_rel is null then
   update public.family_person_view_labels
   set relationship_label=null,updated_at=now()
   where viewer_user_id=v_line.user_id and family_person_id=v_fp.id;
   delete from public.family_person_view_labels
   where viewer_user_id=v_line.user_id and family_person_id=v_fp.id
     and display_label is null and relationship_label is null;
 end if;

 return jsonb_build_object(
   'ok',true,'family_person_id',v_fp.id,'person_id',v_fp.person_id,
   'relationship_label',case
     when exists(select 1 from public.persons p where p.id=v_fp.person_id and p.linked_user_id=v_line.user_id)
       then 'ฉัน'
     else v_rel
   end,
   'resolved_label',private.family_person_label_for_viewer(v_line.user_id,v_fp.id)
 );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_set_line_active_person_notification_preference(p_line_user_id text, p_enabled boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_line record;
  v_ctx private.line_identity_contexts%rowtype;
  v_fp public.family_persons%rowtype;
  v_res text;
  v_count int:=0;
begin
  select * into v_line
  from private.resolve_line_user_for_service(p_line_user_id);

  perform private.ensure_line_identity_context(
    v_line.line_identity_id,v_line.user_id
  );

  select * into v_ctx
  from private.line_identity_contexts
  where line_identity_id=v_line.line_identity_id;

  if v_ctx.active_scope<>'family'
     or v_ctx.active_family_person_id is null then
    raise exception 'family_person_context_required';
  end if;

  select * into v_fp
  from public.family_persons
  where id=v_ctx.active_family_person_id
    and family_id=v_ctx.active_family_id
    and coalesce(status,'active')='active';

  foreach v_res in array array[
    'medications','appointments','health_data'
  ]::text[] loop
    if private.user_can_access_family_person(
      v_line.user_id,v_fp.id,v_res,'view'
    ) then
      insert into public.person_notification_preferences(
        family_id,family_person_id,user_id,resource,
        enabled,set_by,created_at,updated_at
      ) values(
        v_fp.family_id,v_fp.id,v_line.user_id,v_res,
        p_enabled,v_line.user_id,now(),now()
      )
      on conflict(family_person_id,user_id,resource)
      do update set
        enabled=excluded.enabled,
        set_by=excluded.set_by,
        updated_at=now();
      v_count:=v_count+1;
    end if;
  end loop;

  if v_count=0 then raise exception 'person_view_required'; end if;

  return jsonb_build_object(
    'status','ok',
    'enabled',p_enabled,
    'resource_count',v_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_set_line_family_permission(p_line_user_id text, p_member_code text, p_resource text, p_action text, p_enabled boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare v record; v_resource text:=lower(btrim(coalesce(p_resource,''))); v_action text:=lower(btrim(coalesce(p_action,'')));
begin
 if v_resource in ('persons','profile','appointments','medications','health','health_data','emergency') then
   raise exception 'medical_permissions_are_person_scoped';
 end if;
 if v_resource not in ('members','visibility','line_groups','roles','permissions') then
   raise exception 'unsupported_household_permission_resource';
 end if;
 if v_action not in ('view','create','update','delete','manage_permissions') then
   raise exception 'unsupported_permission_action';
 end if;
 select * into v from private.resolve_line_family_member(p_line_user_id,p_member_code);
 perform set_config('request.jwt.claim.sub',v.actor_user_id::text,true);
 if not private.can_manage_permissions(v.family_id) then raise exception 'household_permission_management_denied'; end if;
 return jsonb_build_object('status','ok','scope','household','resource',v_resource,'action',v_action,
   'enabled',p_enabled,'note','household_capabilities_are_derived_from_household_role');
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_set_line_family_person_view_label_by_code(p_line_user_id text, p_person_code text, p_field text, p_value text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v record; v_p public.persons%rowtype; v_existing public.family_person_view_labels%rowtype;
 v_field text:=lower(btrim(coalesce(p_field,'')));
 v_value text:=nullif(btrim(coalesce(p_value,'')),'');
 v_display text; v_relationship text;
begin
 if v_field not in ('display','relationship') then raise exception 'unsupported_label_field'; end if;
 if v_value is not null and char_length(v_value)>80 then raise exception 'label_too_long'; end if;

 select * into v from private.resolve_line_family_person_code(p_line_user_id,p_person_code);
 select p.* into v_p
 from public.family_persons fp join public.persons p on p.id=fp.person_id
 where fp.id=v.family_person_id;

 if v_p.linked_user_id=v.actor_user_id and v_field='relationship' then
   raise exception 'self_relationship_is_fixed';
 end if;

 select x.* into v_existing
 from public.family_person_view_labels x
 where x.viewer_user_id=v.actor_user_id and x.family_person_id=v.family_person_id;

 v_display:=v_existing.display_label;
 v_relationship:=v_existing.relationship_label;
 if v_field='display' then v_display:=v_value; else v_relationship:=v_value; end if;

 if v_display is null and v_relationship is null then
   delete from public.family_person_view_labels x
   where x.viewer_user_id=v.actor_user_id and x.family_person_id=v.family_person_id;
 else
   insert into public.family_person_view_labels(
     viewer_user_id,family_id,family_person_id,display_label,relationship_label,updated_at
   ) values(
     v.actor_user_id,v.family_id,v.family_person_id,v_display,v_relationship,now()
   )
   on conflict(viewer_user_id,family_person_id) do update
   set family_id=excluded.family_id,
       display_label=excluded.display_label,
       relationship_label=excluded.relationship_label,
       updated_at=now();
 end if;

 return jsonb_build_object(
   'status','ok',
   'person_code',lower(btrim(p_person_code)),
   'display_label',v_display,
   'relationship_label',v_relationship,
   'resolved_label',private.family_person_label_for_viewer(v.actor_user_id,v.family_person_id)
 );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_set_line_family_person_view_preference(p_line_user_id text, p_person_code text, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_action text:=lower(btrim(coalesce(p_action,'')));
  v_rank integer;
  v_neighbor record;
  v_current integer;
begin
  select * into v_ref
  from private.resolve_line_family_person_code(p_line_user_id,p_person_code)
  limit 1;

  if v_action not in ('pin','unpin','up','down','reset') then
    raise exception 'invalid_person_view_preference_action';
  end if;

  if v_action='pin' then
    select coalesce(max(sort_rank),0)+10 into v_rank
    from private.family_person_view_preferences
    where viewer_user_id=v_ref.actor_user_id and pinned=true;
    insert into private.family_person_view_preferences(viewer_user_id,family_person_id,pinned,sort_rank,created_at,updated_at)
    values(v_ref.actor_user_id,v_ref.family_person_id,true,v_rank,now(),now())
    on conflict(viewer_user_id,family_person_id) do update
      set pinned=true,
          sort_rank=coalesce(private.family_person_view_preferences.sort_rank,excluded.sort_rank),
          updated_at=now();

  elsif v_action='unpin' then
    insert into private.family_person_view_preferences(viewer_user_id,family_person_id,pinned,sort_rank,created_at,updated_at)
    values(v_ref.actor_user_id,v_ref.family_person_id,false,null,now(),now())
    on conflict(viewer_user_id,family_person_id) do update
      set pinned=false,sort_rank=null,updated_at=now();

  elsif v_action='reset' then
    delete from private.family_person_view_preferences
    where viewer_user_id=v_ref.actor_user_id and family_person_id=v_ref.family_person_id;

  else
    select sort_rank into v_current
    from private.family_person_view_preferences
    where viewer_user_id=v_ref.actor_user_id
      and family_person_id=v_ref.family_person_id
      and pinned=true;

    if v_current is null then
      select coalesce(max(sort_rank),0)+10 into v_current
      from private.family_person_view_preferences
      where viewer_user_id=v_ref.actor_user_id and pinned=true;
      insert into private.family_person_view_preferences(viewer_user_id,family_person_id,pinned,sort_rank,created_at,updated_at)
      values(v_ref.actor_user_id,v_ref.family_person_id,true,v_current,now(),now())
      on conflict(viewer_user_id,family_person_id) do update
        set pinned=true,sort_rank=excluded.sort_rank,updated_at=now();
    end if;

    if v_action='up' then
      select family_person_id,sort_rank into v_neighbor
      from private.family_person_view_preferences
      where viewer_user_id=v_ref.actor_user_id and pinned=true
        and sort_rank < v_current
      order by sort_rank desc
      limit 1;
    else
      select family_person_id,sort_rank into v_neighbor
      from private.family_person_view_preferences
      where viewer_user_id=v_ref.actor_user_id and pinned=true
        and sort_rank > v_current
      order by sort_rank asc
      limit 1;
    end if;

    if v_neighbor.family_person_id is not null then
      update private.family_person_view_preferences
      set sort_rank=case
        when family_person_id=v_ref.family_person_id then v_neighbor.sort_rank
        when family_person_id=v_neighbor.family_person_id then v_current
        else sort_rank end,
        updated_at=now()
      where viewer_user_id=v_ref.actor_user_id
        and family_person_id in (v_ref.family_person_id,v_neighbor.family_person_id);
    end if;
  end if;

  return jsonb_build_object(
    'ok',true,
    'person_code',lower(btrim(p_person_code)),
    'action',v_action,
    'preference',(
      select jsonb_build_object('pinned',coalesce(p.pinned,false),'sort_rank',p.sort_rank)
      from private.family_person_view_preferences p
      where p.viewer_user_id=v_ref.actor_user_id and p.family_person_id=v_ref.family_person_id
    )
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_set_line_family_person_visibility(p_line_user_id text, p_person_code text, p_member_code text, p_visible boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_ref record;
  v_member record;
  v_person public.persons%rowtype;
begin
  select * into v_ref
  from private.resolve_line_family_person_code(p_line_user_id,p_person_code)
  limit 1;

  select * into v_member
  from private.resolve_line_family_member(p_line_user_id,p_member_code)
  limit 1;

  if v_ref.family_id<>v_member.family_id then
    raise exception 'family_scope_mismatch';
  end if;

  if not private.can_manage_family_person_visibility(v_ref.actor_user_id,v_ref.family_person_id) then
    raise exception 'visibility_management_denied';
  end if;

  select p.* into v_person
  from public.family_persons fp
  join public.persons p on p.id=fp.person_id
  where fp.id=v_ref.family_person_id;

  if coalesce(p_visible,true)=false
     and v_person.linked_user_id=v_member.target_user_id then
    raise exception 'cannot_hide_person_from_self';
  end if;

  if coalesce(p_visible,true)=false
     and (
       exists(
         select 1
         from public.person_permissions pp
         where pp.family_person_id=v_ref.family_person_id
           and pp.user_id=v_member.target_user_id
           and pp.status='active'
           and (
             coalesce(pp.can_view,false)
             or coalesce(pp.can_create,false)
             or coalesce(pp.can_update,false)
             or coalesce(pp.can_delete,false)
           )
       )
       or exists(
         select 1
         from public.person_caregiver_assignments ca
         where ca.family_person_id=v_ref.family_person_id
           and ca.caregiver_user_id=v_member.target_user_id
           and ca.status='active'
       )
     ) then
    raise exception 'cannot_hide_member_with_person_access';
  end if;

  if coalesce(p_visible,true) then
    delete from private.family_person_visibility_overrides
    where family_person_id=v_ref.family_person_id
      and viewer_user_id=v_member.target_user_id;
  else
    insert into private.family_person_visibility_overrides(
      family_id,family_person_id,viewer_user_id,is_visible,configured_by,created_at,updated_at
    )
    values(
      v_ref.family_id,v_ref.family_person_id,v_member.target_user_id,false,v_ref.actor_user_id,now(),now()
    )
    on conflict(family_person_id,viewer_user_id) do update
    set is_visible=false,
        configured_by=excluded.configured_by,
        updated_at=now();
  end if;

  insert into public.audit_logs(
    family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,new_data,description,created_at
  )
  values(
    v_ref.family_id,v_ref.actor_user_id,v_member.target_user_id,v_ref.family_person_id,
    'family_person_visibility_updated','persons',
    jsonb_build_object('visible',coalesce(p_visible,true),'source','line'),
    'Updated whether a family member can discover this person',now()
  );

  return jsonb_build_object(
    'status','ok',
    'person_code',lower(btrim(p_person_code)),
    'member_code',lower(btrim(p_member_code)),
    'visible',coalesce(p_visible,true)
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_set_line_family_role(p_line_user_id text, p_member_code text, p_role text, p_enabled boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v record; v_role text:=lower(btrim(coalesce(p_role,''))); v_current text;
begin
 if v_role in ('viewer','patient') then v_role:='member'; end if;
 if v_role='caregiver' then raise exception 'health_role_is_person_scoped'; end if;
 if v_role not in ('admin','member') then raise exception 'unsupported_household_role'; end if;

 select * into v from private.resolve_line_family_member(p_line_user_id,p_member_code);
 perform set_config('request.jwt.claim.sub',v.actor_user_id::text,true);

 select role into v_current
 from public.family_role_assignments
 where family_id=v.family_id and user_id=v.target_user_id and status='active'
 limit 1;

 if v_current='owner' then raise exception 'owner_role_not_editable'; end if;

 if v_role='admin' then
   if not private.is_family_owner(v.family_id) then raise exception 'owner_required_for_admin_role'; end if;
   if p_enabled then
     update public.family_role_assignments set status='inactive',updated_at=now()
      where family_id=v.family_id and user_id=v.target_user_id and status='active';
     insert into public.family_role_assignments(family_id,user_id,role,status,granted_by,granted_at,created_at,updated_at)
      values(v.family_id,v.target_user_id,'admin','active',v.actor_user_id,now(),now(),now())
      on conflict(family_id,user_id,role) where status='active' do nothing;
     v_current:='admin';
   else
     update public.family_role_assignments set status='inactive',updated_at=now()
      where family_id=v.family_id and user_id=v.target_user_id and role='admin' and status='active';
     if not exists(select 1 from public.family_role_assignments
                   where family_id=v.family_id and user_id=v.target_user_id and status='active') then
       insert into public.family_role_assignments(family_id,user_id,role,status,granted_by,granted_at,created_at,updated_at)
       values(v.family_id,v.target_user_id,'member','active',v.actor_user_id,now(),now(),now());
     end if;
     v_current:='member';
   end if;
 else
   if v_current='admin' and not private.is_family_owner(v.family_id) then
     raise exception 'owner_required_to_downgrade_admin';
   end if;
   if p_enabled then
     update public.family_role_assignments set status='inactive',updated_at=now()
      where family_id=v.family_id and user_id=v.target_user_id and status='active';
     insert into public.family_role_assignments(family_id,user_id,role,status,granted_by,granted_at,created_at,updated_at)
      values(v.family_id,v.target_user_id,'member','active',v.actor_user_id,now(),now(),now());
     v_current:='member';
   end if;
 end if;

 insert into public.audit_logs(family_id,actor_user_id,target_user_id,event_type,resource,new_data,description,created_at)
 values(v.family_id,v.actor_user_id,v.target_user_id,'household_role_changed','household_roles',
   jsonb_build_object('role',v_current),'Changed canonical household role',now());

 return jsonb_build_object('status','ok','member_code',lower(btrim(p_member_code)),
   'household_role',v_current,'display_role',
   case v_current when 'admin' then 'ผู้ช่วยดูแลครอบครัว' when 'member' then 'สมาชิกครอบครัว' else v_current end);
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_set_line_family_roles_batch(p_line_user_id text, p_member_code text, p_roles text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare v_roles text[]:=coalesce(p_roles,array[]::text[]); v_target text:='member'; v_out jsonb;
begin
 if 'owner'=any(v_roles) then raise exception 'owner_transfer_flow_required'; end if;
 if 'admin'=any(v_roles) then v_target:='admin'; end if;
 select public.phms_set_line_family_role(p_line_user_id,p_member_code,v_target,true) into v_out;
 return v_out||jsonb_build_object('legacy_health_roles_ignored',true);
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_set_line_member_person_access_bulk(p_line_user_id text, p_member_code text, p_person_codes text[], p_level text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare v_level text:=lower(btrim(coalesce(p_level,'')));v_code text;v_count int:=0;v_skipped int:=0;v_person record;v_member record;v_linked uuid;v_scopes jsonb;
begin
 if v_level not in ('none','view','manage') then raise exception 'invalid_person_access_level';end if;
 if coalesce(array_length(p_person_codes,1),0)=0 then raise exception 'person_targets_required';end if;
 select * into v_member from private.resolve_line_family_member(p_line_user_id,p_member_code);
 v_scopes:=jsonb_build_object('persons',v_level,'appointments',v_level,'health_data',v_level,'medications',v_level,'emergency',v_level);
 foreach v_code in array p_person_codes loop
  select * into v_person from private.resolve_line_family_person_code(p_line_user_id,v_code);
  if v_member.family_id<>v_person.family_id then raise exception 'family_scope_mismatch';end if;
  select p.linked_user_id into v_linked from public.family_persons fp join public.persons p on p.id=fp.person_id where fp.id=v_person.family_person_id;
  if v_linked=v_member.target_user_id then v_skipped:=v_skipped+1;continue;end if;
  perform public.phms_line_medical_set_member_access(p_line_user_id,v_code,p_member_code,v_scopes);
  v_count:=v_count+1;
 end loop;
 return jsonb_build_object('ok',true,'updated_people',v_count,'skipped_self',v_skipped,'level',v_level);
end; $function$

CREATE OR REPLACE FUNCTION public.phms_set_line_person_access_bulk_members(p_line_user_id text, p_person_code text, p_member_codes text[], p_level text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare v_level text:=lower(btrim(coalesce(p_level,'')));v_code text;v_count int:=0;v_scopes jsonb;
begin
 if v_level not in ('none','view','manage','caregiver') then raise exception 'invalid_bulk_member_access_level';end if;
 if coalesce(array_length(p_member_codes,1),0)=0 then raise exception 'member_targets_required';end if;
 v_scopes:=jsonb_build_object('persons',case when v_level='caregiver' then 'manage' else v_level end,
  'appointments',case when v_level='caregiver' then 'manage' else v_level end,
  'health_data',case when v_level='caregiver' then 'manage' else v_level end,
  'medications',case when v_level='caregiver' then 'manage' else v_level end,
  'emergency',case when v_level='caregiver' then 'manage' else v_level end);
 foreach v_code in array p_member_codes loop
   perform public.phms_line_medical_set_member_access(p_line_user_id,p_person_code,v_code,v_scopes);
   v_count:=v_count+1;
 end loop;
 return jsonb_build_object('ok',true,'updated_members',v_count,'level',case when v_level='caregiver' then 'manage' else v_level end);
end; $function$

CREATE OR REPLACE FUNCTION public.phms_set_line_person_access_bundle(p_line_user_id text, p_member_code text, p_person_code text, p_is_caregiver boolean, p_medications_level text, p_appointments_level text, p_health_level text, p_receive_notifications boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_kind text;
 v_med text:=lower(btrim(coalesce(p_medications_level,'none')));
 v_appt text:=lower(btrim(coalesce(p_appointments_level,'none')));
 v_health text:=lower(btrim(coalesce(p_health_level,'none')));
 v_common text;
begin
 if v_med not in ('none','view','manage') or v_appt not in ('none','view','manage')
    or v_health not in ('none','view','manage') then
   raise exception 'invalid_access_level';
 end if;

 -- Old quick actions supply the same level to all three legacy fields.
 -- When they differ, preserve those three and keep profile/emergency at the least-privileged common level.
 v_common:=case
   when v_med='manage' and v_appt='manage' and v_health='manage' then 'manage'
   when v_med in ('view','manage') and v_appt in ('view','manage') and v_health in ('view','manage') then 'view'
   else 'none'
 end;

 v_kind:=case
   when coalesce(p_is_caregiver,false) or 'manage'=any(array[v_med,v_appt,v_health])
   then 'assistant' else 'viewer' end;

 return public.phms_set_line_person_access_bundle_v2(
  p_line_user_id,p_member_code,p_person_code,v_kind,
  v_common,v_med,v_appt,v_health,v_common,coalesce(p_receive_notifications,false)
 );
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_set_line_person_access_bundle_v2(p_line_user_id text, p_member_code text, p_person_code text, p_access_kind text, p_profile_level text, p_medications_level text, p_appointments_level text, p_health_level text, p_emergency_level text, p_receive_notifications boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_member record; v_person record; v_subject_user uuid; v_primary_user uuid;
 v_kind text:=lower(btrim(coalesce(p_access_kind,'')));
 v_profile text:=lower(btrim(coalesce(p_profile_level,'none')));
 v_med text:=lower(btrim(coalesce(p_medications_level,'none')));
 v_appt text:=lower(btrim(coalesce(p_appointments_level,'none')));
 v_health text:=lower(btrim(coalesce(p_health_level,'none')));
 v_emergency text:=lower(btrim(coalesce(p_emergency_level,'none')));
 v_r record; v_notify boolean:=coalesce(p_receive_notifications,false);
begin
 if v_kind not in ('viewer','assistant') then raise exception 'invalid_health_access_kind'; end if;
 if v_profile not in ('none','view','manage') or v_med not in ('none','view','manage')
    or v_appt not in ('none','view','manage') or v_health not in ('none','view','manage')
    or v_emergency not in ('none','view','manage') then raise exception 'invalid_access_level'; end if;
 if v_kind='viewer' and 'manage'=any(array[v_profile,v_med,v_appt,v_health,v_emergency]) then
   raise exception 'viewer_cannot_manage';
 end if;
 if v_kind='assistant' and not ('manage'=any(array[v_profile,v_med,v_appt,v_health,v_emergency])) then
   raise exception 'assistant_requires_manage_scope';
 end if;

 select * into v_member from private.resolve_line_family_member(p_line_user_id,p_member_code);
 select * into v_person from private.resolve_line_family_person_code(p_line_user_id,p_person_code);
 if v_member.family_id<>v_person.family_id then raise exception 'family_scope_mismatch'; end if;
 perform set_config('request.jwt.claim.sub',v_member.actor_user_id::text,true);

 if not private.phms_can_manage_medical_grants(v_member.actor_user_id,v_person.family_person_id) then
   raise exception 'health_access_management_denied';
 end if;

 select p.linked_user_id into v_subject_user
 from public.family_persons fp join public.persons p on p.id=fp.person_id
 where fp.id=v_person.family_person_id;
 select mp.primary_user_id into v_primary_user
 from private.medical_primary_responsibilities mp
 where mp.family_person_id=v_person.family_person_id and mp.state='active';

 if v_member.target_user_id=v_subject_user then raise exception 'subject_uses_self_access'; end if;
 if v_member.target_user_id=v_primary_user then raise exception 'primary_caregiver_has_full_access'; end if;

 for v_r in select * from (values
   ('persons'::text,v_profile),
   ('medications'::text,v_med),
   ('appointments'::text,v_appt),
   ('health_data'::text,v_health),
   ('emergency'::text,v_emergency)
 ) x(resource,level)
 loop
   insert into public.person_permissions(
    family_id,family_person_id,user_id,resource,can_view,can_create,can_update,can_delete,
    can_receive_notifications,granted_by,status,created_at,updated_at
   ) values(
    v_member.family_id,v_person.family_person_id,v_member.target_user_id,v_r.resource,
    v_r.level in ('view','manage'),v_r.level='manage',v_r.level='manage',v_r.level='manage',
    v_notify and v_r.level<>'none',v_member.actor_user_id,'active',now(),now()
   )
   on conflict(family_id,family_person_id,user_id,resource) do update set
    can_view=excluded.can_view,can_create=excluded.can_create,can_update=excluded.can_update,
    can_delete=excluded.can_delete,can_receive_notifications=excluded.can_receive_notifications,
    granted_by=excluded.granted_by,status='active',updated_at=now();
 end loop;

 if v_kind='assistant' then
   insert into public.person_caregiver_assignments(
    family_id,family_person_id,caregiver_user_id,is_primary,
    can_edit_profile,can_manage_medications,can_manage_appointments,can_manage_health,can_manage_emergency,
    can_receive_notifications,status,assigned_by,assigned_at,created_at,updated_at
   ) values(
    v_member.family_id,v_person.family_person_id,v_member.target_user_id,false,
    v_profile='manage',v_med='manage',v_appt='manage',v_health='manage',v_emergency='manage',
    v_notify,'active',v_member.actor_user_id,now(),now(),now()
   )
   on conflict(family_person_id,caregiver_user_id) do update set
    status='active',is_primary=false,can_edit_profile=excluded.can_edit_profile,
    can_manage_medications=excluded.can_manage_medications,
    can_manage_appointments=excluded.can_manage_appointments,
    can_manage_health=excluded.can_manage_health,can_manage_emergency=excluded.can_manage_emergency,
    can_receive_notifications=excluded.can_receive_notifications,
    assigned_by=v_member.actor_user_id,assigned_at=now(),updated_at=now();
 else
   update public.person_caregiver_assignments
    set status='inactive',is_primary=false,updated_at=now()
    where family_person_id=v_person.family_person_id and caregiver_user_id=v_member.target_user_id;
 end if;

 insert into public.audit_logs(
  family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,new_data,description,created_at
 ) values(
  v_member.family_id,v_member.actor_user_id,v_member.target_user_id,v_person.family_person_id,
  'health_access_bundle_updated','medical_access',
  jsonb_build_object('access_kind',v_kind,'profile',v_profile,'medications',v_med,
    'appointments',v_appt,'health',v_health,'emergency',v_emergency,'notifications',v_notify),
  'Updated canonical five-category health access',now()
 );

 return jsonb_build_object('status','ok','access_kind',v_kind,
   'profile',v_profile,'medications',v_med,'appointments',v_appt,'health',v_health,
   'emergency',v_emergency,'receive_notifications',v_notify,
   'member_code',lower(btrim(p_member_code)),'person_code',lower(btrim(p_person_code)));
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_set_line_person_caregiver(p_line_user_id text, p_member_code text, p_enabled boolean, p_primary boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_line record; v_ctx private.line_identity_contexts%rowtype; v_person_code text;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select c.* into v_ctx from private.line_identity_contexts c
 where c.line_identity_id=v_line.line_identity_id;
 if v_ctx.active_scope<>'family' or v_ctx.active_family_id is null or v_ctx.active_family_person_id is null then
   raise exception 'family_person_context_required';
 end if;

 v_person_code:=substr(
   encode(digest(v_ctx.active_family_person_id::text||':'||v_line.line_identity_id::text,'sha256'),'hex'),
   1,12
 );

 return public.phms_set_line_person_caregiver_for_person(
   p_line_user_id,p_member_code,v_person_code,p_enabled,p_primary
 );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_set_line_person_caregiver_for_person(p_line_user_id text, p_member_code text, p_person_code text, p_enabled boolean, p_primary boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare v_member record; v_person record; v_subject_user uuid; v_primary_user uuid;
begin
 select * into v_member from private.resolve_line_family_member(p_line_user_id,p_member_code);
 select * into v_person from private.resolve_line_family_person_code(p_line_user_id,p_person_code);
 if v_member.family_id<>v_person.family_id then raise exception 'family_scope_mismatch'; end if;
 perform set_config('request.jwt.claim.sub',v_member.actor_user_id::text,true);

 if not private.phms_can_manage_medical_grants(v_member.actor_user_id,v_person.family_person_id) then
   raise exception 'health_access_management_denied';
 end if;

 select p.linked_user_id into v_subject_user
 from public.family_persons fp join public.persons p on p.id=fp.person_id
 where fp.id=v_person.family_person_id;
 select mp.primary_user_id into v_primary_user
 from private.medical_primary_responsibilities mp
 where mp.family_person_id=v_person.family_person_id and mp.state='active';

 if p_primary then
   return public.phms_line_medical_primary_nominate(
     p_line_user_id,p_person_code,p_member_code,'ขอเปลี่ยนผู้ดูแลหลัก',false
   );
 end if;

 if v_member.target_user_id=v_subject_user then raise exception 'subject_uses_self_access'; end if;
 if v_member.target_user_id=v_primary_user then raise exception 'primary_caregiver_has_full_access'; end if;

 if p_enabled then
   insert into public.person_caregiver_assignments(
    family_id,family_person_id,caregiver_user_id,is_primary,
    can_edit_profile,can_manage_medications,can_manage_appointments,can_manage_health,can_manage_emergency,
    can_receive_notifications,status,assigned_by,assigned_at,created_at,updated_at
   ) values(
    v_member.family_id,v_person.family_person_id,v_member.target_user_id,false,
    true,true,true,true,false,true,'active',v_member.actor_user_id,now(),now(),now()
   )
   on conflict(family_person_id,caregiver_user_id) do update set
    status='active',is_primary=false,can_edit_profile=true,can_manage_medications=true,
    can_manage_appointments=true,can_manage_health=true,can_manage_emergency=false,
    can_receive_notifications=true,assigned_by=v_member.actor_user_id,assigned_at=now(),updated_at=now();
 else
   update public.person_caregiver_assignments
   set status='inactive',is_primary=false,updated_at=now()
   where family_person_id=v_person.family_person_id
     and caregiver_user_id=v_member.target_user_id and status='active';
 end if;

 insert into public.audit_logs(
  family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,new_data,description,created_at
 ) values(
  v_member.family_id,v_member.actor_user_id,v_member.target_user_id,v_person.family_person_id,
  case when p_enabled then 'care_assistant_assigned' else 'care_assistant_removed' end,
  'medical_access',jsonb_build_object('care_assistant',p_enabled),
  case when p_enabled then 'Assigned health care assistant' else 'Removed health care assistant' end,now()
 );

 return jsonb_build_object('status','ok','access_kind','care_assistant','enabled',p_enabled,
   'member_code',lower(btrim(p_member_code)),'person_code',lower(btrim(p_person_code)));
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_set_line_person_permission(p_line_user_id text, p_member_code text, p_person_code text, p_resource text, p_action text, p_enabled boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_member record;v_person record;
 v_resource text:=case lower(btrim(coalesce(p_resource,'')))
   when 'profile' then 'persons' when 'health' then 'health_data'
   when 'medication' then 'medications' else lower(btrim(coalesce(p_resource,''))) end;
 v_action text:=lower(btrim(coalesce(p_action,'')));
begin
 if v_resource not in ('persons','appointments','medications','health_data','emergency','documents','expenses') then
   raise exception 'unsupported_permission_resource';
 end if;
 if v_action not in ('view','create','update','delete','receive_notifications') then
   raise exception 'unsupported_permission_action';
 end if;

 select * into v_member from private.resolve_line_family_member(p_line_user_id,p_member_code);
 select * into v_person from private.resolve_line_family_person_code(p_line_user_id,p_person_code);
 if v_member.family_id<>v_person.family_id then raise exception 'family_scope_mismatch'; end if;
 perform set_config('request.jwt.claim.sub',v_member.actor_user_id::text,true);

 if not private.phms_can_manage_medical_grants(v_member.actor_user_id,v_person.family_person_id) then
   raise exception 'health_access_management_denied';
 end if;

 if private.phms_is_medical_primary(v_member.target_user_id,v_person.family_person_id) then
   raise exception 'cannot_change_primary_grants';
 end if;
 if exists(
  select 1 from public.family_persons fp join public.persons p on p.id=fp.person_id
  where fp.id=v_person.family_person_id and p.linked_user_id=v_member.target_user_id
 ) then raise exception 'use_self_access_settings'; end if;

 insert into public.person_permissions(
  family_id,family_person_id,user_id,resource,can_view,can_create,can_update,can_delete,
  can_receive_notifications,granted_by,status,created_at,updated_at
 ) values(
  v_member.family_id,v_person.family_person_id,v_member.target_user_id,v_resource,
  case when v_action='view' then p_enabled else false end,
  case when v_action='create' then p_enabled else false end,
  case when v_action='update' then p_enabled else false end,
  case when v_action='delete' then p_enabled else false end,
  case when v_action='receive_notifications' then p_enabled else false end,
  v_member.actor_user_id,'active',now(),now()
 )
 on conflict(family_id,family_person_id,user_id,resource) do update set
  can_view=case when v_action='view' then p_enabled else public.person_permissions.can_view end,
  can_create=case when v_action='create' then p_enabled else public.person_permissions.can_create end,
  can_update=case when v_action='update' then p_enabled else public.person_permissions.can_update end,
  can_delete=case when v_action='delete' then p_enabled else public.person_permissions.can_delete end,
  can_receive_notifications=case when v_action='receive_notifications' then p_enabled else public.person_permissions.can_receive_notifications end,
  granted_by=v_member.actor_user_id,status='active',updated_at=now();

 perform private.sync_care_assistant_from_person_permissions(
  v_person.family_person_id,v_member.target_user_id,v_member.actor_user_id
 );

 insert into public.audit_logs(
  family_id,actor_user_id,target_user_id,family_person_id,event_type,resource,new_data,description,created_at
 ) values(
  v_member.family_id,v_member.actor_user_id,v_member.target_user_id,v_person.family_person_id,
  case when p_enabled then 'person_permission_granted' else 'person_permission_revoked' end,
  v_resource,jsonb_build_object('scope','person','action',v_action,'enabled',p_enabled),
  'Changed person-scoped health permission',now()
 );

 return jsonb_build_object(
  'status','ok','scope','person','resource',v_resource,'action',v_action,'enabled',p_enabled,
  'member_code',lower(btrim(p_member_code)),'person_code',lower(btrim(p_person_code))
 );
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_set_line_person_photo_preference(p_line_user_id text, p_photo_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare v_line record; v_ctx private.line_identity_contexts%rowtype; v_photo public.person_photos%rowtype;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select c.* into v_ctx from private.line_identity_contexts c where c.line_identity_id=v_line.line_identity_id;
 select ph.* into v_photo from public.person_photos ph
 where ph.family_person_id=v_ctx.active_family_person_id and ph.status='active'
 and (ph.uploaded_by=v_line.user_id or ph.visibility='shared')
 and substr(encode(digest(ph.id::text||':'||v_line.line_identity_id::text,'sha256'),'hex'),1,12)=lower(btrim(p_photo_code))
 limit 1;
 if not found then raise exception 'person_photo_not_found'; end if;
 insert into public.person_photo_preferences(viewer_user_id,family_person_id,photo_id,updated_at)
 values(v_line.user_id,v_photo.family_person_id,v_photo.id,now())
 on conflict(viewer_user_id,family_person_id) do update set photo_id=excluded.photo_id,updated_at=now();
 return jsonb_build_object('status','ok','object_name',v_photo.object_name);
end $function$

CREATE OR REPLACE FUNCTION public.phms_set_line_person_photo_private(p_line_user_id text, p_photo_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_line record; v_ctx private.line_identity_contexts%rowtype; v_photo public.person_photos%rowtype;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select c.* into v_ctx from private.line_identity_contexts c where c.line_identity_id=v_line.line_identity_id;

 select ph.* into v_photo
 from public.person_photos ph
 where ph.family_person_id=v_ctx.active_family_person_id
   and ph.status='active'
   and substr(encode(digest(ph.id::text||':'||v_line.line_identity_id::text,'sha256'),'hex'),1,12)=lower(btrim(p_photo_code))
 limit 1;
 if not found then raise exception 'person_photo_not_found'; end if;

 perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
 if not (
   v_photo.uploaded_by=v_line.user_id
   or private.can_access_family_person(v_photo.family_person_id,'persons','update')
 ) then raise exception 'person_photo_private_denied'; end if;

 update public.person_photos
 set visibility='private',is_person_shared_default=false,updated_at=now()
 where id=v_photo.id;

 insert into public.person_photo_preferences(viewer_user_id,family_person_id,photo_id,updated_at)
 values(v_line.user_id,v_photo.family_person_id,v_photo.id,now())
 on conflict(viewer_user_id,family_person_id)
 do update set photo_id=excluded.photo_id,updated_at=now();

 return jsonb_build_object('status','ok','private',true,'object_name',v_photo.object_name);
end $function$

CREATE OR REPLACE FUNCTION public.phms_set_line_person_shared_photo(p_line_user_id text, p_photo_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare v_line record; v_ctx private.line_identity_contexts%rowtype; v_photo public.person_photos%rowtype; v_p public.persons%rowtype;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select c.* into v_ctx from private.line_identity_contexts c where c.line_identity_id=v_line.line_identity_id;
 select p.* into v_p from public.family_persons fp join public.persons p on p.id=fp.person_id where fp.id=v_ctx.active_family_person_id;
 perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
 if not (coalesce(v_p.linked_user_id=v_line.user_id,false) or private.can_access_family_person(v_ctx.active_family_person_id,'persons','update')) then raise exception 'person_photo_share_denied'; end if;
 select ph.* into v_photo from public.person_photos ph
 where ph.family_person_id=v_ctx.active_family_person_id and ph.status='active'
 and substr(encode(digest(ph.id::text||':'||v_line.line_identity_id::text,'sha256'),'hex'),1,12)=lower(btrim(p_photo_code))
 limit 1;
 if not found then raise exception 'person_photo_not_found'; end if;
 update public.person_photos set is_person_shared_default=false,updated_at=now() where family_person_id=v_photo.family_person_id and is_person_shared_default=true;
 update public.person_photos set visibility='shared',is_person_shared_default=true,updated_at=now() where id=v_photo.id;
 return jsonb_build_object('status','ok','object_name',v_photo.object_name);
end $function$

CREATE OR REPLACE FUNCTION public.phms_set_line_prelink_person_access_bundle(p_line_user_id text, p_subject_person_code text, p_target_person_code text, p_is_caregiver boolean, p_medications_level text, p_appointments_level text, p_health_level text, p_receive_notifications boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_med text:=lower(btrim(coalesce(p_medications_level,'none')));
 v_appt text:=lower(btrim(coalesce(p_appointments_level,'none')));
 v_health text:=lower(btrim(coalesce(p_health_level,'none')));
 v_kind text;v_profile text;
begin
 if v_med not in ('none','view','manage') or v_appt not in ('none','view','manage')
    or v_health not in ('none','view','manage') then raise exception 'invalid_access_level'; end if;

 v_kind:=case when coalesce(p_is_caregiver,false)
                  or 'manage'=any(array[v_med,v_appt,v_health])
              then 'assistant' else 'viewer' end;
 v_profile:=case when v_kind='assistant' then 'manage'
                 when v_med<>'none' or v_appt<>'none' or v_health<>'none' then 'view'
                 else 'none' end;

 return public.phms_set_line_prelink_person_access_bundle_v2(
  p_line_user_id,p_subject_person_code,p_target_person_code,v_kind,
  v_profile,v_med,v_appt,v_health,'none',coalesce(p_receive_notifications,false)
 );
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_set_line_prelink_person_access_bundle_v2(p_line_user_id text, p_subject_person_code text, p_target_person_code text, p_access_kind text, p_profile_level text, p_medications_level text, p_appointments_level text, p_health_level text, p_emergency_level text, p_receive_notifications boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_subject record;v_target record;v_linked uuid;
 v_kind text:=lower(btrim(coalesce(p_access_kind,'')));
 v_profile text:=lower(btrim(coalesce(p_profile_level,'none')));
 v_med text:=lower(btrim(coalesce(p_medications_level,'none')));
 v_appt text:=lower(btrim(coalesce(p_appointments_level,'none')));
 v_health text:=lower(btrim(coalesce(p_health_level,'none')));
 v_emergency text:=lower(btrim(coalesce(p_emergency_level,'none')));
 v_assistant boolean:=false;
begin
 select * into v_subject from private.resolve_line_family_person_code(p_line_user_id,p_subject_person_code);
 select * into v_target from private.resolve_line_family_person_code(p_line_user_id,p_target_person_code);
 if v_subject.family_id<>v_target.family_id then raise exception 'family_scope_mismatch'; end if;

 perform set_config('request.jwt.claim.sub',v_subject.actor_user_id::text,true);

 if not private.phms_can_manage_medical_grants(v_subject.actor_user_id,v_target.family_person_id) then
   raise exception 'health_access_management_denied';
 end if;

 if v_kind not in ('viewer','assistant') then raise exception 'invalid_health_access_kind'; end if;
 if v_profile not in ('none','view','manage') or v_med not in ('none','view','manage')
    or v_appt not in ('none','view','manage') or v_health not in ('none','view','manage')
    or v_emergency not in ('none','view','manage') then
   raise exception 'invalid_access_level';
 end if;

 v_assistant:=v_kind='assistant'
   or 'manage'=any(array[v_profile,v_med,v_appt,v_health,v_emergency]);

 if not v_assistant
    and 'manage'=any(array[v_profile,v_med,v_appt,v_health,v_emergency]) then
   raise exception 'viewer_cannot_manage';
 end if;
 if v_assistant
    and not ('manage'=any(array[v_profile,v_med,v_appt,v_health,v_emergency])) then
   raise exception 'assistant_requires_manage_scope';
 end if;

 select p.linked_user_id into v_linked
 from public.family_persons fp join public.persons p on p.id=fp.person_id
 where fp.id=v_subject.family_person_id;
 if v_linked is not null then raise exception 'person_already_linked'; end if;
 if v_subject.family_person_id=v_target.family_person_id then raise exception 'self_target_not_allowed'; end if;

 insert into private.family_person_pending_access(
  family_id,subject_family_person_id,target_family_person_id,is_caregiver,
  profile_level,medications_level,appointments_level,health_level,emergency_level,
  receive_notifications,configured_by,created_at,updated_at
 ) values(
  v_subject.family_id,v_subject.family_person_id,v_target.family_person_id,v_assistant,
  v_profile,v_med,v_appt,v_health,v_emergency,
  coalesce(p_receive_notifications,false),v_subject.actor_user_id,now(),now()
 )
 on conflict(subject_family_person_id,target_family_person_id) do update set
  is_caregiver=excluded.is_caregiver,
  profile_level=excluded.profile_level,
  medications_level=excluded.medications_level,
  appointments_level=excluded.appointments_level,
  health_level=excluded.health_level,
  emergency_level=excluded.emergency_level,
  receive_notifications=excluded.receive_notifications,
  configured_by=excluded.configured_by,
  updated_at=now();

 return jsonb_build_object(
  'status','ok','subject_person_code',lower(btrim(p_subject_person_code)),
  'target_person_code',lower(btrim(p_target_person_code)),
  'access_kind',case when v_assistant then 'assistant' else 'viewer' end,
  'applies_when_linked',true
 );
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_set_line_prelink_roles(p_line_user_id text, p_person_code text, p_roles text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_person record;v_roles text[]:=coalesce(p_roles,array[]::text[]);v_linked uuid;
 v_admin boolean:=false;
begin
 select * into v_person from private.resolve_line_family_person_code(p_line_user_id,p_person_code);
 perform set_config('request.jwt.claim.sub',v_person.actor_user_id::text,true);

 if not private.is_family_owner(v_person.family_id) then
   raise exception 'owner_required_for_admin_role';
 end if;

 select p.linked_user_id into v_linked
 from public.family_persons fp join public.persons p on p.id=fp.person_id
 where fp.id=v_person.family_person_id;
 if v_linked is not null then raise exception 'person_already_linked'; end if;

 if exists(select 1 from unnest(v_roles) r where r not in ('admin','member')) then
   raise exception 'health_roles_are_not_household_roles';
 end if;
 v_admin:='admin'=any(v_roles);

 delete from private.family_person_pending_roles
 where family_person_id=v_person.family_person_id;

 if v_admin then
  insert into private.family_person_pending_roles(
   family_id,family_person_id,role,configured_by,created_at,updated_at
  ) values(
   v_person.family_id,v_person.family_person_id,'admin',v_person.actor_user_id,now(),now()
  );
 end if;

 return jsonb_build_object(
  'status','ok','person_code',lower(btrim(p_person_code)),
  'household_role',case when v_admin then 'admin' else 'member' end,
  'display_role',case when v_admin then 'ผู้ช่วยดูแลครอบครัว' else 'สมาชิกครอบครัว' end,
  'applies_when_linked',true
 );
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_set_line_self_viewer(p_line_user_id text, p_member_code text, p_enabled boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_line record;v_ctx private.line_identity_contexts%rowtype;v_self_fp uuid;
 v_member record;v_res text;v_target_name text;v_self_name text;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 perform private.ensure_line_identity_context(v_line.line_identity_id,v_line.user_id);
 select * into v_ctx from private.line_identity_contexts where line_identity_id=v_line.line_identity_id;
 if v_ctx.active_scope<>'family' or v_ctx.active_family_id is null then
   raise exception 'family_context_required';
 end if;

 select fp.id into v_self_fp
 from public.family_persons fp
 join public.persons p on p.id=fp.person_id
 where fp.family_id=v_ctx.active_family_id
   and p.linked_user_id=v_line.user_id
   and coalesce(fp.status,'active')='active'
   and coalesce(p.status,'active')='active'
 limit 1;
 if v_self_fp is null then raise exception 'self_family_person_not_found'; end if;

 perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);
 if not private.phms_can_manage_medical_grants(v_line.user_id,v_self_fp) then
   raise exception 'health_access_management_denied';
 end if;

 select * into v_member from private.resolve_line_family_member(p_line_user_id,p_member_code) limit 1;
 if v_member.family_id<>v_ctx.active_family_id then raise exception 'family_scope_mismatch'; end if;
 if v_member.target_user_id=v_line.user_id then raise exception 'cannot_grant_self_viewer_to_self'; end if;
 if private.phms_is_medical_primary(v_member.target_user_id,v_self_fp) then
   raise exception 'target_is_primary_caregiver';
 end if;

 if exists(
  select 1 from public.person_caregiver_assignments ca
  where ca.family_id=v_ctx.active_family_id and ca.family_person_id=v_self_fp
    and ca.caregiver_user_id=v_member.target_user_id and ca.status='active'
 ) then raise exception 'target_is_care_assistant'; end if;

 if exists(
  select 1 from public.person_permissions pp
  where pp.family_id=v_ctx.active_family_id and pp.family_person_id=v_self_fp
    and pp.user_id=v_member.target_user_id and pp.status='active'
    and (coalesce(pp.can_create,false) or coalesce(pp.can_update,false) or coalesce(pp.can_delete,false))
 ) then raise exception 'target_has_manage_access'; end if;

 foreach v_res in array array['persons','medications','appointments','health_data','emergency']::text[] loop
  insert into public.person_permissions(
   family_id,family_person_id,user_id,resource,
   can_view,can_create,can_update,can_delete,can_receive_notifications,
   granted_by,status,created_at,updated_at
  ) values(
   v_ctx.active_family_id,v_self_fp,v_member.target_user_id,v_res,
   p_enabled,false,false,false,false,
   v_line.user_id,'active',now(),now()
  )
  on conflict(family_id,family_person_id,user_id,resource) do update
  set can_view=p_enabled,can_create=false,can_update=false,can_delete=false,
      can_receive_notifications=false,
      granted_by=v_line.user_id,status='active',updated_at=now();
 end loop;

 v_target_name:=private.family_user_label_for_viewer(v_line.user_id,v_ctx.active_family_id,v_member.target_user_id);
 v_self_name:=private.family_person_label_for_viewer(v_line.user_id,v_self_fp);

 insert into public.audit_logs(
  family_id,actor_user_id,target_user_id,family_person_id,
  event_type,resource,new_data,description,created_at
 ) values(
  v_ctx.active_family_id,v_line.user_id,v_member.target_user_id,v_self_fp,
  case when p_enabled then 'self_viewer_granted' else 'self_viewer_revoked' end,
  'medical_access',
  jsonb_build_object(
   'mode','viewer','enabled',p_enabled,
   'resources',jsonb_build_array('persons','medications','appointments','health_data','emergency')
  ),
  'Health-data owner/primary caregiver changed view-only access',now()
 );

 if p_enabled then
  insert into public.notifications(
   family_id,recipient_user_id,event_type,title,message,channel,priority,status,
   family_person_id,payload,dedupe_key,created_at,updated_at
  ) values(
   v_ctx.active_family_id,v_member.target_user_id,'self_viewer_granted',
   '👀 คุณได้รับอนุญาตให้ดูข้อมูล',
   coalesce(v_self_name,'เจ้าของข้อมูล')||' อนุญาตให้คุณดูข้อมูลสุขภาพที่กำหนดไว้ได้ โดยแก้ไขไม่ได้',
   'line','normal','pending',v_self_fp,
   jsonb_build_object('mode','viewer','all_five_categories',true),
   'self-viewer-granted:'||v_self_fp::text||':'||v_member.target_user_id::text||':'||extract(epoch from now())::bigint::text,
   now(),now()
  );
 end if;

 return jsonb_build_object(
  'ok',true,'enabled',p_enabled,'target_name',v_target_name,'person_name',v_self_name,
  'access_kind','viewer','all_five_categories',true
 );
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_set_my_family_person_view_label(p_family_person_id uuid, p_relationship_label text DEFAULT NULL::text, p_display_label text DEFAULT NULL::text)
 RETURNS TABLE(family_person_id uuid, family_id uuid, relationship_label text, display_label text, resolved_label text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_fp public.family_persons%rowtype;
  v_relationship text := nullif(btrim(p_relationship_label),'');
  v_display text := nullif(btrim(p_display_label),'');
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  if p_family_person_id is null then raise exception 'family_person_id_required'; end if;

  select fp.* into v_fp
  from public.family_persons fp
  join public.families f on f.id=fp.family_id
  where fp.id=p_family_person_id
    and coalesce(fp.status,'active')='active'
    and coalesce(f.status,'active')='active'
  limit 1;
  if not found then raise exception 'family_person_not_accessible'; end if;

  if not exists(
    select 1 from public.family_memberships fm
    where fm.user_id=v_uid and fm.family_id=v_fp.family_id and fm.status='active'
  ) then raise exception 'family_membership_required'; end if;

  if v_relationship is null and v_display is null then
    delete from public.family_person_view_labels x
    where x.viewer_user_id=v_uid and x.family_person_id=v_fp.id;
  else
    insert into public.family_person_view_labels(
      viewer_user_id,family_id,family_person_id,relationship_label,display_label,updated_at
    ) values(
      v_uid,v_fp.family_id,v_fp.id,v_relationship,v_display,now()
    )
    on conflict (viewer_user_id,family_person_id) do update
      set family_id=excluded.family_id,
          relationship_label=excluded.relationship_label,
          display_label=excluded.display_label,
          updated_at=now();
  end if;

  return query
  select v_fp.id,v_fp.family_id,v_relationship,v_display,
         private.family_person_label_for_viewer(v_uid,v_fp.id);
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_start_line_account_link(p_line_user_id text, p_ttl_minutes integer DEFAULT 15)
 RETURNS TABLE(request_id uuid, verification_token text, expires_at timestamp with time zone, already_linked boolean, linked_user_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_identity public.line_identities%rowtype;
  v_token text;
  v_request_id uuid;
  v_expires_at timestamptz;
begin
  if p_line_user_id is null or btrim(p_line_user_id) = '' then
    raise exception 'line_user_id_required';
  end if;

  if p_ttl_minutes < 5 or p_ttl_minutes > 60 then
    raise exception 'invalid_ttl';
  end if;

  select * into v_identity
  from public.line_identities
  where line_user_id = p_line_user_id
  for update;

  if not found then
    raise exception 'line_identity_not_found';
  end if;

  if coalesce(v_identity.is_active,false) is not true then
    raise exception 'line_identity_inactive';
  end if;

  if v_identity.user_id is not null then
    return query select null::uuid, null::text, null::timestamptz, true, v_identity.user_id;
    return;
  end if;

  update public.account_link_requests alr
  set status = case when alr.expires_at is not null and alr.expires_at <= now() then 'expired' else 'cancelled' end,
      cancelled_at = case when alr.expires_at is null or alr.expires_at > now() then now() else alr.cancelled_at end,
      expired_at = case when alr.expires_at is not null and alr.expires_at <= now() then coalesce(alr.expired_at,now()) else alr.expired_at end,
      updated_at = now()
  where alr.line_identity_id = v_identity.id
    and alr.status in ('pending','confirmed');

  v_token := encode(gen_random_bytes(32),'hex');
  v_expires_at := now() + make_interval(mins => p_ttl_minutes);

  insert into public.account_link_requests(
    line_identity_id,status,verification_token_hash,expires_at,metadata
  ) values (
    v_identity.id,'pending',encode(digest(v_token,'sha256'),'hex'),v_expires_at,
    jsonb_build_object('source','line','flow','line_to_phms_user')
  ) returning id into v_request_id;

  return query select v_request_id, v_token, v_expires_at, false, null::uuid;
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_start_line_structured_text_intake(p_line_user_id text, p_line_message_id text, p_resource text, p_raw_text text, p_normalized_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_key text:=private.phms_crud_resource_key(p_resource);
  v_ctx record;
  v_session_id uuid;
  v_source_id uuid;
  v_candidate_id uuid;
  v_doc_type text;
  v_candidate_type text;
  v_data jsonb:=coalesce(p_normalized_data,'{}'::jsonb);
  v_existing record;
begin
  if v_key not in ('medication','appointment','health') then
    raise exception 'structured_text_resource_not_supported';
  end if;
  if p_line_message_id is null or btrim(p_line_message_id)='' then
    raise exception 'line_message_id_required';
  end if;
  if p_raw_text is null or btrim(p_raw_text)='' then
    raise exception 'raw_text_required';
  end if;
  if jsonb_typeof(v_data)<>'object' then raise exception 'normalized_data_object_required'; end if;

  select * into v_ctx
  from private.phms_line_crud_context(p_line_user_id,v_key,'create')
  limit 1;

  select s.id source_id,s.session_id,c.id candidate_id
  into v_existing
  from public.data_intake_sources s
  join public.data_intake_sessions ds on ds.id=s.session_id
  left join public.data_intake_candidates c on c.source_id=s.id
  where s.line_message_id=p_line_message_id
    and s.submitted_by=v_ctx.actor_user_id
  order by c.ordinal
  limit 1;

  if found then
    return public.phms_get_line_intake_review_source(
      p_line_user_id,v_existing.source_id
    );
  end if;

  if v_key='medication' then
    if nullif(btrim(coalesce(
      v_data->>'generic_name',v_data->>'medication_name',v_data->>'name'
    )),'') is null then
      raise exception 'medication_name_required';
    end if;
    v_doc_type:='medication_label';
    v_candidate_type:='medication';

  elsif v_key='appointment' then
    if private.phms_try_timestamptz(v_data->>'appointment_at') is null then
      raise exception 'appointment_at_required';
    end if;
    v_doc_type:='appointment';
    v_candidate_type:='appointment';

  else
    if nullif(btrim(coalesce(v_data->>'measurement_type',v_data->>'type')),'') is null then
      raise exception 'measurement_type_required';
    end if;
    if private.phms_try_timestamptz(coalesce(v_data->>'measured_at',v_data->>'measurement_at')) is null then
      v_data:=v_data||jsonb_build_object('measured_at',now());
    end if;
    if private.phms_try_numeric(v_data->>'value_numeric') is null
       and nullif(btrim(v_data->>'value_text'),'') is null
       and private.phms_try_numeric(v_data->>'systolic') is null
       and private.phms_try_numeric(v_data->>'diastolic') is null then
      raise exception 'measurement_value_required';
    end if;
    if (private.phms_try_numeric(v_data->>'systolic') is null)
       <> (private.phms_try_numeric(v_data->>'diastolic') is null) then
      raise exception 'blood_pressure_requires_systolic_and_diastolic';
    end if;
    v_doc_type:='free_text';
    v_candidate_type:='health_measurement';
  end if;

  v_data:=v_data||jsonb_build_object(
    'source_text',left(p_raw_text,2000),
    'extraction_mode','line_structured_manual'
  );

  insert into public.data_intake_sessions(
    submitted_by,person_id,family_id,family_person_id,
    channel,status,input_count,context_snapshot
  )
  values(
    v_ctx.actor_user_id,v_ctx.target_person_id,
    v_ctx.active_family_id,v_ctx.active_family_person_id,
    'line','review',1,
    jsonb_build_object(
      'line_user_id',p_line_user_id,
      'line_message_id',p_line_message_id,
      'person_label',v_ctx.target_person_name,
      'person_pending',false,
      'structured_text_add',true,
      'resource',v_key
    )
  )
  returning id into v_session_id;

  insert into public.data_intake_sources(
    session_id,submitted_by,source_kind,document_type,
    raw_text,classification_confidence,source_metadata,line_message_id
  )
  values(
    v_session_id,v_ctx.actor_user_id,'text',v_doc_type,
    left(p_raw_text,20000),1.0,
    jsonb_build_object(
      'extraction_status','completed',
      'extraction_provider','line_structured_manual',
      'ocr_location','human_manual',
      'review_required',true,
      'auto_commit',false,
      'canonical_commit',false,
      'structured_text_add',true,
      'resource',v_key,
      'extracted_at',now()
    ),
    p_line_message_id
  )
  returning id into v_source_id;

  insert into public.data_intake_candidates(
    session_id,source_id,person_id,candidate_type,ordinal,
    extracted_data,normalized_data,confidence_data,
    validation_data,conflict_data,reconciliation_data,review_status
  )
  values(
    v_session_id,v_source_id,v_ctx.target_person_id,v_candidate_type,1,
    jsonb_build_object(
      'raw_line',left(p_raw_text,2000),
      'source_text',left(p_raw_text,2000)
    ),
    v_data,
    jsonb_build_object(
      'provider','line_structured_manual',
      'human_entered',true,
      'quality_score',1.0,
      'classification_confidence',1.0
    ),
    jsonb_build_object(
      'blocking_errors','[]'::jsonb,
      'warnings','[]'::jsonb,
      'validated_at',now()
    ),
    '{}'::jsonb,'{}'::jsonb,'needs_review'
  )
  returning id into v_candidate_id;

  insert into public.data_intake_actions(
    session_id,candidate_id,actor_user_id,action,after_data
  )
  values
    (v_session_id,v_candidate_id,v_ctx.actor_user_id,'create',
      jsonb_build_object('source_id',v_source_id,'resource',v_key,'structured_text_add',true)),
    (v_session_id,v_candidate_id,v_ctx.actor_user_id,'validate',
      jsonb_build_object('blocking_errors','[]'::jsonb,'warnings','[]'::jsonb));

  return public.phms_get_line_intake_review_source(
    p_line_user_id,v_source_id
  );
end
$function$

CREATE OR REPLACE FUNCTION public.phms_switch_user_context(p_scope text, p_family_id uuid DEFAULT NULL::uuid, p_family_person_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(user_id uuid, active_scope text, active_family_id uuid, active_family_person_id uuid, target_person_id uuid, target_person_name text, family_name text, context_ready boolean, context_changed_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_person_id uuid;
  v_person_name text;
  v_family_name text;
begin
  if v_uid is null then
    raise exception 'authentication_required';
  end if;

  if p_scope not in ('personal','family') then
    raise exception 'invalid_context_scope';
  end if;

  if p_scope = 'personal' then
    if p_family_id is not null or p_family_person_id is not null then
      raise exception 'personal_context_must_not_include_family';
    end if;

    perform 1 from public.phms_set_personal_context();

    select p.id, p.display_name
      into v_person_id, v_person_name
      from public.persons p
     where p.linked_user_id = v_uid
       and p.status = 'active'
     limit 1;

    return query
    select uc.user_id,
           uc.active_scope,
           uc.active_family_id,
           uc.active_family_person_id,
           v_person_id,
           v_person_name,
           null::text,
           (v_person_id is not null),
           uc.context_changed_at
      from public.user_contexts uc
     where uc.user_id = v_uid;
    return;
  end if;

  if p_family_id is null then
    raise exception 'family_id_required';
  end if;

  perform 1 from public.phms_set_family_context(p_family_id);

  select f.family_name
    into v_family_name
    from public.families f
   where f.id = p_family_id;

  if p_family_person_id is not null then
    perform 1 from public.phms_select_family_person_context(p_family_person_id);

    select p.id, p.display_name
      into v_person_id, v_person_name
      from public.family_persons fp
      join public.persons p on p.id = fp.person_id
     where fp.id = p_family_person_id
       and fp.family_id = p_family_id
       and fp.status = 'active'
       and p.status = 'active'
     limit 1;

    if v_person_id is null then
      raise exception 'family_person_not_accessible';
    end if;
  end if;

  return query
  select uc.user_id,
         uc.active_scope,
         uc.active_family_id,
         uc.active_family_person_id,
         v_person_id,
         v_person_name,
         v_family_name,
         true,
         uc.context_changed_at
    from public.user_contexts uc
   where uc.user_id = v_uid;
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_transfer_owner(p_family_id uuid, p_new_owner_user_id uuid, p_old_owner_new_role text DEFAULT 'admin'::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid;v_id uuid;v_old_role text:=lower(btrim(coalesce(p_old_owner_new_role,'member')));
begin
 v_actor:=auth.uid();
 if v_actor is null then raise exception 'Authentication required'; end if;
 if v_old_role not in ('admin','member') then raise exception 'invalid_previous_owner_role'; end if;
 v_id:=private.phms_propose_owner_transfer(p_family_id,p_new_owner_user_id,v_old_role,v_actor);
 return 'owner_transfer_requested:'||substr(v_id::text,1,12);
end;
$function$

CREATE OR REPLACE FUNCTION public.phms_update_line_active_person_profile(p_line_user_id text, p_field text, p_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_line public.line_identities%rowtype; v_ctx private.line_identity_contexts%rowtype;
 v_fp public.family_persons%rowtype; v_p public.persons%rowtype;
 v_field text:=lower(btrim(coalesce(p_field,'')));
 v_value text:=nullif(btrim(coalesce(p_value,'')),''); v_date date;
begin
 select * into v_line from public.line_identities li
 where li.line_user_id=p_line_user_id and li.is_active=true and li.user_id is not null
 order by li.updated_at desc nulls last,li.created_at desc limit 1;
 if not found then raise exception 'line_identity_not_ready'; end if;

 perform private.ensure_line_identity_context(v_line.id,v_line.user_id);
 select c.* into v_ctx from private.line_identity_contexts c where c.line_identity_id=v_line.id for update;
 if v_ctx.active_scope<>'family' or v_ctx.active_family_id is null or v_ctx.active_family_person_id is null then
   raise exception 'family_person_context_required';
 end if;

 select fp.* into v_fp from public.family_persons fp
 where fp.id=v_ctx.active_family_person_id and fp.family_id=v_ctx.active_family_id
   and coalesce(fp.status,'active')='active' for update;
 if not found then raise exception 'family_person_not_accessible'; end if;

 if not exists(select 1 from public.family_memberships fm
               where fm.family_id=v_ctx.active_family_id and fm.user_id=v_line.user_id and fm.status='active')
 then raise exception 'family_person_not_accessible'; end if;

 select p.* into v_p from public.persons p where p.id=v_fp.person_id;
 perform set_config('request.jwt.claim.sub',v_line.user_id::text,true);

 if not private.user_can_see_family_person(v_line.user_id,v_fp.id) then
   raise exception 'family_person_not_accessible';
 end if;

 if v_field in ('display_name','relationship') then
   insert into public.family_person_view_labels(
     viewer_user_id,family_id,family_person_id,display_label,relationship_label,updated_at
   )
   values(
     v_line.user_id,v_ctx.active_family_id,v_fp.id,
     case when v_field='display_name' then v_value else
       (select x.display_label from public.family_person_view_labels x
        where x.viewer_user_id=v_line.user_id and x.family_person_id=v_fp.id) end,
     case when v_field='relationship' then v_value else
       (select x.relationship_label from public.family_person_view_labels x
        where x.viewer_user_id=v_line.user_id and x.family_person_id=v_fp.id) end,
     now()
   )
   on conflict (viewer_user_id,family_person_id) do update
   set family_id=excluded.family_id,
       display_label=case when v_field='display_name' then v_value else public.family_person_view_labels.display_label end,
       relationship_label=case when v_field='relationship' then v_value else public.family_person_view_labels.relationship_label end,
       updated_at=now();

   if v_value is null then
     if v_field='display_name' then
       update public.family_person_view_labels set display_label=null,updated_at=now()
       where viewer_user_id=v_line.user_id and family_person_id=v_fp.id;
     else
       update public.family_person_view_labels set relationship_label=null,updated_at=now()
       where viewer_user_id=v_line.user_id and family_person_id=v_fp.id;
     end if;
     delete from public.family_person_view_labels
     where viewer_user_id=v_line.user_id and family_person_id=v_fp.id
       and display_label is null and relationship_label is null;
   end if;

   insert into public.audit_logs(
     family_id,actor_user_id,family_person_id,event_type,resource,record_id,new_data,description,created_at
   ) values(
     v_ctx.active_family_id,v_line.user_id,v_fp.id,'family_person_view_label_updated','persons',v_fp.person_id,
     jsonb_build_object('field',v_field,'value',v_value,'scope','viewer_private','source','line'),
     'Updated viewer-private person label/relationship from LINE',now()
   );
   return public.phms_get_line_active_person_profile(p_line_user_id);
 end if;

 if not private.can_access_family_person(v_ctx.active_family_person_id,'persons','update') then
   raise exception 'permission_denied';
 end if;

 if v_field='nickname' then
   update public.persons set nickname=v_value,updated_at=now() where id=v_fp.person_id;
 elsif v_field='first_name' then
   update public.persons set first_name=v_value,updated_at=now() where id=v_fp.person_id;
 elsif v_field='last_name' then
   update public.persons set last_name=v_value,updated_at=now() where id=v_fp.person_id;
 elsif v_field='date_of_birth' then
   if v_value is null then update public.persons set date_of_birth=null,updated_at=now() where id=v_fp.person_id;
   else
     v_date:=private.normalize_phms_date(v_value);
     update public.persons set date_of_birth=to_char(v_date,'YYYY-MM-DD'),updated_at=now() where id=v_fp.person_id;
   end if;
 elsif v_field='sex' then
   update public.persons set sex=v_value,updated_at=now() where id=v_fp.person_id;
 else raise exception 'unsupported_person_field';
 end if;

 insert into public.audit_logs(
   family_id,actor_user_id,family_person_id,event_type,resource,record_id,new_data,description,created_at
 ) values(
   v_ctx.active_family_id,v_line.user_id,v_fp.id,'family_person_profile_updated','persons',v_fp.person_id,
   jsonb_build_object('field',v_field,
     'value',case when v_field='date_of_birth' and v_value is not null then to_char(v_date,'YYYY-MM-DD') else v_value end,
     'source','line'),
   'Updated family person canonical profile from LINE',now()
 );

 return public.phms_get_line_active_person_profile(p_line_user_id);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_update_line_active_person_profile_batch(p_line_user_id text, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_key text; v_value text; v_result jsonb;
  v_allowed constant text[]:=array[
    'display_name','nickname','first_name','last_name','date_of_birth','sex','relationship'
  ];
begin
  if p_line_user_id is null or btrim(p_line_user_id)='' then raise exception 'line_user_id_required'; end if;
  if p_patch is null or jsonb_typeof(p_patch)<>'object' then raise exception 'person_profile_patch_required'; end if;
  foreach v_key in array v_allowed loop
    if p_patch ? v_key then
      v_value:=coalesce(p_patch->>v_key,'');
      v_result:=public.phms_update_line_active_person_profile(p_line_user_id,v_key,v_value);
    end if;
  end loop;
  if v_result is null then raise exception 'person_profile_patch_empty'; end if;
  return v_result;
end
$function$

CREATE OR REPLACE FUNCTION public.phms_update_line_self_profile(p_line_user_id text, p_field text, p_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_line record; v_p public.persons%rowtype;
 v_field text:=lower(btrim(coalesce(p_field,'')));
 v_value text:=nullif(btrim(coalesce(p_value,'')),''); v_date date;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 select * into v_p from public.persons p
 where p.linked_user_id=v_line.user_id and coalesce(p.status,'active')='active'
 order by p.created_at limit 1;
 if not found then raise exception 'self_person_unavailable'; end if;

 if v_field='display_name' then
   if v_value is null then
     update public.family_person_view_labels v
     set display_label=null,updated_at=now()
     where v.viewer_user_id=v_line.user_id
       and v.family_person_id in (
         select fp.id
         from public.family_persons fp
         join public.family_memberships fm
           on fm.family_id=fp.family_id and fm.user_id=v_line.user_id and fm.status='active'
         where fp.person_id=v_p.id and coalesce(fp.status,'active')='active'
       );

     delete from public.family_person_view_labels v
     where v.viewer_user_id=v_line.user_id
       and v.display_label is null and v.relationship_label is null;
   else
     insert into public.family_person_view_labels(
       viewer_user_id,family_id,family_person_id,display_label,updated_at
     )
     select v_line.user_id,fp.family_id,fp.id,v_value,now()
     from public.family_persons fp
     join public.family_memberships fm
       on fm.family_id=fp.family_id and fm.user_id=v_line.user_id and fm.status='active'
     where fp.person_id=v_p.id and coalesce(fp.status,'active')='active'
     on conflict(viewer_user_id,family_person_id) do update
     set display_label=excluded.display_label,updated_at=now();
   end if;

   return jsonb_build_object('status','ok','person_id',v_p.id,'field',v_field,'scope','viewer_private');
 end if;

 if not private.user_self_profile_update_allowed(v_line.user_id) then
   raise exception 'self_profile_update_requires_approval';
 end if;

 if v_field='nickname' then
   update public.persons set nickname=v_value,display_name=null,updated_at=now() where id=v_p.id;
 elsif v_field='first_name' then
   update public.persons set first_name=v_value,display_name=null,updated_at=now() where id=v_p.id;
 elsif v_field='last_name' then
   update public.persons set last_name=v_value,display_name=null,updated_at=now() where id=v_p.id;
 elsif v_field='date_of_birth' then
   if v_value is null then update public.persons set date_of_birth=null,updated_at=now() where id=v_p.id;
   else
     v_date:=private.normalize_phms_date(v_value);
     update public.persons set date_of_birth=to_char(v_date,'YYYY-MM-DD'),updated_at=now() where id=v_p.id;
   end if;
 elsif v_field='sex' then
   v_value:=case lower(coalesce(v_value,''))
     when 'หญิง' then 'female' when 'female' then 'female'
     when 'ชาย' then 'male' when 'male' then 'male'
     when 'อื่นๆ' then 'other' when 'อื่น' then 'other' when 'other' then 'other'
     when 'ไม่ระบุ' then null else v_value end;
   update public.persons set sex=v_value,updated_at=now() where id=v_p.id;
 else raise exception 'unsupported_person_field';
 end if;

 return jsonb_build_object('status','ok','person_id',v_p.id,'field',v_field,'scope','canonical');
end
$function$

CREATE OR REPLACE FUNCTION public.phms_update_line_self_profile_batch(p_line_user_id text, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
 v_line record; v_p public.persons%rowtype; v_date text; v_sex text; v_has_canonical boolean:=false;
begin
 select * into v_line from private.resolve_line_user_for_service(p_line_user_id);
 select * into v_p from public.persons p
 where p.linked_user_id=v_line.user_id and coalesce(p.status,'active')='active'
 order by p.created_at limit 1;
 if not found then raise exception 'self_person_unavailable'; end if;

 if p_patch ? 'display_name' then
   insert into public.family_person_view_labels(
     viewer_user_id,family_id,family_person_id,display_label,updated_at
   )
   select v_line.user_id,fp.family_id,fp.id,nullif(btrim(p_patch->>'display_name'),''),now()
   from public.family_persons fp
   join public.family_memberships fm
     on fm.family_id=fp.family_id and fm.user_id=v_line.user_id and fm.status='active'
   where fp.person_id=v_p.id and coalesce(fp.status,'active')='active'
   on conflict(viewer_user_id,family_person_id) do update
   set display_label=excluded.display_label,updated_at=now();

   delete from public.family_person_view_labels v
   where v.viewer_user_id=v_line.user_id and v.display_label is null and v.relationship_label is null;
 end if;

 v_has_canonical:=(p_patch ? 'nickname') or (p_patch ? 'first_name') or
                  (p_patch ? 'last_name') or (p_patch ? 'date_of_birth') or (p_patch ? 'sex');

 if v_has_canonical then
   if not private.user_self_profile_update_allowed(v_line.user_id) then
     raise exception 'self_profile_update_requires_approval';
   end if;
   if p_patch ? 'date_of_birth' and nullif(btrim(p_patch->>'date_of_birth'),'') is not null then
     v_date:=to_char(private.normalize_phms_date(p_patch->>'date_of_birth'),'YYYY-MM-DD');
   end if;
   if p_patch ? 'sex' then
     v_sex:=case lower(coalesce(p_patch->>'sex',''))
       when 'หญิง' then 'female' when 'female' then 'female'
       when 'ชาย' then 'male' when 'male' then 'male'
       when 'อื่นๆ' then 'other' when 'อื่น' then 'other' when 'other' then 'other'
       when 'ไม่ระบุ' then null else nullif(p_patch->>'sex','') end;
   end if;
   update public.persons p set
     nickname=case when p_patch ? 'nickname' then nullif(btrim(p_patch->>'nickname'),'') else p.nickname end,
     first_name=case when p_patch ? 'first_name' then nullif(btrim(p_patch->>'first_name'),'') else p.first_name end,
     last_name=case when p_patch ? 'last_name' then nullif(btrim(p_patch->>'last_name'),'') else p.last_name end,
     date_of_birth=case when p_patch ? 'date_of_birth' then v_date else p.date_of_birth end,
     sex=case when p_patch ? 'sex' then v_sex else p.sex end,
     display_name=null,updated_at=now()
   where p.id=v_p.id;
 end if;

 return jsonb_build_object('status','ok','person_id',v_p.id);
end
$function$

CREATE OR REPLACE FUNCTION public.phms_validate_user_context(p_resource text DEFAULT NULL::text, p_action text DEFAULT 'view'::text, p_require_person boolean DEFAULT false)
 RETURNS TABLE(user_id uuid, active_scope text, active_family_id uuid, active_family_person_id uuid, target_person_id uuid, target_person_name text, family_name text, context_valid boolean, context_ready boolean, permission_checked boolean, permission_granted boolean, validation_code text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'extensions'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_ctx public.user_contexts%rowtype;
  v_self_person public.persons%rowtype;
  v_family public.families%rowtype;
  v_family_person public.family_persons%rowtype;
  v_target_person public.persons%rowtype;
  v_membership_ok boolean := false;
  v_permission_checked boolean := false;
  v_permission_granted boolean := true;
  v_context_valid boolean := false;
  v_context_ready boolean := false;
  v_code text := 'ok';
  v_resource text := nullif(btrim(p_resource), '');
  v_action text := lower(coalesce(nullif(btrim(p_action), ''), 'view'));
begin
  if v_uid is null then
    raise exception 'authentication_required';
  end if;

  if v_action not in ('view','create','update','delete','manage_permissions','receive_notifications') then
    raise exception 'unsupported_permission_action';
  end if;

  select * into v_ctx
  from public.user_contexts uc
  where uc.user_id = v_uid;

  if not found then
    perform public.phms_set_personal_context();
    select * into v_ctx
    from public.user_contexts uc
    where uc.user_id = v_uid;
  end if;

  if v_ctx.active_scope = 'personal' then
    select * into v_self_person
    from public.persons p
    where p.linked_user_id = v_uid
    order by p.created_at
    limit 1;

    v_context_valid := true;
    v_context_ready := (v_self_person.id is not null and coalesce(v_self_person.status,'active') = 'active');
    v_permission_checked := false;
    v_permission_granted := true;

    if p_require_person and not v_context_ready then
      v_context_valid := false;
      v_code := 'personal_person_required';
    elsif v_self_person.id is null then
      v_code := 'personal_person_missing';
    elsif coalesce(v_self_person.status,'active') <> 'active' then
      v_context_valid := false;
      v_code := 'personal_person_inactive';
    else
      v_code := 'ok';
    end if;

    return query
    select v_uid,
           v_ctx.active_scope,
           null::uuid,
           null::uuid,
           v_self_person.id,
           coalesce(nullif(btrim(v_self_person.display_name),''), nullif(btrim(concat_ws(' ',v_self_person.first_name,v_self_person.last_name)),''), null),
           null::text,
           v_context_valid,
           v_context_ready,
           v_permission_checked,
           v_permission_granted,
           v_code;
    return;
  end if;

  if v_ctx.active_scope <> 'family' then
    return query select v_uid, v_ctx.active_scope, v_ctx.active_family_id, v_ctx.active_family_person_id,
      null::uuid, null::text, null::text, false, false, false, false, 'invalid_scope'::text;
    return;
  end if;

  if v_ctx.active_family_id is null then
    return query select v_uid, 'family'::text, null::uuid, v_ctx.active_family_person_id,
      null::uuid, null::text, null::text, false, false, false, false, 'family_required'::text;
    return;
  end if;

  select * into v_family
  from public.families f
  where f.id = v_ctx.active_family_id;

  if v_family.id is null then
    return query select v_uid, 'family'::text, v_ctx.active_family_id, v_ctx.active_family_person_id,
      null::uuid, null::text, null::text, false, false, false, false, 'family_not_found'::text;
    return;
  end if;

  if coalesce(v_family.status,'active') <> 'active' then
    return query select v_uid, 'family'::text, v_ctx.active_family_id, v_ctx.active_family_person_id,
      null::uuid, null::text, v_family.family_name, false, false, false, false, 'family_inactive'::text;
    return;
  end if;

  v_membership_ok := private.is_active_family_member(v_ctx.active_family_id);
  if not v_membership_ok then
    return query select v_uid, 'family'::text, v_ctx.active_family_id, v_ctx.active_family_person_id,
      null::uuid, null::text, v_family.family_name, false, false, false, false, 'family_membership_inactive'::text;
    return;
  end if;

  if v_ctx.active_family_person_id is not null then
    select fp.* into v_family_person
    from public.family_persons fp
    where fp.id = v_ctx.active_family_person_id
      and fp.family_id = v_ctx.active_family_id;

    if v_family_person.id is null then
      return query select v_uid, 'family'::text, v_ctx.active_family_id, v_ctx.active_family_person_id,
        null::uuid, null::text, v_family.family_name, false, false, false, false, 'family_person_not_found'::text;
      return;
    end if;

    if coalesce(v_family_person.status,'active') <> 'active' then
      return query select v_uid, 'family'::text, v_ctx.active_family_id, v_ctx.active_family_person_id,
        v_family_person.person_id, null::text, v_family.family_name, false, false, false, false, 'family_person_inactive'::text;
      return;
    end if;

    select * into v_target_person
    from public.persons p
    where p.id = v_family_person.person_id;

    if v_target_person.id is null then
      return query select v_uid, 'family'::text, v_ctx.active_family_id, v_ctx.active_family_person_id,
        v_family_person.person_id, null::text, v_family.family_name, false, false, false, false, 'person_not_found'::text;
      return;
    end if;

    if coalesce(v_target_person.status,'active') <> 'active' then
      return query select v_uid, 'family'::text, v_ctx.active_family_id, v_ctx.active_family_person_id,
        v_target_person.id,
        coalesce(nullif(btrim(v_target_person.display_name),''), nullif(btrim(concat_ws(' ',v_target_person.first_name,v_target_person.last_name)),''), null),
        v_family.family_name, false, false, false, false, 'person_inactive'::text;
      return;
    end if;
  elsif p_require_person then
    return query select v_uid, 'family'::text, v_ctx.active_family_id, null::uuid,
      null::uuid, null::text, v_family.family_name, true, false, false, false, 'family_person_required'::text;
    return;
  end if;

  v_context_valid := true;
  v_context_ready := (not p_require_person) or (v_target_person.id is not null);

  if v_resource is not null then
    v_permission_checked := true;
    if v_ctx.active_family_person_id is not null then
      if v_action = 'receive_notifications' then
        v_permission_granted := exists (
          select 1
          from public.person_permissions pp
          where pp.family_id = v_ctx.active_family_id
            and pp.family_person_id = v_ctx.active_family_person_id
            and pp.user_id = v_uid
            and pp.resource = v_resource
            and pp.status = 'active'
            and pp.can_receive_notifications = true
        ) or private.is_family_owner(v_ctx.active_family_id);
      else
        v_permission_granted := private.can_access_family_person(v_ctx.active_family_person_id, v_resource, v_action);
      end if;
    else
      if v_action = 'receive_notifications' then
        v_permission_granted := false;
      else
        v_permission_granted := private.has_family_permission(v_ctx.active_family_id, v_resource, v_action);
      end if;
    end if;

    if not v_permission_granted then
      v_code := 'permission_denied';
    end if;
  end if;

  return query
  select v_uid,
         'family'::text,
         v_ctx.active_family_id,
         v_ctx.active_family_person_id,
         v_target_person.id,
         coalesce(nullif(btrim(v_target_person.display_name),''), nullif(btrim(concat_ws(' ',v_target_person.first_name,v_target_person.last_name)),''), null),
         v_family.family_name,
         v_context_valid,
         v_context_ready,
         v_permission_checked,
         v_permission_granted,
         v_code;
end;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$
